export default [{"id":2342,"title":"غارة الكرج (الجورجيون، سكان جورجيا) على بلاد الإسلام من ناحية أذربيجان .","date":["العام الهجري :601","العام الميلادي :1204"],"text":"أغارت الكرج على بلاد الإسلامِ من ناحية أذربيجان، فأكثَروا العَيثَ والفَسادَ والنَّهبَ والسَّبيَ، ثمَّ أغاروا على ناحيةِ خلاط من أرمينية، فأوغلوا في البلاد حتى بَلَغوا ملازكرد، ولم يخرُجْ إليهم أحَدٌ من المسلمين يمنَعُهم، فجاسوا خلالَ البلادِ يَنهَبون ويأسِرونَ ويَسْبُون، وكلَّما تقَدَّموا تأخَّرَت عساكِرُ المسلمين عنهم، ثم رجَعوا عنهم، وأغارت الكرجُ على بلاد خلاط، فأتوا إلى أرجيش ونواحيها، فنَهَبوا، وسَبَوا، وخَرَّبوا البلاد، وساروا إلى حِصنِ التين، من أعمالِ خلاط، وهو مجاوِرُ أرزن الروم، فجمع صاحِبُ خلاط عسكَرَه وسار إلى ولد قلج أرسلان، صاحِبِ أرزن الروم، فاستنجَدَه على الكرج، فسيَّرَ عسكَرَه جميعَه معه، فتوجَّهوا نحو الكرج، فلَقُوهم، وتصافُّوا، واقتَتَلوا، فانهزمت الكرج، وقُتِلَ زكري الصغير، وهو من أكابِرِ مُقَدَّميهم، وهو الذي كان مُقَدَّمَ هذا العسكر من الكرج والمقاتِل بهم، وغَنِمَ المسلمون ما معهم من الأموال والسلاح والكراع وغير ذلك، وقتلوا منهم خلقًا كثيرًا، وأسَروا كذلك."},{"id":2343,"title":"الحرب بين أمير مكة وأمير المدينة .","date":["العام الهجري :601","العام الميلادي :1204"],"text":"وقَعَت الحربُ بين الأميرِ قتادةَ الحسني، أميرِ مكة، وبين الأمير سالم بن قاسم الحُسيني، أميرِ المدينة، ومع كل واحدٍ منهما جمعٌ كثير، فاقتتلوا قتالًا شديدًا، وكانت الحربُ بذي الحُلَيفة بالقُرب من المدينة، وكان قتادة قد قصد المدينةَ لِيَحصُرَها ويأخُذَها، فلَقِيَه سالم، فسار فلَقِيَه، فانهزم قتادةُ، وتَبِعَه سالم إلى مكة فحَصَرَه بها، فأرسل قتادةُ إلى من مع سالم من الأمراء، فأفسَدَهم عليه، فمالوا إليه وحالَفوه، فلما رأى سالمٌ ذلك رحل عنه عائدًا إلى المدينةِ، وعاد أمر قتادةَ قويًّا."},{"id":2344,"title":"كيخسرو بن قلج أرسلان يمتلك بلاد الروم من ابن أخيه .","date":["العام الهجري :601","الشهر القمري : رجب","العام الميلادي :1205"],"text":"مَلَك غياثُ الدين كيخسرو بن قلج أرسلان بلادَ الرومِ التي كانت بيد أخيه رُكن الدين سليمان وانتَقَلَت بعد موته إلى ابنه قلج أرسلان بن ركن الدين، وكان سبَبُ مِلك غياث الدين لها أنَّ ركنَ الدين كان قد أخذ ما كان لأخيه غياث الدين، وهي مدينةُ قونية، فهَرَب غياث الدين منه، وقَصَد الشامَ إلى المَلِك الظاهر غازي بن صلاح الدين، صاحب حلب، فلم يجد عنده قبولًا، وقصر به، فسار مِن عنده، وتقَلَّب في البلاد إلى أن وصل إلى القُسطنطينيَّة، فأحسن إليه مَلِكُ الروم وأقطَعَه وأكرَمَه، فأقام عنده، وتزوجَ بابنةِ بعض البطارقة الكبارِ، فأقام عنده، فلما مات أخوه ركن الدين سليمان سنة ستمائة، اجتمع الأمراءُ على ولده قلج، وخالَفَهم الأتراك الأوج، وهم كثيرٌ بتلك البلاد، وأنِفَ مِن اتباعهم، أرسل قلج إلى عَمِّه غياث الدين كيخسرو يستدعيه إليه ليُمَلِّكَه البلاد، فسار إليه، فوصَلَ في جمادى الأولى، واجتمع به، وكَثُرَ جَمعُه، وقصد مدينة قونيَّة ليَحصُرَها، وكان قلج والعساكرُ بها، فأخرجوا إليه طائفةً من العسكر، فلَقُوه فهزموه، فبَقِيَ حيران لا يدري أين يتوجَّهُ، فقصد بلدةً صغيرة يقالُ لها أوكرم بالقُربِ من قونية، فقَدَّرَ الله تعالى أن أهل مدينة أقصر وثبوا على الوالي فأخرجوه منها ونادَوا بشعار غياثِ الدين، فلَمَّا سَمِعَ أهل قونية بما فعله أهل أقصر قالوا: نحن أولى مَن فعل هذا؛ لأنَّه كان حَسَنَ السيرة فيهم لَمَّا كان مالكهم، فنادوا باسمِه أيضًا، وأخرجوا مَن عِندَهم، واستدعوه، فحضَرَ عندهم، ومَلَك المدينةَ وقبض على ابن أخيه ومَن معه."},{"id":2345,"title":"وقوع فتن بين أهل بغداد .","date":["العام الهجري :601","الشهر القمري : رمضان","العام الميلادي :1205"],"text":"في تاسع رمضان وقعت فتنةٌ بين أهل سوق السلطان والجعفرية، منشؤها أنَّ رَجُلَينِ مِن المحلَّتَينِ اختصما وتوعَّدَ كُلُّ واحدٍ منهما صاحِبَه، فاجتمع أهلُ المحلَّتَينِ، واقتتلوا في مقبرةِ الجعفرية، فسَيَّرَ إليهم مِن الديوان من تلافى الأمرَ وسَكَّنَه، وفي سابع عشر رمضان جرت فتنةٌ ببغداد بين أهل باب الأزج وأهل المأمونيَّة، وسبَبُها أنَّ أهل باب الأزج قتلوا سَبُعًا وأرادوا أن يطوفوا به، فمنَعَهم أهل المأمونية، فوَقَعت الفتنةُ بينهما فجُرِحَ منهم خلق كثير، وقُتِلَ جماعة، وركِبَ صاحب الباب لتسكينِ الفتنة فجُرِحَ فَرَسُه، فعاد، فلما كان الغدُ سار أهل المأمونية إلى أهل باب الأزج، فوقَعَت بينهم فتنةٌ شديدةٌ وقِتالٌ بالسيوف والنشاب، واشتدَّ الأمر، فنُهَبَت الدور القريبة منهم، وسعَى الركن بن عبد القادر ويوسف العقاب في تسكينِ الناس، ورَكِبَ الأتراك، فصاروا يَبِيتون تحت المنظرة، فامتنَعَ أهل الفتنة من الاجتماع، فسَكَنوا، وفي العشرين منه جرَت فتنة بين أهل قطفتا والقرية، من محالِّ الجانب الغربي، بسبب قَتْلِ سَبُع أيضًا، أراد أهل قطفتا أن يجتَمِعوا ويطوفوا به، فمنَعَهم أهل القرية أن يَجوزوا به عندهم، فاقتتَلوا، وقَتَلَ بينهم عدة قتلى، فأرسل إليهم عسكَرٌ من الديوان لتلافي الأمر ومَنْع الناس عن الفتنة، فامتنعوا، فلمَّا كَثُرَت الفتن رُتِّبَ أميرٌ كبير من مماليك الخليفة، ومعه جماعة كثيرة، فطاف في البلد، وقَتَل جماعةً ممن فيه شبهة، فسكن الناس."},{"id":2346,"title":"استيلاء الأمير عماد الدين الغوري صاحب بلخ على مدينة ترمذ .","date":["العام الهجري :601","الشهر القمري : ذي القعدة","العام الميلادي :1205"],"text":"سار الأميرُ عِمادُ الدين عُمَر بن الحسين الغوري، صاحبُ بلخ، إلى مدينةِ ترمذ، وهي للأتراكِ الخطا الكُفَّار، فافتتحها عَنوةً، وجعل بها ولَدَه الأكبر، وقَتَل مَن بها من الخطا، ونقل العَلَويينَ منها إلى بلخ، وصارت ترمذ دارَ إسلام، وهي من أمنَعِ الحُصونِ وأقواها."},{"id":2347,"title":"استيلاء خوارزم شاه على بلاد الغورية .","date":["العام الهجري :602","العام الميلادي :1205"],"text":"بعد مُكاتَبةِ الحُسَينِ بنِ خرميل، والي هراة، خوارزمَ شاه، ومراسَلَتِه في الانتماءِ إليه والطاعة له، تَرَكَ طاعةَ الغورية، وخِداعه لغياث الدين، ومغالطته له بالخُطبة له والطاعة؛ انتظارًا لوصولِ عسكر خوارزم شاه، ووصل عسكَرُ خوارزم شاه، فلَقِيَهم ابن خرميل، وأنزلهم على بابِ البلد، فقالوا له: قد أَمَرنا خوارزم شاه ألَّا نُخالِفَ لك أمرًا، فشَكَرَهم على ذلك، وكان يخرج إليهم كلَّ يَومٍ، وأقام لهم الوظائِفَ الكثيرةَ."},{"id":2348,"title":"خوارزم شاه يمتلك مدينة ترمذ وتسليمها إلى الخطا الكفار .","date":["العام الهجري :602","العام الميلادي :1205"],"text":"لما أخذ خوارزم شاه مدينة بلخ سار عنها إلى مدينة ترمذ مجِدًّا، وبها ولدُ عماد الدين صاحب بلخ، فأرسل إليه محمَّد بن علي بن بشير يقولُ له: إن أباك قد صار من أخصِّ أصحابي وأكابِرِ أمراء دولتي، وقد سَلَّمَ إليَّ بلخ، وإنما ظهَرَ لي منه ما أنكَرْتُه، فسَيَّرْتُه إلى خوارزم مُكرَمًا محترمًا، وأمَّا أنت فتكون عندي أخًا ووعَدَه، وأقطعه الكثيرَ، فخدعه محمد بن علي، فرأى صاحِبُها أنَّ خوارزم شاه قد حصره مِن جانبٍ والخطا قد حصره من جانبٍ آخر، وأصحابُه قد أسرهم الدز بغُزنة، فضَعُفَت نفسه، وأرسل من يستحلِفُ له خوارزم شاه، فحلَفَ له، وتسَلَّم منه ترمذ وسَلَّمَها إلى الخطا الكفار، فلقد اكتسَبَ بها خوارزم شاه سُبَّةً عظيمة، وذِكرًا قبيحًا في عاجِلِ الأمر، ثم ظهر للناس بعد ذلك أنَّه إنما سلمها إليهم ليتمكَّنَ بذلك مِن مُلكِ خراسان، ثم يعود إليهم فيأخُذُها وغيرَها منهم؛ لأنَّه لَمَّا مَلَكَ خراسان وقصد بلاد الخطا وأخَذَها وأفناهم؛ عَلِمَ النَّاسُ أنَّه فعل ذلك خديعةً ومكرًا."},{"id":2349,"title":"الغارة من ابن ليون على أعمال حلب .","date":["العام الهجري :602","العام الميلادي :1205"],"text":"توالت الغارةُ من ابن ليون الأرمني، صاحِبِ الدروب، على ولايةِ حَلَب، فنَهَب وحرق، وأسر وسبى، فجمع المَلِكُ الظاهر غازي بن صلاح اِلدين الأيوبي، صاحِبُ حلب، عساكِرَه واستنجد غيرَه من الملوك، فجمع كثيرًا من الفارِسِ والراجِل، وسار عن حَلَب نحو ابن ليون، وكان ابنُ ليون قد نزل في طرف بلادِه مما يلي بلد حلب، فليس إليه طريقٌ؛ لأن جميع بلاده لا طريقَ إليها إلَّا مِن جبال وعرة، ومضايق صعبة، فلا يقدِرُ غيره على الدخول إليها، لا سيما من ناحية حَلَب؛ فإن الطريق منها متعَذِّرٌ جدًّا، فنزل الظاهر على خمسة فراسخ من حَلَب، وجعل على مقَدِّمَته جماعةً مِن عسكره مع أميرٍ كبير من مماليك أبيه اسمُه ميمون، فأنفذ الظاهِرُ ميرةً وسلاحًا إلى حِصنٍ له مجاور لبلاد ابنِ ليون، اسمُه دربساك، وأنفذ إلى ميمون ليرسِلَ طائفة من العسكر الذين عنده إلى طريق هذه الذخيرة ليسيروا معها إلى دربساك، ففعل ذلك، وسيَّرَ جماعة كثيرة من عسكَرِه، وبَقِيَ في قلة، فبلغ الخبَرُ إلى ابن ليون، فجَدَّ فوافاه وهو مخِفٌّ من العسكرِ، فقاتله واشتد القتال بينهم، فأرسل ميمون إلى الظاهِرِ يُعَرِّفُه، وكان بعيدًا عنه، فطالت الحربُ بينهم، وحمى ميمون نفسَه وأثقالَه على قِلَّةٍ مِن المسلمين وكثرةٍ مِن الأرمن، فانهزم المسلمون، ونال العدوُّ منهم، فقتل وأسَر، وكذلك أيضًا فَعَل المسلمون بالأرمن مِن كثرةِ القَتلِ، وظَفِرَ الأرمنُ بأثقال المسلمين فغَنِموها وساروا بها، فصادَفَهم المسلمون الذين كانوا قد ساروا مع الذَّخائِرِ إلى دربساك، فلم يَشعُروا بالحال، فلم يَرُعْهم إلَّا العدو وقد خالطهم ووضع السيفَ فيهم، فاقتتلوا أشَدَّ قتال، ثم انهزم المسلمون أيضًا، وعاد الأرمن إلى بلادهم بما غَنِموا، واعتصموا بجبالهم وحصونهم."},{"id":2350,"title":"ثورة ابن غانية على دولة الموحدين بشمال أفريقيا .","date":["العام الهجري :602","الشهر القمري : ربيع الآخر","العام الميلادي :1205"],"text":"بعد أن استطاع الموحِّدون إخراجَ عليِّ بنِ أحمد من بني خراسان من إفريقيا وطرَدوا النورماند من المهديَّة ووصلوا إلى بُرقةَ، واستَخلَفَ عليها عبدُ المؤمن أبا محمد عبد السلام الكورميَّ، وجعل العاصمة تونس، ثم جاء الأميرُ يعقوب المنصور الذي خرج عليه يحيى بن إسحاق المنورقي المعروف بابن غانية، فقام بالثورة عليه حتى كاد يُنهي دولةَ الموحِّدينَ إلَّا قليلا خلال الفترة من 580 إلى 604 حتى اضطُرَّ السلطان الموحدي للحضورِ ومعه أبو محمد عبد الواحد الحفصي سنة 602؛ لإخماد ثورة ابن غانية حيث استطاع إخمادَها وهرب ابن غانية إلى أسبانيا، وكان هذا أيضًا بدءًا لظهور قوة الدولة الحَفصيَّة."},{"id":2351,"title":"وفاة الأمير طاشتكين مجير الدين أمير الحاج بتستر .","date":["العام الهجري :602","الشهر القمري : جمادى الآخرة","العام الميلادي :1206"],"text":"هو الأميرُ مجيرُ الدين طاشتكين بن عبد الله المقتفوي المستنجدي, أميرُ الحاج وزعيم بلاد خوزستان، كان شيخًا غاليًا في التشَيُّع، وكانت الحلة الشيعيَّة إقطاعَه، وكان شجاعًا قليلَ الكلام، يمضي عليه الأسبوعُ لا يتكلم فيه بكلمةٍ، وذُكِرَ أنَّه حج بالناس ستًّا وعشرين سنة، كان يكونُ في الحجاز كأنَّه مَلِكٌ، وقد رماه الوزيرُ ابن يونس بأنه يكاتب صلاحَ الدين فحبَسَه الخليفة، ثم تبيَّنَ له بطلان ما ذكر عنه فأطلقه وأعطاه خوزستان، ثم أعاده إلى إمرة الحَجِّ،‏ توفي بتستر ثاني جمادى الآخرة وحُملَ تابوتُه إلى الكوفة فدُفِنَ بمشهد عليٍّ لوصيَّتِه بذلك."},{"id":2352,"title":"عدوان الكرج (الجورجيون، سكان جورجيا) على ولاية خلاط من أرمينية .","date":["العام الهجري :602","الشهر القمري : جمادى الآخرة","العام الميلادي :1206"],"text":"قَصَدت الكرجُ في جموعها ولايةَ خلاط من أرمينيَّة، ونهبوا وقتلوا، وأسَروا وسَبَوا أهلَها كثيرًا، وجاسُوا خلالَ الديار آمنين، ولم يخرُجْ إليهم من خلاط من يمنَعُهم فبَقُوا متصرفين في النهب والسبي، والبلادُ شاغرة لا مانع لها، لأنَّ صاحِبَها صبيٌّ، والمدبِّر لدولتِه ليست له تلك الطاعة على الجُندِ، فلما اشتَدَّ البلاء على الناس تذامَروا، وحَرَّض بعضُهم بعضًا، واجتمعت العساكِرُ الإسلاميَّة التي بتلك الولاية جميعها، وانضاف إليهم من المتطوِّعة كثيرٌ، فساروا جميعُهم نحو الكرج وهم خائفونَ، فوصلت الأخبارُ إلى الكرج، فعزموا على كبسِ المسلمين، فانتقلوا من موضِعِهم بالوادي إلى أعلاه، فنزلوا فيه ليكبِسوا المسلمين إذا أظلَمَ اللَّيلُ، فأتى المسلمين الخبَرُ، فقصدوا الكرج وأمسكوا عليهم رأسَ الوادي وأسفَلَه، وهو وادٍ ليس إليه غيرُ هذين الطريقين، فلما رأى الكرجُ ذلك أيقنوا بالهلاك، وسُقِطَ في أيديهم، وطَمِعَ المسلمون فيهم، وضايقوهم، وقاتلوهم، فقَتَلوا منهم كثيرًا، وأسَروا مِثلَهم، ولم يُفلِتْ مِن الكرجِ إلَّا القليلُ، وكفى الله المسلمينَ شَرَّهم بعد أن كانوا أشرفوا على الهَلاكِ."},{"id":2353,"title":"مقتل السلطان شهاب الدين الغوري ملك غزنة .","date":["العام الهجري :602","الشهر القمري : شعبان","العام الميلادي :1206"],"text":"هو السُّلطانُ شِهابُ الدين أبو المظفَّر محمَّد بن سام الغوري، مَلِكُ غزنة وبعض خراسان. كان ملكًا شجاعًا غازيًا، عادلًا حَسَنَ السيرة، يحكُمُ بما يوجِبُه الشرع، يُنصِفُ الضعيفَ والمظلوم، وكان يَحضُرُ عنده العُلَماءُ. لما مات أخوه السلطان غياث الدين، قَبَضَ شهاب الدين على جماعةٍ مِن خواصِّ أخيه وأتباعه وصادرهم. قُتِلَ شهاب الدين بعد عودته من لهاوور، بمنزلٍ يقال له دميل، وقتَ صلاة العشاء، وكان سبَبُ قتله أن نفرًا من الكُفَّار الكوكرية لَزِموا عسكره عازمينَ على قتله، كما فعَلَ بهم من القَتلِ والأسر والسَّبيِ، فلما كان هذه الليلة تفَرَّق عنه أصحابُه، وكان معه من الأموالِ ما لا يُحصى، فإنَّه كان عازمًا على قصد الخطا والاستكثار مِن العساكِرِ، وتفريق المال فيهم، وكان على نيَّةٍ جيدة من قتال الكُفَّار، وبقي وحده في خركاه، فثار أولئك النفر، فقَتَل أحَدُهم بعضَ الحُرَّاس بباب سرادق شهاب الدين، فلما قَتَلوه صاح، فثار أصحابُه من حول السرادق لينظُروا ما بصاحِبِهم، فأخلَوا مواقِفَهم، وكَثُرَ الزحام، فاغتَنَم الكوكرية غفلَتَهم عن الحفظ، فدخلوا على شهابِ الدين وهو في الخركاه، فضَرَبوه بالسكاكين اثنتين وعشرين ضربةً فقتلوه، فدخل عليه أصحابُه، فوجدوه على مصلَّاه قتيلًا وهو ساجِدٌ، فأخذوا أولئك الكُفَّار فقتلوهم، وقيل: إنما قتَلَه الإسماعيليَّةُ؛ لأنهم خافوا خروجه إلى خراسان، فلمَّا قُتِلَ اجتمع الأمراء عند وزيره مؤيد الملك بن خوجا سجستان، فتحالَفوا على حِفظِ الخزانة والملك، ولزوم السَّكينة إلى أن يظهَرَ من يتولاه، وتقَدَّمَ الوزير إلى أمير داذ العسكر بإقامةِ السياسة، وضَبط العسكر.  وصيَّروا السلطان في محفَّة، وحَفُّوها بالجسم والصناجق يوهمون أنه حيٌّ, وكانت الخزانةُ على ألفين ومائتي جَمَل، وساروا إلى أن وصلوا إلى كرمان، وكاد يتخَطَّفُهم أهلُ تلك النواحي، فخرج إليهم الأميرُ تاج الدين ألدز، فجاء ونزل وقَبَّل الأرض، وكَشَف المحَّفة، فلما رأى السلطان ميتًا، شَقَّ ثيابه وبكى، وبكى الأمراءُ وكان يومًا مشهودًا. وكان ألدز من أكبَرِ مماليكه وأجَلِّهم، فلمَّا قُتِلَ شهاب الدين طَمِعَ أن يَملِكَ غزنة، وحُمِل السلطان إلى غزنة، فدُفِن في التربة التي أنشأها."},{"id":2354,"title":"ملك خوارزم شاه الطالقان .","date":["العام الهجري :603","العام الميلادي :1206"],"text":"لَمَّا سَلَّم خوارزم شاه ترمذَ إلى الخطا سار عنها إلى ميهنة وأندخوي، وكتب إلى سونج أمير أشكار، نائب غياث الدين محمود بالطالقان يستميلُه، فعاد الرسول خائبًا لم يجِبْه سونج إلى ما أراد منه، وجمع عسكَرَه وخرج يحارِبُ خوارزم شاه، فالتَقَوا بالقرب من الطالقان، فلما تقابل العسكرانِ حمل سونج وحده مجِدًّا حتى قارب عسكرَ خوارزم شاه، فألقى سونج نفسَه إلى الأرض، ورمى سلاحه عنه، وقَبَّلَ الأرضَ، وسأل العَفْوَ، فظَنَّ خوارزم شاه أنَّه سَكرانُ، فلمَّا عَلِمَ أنه صاح ذَمَّه وسَبَّه، وقال: من يثِقُ بهذا وأشباهِه، ولم يلتفت إليه، وأخذ خوارزم شاه ما بالطالقانِ مِن مالٍ وسلاح ودوابَّ وأنفَذَه إلى غياث الدين مع رسولٍ، وحمَّله رسالةً تتضَمَّنُ التقَرُّبَ إليه والملاطفة له، واستناب بالطالقان بعضَ أصحابه، وسار إلى قلاع كالوين وبيوار، فخرجَ إليه حسام الدين عليُّ بن أبي علي، صاحب كالوين، وقاتله على رؤوس الجبال، فأرسل إليه خوارزمُ شاه يتهَدَّدُه إن لم يسَلِّمْ إليه، فقال: أمَّا أنا فمملوك، وأمَّا هذه الحصونُ فهي أمانةٌ بيدي، ولا أسَلِّمُها إلَّا إلى صاحبها، فاستحسن خوارزم شاه منه هذا، وأثنى عليه، وذمَّ سونج, ولَمَّا بلغ غياث الدين خَبَرُ سونج، وتسليمُه الطالقان إلى خوارزم شاه، عَظُمَ عِندَه وشَقَّ عليه، فسَلَّاه أصحابه، وهوَّنوا الأمر، ولَمَّا فرغ خوارزم شاه من الطالقان سار إلى هراة، فنزل بظاهِرِها."},{"id":2355,"title":"وفاة حسام الدين أردشير صاحب مازندران والخلاف بين أولاده .","date":["العام الهجري :603","العام الميلادي :1206"],"text":"توفِّيَ حُسامُ الدين أردشير، صاحِبُ مازندران، وخَلَّفَ ثلاثة أولاد، فمَلَك بعده ابنُه الأكبَرُ، وأخرج أخاه أسامةَ وهو الأوسَطُ مِن البلاد، فقَصَد جرجان، وبها المَلِك علي شاه بن خوارزم شاه تكش، أخو خوارزم شاه محمد، وهو ينوبُ عن أخيه فيها، فشكا إليه ما صنَعَ به أخوه من إخراجِه مِن البلاد، وطَلَب منه أن يُنجِدَه عليه، ويأخُذَ له البلاد؛ ليكون في طاعته، فكتَبَ علي شاه إلى أخيه خوارزم شاه في ذلك، فأمر بالمسيرِ معه إلى مازندران، وأخْذ البلاد له، وإقامة الخُطبة لخوارزم شاه فيها، فساروا عن جرجان، فاتَّفق أن ابن حسام الدين، الأخَ الأكبر صاحب مازندران، مات في ذلك الوقت، وملك البلادَ بعده أخوه الأصغَرُ، واستولى على القلاعِ والأموال، فدخل علي شاه البلادَ، ومعه أسامةُ الأخ الأوسط، فنَهَبوها وخَرَّبوها، وامتنع منهم الأخُ الصغير بالقلاع، وأقام بقلعةِ كور، وهي التي فيها الأموالُ والذخائر، وحصروه فيها بعد أن ملَّكوا أسامة البلادَ، مثل: سارية وآمل وغيرهما من البلاد والحصون، وخُطِبَ لخوارزم شاه فيها جميعها، سوى القلعة التي فيها أخوه الأصغَرُ، وهو يراسله، ويستميله، ويستعطِفُه، وأخوه لا يردُّ جوابًا، ولا يَنزِلُ عن حِصنِه."},{"id":2356,"title":"امتلاك الكرج (الجورجيون، سكان جورجيا) لمدينة قرس وموت ملك الكرج .","date":["العام الهجري :603","العام الميلادي :1206"],"text":"ملك الكرج حصن قرس من أعمال خلاط، وكانوا قد حصروه مدةً طويلة، وضيَّقوا على من فيه، وأخذوا دخلَ الولاية عدة سنين، وكل من يتولى خلاط لا ينجِدُهم، ولا يسعى في راحة تصل إليهم، وكان الوالي بها يواصل رسله في طلب النجدة، وإزاحة من عليه من الكرج، فلا يجاب له دعاء، فلما طال الأمرُ عليه ورأى أنْ لا ناصر له، صالح الكرجَ على تسليم القلعة على مالٍ كثير وإقطاع يأخذُه منهم، وصارت دار شرك بعد أن كانت دار توحيد! ثمَّ إن الله تعالى نظر إلى قلة ناصر الإسلام، فتولاه هو، فأمات ملكة الكرج، واختلفوا فيما بينهم، وكفى الله شرهم إلى آخر السنة."},{"id":2357,"title":"غياث الدين كيخسرو يمتلك مدينة أنطاكية .","date":["العام الهجري :603","الشهر القمري : شعبان","العام الميلادي :1207"],"text":"في الثالث من شعبان ملك غياث الدين كيخسرو، صاحِبُ قونية وبلد الروم، مدينةَ أنطاكية بالأمان، وهي للرومِ على ساحِلِ البحر، وسَبَبُ ذلك أنَّه كان حَصَرَها قبل هذا التاريخ، وأطال المقامَ عليها، وهَدَّمَ عِدَّةَ أبراج من سورها، ولم يبقَ إلَّا فَتْحُها عَنوةً، فأرسل مَن بها من الروم إلى الفرنجِ الذين بجزيرة قبرص، وهي قريبةٌ منها، فاستنجدوهم، فوصل إليها جماعةٌ منهم، فعند ذلك يَئِسَ غياث الدين منها، ورَحَلَ عنها، وتَرَك طائفةً مِن عسكره بالقُربِ منها، بالجبالِ التي بينها وبين بلاده، وأمَرَهم بقَطعِ الميرة منها، فاستمَرَّ الحالُ على ذلك مُدَّةً حتى ضاق بأهلِ البلد، واشتَدَّ الأمر عليهم، فطَلَبوا من الفرنج الخروج لدفعِ المسلمين عن مضايقَتِهم، فظَنَّ الفرنجُ أنَّ الروم يريدون إخراجهم من المدينةِ بهذا السبب، فوقع الخلافُ بينهم، فاقتتلوا، فأرسل الرومُ إلى المسلمين، وطَلَبوهم ليسَلِّموا إليهم البلدَ، فوصلوا إليهم، واجتمعوا على قتالِ الفِرنجِ، فانهزم الفرنجُ ودخل المسلمون الحِصنَ فاعتَصَموا به، ثم أرسلوا يطلُبونَ غياثَ الدين، وهو بمدينةِ قونيَّة، فسار إليهم مجِدًّا في طائفةٍ مِن عسكره، فوصلها ثاني شعبان، وتقَرَّرَ الحالُ بينه وبين الروم، وتسَلَّمَ المدينة ثالثة، وحَصَر الحِصنَ الذي فيه الفرنج، وتسَلَّمَه وقَتَلَ كُلَّ من كان به مِن الفرنجِ."},{"id":2358,"title":"الحرب بين عسكر الخليفة الناصر لدين الله وصاحب لرستان .","date":["العام الهجري :603","الشهر القمري : رمضان","العام الميلادي :1207"],"text":"سار عسكر الخليفة الناصر لدين الله من خوزستان مع مملوكه سنجر، إلى جبال لرستان، وصاحبها يعرف بأبي طاهر، وهي جبال منيعة بين فارس وأصبهان وخوزستان، فقاتلوا أهلها وعادوا منهزمين، وسبب ذلك أن مملوكًا للخليفة اسمه قشتمر من أكابر مماليكه كان قد فارق الخدمة لتقصير رآه من الوزير نصير الدين العلوي الرازي، واجتاز بخوزستان، وأخذ منها ما أمكنه ولحق بأبي طاهر صاحب لرستان، فأكرمه وعظَّمه وزوجه ابنته، ثم توفِّي أبو طاهر فقوي أمر قشتمر، وأطاعه أهل تلك الولاية، فأمر سنجر بجمع العساكر وقصْده وقتاله، ففعل سنجر ما أمر به، وجمع العساكرَ وسار إليه، فأرسل قشتمر يعتذر، ويسأل ألا يقصد ولا يخرج عن العبودية، فلم يقبل عذره، فجمع أهل تلك الأعمال، ونزل إلى العسكر، فلَقيَهم، فهزمهم، وأرسل إلى صاحب فارس بن دكلا وشمس الدين إيدغمش، صاحب أصبهان وهمذان والري، يعرِّفُهما الحال، ويقول: إنني لا قوة لي بعسكر الخليفة، وربما أضيف إليهم عساكر أخرى من بغداد وعادوا إلى حربي، وحينئذٍ لا أقدر بهم، وطلب منهما النجدة، وخوَّفهما من عسكر الخليفة إن ملكوا تلك الجبال، فأجاباه إلى ما طلب، فقوي جنانه، واستمرَّ على حاله."},{"id":2359,"title":"محمد خوارزم شاه يمتلك بلاد ما وراء النهر بعد حروب طويلة .","date":["العام الهجري :604","العام الميلادي :1207"],"text":"عبر علاء الدين محمد خوارزم شاه نهر جيحون لقتال الخطا، وسبب ذلك أن الخطا كانوا قد طالت أيامهم ببلاد تركستان، وما وراء النهر، وثقُلت وطأتُهم على أهلها، ولهم في كل مدينة نائب يجبي إليهم الأموال، فاتفق أن سلطان سمرقند وبخارى، أنف وضجر من تحكُّم الكفار على المسلمين، فراسل خوارزم شاه يقول له: إن اللهَّ عزَّ وجلَّ قد أوجب عليك بما أعطاك مِن سَعة الملك وكثرة الجنود أن تستنقِذَ المسلمين وبلادهم من أيدي الكفار، فسيَّرَ إليه صاحبُ سمرقند وجوه أهل بخار وسمرقند، بعد أن حلفوا صاحبهم على الوفاء بما تضمنه، وضمنوا عنه الصدق والثبات على ما بذل، وجعلوا عند خوارزم رهائن، فشرع في إصلاح أمر خراسان، وتقرير قواعدها، وجمع عساكره جميعها، وسار إلى خوارزم، وتجهَّزَ منها، وعبر جيحون، واجتمع بسلطان سمرقند، ولَمَّا سمع الخطا به حشدوا وجمعوا وجاؤوا إليه، فجرى بينهم وقعات كثيرة ومغاورات، فتارة له وتارة عليه، ثم دخل خوارزم شاه نيسابور، وأصلح أمرها، وجعل فيها نائبًا، وسار إلى هراة، فنزل عليها مع عسكره الذين يحاصرونه، وزحف إليه بعسكره، فلم يكن فيه حيلة، فاتفقَ جماعة من أهل هراة وقالوا: هلك الناسُ من الجوع والقلة، وقد تعطلت علينا معايشنا، وقد مضى سنة وشهر، وكان الوزير يعِدُ بتسليم البلد إلى خوارزم شاه إذا وصل إليه، وقد حضر خوارزم شاه ولم يسَلِّم، ويجب أن نحتال في تسليم البلد والخلاص من هذه الشدة التي نحن فيها، فانتهى ذلك إلى الوزير، فبعث إليهم جماعة من عسكره، وأمرهم بالقبضِ عليهم، فمضى الجند إليهم، فثارت فتنة في البلد عظُمَ خَطبُها، فاحتاج الوزير إلى تداركها بنفسه، فمضى لذلك، فكتب من البلد إلى خوارزم شاه بالخبر، وزحف إلى البلد وأهله مختلطون، فخربوا برجين من السور، ودخلوا البلد فملكوه، وقبضوا على الوزير، فقتله خوارزم شاه، وملَكَ البلد، وذلك سنة 605، وأصلح حاله، وسلمه إلى خاله أمير ملك، وهو من أعيان أمرائه، فلم يزل بيده حتى هلك خوارزم شاه."},{"id":2360,"title":"ملك نجم الدين بن الملك العادل خلاط .","date":["العام الهجري :604","العام الميلادي :1207"],"text":"ملك الملك الأوحد نجم الدين أيوب بن الملك العادل أبي بكر ابن أيوب مدينةَ خلاط، وسبب ذلك أنَّه كان بمدينة ميافارقين مع أبيه، فلما كان من مُلك سيف الدين بلبان خلاط قصَدَ نجم الدين مدينة موش، وحصرها وأخذها، وأخذ معها ما يجاورها، وطَمِعَ في خلاط، فسار إليها فهزمه بلبان، فعاد إلى بلده وجمع وحشد، وسيَّرَ إليه أبوه جيشًا، فقصد خلاط، فسار إليه بلبان، فتصافَّا واقتتلا، فانهزم بلبان، وتمكن نجم الدين من البلاد وازداد منها، ودخل بلبان خلاط واعتصم بها، وأرسل رسولًا إلى مغيث الدين طغرل شاه بن قلج أرسلان، وهو صاحب أرزن الروم، يستنجده على نجم الدين، فحضر بنفسه ومعه عسكره، فاجتمعا وهَزَما نجم الدين، وحصرا موش، فأشرف الحصن على أن يُملَك، فغدر ابن قلج أرسلان بلبان وقتَلَه طمعًا في البلاد، فلما قتله سار إلى خلاط، فمنعه أهلُها عنها، فسار إلى ملازكرد، فردَّه أهلها أيضًا، وامتنعوا عليه، فلما لم يجِدْ في شيء من البلاد مطمعًا عاد إلى بلده، فأرسل أهل خلاط إلى نجم الدين يستدعونَه إليهم ليُمَلِّكوه، فحضر عندهم، وملك خلاط وأعمالَها سوى اليسير منها، وكره الملوك المجاورون له ملكَه لها؛ خوفًا من أبيه، وكذلك أيضًا خافه الكرج وكرهوه، فتابعوا الغارات على أعمال خلاط وبلادها، ونجم الدين مقيمٌ بخلاط لا يقدِرُ على مفارقتِها."},{"id":2361,"title":"غارات الفرنج بالشام .","date":["العام الهجري :604","العام الميلادي :1207"],"text":"كثر الفرنج الذين بطرابلس وحصن الأكراد، وأكثروا الإغارة على بلد حمص وولاياتها، ونازلوا مدينة حمص، وكان جمعهم كثيرًا لم يكن لصاحبها أسدِ الدين شيركوه بن محمد بن شيركوه بهم قوَّةٌ ولا يقدر على دفعِهم ومنعِهم، فاستنجد الظاهِرَ غازي، صاحِبَ حلب، وغيره من ملوك الشام، فلم ينجده إلا الظاهر؛ فإنه سيَّرَ له عسكرًا أقاموا عنده، ومنعوا الفرنجَ عن ولايته، ثمَّ إن الملك العادل خرج من مصر بالعساكر الكثيرة، وقصد مدينةَ عكا، فصالحه صاحبُها الفرنجي على قاعدة استقرت من إطلاق أسرى من المسلمين وغير ذلك، ثم سار إلى حمص، فنزل على بحيرة قدس، وجاءته عساكرُ الشرق وديار الجزيرة، ودخل إلى بلادِ طرابلس، وحاصر موضعًا يسمَّى القليعات، وأخذه صلحًا، وأطلق صاحِبَه، وغنم ما فيه من دواب وسلاح، وخرَّبه، وتقدَّمَ إلى طرابلس، فنهب وأحرق وسبى، وغنم وعاد، وكانت مدَّة مقامه في بلد الفرنج اثني عشر يومًا، وعاد إلى بحير قدس، وترددت الرسل بينه وبين الفرنج في الصُّلح، فلم تستقِرَّ قاعدة، ودخل الشتاء، وطلبت العساكر الشرقيَّة العودَ إلى بلادهم قبل البرد الشديد، فنزل طائفةٌ من العسكر بحمص عند صاحبها، وعاد إلى دمشق فشتى بها، وعادت عساكر ديار الجزيرة إلى أماكنها."},{"id":2362,"title":"حدوث زلزلة بالموصل .","date":["العام الهجري :604","الشهر القمري : رجب","العام الميلادي :1208"],"text":"حدثت زلزلة بالموصل في وقت السَّحَر، ولم تكن بها شديدة، وجاءت الأخبارُ من كثير من البلاد بأنها زلزلت ولم تكن بالقويَّة."},{"id":2363,"title":"مقتل السلطان غياث الدين محمود صاحب الغور .","date":["العام الهجري :605","العام الميلادي :1208"],"text":"هو السلطان غياث الدين محمود بن السلطان الكبير غياث الدين محمد بن سام الغوري, صاحب غزنة والغور وفيروزكوه, وهو مِن كبار ملوك الإسلام، اتَّفق أن خوارزم شاه علاء الدين هزم الخطا مرات، ثم وقع في أسرِهم مع بعض أمرائه، فبقي خوارزم شاه يخدُم ذلك الأمير كأنَّه مملوكه، ثم قال الأميرُ للذي أسرهما: نفِّذْ غلمانك إلى أهلي ليفتَكُّوني بمال. فقال: فابعث معهم غلامَك هذا ليدُلَّهم، فبعثه ونجا علاء الدين بهذه الحيلة، وقَدِمَ، فإذا أخوه علي شاه نائبه على خراسان قد هم بالسلطنة، ففزع منه، فهرب خوارزم شاه إلى غياث الدين محمود، فبالغ في إكرامه. لما سلَّم خوارزم شاه هراة إلى خاله \"أمير ملك\" سنة 605، وسار إلى خوارزم، أمره أن يقصد غياث الدين محمود بن غياث، وأن يقبِضَ عليه وعلى أخيه علي شاه بن خوارزم شاه، ويأخذ فيروزكوه من غياث الدين، فسار أميرُ ملك إلى فيروزكوه، وبلغ ذلك إلى محمود، فأرسل يبذُلُ الطاعة ويطلُب الأمان، فأعطاه ذلك، فنزل إليه محمود، فقبض عليه أمير ملك، وعلى علي شاه أخي خوارزم شاه، فسألاه أن يحمِلَهما إلى خوارزم شاه ليرى فيهما رأيَه، فأرسل إلى خوارزم شاه يعرفه الخبَرَ، فأمره بقتلِهما، فقُتلا في يوم واحد معا بغيًا وعدوانًا، واستقامت خراسان كلها لخوارزم شاه، وغياث الدين محمود هو آخر ملوك الغورية، وقد كانت دولتُهم من أحسن الدول سيرةً، وأعدَلِها وأكثَرِها جهادًا."},{"id":2364,"title":"مقتل سنجر شاه صاحب جزيرة ابن عمر وملك ابنه محمود .","date":["العام الهجري :605","العام الميلادي :1208"],"text":"هو سنجر شاه بن غازي بن مودود بن زنكي بن آقسنقر، صاحب جزيرة ابن عمر، وهو ابن عم نور الدين، صاحب الموصل، قتله ابنه غازي، وسبب ذلك أن سنجر كان سيئَ السيرة غشومًا ظلومًا لرعيته وجندِه وحَرَمِه وولَدِه، كثيرَ القهر لهم والانتقام منهم، فاقِدَ الشفقة على بنيه حتى غرَّب ابنيه محمودًا ومودودًا إلى قلعة فرح من بلاد الزوزان لتوهُّمٍ توهَّمه فيهما, ثم أخرج ابنه غازي إلى دار بالمدينة, ووكل به فساءت حاله، وكانت الدار كثيرة الخشاش فضَجِرَ من حاله, فأعمل غازي الحيلة حتى نزل من الدار التي كان قد حبسه أبوه بها واختفى، ثمَّ إن غازي بن سنجر تسلَّقَ إلى دار أبيه، واختفى عند بعضِ سراريِّه، وعلم به أكثَرُ من بالدار، فسَتَرت عليه بغضًا لأبيه، وتوقعًا للخلاصِ منه لشِدَّتِه عليهن، فبقي كذلك، وترك أبوه الطَّلبَ له ظنًّا منه أنَّه بالشام، فاتفق أنَّ أباه، في بعض الأيام شرب الخمر بظاهرِ البلد مع نُدَمائه، فلم يزل كذلك إلى آخر النهار، وعاد إلى داره، فلما دخل الخلاءَ، دخل عليه ابنه غازي فضربه بالسكينِ أربع عشرةَ ضربةً، ثم ذبحَه، وتركه مُلقًى، فاتفق أن بعض الخدم الصغار خرج إلى البابِ وأعلم أستاذ دار سنجر الخبَرَ، فأحضر أعيان الدولة وعرَّفَهم ذلك، وأغلق الأبوابَ على غازي، واستحلف الناسَ لمحمود بن سنجر شاه، وأرسل إليه فأحضره من قلعةِ فرح ومعه أخوه مودود، فلما حلفَ الناس وسكنوا فتحوا باب الدارِ على غازي، ودخلوا عليه ليأخُذوه، فمانعهم عن نفسِه، فقتلوه وألقَوه على باب الدار، فأكلت الكلابُ بعضَ لحمه، ثم دُفِنَ باقيه، ووصل محمودٌ إلى البلد ومَلَكَه، ولُقِّبَ بمعز الدين، لَقَب أبيه، فلما استقَرَّ عمد الى الجواري اللواتي واطأنَ على قتل أبيه فغرَّقَهن في دجلةَ."},{"id":2365,"title":"ملك العادل الخابور ونصيبين ومحاولة أخذ سنجار .","date":["العام الهجري :606","العام الميلادي :1209"],"text":"ملك العادل أبو بكر بن أيوب بلد الخابور ونصيبين، وحصر مدينة سنجار، والجميع من أعمال الجزيرة، وهو بيد قطب الدين محمد بن زنكي بن مودود، وسببُ ذلك أن قطب الدين كان بينه وبين ابنِ عَمِّه نور الدين أرسلان شاه بن مسعود بن مودود، صاحب الموصل، عداوةٌ مستحكمة، وكان لنور الدين وزراء يحبون أن يشتغل عنهم، فحسَّنوا له مراسلة العادل والاتفاق معه على أن يقتسما بالبلاد التي لقطب الدين، وبالولاية التي لولد سنجر شاه بن غازي بن مودود، وهي جزيرة ابن عمر وأعمالها، فيكون مُلك قطب الدين للعادل، وتكون الجزيرةُ لنور الدين، فوافق هذا القولُ هوى نور الدين، فأرسل إلى العادل في المعنى، فأجابه إلى ذلك مستبشرًا، فبادر العادلُ إلى المسير من دمشق إلى الفرات في عساكره، وقصد الخابور فأخذه، فلما سمع نور الدين بوصوله كأنَّه خاف واستشعر، هذا والعادل قد ملك الخابورَ ونصيبين، وسار إلى سنجار فحصرها، فبينما الأمرُ على ذلك إذ جاءهم أمر لم يكن لهم في حساب، وهو أن مظفر الدين كوكبري، صاحب إربل، أرسل وزيره إلى نور الدين يبذُلُ من نفسه المساعدةَ على منع العادل عن سنجار، وأنَّ الاتفاق معه على ما يريده، فوصل الرسولُ ليلًا فوقف مقابل دار نور الدين وصاح، فعبَرَ إليه سفينة عبر فيها، واجتمع بنور الدين ليلًا وأبلغه الرسالة، فأجاب نور الدين إلى ما طلب من الموافقة، وحلفَ له على ذلك، وعاد الوزيرُ من ليلته، فسار مظفر الدين، واجتمع هو ونور الدين، ونزلا بعساكِرِهما بظاهر الموصل، ولما وصل مظفر الدين إلى الموصل، واجتمع بنور الدين، أرسلا إلى الملك الظاهرِ غازي بن صلاح الدين، وهو صاحِبُ حلب، وإلى كيخسرو بن قلج أرسلان، صاحب بلاد الروم، بالاتِّفاق معهما، فكلاهما أجاب إلى ذلك، فتواعَدوا على الحركة وقصْد بلاد العادل إن امتنع من الصلحِ والإبقاء على صاحب سنجار، وأرسلا أيضًا إلى الخليفة الناصر لدين الله ليرسِلَ رسولًا إلى العادل في الصلح أيضًا، فقويت حينئذ نفس صاحب سنجار على الامتناع، ووصلت رسلُ الخليفة إلى العادل وهو يحاصر سنجار، فأجاب أولًا إلى الرحيل، ثم امتنع عن ذلك، وغالط، وأطال الأمر لعله يبلغ منها غرضًا، فلم ينلْ منها ما أمَّله، وأجاب إلى الصلح على أن يكون له ما أخذ وتبقى سنجار لصاحبها، واستقرَّت القاعدة على ذلك، وتحالفوا على هذا كلُّهم، وعلى أن يكونوا يدًا واحدة على الناكثِ منهم؛ ورحل العادل عن سنجار إلى حران، وعاد مظفر الدين إلى إربل، وبقي كل واحد من الملوك في بلده."},{"id":2366,"title":"وفاة الفخر الرازي .","date":["العام الهجري :606","الشهر القمري : شوال","العام الميلادي :1210"],"text":"هو العلَّامة فخر الدين, إمام الدنيا في عصره، أبو المعالي وأبو عبد الله محمد بن عمر بن الحسين بن الحسن بن علي القرشي التيمي البكري، الطبرستاني الأصل, الرازي المعروف بالفخرِ الرازي، ويقال له خطيبُ الريِّ، الفقيهُ الشافعي، المفسِّر المتكَلِّم, صاحب التصانيف المشهورة في الفقه والأصولين وغيرهما، أحد فقهاء الشافعية المشاهير بالتصانيف الكبار والصغار، له نحو من مائتي مصنَّف. ولد سنة 543, وقيل سنة أربعة وأربعين. حادَّ الذهن، كثير البراعة، قويَّ النظر في صناعة الطب، عارفًا بالأدب، له شعر بالفارسي والعربي، وكان ضخمَ البدن ربْعَ القامة، كبير اللحية، في صوته فخامة. اشتغل على والده الإمام ضياء الدين عمر، وبعد وفاة والده قصد الكمال السمناني، واشتغل عليه مدة، ثم عاد إلى الري، ثم قصد خوارزم وقد تمهر في العلوم، فجرى بينه وبين أهلها كلام فيما يرجع إلى المذهب والعقيدة، فأُخرِجَ من البلد، فقصد ما وراء النهر، فجرى له أيضًا ما جرى بخوارزم، فعاد إلى الريِّ، وكان بها طبيب حاذق له ثروة ونعمة، وله بنتان، ولفخر الدين ابنان، فمَرِضَ الطبيب فزوج بنتيه بابني الفخر، ولما مات الطبيب حصل الفخر على جميع أموالِه\". وقد كان معظَّمًا عند ملوك خوارزم وغيرهم، وبنيت له مدارس كثيرة في بلدان شتى، وكان يحضر في مجلس وعظه الملوك والوزراء والعلماء، والأمراء، والفقراء والعامة، وله في الوعظِ مرتبةٌ عالية يعظ باللسانين الفارسي والعربي، وكان يلحقه الوجدُ حالَ وعظه، ويحضُرُ مجلِسَه أرباب المقالات والمذاهب ويسألونه. ورجع بسببِه خلق كثير من الكرَّاميَّة وغيرهم إلى مذهب أهل السنة، وكان يلقَّب في هراة بشيخ الإسلام. وقد وقع بينه وبين الكرَّاميَّة وقائع في أوقات متفرقة، وكان يبغضهم ويبغضونه، ويبالغون في الحطِّ عليه، ويبالغ هو أيضًا في ذمهم، وكان مع غزارة علمِه في فن الكلام يقول: من لزم مذهبَ العجائِز كان هو الفائز، وقد قيل في وصيته عند موته أنَّه رجع عن مذهب الكلامِ فيها إلى طريقةِ السَّلَف وتسليم ما ورد على وجهِ المراد اللائقِ بجلالِ الله سبحانه، وقد كان يصحب السلطانَ ويحب الدنيا ويتَّسِعُ فيها اتساعًا عظيمًا، حتى قيل: ملك من الذهب العين ثمانين ألف دينار، وغير ذلك من الأمتعة والمراكب والأثاث والملابس، وكان له خمسون مملوكًا من الترك، وحشم وتجمل زائد، وعلى مجلسه هيبة شديدة. وليس ذلك من صفة العلماء؛ ولهذا وأمثاله كثرت الشناعات عليه، كما قامت عليه شناعات عظيمةٌ بسبب كلمات كان يقولها. قال أبو المظفر سبط ابن الجوزي، وأبو شامة: \"اعتنى الفخرُ الرازي بكتب ابن سيناء وشَرحِها. وكان يعظ وينال من الكرَّامية، وينالون منه سبًّا وتكفيرا، وقيل: إنهم وضعوا عليه من سقاه السمَّ فمات، وكانوا يرمونه بالكبائر. ولا كلامَ في فضله، وإنما الشناعاتُ قائمة عليه بأشياء؛ منها: أنه قال: قال محمد التازي، وقال محمد الرازي، يعني النبي صلى الله عليه وسلم ونفسه، والتازي: هو العربي- وقيل كان يقول محمد البادي يعني العربي يريد به النبيَّ صلى الله عليه وسلم نسبة إلى البادية. ومنها أنه كان يقرر مسائل الخصوم وشبههم بأتمِّ عبارة، فإذا جاء بالأجوبة، قنع بالإشارة. ولعله قصد الإيجاز، ولكن أين الحقيقة من المجاز\", ومن مصنفاته: وتفسيره الكبير في اثنتي عشرة مجلدة كبار سماه \" \"فتوح الغيب\" أو \"مفاتيح الغيب\". وفسر الفاتحة في مجلد مستقل. وشرح نصف \"الوجيز\" للغزالي. وله كتاب \" المطالب العالية \" في ثلاثة مجلدات، ولم يتمه، وهو من آخر تصانيفه، وله كتاب \"عيون الحكمة \" فلسفة، وكتاب في الرمل، وكتاب في الهندسة، وكتاب \" الاختبارات العلائية \" فيه تنجيم، وكتاب \" الاختبارات السماوية \" تنجيم، وكتاب \" الملل والنحل \"، وكتاب في النبض، وكتاب \" الطب الكبير \"، وكتاب \" التشريح \" لم يتمه، وصنف ترجمة الشافعي في مجلد مفيد، وفيه غرائب لا يوافَق عليها، ويُنسَب إليه أشياء عجيبة، وغيرها من المصنفات وهي كثيرة. قال ابن خلكان: \"وكل كتبه ممتعة، وانتشرت تصانيفُه في البلاد ورُزِقَ فيها سعادة عظيمة؛ فإن الناس اشتغلوا بها ورفضوا كتبَ المتقدمين، وهو أول من اخترع هذا الترتيب في كتبِه، وأتى فيها بما لم يُسبَق إليه\". قال الموفق أحمد بن أبي أصيبعة في \" تاريخه:\"انتشرت في الآفاق مصنفات فخر الدين وتلامذته، وكان إذا ركب مشى حوله نحو ثلاثمائة تلميذ من الفقهاء، وغيرهم، وكان خوارزم شاه يأتي إليه، وكان شديدَ الحرص جدًّا في العلوم الشرعية والحكمية، وكان طلاب العلم يقصدونَه من البلاد على اختلاف مطالبِهم في العلوم وتفنُّنِهم، فكان كلٌّ منهم يجد عنده النهاية القصوى فيما يرومه منه. قرأ الحكمة على المجد الجيلي بمراغة، وكان المجد من كبار الفضلاء وله تصانيف. قلت (الذهبي): يعني بالحكمة: الفلسفة\". ومن تلامذته مصنف \" الحاصل \" تاج الدين محمد بن الحسين الأرموي، وشمس الدين عبد الحميد بن عيسى الخسروشاهي، والقاضي شمس الدين الخويي، ومحيي الدين قاضي مرند, ولَمَّا أثرى الفخر الرازي، لازم الأسفارَ والتجارة، وعاملَ شهاب الدين الغوري في جملةٍ من المال، ومضى إليه لاستيفاء حقِّه، فبالغ في إكرامه، ونال منه مالًا طائلًا، ثم اتصل بالسلطان محمد بن تكش المعروف بخوارزم شاه، وحظي عنده، ونال أسنى المراتبِ، ولم يبلغ أحد منزلتَه عنده, وكان الفخر الرازي خطيبَ الري، وكان أكثَرُ مُقامه بها، وتوجه إلى خوارزم ومرض بها، وامتد مرضه أشهرًا، وتوفي يوم عيد الفطر بهراة بدار السلطنة. وكان علاء الملك العلوي وزير خوارزم شاه قد تزوج بابنته, ومن كلام فخر الدين قال: \" فاعلموا أنني كنت رجلًا محبًّا للعلم، فكنت أكتبُ في كل شيء شيئًا؛ لأقف على كميته وكيفيته، سواء كان حقًّا أو باطلًا، ولقد اختبرت الطرقَ الكلامية، والمناهج الفلسفيةَ، فما رأيت فيها فائدة تساوي الفائدة التي وجدتُها في القرآنِ؛ لأنَّه يسعى في تسليم العظمة والجلالة لله، ويمنَعُ عن التعمق في إيراد المعارضات والمناقضات؛ فلهذا أقول: كل ما ثبت بالدلائل الظاهرة من وجوب وجوده ووحدته، وبراءتِه عن الشركاء في القِدَم، والأزلية، والتدبير، والفعالية، فذلك هو الذي أقولُ به، وألقى الله به. وأما ما انتهى الأمر فيه إلى الدقة والغموض، وكل ما ورد في القرآن والصحاح، المتعين للمعنى الواحد، فهو كما هو، والذي لم يكن كذلك أقول: يا إله العالمين، إني أرى الخلق مطبقين على أنَّك أكرم الأكرمين، وأرحم الراحمين، فلك ما مدَّ به قلمي، أو خطر ببالي فأستشهد وأقول: إن علمتَ مني أني أردتُ به تحقيق باطل، أو إبطالَ حَقٍّ، فافعل بي ما أنا أهلُه، وإن علمتَ مني أني ما سعيتُ إلا في تقرير اعتقدت أنه الحق، وتصورتُ أنه الصدق، فلتكن رحمتُك مع قصدي لا مع حاصلي، فذاك جهدُ المُقِلِّ، فأغثني وارحمني، واستر زلتي وامح حوبتي، وأقول: ديني متابعةُ الرسول محمد صلى الله عليه وسلم، وكتابي القرآن العظيم، وتعويلي في طلب الدين عليهما، وأمَّا الكتب التي صنفتها، واستكثرت فيها من إيراد السؤالات، فليذكرني من نظر فيها بصالحِ دعائه، على سبيل التفَضُّل والإنعام، وإلَّا فليحذف القولَ السيئَ، فإني ما أردت إلا تكثير البحثِ، وشحذ الخاطر، والاعتماد في الكل على الله\"."},{"id":2367,"title":"وفاة ابن الأثير الجزري صاحب جامع الأصول .","date":["العام الهجري :606","الشهر القمري : ذي الحجة","العام الميلادي :1210"],"text":"هو مجد الدين أبو السعادات المبارك بن أبي الكرم محمد بن محمد بن عبد الكريم بن عبد الواحد الشيباني، المعروف بابن الأثير الجزري كانت ولادته بجزيرة ابن عمر سنة 544 ونشأ بها، ثم انتقل إلى الموصل سنة خمس وستين, ثم عاد إلى الجزيرة، ثم الموصل، وتنقل في الولايات بها واتصل بخدمة الأمير مجاهد الدين قايماز بن عبد الله الخادم الزيني، فكتب له, ثمَّ اتصل بخدمة عز الدين مسعود بن مودود صاحب الموصل، وتولى ديوان رسائله وكتب له إلى أن توفي، ثم اتصل بولده نور الدين أرسلان شاه فحَظِيَ عنده، وتوفَّرت حرمتُه لديه، وكتب له مدة, ثم عرض له مرض كفَّ يديه ورجليه فمنعه من الكتابة مطلقًا، وأقام في داره يغشاه الأكابرُ والعلماء، وأنشأ رباطًا بقرية من قرى الموصل ووقفَ أملاكَه عليه وعلى داره التي كان يسكنها بالموصل، وقيل: إنه صنف كتبه كلَّها في مدة العطلة، وكان عنده جماعة يعينونه عليها في الاختيار والكتابة. كان ابن الأثير عالِمًا في عدة علوم مبرزًا فيها، منها: الفقه، والأصولان، والنحو، والحديث، واللغة، وله تصانيف مشهورة في التفسير والحديث، والنحو، والحساب، وغريب الحديث، وله رسائل مدوَّنة، وهو صاحب جامع الأصول في الحديث، وله كتاب غريب الحديث والأثر، وغيرها من المصنفات، وهو غير صاحب الكامل في التاريخ، فهذا أخوه. قال أبو البركات ابن المستوفي في تاريخ إربل في حقه: أشهر العلماء ذِكرًا، وأكبر النبلاء قدرًا، وأحد الأفاضل المشار إليهم، وفرْد الأماثل المعتمد في الأمور عليهم، أخذ النحوَ عن شيخه أبي محمد سعيد بن المبارك الدهان، وسمع الحديث متأخرًا، ولم تتقدَّم روايته. وله المصنَّفات البديعة والرسائل الوسيعة \" توفي في آخر ذي الحجة."},{"id":2368,"title":"وفاة السلطان أرسلان شاه بن مسعود وقيام ولده بعده .","date":["العام الهجري :607","الشهر القمري : رجب","العام الميلادي :1211"],"text":"هو السلطانُ الملك العادل نور الدين أبو الحارث، أرسلان شاه بن مسعود بن مودود بن أتابك عماد الدين زنكي بن آقسنقر، صاحب الموصل, وابنُ صاحبها، كان ملكًا شَهمًا، عارفًا بالأمور، جبارًا سافكًا للدماء بخيلًا. انتقل إلى مذهب الشافعي، ولم يكن في بيته شافعيٌّ سواه. وبنى المدرسة المعروفة به بالموصل للشافعية، قل أن توجد مدرسة في حسنها. كان سريع الحركة في طَلَبِ الملك، إلَّا أنه لم يكن له صبرٌ؛ فلهذا لم يتَّسِع ملكه، ولما احتُضِرَ أمر أن يرتب في الملك ولده الملك القاهر مسعود، وأعطى ولده عماد الدين زنكي قلعتين، وجعل تدبيرَ مملكتهما إلى فتاه بدر الدين لؤلؤ. وكان مرضه قد طال، ومزاجه قد فسد، وكانت مُدَّة ملكه سبع عشرة سنة وأحد عشر شهرًا، وكان شهمًا شجاعًا، ذا سياسة للرعايا، شديدًا على أصحابه، فكانوا يخافونه خوفًا شديدًا، وكان ذلك مانعًا من تعدي بعضِهم على بعض، وكان له همة عالية، أعاد ناموس البيت الأتابكي وجاهَه وحُرمَتَه، بعد أن كانت قد ذهبَت، وخافه الملوك؛ ولما اشتد مرضه وأيس من نفسه أمره الأطباء بالانحدار إلى الحامة المعروفة بعين القيارة، وهي بالقرب من الموصل، فانحدر إليها، فلم يجِدْ بها راحة، وازداد ضعفًا، فأخذه بدر الدين وأصعده في الشبارة إلى الموصل، فتوفي في التاسع والعشرين من رجب. في الطريق ليلًا ومعه الملاحون والأطباء بينه وبينهم ستر، وكان مع بدر الدين عند نور الدين مملوكان، فلما توفي نور الدين قال لهما: لا يسمع أحدٌ بموته، وقال للأطباء والملاحين: لا يتكلم أحد، فقد نام السلطانُ، فسكتوا، ووصلوا إلى الموصل في الليل، فأمر الأطباءَ والملاحين بمفارقة الشبارة؛ لئلَّا يَرَوه ميتًا، وأبعدوا، فحمله هو والمملوكان، وأدخله الدار، وتركه في الموضع الذي كان فيه ومعه المملوكان، ونزل على بابه من يثقُ به لا يمكِّن أحدًا من الدخول والخروج، وقعد مع الناس يمضي أمورًا كان يحتاجُ إلى إتمامها، فلما فرغَ مِن جميع ما يريدُه أظهَرَ موتَه وقت العصر، ودُفِنَ ليلًا بالمدرسة التي أنشأها مقابلَ داره، وضبط البلدَ تلك الليلة ضبطًا جيدًا واستقَرَّ الملك لولده، وقام بدر الدين بتدبير الدولة والنظر في مصالحِها."},{"id":2369,"title":"اعتداءات الفرنج على البلاد المسلمين في الشام ومصر .","date":["العام الهجري :607","الشهر القمري : ذي الحجة","العام الميلادي :1211"],"text":"توجَّهت مراكب من عكا فيها ملك قبرص المسمَّى إليان إلى ثغر دمياط، فدخله ليلًا وأغار على بعض البلاد، فقتل وسبى وكر راجعًا، فركب مراكبه ولم يدركه الطلبُ، وقد تقدمت له غارة مثلُها قبل هذه، وهذا شيءٌ لم يتَّفِق لغيره، وفيها عاثت الفرنجُ بنواحي القدس، فبرز إليهم الملك المعظم شرف الدين بن الملك العادل، وعمل أبو المظفر سبط ابن الجوزي ميعادًا بنابلس وحثَّ على الجهاد، وكان يومًا مشهودًا، ثم سار هو ومن معه وبصحبته المعظَّم نحو الفرنج، فقتلوا خلقًا وخربوا أماكن كثيرة، وغَنِموا وعادوا سالمين، وشرع المعظَّم في تحصين جبل الطور وبنى قلعة فيه ليكونَ إلبًا على الفرنج، فغرم أموالًا كثيرة في ذلك، فبعث الفرنجُ إلى العادل يطلُبونَ منه الأمان والمصالحة، فهادنهم وبطلت تلك العمارةُ وضاع ما كان المعظَّمُ غرم عليها."},{"id":2370,"title":"هزيمة الفرنج بطليطلة ببلاد الأندلس .","date":["العام الهجري :608","العام الميلادي :1211"],"text":"جاءت الأخبار من بلاد الأندلس بأنَّ الموحِّدينَ قد كسروا الفرنجَ بطُليطِلة كسرةً عظيمة، وربما فتحوا طليطلةَ عَنوةً وقَتل منهم خلقًا كثيرًا."},{"id":2371,"title":"إظهار الإسماعيلية توبتهم من اعتقادات الباطنية .","date":["العام الهجري :608","العام الميلادي :1211"],"text":"أظهر الإسماعيليَّةُ- ومقَدَّمُهم جلالُ الدين الإسماعيليُّ، تولى بعد أبيه, وقيل: إنه كان غير راضٍ عن ممارساتِ أبيه أعلى محمد وسياستِه العدوانيَّة- الانتِقالَ عن فعل المحرَّمات واستحلالِها، وأمَرَ بإقامة الصلواتِ وشرائِعِ الإسلامِ ببلادهم من خراسان والشام، وأرسل مقدُّمُهم رسلًا إلى الخليفة، وغيره من ملوك الإسلام، يخبِرُهم بذلك، وأرسل والدتَه إلى الحجِّ، فأُكرِمَت ببغدادَ إكرامًا عظيمًا، وكذلك بطريقِ مكَّةَ."},{"id":2372,"title":"وفاة العلامة محمد بن يونس بن منعة الفقيه الشافعي .","date":["العام الهجري :608","الشهر القمري : جمادى الآخرة","العام الميلادي :1211"],"text":"هو العلَّامةُ عماد الدين أبو حامد محمد بن يونس بن محمد بن منعة بن مالك الإربلي الأصل الموصلي، الفقيه الشافعي، وُلِدَ سنة 535 بمدينة الموصل وتفَقَّه بها على والده، ثم سار إلى بغداد، وتفقَّه بها بالنظامية على السديد محمَّد السلماسي، وأبي المحاسن يوسف بن بندار الدمشقي، وسمِعَ الحديثَ من أبي حامد محمد بن أبي الربيع الغرناطي، وعبد الرحمن بن محمد الكشميهني. وعاد إلى الموصل، ودرَّس بها في عدة مدارس، وعلا صيتُه، وشاع ذكرُه، وقصَدَه الفقهاء من البلاد، وتخرَّجَ به خلقٌ، انتهت إليه رياسةُ الشافعية، وكان حسَنَ الأخلاق، كثيرَ التجاوز عن الفقهاء، كثيرَ الإحسان إليهم. كان إمامًا فاضلًا، وإمامَ وَقتِه في المذهب والأصول والخِلاف، وكان له صيتٌ عظيم في زمانه، صنف \" المحيط \" وجمع فيه بين \"المهذب\" و\"الوسيط\"، وشرح \"الوجيز\"، وصنف جدلًا، وعقيدة، وغير ذلك وتوجَّه رسولًا إلى الخليفة غير مرة، ووليَ قضاءَ الموصل خمسة أشهر ثم عُزِل، وذلك في صفر سنة ثلاث وتسعين، قال ابن خلكان: \"كان شديدَ الورع والتقشُّف، لا يلبس الثوب الجديد حتى يغسِلَه، ولا يمسُّ القلَمَ للكتابة إلا ويغسِلُ يده، وكان دمثَ الأخلاق لطيف الخلوة ملاطفًا بحكايات وأشعار، وكان كثيرَ المباطنة لنور الدين أرسلان صاحب الموصل يُرجَع إليه في الفتاوى ويُشاوَر في الأمور, ولم يزل معه حتى انتقل أرسلان عن مذهب أبي حنيفة إلى مذهب الشافعي\" فلما توفي نور الدين توجَّه الشيخ عماد الدين إلى بغداد، وأخذ السلطنة للملك القاهر مسعود بن نور الدين، وأتى بالتقليدِ والخِلعة."},{"id":2373,"title":"استيلاء منكلي على بلاد الجبل وأصفهان .","date":["العام الهجري :608","الشهر القمري : شعبان","العام الميلادي :1212"],"text":"قدم إيدغمش، صاحب همذان وأصفهان والري وما بينهما من البلاد إلى بغداد، هاربًا من منكلي، وسببُ ذلك أن إيدغمش كان قد تمكَّنَ في البلاد، وعظم شأنُه، وانتشر صيتُه، وكثُرَ عَسكَرُه، حتى إنَّه حصر صاحبه أبا بكر البهلوان، صاحب هذه البلاد: أذربيجان وأران، فلما كان هذا العام خرج عليه مملوكٌ اسمه منكلي، ونازعه في البلادِ، وكثر أتباعه، وأطاعه المماليكُ البهلوانية، فاستولى عليها، وهرب منه شمس الدين إيدغمش إلى بغداد، فلما وصل إليها أمر الخليفة بالاحتفالِ له في اللقاء، فخرج الناسُ كافة، وكان يومُ وصوله مشهودًا، ثمَّ قَدِمَت زوجتُه في رمضان في محمل، فأُكرِمَت وأُنزِلَت عند زوجها، وأقام ببغدادَ إلى سنة عشر وستمائة، فسار عنها."},{"id":2374,"title":"نهب أمير مكة حجاج العراق بمنى .","date":["العام الهجري :608","الشهر القمري : ذي الحجة","العام الميلادي :1212"],"text":"وثب أحدُ الباطنية على بعض أهلِ الأمير قتادة، صاحِبِ مكة، فقتله بمنًى ظنًّا منه أنه قتادة، فلما سمع قتادةُ ذلك جمع الأشراف والعربَ والعبيد وأهلَ مكَّة، وقصدوا الحاجَّ، ونزلوا عليهم من الجبَلِ، ورموهم بالحجارة والنبل وغير ذلك، وكان أميرُ حجاَّج العراق ولد الأمير ياقوت وهو صبي لا يَعرِفُ كيف يفعَلُ، فخاف وتحيَّرَ، وتمكن أمير مكة من نهب الحاجِّ، فنَهَبوا منهم من كان في الأطراف، وأقاموا على حالهم إلى الليلِ، فاضطرب الحاجُّ، وباتوا بأسوأ حال من شدة الخوفِ مِن القتل والنهب، فقال بعضُ الناس لأمير الحاج لينتقل بالحجَّاج إلى منزلة حجَّاج الشام، فأمر بالرحيل، فرفعوا أثقالَهم على الجمال تؤخَذُ بأحمالها، والتحَقَ مَن سَلِمَ بحجاج الشام، فاجتمعوا بهم، ثم رحلوا إلى الزاهر، ومُنعوا من دخولِ مكة، ثم أذِنَ لهم في ذلك، فدخلوها وتمَّموا حجَّهم وعادوا، ثم أرسل قتادةُ ولده وجماعة من أصحابه إلى بغداد، فدخلوها ومعهم السيوفُ مسلولةً والأكفان، فقَبَّلوا العتبةَ، واعتذروا ممَّا جرى على الحُجَّاج."},{"id":2375,"title":"وفاة الملك الأوحد صاحب خلاط .","date":["العام الهجري :609","العام الميلادي :1212"],"text":"توفي الملك الأوحد نجم الدين والدنيا أيوب بن السلطان الملك العادل أبي بكر، صاحب خلاط بتركيا في أيام أبيه الملك العادل، مَلَكَ خلاط ونواحيها، فظلم وعسَف وسفك الدماء بها, وقيل إنه قتل ثمانية عشر ألف نَسَمة بخلاط عندما أخذها، فابتُلي بأمراضٍ مزمنة، فتمنى الموتَ، فمات قبل الكهولة, وكان قد استزار أخاه الملك الأشرف موسى من حران، فأقام عنده أيامًا، واشتد مرضُه فطلب الأشرف الرجوع إلى حران، فقال له الأوحدُ: يا أخي لم تلِحُّ في الرواح، والله إني ميت وأنت تأخذ البلادَ مِن بعدي، فكان كذلك! وملك الأشرف بعد موته خلاط وأحبَّه أهلُها، كلُّ ذلك في حياة أبيهما الملك العادل، فكانت مدَّة تملك الأوحد خلاط أقلَّ من خمس سنين."},{"id":2376,"title":"محاولة الأمير أسامة الجبلي الاستيلاء على دمشق .","date":["العام الهجري :609","العام الميلادي :1212"],"text":"اجتمع العادل وأولاده الكامل والمعظم والفائز بدمياط من بلاد مصر في مقاتلة الفرنج، فاغتنم غيبتَهم أسامة الجبلي أحدُ أكابر الأمراء، وكانت بيدِه قلعة عجلون وكوكب فسار مسرعًا إلى دمشق ليتسلم البلدين، فأرسل العادلُ في إثره ولَدَه المعَظَّم فسبقه إلى القدسِ وحملَ عليه في كنيسة صهيون، وكان الجبلي شيخًا كبيرًا قد أصابه النقرس، فشرع المعظَّمُ يرده إلى الطاعة بالملاطفةِ فلم ينفَعْ فيه، فاستولى على حواصله وأملاكِه وأموالِه، وأرسله إلى قلعة الكرك فاعتُقِلَ فيها، ثم أمر العادل بقتله فقُتِلَ بها، وكان قيمة ما أخذ من الجبلي قريبًا من ألف ألف دينار، من ذلك داره وحمَّامه داخل باب السلامة، ودارُه هي التي جعلها البادرائي مدرسة للشافعية، وخُرِّب حِصنُ كوكب ونُقِلَت حواصله إلى حصن الطور الذي استجده العادِلُ وولده المعظم."},{"id":2377,"title":"قدوم ابن منكلي بغداد .","date":["العام الهجري :609","الشهر القمري : محرم","العام الميلادي :1212"],"text":"قدم محمد بن منكلي المستولي على بلاد الجبل إلى بغداد، وسببُ ذلك أنَّ أباه منكلي لَمَّا استولى على بلاد الجبل وهرب إيدغمش صاحبها منها إلى بغداد خاف أن يساعِدَه الخليفة، ويرسِل معه العساكر، فيَعظُم الأمر عليه؛ لأنَّه لم يكن قد تمكَّن في البلاد، فأرسل ولده محمدًا ومعه جماعةٌ من العسكر، فخرج النَّاسُ ببغداد على طبقاتِهم يلتقونَه، وأُنزِلَ وأُكرِمَ، وبَقِيَ ببغداد إلى أن قُتِلَ منكلي إيدغمش بهمذان سنة عشر، فخلع الخليفةُ على ابن منكلي وعلى من معه، وأُكرِموا، وسيَّرَهم إلى بلاد الجبل."},{"id":2378,"title":"هزيمة الموحدين في موقعة العقاب بالأندلس .","date":["العام الهجري :609","الشهر القمري : صفر","العام الميلادي :1212"],"text":"انهزم الموحِّدون في وقعةِ العقاب أمام جيوشِ الأسبان من قشتالة وليون ونافار المتحالفة بقيادة ألفونسو الثامن ملك قشتالة، وهذه المعركة وقَعَت قُربَ حِصنِ العقاب في الخامسَ عشَر مِن صفر. لَمَّا انتهت الهدنة مع الفرنج، عبَرَ السلطان الناصر بجيوشه إلى إشبيلية, ثم تحرَّك في سنة 608 لجهادهم، فنازل حصنًا لهم فأخذه، فسار ألفونسو في أقاصي الممالك يستنفر عبَّاد الصليب، فاجتمَعَت له جيوش ما سُمِعَ بمِثلِها، ونجدته فرنج الشام، وعساكر القسطنطينية، وملك أرغن البرشلوني، واستنفر السلطانُ الناصر الناس، والتقى الجمعانِ في وقعة تُعرَف بالعقاب، بالقربِ من حصنِ سالم، فتحَمَّل ألفونسو حملةً شديدة، فهزم المسلمين، واستشهد خلقٌ كثير. وكان أكبر أسباب الكسرة غضبَ الجند من تأخُّر عطائهم، وخصوصًا في هذه السفرة، فنَسَبوا ذلك إلى الوزراء، وخرجوا وهم كارهون، فلم يَسُلُّوا سيفًا ولا شرعوا رمحًا ولا أخذوا في شيءٍ مِن أهبة القتال؛ بل انهزموا لأوَّلِ حَملةِ الإفرنج عليهم قاصدين لذلك. وثبت السلطانُ ثباتًا عظيمًا، وكانت الملحمة في صفر سنة 609، ورجع العدوُّ بغنائم لا توصف، وأخذوا بياسة عنوةً، فلما وجدها شبه خالية، حرق دورها وخرَّب مسجدها الكبير؛ ثم نزل ألفونسو على أبذة وقد اجتمع فيها من المسلمين عدد كثير من المنهزمة وأهل بياسة وأهل البلد نفسه، فأقام عليها ثلاثة عشر يومًا، ثم دخلها عَنوةً فقتل وسبى وغنم، وأخذ هو وأصحابه من السبيِ مِن النساء والصبيان ما مَلَؤوا به بلاد الروم قاطبة، فكانت هذه أشدَّ على المسلمين من الهزيمة, وقد ترتَّبَ على هذه الهزيمة انحسارُ المسلمين في الأندلس بغرناطة وتفكُّك وحدة الشمال الإفريقي، وقيام ثلاث دول إسلامية مغربية، هي دولة بني حفص شرقًا، ودولة بني زيان من بني عبد الواد بالمغرب الأقصى، ودولة بني مرين غربًا، فاستقَلَّت هذه الدولُ عن دولة الموحِّدين."},{"id":2379,"title":"قتل إيدغمش صاحب همذان .","date":["العام الهجري :610","الشهر القمري : محرم","العام الميلادي :1213"],"text":"هو شمسُ الدين إيدغمش صاحب همذان وأصبهان والري. كان قد تمكن وعَظُم أمرُه، وبَعُد صيتُه، وكثُرَ جَيشُه إلى أن حصر ابن أستاذه أبا بكر بن البهلوان صاحب أذربيجان، فلما كان في سنة ثمان وستمائة خرج عليه أحدُ مماليكه اسمه منكلي ونازعه في البلاد، وأطاعته المماليكُ البهلوانية. فهرب أيدغمش سنة ثمانٍ إلى بغداد وأقام بها، فأنعم عليه الخليفةُ، وشَرَّفه بالخِلَع، ثمَّ سَيَّرَه إلى همذان، فسار إيدغمش في جمادى الآخرة عن بغداد قاصدًا همذان، فوصل إلى بلاد سليمان بن ترجم واجتمعا، وأقام ينتظر وصولَ عساكر بغداد إليه ليسيرَ معه على قاعدة استقَرَّت بينهم، وكان الخليفة قد عزل ابن ترجم عن الإمارة على عشيرته من التركمان الإيوانية، وولى أخاه الأصغر، فأرسل ابن ترجم إلى منكلي يعَرِّفُه بحال إيدغمش، ومضى هو على وجهِه، فأرسل منكلي من أخَذَه وقَتَلَه، وحمل رأسَه إليه، وتفَرَّق أصحاب إيدغمش في البلاد، ووصل الخبَرُ بقتله إلى بغداد، فعظُم ذلك على الخليفة، وأرسلَ إلى منكلي ينكِرُ عليه ما فعل، فأجاب جوابًا شديدًا، وتمكَّن من البلاد، وقَوَيَ أمرُه، وكثرت جموعُ عساكِرِه."},{"id":2380,"title":"وفاة الناصر حاكم الموحدين بالمغرب والأندلس .","date":["العام الهجري :610","الشهر القمري : شعبان","العام الميلادي :1214"],"text":"هو السلطانُ أبو عبد الله الملك الناصر محمد بن يعقوب المنصور بالله يوسف بن عبد المؤمن بن علي القيسي, أميرُ الموحدين، وأمُّه رومية اسمها زهر. بويعَ له بعد أبيه سنة 595 بعهدٍ من أبيه، وكان أشقَرَ أشهَلَ أسيل الخَدِّ مليح الشكل، كثير الصمتِ والإطراق، شجاعًا مَهيبًا بعيدَ الغور، حليمًا عفيفًا عن الدماء، وفي لسانه لثغةٌ، وكان بخيلًا، وله عِدَّة أولاد. استوزر أبا زيد بن يوجان، ثم عزله، واستوزر الأمير إبراهيم أخاه، وكتب سرَّه ابن عياش، وابن يخلفتن الفازازي، وولي قضاءَه غير واحد. وكان قد استرد تونس والمهدية وما كان استولى عليه عليُّ بن غانية من إفريقيا، كما استولى على طرابلس الغرب وانتزعها من الأميرِ بهاء الدين قراقوش قائد الأيوبيين المصري، كما انتزع جزيرة ميورقة وما حولها من الجزر جزر الباليار من بني غانية، وكانوا نواب المرابطين فيها، وقاتل الأسبان فهزموه في وقعة العقاب عام 609, ولما عاد الناصرُ إلى مراكش أخذ البيعة لولده يوسف الملقب بالمستنصر بالله، ثمَّ احتجب في قصره إلى أن مات في هذا العامِ بعد أن أصيب بمرضٍ أيامًا، ومات في شعبانَ مِن هذه السنة، وكانت أيامُه خمسة عشر عامًا، وقام بعده ابنه المستنصرُ يوسف عشرة أعوام."},{"id":2381,"title":"خوارزم شاه يمتلك مدينة كرمان ومكران والسند .","date":["العام الهجري :611","العام الميلادي :1214"],"text":"كان من جملة أمراء خوارزم شاه تكش والد خوارزم شاه محمد, أميرٌ اسمُه أبو بكر، ولقَبُه تاج الدين، وكان في ابتداءِ أمرِه جمَّالًا يكري الجمالَ في الأسفار، ثم جاءته السعادة، فاتصل بخوارزم شاه، وصار سيروانَ جمالِه، فرأى منه جلدًا وأمانةً، فقَدَّمَه إلى أن صار من أعيانِ أمراءِ عَسكَرِه، فولَّاه مدينة زوزن، وكان عاقلًا ذا رأي وحزمٍ وشجاعة، فتقَدَّم عند خوارزم شاه تقدمًا كثيرًا، فوَثِقَ به أكثَرَ مِن جميع أمراء دولتِه، فقال أبو بكر لخوارزم شاه: إنَّ بلاد كرمان مجاورةٌ لبلدي، فلو أضاف السلطانُ إليَّ عسكرًا لملكتُها في أسرع وقت، فسيَّرَ معه عسكرًا كثيرًا فمضى إلى كرمان، وصاحبها اسمه حرب بن محمد بن أبي الفضل الذي كان صاحِبَ سجستان أيَّامَ السلطان سنجر، فقاتَلَه، فلم يكُنْ له به قوة، وضَعُفَ، فملك أبو بكر بلادَه في أسرع وقت، وسار منها إلى نواحي مكرانَ فملكها كلها إلى السند، من حدودِ كابل، وسار إلى هرمز، مدينةٍ على ساحلِ بحر مكران، فأطاعه صاحبُها، واسمه ملنك، وخطَبَ بها لخوارزم شاه، وحملَ عنها مالًا، وخطبَ له بقلهات، وبعض عمان؛ لأن أصحابها كانوا يطيعون صاحِبَ هرمز. وقيل إنَّ ملك خوارزم شاه لكرمان ومكران والسند كان في السنةِ التي قبلها أو بعدها بقليلٍ."},{"id":2382,"title":"تبليط داخل الجامع الأموي .","date":["العام الهجري :611","العام الميلادي :1214"],"text":"شُرِعَ في تبليطٍ داخل الجامع الأموي وبدؤوا من ناحيةِ السبع الكبير، وكانت أرضُ الجامع قبل ذلك حُفرًا وجورًا، فاستراح النَّاسُ بتبليطِه."},{"id":2383,"title":"أخذ المعظم قلعة صرخد من ابن قراجا .","date":["العام الهجري :611","العام الميلادي :1214"],"text":"أخذ المُعظَّم قلعة صرخد من ابن قراجا وعَوَّضَه عنها وسَلَّمَها إلى مملوكه عز الدين أيبك المعظمي، فثبَتَت في يده إلى أن انتزعها منه نجمُ الدين أيوب سنة 644."},{"id":2384,"title":"طرد الملك العادل أمير مكة منها .","date":["العام الهجري :611","العام الميلادي :1214"],"text":"حجَّ الملك المعَظَّم بنُ العادلِ فرَكِبَ مِن الكرك على الإبل في حادي عشر ذي القعدة، ومعه ابن موسك ومملوك أبيه وعز الدين أستاذ داره وخَلْقٌ، فلما قدم المدينةَ النبويَّةَ تلقَّاه صاحبُها سالم وسَلَّمَ إليه مفاتيحَها وخَدَمه خدمةً تامَّةً، وأمَّا صاحب مكة قتادةُ فلم يرفَعْ به رأسًا؛ ولهذا لما قضى نسُكَه، وكان قارنًا، وأنفق في المجاورين ما حمَلَه إليهم من الصَّدَقاتِ، وكَرَّ راجعًا؛ استصحب معه سالِمًا صاحب المدينة وتشكى إلى أبيه عند رأسِ الماء ما لقيه من صاحب مكةَ، فأرسل العادِلُ، مع سالم جيشًا يطرُدونَ صاحِبَ مكَّةَ، فلمَّا انتهوا إليها هرب منهم في الأوديةِ والجبالِ والبراري."},{"id":2385,"title":"تملك أضسيس اليمن بعد وفاة أيوب بن طغتكين  .","date":["العام الهجري :611","العام الميلادي :1214"],"text":"لما مات صاحب اليمن أيوب بن طغتكين تولى بعده سليمان بن شاهنشاه بن تقي الدين عمر بن شاهنشاه بن أيوب باتِّفاق الأمراء عليه، فأرسل العادِلُ إلى ولده الكامِلِ أن يرسِلَ إليها ولده أضسيس (ومعناه ما له اسم) وتسمَّى بالمسعودِ صلاح الدين يوسف، فخرج في جيش كثيفٍ من مصر، وسار إلى بلاد اليمن، فاستولى على معاقلِها، وظَفِرَ بصاحبها الملك سليمان شاهنشاه, فسَيَّرَه تحت الحوطة إلى مصر، فتمَلَّك أضسيس اليمن فظَلَم بها وفتك وغشم، وقتَلَ من الأشراف نحوًا من ثمانمائة، وأمَّا من عداهم فكثير، وكان من أفجَرِ الملوك وأكثَرِهم فِسقًا وأقلِّهم حياءً ودينًا، وقد ذكروا عنه ما تقشَعِرُّ منه الأبدانُ وتُنكِرُه القلوبُ."},{"id":2386,"title":"عدوان فرنج قبرص وعكا وطرابلس وأنطاكية على المسلمين .","date":["العام الهجري :611","العام الميلادي :1214"],"text":"تجمع فرنج قبرص وعكا وطرابلس وأنطاكية، وانضم إليهم عسكرُ ابن ملك الأرمن؛ لقصد بلاد المسلمين، فخافهم المسلمون، وكان أول ما بدؤوا به بلاد الإسماعيلية، فنازلوا قلعةَ الخوابي وجدُّوا في حصارها، وكانوا حانقين على الإسماعيلية؛ بسبب قتلهم ابن البرنس صاحب أنطاكية؛ شابٍّ في الثامنة عشرة من العمر، وثبوا عليه العام الماضي فقتلوه، فخرج الملك الظاهر بعسكَرِه ليدافِعَ عن القلعة، فترحَّلت الفرنجُ ثم ساروا عنها إلى أنطاكية."},{"id":2387,"title":"القتال بين أمير المدينة النبوية وبين أمير مكة .","date":["العام الهجري :612","العام الميلادي :1215"],"text":"حاصر الأمير قتادة أميرُ مكَّةَ المدينةَ ومن بها وقطع نخلًا كثيرًا، فقاتَلَه أهلُها فكَرَّ خائبًا خاسرًا حسيرًا، وكان صاحب المدينة بالشام فطلب مِن العادل نجدةً على أمير مكة، فأرسل معه جيشًا فأسرع في الأوبة، فمات أمير المدينة في أثناء الطريق، فاجتمع الجيشُ على ابن أخيه جماز فقصَدَ مكة فالتقاه أميرُها بالصفراء فاقتتلوا قتالًا شديدًا، فهرب المكيُّون وغَنِمَ منهم جماز شيئًا كثيرًا، وهربَ قتادةُ إلى ينبع، فساروا إليه فحاصروه بها وضيَّقوا عليه."},{"id":2388,"title":"مناوشات بين الفرنج والمسلمين .","date":["العام الهجري :612","العام الميلادي :1215"],"text":"أغارت الفرنج على بلاد الإسماعيلية فقتلوا ونهبوا ثم اصطلحوا، وأخذ مَلِكُ بلاد الروم عزُّ الدين كيكاوس بن كيخسرو مدينة إنطاكية من أيدي الفرنجِ، ثم أخَذَها منه ابنُ لاون ملك الأرمن، ثم منه إبريس طرابلس، وسار عزُّ الدين إلى بلاد الأرمن، وحاصرَ قلعة جابان، وهزم عندها جيوش الأرمن، ورجع إلى قيصريَّة قبل أن يستوليَ على قلعة جابان، ثم طلب الأرمنُ الصلحَ، وأجابهم إليه عزُّ الدين، فأخذ في مقابلِ الصلح من بلاد الأرمن قلعةَ لؤلؤة ولوزاد."},{"id":2389,"title":"وفاة ولي العهد الملك المعظم أبي الحسن علي بن الخليفة الناصر .","date":["العام الهجري :612","الشهر القمري : جمادى الأولى","العام الميلادي :1215"],"text":"هو أبو الحسَنِ عليُّ بن الخليفة الناصر لدين الله أحمد بن المستضيء بأمر الله، وهو الأصغر، وكان يلقَّب الملك المعظم، وكان أحبَّ ولدي الخليفة إليه، وقد رشَّحه لولاية العهد بعده، وعزَلَ ولده الأكبر عن ولاية العهدِ؛ لأجل أبي الحسن علي, وكان كريمًا كثير الصدقة والمعروف، حَسَن السيرة، محبوبًا إلى الخاص والعام، وكان سببُ موتِه أنَّه أصابه إسهالٌ فتوفِّيَ، وحَزِنَ عليه الخليفةُ حُزنًا لم يُسمَعْ بمثله، حتى إنه انقطع، ثم أُخرجَ نهارًا، ومشى جميعُ الناس بين يدي تابوتِه إلى تربة جدَّتِه عند قبر معروف الكرخي، فدُفِنَ عندها، ولما أُدخِل التابوت أُغلِقَت الأبواب، وسُمِعَ الصراخ العظيم من داخل التربة، فقيل إن ذلك صوتُ الخليفة, وأمَّا العامة ببغداد فإنَّهم وجدوا عليه وجدًا شديدًا، ودامت المناحات عليه في أقطار بغداد ليلًا ونهارًا، ولم تبق امرأةٌ إلَّا وأظهرت الحزن، وما سُمِعَ ببغداد مثل ذلك في قديمِ الزمانِ وحديثه. وتَرَك أبو الحسن ولدينِ أحدهما المؤيَّد أبو عبد الله الحسين، والموفَّق أبو الفضل يحيى."},{"id":2390,"title":"مقتل منكلي وولاية أغملش .","date":["العام الهجري :612","الشهر القمري : جمادى الأولى","العام الميلادي :1215"],"text":"انهزم منكلي صاحب همذان وأصفهان والري وما بينهما من البلاد، ومضى هاربًا، فقُتِلَ، وسَبَبُ ذلك أنَّه كان قد ملكَ البلاد، وقتل إيدغمش فأُرسلَ إليه من الديوان الخليفي رسولٌ ينكِرُ ذلك عليه، وكان قد أوحش الأمير أوزبك بن البهلوان، صاحب أذربيجان، فأرسل الخليفةُ إليه يحَرِّضُه على منكلي ويَعِدُه النصرةَ، وأرسل أيضًا إلى جلال الدين الإسماعيلي، صاحِبِ قلاع الإسماعيلية ببلاد العجم، ألموت وغيرها، يأمرُه بمساعدة أوزبك على قتال منكلي، واستقرت القواعد بينهم على أن يكون للخليفةِ بعضُ البلاد، ولأوزبك بعضُها، ويعطى جلال الدين بعضَها، فلما استقَرَّت القواعد بينهم على ذلك جهَّزَ الخليفة عسكرًا كثيرًا، وجعل مُقَدَّمَهم مملوكَه مُظفَّر الدين سنقر، الملقب بوجه السبع، فساروا إلى همذان، فاجتمعت العساكرُ كلها فانزاح منكلي من بين أيديهم وتعلَّق بالجبال، وتبعوه، فنزلوا بسفحِ جبل هو في أعلاه بالقرب من مدينة كرج، وضاقت الميرة والأقوات على العسكر الخليفي جميعِه ومن معهم، فحَمَلوا عليه، فلم يثبُت أوزبك، ومضى منهَزِمًا، فعاد أصحابُ منكلي وصَعِدوا الجبَلَ، وعاد أوزبك إلى خيامِه، فطَمِعَ منكلي حينئذ، ونزل من الغدِ في جميع عسكرِه، واصطَفَّت العساكر للحرب، واقتتلوا أشدَّ قتال يكون، فانهزم منكلي وصعد الجبل، واستولى عسكرُ الخليفة وأوزبك على البلاد، فأعطى جلال الدين، ملك الإسماعيلية، من البلاد ما كان استقَرَّ له، وأخذ الباقي أوزبك، فسَلَّمَه إلى أغلمش مملوكِ أخيه. أمَّا منكلي فإنَّه مضى منهزمًا إلى مدينة ساوة، وبها شحنة هو صديقٌ له، فأرسل إليه يستأذنُه في الدخول إلى البلد، فأذن له، وخرج إليه فلقيه وقبَّل الأرضَ بين يديه، وأدخله البلد، وأنزله في داره، ثم أخذ سلاحَه، وأراد أن يقيِّدَه ويُرسِلَه إلى أغلمش، فسأله أن يقتُلَه هو ولا يرسلَه، فقتله، وأرسل رأسَه إلى أوزبك، وأرسله أوزبك إلى بغداد، وكان يومُ دخولها يومًا مشهودًا, ولم يتمَّ فرحة الخليفة ذلك اليوم لموت ولَدِه وولي عهده أبو الحسَنِ علي."},{"id":2391,"title":"خوارزم شاه  يمتلك مدينة غزنة وأعمالها .","date":["العام الهجري :612","الشهر القمري : شعبان","العام الميلادي :1215"],"text":"ملك خوارزم شاه محمد بن تكش مدينة غزنة وأعمالها، وسببُ ذلك أنَّ خوارزم شاه لَمَّا استولى على عامَّة خراسان وملك باميان وغيرها، أرسلَ إلى تاج الدين، صاحبِ غزنة، يطلُبُ منه أن يخطُبَ له، ويضرِبَ السِّكَّة باسمه، ويرسِلَ إليه فيلًا واحدًا ليصالِحَه ويقِرَّ بيده غزنة، ولا يعارِضه فيها، فأحضر الأمراءَ وأعيانَ دولته واستشارهم، فخطب لخوارزم شاه، وضَرَب السكة باسمِه، وأرسل إليه فيلًا، وأعاد رسولَه إليه، ومضى إلى الصيدِ، فأرسل قتلغ تكين، والي غزنة، إلى خوارزم شاه يطلبه ليسلم إليه غزنة، فسار مجِدًّا، وسبق خبَرُه، فسلم إليه قتلغ تكين غزنةَ وقلعتها، فلمَّا دخلها خوارزم شاه قتَلَ من بها من عسكر الغورية لا سيما الأتراك، وقيل: إنَّ مِلكَ خوارزم شاه غزنة كان سنة ثلاث عشرة."},{"id":2392,"title":"وقوع بَرَد شديد بالبصرة وهبوب ريح سوداء شديدة ببغداد .","date":["العام الهجري :613","الشهر القمري : محرم","العام الميلادي :1216"],"text":"وقع بالبصرة بَرَد كثير، وهو مع كثرتِه عظيمُ القَدرِ، قيل: كان أصغرُه مثل النارنجة- نوع من الليمون- الكبيرة، وقيل في أكبرِه ما يستحي الإنسانُ أن يذكُرَه، فكسر كثيرًا من رؤوسِ النخيل. وفي صفَر من نفس العام هبَّت ببغداد ريحٌ سوداءُ شديدة، كثيرةُ الغبار والقتام، وألقت رملًا كثيرًا، وقلعت كثيرًا من الشَّجَر، فخاف الناسُ وتضَرَّعوا، ودامت من العشاءِ الآخرة إلى ثلث الليل ثم انكشَفَت."},{"id":2393,"title":"وفاة الملك الظاهر غازي بن صلاح الدين صاحب حلب .","date":["العام الهجري :613","الشهر القمري : جمادى الآخرة","العام الميلادي :1216"],"text":"هو المَلِكُ الظاهر غازي بن صلاح الدين يوسف بن أيوب، وهو صاحِبُ مدينة حلب ومنبج وغيرهما من بلاد الشام، وكان مرضُه إسهالًا، وكان شديد السيرة، ضابطًا لأموره كلِّها، ولَمَّا اشتدت علتُه عهد بالملك بعده لولد له صغيرٍ اسمه محمد، ولقَّبَه الملك العزيز غياث الدين، عُمُره ثلاثُ سنين، وعدَلَ عن ولد كبير لأنَّ الصغيرَ كانت أمه ابنة عمه الملك العادل أبي بكر بن أيوب، صاحب مصر ودمشق وغيرهما من البلاد، فعَهِدَ بالملك له ليبقى عمُّه البلاد عليه، ولا ينازعه فيها، ولَمَّا عهد الظاهر إلى ولده بذلك جعل أتابكه ومربِّيَه خادمًا روميًّا، اسمه طغرل، ولقَّبَه شهاب الدين، وهو من خيارِ عبادِ الله، كثيرُ الصدقة والمعروف، ولما توفي الظاهر أحسن الأتابك شهاب الدين السيرةَ في الناس، وعدل فيهم، وأزال كثيرًا من السُّنَن الجارية، وأعاد أملاكًا كانت قد أُخذَت من أربابهِا، وقام بتربية الطفلِ أحسَنَ قيامٍ، وحَفِظَ بلاده، واستقامت الأمورُ بحُسنِ سيرته وعَدلِه."},{"id":2394,"title":"خوارزم شاه يمتلك بلد الجبل .","date":["العام الهجري :614","العام الميلادي :1217"],"text":"سار خوارزم شاه علاء الدين محمد بن تكش إلى بلاد الجَبَل فمَلَكَها، وكان سببُ حركتِه في هذا الوقت عِدَّة أمور؛ أحدها: أنه كان قد استولى على ما وراء النهر، وظَفِرَ بالخطا، وعَظُم أمره، وعلا شأنه، وأطاعه القريبُ والبعيد، ومنها: أنه كان يهوى أن يُخطَبَ له ببغداد، ويُلَقَّب بالسلطان، ومنها: أن أغلمش لَمَّا ملك بلاد الجبل خطب له فيها جميعِها، فلما قتَلَه الباطنية غَضِبَ له، وخرج لئلا تخرُجَ البلاد عن طاعته، فسار مجدًّا في عساكر تطبقُ الأرض، فوصل إلى الريِّ فملكها، وكان أتابك سعد بن دكلا، صاحِبُ بلاد فارس، لَمَّا بلغه مقتل أغلمش جمع عساكِرَه وسار نحو بلاد الجبل طمعًا في تملكها لخلوِّها عن حامٍ وممانع، فوصل إلى أصفهان، فأطاعه أهلُها، وسار منها يريد الري، ولم يعلم بقدوم خوارزم شاه، فلَقِيَه مقدمة خوارزم شاه فظَنَّها عساكر تلك الديار قد اجتمعت لقتاله ومنْعِه عن البلاد، فقاتلهم، وجَدَّ في محاربتهم حتى كاد يهزِمُهم، ثم انهزم وملك خوارزم شاه البلدَ."},{"id":2395,"title":"قدوم خوازم شاه إلى بغداد طالبا السلطنة .","date":["العام الهجري :614","العام الميلادي :1217"],"text":"قَدِمَ السلطانُ علاء الدين خوارزم شاه محمد بن تكش من همدان قاصدًا بغداد في أربعمائة ألف مقاتل، وقيل في ستمائة ألف، فاستعَدَّ له الخليفة واستخدم الجيوَش وأرسل إلى الخليفةِ يطلُبُ منه أن يكون بين يديه على قاعدةِ مَن تقَدَّمه من الملوك السلاجقة، وأن يَخطُبَ له ببغداد، فلم يجِبْه الخليفة إلى ذلك، وأرسل إليه الشيخ شهاب الدين السهروردي، فلما وصل شاهدَ عند خوارزم شاه من العظمةِ وكثرة الملوك بين يديه وأخذَ السهروردي في خطبةٍ هائلة فذكر فيها فضلَ بني العباس وشرَفَهم، والترجمان يعيد على السلطانِ خوارزم شاه، فقال السلطانُ أمَّا ما ذكرتَ مِن فضل الخليفة فإنَّه ليس كذلك، ولكني إذا قَدِمتُ بغداد أقمتُ من يكون بهذه الصِّفة، وانصرف السهروردي راجعًا، وأرسل الله تعالى على خوارزم شاه وجنده ثلجًا عظيمًا ثلاثة أيام حتى طَمَّ الخيامَ والخراكي -لفظ فارسيٌّ يعني بيتًا من الخشب- ووصل إلى قريب رؤوس الأعلام، وتقطَّعت أيدي رجالٍ وأرجُلُهم، وعَمَّهم من البلاء ما لا يُحَدُّ ولا يوصف، فمات كثيرٌ من الدواب والرجال، فلم يحقِّق خوارزم شاه ما جاء لأجلِه، وخاف أن يتغلَّب التَّترُ على بلاده؛ إذ قد بدأوا بالتحرُّك، فرجع إلى بلاده!"},{"id":2396,"title":"انقضاء الهدنة مع الفرنج وغزوهم بلاد الشام .","date":["العام الهجري :614","العام الميلادي :1217"],"text":"وصلت أمداد الفرنج في البحر من روميَّة الكبرى وغيرها من بلاد الفرنج في الغرب والشمال، إلَّا أن المتولي لها كان صاحب رومية؛ لأنَّه يتنزل عند الفرنج بمنزلة عظيمةٍ، لا يرون مخالفةَ أمره ولا العُدولَ عن حُكِمهِ فيما سَرَّهم وساءهم، فجهَّز العساكرَ مِن عنده مع جماعةٍ مِن مقَدَّمي الفرنج، وأمَرَ غيرَه من ملوكِ الفرنج إمَّا أن يسير بنفسِه، أو يرسِلَ جيشًا، ففعلوا ما أمَرَهم، فاجتمعوا بعكَّا من ساحل الشام، وكان الملك العادلُ أبو بكر بن أيوب بمصر، فسار منها إلى الشامِ، فوصل إلى الرملة، ومنها إلى لد، وبرز الفرنج من عكَّا ليقصدوه، فسار العادلُ نحوَهم، فوصل إلى نابلس عازمًا على أن يسبِقَهم إلى أطراف البلاد ممَّا يلي عكا ليحميَها منهم، فساروا هم فسَبَقوه، فنزل على بيسان من الأردن، فتقدَّم الفرنجُ إليه في شعبان عازمينَ على محاربته؛ لعلمهم أنَّه في قلة من العسكر، لأنَّ العساكِرَ كانت متفرقةً في البلاد، فلمَّا رأى العادلُ قُربَهم منه لم يرَ أن يلقاهم في الطائفةِ التي معه، خوفًا من هزيمة تكونُ عليه، وكان حازمًا كثير الحذر، ففارق بيسان نحو دمشق ليُقيمَ بالقرب منها، ويرسِلَ إلى البلاد ويجمعَ العساكر، فوصل إلى مرج الصفر فنزل فيه، فأخذ الفرنجُ كلَّ ما في بيسان من ذخائِرَ قد جُمِعَت، وكانت كثيرةً، وغنموا شيئًا كثيرًا، ونَهَبوا البلاد من بيسان إلى بانياس، وبثوا السرايا في القرى فوصلت إلى خسفين، ونوى وأطراف البلاد، ونازلوا بانياس، وأقاموا عليها ثلاثة أيام، ثم عادوا عنها إلى مرج عكا، ومعهم من الغنائم والسبي والأسرى ما لا يحصى كثرةً، سوى ما قتلوا وأحرقوا وأهلكوا، فأقاموا أيامًا استراحوا خلالها، ثم جاؤوا إلى صور، وقَصَدوا بلد الشقيف، ونزلوا بينهم وبين بانياس مقدار فرسخين، فنهبوا البلاد: صيدا والشقيف، وعادوا إلى عكا، وكان هذا من نصف رمضان إلى العيد، والذي سَلِمَ من تلك البلاد كان متخفيًا حتى قَدَر على النجاة، ولما نزل العادِلُ على مرج الصفر سيَّرَ ولده الملك المعظم عيسى، وهو صاحِبُ دمشق في قطعةٍ صالحة من الجيش إلى نابلس ليمنَعَ الفرنجَ عن بيت المقدس."},{"id":2397,"title":"حصر الفرنج قلعة الطور وتخريبها .","date":["العام الهجري :614","العام الميلادي :1217"],"text":"لما نزل الفرنج بمرج عكَّا تجَّهزوا، وأخذوا معهم آلةَ الحصار من مجانيقَ وغيرها، وقصدوا قلعةَ الطور، وهي قلعةٌ منيعة على رأس جبلٍ بالقرب من عكا العادل قد بناها عن قريبٍ، فتقدموا إليها وحصروها وزحفوا إليها، وصَعِدوا في جبلها حتى وصلوا إلى سورها، وكادوا يملِكونه، فاتَّفق أن بعض المسلمين ممَّن فيها قتَل بعضَ ملوكهم، فعادوا عن القلعة فتركوها، وقصدوا عكَّا، وكانت مدة مُقامهم على الطور سبعة عشر يومًا، ولَمَّا فارقوا الطور أقاموا قريبًا، ثم ساروا في البحرِ إلى ديار مصر، فتوجَّه الملك المعظَّم إلى قلعة الطورِ فخَرَّبها إلى أن ألحَقَها بالأرض؛ لأنَّها بالقُربِ مِن عكا ويتعَذَّر حِفظُها."},{"id":2398,"title":"قيام فتنة ببغداد بين أهل المأمونية وبين أهل باب الأزج .","date":["العام الهجري :614","الشهر القمري : محرم","العام الميلادي :1217"],"text":"وقعت ببغداد فتنة بين أهل المأمونية وبين أهل باب الأزج بسبب قتل سبع؛ وزاد الشرُّ بينهم، واقتتلوا، فجُرح بينهم كثير، فحضر نائبُ الباب وكفَّهم عن ذلك، فلم يقبلوا ذلك، وأسمعوه ما يكرَهُ، فأُرسِل من الديوان أميرٌ من مماليك الخليفة، فرَدَّ أهل كل محلَّة إلى محلَّتِهم، وسكنت الفتنةُ."},{"id":2399,"title":"قصد كيكاوس ولاية حلب .","date":["العام الهجري :615","العام الميلادي :1218"],"text":"سار عز الدين كيكاوس بن كيخسرو ملك بلاد الروم إلى ولاية حلب؛ قصدًا للتغلُّب عليها، ومعه الأفضلُ بن صلاح الدين يوسف، حيث كان أشار عليه ذوو الرأيِ من أصحابه، وقالوا له: لا يتِمُّ لك هذا إلا بأن يكون معك أحدٌ من بيت أيوب لِيسهلَ على أهل البلاد وجُندِها الانقياد إليه؛ وهذا الأفضَلُ بن صلاح الدين هو في طاعتك، فأحضر الأفضل من سميساط إليه، واستقَرَّت القواعد بينهما أن يكون ما يفتحه من حلب وأعمالها للأفضل، وهو في طاعة كيكاوس، والخطبة له في ذلك أجمع، ثم يقصِدون ديارَ الجزيرة، فما يفتحونَه مِمَّا بيد الملك الأشرف مثل: حران والرَّها من البلاد الجزرية، تكون لكيكاوس، وجرت الأيمانُ على ذلك، وجمعوا العساكِرَ وساروا، فملكوا قلعة رغبان، فتسَلَّمَها الأفضل، فمال الناسُ حينئذ إليهما، ثم سارا إلى قلعةِ تل باشر، وفيها صاحِبُها ولَدُ بدر الدين دلدرم الياروقي، فحصروه، وضَيَّقوا عليه، وملكوها منه، فأخذها كيكاوس لنفسِه، ولم يسَلِّمها إلى الأفضل، فاستشعر الأفضَلُ من ذلك، وقال: هذا أوَّلُ الغدر، وخاف أنَّه إن ملك حلب يفعل به هكذا، فلا يحصُلُ إلَّا أن يكون قد قلع بيتَه لغيره، ففترت نيَّتُه، وأعرض عمَّا كان يفعله، وكذلك أيضًا أهل البلاد، وأما صاحِبُ حلب فلما حدث هذا الأمر خاف أن يحصُروه، وربَّما سَلَّم أهلُ البلد والجند المدينةَ إلى الأفضل لمَيلِهم إليه، فأرسل إلى المَلِك الأشرف بن الملك العادل، صاحبِ الديار الجزرية وخلاط وغيرها، يستدعيه إليه لتكونَ طاعتُهم له، ويخطُبون له، ويجعل السكةَ باسمه، ويأخُذ من أعمال حلب ما اختار، فجمع عسكَرَه وأحضر إليه العربَ من طيئ وغيرهم، ونزل بظاهِرِ حلب، ولما أخذ كيكاوس تل باشر كان الأفضَلُ يشير بمعاجلة حلب قبل اجتماعِ العساكر بها، وقبل أن يحتاطوا ويتجَهَّزوا، فعاد عن ذلك، وصار يقولُ: الرأي أننا نقصد منبج وغيرها؛ لئلا يبقى لهم وراء ظهورِنا شيء، قصدًا للتمادي فتوجَّهوا من تل باشر إلى جهة منبج، وتقدَّم الأشرف نحوهم، وسارت العربُ في مقدِّمته، وكان طائفة من عسكر كيكاوس، نحو ألف فارس، قد سبقت مقدمته له، فالتقوا هم والعربُ ومن معهم من العسكر الأشرفي، فاقتتلوا، فانهزم عسكر كيكاوس، وعادوا إليه منهزمينَ، وأكثر العرب الأسرَ منهم والنهبَ؛ لجودة خيلهم ودبر خيل الرومِ، فلما وصل إليه أصحابُه منهزمين لم يثبت، بل ولى على أعقابِه يطوي المراحِلَ إلى بلاده خائفًا يترقَّبُ، فلما وصل إلى أطرافها أقام، فسار حينئذ الأشرف، فملك رغبان، وحصر تل باشر، وبها جمعٌ مِن عسكر كيكاوس، فقاتلوه حتى غُلِبوا، فأُخِذَت القلعة منهم، وأطلَقهم الأشرف، وسَلَّم الأشرف تل باشر وغيرها من بلد حلب إلى شهابِ الدين أتابك، صاحب حلب، وكان عازمًا على اتباعِ كيكاوس، ودخول بلاده، فأتاه الخبَرُ بوفاة أبيه الملك العادل، فاقتضت المصلحةُ العودَ إلى حلب."},{"id":2400,"title":"حصر الفرنج دمياط  .","date":["العام الهجري :615","العام الميلادي :1218"],"text":"لما عاد الفرنجُ من حصار الطور أقاموا بعكَّا إلى أن دخلت هذه السَّنةُ، فساروا في البحرِ إلى دمياط، فوصَلوا في صفر، فأرسوا على بر الجيزة، بينهم وبين دمياط النيل، فإنَّ بعض النيل يصب في البحر المالح عند دمياط، وقد بني في النيل برجٌ كبير منيع، وجعلوا فيه سلاسِلَ من حديد غلاظ، ومدُّوها في النيل إلى سورِ دمياط لتَمنَعَ المراكِبَ الواصلة في البحرِ المالح أن تصعَدَ في النيل إلى ديار مصر، ولولا هذا البرجُ وهذه السلاسل لكانت مراكِبُ العدو لا يقدِرُ أحَدٌ على مَنعِها عن أقاصي ديارِ مِصرَ وأدانيها، فلمَّا نزل الفرنجُ على بر الجيزة، وبينهم وبين دمياط النيل، بَنَوا عليه سورًا، وجعلوا خندقًا يمنعُهم من يريدهم، وشرعوا في قتال من بدمياط، وعملوا آلات ومرمات، وأبراجًا متحركة يزحفون بها في المراكب إلى البرج الذي في النيل ليقاتلوه ويملكوه، وكان البرجُ مشحونًا بالرجال، وقد نزل الملك الكامِلُ بن الملك العادل، وهو صاحِبُ ديار مصر، بمنزلة تُعرَفُ بالعادلية، بالقرب من دمياط، والعساكِرُ متصلة من عنده إلى دمياط، ليمنع العدُوَّ من العبور إلى أرضهم، وأدام الفرنجُ قتال البرج وتابعوه، فلم يظفروا منه بشيءٍ، وكُسِرَت مرماتهم وآلاتهم، ومع هذا فهم ملازمون لقتاله، فبَقُوا كذلك أربعة أشهر، ولم يقدروا على أخذه، ثم تمكنوا من أخذه فقطعوا السلاسِلَ لتدخُلَ مراكبُهم من البحر المالح في النيل ويتحكموا في البر، فنصب الملك الكامِلُ عِوَضَ السلاسلِ جسرًا عظيمًا امتنعوا به من سلوكِ النيل، ثم إنهم قاتلوا عليه أيضًا قتالًا شديدًا، كثيرًا، متتابعًا حتى قطعوه، فلما قطع أخذ الملكُ الكامل عدَّةَ مراكب كبار وملأها وخرَقَها وغَرَقها في النيل، فمَنَعت المراكِبَ من سلوكه، فلما رأى الفرنج ذلك قصدوا خليجًا هناك يُعرَف بالأزرق، كان النيل يجري فيه قديمًا، فحفروا ذلك الخليج وعَمَّقوه فوق المراكبِ التي جُعِلَت في النيل، وأجروا الماء فيه إلى البحر المالحِ، وأصعدوا مراكِبَهم فيه إلى موضعٍ يقال له بورة، على أرض الجيزة أيضًا، مقابل المنزلةِ التي فيها الملك الكامل ليقاتلوه من هناك، فإنَّهم لم يكن لهم إليه طريقٌ يقاتلونه فيها، كانت دمياط تحجز بينهم وبينه، فلما صاروا في بورة حاذوه فقاتلوه في الماء، وزحفوا غيرَ مَرَّة، فلم يظفروا بطائل، ولم يتغيَّرْ على أهل دمياط شيءٌ؛ لأن الميرة والأمداد متَّصلة بهم، والنيلُ يحجُز بينهم وبين الفرنج، فهم ممتَنِعون لا يصلُ إليهم أذى، وأبوابُها مفتحة، وليس عليها من الحَصرِ ضِيقٌ ولا ضرر."},{"id":2401,"title":"وفاة الملك القاهر صاحب الموصل وتملك ولده بعده .","date":["العام الهجري :615","الشهر القمري : ربيع الأول","العام الميلادي :1218"],"text":"هو المَلِكُ القاهر عزُّ الدين مسعود بن أرسلان شاه بن مسعود بن مودود بن زنكي بن آقسنقر، صاحِبُ الموصل، توفِّيَ ليلة الاثنين لثلاثٍ بقِينَ من شهر ربيع الأول، وكانت ولايتُه سبع سنين وتسعة أشهر، وكان سبب موته أنَّه أخذته حمى، ثم فارقته الغد، وبقي يومينِ موعوكًا، ثم عاودته الحُمَّى مع قيءٍ كثير، وكربٍ شديد، وقلق متتابعٍ، ثم برد بدَنُه، وعَرقَ، وبَقِيَ كذلك إلى وسط الليل، ثم توفِّيَ، وقيل مات مسمومًا، وكان لما حضرته الوفاة أوصى بالملك لولدِه الأكبر نور الدين أرسلان شاه، وعُمُره حينئذ نحو عشر سنين، وجعل الوصيَّ عليه والمدبِّر لدولته بدر الدين لؤلؤًا، وهو الذي كان يتولى دولة القاهر ودولة أبيه نور الدين قبله، فلما قضى نحبَه قام بدر الدين بأمر نور الدين، وأجلسه في مملكةِ أبيه، وأرسل إلى الخليفةِ يطلب له التقليدَ والتشريف، وأرسل إلى الملوك، وأصحاب الأطراف المجاورين لهم، يطلبُ منهم تجديد العهد لنور الدين على القاعدةِ التي كانت بينهم وبين أبيه، فلم يصبِحْ إلَّا وقد فرغ من كل ما يحتاج إليه، وجلس للعزاء، وحَلَف الجند والرعايا، وضبط المملكة، وبعد أيامٍ وصل التقليد من الخليفة لنور الدين بالولاية، ولبدر الدين بالنظرِ في أمر دولته، والتشريفات لهما أيضًا، وأتتهما رسلُ الملوك بالتعزية، وبذل ما طلب منهم من العهود، واستقَرَّت القواعد لهما. ثم تغلب بدر الدين لؤلؤ على الموصِلِ، وملكها 40 سنة، وكان من قبلُ نائبًا بها ثم استَقَلَّ بالسلطنة وتلَقَّب بالملك الرَّحيم."},{"id":2402,"title":"وفاة أم المؤيد زينب بنت الشعري\n  .","date":["العام الهجري :615","الشهر القمري : جمادى الآخرة","العام الميلادي :1218"],"text":"هي أم المؤيد زينبُ بنت أبي القاسم عبد الرحمن بن الحسن بن أحمد بن سهل بن أحمد بن عبدوس الجرجاني الأصل النيسابوري الدار، الصوفي المعروف بالشعري- وتدعى حرة- وُلِدَت سنة 524 بنيسابور، وكانت عالمة، وأدركت جماعة من أعيان العلماء، وأخذت عنهم رواية وإجازة. سمعت من أبي محمد إسماعيل بن أبي القاسم ابن أبي بكر النيسابوري القارئ، وأبي القاسم زاهر وأبي بكر وجيه ابني طاهر الشحاميين، وأبي المظفر عبد المنعم بن عبد الكريم بن هوازن القشيري، وأبي الفتوح عبد الوهاب بن شاه الشاذياخي وغيرهم، وأجاز لها الحافظ أبو الحسن عبد الغافر بن إسماعيل بن عبد الغافر الفارسي، والعلامة أبو القاسم محمود ابن عمر الزمخشري صاحب \" الكشاف \" وغيرهما من السادات الحُفَّاظ. قال ابن خلكان: \"ولنا منها إجازة كتبتها في بعض شهور سنة 610، ومولدي يوم الخميس بعد صلاة العصر حادي عشر شهر ربيع الآخر سنة 608 بمدينة إربل بمدرسة سلطانها الملك المعظم مظفر الدين بن زين الدين\" توفيت الحرة سنة 615 في جمادى الآخرة بمدينة نيسابور\" قال الذهبي: \"حدثت أم المؤيد أكثر من ستين سنة، روى عنها: عبد العزيز بن هلالة، وابن نقطة، والبرزالي، والضياء، وابن الصلاح، والشرف المرسي، والصريفيني، والصدر البكري، ومحمد بن سعد الهاشمي، والمحب ابن النجار، وجماعة كثيرة. وسمعت بإجازتها على التاج بن عصرون، والشرف بن عساكر، وزينب الكندية. وكانت شيخة صالحة، عالية الإسناد معمرة، مشهورة، انقطع بموتها إسناد عال\". قال ابن خلكان: \"الشَّعْري بفتح الشين المثلثة وسكون العين المهملة وفتحها وبعدها راء، هذه النسبة إلى الشعر وعمله وبيعه، ولا أعلم من كان في أجدادها يتعاطاه فنسبوا إليه، والله أعلم\"."},{"id":2403,"title":"وفاة الملك العادل سيف الدين أبو بكر الأيوبي .","date":["العام الهجري :615","الشهر القمري : جمادى الآخرة","العام الميلادي :1218"],"text":"هو الملك العادل سيف الدين أبو بكر محمد بن أبي الشكر أيوب بن شاذي بن يعقوب بن مروان الدويني، ثم التكريتي، ثم الدمشقي. وُلِدَ ببعلبك في سنة 534، وهو أصغَرُ من أخيه السلطان صلاح الدين بسنتين. وقيل: وُلِدَ بدمشق سنة ثمان وثلاثين. وقيل: ولد سنة أربعين. وهو أحد ملوك الدولة الأيوبية. لما ملك صلاح الدين الديار المصرية كان العادل ينوب عنه في حال غيبته في الشام، ويستدعي منه الأموال للإنفاق على الجند وغيرهم. ولَمَّا ملك صلاح الدين مدينة حلب سنة 579 أعطاها لولده الملك الظاهِرِ غازي، ثم أخذها منه، وأعطاها للملك العادل، ثم نزل عنها للملك الظاهر غازي لمصلحةٍ وقع الاتِّفاقُ عليها بينه وبين أخيه صلاح الدين. وآخر الأمر استقل العادل بمصر سنة 596 واستقَرَّت له القواعد، ثم خُطِبَ له بحلب سنة 598, وملك معها البلادَ الشامية والشرقيَّة، ثم ملك اليمن سنة 612، وسيَّرَ إليها ابنه الملك المسعود صلاح الدين. قال أبو شامة: \"عاش العادلُ ستا وسبعين سنة. نشأ في خدمة نور الدين محمود مع أبيه، وإخوته. وحضر مع أخيه صلاح الدين فتوحاتِه. وقام أحسنَ قيام في الهدنة مع ملك الفرنج بعد أخذهم عكَّا. وكان صلاح الدين يعَوِّلُ عليه كثيرًا، واستنابه بمصر مدة\" ملك العادِلُ من بلاد الكرج إلى قريب همذان، والشام، والجزيرة، ومصر، والحجاز، واليمن، إلى حضرموت. وقد أبطل كثيرًا من الظلم والمكوس. ولما تمهدت له البلاد قسمَها بين أولاده، فأعطى الملك الكامل الديار المصريَّة، والملك المعظم البلاد الشامية، والملك الأشرف البلاد الشرقية، والملك الأوحد نجم الدين أيوب ميافارقين وتلك النواحي، وكان يتردد بينهم وينتقل إليهم من مملكةٍ إلى أخرى, وقد كان ملكًا عظيمًا ذا رأي ومعرفة تامةٍ قد حنكته التجاربُ، حسن السيرة، جميل الطوية، فيه حِلمٌ وأناة وصبر على الشدائد، وكان سعيد الجد، عاليَ الكعب، مظفرًا بالأعداء وافِرَ العقل، حازمًا في الأمور صالحًا محافظًا على الصلوات في أوقاتها، مائلًا إلى العلماء. قال أبو المظفر سبط ابن الجوزي: \"كان خليقًا بالملك، حسنَ التدبير، حليمًا، صفوحًا، مجاهدًا، عفيفًا، دَيِّنًا، متصدقًا، آمرًا بالمعروف، ناهيًا عن المنكر طهر جميع ولايته من الخمور، والخواطئ، والمكوس، والمظالم\". قال الموفق عبد اللطيف في سيرة العادل: \"كان أصغر إخوته، وأطولهم عمرًا، وأعمقهم فكرًا، وأنظرهم في العواقب، وأشدهم إمساكًا، وأحبهم للدرهم\". قال ابن كثير: \"كان العادل حليمًا صفوحًا صبورًا على الأذى كثير الجهاد بنفسه ومع أخيه، حضر معه مواقفه كلها أو أكثرها في مقاتلة الفرنج، وكانت له في ذلك اليد البيضاء، وكان ماسك اليد، وقد أنفق في عام الغلاء بمصر أموالًا كثيرة على الفقراء وتصدق على أهل الحاجة من أبناء الناس وغيرهم شيئًا كثيرًا جِدًّا، ثم إنه كفل بعد عام الغلاء مائة ألف إنسان من الغرباء والفقراء، وكان كثير الصدقة في أيام مرضه، حتى كان يخلع جميع ما عليه ويتصَدَّق به وبمركوبه، وكان كثير الأكل ممتعًا بصحة وعافية مع كثرة صيامِه\" لما ظهر الفرنج، سنة أربع عشرة وستمائة، قصد هو مرج الصفر، فلما سار الفرنج إلى ديار مصر انتقل هو إلى عالقين، فأقام به، ومرض، وتوفي في سابع جمادى الآخرة، وحمل إلى دمشق، فدُفن بالتربة التي له بها، وكانت مدة ملكه عشرين سنة إلا ثلاثة أشهر، وكان العادل قد قسم البلاد في حياته بين أولاده، فلما توفي ثبت كلٌّ منهم في المملكة التي أعطاه أبوه، واتفقوا اتفاقًا حسنًا لم يجرِ بينهم من الاختلاف شيءٌ، ثم إن ابنه الكامل محمد تملك مصر بعده وقد كان أبوه أعطاه إياها وأكمل بعده قتال الفرنج."},{"id":2404,"title":"القتال بين جنكيزخان وخوارزم شاه في بلاد ما وراء النهر .","date":["العام الهجري :616","العام الميلادي :1219"],"text":"كان سبب غزو جنكيز خان لِما وراءَ النَّهرِ هو أن خوارزم شاه محمد قد بدأ يأخذ أموال التجار الذين من طرف جنكيز خان ثم زاد الأمرُ أن قتل سفير جنكيز نفسه الذي جاء من أجل إعادة تلك الأموال، فأثار ذلك غضب جنكيز الذي جهز العساكِرَ من فوره، وانطلق إلى خوارزم شاه فوقع بينهما ما وقع."},{"id":2405,"title":"هزيمة عماد الدين زنكي بن مودود من العسكر البدري .","date":["العام الهجري :616","الشهر القمري : محرم","العام الميلادي :1219"],"text":"كان عسكر البدري يحاصر العماديَّة وبها عمادُ الدين زنكي بن مودود، فلمَّا عاد العسكرُ عنها قَوِيَت نفسُه وفارقها، وعاد إلى قلعة العقر التي له ليتسَلَّط على أعمال المَوصِل بالصحراء، فإنَّه كان قد فرغ من بلدِ الجبل، وأمدَّه مظفر الدين بطائفةٍ كثيرة من العسكَر. ولَمَّا اتَّصل الخبَرُ ببدر الدين لؤلؤ أتابك صاحِبِ الموصل سيَّرَ طائفةً من عسكره إلى أطراف الموصِل يحمونَها، فأقاموا على أربعة فراسخ من الموصل، ثمَّ إنهم اتَّفقوا بينهم على المسير إلى زنكي، وهو عند العقر في عسكره، ومحاربته، ففعلوا ذلك، ولم يأخذوا أمرَ بدر الدين بل أعلموه بمسيرِهم جريدة ليس معهم إلَّا سلاحهم، ودواب يقاتلون عليها، فساروا ليلتَهم، وصبَّحوا زنكي بكرة الأحد لأربع بقين من المحرم من سنة 616، فالتقوا واقتتلوا تحت العقر، وعظُم الخطب بينهم، فانتصر العسكرُ البدري، وانهزم عماد الدين وعسكرُه، وسار إلى إربل منهزمًا، وعاد العسكرُ البدري إلى منزلته التي كان بها، وحضرت الرسلُ من الخليفة الناصر لدين الله ومِن المَلِك الأشرف في تجديد الصلح، فاصطلحوا، وتحالفوا بحضور الرسُل."},{"id":2406,"title":"ظهور المغول التتر وقتالهم مع المسلمين .","date":["العام الهجري :616","الشهر القمري : صفر","العام الميلادي :1219"],"text":"ظهر التترُ إلى بلاد الإسلام، وهم نوع كثير من الترك، ومساكنُهم جبالُ طمغاج من نحو الصين، وكان السبب في ظهورِهم أنَّ مَلِكَهم- ويسمى بجنكيزخان، المعروف بتموجين- كان قد فارق بلاده وسار إلى نواحي تركستان، وسيَّرَ جماعة من التجار والأتراك، ومعهم شيءٌ كثير من النقرة- قطع مذابةُ من الذَّهب أَو الفِضَّة- وغيرِها، إلى بلاد ما وراء النهر سمرقند وبخارى؛ ليشتروا له ثيابًا للكسوة، فوصلوا إلى مدينة من بلاد الترك تسمى أوترا، وهي آخرُ ولاية خوارزم شاه محمد، وكان له نائب هناك، فلما ورد عليه هذه الطائفةُ مِن التَّتَر أرسل إلى خوارزم شاه يُعلِمُه بوصولهم ويذكُرُ له ما معهم من الأموالِ، فبعث إليه خوارزم شاه يأمُرُه بقتلِهم وأخْذِ ما معهم من الأموالِ وإنفاذِه إليهم، فقتلهم، وسيَّرَ ما معهم، وكان شيئًا كثيرًا، فلمَّا وصل إلى خوارزم شاه فرَّقه على تجار بخارى، وسمرقند، وأخذ ثمَنَه منهم، وكان بعد أن ملك ما وراء النهر من الخطا قد سدَّ الطرقَ عن بلاد تركستان وما بعدها من البلادِ، وإنَّ طائفةً من التتر أيضًا كانوا قد خرجوا قديمًا والبلادُ للخطا، فلمَّا ملك خوارزم شاه البلادَ بما وراء النهر من الخطا، قتَلَهم. استولى التتَرُ على تركستان: كاشغر، وبلاساغون وغيرهما، وصاروا يحاربونَ عساكِرَ خوارزم شاه، فلذلك منعَ الميرة عنهم من الكسوات وغيرها، فلما قتَلَ نائبُ خوارزم شاه أصحابَ جنكيزخان أرسل جواسيس إلى جنكيزخان لينظُرَ ما هو، وكم مقدارُ ما معه من الترك، وما يريدُ أن يعمل، فمضى الجواسيسُ، وسلكوا المفازةَ والجبال التي على طريقِهم، حتى وصلوا إليه، فعادوا بعد مدَّةٍ طويلة وأخبَروه بكثرةِ عَدَدِهم، وأنَّهم يخرجون عن الإحصاء، وأنَّهم من أصبر خلقِ الله على القتال لا يعرفونَ هزيمةً، وأنهم يعملون ما يحتاجون إليه من السلاحِ بأيديهم، فندم خوارزم شاه على قَتلِ أصحابهم وأخْذِ أموالهم، وكان جنكيزخان قد سار إلى تركستان، فملكها، وأزال عنها التترَ الأولى، فلم يظهر لهم خبَرٌ، ولا بقي لهم أثر، بل بادوا كما أصاب الخطا، وتجهز خوارزم شاه، وسار مبادرًا ليسبِقَ خبره ويكبِسَهم، فأدمن السير، فمضى، وقطع مسيرة أربعة أشهر، فوصل إلى بيوتهم، فلم يرَ فيها إلا النِّساءَ والصبيان والأثقال، فأوقع بهم وغنم الجميع، وسبى النساء والذرية، وكان سببُ غيبة الكفار عن بيوتهم أنَّهم ساروا إلى محاربة ملك من ملوك الترك يقال له كشلوخان، فقاتلوه، وهزموه، وغَنِموا أمواله وعادوا، فلَقِيَهم في الطريق الخبر بما فعل خوارزم شاه بمخَلَّفيهم، فجدُّوا السير، فأدركوه قبل أن يخرجَ عن بيوتهم، وتصافُّوا للحرب، واقتتلوا قتالًا لم يُسمَعْ بمثله، فبَقُوا في الحرب ثلاثة أيام بلياليها، فقُتِلَ من الطائفتين ما لا يُعَدُّ، ولم ينهزم أحد منهم، أما المسلمون فإنهم صبروا حميَّةً للدين، وعلموا أنهم إن انهزموا لم يبقَ للمسلمين باقية، وأنهم يؤخَذون لبُعدِهم عن بلادهم، وأما الكفَّار فصبروا لاستنقاذ أهليهم وأموالهم، واشتدَّ بهم الأمر، حتى إنَّ أحدهم كان ينزل عن فرسِه ويقاتل قرنَه رَجِلًا، ويتضاربون بالسكاكين، وجرى الدمُ على الأرض، حتى صارت الخيلُ تزلق من كثرته، واستنفذ الطائفتان وُسعَهم في الصبر والقتال، هذا القتالُ جميعه مع ابن جنكيزخان ولم يحضُر أبوه الوقعة، ولم يشعرْ بها، فأحصِيَ من قتل من المسلمين في هذه الوقعة فكانوا عشرين ألفًا، وأما من الكفَّار فلا يحصى من قُتِل منهم، فلما كان الليلة الرابعة افترقوا، فنزل بعضُهم مقابل بعض، فلما أظلم الليلُ أوقد الكفار نيرانهم وتركوها بحالها وساروا، وكذلك فعل المسلمون أيضًا، كل منهم سَئِمَ القتال؛ فأما الكفار فعادوا إلى مَلِكهم جنكيزخان؛ وأما المسلمون فرجعوا إلى بخارى، فاستعدَّ صاحبها للحصار لعلمه بعجزه؛ لأنَّ طائفة عسكره لم يقدر على أن يظفَرَ بالتتر، فكيف إذا جاؤوا جميعُهم مع ملكهم؟ فأمر أهل بخارى وسمرقند بالاستعداد للحصار، وجمعَ الذخائرَ للامتناع، وجعلَ في بخارى عشرين ألف فارس من العسكر يحمونَها، وفي سمرقند خمسين ألفًا، وقال لهم: احفظوا البلد حتى أعود إلى خوارزم وخراسان وأجمع العساكر وأستنجد بالمسلمين وأعود إليكم."},{"id":2407,"title":"وفاة الملك المنصور قطب الدين محمد بن زنكي وملك ابنه .","date":["العام الهجري :616","الشهر القمري : صفر","العام الميلادي :1219"],"text":"هو الملك المنصور قطب الدين محمد بن زنكي بن مودود بن عماد الدين زنكي، صاحب سنجار، وكان كريمًا، حسنَ السيرة في رعيته، حسَنَ المعاملة مع التجَّار، كثيرَ الإحسان إليهم، وأمَّا أصحابه فكانوا معه في أرغد عيش؛ يعُمُّهم بإحسانه، ولا يخافون أذاه، وكان عاجزًا عن حفظ بلده، مسلِّمًا الأمورَ إلى نوابه, ولما توفِّيَ قطب الدين مَلَك بعده ابنُه عماد الدين شاهنشاه، وركب الناسُ معه، وبقي مالكًا لسنجار عدةَ شهور، وسار إلى تل أعفر، وهي له، فدخل عليه أخوه عمر بن محمد بن زنكي، ومعه جماعة، فقتلوه، وملك أخوه عمر بعده فبَقيَ كذلك إلى أن سَلَّم سنجار إلى الملك الأشرف، ولم يمتَّع بملكه الذي قطع رحمه، وأراق الدم الحرام لأجله, ولَمَّا سلم سنجار أخذ عِوَضَها الرقَّةَ، ثم أُخِذَت منه عن قريب، وتوفِّيَ بعد أخذها منه بقليلٍ."},{"id":2408,"title":"وفاة الحافظ أبو الحسن بن عساكر .","date":["العام الهجري :616","الشهر القمري : جمادى الأولى","العام الميلادي :1219"],"text":"هو أبو الحسن علي بن أبي محمد القاسم بن علي بن الحسن بن عبد الله الدمشقي، الحافِظُ بن الحافظ بن الحافظ، المعروف بابن عساكر، وكان قد قصد خراسانَ وسَمِعَ بها الحديثَ فأكثر، وعاد إلى بغداد، وكان قد وقع على القفل- الحمل- الذي هو فيه، في الطريق حرامية، وجرحوا ابن عساكر، ووصل على تلك الحال إلى بغداد، وبقي بها حتى توفي في هذه السنة في جمادى الأولى."},{"id":2409,"title":"الصليبيون يحتلون دمياط (الحملة الصليبية الخامسة) .","date":["العام الهجري :616","الشهر القمري : شعبان","العام الميلادي :1219"],"text":"تعتبر هذه الهجمة هي الحملة الصليبية الخامسة على المسلمين؛ حيث اجتمع رأي الفرنج على الرحيل من عكا إلى مصر، والاجتهاد في تملُّكِها، فأقلعوا في البحر، وأرسَوا على دمياط، في يوم الثلاثاء رابع شهر ربيع الأول سنة 515 على بر جيزة دمياط، وصار الفرنجُ في غربي النيل، فأحاطوا على معسكَرِهم خندقًا، وبنوا بدائره سورًا، وأخذوا في محاربة أهل دمياط، وعملوا آلات ومرمات، وأبراجًا متحركة يزحفون بها في المراكب إلى برج السلسلة ليملكوه، حتى يتمكَّنوا من البلد، والملك العادل يجهِّز عساكر الشام شيئًا بعد شيء إلى دمياط، حتى صار عند الكامل من المقاتلة ما لا يكاد ينحصر عددُه، هذا والعادل بمرج الصفر، فبينا هو في الاهتمام بأمر الفرنج، إذ ورد عليه الخبر بأخذ الفرنج برج السلسلة بدمياط، فمَرِضَ من ساعته، فرحل من المرج إلى عالقين، وقد اشتد مرضه، فمات في سابع جمادى الآخرة يوم الخميس من هذه السنة، وكان الكاملُ قد بعث إلى الآفاق سبعين رسولًا، يستنجد أهل الإسلام على قتال الفرنج، فقَدِمَت النجدات من حماة وحلب، إلا أنه لما قدم على المعسكر موت العادل وقع الطمعُ في الملك الكامل، وثار العربُ بنواحي أرض مصر، وكثر خلافهم واشتد ضَرَرُهم، وصار من الخلاف ما حرض الفرنجَ على التحرك، فضعفت نفوس الناس لأنَّه السلطان حقيقة، وأولاده وإن كانوا ملوكًا إلا أنه يحكُمُهم، والأمر إليه، وهو ملك البلاد، فاتفق موته والحالُ هكذا من مقاتلة العدو، وكان من جملة الأمراء بمصر أميرٌ يقال له عماد الدين أحمد بن علي، ويعرف بابن المشطوب، وهو من الأكراد الهكارية، وهو أكبر أميرِ بمصر، وله لفيف كثير، وجميع الأمراء أرادوا أن يخلعوا الملكَ الكامل من المُلك ويملكوا أخاه الملك الفائز بن العادل ليصيرَ الحكم إليهم عليه وعلى البلاد، فبلغ الخبر إلى الكامل، ففارق المنزلة التي كان فيها ليلًا جريدة، وسار إلى قرية يقال لها أشموم طناح، فنزل عندها، وأصبح العسكَرُ وقد فقدوا سلطانهم، فركب كل إنسان منهم هواه، ولم يقف الأخ على أخيه، ولم يقدروا على أخذِ شَيءٍ من خيامهم وذخائرهم وأموالهم وأسلحتهم إلَّا اليسير الذي يخِفُّ حمله، وتركوا الباقيَ بحاله من ميرة، وسلاح، ودواب، وخيام وغير ذلك، ولحقوا بالكامِلِ، وأما الفرنج فإنهم أصبحوا من الغد، فلم يروا من المسلمين أحدًا على شاطئِ النيل كجاري عادتهم، فبقوا لا يدرون ما الخبر، حتى أتاهم من أخبرهم الخبر على حقيقته، فعبروا النيل إلى بر دمياط آمنين بغير منازعٍ ولا ممانع، فغَنِموا ما في معسكر المسلمين، فكان عظيمًا يُعجِز العادِّين. وكاد الملك الكامل يفارق الديار المصرية؛ لأنه لم يثق بأحد من عسكره، فاتفق من لطف الله تعالى بالمسلمين أن الملك المعظم عيسى وصل إلى أخيه الكامل بعد الهزيمة بيومين، والناسُ في أمر مريج، فقَوِيَ به قلبه، واشتد ظهرُه، وثبت جنانه، وأقام بمنزلته، وأخرجوا ابن المشطوب إلى الشام، فاتصل بالملك الأشرف وصار من جندِه، قال ابن خلكان: \"فلما عبر الفرنج إلى أرض دمياط اجتمعت العربُ على اختلاف قبائلها، ونهبوا البلاد المجاورة لدمياط، وقطعوا الطريق، وأفسدوا، وبالغوا في الإفسادِ، فكانوا أشدَّ على المسلمين من الفرنج، وكان أضرَّ شيءٍ على أهل دمياط أنَّها لم يكن بها من العسكر أحدٌ؛ لأن السلطان ومن معه من العساكر كانوا عندها يمنعون العدُوَّ عنها، فأتتهم هذه الحركة بغتة، فلم يدخلها أحدٌ من العسكر، وكان ذلك من فِعلِ ابن المشطوب؛ لا جَرَم لم يمهِلْه الله، وأخذه أخذةً رابيةً\"، أحاط الفرنج بدمياط، وقاتلوها برًّا وبحرًا، وعملوا عليهم خندقًا يمنعهم من يريدهم من المسلمين، وهذه كانت عادتهم، وأداموا القتال. اشتد قتالُ الفرنج، وعَظُمَت نكايتهم لأهل دمياط، كان فيها نحو العشرين ألف مقاتل، فنهكتهم الأمراضُ، وغلت عندهم الأسعار، وامتلأت الطرقاتُ من الأموات، وعدمت الأقوات، وسئموا القتالَ وملازمته؛ لأن الفرنج كانوا يتناوبون القتال عليهم لكثرتِهم، وليس بدمياط من الكثرة ما يجعلون القتالَ بينهم مناوبة، ومع هذا فقد صبروا صبرًا لم يُسمَع بمِثلِه، وكثر القتل فيهم والجراح والموت والأمراض، ودام الحصارُ عليهم إلى السابع والعشرين من شعبان سنة 616، فعجز من بقي من أهلها عن الحفظ لقلَّتِهم، وتعذر القوت عندهم، فسَلَّموا البلد إلى الفرنج في هذا التاريخ، بالأمان، فخرج منهم قوم وأقام آخرون لعجزهم عن الحركة. وعندما أخذ الفرنج دمياط وضعوا السيَف في الناس، فلم يُعرَف عدد من قتل لكثرتهم، ورحل السلطانُ بعد ذلك بيومين، ونزل قبالة طلخا، على رأس بحر أكوم ورأس بحر دمياط، وخيَّم بالمنزلة التي عرفت بالمنصورة وحَصَّن الفرنج أسوار دمياط، وجعلوا جامِعَها كنيسةً."},{"id":2410,"title":"وفاة السلطان كيكاوس صاحب بلاد الروم وملك كيقباذ أخيه .","date":["العام الهجري :616","الشهر القمري : شوال","العام الميلادي :1220"],"text":"هو صاحب بلاد الروم السلطان الملك الغالب عز الدين كيكاوس بن السلطان كيخسرو بن قلج رسلان السلجوقي التركماني القتلمشي، صاحب قونية وأقصرا وملطية. وهو أخو السلطان كيقباذ. كان جبارًا، سفاكًا للدماء، كسره المَلِك الأشرف لَمَّا قدم ليأخذ حلب وقت الملك الظاهر غازي، فاتهم أمراءه أنهم ما نصحوا في القتال. وسلقَ جماعةً في القدورِ، وحرقَ آخرين، فأخذه الله فُجاءةً وهو مخمورٌ، وقيل: ابتلي وتقطَّعَ بَدَنُه. وكان أخوه علاء الدين كيقباذ في سجنه، فأخرجوه ومَلَّكوه."},{"id":2411,"title":"وفاة الأميرة ست الشام بنت أيوب أخت الناصر صلاح الدين الأيوبي .","date":["العام الهجري :616","الشهر القمري : ذي القعدة","العام الميلادي :1220"],"text":"هي الست الجليلة المصونُ خاتون ست الشام بنت أيوب بن شادي، واقفةُ المدرستين البرَّانية والجُوَّانية, وهي أختُ الملوك وعمَّةُ أولادهم، وأمُّ الملوك، كان لها من الملوك المحارم خمسة وثلاثون ملكًا، منهم أشقاؤها: الملك الناصر صلاح الدين، والملك العادل، والمعظم توران شاه بن أيوب صاحب اليمن، وكانت قد تزوجت ابن عمِّها ناصرَ الدين محمد بن أسد الدين شيركوه بن شادي صاحب حمص بعد عمر بن لاجين والد ابنها حسام، وكان ابنها حسام الدين من أكابر العلماء عند خاله صلاح الدين، وكانت ست الشام من أكثر النساء صدقة وإحسانًا إلى الفقراء والمحاويج، وكانت تعمل في كل سنة في دارها بألوف من الذهب أشربةً وأدوية وعقاقير وغير ذلك وتفَرِّقه على الناس، وكانت وفاتُها يوم الجمعة آخر النهار السادس عشر من ذي القعدة من هذه السنة، في دارها التي جعلتها مدرسةً، عن المارستان وهي الشامية الجوانية، ونُقِلت منها إلى تربتها بالشامية البرانية، وكانت جنازتها حافلة."},{"id":2412,"title":"إجلاء بني معروف عن البطائح وقتلهم .","date":["العام الهجري :616","الشهر القمري : ذي القعدة","العام الميلادي :1220"],"text":"أمر الخليفة الناصر لدين الله الشريف معدًّا، متولي بلاد واسط، أن يسير إلى قتال بني معروف، فتجهز وجمع معه من الرجَّالة من تكريت، وهيت، والحديثة، والأنبار، والحلة، والكوفة، وواسط، والبصرة، وغيرها، خلقًا كثيرًا، وسار إليهم، ومُقَدَّمهم حينئذ معلى بن معروف، وهم قوم من ربيعة, وكانت بيوتهم غربي الفرات، تحت سوراء، وما يتَّصل بذلك من البطائح، وكثُرَ فسادهم وأذاهم لما يقاربهم من القرى، وقطعوا الطريقَ، وأفسدوا في النواحي المقارِبة لبطيحة العراق، فشكا أهلُ تلك البلاد إلى الديوان منهم، فأمر معدًّا أن يسير إليهم في الجموع، فسار إليهم، فاستعد بنو معروف لقتاله، فاقتتلوا بموضعٍ يعرف بالمقبر، وهو تل كبير بالبطيحة بقرب العراق، وكثر القتل بينهم، ثم انهزم بنو معروف، وكثُرَ القتل فيهم، والأسر والغرق، وأُخِذَت أموالهم، وحُمِلَت رؤوس كثيرة من القتلى إلى بغداد في ذي الحجة من السنة."},{"id":2413,"title":"المغول يغيرون على بخارى ويذبحون أهلها .","date":["العام الهجري :616","الشهر القمري : ذي الحجة","العام الميلادي :1220"],"text":"لما نشب القتالُ مع المغول أمر خوارزم شاه بتحصين بخارى وسمرقند, ثم قفل ليجمع العساكِرَ من الأنحاء لقتال المغول، فلما فرغ من ذلك رحل عائدًا إلى خراسان، فعبر جيحون، ونزل بالقرب من بلخ فعسكر هناك، وأمَّا الكُفَّار فإنهم رحلوا بعد أن استعدوا يطلبون ما وراء النهر، فوصلوا إلى بخارى بعد خمسة أشهر من وصول خوارزم شاه، وحصروها، وقاتلوها ثلاثة أيام قتالًا شديدًا متتابعًا، فلم يكن للعسكر الخوارزمي بهم قوة، ففارقوا البلد عائدين إلى خراسان، فلما أصبح أهلُ البلد وليس عندهم من العسكر أحد ضَعُفَت نفوسهم، فأرسلوا القاضي، وهو بدر الدين قاضي خان، ليطلب الأمانَ للناس، فأعطَوهم الأمان، وكان قد بقي من العسكر طائفةٌ لم يمكِنْهم الهرب مع أصحابهم، فاعتصَموا بالقلعة، فلما أجابهم جنكيزخان إلى الأمان فُتِحَت أبواب المدينة يوم الثلاثاء رابع ذي الحجة، فدخل الكفَّار بخارى، ولم يتعرضوا لأحدٍ بل قالوا لهم: كل ما هو للسلطان عندكم من ذخيرة وغيره أخرِجوه إلينا، وساعِدونا على قتال مَن بالقلعة؛ وأظهروا عندهم العَدلَ وحسن السيرة، ودخل جنكيزخان بنفسِه وأحاط بالقلعة، ونادى في البلدِ بأن لا يتخلف أحدٌ ومن تخلَّف قتل، فحضروا جميعُهم، فأمرهم بطم الخندق، فطمُّوه بالأخشاب والتراب وغير ذلك، حتى إن الكفار كانوا يأخذونَ المنابر وربعات القرآن فيلقونهم في الخندقِ- فإنا لله وإنا إليه راجعون- وبحَقٍّ سمَّى الله نفسَه صبورًا حليمًا، وإلا كان خسف بهم الأرض عند فِعل ِمثل هذا، ثم تابعوا الزحف إلى القلعة وبها نحو أربعمائة فارس من المسلمين، فبذلوا جهدهم، ومنعوا القلعة اثني عشر يومًا يقاتلون جميع الكفار وأهل البلد، فقتل بعضهم، ولم يزالوا كذلك حتى زحفوا إليهم، ووصل النقَّابون إلى سور القلعة فنَقَبوه، واشتد حينئذ القتال، ومن بها من المسلمين يرمونَ ما يجدون من حجارة ونار وسهام، فغَضِبَ اللعين، ورد أصحابَه ذلك اليوم، وباكرهم من الغد، فجَدُّوا في القتال، وقد تعب مَن بالقلعة ونصبوا، وجاءهم ما لا قِبَل لهم به، فقهرهم الكفار ودخلوا القلعة، وقاتلهم المسلمون الذين فيها حتى قُتِلوا عن آخرهم، فلما فرغ من القلعة نادى أن يُكتَبَ له وجوه الناس ورؤساؤهم، ففعلوا ذلك، فلما عرضوا عليه أمَرَ بإحضارهم فحضروا، فقال: أريد منكم النقرةَ -قطع مذابةٌ من الذَّهب أَو الفِضَّة- التي باعكم خوارزم شاه، فإنَّها لي، ومن أصحابي أُخِذَت، وهي عندكم، فأحضر كل من كان عنده شيء منها بين يديه، ثم أمرهم بالخروج من البلد، فخرجوا من البلد مجردين من أموالهم، ليس مع أحد منه غير ثيابه التي عليه، ودخل الكفار البلد فنهبوه وقتلوا من وجدوا فيه، وأحاط بالمسلمين، فأمر أصحابه أن يقتَسِموهم، فاقتَسَموهم، وكان يومًا عظيمًا من كثرة البكاءِ مِن الرجال والنساء والولدان، وتفَرَّقوا وتمزقوا كل ممزق، واقتسموا النساء أيضًا، وأصبحت بخارى خاويةً على عروشها كأنْ لم تغنَ بالأمس، وارتكبوا من النساء العظيم، والناس ينظرون ويبكون، ولا يستطيعون أن يدفعوا عن أنفسِهم شيئًا مما نزل بهم، فمنهم من لم يرضَ بذلك، واختار الموت على ذلك فقاتل حتى قُتِل، ومن استسلم أخذ أسيرًا، وألقوا النار في البلد، والمدارس، والمساجد، وعذبوا الناس بأنواع العذاب في طلب المالِ."},{"id":2414,"title":"ذكر خروج التتار إلى بلاد الإسلام وإهلاكهم الحرث والنسل ووصف ابن الأثير لأفعالهم .","date":["العام الهجري :617","العام الميلادي :1220"],"text":"في هذه السنة عمَّ البلاء وعظُمَ العزاء بجنكيزخان المسمى بتموجين وقيل (تمرجين) لعنه الله تعالى، ومن معه من التتر قبَّحهم الله أجمعين، واستفحل أمرُهم واشتد إفسادُهم من أقصى بلاد الصين إلى أن وصلوا بلاد العراق وما حولها حتى انتهوا إلى إربل وأعمالها، فمَلَكوا في سنة واحدة وهي هذه السنة سائر الممالك المشرق، وقهروا جميع الطوائفِ التي بتلك النواحي الخوارزمية والقفجاق والكرج واللان والخزر وغيرهم، وقتلوا في هذه السنة من طوائف المسلمين وغيرهم في بلدان متعددة ما لا يحَدُّ ولا يُوصَفُ، وبالجملة فلم يدخُلوا بلدًا إلا قتلوا جميعَ من فيه من المقاتلة والرجال، وكثيرًا من النساء والأطفال، وأتلفوا ما فيه بالنَّهبِ إن احتاجوا إليه، وبالحريق إن لم يحتاجوا إليه، حتى إنهم كانوا يجمعون الحريرَ الكثير الذي يعجزون عن حمله فيطلقون فيه النار وهم ينظرون إليه، ويخربون المنازل، وما عَجَزوا عن تخريبه يحرقونه، وأكثر ما يحرقون المساجد والجوامع، وكانوا يأخذون الأسارى من المسلمين فيقاتِلون بهم ويحاصِرون بهم، وإن لم ينصحوا في القتال قَتَلوهم. وقد بسط ابن الأثير في كامله خبرهم في هذه السنة بسطًا حسنًا مفصلًا، فقال: \"لقد بقيت عدة سنين معرضًا عن ذكر هذه الحادثة استعظامًا لها، كارهًا لذكرها، فأنا أقدم إليه رجلًا وأؤخر أخرى، فمن الذي يسهل عليه أن يكتب نعي الإسلام والمسلمين؟ ومن الذي يهونُ عليه ذكرُ ذلك؟ فيا ليت أمي لم تلدني، ويا ليتني مت قبل حدوثها وكنت نسيًا منسيًّا، إلا أنني حثني جماعة من الأصدقاء على تسطيرها وأنا متوقف، ثم رأيتُ أنَّ تَرْك ذلك لا يجدي نفعًا، فنقول: هذا فصلٌ يتضمن ذكر الحادثة العظمى والمصيبة الكبرى التي عقمت الليالي والأيام عن مثلِها، عمت الخلائقَ وخَصَّت المسلمين، فلو قال قائل: إن العالمَ منذ خلق الله آدمَ وإلى الآن، لم يُبتَلوا بمثلها لكان صادقًا، فإن التواريخ لم تتضمن ما يقاربها ولا يدانيها، ومن أعظم ما يذكرون من الحوادثِ ما فعل بختنصر ببني إسرائيل من القتل، وتخريب بيت المقدس، وما بيتُ المقدس بالنسبة إلى ما خرَّب هؤلاء الملاعين من البلاد؟ ولعلَّ الخلائق لا يرون مثل هذه الحادثة إلى أن ينقَرِضَ العالم، وتفنى الدنيا إلا يأجوج ومأجوج، وأما الدجَّال فإنه يبقي على من اتَّبَعه، ويهلك من خالفه، وهؤلاء لم يُبقُوا على أحد، بل قتلوا الرجال والنساء والأطفال، وشَقُّوا بطون الحوامل، وقتلوا الأجنَّة، فإنا لله وإنا إليه راجعون، ولا حول ولا قوة إلا بالله العلي العظيم لهذه الحادثة التي استطار شررها، وعم ضررها، وسارت في البلاد كالسحاب استدبرته الريح، فإنَّ قومًا خرجوا من أطراف الصين، فقصدوا بلاد تركستان مثل كاشغر وبلاساغون، ثم منها إلى بلاد ما وراء النهر مثل سمرقند وبخارى وغيرهما، فيملكونها، ويفعلون بأهلها الأفاعيل، ثم تعبر طائفة منهم إلى خراسان فيفرغون منها ملكًا، وتخريبًا وقتلًا ونهبًا، ثم يجاوزونَها إلى الري وهمذان وبلد الجبل وما فيه من البلاد إلى حد العراق، ثم يقصِدون بلاد أذربيجان وأرانية ويخربونه، ويقتلون أكثَرَ أهلها ولم ينجُ منهم إلا الشريد النادر في أقل من سنة، هذا ما لم يسمع بمثله، ثم ساروا إلى دربند شروان فملكوا مدنَه، ولم يسلَمْ غير قلعته التي بها مُلكُهم، وعبَروا عندها إلى بلد اللان، واللكز ومن في ذلك الصقع من الأمم المختلفة، فأوسعوهم قتلًا ونهبًا وتخريبًا، ثم قصدوا بلاد قفجاق، وهم من أكثر الترك عددًا، فقتلوا كل من وقف لهم وهرب الباقون إلى الغياض وملكوا عليهم بلادهم، وسارت طائفة أخرى إلى غزنة وأعمالها، وما يجاورها من بلاد الهند وسجستان وكرمان، ففعلوا فيها مثل أفعال هؤلاء وأشد، هذا ما لم يطرق الأسماعَ مثلُه، فإن الإسكندر الذي اتفق المؤرخون على أنه ملك الدنيا لم يملِكْها في سنة واحدة، إنما ملَكَها في نحو عشر سنين، ولم يقتل أحدًا، بل رضي من الناس بالطاعة، وهؤلاء قد ملكوا أكثر المعمور من الأرض وأطيبه وأحسنه عمارة، وأكثره أهلًا وأعدلهم أخلاقًا وسيرة في نحو سنة، ولم يتَّفِق لأحد من أهل البلاد التي لم يطرقوها بقاء إلا وهو خائف مترقِّب وصولهم إليه. ثم إنهم لا يحتاجون إلى ميرة ومدد يأتيهم، فإنهم معهم الأغنام، والبقر، والخيل، وغير ذلك من الدواب، يأكلون لحومَها لا غير، وأما دوابهم التي يركبونها فإنها تحفِرُ الأرض بحوافرها، وتأكل عروقَ النبات لا تعرفُ الشعير، فهم إذا نزلوا منزلًا لا يحتاجون إلى شيءٍ مِن خارجه. وأمَّا ديانتهم، فإنهم يسجدون للشمسِ عند طلوعها، ولا يحرمون شيئًا، فإنهم يأكلون جميعَ الدواب، حتى الكلاب، والخنازير، وغيرها، ولا يعرفون نكاحًا بل المرأة يأتيها غيرُ واحد من الرجال، فإذا جاء الولدُ لا يَعرِف أباه. وإنما استقام لهم هذا الأمرُ لعدم المانع؛ لأن السلطان خوارزم شاه محمدًا كان قد قتل الملوك من سائر الممالك، واستقَرَّ في الأمور، فلما انهزم من التتر في العام الماضي وضَعُف عنهم وساقوا وراءه فهرب فلا يدرى أين ذهب، وهلك في بعض جزائر البحر، خلت البلادُ ولم يبق لها من يحميها؛ {لِيَقْضِيَ اللَّهُ أَمْرًا كَانَ مَفْعُولًا} [الأنفال: 44] وإلى الله تُرجَع الأمور.\""},{"id":2415,"title":"المغول يغيرون على سمرقند ويذبحون أهلها .","date":["العام الهجري :617","الشهر القمري : محرم","العام الميلادي :1220"],"text":"بعد استيلاء المغول على بخارى وما كان فيها منهم رحلوا نحو سمرقند وقد تحقَّقوا عجز خوارزم شاه عنهم، وهم بمكانه بين ترمذ وبلخ، واستصحبوا معهم من سَلِمَ من أهل بخارى أسارى، فساروا بهم مشاةً على أقبح صورة، فكلُّ من أعيا وعجز عن المشي قتلوه، فلما قاربوا سمرقند قدَّموا الخيَّالة، وتركوا الرجَّالة والأسارى والأثقال وراءهم، حتى تقدموا شيئًا فشيئًا، ليكون أرعبَ لقلوب المسلمين؛ فلما رأى أهل البلد سوادهم استعظموه، فلما كان اليومُ الثاني وصل الأسارى والرجالة والأثقال، ومع كل عشرةٍ من الأسارى عَلَم، فظن أهل البلد أن الجميعَ عساكر مقاتلة، وأحاطوا بالبلدِ وفيه خمسون ألف مقاتل من الخوارزمية، وأما عامة البلد فلا يحصون كثرة، فخرج إليهم شجعان أهله، وأهل الجلد والقوة رجالة، ولم يخرج معهم من العسكر الخوارزمي أحدٌ؛ لما في قلوبهم من خوف هؤلاء الملاعين، فقاتلهم الرجَّالة بظاهر البلد، فلم يزل التتر يتأخَّرون، وأهل البلد يَتبَعونهم، ويطمعون فيهم، وكان الكفار قد كمنوا لهم كمينًا، فلما جاوزوا الكمين خرج عليهم وحال بينهم وبين البلد، ورجع الباقون الذين أنشبوا القتال أولًا، فبَقُوا في الوسط، وأخذهم السيفُ من كل جانب، فلم يسلَمْ منهم أحد، قتلوا عن آخرهم، وكانوا سبعين ألفًا على ما قيل، فلما رأى الباقون من الجند والعامة ذلك ضَعُفت نفوسهم وأيقنوا بالهلاك، فقال الجند: وكانوا أتراكًا: نحن من جنس هؤلاء ولا يقتلوننا، فطلبوا الأمان، فأجابوهم إلى ذلك، ففتحوا أبوابَ البلد، ولم يقدِر العامة على منعهم، وخرجوا إلى الكفَّار بأهلهم وأموالهم، فقال لهم الكفار: ادفعوا إلينا سلاحَكم وأموالكم ودوابَّكم ونحن نسيركم إلى مأمنِكم، ففعلوا ذلك، فلما أخذوا أسلحتهم ودوابهم وضعوا السيف فيهم وقتلوهم عن آخِرِهم، وأخذوا أموالَهم ودوابَّهم ونساءهم، فلما كان اليوم الرابع نادوا في البلد أن يخرج أهله جميعهم، ومن تأخَّرَ قتلوه، فخرج جميعُ الرجال والنساء والصبيان، ففعلوا مع أهل سمرقند مثل فعلِهم مع أهل بخارى من النهب، والقتل، والسبي، والفساد، ودخلوا البلدَ فنهبوا ما فيه، وأحرقوا الجامِعَ وتركوا باقي البلد على حاله، وافتضُّوا الأبكار، وعذَّبوا الناس بأنواع العذاب في طلب المال، وقتلوا من لم يصلح للسبي، وكان ذلك في المحرَّم، وكان خوارزم شاه بمنزلته كلمَّا اجتمع إليه عسكر سيره إلى سمرقند، فيرجعون ولا يقدرون على الوصولِ إليها."},{"id":2416,"title":"محاولة الفرنج التوسع في احتلال أراضي مصر بعد احتلالهم دمياط .","date":["العام الهجري :617","الشهر القمري : شعبان","العام الميلادي :1220"],"text":"لَمَّا ثبت الفرنج في دمياط بثُّوا سراياهم في القرى يقتلون ويأسرون، فعظُم الخطب واشتدَّ البلاء، وندب السلطانُ الملك الكامل الناسَ وفَرَّقهم في الأرض، فخرجوا إلى الآفاق يستصرخون النَّاسَ لاستنقاذ أرض مصر من أيدي الفرنج، وشرع الكاملُ في بناء الحور –خيام من جلد أبيض- والفنادق والحمامات والأسواق بمنزلة المنصورةِ، وجهَّزَ الفرنج من حصل في أيديهم من أسارى المسلمين في البحرِ إلى عكا وبرزوا من مدينةِ دمياط يريدون أخذَ مصرَ والقاهرة، فنازلوا السلطان تجاه المنصورة، واجتمع الناسُ من أهل مصر وسائر النواحي ما بين أسوان إلى القاهرة، ونودِيَ بالنفير العام، وألَّا يبقى أحد, وذكروا أن مَلِكَ الفرنج قد أقطع ديارَ مصر لأصحابه, وأنزل الكامِلُ على ناحية شار مساح ألفي فارس، في آلاف من العربان، ليحولوا بين الفرنج وبين مرادِهم، وسارت الشواني- ومعها حراقة كبيرة- إلى رأس بحر المحلة، وعليها الأميرُ بدر الدين بن حسون، فانقطعت الميرةُ عن الفرنج من البر والبحر، وقَدِمَت النجدات للملك الكافي من بلاد الشام، وخرجت أمم الفرنج من داخل البحر تريد مدَدَ الفرنج على دمياط فوافى دمياط منهم طوائفُ لا يحصى لهم عدد فلما تكاملَ جمعُهم بدمياط خرجوا منها، وقد زُيِّنَ لهم سوءُ عمَلِهم أن يملكوا أرض مصر، ويستولوا منها على مماليكِ البسيطة كلها، فلما قدمت النجدات من المسلمين هال الفرنجَ ما رأوا، وكان قدومُ هذه النجدات في الثالث والعشرين من جمادى الآخرة سنة ثماني عشرة، وتتابع قدوم النجدات حتى بلغ عدد فرسان المسلمين نحو الأربعين ألفًا، فحاربوا الفرنج في البر والبحر، وأخذوا منهم ست شواني وجلاسة وبطسة- سفن حربية ضخمة- وأسروا منهم ألفين ومائتي رجل، ثم ظفروا أيضًا بثلاث قطائع فتضعضع الفرنجُ لذلك، وضاق بهم المقام، وبعثوا يسألون في الصُّلحِ."},{"id":2417,"title":"وفاة السلطان علاء الدين محمد خوارزم شاه .","date":["العام الهجري :617","الشهر القمري : شوال","العام الميلادي :1220"],"text":"هو السُّلطانُ علاء الدين خوارزم شاه محمد بن تكش بن إيل أرسلان بن آتسز بن محمد بن نوشتكين. نسبه ينتهي إلى إيلتكين أحد مماليك السلطان ألب أرسلان بن جغر بيك السلجوقي. أباد ملوك العالم، ودانت له الممالك واستولى على الأقاليم. كان صبورًا على التعب وإدمان السير، غير متنَعِّم ولا مقبل على اللذات، إنما نهمتُه في المُلك وتدبيره وحِفظِه وحِفظِ رعيَّتِه. كان فاضِلًا، عالِمًا بالفقه والأصول، وغيرهما. وكان مكرمًا للعلماء محبًّا لهم، محسنًا إليهم، يحب مناظرتَهم بين يديه. ويُعظِّم أهل الدين ويتبَرَّك بهم. أفنى ملوك خراسان، وما وراء النهر، وقتل صاحب سمرقند، وأخلى البلاد من الملوك- ولم يبقَ لها من يحميها- واستقلَّ بها، فكان ذلك سببًا لهلاكه, فلما نزل خوارزم شاه محمد همذان، كاتب الوزير مؤيد الدين محمد بن القمي نائب وزير الخليفة عساكرَ خوارزم شاه، ووعدهم بالبلاد، فاتفقوا مع الخطا على قتل علاء الدين، وبعث القميُّ إليهم بالأموال والخيول سرًّا، فكان ذلك سببًا لوهنه، وعَلِمَ بذلك، فسار من همذان إلى خراسان ونزل مرو، فصادف في طريقه الخيول والهدايا والكُتُب إلى الخطا، وكان معه منهم سبعون ألفًا، فلم يمكنه الرجوعُ لفساد عسكره. وكان خالُه من أمراء الخطا، وقد حلَّفوه أن لا يطلع خوارزم شاه على ما دبروا عليه، فجاء إليه في الليل، وكتب في يده صورة الحال، ووقف بإزائه، فنظر إلى السطورِ وفَهِمَها، وهو يقول: خُذْ لنفسِك، فالساعةَ تُقتَلُ، فقام وخرج من تحت ذيل الخيمةِ، ومعه ولداه جلال الدين والآخر، فركب، وسار بهما، ثم دخل الخطا والعساكر إلى خيمته، فلم يجدوه، فنهبوا الخزائن والخيول، فيقال: إنه كان في خزائنه عشرة آلاف ألف دينار وألف حمل قماش أطلس وغيره. وكانت خيله عشرين ألف فرس وبغل، وله عشرة آلاف مملوك. فهرب ورَكِب في مركب صغير إلى جزيرة فيها قلعة ليتحصَّن بها، فأدركه الأجَلُ، فدفن على ساحل البحر، وهرب ولداه، وتفرقت الممالك بعده، وأخذت التتار البلاد, وقيل بعد فراغ جنكيزخان من سمرقند أرسل وراء خوارزم شاه، وكانوا عشرين ألفا فساروا وراءه فأدركوه وبينهم وبينه نهر جيحون وهو آمن بسببه، فلم يجدوا سفنًا فعملوا لهم أحواضًا يحملون عليها الأسلحة ويُرسِل أحدهم فرسه ويأخذ بذنَبِها فتجرُّه الفرس بالماء وهو يجر الحوضَ الذي فيه سلاحُه، حتى صاروا كلُّهم في الجانب الآخر، فلم يشعُرْ بهم خوارزم شاه إلا وقد خالطوه، فهرب منهم إلى نيسابور ثم منها إلى غيرها وهم في أثره لا يمهلونه يجمع لهم فصار كلما أتى بلدًا ليجتمع فيه عساكره له يدركونه فيهرب منهم، حتى ركب في بحر طبرستان وسار إلى قلعة في جزيرة فيه، فكانت فيها وفاته، وقيل إنه لا يعرف بعد ركوبه في البحر ما كان من أمره بل ذهب فلا يدرى أين ذهب، ولا إلى أي مفر هرب، وملكت التتار حواصله فوجدوا في خزانته ما لا يحصى، وقبل وفاة علاء الدين خوارزم شاه أوصى لابنه جلال الدين منكبرتي بالسلطة."},{"id":2418,"title":"استيلاء التتار على كثير من البلدان وما صنعوا فيها من الفظائع .","date":["العام الهجري :618","العام الميلادي :1221"],"text":"بعد ما فعل المغول في سمرقند ما فعلوه أخذ جنكيزخان يرسِلُ السَّرايا إلى البلدانِ فأرسل سريةً إلى بلاد خراسان وتسميها التتار المغربة، وأرسل أخرى وراء خوارزم شاه، ثم ساروا إلى مازندران وقلاعها من أمنَعِ القلاع، بحيث إن المسلمين لم يفتحوها إلَّا في سنة تسعين من أيام سليمان بن عبد الملك، ففتحها هؤلاء في أيسَرِ مُدَّة ونهبوا ما فيها وقتَلوا أهاليها كلَّهم وسَبَوا وأحرقوا، ثمَّ ترحلوا عنها نحو الريِّ فدخلوها على حينِ غفلةٍ مِن أهلها فقَتَلوهم وسَبَوا وأسروا، ثم ساروا إلى همذان فمَلَكوها ثم إلى زنجان فقتلوا وسبوا، ثم قصدوا قزوين فنهبوها وقَتَلوا من أهلها نحوًا مِن أربعين ألفًا، ثم تيمَّموا بلاد أذربيجان فصالحَهم مَلِكُها أزبك بن البهلوان على مالٍ حَمَله إليهم لشُغلِه بما هو فيه من السُّكرِ وارتكابِ السيئات والانهماك على الشَّهواتِ، فتركوه وساروا إلى موقان فقاتلهم الكرج في عشرة آلاف مقاتل، فلم يقفوا بين أيديهم طرفةَ عين حتى انهزمت الكرج, ثم أقبَلوا إليهم مرَّةً أخرى بحدِّهم وحديدِهم، فكسرَتْهم التتار في وقعة ثانية أقبَحَ هزيمة وأشنَعَها، وانقضت هذه السنةُ وهم في بلاد الكرج، فلما رأوا منهم ممانعةً ومقاتلة يطول عليهم بها المقام عَدَلوا إلى غيرهم، وكذلك كانت عادتهم فساروا إلى تبريز فصالحَهم أهلها بمال، ثم ساروا إلى مراغة فحَصَروها ونصبوا عليها المجانيقَ وتترسوا بالأسارى من المسلمين، وعلى البلد امرأةٌ ففتحوا البلد بعد أيام وقتلوا من أهله خلقًا لا يعلم عدتَهم إلا الله عز وجل، وغنموا منه شيئًا كثيرًا، وسَبَوا وأسروا على عادتهم, ثم قصدوا مدينة إربل فضاق المسلمون لذلك ذرعًا، وقال أهل تلك النواحي هذا أمر عصيب، وكتب الخليفةُ إلى أهل الموصل والمَلِك الأشرف صاحب الجزيرة يقول: إني قد جهَّزتُ عسكرًا فكونوا معه لقتالِ هؤلاء التتار، فأرسل الأشرفُ يعتذر إلى الخليفة بأنه متوجِّه نحو أخيه الكامل إلى الديار المصرية بسبب ما قد دهم المسلمين هناك من الفرنج، وأخْذهم دمياط الذي قد أشرفوا بأخذهم له على أخذ الديار المصرية قاطبة، فكتب الخليفة إلى مظفَّر الدين صاحب إربل ليكون هو المقدم على العساكر التي يبعثها الخليفة وهي عشرة آلاف مقاتل، فلم يَقدَم عليه منهم ثمانمائة فارس ثم تفَرَّقوا قبل أن يجتمعوا، ولكنَّ الله سلم بأن صرف همة التتار إلى ناحية همذان فصالحَهم أهلُها وترك عندهم التتار شحنة، ثم اتفقوا على قتلِ شحنتِهم فرجعوا إليهم فحاصروهم حتى فتحوها قسرًا وقتلوا أهلَها عن آخرهم، ثم ساروا إلى أذربيجان ففتحوا أردبيل ثم تبريز ثم إلى بيلقان فقتلوا من أهلها خلقًا كثيرًا وجمًّا غفيرا، وحرقوها وكانوا يفجُرون بالنساء ثم يقتلونهنَّ ويشقون بطونهنَّ عن الأجنَّة ثم عادوا إلى بلاد الكرج وقد استعدت لهم الكرج فاقتتلوا معهم فكسروهم أيضًا كسرة فظيعة، ثم فتحوا بلدانًا كثيرة يقتلون أهلها ويسبون نساءها ويأسرون من الرجالِ ما يقاتلون بهم الحصون، يجعلونَهم بين أيديهم ترسًا يتقون بهم الرميَ وغيره، ومن سلم منهم قتلوه بعد انقضاء الحرب، ثم ساروا إلى بلاد اللان والقبجاق فاقتتلوا معهم قتالًا عظيمًا فكسروهم وقصدوا أكبَرَ مدائن القبجاق وهي مدينة سوداق وفيها من الأمتعة والثياب والتجائر شيءٌ كثير جدًّا، ولجأت القبجاق إلى بلاد الروس وكانوا نصارى فاتفقوا معهم على قتال التتار فالتَقَوا معهم فكسرتهم التتار كسرةً فظيعةً جدًّا، ثم ساروا نحو بلقار في حدود سنة620, ففرغوا من ذلك كلِّه ورجعوا نحو مَلِكهم جنكيزخان، هذا ما فعلته هذه السرية المغربة، وكان جنكيزخان قد أرسل سرية في هذه السنة إلى كلانة وأخرى إلى فرغانة فملكوها، وجهز جيشًا آخر نحو خراسان فحاصروا بلخ فصالحهم أهلُها، وكذلك صالحوا مدنًا كثيرة أخرى، حتى انتهوا إلى الطالقان فأعجزتهم قلعتها وكانت حصينةً فحاصروها ستة أشهر حتى عجزوا فكتبوا إلى جنكيزخان فقَدِمَ بنَفسِه فحاصرها أربعة أشهر أخرى حتى فتحها قهرًا، ثم قتل كل من فيها وكل من في البلد بكماله خاصةً وعامة، ثم قصدوا مدينةَ مرو مع جنكيزخان فقد عسكر بظاهرها نحو من مائتي ألف مقاتل من العرب وغيرهم فاقتتلوا معه قتالًا عظيمًا حتى انكسر المسلمون، فإنا لله وإنا إليه راجعون، ثم حصروا البلد خمسة أيام واستنزلوا نائبها خديعةً ثم غدروا به وبأهل البلد فقتلوهم وغَنِموهم وسلبوهم وعاقبوهم بأنواع العذاب، حتى إنهم قتلوا في يوم واحد سبعمائة ألف إنسان، ثم ساروا إلى نيسابور ففعلوا فيها ما فعلوا بأهل مرو، ثم إلى طوس فقتلوا وخربوا مشهدَ علي بن موسى الرضا، وخربوا تربة الرشيد الخليفة فتركوه خرابًا، ثم ساروا إلى غزنة فقاتلهم جلال الدين بن خوارزم شاه فكسَرَهم ثم عادوا إلى ملكهم جنكيزخان، وأرسل جنكيزخان طائفة أخرى إلى مدينة خوارزم فحاصروها حتى فتحوا البلد قهرًا فقتلوا من فيها قتلًا ذريعًا، ونهبوها وسبوا أهلها وكسروا الجسر الذي يمنع ماء جيحون منها فغرقت دورها وهلك جميع أهلها ثم عادوا إلى جنكيزخان وهو مخيم على الطالقان فجهز منهم طائفة إلى غزنة فاقتتل معهم جلال الدين بن خوارزم شاه فكسرهم جلال الدين كسرة عظيمة، واستنقذ منهم خلقًا من أسارى المسلمين، ثم كتب إلى جنكيزخان يطلب منه أن يبرز بنفسِه لقتاله، فقصده جنكيزخان فتواجَها وقد تفَرَّق على جلال الدين بعضُ جيشه ولم يبق بدٌّ من القتال، فاقتتلوا ثلاثة أيام لم يُعهَد قبلها مثلها من قتالهم، ثم ضَعُف أصحاب جلال الدين فذهبوا فركبوا بحر الهند فسارت التتار إلى غزنة فأخذوها بلا كلفة ولا ممانعة."},{"id":2419,"title":"وفاة قتادة أمير مكة وملك ابنه الحسن .","date":["العام الهجري :618","الشهر القمري : جمادى الآخرة","العام الميلادي :1221"],"text":"هو أميرُ مكة، قتادة بن إدريس العلوي، الحسني. كان في أول ملكه، لَمَّا ملك مكة، حرسها الله، حسنَ السيرة أزال عنها العبيد المفسِدين، وحمى البلاد، وأحسن إلى الحُجَّاج، وأكرمهم، وبقي كذلك مدة، ثم إنه بعد ذلك أساء السيرة، وجدد المكوسَ بمكة، وفعل أفعالًا شنيعة، ونهب الحاجَّ في بعض السنين، وقيل في موت قتادة إن ابنه حسنًا خنقه فمات، وسبب ذلك أن قتادة جمع جموعًا كثيرة وسار عن مكة يريد المدينة، فنزل بوادي الفرع وهو مريض، وسير أخاه على الجيش ومعه ابنه الحسن بن قتادة، فلما أبعدوا بلغ الحسن أن عمه قال لبعض الجند: إن أخي مريض، وهو ميت لا محالة، وطلب منهم أن يحلفوا له ليكون هو الأمير بعد أخيه قتادة، فحضر الحسن عند عمه، واجتمع إليه كثير من الأجناد والمماليك الذين لأبيه، فقال الحسن لعمه: قد فعلتَ كذا وكذا، فقال: لم أفعل؛ فأمر حسن الحاضرين بقتلِه، فلم يفعلوا، وقالوا: أنت أميرٌ وهذا أمير، ولا نمد أيدينا إلى أحدكما، فقال له غلامان لقتادة: نحن عبيدُك، فمُرْنا بما شئت؛ فأمرهم أن يجعلا عمامةَ عمِّه في عنقه، ففعلا، ثمَّ قتَلَه، فسمع قتادة الخبر، فبلغ منه الغيظُ كُلَّ مبلغ، وحلف ليقتُلَنَّ ابنه، وكان على ما كان من المرض، فكتب بعض أصحابه إلى الحسَنِ يعرفه الحال، ويقول له: ابدأ به قبل أن يقتُلَك،  فعاد الحسن إلى مكة، فلما وصلها قصد دار أبيه في نفر يسير فوجد على باب الدار جمعًا كثيرًا، فأمرهم بالانصرافِ إلى منازلهم، ففارقوا الدارَ وعادوا إلى مساكِنِهم، ودخل الحسَنُ إلى أبيه، فلما رآه أبوه شَتَمه، وبالغ في ذمِّه وتهديده، فوثب إليه الحسن فخنقه لوقتِه، وكان عمره نحو تسعين سنة، ثم خرج الحسن إلى الحرم الشريف، وأحضر الأشرافَ، وقال: إن أبي قد اشتد مرضه، وقد أمركم أن تحلِفوا لي أن أكونَ أنا أميركم، فحلفوا له، ثم إنه أظهر تابوتًا ودفنه ليظُنَّ الناسُ أنه مات، وكان قد دفنه سرًّا، فلما استقرت الإمارةُ بمكة له أرسل إلى أخيه الذي بقلعة ينبع على لسان أبيه يستدعيه، وكتم موتَ أبيه عنه، فلما حضر أخوه قتَلَه أيضًا، واستقَرَّ أمره، وثَبَت قدمُه، فارتكب عظيمًا: قتل أباه وعمه وأخاه في أيام يسيرةٍ."},{"id":2420,"title":"اقتتال أمير مكة الحسن وأخيه وقتل أمير الحجاج .","date":["العام الهجري :618","الشهر القمري : رجب","العام الميلادي :1221"],"text":"لما مات أمير مكة قتادة، وملك بعده ابنه الحسن، وكان له ابن آخر اسمه راجح، مقيم في العرب بظاهر مكة، يُفسِد وينازع أخاه في ملك مكة، فلما سار حاج العراق كان الأمير عليهم مملوكًا من مماليك الخليفة الناصر لدين الله اسمه أقباش، وكان حسن السيرة مع الحاج في الطريق، كثير الحماية، فقصده راجح بن قتادة، وبذل له وللخليفة مالًا ليساعده على ملك مكة، فأجابه إلى ذلك، ووصلوا مكة، ونزلوا بالزاهر، وتقدم أقباش إلى مكة مقاتلًا لصاحِبِها الحسن، وكان الحسَنُ قد جمع جموعًا كثيرة من العرب وغيرها، فخرج إليه من مكة وقاتله، وتقدم أميرُ الحاج من بين يدي عسكره منفردًا، وصعد الجبل إدلالًا بنفسِه، وأنه لا يقدم أحدٌ عليه، فأحاط به أصحابُ الحسن، وقتلوه، وعلقوا رأسه، فانهزم عسكر أمير المؤمنين، وأحاط أصحابُ الحسن بالحاجِّ لينهبوهم، فأرسل إليهم الحسنُ عمامته أمانًا للحُجَّاج، فعاد أصحابه ولم ينهبوا منهم شيئًا وسكن النَّاسُ، وأذِنَ لهم الحسن في دخول مكة وفِعْل ما يريدونه من الحج والبيع وغير ذلك، وأقاموا بمكَّةَ عشرة أيام، وعادوا، فوصلوا إلى العراق سالمين، وعظُمَ الأمر على الخليفة، فوصلت رسل الحسنِ يعتذرون، ويطلبون العفوَ عنه، فأجيبَ إلى ذلك."},{"id":2421,"title":"انهزام الحملة الصليبية الخامسة واستعادة المسلمين دمياط .","date":["العام الهجري :618","الشهر القمري : رجب","العام الميلادي :1221"],"text":"اشتَدَّ القتال بين الفرنج والمسلمين برًّا وبحرًا، وقد اجتمع من الفرنج والمسلمين ما لا يعلم عددهم إلا الله، هذا والرسُل تتردد من عند الفرنج في طلب الصلحِ بشروط: منها أخذ القدس وعسقلان وطبرية، وجبلة واللاذقية، وسائر ما فتحه السلطان صلاحُ الدين من بلاد الساحل، فأجابهم الملوك إلى ذلك، ما خلا الكرك والشوبك، فأبى الفرنجُ، وقالوا: لا نسَلِّم دمياط حتى تسلِّموا ذلك كله فرضي الكامل، فامتنع الفرنج، وقالوا: لا بد أن تعطونا خمسمائة ألف دينار، لنعمر بها ما خربتم من أسوار القدس، مع أخْذِ ما ذكر من البلاد، وأخذ الكرك والشوبك أيضًا، فاضطر المسلمون إلى قتالهم ومصابرتِهم، وعبَرَ جماعة من المسلمين في بحر المحلة إلى الأرض التي عليها معسكر الفرنج، وفتحوا مكانًا عظيمًا في النيل، وكان وقتَ قوة زيادة النيل، والفرنج لا معرفةَ لهم بحال أرض مصر، ولا بأمر النيل، فلم يشعر الفرنج إلا والماء قد غرق أكثر الأرض التي هم عليها، وصار حائلًا بينهم وبين دمياط، وأصبحوا وليس لهم جهة يسلكونها، سوى جهةٍ واحدة ضيقة، فأمر السلطانُ في الحال بنصب الجسور وعبَرَت العساكر الإسلامية عليها، وملكت الطريق التي تسلكها الفرنجُ إلى دمياط، فانحصروا من سائر الجهات، وقَدَّر الله سبحانه بوصول فرقةٍ عظيمة في البحر للفرنج، وحولها عدةُ حراقات تحميها، وسائرها مشحونة بالميرة والسلاح، وسائر ما يحتاج إليه، فأوقع بها شواني الإسلام، وكانت بينهما حربٌ، أنزل الله فيها نصره على المسلمين، فظَفِروا بها وبما معها من الحراقات، ففتَّ ذلك في عضد الفرنج، وألقِيَ في قلوبهم الرعب والذلة، بعدما كانوا في غاية الاستظهار والعنت على المسلمين، وعلموا أنهم مأخوذون لا محالة، فأجمعوا أمرهم على مناهضة المسلمين؛ ظنًّا منهم أنهم يصلون إلى دمياط، فخَرَّبوا خيامهم ومجانيقَهم، وعزموا على أن يحطموا حطمةً واحدة، فلم يجدوا إلى ذلك سبيلًا، لكثرةِ الوحل والمياه التي قد ركبت الأرضَ مِن حولهم، فعجزوا عن الإقامة لقلَّةِ الأزواد عندهم، ولاذوا إلى طلَبِ الصلحِ، وبعثوا يسألون الملك الكامل وأخويه الأشرف والمعظم الأمانَ لأنفُسِهم، وأنهم يسلِّمونَ دمياط بغير عوض، فاقتضى رأيُ الملك الكامل إجابتهم، هذا وقد ضجرت عساكر المسلمين، وملت من طول الحرب، فإنها مقيمة في محاربة الفرنج ثلاث سنين وأشهرًا، وما زال الكامل قائمًا في تأمين الفرنج إلى أن وافقه بقيَّة الملوك على أن يبعث الفرنجُ برهائن من ملوكِهم لا من أمرائهم إلى أن يسَلِّموا دمياط فطلب الفرنجُ أن يكون ابن الملك الكامل عندهم رهينةً، إلى أن تعود إليهم رهائنُهم، فتقَرَّر الأمر على ذلك، وحلف كل من ملوك المسلمين والفرنج، في سابع شهر رجب، وبعث الفرنج بعشرين ملكًا من ملوكهم رهنًا، منهم يوحنا صاحب عكا، ونائب البابا، وبعث الملك الكامل إليهم بابنه الملك الصالح نجم الدين أيوب، وله من العمر يومئذ خمس عشرة سنة، ومعه جماعة من خواصه، وعندما قدم ملوك الفرنج جلس لهم الملك الكامل مجلسًا عظيمًا، ووقف الملوكُ من إخوته وأهل بيته بين يديه، في يوم الأربعاء التاسع عشر من شهر رجب، فهال الفرنج ما شاهدوا من تلك العظمة وبهاء ذلك الناموس، وقدمت قسوس الفرنج ورهبانهم إلى دمياط، ليسَلِّموها إلى المسلمين، فتسَلَّمها المسلمون في يوم الأربعاء التاسع عشر من شهر رجب، فلما تسلمها المسلمون قدم في ذلك اليوم من الفرنج نجدة عظيمة، يقال أنها ألف مركب، فعُدَّ تأخُّرُهم إلى ما بعد تسليمِها من الفرنج صنعًا جميلًا من الله سبحانه، وشاهد المسلمون عندما تسلموا دمياط من تحصين الفرنج لها ما لا يمكِن أخذُها بقوة البتة، وبعث السلطان بمن كان عنده في الرهن من الفرنج، وقَدِمَ الملك الصالح ومن كان معه، وتقررت الهدنة بين الفرنج وبين المسلمين مدة ثماني سنين، على أن كلًّا من الفريقين يطلق ما عنده من الأسرى، وحلف السلطان وإخوته وحلف ملوك الفرنج على ذلك، وتفرَّق من كان قد حضر للقتال، فكانت مدة استيلاء الفرنج على دمياط سنة واحدة وعشرة أشهر وأربعة وعشرين يومًا، ثم دخل الملك الكامل إلى دمياط بعساكره وأهله، وكان لدخوله مسرة عظيمة وابتهاج زائد، ثم سار الفرنج إلى بلادهم وعاد السلطان إلى قلعة الجبل في يوم الجمعة ثاني عشر شهر رمضان، ودخل الوزير الصاحب صفي الدين عبد الله بن علي بن شكر في البحر، وأطلق من كان بمصر من الأسرى، وكان فيهم من أُسِرَ من الأيام الصلاحية، وأطلق الفرنج من كان في بلادهم من أسرى المسلمين."},{"id":2422,"title":"نهب الكرج (الجورجيون، سكان جورجيا) بيلقان .","date":["العام الهجري :619","الشهر القمري : رمضان","العام الميلادي :1222"],"text":"سار الكرج من بلادهم إلى بلاد أران وقصدوا مدينة بيلقان، وكان التتار قد خربوها، ونهبوها فلما سار التتر إلى بلاد قفجاق عاد من سلم من أهلها إليها، وعَمَروا ما أمكنهم عمارته من سورها، فبينما هم كذلك إذ أتاهم الكرج ودخلوا البلد وملكوه، وكان المسلمون في تلك البلاد ألِفُوا من الكرج أنهم إذا ظفروا ببلد صانعوه بشيء من المال فيعودون عنهم، فكانوا أحسن الأعداء مقدرةً، فلما كانت هذه الدفعة ظن المسلمون أنهم يفعلون مثل ما تقدم، فلم يبالغوا في الامتناعِ منهم، ولا هربوا من بين أيديهم، فلمَّا ملك الكرج المدينة وضعوا السيف في أهلِها، وفعلوا من القتل والنهب أكثَرَ مما فعل بهم التتر، هذا جميعُه يجري، وصاحب بلاد أذربيجان أوزبك بن البهلوان بمدينة تبريز، ولا يتحرك في صلاح، ولا يتجه لخير، بل قد قنع بالأكل وإدمان الشرب والفساد."},{"id":2423,"title":"حج مسعود بن أقسيس صاحب اليمن وما فعله في مكة .","date":["العام الهجري :619","الشهر القمري : ذي الحجة","العام الميلادي :1223"],"text":"حج الملك مسعود بن أقسيس بن الكامل صاحب اليمن، فبدت منه أفعال ناقصة بالحرمِ مِن سُكرٍ ورَشقِ حمامِ المسجِدِ بالبندق من أعلى قبَّة زمزم، وكان إذا نام في دار الإمارة يُضرَبُ الطائفون بالمسعى بأطرافِ السيوف لئلَّا يشوشوا عليه، وهو نوم سكر، وكان مع هذا كله مهيبًا محترمًا والبلاد به آمنة، وقد كاد يرفع سنجق أبيه يوم عرفة على سنجق الخليفة، فيجري بسبب ذلك فتنة عظيمة."},{"id":2424,"title":"الملك المسعود صاحب اليمن يستولي على مكة وينهب أهلها .","date":["العام الهجري :620","العام الميلادي :1223"],"text":"سار صاحب اليمن الملك المسعود أقسيس بن الملك الكامل محمد، صاحب مصر، إلى مكة وصاحبها حينئذ حسن بن قتادة بن إدريس، العلوي الحسيني، قد ملكها بعد أبيه، وكان حسن قد أساء إلى الأشراف والمماليك الذين كانوا لأبيه، وقد تفرقوا عنه، ولم يبق عنده غيرُ أخواله من غيره، فوصل صاحب اليمن إلى مكة، ونهبها عسكرُه إلى العصر، حتى أخذوا الثيابَ عن الناس، وأفقَروهم، وأمر صاحب اليمنِ أن ينبش قبر قتادة الأمير السابق ويُحرَق، فنبشوه، فظهر التابوت الذي دفنه ابنه الحسَنُ والناس ينظرون إليه، فلم يَرَوا فيه شيئًا، فعلموا حينئذ أن الحسَنَ دفَنَ أباه سرًّا، وأنه لم يجعل في التابوت شيئًا، وذاق الحسَنُ عاقبةَ قطيعة الرحم، وعجَّلَ الله مقابلته، وأزال عنه ما قَتَلَ أباه وأخاه وعمه لأجله."},{"id":2425,"title":"وفاة الإمام فخر الدين ابن عساكر الشافعي .","date":["العام الهجري :620","العام الميلادي :1223"],"text":"هو الشيخ الإمام العالم القدوة المفتي شيخ الشافعية: فخر الدين، أبو منصور عبد الرحمن بن محمد بن الحسن بن هبة الله بن عبد الله الدمشقي، الشافعي. ولد سنة 550, وسمع من عميه؛ الصائن والحافظ، وتفقه على قطب الدين مسعود النيسابوري، وتزوج بابنته، وجاءه ولد منها، سماه مسعودًا. درَّس بالجاروخية، ثم بالصلاحية بالقدس، وبالتقوية بدمشق، فكان يقيم بالقدس أشهرًا، وبدمشق أشهرًا، وكان عنده بالتقوية فضلاء البلد، حتى كانت تُسمى نظامية الشام، ثم درس بالعذراوية سنة 593، وكان فخر الدين لا يَملُّ الشخص من النظر إليه، لحسن سمته، ونور وجهِه، ولطفه، واقتصاده في ملبسِه، وكان لا يفتُرُ من الذكر، استدعاه الملك العادل بعد ما عزل قاضيه ابن الزكي فأجلسه إلى جانبه وقت السماط، وسأل منه أن يلي القضاء بدمشق، فقال حتى أستخير الله تعالى، ثم امتنع من ذلك فشَقَّ على السلطان امتناعه، وهم أن يؤذيَه فقيل له: احمدِ الله الذي في بلادك مثل هذا, وكان قد خاف أن يُكرَه، فجهز أهله للسفر، وخرجت المحابر- طلبة العلم الذين يستملون- إلى ناحية حلب، فردها العادل، وعزَّ عليه ما جرى. قال أبو شامة: كان فخر الدين يتورع من المرور في زقاق الحنابلة لئلَّا يأثموا بالوقيعة فيه؛ وذلك لأن عوامهم يبغضون بني عساكر؛ لأنهم كانوا أعيان الشافعية الأشعرية\" لما توفي الملك العادل وأعاد ابنه المعظم الخمور أنكر عليه الشيخ فخر الدين، فبقي في نفسِه منه، فانتزع منه تدريس التقوية، ولم يبق معه سوى الجاروخية ودار الحديث النورية ومشهد ابن عروة، كان زاهدًا عابدًا ورعًا، منقطعًا إلى العلم والعبادة، حسَنَ الأخلاق، قليل الرغبة في الدنيا، وقلَّ من تخلف عن جنازته. قال أبو شامة: \"أخبرني من حضره قال: صلى الظهر، وجعل يسأل عن العصر، وتوضَّأ، ثم تشهد وهو جالس، وقال: رضيتُ بالله ربًّا، وبالإسلام دينًا، وبمحمدٍ نبيًّا، لقنني اللهُ حُجَّتي، وأقالني عثرتي، ورَحِمَ غُربتي، ثم قال: وعليكم السلام، فعلمنا أنَّه حضرت الملائكة، ثم انقلب ميتًا، غسله الفخر بن المالكي، وابن أخيه تاج الدين، وكان مرضه بالإسهال، وصلى عليه أخوه زين الأمناء، ومن الذي قدر على الوصول إلى سريره\" وقال عمر بن الحاجب: \"هو أحد الأئمة المبرزين، بل واحدهم فضلًا وقدرًا، شيخ الشافعية، كان زاهدًا ثقةً مجتهدًا، غزير الدمعة، حسنَ الأخلاق، كثير التواضع، قليل التعصُّب، سلك طريق أهل اليقين، وكان أكثر أوقاته في بيته في الجامع، ينشُرُ العلم، وكان مطرح الكلف، عرضت عليه مناصب فتركَها، ولد في رجب وتوفي فيه، وعاش سبعين سنة، وكان الجمع لا ينحصر كثرةً في جنازته، حدث بمكة ودمشق والقدس، وصنف عدة مصنفات\". وقال القوصي: \"كان كثير البكاء، سريع الدموع، كثير الورع والخشوع، وافر التواضع والخضوع، كثير التهجد، قليل الهجوع، مبرزًا في علمي الأصول والفروع، وعليه تفقهتُ وعرضت عليه (الخلاصة) للغزالي\"، ودفن عند شيخه قطب الدين مسعود النيسابوري."},{"id":2426,"title":"حرب بين المسلمين والكرج (الجورجيون، سكان جورجيا) بأرمينية .","date":["العام الهجري :620","الشهر القمري : شعبان","العام الميلادي :1223"],"text":"سار شهاب الدين غازي بن الملك العادل أبي بكر بن أيوب صاحب قلعة سرماري، وهي من أعمال أرمينية إلى خلاط، لأنه كان في طاعة صاحب خلاط، فحضر عنده، واستخلف ببلده أميرًا من أمرائه، فجمع هذا الأمير جمعًا وسار إلى بلاد الكرج، فنهب منها عدة قرى وعاد، فسمعت الكرج بذلك، فجمع صاحب دوين، واسمه شلوة، وهو من أكابر أمراء الكرج، عسكره وسار إلى سرماري فحصرها أيامًا، ونهب بلدها وسوادها ورجع، فسمع صاحب سرماري شهاب الدين الخبر، فعاد إلى سرماري، فوصل إليها في اليوم الذي رحل الكرج عنها، فأخذ عسكره وتبعهم، فأوقع بساقتهم، فقتل منهم وغنم، واستنقذ بعض ما أخذوا من غنائم بلاده، ثم إن صاحب دوين جمع عسكره وسار إلى سرماري ليحصرها، فوصل الخبَرُ إلى شهاب الدين بذلك، فحَصَّنها، وجمع الذخائر وما يحتاج إليه، فأتاه من أخبره أن الكرج نزلوا بوادي بني دوين وسرماري، وهو وادي ضيق، فسار بجميع عسكره جريدة –الجريدة: خَيْلٌ لا رَجَّالة فيها- وجَدَّ السير ليكبس الكرج، فوصل إلى الوادي الذي هم فيه وقت السحر، ففرق عسكره فرقتين: فرقةً من أعلى الوادي، وفرقة من أسفله، وحملوا عليهم وهم غافلون، ووضعوا السيف فيهم، فقتلوا وأسروا، فكان في جملة الأسرى شلوة أمير دوين، في جماعة كثيرة من مقدميهم، ومن سلم من الكرج عاد إلى بلدهم على حال سيئة، ثم إن ملك الكرج أرسل إلى الملك الأشرف موسى بن العادل، صاحب ديار الجزيرة، وهو الذي أعطى خلاط وأعمالها الأمير شهاب الدين، يقول له: كنا نظن أننا صلح، والآن فقد عمل صاحب سرماري هذا العمل، فإن كنا على الصلح فنريد إطلاق أصحابنا من الأسر، وإن كان الصلح قد انفسخ بيننا فتعرفنا حتى ندبِّر أمرنا، فأرسل الأشرف إلى صاحب سرماري يأمره بإطلاق الأسرى وتجديد الصلح مع الكرج، ففعل ذلك واستقرت قاعدة الصلح، وأُطلق الأسرى."},{"id":2427,"title":"وفاة الإمام العلامة موفق الدين ابن قدامة المقدسي الحنبلي .","date":["العام الهجري :620","الشهر القمري : شوال","العام الميلادي :1223"],"text":"هو الإمامُ العلَّامة البارع الفقيه أبو محمد موفق الدين عبد الله بن أحمد بن محمد بن قدامة بن مقدام بن نصر المقدسي، الجماعيلي، الدمشقي، الصالحي، الحنبلي، صاحب (المُغني). ولد بجماعيل، من عمل نابلس، في شعبان سنة 541. صاحب كتاب المغني المشهور في المذهب الحنبلي، قدم مع أهله إلى دمشق في سنة إحدى وخمسين، وهو ابن عشر سنوات ومعه ابن خاله الحافظ عبد الغني, وقرأ القرآن وسمع الحديث الكثير، ورحل مرتين إلى العراق إحداهما مع الحافظ عبد الغني، فأدركا نحو أربعين يومًا من جنازة الشيخ عبد القادر، فنزلا عنده بالمدرسة، واشتغلا عليه تلك الأيام، وسمعا منه، تفقه ببغداد على مذهب الإمام أحمد، وبرع وأفتى وناظر وتبحَّر في فنون كثيرة، مع زهد وعبادة، وورع وتواضع وحسن أخلاق، وجودٍ وحياء وحسن سمت وكثرة تلاوة، وصلاة وصيام وقيام، وطريقة حسنة واتباع للسلف الصالح، فكان عالم أهل الشام في زمانه. قال ابن النجار: \"كان إمام الحنابلة بجامع دمشق، وكان ثقة حجة، نبيلًا، غزير الفضل، نزهًا، وَرِعًا، عابدًا، على قانون السلف، عليه النور والوقار، ينتفع الرجل برؤيته قبل أن يسمع كلامَه\", وقال عمر بن الحاجب: \"هو إمام الأئمة، ومفتي الأمة، خصه الله بالفضل الوافر، والخاطر الماطر، والعلم الكامل، طنَّت بذكره الأمصار، وضَنَّت بمثله الأعصار، أخذ بمجامع الحقائق النقلية والعقلية...، إلى أن قال: وله المؤلفات الغزيرة، وما أظن الزمان يسمح بمثله، متواضع، حسن الاعتقاد، ذو أناة وحلم ووقار، مجلسه معمور بالفقهاء والمحدثين، وكان كثير العبادة، دائم التهجد، لم نرَ مثله، ولم ير مثل نفسِه\". عمل الشيخ الضياء (سيرته) في جزأين، فقال: \"كان تام القامة، أبيض، مشرق الوجه، أدعج، كأن النور يخرج من وجهه لحسنه، واسع الجبين، طويل اللحية، قائم الأنف، مقرون الحاجبين، صغير الرأس، لطيف اليدين والقدمين، نحيف الجسم، ممتَّعًا بحواسه\". وقال الضياء: \"سمعت المفتي أبا بكر محمد بن معالي بن غنيمة يقول: ما أعرف أحدًا في زماننا أدرك درجة الاجتهاد إلا الموفق, وسمعت الحافظ أبا عبد الله اليونيني يقول: أما ما علمته من أحوال شيخنا وسيدنا موفق الدين، فإنني إلى الآن ما أعتقد أن شخصًا ممن رأيته حصل له من الكمال في العلوم والصفات الحميدة التي يحصل بها الكمال سواه؛ فإنه كان كاملًا في صورته ومعناه من حيث الحسن، والإحسان، والحلم والسؤدد، والعلوم المختلفة، والأخلاق الجميلة، رأيت منه ما يعجز عنه كبار الأولياء، فإن رسول الله صلى الله عليه وسلم قال: ((ما أنعم اللهُ على عبدٍ نعمةً أفضل من أن يلهِمَه ذِكْرَه)), فقلت بهذا: إن إلهام الذكر أفضل من الكرامات، وأفضل الذكر ما يتعدى إلى العباد، وهو تعليمُ العلم والسنة، وأعظمُ من ذلك، وأحسن ما كان جبلة وطبعًا، كالحلم، والكرم، والعقل، والحياء، وكان الله قد جبله على خُلق شريف، وأفرغ عليه المكارم إفراغًا، وأسبغ عليه النعم، ولطف به في كل حال. قال الضياء: كان الموفَّق لا يناظر أحدًا إلا وهو يتبسم, وقيل: إن الموفق ناظر ابن فضلان الشافعي الذي كان يُضرَبُ به المثل في المناظرة، فقطَعَه. وبقي الموفق يجلسُ زمانًا بعد الجمعة للمُناظرة، ويجتمع إليه الفقهاء، وكان يشغلُ إلى ارتفاع النهار، ومن بعد الظهر إلى المغرب ولا يضجر، ويسمعونَ عليه، وكان يقرئُ في النحو، وكان لا يكاد يراه أحد إلا أحبَّه, وما علمت أنه أوجع قلبَ طالب، وكانت له جارية تؤذيه بخُلُقِها، فما يقول لها شيئًا، وأولاده يتضاربون وهو لا يتكلم, وسمعت البهاءَ يقول: ما رأيتُ أكثر احتمالًا منه.\" كان يؤمُّ الناس للصلاة في محراب الحنابلة هو والشيخ العماد، فلما توفي العماد استقل هو بالوظيفة، وله مصنفات عديدة مشهورة، أشهرها المغني في شرح مختصر الخرقي، والكافي في الفقه الحنبلي، والمقنع للحفظ، والروضة في أصول الفقه، وغير ذلك من التصانيف المفيدة، وكانت وفاته في يوم عيد الفطر، وقد بلغ الثمانين، وكان يوم سبت وحضر جنازته خلق كثير، ودفن بتربته المشهورة، ورئيت له منامات صالحة رحمه الله تعالى. كان له أولاد ذكور وإناث، ماتوا في حياته, ولم يعقب منهم سوى ابنه عيسى ولد له ولدان ثم ماتا وانقطع نسله."},{"id":2428,"title":"وفاة المنتصر بالله أبي يعقوب يوسف المؤمني صاحب المغرب .","date":["العام الهجري :620","الشهر القمري : ذي القعدة","العام الميلادي :1223"],"text":"هو المنتصر بالله- وقيل المستنصر بالله أبو يعقوب يوسف بن محمد الناصر بن يعقوب المنصور بن يوسف بن عبد المؤمن بن علي. ولد سنة 594، وأمه أم ولد، اسمها قمر الرومية، وكان يشبه بجَدِّه. تولى الملك بعد وفاة أبيه يقول الذهبي: \"فملكوه وله ست عشرة سنة، فضيعوا أمرَ الأمة، وكان بديع الحسن، بليغ المنطق، غارقًا في وادي اللهو والبطالة\" فغلب عليه وزراؤه واشتغل المنتصرُ بما يستهويه, وفي عهده استولى الأسبان في الأندلس على المعاقل التي كانت للموحِّدين، وكانت في عهده هزائم أخرى أشهرها العقاب في الأندلس، وبدأت دولته في عصره بالهرم، ثم إن المنتصر ظل مقيمًا في مراكش إلى أن توفي ولم يخلف ولدًا، فبويع بعده عم أبيه عبد الواحد بن يوسف الملقب بالمخلوع، لكِبَرِ سنه ووفور عقلِه، فلم يُحسِن التدبير، ولا دارى أهل دولته فخلعوه وخنَقوه بعد تسعة أشهر من ولايته. وبويع ابن أخيه عبد الله العادل بن يعقوب المنصور."},{"id":2429,"title":"غياث الدين بن خوارزم يمتلك بلاد فارس .","date":["العام الهجري :621","العام الميلادي :1224"],"text":"كان غياث الدين بن خوارزم شاه محمد بالري، وله معها أصفهان وهمذان وما بينهما من البلاد، وله أيضًا بلادُ كرمان، فلما هلك أبوه، وصل التترُ إلى بلاده، وامتنع بأصفهان، وحصره التترُ فيها فلم يقدروا عليها، فلما فارق التتر بلادَه، وساروا إلى بلاد قفجاق، عاد ملك البلاد وعَمَر ما أمكَنَه منها، وأقام بها إلى أواخر سنة 620، فسار إلى بلاد فارس فلم يشعُرْ صاحبُها، وهو أتابك سعد بن دكلا، إلا وقد وصل غياث الدين إلى أطراف بلاده، فلم يتمكن من الامتناع، فقصد قلعة إصطخر فاحتمى بها، وسار غياث الدين إلى مدينة شيراز، وهي كرسيُّ مملكة فارس، وأكبَرُها وأعظَمُها، فملكها بغير تعبٍ هذه السنة، وبقي غياث الدين بها، واستولى على أكثر البلاد، ولم يبقَ بيد سعد إلا الحصونُ المنيعة، فلما طال الأمرُ على سعد صالحَ غياثَ الدين على أن يكون لسعد من البلاد قَسمٌ اتفقوا عليه، ولغياث الدين الباقي، وأقام غياث الدين بشيراز، وازداد إقامةً وعزمًا على ذلك لَمَّا سمع أن التتر قد عادوا إلى الريِّ والبلاد التي له وخرَّبوها."},{"id":2430,"title":"عود طائفة من التتار إلى الري وهمذان وغيرهما .","date":["العام الهجري :621","الشهر القمري : محرم","العام الميلادي :1224"],"text":"أول هذه السنة وصلت سرية للريِّ من التتر من عند مَلكِهم جنكيزخان، وهؤلاء غيرُ الطائفة الغربية، وكان من سَلِمَ من أهلها قد عادوا إليها وعَمَروها، فلم يشعروا بالتتر إلا وقد وصلوا إليها، فلم يمتَنِعوا عنهم، فوضعوا في أهلها السيفَ وقتلوهم كيف شاؤوا، ونهبوا البلد وخَرَّبوه، وساروا إلى ساوة ففعلوا بها كذلك، ثمَّ إلى قم وقاشان، وكانتا قد سَلِمَتا من التتر أولًا، فإنَّهم لم يقربوهما، ولا أصاب أهلَهما أذًى، فأتاهما هؤلاء وملكوهما، وقتلوا أهلَهما، وخَرَّبوها، وألحقوهما بغيرِهما من البلاد الخراب، ثم ساروا في البلادِ يُخرِبون ويقتلون وينهَبون، ثم قصدوا همذان، وكان قد اجتمع بها كثيرٌ ممن سَلِمَ من أهلها، فأبادوهم قتلًا وأسرًا ونهبًا، وخرَّبوا البلد، وكانوا لَمَّا وصلوا إلى الريِّ رأوا بها عسكرًا كثيرًا من الخوارزمية، فكَبَسوهم وقتلوا منهم، وانهزم الباقون إلى أذربيجان، فنزلوا بأطرافِها، فلم يَشعُروا إلا والتترُ أيضًا قد كبسوهم ووضعوا السيفَ فيهم، فولوا منهزمين، فوصل طائفةٌ منهم إلى تبريز، وأرسلوا إلى صاحِبِها أوزبك بن البهلوان يقولون: إن كنتَ موافِقَنا فسَلِّمْ إلينا من عندك من الخوارزمية، وإلا فعرفنا أنك غير موافقٍ لنا، ولا في طاعتِنا، فعمد إلى من عنده من الخوارزمية فقتل بعضَهم وأسر بعضهم، وحمل الأسرى والرؤوس إلى التتر، وأنفذ معها من الأموال والثياب والدواب شيئًا كثيرًا، فعادوا عن بلاده نحو خراسان، فعلوا هذا وليسوا في كثرة، كانوا نحو ثلاثة آلاف فارس، وكان الخوارزمية الذين انهزموا منهم نحو ستة آلاف راجل، وعسكر أوزبك أكثرُ من الجميع، ومع هذا فلم يحَدِّثْ نَفسَه ولا الخوارزمية بالامتناع منهم."},{"id":2431,"title":"حصر الكرج (الجورجيون، سكان جورجيا) مدينة كنجة .","date":["العام الهجري :622","العام الميلادي :1225"],"text":"سارت الكرج (وهم قوم كفار) في جموعِها إلى مدينة كنجة من بلاد أران قصدًا لحصرها، وأعتَدُوا لها بما أمكنهم من القوة؛ لأن أهل كنجة كثيرٌ عددهم، قويةٌ شوكتُهم، وعندهم شجاعةٌ كثيرة من طول ممارستهم للحرب مع الكرج، فلما وصلوا إليها ونازلوها قاتلوا أهلها عدة أيام من وراء السور، لم يظهر من أهلها أحد، ثم في بعض الأيام خرج أهل كنجة ومن عندهم من العسكر من البلد، وقاتلوا الكرج بظاهر البلد أشدَّ قتال وأعظَمَه، فلما رأى الكرج ذلك علموا أنهم لا طاقةَ لهم بالبلد، فرحلوا بعد أن أثخن أهل كنجة فيهم، {وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْرًا} [الأحزاب: 25]"},{"id":2432,"title":"خلع ابن شروان شاه لأبيه وظفر الأبن بالكرج (جورجيا) .","date":["العام الهجري :622","العام الميلادي :1225"],"text":"ثار على شروان شاه ولده فنزع منه الملك، وأخرجه من البلاد، ومَلَك بعده، وسبب ذلك أن شروان شاه كان سيئ السيرة، كثيرَ الفساد والظلم، يتعرض لأموال الرعايا وأملاكهم، وقيل أيضًا: إنه كان يتعرض للنِّساء والولدان، فاشتدت وطأتُه على الناس، فاتفق بعضُ العسكر مع ولده، وأخرجوا أباه من البلاد، وملك الابن وأحسن السيرة، فأحبه العساكر والرعيَّة، وأرسل الولد إلى أبيه يقول له: إني أردتُ أن أتركك في بعض القلاعِ وأجري لك الجرايات الكثيرة، ولكلِّ مَن تحب أن يكون عندك، والذي حملني على ما فعلتُ معك سوءُ سيرتك وظُلمُك لأهل البلاد، وكراهيتُهم لك ولدولتك, فلما رأى الأب ذلك سار إلى الكرج، واستصرخ بهم وقرَّرَ معهم أن يرسلوا معه عسكرًا يعيدونَه إلى ملكه، ويعطيهم نصفَ البلاد، فسيروا معه عسكرًا كثيرًا، فسار حتى قارب مدينة شروان، فجمع ولدُه العسكر، فخرج في عسكره، وهم قليل، نحو ألف فارس، ولقوا الكرجَ وهم في ثلاثة آلاف مقاتل، فالتقوا واقتتلوا، وصبَرَ أهل شروان، فانهزم الكرج، فقُتِلَ كثير منهم، وأُسِرَ كثير، ومن سلم عاد بأسوأ حال، وشروان شاه المخلوع معهم، فتشاءم الكرجُ منه فطردوه عن بلادِهم، واستقَرَّ ابنه في الملك، واغتبط الناسُ بولايته."},{"id":2433,"title":"محاصرة الكرج (الجورجيون، سكان جورجيا) لأذربيجان .","date":["العام الهجري :622","العام الميلادي :1225"],"text":"سار جمع من الكرج الكفار من تفليس يقصدون أذربيجان والبلاد التي بيد أوزبك بن البهلوان، فنزلوا وراء مضيقٍ في الجبال لا يسلك إلا للفارس بعد الفارس، فنزلوا آمنين من المسلمين استضعافًا لهم، واغترارًا بحصانة موضعِهم، وأنه لا طريقَ إليهم، وركب طائفةٌ من العساكر الإسلامية وقصدوا الكرج، فوصلوا إلى ذلك المضيق، فجاوزوه مخاطرينَ، فلم يشعر الكرج إلا وقد غَشِيَهم المسلمون ووضعوا فيهم السيفَ فقتلوهم كيف شاؤوا، وولى الباقون منهزمين وأُسرَ منهم جمع كثير، فعظم الأمر عليهم، وعزموا على الأخذ بثأرهم، والجِدِّ في قصد أذربيجان واستئصال المسلمين منه، وأخذوا يتجهَّزون على قدر عَزمِهم، فبينما هم في ذلك إذ وصل إليهم الخبَرُ بوصول جلال الدين بن خوارزم شاه إلى مراغة، فتركوا ذلك وأرسلوا إلى أوزبك، صاحب أذربيجان، يدعونه إلى الموافقة على ردِّ جلال الدين، وقالوا: إن لم نتَّفِق نحن وأنت وإلا أخذك ثمَّ أخَذَنا، فعاجلهم جلال الدين قبل اتفاقِهم واجتماعِهم."},{"id":2434,"title":"تخلي الموحدين عن إسبانيا وقيام عدة دويلات .","date":["العام الهجري :622","العام الميلادي :1225"],"text":"كانت دولة الموحِّدين قد قَوِيَت أولًا في إسبانيا، ولكنها لم تستطع أن تقف لوحدها في وجه التوسع الصليبي بصورة دائمة، كما لم يدُمْ صمودهم طويلًا إثر ذلك النصر الذي أحرزوه في معركة الأرك سنة 591 فقد جاءت هزيمتهم الماحقة في معركة العقاب سنة 609 على أيدي تحالف ملوك الصليبيين في إيبيريا، والذي نجم عنه انسحاب الموحدين نهائيًّا من إسبانيا وانكماش آخر سلاطينهم إلى المغرب، وضَعْف شوكتهم عمومًا حتى في المغرب. ونشوء إمارات بني مرين في فاس، والحفصيين في تونس، وبني زيان في تلمسان، وبني هود في مرسية بالأندلس."},{"id":2435,"title":"عودة جنكيزخان إلى منغوليا بعد أن قضى على دولة خوارزم .","date":["العام الهجري :622","العام الميلادي :1225"],"text":"بعد أن قضى جنكيزخان على دول خوارزم شاه وفعل ما فعله من القبائح والرذائل، عاد إلى بلاده وخاصة أنه سمع أنَّه قد ثار عليه فيها البعضُ يريدون إزالتَه من ملكه، فبقي في مسيره ذلك سنتين ووصل إلى بلاده، فاشتغل بإنهاء تلك الثورة، ثم أخلد للراحةِ وممارسة هواية الصيدِ."},{"id":2436,"title":"وفاة الملك الأفضل علي بن صلاح الدين الأيوبي .","date":["العام الهجري :622","الشهر القمري : صفر","العام الميلادي :1225"],"text":"هو السُّلطانُ الملك الأفضل علي بن يوسف بن أيوب بن شاذي. ابن السلطان الملك الناصر صلاح الدين، ولد يوم عيد الفطر سنة 565 بالقاهرة، وقيل: سنة ست وستين. وسمع من عبد الله بن بري النحوي، وأبي الطاهر إسماعيل بن عوف الزهري، وأجاز له جماعة. وله شِعر حسن، وترسُّل، وخط مليح. وكان أسنَّ إخوانه، وإليه كانت ولاية عهد أبيه. ولما مات أبوه، كان معه بدمشق، فاستقل بسلطنتها، واستقل أخوه الملك العزيز بمصر، وأخوهما الظاهر بحلب. ثم جرت للأفضل والعزيز فتن وحروب، ثم اتفق العزيز وعمه الملك العادل على الأفضل، وقصدا دمشق، وحاصراه، وأخذاها منه، فالتجأ إلى صرخد، وأقام بها قليلًا، فمات العزيز بمصر، وقام ولده المنصور محمد وهو صبي، فطلبوا له الملك الأفضل ليكون أتابكه، فقدم مصر، ومشى في ركاب الصبي. ثم إن العادل عَمِلَ على الأفضل، وقَدِمَ مصر وأخذها، ودفع إلى الأفضل ثلاثة مدائن بالشرق، فسار إليها، فلم يحصل له سوى سميساط، فأقام بها ولم يزَلْ بها إلى أن توفي بها، وكان خيرًا، وما أحسن ما قال القاضي الفاضل: \"أمَّا هذا البيت، فإن الآباء منه اتَّفقوا فمَلَكوا، والأبناء منه اختلفوا فهلكوا\". قال الذهبي: \"كان فيه تشيُّع\". وقد قال ابن الأثير \" إنَّه ما ملك الأفضل شيئًا من البلاد إلا وأخذه عمُّه منه، بل ذكر أنه رأى عمودًا من الرخام الفاخر في بيت المقدس فقيل له إنه كان للأفضل، ثم أخذه منه عمه العادل\"، ولما مات الأفضل اختلف أولاده وعمهم قطب الدين موسى، ولم يقوَ أحد منهم على الباقين ليستبدَّ بالأمر."},{"id":2437,"title":"استحواذ جلال الدين بن خوارزم شاه على بلاد أذربيجان .","date":["العام الهجري :622","الشهر القمري : رجب","العام الميلادي :1225"],"text":"استحوذ جلالُ الدين بن خوارزم شاه على بلاد أذربيجان وكثيرٍ من بلاد الكرج، وكسر الكرجَ وهم في سبعين ألف مقاتل، فقتل منهم عشرين ألفًا من المقاتلة، واستفحل أمره جدًّا وعظم شأنه، وفتح تفليس فقتل منها ثلاثين ألفًا، وقتل من الكرج سبعين ألفًا في المعركة، وقتل من تفليس تمامَ المائة ألف، وقد اشتغل بهذه الغزوة عن قصد بغداد، وذلك أنه لما حاصر دقوقا سبَّه أهلها ففتحها قسرًا وقتل من أهلها خلقًا كثيرًا، وخرب سورها وعزم على قصد الخليفةِ ببغداد؛ لأنه فيما زعم عمل على أبيه حتى هلك، واستولت التتر على البلاد، وكتب إلى المعظَّم بن العادل يستدعيه لقتال الخليفة ويحَرِّضه على ذلك، فامتنع المعظَّم من ذلك، ولما علم الخليفة بقصد جلال الدين بن خوارزم شاه بغداد انزعجَ لذلك وحصن بغداد واستخدم الجيوشَ والأجناد، وأنفق في الناس ألف ألف دينار، وكان جلال الدين قد بعث جيشًا إلى الكرج فكتبوا إليه أن أدرِكْنا قبل أن نهلك عن آخرنا، وبغداد ما تفوتُ، فسار إليهم."},{"id":2438,"title":"وفاة الخليفة العباسي الناصر لدين الله وتولي ابنه الظاهر بأمر الله .","date":["العام الهجري :622","الشهر القمري : رمضان","العام الميلادي :1225"],"text":"هو الخليفة الناصر لدين الله أبو العباس أحمد بن المستضيء بأمر الله أبي محمد الحسن بن المستنجد بالله يوسف بن المقتفي محمد بن المستظهر بالله أحمد بن المقتدي الهاشمي، العباسي، البغدادي. ولد في عاشر رجب، سنة 553.كان أبيض معتدل القامة، تركيَّ الوجه، مليح العينين، أنور الجبهة، أقنى الأنف، خفيف العارضين، أشقر، رقيق المحاسن، نَقشُ خاتمه: رجائي من الله عَفوُه. وبويع في أول ذي القعدة سنة 575، وكانت خلافته ستًّا وأربعين سنة وعشرة أشهر وثمانية وعشرين يومًا، فلم يلِ الخلافةَ أطولَ مدة منه إلَّا ما قيل عن المستنصر بالله العُبيدي، صاحب مصر، فإنَّه ولي ستين سنة، ولا اعتبارَ به، فإنَّه ولي وله سبع سنين، وكذا ولي الأندلس عبد الرحمن الناصر خمسين سنة. كان المستضيء والد الناصر قد تخوَّف منه فحَبَسَه، ومال إلى أخيه أبي منصور، وكان ابن العطار وكبراء الدولة ميلهم إلى أبي منصور، وكانت حظية المستضيء بنفشا والدة الناصر, والمجد بن الصاحب وطائفة مع الناصر، فلما بويع قبض على ابن العطار، وقتله, ثم سحب في الشوارع ميتًا، وطغى ابن الصاحب إلى أن قُتِل. قال الموفق عبد اللطيف: كان الناصر شابًّا مرحًا عنده ميعة الشباب، يشقُّ الدروب والأسواق أكثر الليل، والناس يتهيبون لقياه، وكان الرفضُ قد ظهر بسبب ابن الصاحب، ثم انطفأ بهلاكه وظهر التسنن، ثم زال, وقد خطب الناصر بولاية العهد لولده الأكبر أبي نصر، ثم ضيَّق عليه لما استشعر منه، وعيَّن أخاه، وأخذ خطًّا باعتراف أبي نصر بالعجز، أفسد ما بينهما النصير بن مهدي الوزير، وأفسد قلوب الرعية والجند على الناصر وبَغَّضَه إلى الملوك، وزاد الفساد، ثم قبض على الوزير، وتمكن بخراسان أيام الناصر خوارزمشاه محمد بن تكش وتجبَّرَ واستعبد الملوك وأباد الأمم من الترك والخطا، وظلم وعسف، وقطع خطبة الناصر من بلاده، ونال منه، وقصد بغداد، وجمع الناصرُ الجيش وأنفق الأموال، واستعد، فجاءت الأخبار إلى خوارزمشاه أن التتر قد حشدوا، وطمعوا في بلاده، فكرَّ إليهم وقصدهم فقصدوه وكثروه إلى أن مزَّقوه، وبلبلوا لبَّه وشتتوا شمله، وملكوا الأقطار، وصار أين توجَّه وجد سيوفَهم متحكمة فيه، وتقاذفت به البلاد، فشَرَّق وغرب، وأنجدَ وأسهَل، وأصحَرَ وأجبَلَ، والرعب قد زلزل لبه، فعند ذلك قضى نحبه. وقد جرى له ولابنه جلال الدين منكوبرتي عجائب. قال الموفق: \"لم يزل الناصر في عز وقمع الأعداء، ولا خرج عليه خارجيٌّ إلا قمعه، ولا مخالفٌ إلا دمغه، ولا عدوٌّ إلا خُذِل، كان شديد الاهتمام بالمُلك، لا يخفى عليه كبيرُ شيء من أمور رعيته، أصحاب أخباره في البلاد، حتى كأنه شاهد جميعَ البلاد دفعة واحدة، كانت له حِيَل لطيفة، وخُدَع لا يفطِنُ إليها أحد، يوقع صداقةً بين ملوك متعادين، ويوقع عداوةً بين ملوك متوادين ولا يفطِنون. إلى أن قال: ولما دخل رسولُ صاحب مازندران بغداد كانت تأتيه كل صباح ورقة بما فعل في الليل، فصار يبالغ في التكتم، واختلى ليلة بامرأة فصبحته ورقة بذلك، فتحيَّرَ، وخرج لا يرتاب أن الخليفة يعلم الغيب, وجاءه مرة رسول لخوارزم شاه فحبس أشهرًا ثم أعطي عشرة آلاف دينار فذهب وصار مناصحًا للخليفة. وكان الناصرُ إذا أطعم أشبع، وإذا ضرب أوجع. قلت (الذهبي): أظنُّه كان مخدومًا من الجنِّ, وما تحت هذا الفعل طائلٌ، فكلُّ مخدوم وكاهن يتأتى له أضعاف ذلك. قال الموفق عبد اللطيف: وفي وسط ولايته اشتغل بروايةِ الحديث، واستناب نوابًا يروونَ عنه، وأجرى عليهم جراياتٍ، وكتب للملوك والعلماء إجازات، وجمع كتابًا سبعين حديثًا وصل على يد السهروردي إلى حلب فسمعه الظاهر، وجماهير الدولة وشرحته. قلت (الذهبي): ممن يروي عن الناصر بالإجازة عبد الوهاب بن سكينة، وابن الأخضر، وقاضي القضاة ابن الدامغاني، وولي عهده الظاهر بأمر الله, والملك العادل، وبنوه، وشيخانا: محمود الزنجاني، والمقداد القيسي. قال ابن النجار: \"شرفني الناصر بالإجازة، ورويت عنه بالحرمين ودمشق والقدس وحلب، وبغداد وأصبهان، ونيسابور ومرو وهمذان\", قال الموفق: \"وكان الناصرُ قد ملأ القلوب هيبةً وخيفةً، حتى كان يرهبُه أهل الهند، وأهل مصر، فأحيا هيبة الخلافة، لقد كنت بمصر وبالشام في خلوات الملوك والأكابر إذا جرى ذكره خفضوا أصواتَهم إجلالًا له\". قال ابن النجار: \"دانت السلاطين للناصر، ودخل في طاعتِه مَن كان من المخالفين، وذُلِّلت له العتاة والطغاة، وانقهرت بسيفه الجبابرة، واندحض أعداؤه، وكثُر أنصاره، وفتح البلاد العديدة، ومَلَك من الممالك مالم يملكْه أحد ممن تقدمه من الخلفاء والملوك، وخطب له ببلاد الأندلس وبلاد الصين, وبعث صلاح الدين الأيوبي برايته وترسه للخليفة دليلًا على تبعيته- وكان أسد بني العباس تتصدع لهيبته الجبال، وتذل لسطوته الأقيال، وكان حسن الخلق أطيف الخلق، كامل الظرف، فصيحًا بليغًا، له التوقيعات المسددة والكلمات المؤيدة، كانت أيامه غرة في وجه الدهر، ودرة في تاج الفخر\" وكان لا يخلو من قبح السيرة في رعيته، والتعدي على أموالهم، كما اتهم بخراب العراق في أيامه، وأنه هو من أطمع التتار بالبلاد من كثرة ما فعله وما تلهى به، بقي الناصر لدين الله في آخر عمره ثلاث سنين عاطلًا عن الحركة بالكلية، وقد ذهبت إحدى عينيه والأخرى يبصر بها إبصارًا ضعيفًا، ثم أصابه دوسنطاريا (وهو مرض عدم استطاعة التبول) عشرين يومًا، ومات في شهر رمضان، وكان عمره نحو سبعين سنة تقريبًا، وقد كانت سنة 585 الخطبة للأمير أبي نصر محمد بن الخليفة الناصر لدين الله بولاية العهد في العراق وغيره من البلاد، ثم بعد ذلك خلعه الخليفةُ من ولاية العهد، وأرسل إلى البلاد في قطعِ الخطبة له، وإنما فعل ذلك لأنه كان يميل إلى ولَدِه الصغير علي، فاتفق أن الولد الصغير توفي سنة 612، ولم يكن للخليفة ولد غير ولي العهد، فاضطر إلى إعادته، إلا أنه تحت الاحتياط والحجر لا يتصرف في شيءٍ، فلما توفي أبوه وليَ الخلافة، وأحضر الناس لأخذ البيعة، وتلقَّب بالظاهر بأمر الله، وعلم أنَّ أباه وجميع أصحابه أرادوا صرفَ الأمر عنه، فظهر وولي الخلافة بأمر الله لا بسعي أحدٍ، ولَمَّا ولي الخلافة أظهر من العدل والإحسان ما أعاد به سنَّة العُمَرين."},{"id":2439,"title":"إيقاع جلال الدين خوارزم شاه بالتركمان الإيوانية .","date":["العام الهجري :623","العام الميلادي :1226"],"text":"كان التركمان الإيوانية قد تغلَّبوا على مدينة أسنة وأرمية، من نواحي أذربيجان، وأخذوا الخراجَ من أهلِها ليكفُّوا عنهم، واغتروا باشتغال جلال الدين بالكرج، وبُعدِهم بخلاط، وازداد طمعُهم، وانبسطوا بأذربيجان ينهبون، ويقطعون الطريقَ، والأخبار تأتي إلى جلال الدين بن خوارزم شاه، وهو يتغافل عنهم لاشتغاله بما هو المهمُّ عنده، فلما اشتد ذلك على الناس وعظُمَ الشَّرُّ أرسلت زوجة جلال الدين ابنة السلطان طغرل ونوابه في البلاد إليه يستغيثون، ويعرفونَه أن البلاد قد خربها الإيوانية، ولئن لم يلحَقْها وإلا هلكت بالمرَّة، فاتفق هذا إلى خوفِ الثلج، فرحل عن خلاط، وجدَّ السير إلى الإيوانية، وهم آمنون مطمئنون؛ لعِلمِهم أن خوارزم شاه على خلاط، وظنوا أنَّه لا يفارِقُها، فلم يَرُعْهم إلا والعساكر الجلالية قد أحاطت بهم، وأخذهم السَّيفُ من كل جانب، فأكثروا القتلَ فيهم، والنهبَ والسبي، واسترقُّوا الحريم والأولاد، وأخذوا من عندهم ما لا يدخلُ تحت الحصر، فرأوا كثيرًا من الأمتعة التي أخذوها من التجَّار بحالها في الشذوات، هذا سوى ما كانوا قد حلوه وفصلوه، فلما فرغ عاد إلى تبريز."},{"id":2440,"title":"الصلح بين الأخوين المعظم والأشرف الأيوبيين .","date":["العام الهجري :623","العام الميلادي :1226"],"text":"كان بين المعظم والأشرف خلافٌ سَبَبُه أنَّه لَمَّا توفِّيَ الملك العادل أبو بكر بن أيوب، اتفق أولاده الملوك بعده اتفاقًا حسنًا، وهم: الملك الكامل محمد، صاحب مصر، والملك المعظم عيسى، صاحب دمشق، والملك الأشرف موسى، صاحب ديار الجزيرة وخلاط، واجتمعت كلمتُهم على دفع الفرنج عن الديار المصريَّة، ولما رحل الكامل عن دمياط لما كان الفرنج يحصُرونَها، صادفه أخوه المعظَّم من الغد، وقَوِيَت نفسه، وثَبَتت قدمه، ولولا ذلك لكان الأمر عظيمًا، ثم إنَ المعظم لما عاد من مصر سار إلى أخيه الأشرف ببلاد الجزيرة مرَّتين يستنجده على الفرنج، ويحثُّه على مساعدة أخيهما الكامل، ولم يزل به حتى أخذه وسارا إلى مصر، وأزالوا الفرنجَ، فلما فارق الفرنجُ مصرَ وعاد كل من الملوك أولاد العادل إلى بلده بَقُوا كذلك يسيرًا، ثم سار الأشرفُ إلى أخيه الكامل بمصر، فاجتاز بأخيه المعظَّم بدمشق، فلم يستصحِبْه معه، وأطال المقامَ بمصر، فساء المعظَّم ذلك، ثم إن المعظَّم سار إلى مدينة حماة وحصرها، فأرسل إليه أخوه من مصرَ ورحَّلاه عنها كارهًا، فازداد نفورًا، وقيل: إنَّه نقل إليه عنهما أنهما اتفقا عليه، والله أعلم بذلك، ثم انضاف إلى ذلك أن الخليفة الناصر لدين الله، كان قد استوحش من الكامِلِ؛ لِما فعله ولده صاحِبُ اليمن من الاستهانة بأمير الحاج العراقي، فأعرض عنه وعن أخيه الأشرف لاتفاقِهما، وقاطعهما وراسل مظفر الدين كوكبري بن زين الدين علي، صاحب إربل، يعلِمُه بانحرافه عن الأشرف، واستمالَه واتفقا على مراسلة المعظَّم وتعظيم الأمر عليه، فمال إليهما وانحرف عن إخوته، ثم اتفَقَ ظهور جلال الدين وكثرةُ ملكه، فاشتد الأمرُ على الأشرف بمجاورة جلال الدين خوارزم شاه ولاية خلاط، ولأنَّ المعظم بدمشق يمنع عنه عساكرَ مصر أن تصِلَ إليه، وكذلك عساكر حلب وغيرها من الشام، فرأى الأشرفُ أن يسير إلى أخيه المعظَّم بدمشق، فسار إليه في شوال واستماله واصطلح معه، فلما سمع الكامل بذلك عظم عليه، ثم إنهما راسلاه وأعلماه بنزول جلال الدين على خلاط، وعظَّما الأمر عليه، وأعلماه أن هذه الحال تقتضي الاتفاق لعمارة البيت العادلي، وانقضت السنةُ والأشرف بدمشق والناس على مواضِعِهم ينتظرون خروجَ الشتاء ما يكون من الخوارزميين."},{"id":2441,"title":"الفتنة بين الفرنج والأرمن .","date":["العام الهجري :623","العام الميلادي :1226"],"text":"جمع البرنس الفرنجي، صاحب أنطاكية، جموعًا كثيرة وقصد الأرمن الذين في الدروب بلاد ابن ليون، فكان بينهم حربٌ شديدةٌ، وسَبَبُ ذلك أنَّ ابن ليون الأرمني، صاحِبَ الدروب، توفِّيَ قبلُ ولم يخلف ولدًا ذكرًا، إنما خلف بنتًا، فملَّكَها الأرمنُ عليهم، ثمَّ عَلِموا أنَّ المُلكَ لا يقومُ بامرأة، فزوجوها من ولد البرنس، فتزوجَّها، وانتقل إلى بلَدِهم، واستقَرَّ في الملك نحو سنة، ثم نَدِموا على ذلك، وخافوا أن يستولي الفرنجُ على بلادهم، فثاروا بابن البرنس، فقَبَضوا عليه وسجنوه، فأرسل أبوه يطلبُ أن يُطلَق ويعاد في المُلك، فلم يفعلوا، فأرسل إلى بابا ملك الفرنجِ برومية الكبرى يستأذنُه في قصد بلادهم، ومِلك روميَّة، فمنعه عنهم، فخالفه وأرسلَ إلى علاء الدين كيقباذ ملك قونية وملطية وما بينهما من بلاد المسلمين، وصالحه، ووافقه على قصدِ بلاد ابن ليون، والاتفاق على قصدها، فاتفقا على ذلك، وجمع البرنس عساكره ليسير إلى بلاد الأرمن، فخالف عليه الداوية والاسبتارية، وهما جمرة الفرنج، فدخل أطراف بلاد الأرمن، وهي مضايق وجبال وعْرة، فلم يتمكَّن مِن فِعلِ ما يريد، وأمَّا كيقباذ، فإنه قصدَ بلاد الأرمن من جهتِه، وهي أسهَلُ من جهة الشام، فدخلها سنة 622، فنهبها، وأحرقها، وحصر عِدَّة حصون، ففتح أربعةَ حصون، وأدركه الشتاءُ فعاد عنها، فلما سَمِعَ بابا ملك الفرنج برومية أرسل إلى الفرنج بالشام يُعلِمُهم أنَّه قد أصدر صك حرمان بحق البرنس، فكان الداوية والاسبتارية وكثيرٌ من الفرسان لا يحضُرونَ معه، ولا يسمعون قوله، وكان أهل بلاده، وهي أنطاكية وطرابلس، إذا جاءهم عيد يخرجُ من عندهم، فإذا فرغوا من عيدهم دخل البلد، ثم إنه أرسل إلى ملك رومية يشكو من الأرمن، وأنَّهم لم يطلقوا ولده، ويستأذنه في أن يدخلَ بلادَهم ويحاربَهم إن لم يطلقوا ابنه، فأرسل إلى الأرمن يأمرُهم بإطلاق ابنه وإعادته إلى الملك، فإن فعلوا وإلَّا فقد أذن له في قصدِ بلادهم، فلما بلغَتْهم الرسالةُ لم يطلقوا ولده، فجمع البرنس وقصد بلادَ الأرمن، فأرسل الأرمن إلى الأتابك شهاب الدين بحلب يستنجدونَه، ويخيفونَه من البرنس إن استولى على بلادِهم لأنها تجاور أعمال حلب، فأمدهم بجند وسلاح، فلما سمع البرنس ذلك صمم العزمَ على قصد بلادهم، فسار إليهم وحاربَهم، فلم يحصل على غرض، فعاد عنهم."},{"id":2442,"title":"جلال الدين خوارزم شاه يمتلك مدينة تفليس .","date":["العام الهجري :623","الشهر القمري : ربيع الأول","العام الميلادي :1226"],"text":"فتح جلال الدين بن خوارزم شاه مدينة تفليس من الكرج في ثامن ربيع الأول، وقد كانت الحرب بينه وبينهم من السنة الماضية، وقد انهزموا منه، ثم عاد إلى تبريز بسبب الخلاف الواقع فيها، فلما استقرَّ الأمر في أذربيجان عاد إلى بلد الكرج هذه السنة، فقصد بلادَهم، وقد عادوا فحشدوا وجمعوا من الأمم المجاورة لهم اللان واللكز وقفجاق وغيرهم، فاجتمعوا في جمعٍ كثير لا يحصى، فطمعوا بذلك، فلَقِيَهم وجعل لهم الكمينَ في عدة مواضع، والتَقَوا واقتَتَلوا، فولى الكرج منهزمين وأخذتهم سيوفُ المسلمين من كل جانبٍ، فلم ينجُ منهم إلا اليسيرُ الشاذُّ الذي لا يعبأ به، وأمر جلال الدين عسكَرَه ألَّا يُبقوا على أحدٍ، وأن يقتلوا من وجدوا، فتبعوا المنهزمين يقتلونهم، وأشار عليه أصحابُه بقصد تفليس دار مُلكِهم، فقال: لا حاجة لنا إلى أن نقتُلَ رجالَنا تحت الأسوار، إنَّما إذا أفنيت الكرج أخذت البلاد صفوًا عفوًا، ولم تزل العساكرُ تَتبَعُهم وتستقصي في طلبِهم إلى أن كادوا يفنونَهم، فحينئذ قصد تفليس ونزل بالقرب منها، وسار في بعض الأيامِ في طائفة من العسكر، وقصدها لينظُرَ إليها، ويبصر مواضِعَ النزول عليها، وكيف يقاتِلُها، فلما قاربها كمن أكثرُ العسكر الذي معه في عدة مواضع، ثم تقدَّم إليها في نحو ثلاثة آلاف فارس، فلمَّا رآه من بها من الكرج طَمِعوا فيه لقِلَّةِ من معه، ولم يعلموا بمن معه، فظهروا إليه فقاتلوه، فتأخر عنهم، فقويَ طَمَعُهم فيه لقِلَّةِ من معه، فظنُّوه منهزمًا، فتبعوه، فلما توسطوا العساكِرَ خرجوا عليهم ووضعوا السيف فيهم، فقُتِل أكثَرُهم، وانهزم الباقون إلى المدينة فدخلوها، وتبعهم المسلمون، فلمَّا وصلوا إليها نادى المسلمون من أهلها بشعار الإسلام، وباسمِ جلال الدين، فألقى الكرج بأيديهم واستسلموا؛ لأنهم كانوا قد قتل رجالهم في الوقعات السابقة، فقل عددُهم، وملئت قلوبُهم خوفًا ورعبًا، فملك المسلمون البلد عَنوةً وقهرًا بغير أمان، وقُتِلَ كلُّ من فيه من الكرج، ولم يبق على كبير ولا صغير إلا من أذعن بالإسلام، وأقرَّ بكلمتي الشهادة، فإنَّه أبقى عليه، وأمرهم فتختَّنوا وتركهم، ونهب المسلمون الأموال، وسَبَوا النساء واستَرَقُّوا الأولاد، ووصل إلى المسلمين الذين بها بعض الأذى من قتلٍ ونهب وغيره، وتفليس هذه من أحصَنِ البلاد وأمنعها، وهي على جانبي نهر الكر، وهو نهر كبير، ولقد جلَّ هذا الفتح وعظُمَ مَوقِعُه في بلاد الإسلامِ وعند المسلمين؛ فإنَّ الكرجَ كانوا قد استطالوا عليهم، وفعلوا بهم ما أرادوا، فكانوا يقصِدونَ أيَّ بلاد أذربيجان أرادوا، فلا يمنَعُهم عنها مانع، ولا يدفَعُهم عنها دافعٌ."},{"id":2443,"title":"عصيان بمدينة كرمان على جلال الدين خوارزم شاه .","date":["العام الهجري :623","الشهر القمري : جمادى الآخرة","العام الميلادي :1226"],"text":"وصل الخبَرُ إلى جلال الدين أن نائبه بكرمان، وهو أميرٌ كبير اسمه بلاق حاجب، قد عصى عليه، وطَمِعَ في أن يتملَّك البلاد ويستبِدَّ بها لبُعدِ جلال الدين عنها، واشتغاله بالكرج وغيرهم، وأنه أرسل إلى التتر يعَرِّفُهم قوة جلال الدين ومُلكَه كثيرًا من البلاد، وإن أخذ الباقي عَظُمَت مملكته، وكثُرَت عساكره، وأخذَ ما بأيديكم من البلاد. فلما سمع جلال الدين ذلك كان قد سار يريد خلاط، فتركها وسار إلى كرمان يطوي المراحِلَ، وأرسل بين يديه رسولًا إلى صاحِبِ كرمان، ومعه الخِلَع ليطمَئِنَّ ويأتيه وهو غيرُ محتاط ولا مستعِدٍّ للامتناع منه، فلما وصل الرسول عَلِمَ أن ذلك مكيدةٌ عليه لِما يَعرِفُه من عادته، فأخذ ما يعِزُّ عليه، وصعد إلى قلعةٍ منيعةٍ فتحَصَّن بها، وجعل من يثقُ به من أصحابه في الحصونِ يمتَنِعون بها، وأرسل إلى جلال الدين يقول: إنَّني أنا العبد والمملوك، ولما سمعت بمسيرك إلى هذه البلاد أخليتُها لك؛ لأنَّها بلادك، ولو علمتُ أنَّك تبقي علي لحضرتُ بابك، ولكنِّي أخاف هذا جميعَه، والرسولُ يحلف له أنَّ جلال الدين بتفليس، وهو لا يلتَفِتُ إلى قوله، فعاد الرسول، فعلم جلالُ الدين أنه لا يمكِنُه أخذ ما بيده من الحصونِ؛ لأنه يحتاج أن يحصُرَها مدة طويلة، فوقف بالقُربِ من أصفهان، وأرسل إليه الخِلَع، وأقرَّه على ولايته, فبينما الرسل تتردد إذ وصل رسولٌ مِن وزير جلالِ الدين إليه من تفليس يعَرِّفُه أن عسكر الملك الأشرفِ الذي بخلاط قد هَزَموا بعض عسكره وأوقعوا بهم، ويحثُّه على العود إلى تفليس فعاد إليهم مُسرعًا."},{"id":2444,"title":"مسير مظفر الدين صاحب إربل إلى الموصل وعوده عنها .","date":["العام الهجري :623","الشهر القمري : جمادى الآخرة","العام الميلادي :1226"],"text":"استقرَّت القاعدة بين مظفر الدين بن زين الدين، صاحب إربل وبين جلال الدين بن خوارزم شاه وبين الملك المعظَّم، صاحب دمشق، وبين صاحِبِ آمد، وبين ناصر الدين، صاحب ماردين، ليقصِدوا البلادَ التي بيد الأشرف، ويتغلَّبوا عليها، ويكون لكُلٍّ منهم نصيبٌ، فبادر مظفر الدين إلى الموصِل, وأمَّا جلال الدين فإنَّه قد شُغِلَ بعصيان نائبه ببلاد كرمان، فانفسخ جميعُ ما كانوا عزموا عليه إلَّا أن مظفر الدين سار من إربل ونزل على جانب الزابن ولم يمكِنْه العبور إلى بلد الموصل, وكان بدرُ الدين قد أرسل من الموصل إلى الأشرف، وهو بالرقَّة، يستنجده ويطلُبُ منه أن يحضُرَ بنفسه الموصِلَ ليدفع مظفر الدين، فسار منها إلى حرَّان، ومن حران إلى دنيسر، فخربَ بلد ماردين وأهله تخريبًا ونهبًا, وأما المعظَّم، صاحب دمشق، فإنه قصد بلادَ حِمص وحماة، وأرسل إلى أخيه الأشرف ليرحلَ عن ماردين وحلب، على أن يعودَ كُلٌّ منهم إلى بلده. فرحل الأشرفُ عن ماردين، ورحل المعظَّم عن حمص وحماة، ورحل مظفَّر الدين عن الموصل."},{"id":2445,"title":"وفاة الخليفة العباسي الظاهر بأمر الله ومبايعة ابنه المستنصر بالله .","date":["العام الهجري :623","الشهر القمري : رجب","العام الميلادي :1226"],"text":"هو الخليفة الإمام الظاهر بأمر الله أبو نصر محمد بن الناصر لدين الله أبي العباس أحمد بن المستضيء بأمر الله أبي محمد الحسن ابن المستنجد بالله يوسف بن المقتفي محمد بن المستظهر بالله أحمد بن المقتدي الهاشمي، العباسي، البغدادي. ولد سنة 571. بايع له أبوه بولاية العهد في سنة 585، وخطب له على المنابر، ونثر عند ذكره الدنانير وعليها اسمُه. ولم يزل الأمر على ذلك حتى قطع ذلك أبوه في سنة 601, وخلعه وأكرهه، وزوى الأمر عنه إلى ولده الآخر. فلما مات ذلك الولد، اضطُرَّ أبوه إلى إعادته، فبايع له وخطب له في شوال سنة 618. واستخلف عند موت والده. قال ابن الساعي: حضرت بيعةَ العامَّة، فلما رُفِعَت الستارة، شاهدتُه وقد كمل الله صورتَه ومعناه، وعمُرُه إذ ذاك خمس وثلاثون سنة، وكان أبيض مشربًا حمرة، أزج الحاجبين، أدعج العينين، سهل الخدين، أقنى، رحب الصدر، عليه قميص أبيض، وعليه طرحة قصب بيضاء\" وكان نعم الخليفة، جمع الخشوعَ مع الخضوع لربِّه، والعدل ولم يزَلْ كل يوم يزداد من الخير والإحسان إلى الرعية, فقد أبطل المكوس، وأزال المظالم، وفرَّق الأموال. روى عن والده بالإجازة قبل أن يستخلِفَ, وكانت خلافتُه تسعة أشهر وأربعة وعشرين يومًا، ولَمَّا توفي الظاهر بأمر الله بويع بالخلافة ابنه الأكبر أبو جعفر المنصور، ولقب المستنصر بالله، وسلك في الخير والإحسان إلى الناس سيرة أبيه، وأمر فنودي ببغداد بإفاضة العدل، وأن من كان له حاجة، أو مظلمة يطالع بها، تُقضى حاجتُه، وتُكشَف مظلمتُه، فلما كان أول جمعة أتت على خلافته أراد أن يصليَ الجمعة في المقصورة التي كان يصلي فيها الخلفاء، فقيل له إن المطبق- طريق تحت الأرض- الذي يسلكه إليها خراب لا يمكن سلوكُه، فركب فرسًا وسار إلى الجامع، جامع القصر، ظاهرًا يراه الناسُ بقميص أبيض وعمامة بيضاء، ولم يترك أحدًا يمشي معه بل أمر كل من أراد أن يمشي معه من أصحابِه بالصلاة في الموضِعِ الذي كان يصلي فيه، وسار هو ومعه خادمان وركابدار لا غير، وكذلك الجمعة الثانية حتى أصلح له المطبق."},{"id":2446,"title":"الحرب بين كيقباذ وصاحب آمد .","date":["العام الهجري :623","الشهر القمري : شعبان","العام الميلادي :1226"],"text":"سار علاء الدين كيقباذ بن كيخسرو بن قلج أرسلان، مَلِكُ بلاد الروم، إلى بلاد الملك المسعود بن مودود، صاحِبِ آمد، ومَلَكَ عِدَّةً مِن حصونه، وسببُ ذلك اتفاق صاحب آمد مع جلال الدين بن خوارزم شاه والملك المعظم، صاحب دمشق، وغيرهما على خلاف الأشرف؛ فلما رأى الأشرف ذلك أرسل إلى كيقباذ، ملك الروم، وكانا متفقَينِ، يطلب منه أن يقصِدَ بلد صاحب آمد ويحاربَه، وكان الأشرفُ حينئذ على ماردين، فسار ملك الرومِ إلى ملطية، وهي له، فنزل عندها، وسيَّرَ العساكر إلى ولاية صاحب آمد، ففتحوا حصن منصور وحصن سمكاراد وغيرهما؛ فلمَّا رأى صاحب آمد ذلك راسل الأشرف، وعاد إلى موافقتِه، فأرسل الأشرفُ إلى كيقباذ يعرِّفُه ذلك، ويقول له ليعيد إلى صاحب آمد ما أخذَ منه، فلم يفعل، وقال: لم أكن نائبًا للأشرَفِ يأمرني وينهاني، فاتفَقَ أن الأشرف سار إلى دمشق ليصالح أخاه الملك المعظَّم، وأمر العساكر التي له بديار الجزيرة بمساعدة صاحب آمد، إن أصرَّ ملك الروم على قَصْدِه، فسارت عساكِرُ الأشرف إلى صاحب آمد وقد جمع عسكَرَه، ومن ببلاده ممن يَصلُح للحرب وسار إلى عسكر ملك الروم وهم يحاصِرونَ قلعة الكختا بعد الهزيمة، وهي من أمنع الحصونِ والمعاقل، فلما ملكوها أعادوها إلى صاحبها."},{"id":2447,"title":"حصر جلال الدين بن خوارزم شاه مدينتي آني وقرس وخلاط .","date":["العام الهجري :623","الشهر القمري : رمضان","العام الميلادي :1226"],"text":"عاد جلال الدين بن خوارزم شاه من كرمان، إلى تفليس، وسار منها إلى مدينة آني، وهي للكرج، وبها إيواني مقدَّم عساكر الكرج فيمن بقي معه من أعيان الكرج، فحصره وسيَّرَ طائفةً مِن العسكر إلى مدينة قرس، وهي للكرج أيضًا، وكلاهما من أحصَنِ البلاد وأمنَعِها، فنازلهما وحصَرَهما، وقاتل من بهما، ونصَبَ عليهما المجانيقَ، وجدَّ في القتال على مدينتي آني وقرس، وبالغ الكرج في حفظِهما والاحتياطِ لهما لخوفِهم منه أن يفعَلَ بهما ما فعل بأشياعِهم مِن قبلُ بمدينة تفليس، وأقام عليهما إلى أن مضى بعضُ شوال، ثم ترك العسكَرَ عليهم يحصرونَهم وعاد إلى تفليس، وسار من تفليس مجدًّا إلى بلاد أبخاز وبقايا الكرج، فأوقعَ بمن فيها، فنهب وقتل وسبى، وخرَّب البلادَ وأحرقها، وغَنِمَ عساكرُه ما فيها، وعاد منها إلى تفليس، أما خلاط فإنَّ جلال الدين عاد من مدينة آني إلى تفليس ودخل بلاد أبخاز، وكان رحيلُه مكيدةً؛ لأنَّه بلغه أن النائِبَ عن الملك الأشرف، وهو الحاجب حسام الدين علي بمدينة خلاط، قد احتاط واهتم بالأمر وحفظ البلد لقُربِه منه، فعاد إلى تفليس ليطمَئِنَّ أهل خلاط ويتركوا الاحتياطَ والاستظهارَ ثم َّيقصِدَهم بغتة؛ وسار مجدًّا فوصل الخبَرُ إليهم قبل وصوله بيومين، ووصل جلالُ الدين فنازل مدينة ملازكرد يوم السبت ثالث عشر ذي القعدة، ثم رحل عنها؛ فنازل مدينة خلاط يوم الاثنين خامس عشر ذي القعدة، فلم ينزل حتى زحف إليها، وقاتل أهلها قتالًا شديدًا، فوصل عسكرُه سور البلد، وقُتِلَ بينهم قتلٌ كثير، ثم زحف إليها مرة ثانية، وقاتل أهل البلد قتالًا عظيمًا، فعَظُمت نكايةُ العسكر في أهل خلاط، ووصلوا إلى سور البلد، ودخلوا الربضَ الذي له، ومدوا أيديَهم في النهب وسبي الحريم، فلمَّا رأى أهل خلاط ذلك تذامروا، وحَرَّضَ بعضهم بعضًا، فعادوا إلى العسكَرِ فقاتلوهم فأخرجوهم من البلد، وقُتِل بينهم خلق كثير، وأسر العسكرُ الخوارزمي من أمراء خلاط جماعةً، وقُتِلَ منهم كثيرٌ، ثمَّ إن جلال الدين استراح عدَّة أيام، وعاود الزحفَ مثل أول يوم، فقاتلوه حتى أبعدوا عسكره عن البلد، ثم أقام عليها إلى أن اشتَدَّ البرد، ونزل شيءٌ من الثلج، فرحل عنها يوم الثلاثاء لسبعٍ بَقِين من ذي الحجة من السنة، وكان سببُ رحيله مع خوف الثلج ما بلغه عن التركمان الإيوانية من الفسادِ ببلاده."},{"id":2448,"title":"نهب جلال الدين بن خوارزم شاه بلاد الإسماعيلية .","date":["العام الهجري :624","العام الميلادي :1226"],"text":"قتل الإسماعيلية أميرًا كبيرًا من أمراء جلال الدين، وكان قد أقطعه جلالُ الدين مدينةَ كنجة وأعمالها، فلما قُتِلَ ذلك الأميرُ عَظُم قَتلُه على جلال الدين، واشتد عليه، فسار في عساكرِه إلى بلاد الإسماعيلية، مِن حدود ألموت إلى كردكوه بخراسان، فخرب الجميعَ، وقتل أهلَها، ونهب الأموالَ، وسبى الحريمَ، واسترقَّ الأولادَ، وقتل الرجالَ، وعَمِلَ بهم الأعمالَ العظيمةَ وانتقم منهم، وكانوا قد عَظُمَ شَرُّهم وازداد ضَرُّهم، وطمعوا منذ خرج التتر إلى بلاد الإسلامِ إلى الآن، فكَفَّ عاديتَهم وقمَعهم، ولقَّاهم اللهُ ما عملوا بالمسلمينَ."},{"id":2449,"title":"الحرب بين جلال الدين بن خوارزم شاه والتتر .","date":["العام الهجري :624","العام الميلادي :1226"],"text":"لما فرغ جلال الدين من الإسماعيلية بلغه الخبَرُ أن طائفةً مِن التتر عظيمةً قد بلغوا إلى دامغان، بالقُربِ من الري، عازمينَ على قصدِ بلاد الإسلام، فسار إليهم وحاربَهم، واشتَدَّ القتال بينهم، فانهزموا منه، فأوسعَهم قتلًا، وتَبِعَ المنهزمين عدَّة أيام يقتُلُ ويأسِرُ، فبينما هو كذلك قد أقام بنواحي الري خوفًا من جمع آخرَ للتتر، إذ أتاه الخبَرُ بأن كثيرًا منهم واصلون إليه، فأقام ينتَظِرُهم. حتى لقيهم سنة 625."},{"id":2450,"title":"خلاف بين أبناء العادل الأيوبي وأثره في مواجهة الحملة الصليبية .","date":["العام الهجري :624","العام الميلادي :1226"],"text":"تأكدت الوحشةُ بين الكامل وبين أخويه المعظَّم والأشرف، وخاف الكامِلُ من انتماء أخيه المعظم إلى السلطان جلال الدين بن خوارزم شاه، فبعث الكامِلُ الأمير فخر الدين يوسف بن شيخ الشيوخ صدر الدين بن حمويه إلى ملك الفرنج، يريدُ منه أن يَقدَم إلى عكا، ووعده أن يعطيه بعض ما بيد المسلمين من بلاد الساحل، ليشغلَ سِرَّ أخيه المعظم، فتجهَّز إمبراطور الألمان فردريك الثاني لقصد الساحل، وبلغ ذلك المعظَّم، فكتب إلى السلطان جلال الدين يسألُه النجدة على أخيه الكامل، ووعده أن يخطُبَ له، ويضرب السكَّة باسمه، فسيَّرَ إليه جلال الدين خِلعةً لبسها، وشَقَّ بها دمشق، وقطع الخطبة للملك الكامل، فبلغ ذلك الكامل، فخرج من القاهرة بعساكره، ونزل بلبيس في شهر رمضان فبعث إليه المعظم: إني نذرتُ لله تعالى أنَّ كُلَّ مرحلة ترحلها لقصدي أتصدَّقُ بألف دينار، فإنَّ جميع عسكرك معي، وكتُبُهم عندي، وأنا آخُذُك بعسكرِك، وكتب المعظَّم مكاتبةً بهذا في السر، ومعها مكاتبةٌ في الظاهِرِ فيها: بأني مملوكُك، وما خرجتُ عن محبَّتِك وطاعتك، وحاشاك أن تخرجَ وتقابلني، وأنا أوَّلُ من أنجَدَك وحضر إلى خدمتِك من جميع ملوك الشام والشرق، فأظهر الكامِلُ هذا بين الأمراء، ورجع من العباسة إلى قلعة الجبلِ، وقبض على عدَّة من الأمراء ومماليك أبيه، لمكاتبتِهم المعظَّم، واعتقلهم وأخذ سائر موجودِهم، وأنفق في العسكر ليسيرَ إلى دمشق."},{"id":2451,"title":"دخول الكرج (وهم الجورجيون، سكان جورجيا) مدينة تفليس وإحراقها .","date":["العام الهجري :624","الشهر القمري : ربيع الأول","العام الميلادي :1227"],"text":"وصل الكرج مدينةَ تفليس، ولم يكُنْ بها من العسكَرِ الإسلاميِّ من يقومُ بحمايتها، وسبَبُ ذلك أنَّ جلال الدين لَمَّا عاد من خلاط، وأوقع بالإيوانية، فرق عساكره إلى المواضع الحارة الكثيرة المرعى، ليشتُوا بها، وكان عسكره قد أساؤوا السيرةَ في رعية تفليس، وهم مسلمون، وعَسَفوهم، فكاتبوا الكرج يستدعونَهم إليهم، ليملِّكوهم البلد، فاغتنم الكرج ذلك؛ لميل أهل البلدِ إليهم، وخَلَّوه من العسكر، فاجتمعوا، وكانوا بمدينتي قرس وآني وغيرهما من الحصون، وساروا إلى تفليس، وكانت خاليةً، ولأن جلال الدين استضعف الكرجَ لكثرة من قُتِلَ منهم، ولم يظنَّ فيهم حركة، فملكوا البلد، ووضعوا السيفَ فيمن بقي من أهلها، وعَلِموا أنَّهم لا يقدرون على حفظ البلدِ مِن جلال الدين، فأحرقوها، وأمَّا جلال الدين فإنه لما بلغه الخبَرُ سار فيمن عنده من العساكر ليدرِكَهم، فلم يرَ منهم أحدًا، كانوا قد فارقوا تفليس لَمَّا أحرقوها."},{"id":2452,"title":"نشأة الدولة الحفصية على يد أبي زكريا الحفصي .","date":["العام الهجري :624","الشهر القمري : شعبان","العام الميلادي :1227"],"text":"بعد أنْ تولَّى أمرَ دولة الموحدينَ أبو محمد العادل بن أبي يوسف يعقوب المنصور سنة 621هـ (1224م) عهد بولاية إفريقيَّةَ إلى أبي محمَّد عبد الله بن عبد الواحد بن أبي حفص، وكان في صحبته أخوه أبو زكريا يحيى، وقام الوالي الجديدُ بإعادة الهدوء والاستقرارِ بعد أن عكَّرت صفوَها الفتنُ والثَّورات، وقام بحَمَلات على الخارجينَ على سلطان الدولة، وما كادت الأمورُ تستقرُّ حتى قفز على منصبِ حُكم الموحِّدين أبو العلاء إدريس المأمون سنة 624 هـ (1227م) بعد ثورة قادها ضدَّ أخيه أبي محمد العادل، فرفض أبو محمد عبد الله الحفصي بيعتَه والدُّخولَ في طاعته، فما كان من حاكِمِ الموحِّدين الجديدِ إلَّا أن كتب بولاية إفريقية إلى أبي زكريا يحيى، فقَبِلَها على الفور وسار من تونس إلى القيروان، وتغلَّب على أخيه أبي محمد عبد الله، وتولى أمر البلاد سنة 625 هـ (1228م) وكانت سن أبي زكريا يوم بدأ حكمه سبعًا وعشرين سنة، لكن ما أظهَرَه من أول وهلة من براعة ومقدرة كان يدلُّ على ما يتمتَّعُ به من نضجٍ سياسيٍّ، ومهارة إداريَّة، وسبق له أن حكمَ في منطقة إشبيليَّة بالأندلس؛ حيث كان واليًا على بعضِ المقاطعاتِ هناك. وبعد قليلٍ مِن ولايته خلع أبو زكريا طاعةَ أبي العلاء إدريس حاكِمِ الموحدين، ولكنَّه لم يدعُ لنفسه بالأمر؛ تحسبًا للموحِّدينَ الذين كانوا في ولايته، واتخذَ تونس عاصمة له، وبدأ في اكتساب محبَّة أهل إفريقيَّة باتباعِ سياسة معينة، فأحسن معاملتَهم، وخفَّف عنهم أعباءَ الضرائب، ونظر في أمورِهم، وراقبَ عُمَّاله وولاتَه، واستعان بأهل الخبرة والكفاءة، وقرَّب الفقهاءَ إليه، فأسلَمَت له البلاد قيادَها ودانت له بالطاعة والولاء. ثم نهض أبو زكريا لإقرار سُلطانِه وبَسطِ نفوذه في المناطق المجاورة، فزحف بجيشِه إلى قسنطينة بالجزائر، فدخلها دون صعوبةٍ، وخرج أهلُها لمبايعته في شعبان 626 هـ (1229م)، ثم اتجه إلى بجاية ففتحها ودخلت في سلطانه، وبذلك خرجت الولايتان من سلطان دولة الموحدين، وأصبحتا تابعتين لأبي زكريا، ثم طاف بالنواحي الشَّرقية من ولايته، واستوثق من طاعة أهلِها. وكان ردُّ الموحدينَ على توسعات أبي زكريا على حساب دولتِهم ضعيفًا للغاية، بل يكاد يكونُ معدومًا، ولم يستطع حكَّام الموحدين أن يمنعوا تفكُّكَ دولتهم، أو يقضوا على الحركاتِ الانفصاليَّة، فكانت الدولةُ مشغولةً بالفِتَن والثورات التي تهب في الأندلُسِ، بل في مراكشَ عاصمةِ دولتِهم."},{"id":2453,"title":"دخول عساكر الملك الأشرف الأيوبي إلى أذربيجان .","date":["العام الهجري :624","الشهر القمري : شعبان","العام الميلادي :1227"],"text":"سار الحاجب علي حسام الدين، وهو النائب عن الملك الأشرف بخلاط، والمقدَّم على عساكرِها، إلى بلاد أذربيجان فيمن عندَه من العساكر، وسببُ ذلك أنَّ سيرة جلال الدين كانت جائرةً، وعساكرُه طامعةً في الرعايا، وكانت زوجتُه ابنةَ السلطان طغرل السلجوقي، وهي التي كانت زوجةَ أوزبك بن البهلوان، صاحب أذربيجان، فتزوجَّها جلال الدين، وكانت مع أوزبك تحكُم في البلاد جميعها، ليس له ولا لغيره معها حكمٌ، فلما تزوجها جلال الدين أهملها ولم يلتَفِتْ إليها، فخافته مع ما حُرِمَته من الحكم والأمر والنهي، فأرسلَت هي وأهل خُوَيٍّ إلى حسام الدين الحاجب يستدعونَه ليسَلِّموا البلاد، فسار ودخل البلاد، بلاد أذربيجان، فمَلَك مدينة خوي وما يجاورها من الحصون التي بيد امرأة جلال الدين، وملك مَرَنْدَ، وكاتبه أهلُ مدينة نقجوان، فمضى إليهم، فسَلَّموها إليه، وقَوِيَت شوكتُهم بتلك البلاد."},{"id":2454,"title":"مقتل العادل الموحدي وانقسام دولة الموحدين .","date":["العام الهجري :624","الشهر القمري : شوال","العام الميلادي :1227"],"text":"قُتل العادِلُ الموحدي عبد الله بن يعقوب المنصور بن يوسف بن عبدالمؤمن بن علي, فقد كان أميرًا على شرقيِّ الأندلس وجاءته بيعةُ أهل مراكش بعد خلع عمه عبد الواحد، ففوض الأمرَ إلى أخيه أبي العلاء وقصد مراكش ثمَّ اضطربت عليه الأمورُ وقامت فِتَنٌ، فدعا أخوه أبو العلاء لنفسه في إشبيلية وأخذ البيعةَ وتلقب بالمأمون، وأرسل إلى مراكش يدعوهم إلى بيعته، وأعلمهم أن أهلَ الأندلسِ معه، فخلع أهلُ مراكش العادل بعد أن طلبوا منه أن يخلعَ نفسَه، فلم يفعل فقتلوه وبايعوا يحيى المعتصم بالله بن محمد الناصر بن أبي يوسف يعقوب المنصور، فأصبح لدولة الموحدين دولتان وملكان."},{"id":2455,"title":"وفاة الملك المعظم صاحب دمشق وملك ولده داود .","date":["العام الهجري :624","الشهر القمري : ذي القعدة","العام الميلادي :1227"],"text":"هو المَلِكُ المعَظَّم شرفُ الدين عيسى بن الملك العادل كان عاليَ الهمة حازمًا شجاعًا مهيبًا فاضلًا جامعًا شَملَ أرباب الفضائل محبًّا لهم، كانت مملكتُه متسعة من حدود بلد حمص إلى العريش يدخل في ذلك بلاد الساحل الإسلامية منها، وبلاد الغور وفلسطين والقدس والكرك والشوبك وصرخد وغير ذلك. توفي يوم الجمعة آخر ذي القعدة، وكان مرضُه دوسنطاريا، وكان ملكُه لمدينة دمشق، من حين وفاة والده الملك العادل، عشر سنين وخمسة أشهر وثلاثة وعشرين يومًا، وكان في الفقه على مذهب أبي حنيفة متعصبًا لمذهبه، فإنه كان قد اشتغل به كثيرًا، وصار من المتميزين فيه، ولم يكن في بني أيوب حنفيٌّ سواه، وتبعه أولاده، وكان يحب الأدبَ كثيرًا واشتغل بعلم النحو اشتغالًا زائدًا، وصار فيه فاضلًا، وكذلك اللغة وغيرها، وقيل إنه كان قد شرط لكلِّ من يحفظ \"المفصَّل\" للزمخشري مائة دينار وخلعة، فحفظه لهذا السبب جماعة، ورأيت بعضَهم بدمشق، والناس يقولون: إن سبب حفظهم له كان هذا، وقيل إنَّه لما توفي كان قد انتهى بعضُهم إلى أواخره وبعضُهم في أثنائه، وهم على قدر أوقاتِ شروعهم فيه، ولم يُسمَعْ بمثل هذه المنقبة لغيره. وكان يقولُ كثيرًا: إن اعتقادي في الأصول ما سطره أبو جعفر الطحاوي، ووصى عند موته بأن يكَفَّن في البياض، ولا يجعل في أكفانه ثوبٌ فيه ذهب، وأن يُدفَن في لحد، ولا يبنى عليه بناءٌ، بل يكون قبره في الصحراء تحت السماء، ولما توفي ولي بعده ابنُه داود وتلقب بالملك الناصر، وكان عمرُه قد قارب عشرين سنة."},{"id":2456,"title":"قيام دولة بني حفص (الحفصيون) في تونس .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"استقَلَّ بنو حفص عن دولة الموحِّدين بعد أن انقسمت دولتُهم: قِسمٌ في الأندلس، وقِسمٌ في مراكش، فأطمعهم ذلك بالافتراق عنهم فأقاموا دولةً لهم بزعامةِ أبي زكريا يحيى الأوَّل بن أبي حفص الهتاني، واستمرَّت دولتُهم هذه إلى عام 981."},{"id":2457,"title":"هلاك جنكيزخان وانقسام الإمبراطورية المغولية بين أبنائه الأربعة .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"هو جنكيزخان السلطان الأعظم عند التتار والدُ ملوكهم، واسمه تموجين وقيل (تمرجين أو تمرجي) ولد في غرة محرم سنة 550 في منغوليا على الضفة اليمنى لنهر الأونون في مقاطعة دولون بولداق وهذه المقاطعة توجد اليوم في الأراضي الروسية. وكان أبوه بسوكاي رئيسًا لقبيلة قيات المغولية فسمَّاه باسم قائد صرعه؛ لأنَّه كان معجبًا به لفرط شجاعته, وقيل: \"إنَّ أمَّه كانت تزعمُ أنها حملته من شعاع الشمس؛ فلهذا لا يُعرَفُ له أب، ولهذا قد يكون مجهولَ النسب\". لما مات بسوكاي سنة 563 حل محلَّه تمرجين وكان عمره ثلاثة عشر عامًا إلَّا أن رجال قبيلته استصغروا سنَّه ورفضوا طاعته, حينما بلغ السابعةَ عشرة من عمره استطاع بقوَّة شخصيته وحِدَّة ذكائه أن يعيدَ رجال قبيلته إلى طاعته وأن يُخضِعَ المناوئين له حتى تمَّت له السيطرة, وأصبح تمرجين بعد انتصاره أقوى شخصية مغولية، فنودي به خاقانًا، وعُرف باسم \"جنكيز خان\" أي: إمبراطور العالم. وهو صاحب \"التورا\" و\"اليسق أو الياسق\"، وضعه ليتحاكم إليه التتار ومن معهم من أمراء الترك, والتورا باللغة التركية هو المذهب، واليسق هو الترتيب، وأصل كلمة اليسق: سي يسا، وهو لفظ مركب من أعجمي وتركي، ومعناه: التراتيب الثلاث؛ لأن \" سي \" بالعجمي في العدد ثلاثة، و\" يسا \" بالتركي: الترتيب؛ وعلى هذا مشت التتار منذ أن وضعه لهم جنكيز خان، وانتشر الياسق في سائر الممالك حتى ممالك مصر والشام، وصاروا يقولون: \" سي يسا \" فثقلت عليهم فقالوا: \" سياسة \" على تحاريف العرب في اللغات الأعجمية لهم السياسا التي يتحاكمون إليها، ويحكمون بها، وأكثرها مخالف لشرائع الله تعالى وكتبه، وهو شيء اقترحه من عند نفسه، وتَبِعوه في ذلك, وقد عظُمَ أمر جنكيزخان وبعُدَ صِيتُه وخضعت له قبائلُ الترك ببلاد طمغاج كلها، حتى صار يركَبُ في نحو ثمانمائة ألف مقاتل، وأكثَرُ القبائل قبيلته التي هو منها يقال لهم قيان، ثم أقرب القبائلِ إليه بعدهم قبيلتان كبيرتا العدد، وهما أزان وقنقوران، وكان يصطاد من السنة ثلاثة أشهر، والباقي للحرب والحكم، فلما هلك جعلوه في تابوت من حديد وربطوه بسلاسل وعلقوه بين جبلين, وأما كتابُه الياسا فإنه يكتب في مجلدين بخط غليظ، ويُحمَل على بعير عندهم، وقد ذكَرَ بعضُهم أنه كان يصعد جبلًا ثم ينزل. ثم يصعدُ ثم ينزل مرارًا حتى يعيى ويقع مغشيًّا عليه، ويأمر من عنده أن يكتبَ ما يلقى على لسانه حينئذٍ، فإن كان هذا هكذا فالظاهر أن الشيطانَ كان ينطق على لسانِه بما فيها، واستمر أولاد جنكيزخان في ممالكه التي قسمها عليهم في حياته، ولم يختلف منهم واحد على واحد، ومشوا على ما أوصاهم به، وعلى طريقته \" التورا \" و\" اليسق \" ولما احتُضر أوصى أولاده بالاتفاق وعدم الافتراق، وضرب لهم في ذلك الأمثال، وأحضر بين يديه نشابًا وأخذ سهمًا أعطاه لواحد منهم فكسره، ثم أحضر حزمة ودفعها إليهم مجموعة فلم يطيقوا كسرَها، فقال: هذا مثَلُكم إذا اجتمعتم واتَّفقتم، وذلك مثلُكم إذا انفردتُم واختلفتُم، قال: وكان له عِدَّةُ أولاد ذكور وإناث، منهم أربعة هم عظماء أولاده، أكبرهم يوسي وهريول وباتو وبركة وتركجار، وكان كل منهم له وظيفة عنده. قال ابن كثير: \" وقد رأيت مجلدًا ببغداد جمعه الوزير علاء الدين الجويني في ترجمة جنكيز خان، ذكر فيه سيرته، وما كان يشتَمِلُ عليه من العقل السياسي والكرم والشجاعة والتدبير الجيد للملك والرعايا، والحروب, وذكر فيه نتفًا من الياسا من ذلك: أنه من زنا قتل، محصنًا كان أو غير محصن، وكذلك من لاط قُتل، ومن تعمد الكذب قُتل، ومَن سحر قُتل، ومن تجسَّس قُتل، ومن دخل بين اثنين يختصمان فأعان أحدَهما قُتل، ومن بال في الماء الواقف قُتل، ومن انغمس فيه قُتل، ومن أطعم أسيرًا أو سقاه أو كساه بغير إذن أهلِه قُتل.... \""},{"id":2458,"title":"ضم قبرص إلى المملكة الألمانية .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"توفي ملك قبرص هوك دولوزنيان وقد خلف ولدًا قاصرًا هو هنري الأول، فتولى الوصاية عليه فيليب إيبلان برضا أمه الملكة، فلما توفي فيليب انتقلت الوصاية إلى أخيه جان، لكن بغير رضا الملكة، وكان الملك فردريك الثاني قد مر على قبرص في طريقه إلى بلاد الشام، فاستعانت به الملكة ضد الوصي جان فاستولى فردريك على قبرص وضمها إلى مملكته الألمانية."},{"id":2459,"title":"ثورة ابن هود على الموحدين .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"استولى محمد بن يوسف بن هود من سلالة بني هود على مرسية، وطرد منها الموحدين، وأعلن طاعته للخليفة العباسي المستنصر بالله، وتلقب بالمتوكل على الله، ودخل في طاعته جيان وقرطبة وماردة وبطليوس وغيرها من المدن الإسبانية."},{"id":2460,"title":"نشأة محاكم التفتيش في إسبانيا .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"بدأ في هذا العام إنشاء محاكم التفتيش الصليبية على يد رجال الكنيسة الكاثوليكية لمحارة الخارجين على سيادة الكنيسة وسلطة البابا؛ حيث وصمت الكنيسة هؤلاء الخارجين على سيادتها من اليهود والنصارى بالكفر والانحراف والبدعة والهرطقة، وأصدرت قوانين التعذيب والقتل بأبشع صورة, وفي القرن الخامس عشر والسادس عشر سلطت هذه المحاكم زبانيتها على المسلمين الذين بقوا في الأندلس بعد سقوط حكم المسلمين فيها لردهم عن دينهم."},{"id":2461,"title":"الحرب بين جلال الدين والتتار وما وقع فيها من عجائب غريبة .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"عاود التتر الخروج إلى الري، وجرى بينهم وبين جلال الدين حروب كثيرة، كان أكثرها عليه، وفي الأخير كان الظفر له وكانت أول حرب بينهم فيها عجائب غريبة، وكان هؤلاء التتر قد سخط ملكُهم جنكيزخان على مُقدَّمهم، وأبعده عنه، وأخرجه من بلاده، فقصد خراسان، فرآها خرابًا، فقصد الريَّ ليتغلب على تلك النواحي والبلاد، فلقيه بها جلال الدين، فاقتتلوا أشدَّ قتال، ثم انهزم جلال الدين وعاد ثم انهزم، وقصد أصفهان، وأقام بينها وبين الري، وجمع عساكره ومَن في طاعته، فكان فيمن أتاه صاحب بلاد فارس، وهو ابن أتابك سعد ملك بعد وفاة أبيه، وعاد جلال الدين إلى التتر فلَقِيَهم، فبينما هم مصطفون كلُّ طائفة مقابل الأخرى انعزل غياث الدين أخو جلال الدين فيمن وافقه من الأمراء على مفارقةِ جلال الدين، واعتزلوا، وقصدوا جهةً ساروا إليها، فلما رآهم التتر قد فارقوا العسكر ظنُّوهم يريدون أن يأتوهم من وراء ظهورهم ويقاتلوهم من جهتين، فانهزم التتر لهذا الظنِّ وتَبِعَهم صاحب بلاد فارس، وأمَّا جلال الدين فإنه لما رأى مفارقة أخيه إياه ومن معه من الأمراء ظنَّ أن التتر قد رجعوا خديعة ليستدرجوه، فعاد منهزمًا، ولم يجسر أن يدخل أصفهان؛ لئلا يحصره التتر، فمضى إلى سميرم، وأما صاحب فارس فلما أبعد في أثر التتر، ولم ير جلال الدين ولا عسكره معه، خاف التتر فعاد عنهم، وأما التترُ فلما لم يروا في آثارهم أحدًا يطلبُهم وقفوا، ثم عادوا إلى أصفهان، فلم يجدوا في طريقهم من يمنَعُهم، فوصلوا إلى أصفهان فحصروها، وأهلها يظنون أنَّ جلال الدين قد عدم، فبينما هم كذلك والتتر يحصرونَهم إذ وصل قاصد من جلال الدين إليهم يعرفُهم سلامته، ويقول: إني أدور حتى يجتَمِعَ إليَّ من سلم من العسكر وأقصدُكم ونتفق أنا وأنتم على إزعاج التتر وترحيلهم عنكم، فأرسلوا إليه يستدعونه إليهم، ويعدونه النصرةَ والخروج معه إلى عدوه، وفيهم شجاعة عظيمة، فسار إليهم واجتمع بها، وخرج أهل أصفهان معه، فقاتلوا التتر، فانهزم التترُ أقبَحَ هزيمة، وتبعهم جلال الدين إلى الريِّ يقتُلُ ويأسر، فلما أبعدوا عن الري أقام بها، وأرسل إليه ابن جنكيزخان يقول: إن هؤلاء ليسوا من أصحابنا، إنما نحن أبعدناهم عنا، فلمَّا أمن جانب ابن جنكيزخان أمن وعاد إلى أذربيجان."},{"id":2462,"title":"خروج الفرنج إلى الشام وعمارة صيدا .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"خرج كثيرٌ من الفرنج من بلادهم، التي هي في الغرب من صقلية وما وراءها من البلاد، إلى بلادهم التي بالشام: عكا وصور وغيرهما من ساحل الشام، فكثُرَ جمعهم، وكان قد خرج قبل هؤلاء جمع آخر أيضًا إلا أنهم لم تمكِنْهم الحركة والشروع في أمر الحرب؛ لأجل أنَّ مَلِكَهم الذي هو المقدَّم عليهم هو ملك الألمان، ولأنَّ الملك المعظم عيسى بن العادل صاحب دمشق كان حيًّا، وكان شهمًا شجاعًا مقدامًا، فلما توفي المعظم، وولي بعده ابنُه وملك دمشق، طمع الفرنج، وظهروا من عكا وصور وبيروت إلى مدينة صيدا، وكانت مناصفة بينهم وبين المسلمين، وسورها خراب، فعمروها، واستولوا عليها، وإنما تمَّ لهم ذلك بسبب تخريب الحصون القريبة منها؛ تبنين وهونين وغيرهما، فعظمت شوكة الفرنج، وقوي طمعُهم."},{"id":2463,"title":"علاء الدين كيقباذ السلجوقي يمتلك مدينة أرزنكان .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"ملك علاء الدين كيقباذ بن كيخسرو بن قلج أرسلان- وهو صاحب قونية وما حولها من بلاد الروم- أرزنكان، وسبب ملكه إياها أن صاحبها بهرام شاه كان قد طال مُلكُه لها، وجاوز ستين سنة، توفي ولم يزل في طاعة قلج أرسلان وأولاده بعده، فلما توفي ملك بعده ولده علاء الدين داود شاه، فأرسل إليه كيقباذ يطلب منه عسكرًا ليسير معه إلى مدينة أرزن الروم- وهي قريبة من مدينة أرزنكان- ليحصرها، ويكون هو مع العسكر، ففعل ذلك، وسار في عسكره إليه، فلما وصل قبض عليه، وأخذ مدينة أرزنكان منه، وله حصنٌ من أمنع الحصون اسمه كماخ، وفيه مستحفظ لداود شاه، فأرسل إليه ملك الروم يحصُره، فلم يقدر العسكرُ على القرب منه؛ لعُلُوِّه وارتفاعه وامتناعه، فتهدَّد داود شاه إن لم يسلم كماخ، فأرسل إلى نائبه في التسليم، فسلم القلعةَ إلى كيقباذ، وأراد كيقباذ المسير إلى أرزن الروم ليأخُذَها وبها صاحبها ابن عمه طغرل شاه بن قلج أرسلان، فلما سمع صاحبها بذلك أرسل إلى الأمير حسام الدين علي، النائب عن الملك الأشرف بخلاط، يستنجِدُه، وأظهر طاعة الأشرف، فسار حسام الدين فيمن عنده من العساكر، وكان قد جمعها من الشام، وديار الجزيرة، خوفًا من ملك الروم، خافوا أنه إذا ملك أرزن الروم يتعدى ويقصد خلاط، فسار الحاجب حسام الدين إلى الروم ومنع عنها، ولما سمع كيقباذ بوصول العساكر إليها لم يُقدِم على قصدها، فسار من أرزنكان إلى بلاده، وكان قد أتاه الخبر أن الروم الكفار المجاورين لبلاده قد ملكوا منه حصنًا يسمى صنوب، وهو من أحصن القلاع، مطِلٌّ على البحر السياه بحر الخزر، فلما وصل إلى بلاده سيَّرَ العسكر إليه وحصره برًّا وبحرًا، فاستعاده من الروم، وسار إلى أنطاكية ليشتي بها على عادته."},{"id":2464,"title":"نهب جلال الدين خوارزم شاه بلاد أرمينية .","date":["العام الهجري :625","العام الميلادي :1227"],"text":"وصل جلال الدين خوارزم شاه إلى بلاد خلاط، وتعدى خلاط إلى صحراء موش، وجبل جور، ونهب الجميع، وسبى الحريم، واسترقَّ الأولاد، وقتل الرجال، وخرب القرى، وعاد إلى بلاده، ولما وصل الخبرُ إلى البلاد الجزرية: حران وسروج وغيرهما، أنَّه قد جاز خلاط إلى جور، وأنه قد قرب منهم، خاف أهل البلاد أن يجيء إليهم، لأنَّ الزمان كان شتاء، وظنُّوا أنه يقصد الجزيرة ليشتي بها، لأنَّ البرد بها ليس بالشديد، وعزموا على الانتقال من بلادهم إلى الشام، ووصل بعض أهل سروج إلى منبج من أرض الشام، فأتاهم الخبر أنه قد نهب البلاد وعاد، فأقاموا، وكان سبب عوده أن الثلج سقط ببلاد خلاط كثيرًا، لم يعهد مثله، فأسرع العودَ."},{"id":2465,"title":"خروج الملك الكامل صاحب مصر إلى الشام .","date":["العام الهجري :625","الشهر القمري : شوال","العام الميلادي :1228"],"text":"سار الملك الكامل محمد بن الملك العادل، صاحب مصر, فوصل إلى بيت المقدس, ثم سار عنه، وتولى بمدينة نابلس، وشحن على تلك البلاد جميعها، وكانت من أعمال دمشق، فلما سمع صاحبها، وهو ابن الملك المعظم، خاف أن يقصده ويأخذ دمشق منه، فأرسل إلى عمه الملك الأشرف يطلبه ليحضر عنده بدمشق، فسار إليه جريدة، فدخل دمشق، فلما سمع الكامل بذلك لم يتقدم لعِلمِه أن البلد منيع، وقد صار به من يمنعه ويحميه، وأرسل إليه الملك الأشرف يستعطفه، ويعرفه أنه ما جاء إلى دمشق إلا طاعة له، وموافقة لأغراضه، والاتفاق معه على منع الفرنج عن البلاد، فأعاد الكامل الجواب يقول: إنني ما جئت إلى هذه البلاد إلا بسبب الفرنج، وحيث قد حضرتَ أنت فأنا أعود إلى مصر، واحفظ أنت البلاد، ولستُ بالذي يقال عني إني قاتلت أخي، وحصرته، حاشا لله تعالى، وتأخر عن نابلس نحو الديار المصرية، ونزل تل العجول، فخاف الأشرف والناس قاطبة بالشام، وعلموا أنه إن عاد استولى الفرنجُ على بيت المقدس وغيره مما يجاوره، لا مانع دونه، فترددت الرسل وسار الأشرف بنفسه إلى الكامل أخيه، فحضر عنده، وكان وصوله ليلة عيد الأضحى، ومنعه من العود إلى مصر، فأقام بمكانِه."},{"id":2466,"title":"اتفاق يافا وتسليم الملك الكامل بيت المقدس للصليبيين .","date":["العام الهجري :626","العام الميلادي :1228"],"text":"بعد أن ترددت الرسل بين الملك الكامل صاحب مصر وفردريك الثاني ملك ألمانيا انتهوا على صلح عشر سنوات يسلم الكامل بيت المقدس للصليبيين نكاية بإخوانه في الشام بسبب خلاف بينه وبينهم, وجاء في بنود الاتفاق الذي عرف باتفاق يافا: 1/ أن ملك الفرنج يأخذ القدس من المسلمين، ويبقيها على ما هي من الخراب، ولا يجدد سورها. 2/ أن يكون سائر قرى القدس للمسلمين، لا حكم فيها للفرنج. 3/ أن الحرم بما حواه من الصخرة والمسجد الأقصى يكون بأيدي المسلمين، لا يدخله الفرنج إلا للزيارة فقط، ويتولاه والٍ من المسلمين، ويقيمون فيه شعار الإسلام من الأذان والصلاة. 4/ أن تكون القرى التي فيها بين عكا وبين يافا، وبين القدس، بأيدي الفرنج، دون ما عداها من قرى القدس. ثم في 22 ربيع الأول من هذه السنة، ( 18فبراير 1229 م) تسلم الفرنج بيت المقدس صلحًا، ولما تسلم الفرنج البيت المقدس، استعظم المسلمون ذلك وأكبروه واستقبحوا ما فعله الكامل، ووجدوا له من الوهن والتألم ما لا يمكن وصفه. وقد ذكر سبط ابن الجوزي ردة الفعل على تسليم الكامل بيت المقدس للصليبيين بقوله: \"قامت القيامة في جميع بلاد الإسلام، واشتدت العظائم، بحيث أقيمت المآتم، وأشار علي الملك الناصر داود بن الملك المعظم أن أجلس بجامع دمشق، وأذكر ما جرى على البيت المقدس، فما أمكنني مخالفته، ورأيت من جملة الديانة الحمية للإسلام موافقته، فجلست بجامع دمشق، وحضر الناصر داود، على باب مشهد علي، وكان يومًا مشهورًا، لم يتخلف من أهل دمشق أحد, وقد انقطعت عن البيت المقدس وفود الزائرين، فيا وحشة المجاورين، كم كان لهم في تلك الأماكن من ركعة، وكم خرت لهم على تلك المساكن من دمعة، والله لو صارت عيونهم عيونًا لما وفت، ولو تقطعت قلوبهم أسفًا لما شفت، أحسن الله عزاء المؤمنين، يا خجلة ملوك المسلمين لمثل هذه الحادثة تسكب العبرات، لمثلها تنقطع القلوب من الزفرات، لمثلها تعظم الحسرات\""},{"id":2467,"title":"الملك فردريك الثاني يتوج نفسه ملكا على القدس .","date":["العام الهجري :626","العام الميلادي :1228"],"text":"بعد أن تسلم فردريك الثاني ملك ألمانيا القدس على الاتفاق توج نفسه ملكًا على القدس بوصفه زوجًا للملكة إيزابيلا الثانية ملكة القدس ثم غادر فلسطين."},{"id":2468,"title":"استيلاء السلطان التتمش على البنجاب السفلي والعلوي .","date":["العام الهجري :626","العام الميلادي :1228"],"text":"انتهى حكم أيبك على هندستان في سنة 608 (1210م) وذلك على أثر سقوطه من على فرسه. أثناء لعبة الكرة أو البولو- جوكان- فتوفي على الأثر, وخلفه أحدُ مماليكه البارزين وزوج ابنته شمس الدين التتمش الذي سار سيرة حسنة في رعيته، واشتدَّ في رد المظالم وإنصاف المظلومين. فيؤثر عنه أنه أمر أن يلبس كلُّ مظلوم ثوبًا مصبوغًا. وأهل الهند جميعًا يلبسون البياض، فكان إذا قعد للنَّاسِ أو ركب، فرأى أحدًا عليه ثوب مصبوغ نظر في قضيته وأنصفه ممَّن ظلمه. وبلغ فوز السلطان التتمش أقصى مداه حينما اعترف به خليفة بغداد المستنصر بالله العباسي، سلطانًا على الهند، وبعث له بالتقليد والخِلَع والألوية في سنة 626 (1229 م)، فأصبح التتمش بذلك أول ملك في الهند تسلم مثل هذا التقليد. ومنذ ذلك التاريخ ضرب التتمش نقودًا فضية نقش عليها اسم الخليفة العباسي بجوار اسمه. ويعتبر هذا العمل شيئا جديدًا على نظام العملة الهندية؛ إذ كان الحكام المسلمون قبل ذلك يضربون نقودًا معدنية صغيرة على غرار النقود الوطنية، تنقش عليها أشكال مألوفة لدى الهنود، كثور سيفا مثلًا، كما كانت أسماء الفاتحين تكتب بحروف هندية في غالب الأحيان. فالتتمش يعتبر أول من ضرب نقودًا فضية خالصة في الهند."},{"id":2469,"title":"البابا يصدر حرمان من الكنسية ضد الملك فردريك ومنعه من بيت المقدس .","date":["العام الهجري :626","الشهر القمري : ربيع الأول","العام الميلادي :1229"],"text":"كان البابا غريغوريوس التاسع قد أصدر سابقًا سنة 623 صكًّا فيه حرمان الملك فردريك ملك ألمانيا من الكنيسة؛ وذلك بسبب تأخره عن تجهيز الحملة الصليبية السادسة، واعتذر بسبب مرضه وهذا لم يشفع له، ثم في هذا العام أصدر البابا صكًّا آخر فيه حرمان ثان؛ وذلك ليمنعه من تسلم بيت المقدس كما وعده الكامل صاحب مصر، وقام البابا أيضًا بمراسلة الكامل، وبيَّنَ له أن فردريك قد طرد من الكنيسة ولا يستحق أن يتسلم بيت المقدس."},{"id":2470,"title":"هدنة الملك الكامل الأيوبي مع الفرنج وتسليم القدس للصليبيين .","date":["العام الهجري :626","الشهر القمري : ربيع الآخر","العام الميلادي :1229"],"text":"بدأت الحملة الصليبية السادسة سنة 625 (1227م)كمحاولة لإعادة السيطرة على بيت المقدس. بدأت بعد سبع سنوات فقط من فشل الحملة الصليبية الخامسة التي ترأسها الإمبراطور فريدريك الثاني هوهنشتاوفن الألماني الذي نذر النذر الصليبي للحملة السابقة ولم يف به حينها، وأراد الإمبراطور أن يحقق مقاصده دون أن يسحب سيفه من غمده، فتزوج في صيف سنة 622 (1224م) من ابنة ملك بيت المقدس يوحنا دي بريان (يولاندي والمعروفة أيضًا باسم إيزابيلا) وتزوج كذلك من ماريا من مونتفيرات، وأخذ يطالب بعرش مملكة زالت من الوجود من زمان في فلسطين، واستغل الحرب بين الأيوبيين الملك الكامل صاحب مصر مع أخيه الملك المعظم صاحب دمشق ودخل في مفاوضات مع السلطان الكامل، الأمر الذي أثار غضب روما، وقيَّم البابا أونوريوس الثالث مسلك فريدريك الثاني بكل قساوة واتهمه بإهمال قضية الرب؛ بل إنه هدده بالحرمان من الكنيسة وفرض غرامة مقدارها 100 ألف أوقية من الذهب إذا لم تقم الحملة الصليبية في آخر المطاف، وقد أرجئ البدء بها إلى 624 (1226م) وبدأ فريدريك الثاني ببناء السفن واستأنفت روما في الدعوة إلى الحرب المقدسة، ولكن الدعوات قوبلت باللامبالاة، وفي هذه الأثناء، وقبل خمسة أشهر من الموعد المعين، توفي البابا أونوريوس الثالث. وفي صيف 624 (1226م) تجمع بضع عشرات من الآلاف من المجندين، معظمهم من ألمانيا والبقية من فرنسا وإنجلترا وإيطاليا في معسكر قرب برنديزي والبعض الآخر في أبحر صقلية، ولكن الأمراض وقلة المؤن ومرض فريدريك الثاني أدى إلى إرجاء الحملة، ولكن البابا الجديد غريغوريوس التاسع أصدر صك حرمان من الكنيسة بحق فريدريك الثاني، وتشفيًا بالبابا أبحر الإمبراطور فريدريك إلى سوريا 626 (1228م)، فكان من البابا أن منع الحملة الصليبية، ووصف فريدريك بأنه قرصان، وبأنه يريد سرقة مملكة القدس، فكانت أول حملة صليبية لا يباركها البابا، ولكن فريدريك الثاني لم يأبه فاستولى على قبرص ووصل إلى عكا، حيث بدأ المفاوضات مع السلطان الكامل أسفرت سنة 627 (1229م) عن صلح لمدة 10 سنوات تنازل بمقابله الملك الكامل عن بيت المقدس باستثناء منطقة الحرم، وبيت لحم والناصرة وجميع القرى المؤدية إلى القدس، وقسم من دائرة صيدا وطورون (تبنين حاليًّا)، وعزز الإمبراطور الألماني بعض الحصون والقلاع وأعاد تنظيمها، ووقع مع مصر عدّة اتفاقيات تجارية، وتعهد فريدريك الثاني بمساعدة الملك الكامل ضد أعدائه أيًّا كانوا، مسلمين أم نصارى، وضمن عدم تلقي القلاع الباقية خارج سيطرته أية مساعدة من أي مكان. ووقع الاتفاق الذي عرف باتفاق يافا."},{"id":2471,"title":"الملك الأشرف الأيوبي يمتلك مدينة دمشق .","date":["العام الهجري :626","الشهر القمري : شعبان","العام الميلادي :1229"],"text":"في يوم الاثنين ثاني شعبان مَلَك المَلِك الأشرف بن الملك العادل مدينة دمشق من ابن أخيه الملك الناصر صلاح الدين داود بن المعظم، وسبب ذلك أن صاحب دمشق لما خاف من عمِّه الملك الكامل أرسل إلى عمه الأشرف يستنجده، ويستعين به على دفع الكاملِ عنه، وسار صاحب دمشق إلى بيسان وأقام بها، وعاد الملك الأشرف من عند أخيه، واجتمع هو وصاحب دمشق، ولم يكن الأشرف في كثرة من العسكر، ووصلت العساكر من الكامل إلى الأشرف، وسار فنازل دمشق وحصرها، وأقام محاصرًا لها إلى أن وصل إليه الملك الكامل، فحينئذ اشتدَّ الحصار، وكان من أشد الأمور على صاحبها أن المال عنده قليل؛ لأنَّ أمواله بالكرك، ولوثوقه بعمه الأشرف لم يحضر منها شيئًا فاحتاج إلى أن باع حلي نسائِه وملبوسَهنَّ، وضاقت الأمور عليه، فخرج إلى عمِّه الكامل وبذل له تسليم دمشق وقلعة الشوبك على أن يكون له الكرك والغور وبيسان ونابلس، وأن يبقي على أيبك قلعة صرخد وأعمالها، وتسلم الكاملُ دمشق، وجعل نائبَه بالقلعة إلى أن سلم إليه أخوه الأشرف حران والرها والرقة وسروج ورأس عين من الجزيرة، فلما تسلَّم ذلك سلم قلعة دمشق إلى أخيه الأشرف، فدخلها وأقام بها، وسار الكامل إلى الديار الجزرية، فأقام بها إلى أن استدعى أخاه الأشرف بسبب حصر جلال الدين بن خوارزم شاه مدينة خلاط، فلما حضر عنده بالرقة عاد الكامل إلى ديار مصر."},{"id":2472,"title":"انتصار الملك الأشرف الأيوبي على خوارزم شاه بمدينة خلاط .","date":["العام الهجري :626","الشهر القمري : رمضان","العام الميلادي :1229"],"text":"نزل جلال الدين خوارزم شاه على خلاط وحاصرها وضايقها أشَدَّ مضايقة، وأخذَها من نواب الملك الأشرف، وهو مقيمٌ بدمشق، ولم يمكِنْه في ذلك الوقت قَصْدَها للدفع عنها لأعذارٍ كانت له. ثم عقيبَ ذلك دخل الأشرفُ بلاد الروم باتفاق مع سلطانِها علاء الدين كيقباذ، وتعاقدا على قصد خوارزم شاه، وضرب المصاف معه، فإن صاحب الروم كان يخاف على بلاده منه؛ لكونِه مجاوِرَه، فتوجَّها نحوه في جيش عظيم من جهة الشام والشرق في خدمة الملك الأشرف، وعسكر صاحب الروم، والتقوا بين خلاط وأرزنكان، بموضع يقال له: يا للرحمان في يوم الجمعة ثاني عشر رمضان سنة 627، وانكسر خوارزم شاه، وهي واقعة مشهورة، وعادت خلاط إلى الملك الأشرف وقد خربت."},{"id":2473,"title":"الملك الكامل الأيوبي يمتلك مدينة حماة .","date":["العام الهجري :626","الشهر القمري : رمضان","العام الميلادي :1229"],"text":"ملك الملك الكامل مدينة حماة، وسبب ذلك أنَّ الملك المنصور محمد بن تقي الدين عمر، وهو صاحب حماة، توفِّي، ولما حضرته الوفاة حلف الجندُ وأكابر البلد لولده الأكبر، ويلقب بالملك المظفَّر، وكان قد سيَّرَه أبوه إلى الملك الكامل، صاحب مصر، وكان لمحمَّد ولد آخر اسمه قلج أرسلان، ولقبه صلاح الدين، وهو بدمشق، فحضر إلى مدينة حماة فسُلِّمَت إليه، واستولى على المدينة وعلى قلعتها، فأرسل الملك الكامل يأمره أن يسلِّمَ البلد إلى أخيه الأكبر، فإنَّ أباه أوصى له به، فلم يفعل، وترددت الرسل في ذلك إلى الملك المعظَّم، صاحب دمشق، فلم تقع الإجابة، فلما توفِّيَ المعظم، وخرج الكامل إلى الشام وملك دمشق، سيَّرَ جيشًا إلى حماة فحصرها ثالث شهر رمضان، وكان المقَدَّم على هذا الجيش أسد الدين شيركوه، صاحب حمص، وأمير كبير من عسكره يقال له فخر الدين عثمان، ومعهما ولد محمد بن تقي الدين محمد الذي كان عند الكامل، فبقي الحصار على البلد عدة أيام، وكان الملك الكامل قد سار عن دمشق ونزل على سلمية يريد العبور إلى البلاد الجزرية، حران وغيرها، فلما نازلها قَصَده صاحب حماة صلاح الدين، ونزل إليه من قلعتِه في نفرٍ يسيرٍ، ووصل إلى الكامل، فاعتقَلَه إلى أن سلَّمَ مدينة حماة وقلعتَها إلى أخيه الأكبر الملك المظفَّر، وبقي بيده قلعة بارين، فإنها كانت له."},{"id":2474,"title":"حصر جلال الدين خوارزم شاه خلاط وملكها .","date":["العام الهجري :626","الشهر القمري : شوال","العام الميلادي :1229"],"text":"حصر جلال الدين خوارزم شاه مدينة خلاط، وهي للملك الأشرف، وبها عسكره، فامتنعوا بها، وأعانهم أهل البلد خوفًا من جلال الدين لسوء سيرته، وأسرفوا في الشتم والسفه، فأخذه اللجاج معهم، وأقام عليهم جميع الشتاء محاصرًا، وفرق كثيرًا من عساكره في القرى والبلاد القريبة من شدة البرد وكثرة الثلج؛ فإن خلاط من أشد البلاد بردًا وأكثرها ثلجًا، وأبان جلال الدين عن عزم قوي، وصبر تحارُ العقول منه، ونصب عليها عدةَ مجانيق، ولم يزل يرميها بالحجارة حتى خربت بعض سورها، فأعاد أهلُ البلد عمارته، ولم يزل مصابِرَهم وملازِمَهم إلى أواخر جمادى الأولى من سنة سبع وعشرين، فزحف إليها زحفًا متتابعًا، وملكها عَنوةً وقهرًا يوم الأحد الثامن والعشرين من جمادى الأولى، سلمها إليه بعض الأمراء غدرًا، فلما ملك البلد صعد من فيه من الأمراء إلى القلعة التي لها وامتنعوا بها، وهو مُنازِلهم، ووضع السيف في أهل البلد، وقتل من وجد به منهم، وكانوا قد قلوا، فإن بعضهم فارقوه خوفًا، وبعضهم خرج منه من شدة الجوع، وبعضهم مات من القلة وعدم القوت، وخرب عساكر جلال الدين خلاط، وأكثروا القتلَ فيها، ومن سلم هرب في البلاد، وسبوا الحريم، واسترقُّوا الأولادَ، وباعوا الجميعَ، فتمَزَّقوا كلَّ مُمزَّق، وتفَرَّقوا في البلاد، ونهبوا الأموال، وجرى على أهلِها ما لم يسمَعْ بمثله أحدٌ، ولا حول ولا قوة إلا بالله."},{"id":2475,"title":"علاء الدين كيقباذ السلجوقي يسيطر على مدينة أرزن .","date":["العام الهجري :627","العام الميلادي :1229"],"text":"كان صاحب أرزن الروم مع جلال الدين على خلاط، ولم يزل معه، وشهد معه المصاف بباسي حمار، فلمَّا انهزم جلال الدين أُخِذَ صاحب أرزن الروم أسيرًا، فأحضر عند علاء الدين كيقباذ بن عمه، فأخذه وقصد أرزن الروم، فسَلَّمَها صاحبها إليه وهي وما يتبعها من القلاع والخزائن وغيرها، فجاء إلى جلال الدين يطلُبُ الزيادة، فوعَدَه بشيءٍ مِن بلاد علاء الدين، فأخذ مالَه وما بيديه من البلادِ وبَقِيَ أسيرًا، فسُبحان من لا يزول ملكُه."},{"id":2476,"title":"ملك شهاب الدين غازي مدينة أرزن الروم .","date":["العام الهجري :627","العام الميلادي :1229"],"text":"كان حسام الدين صاحب مدينة أرزن الروم من ديار بكر لم يزل مصاحبًا للملك الأشرف، مشاهدًا جميع حروبه وحوادثه، وينفِقُ أمواله في طاعته، ويبذل نفسَه وعساكره في مساعدته، فهو يعادي أعداءه، ويوالي أولياءه، ومن جملة موافقته أنه كان في خلاط لَمَّا حصرها جلال الدين، فأسره جلالُ الدين، وأراد أن يأخذ منه مدينة أرزن، فقيل له: إن هذا من بيت قديمٍ عريق في الملك، وإنه ورث أرزن هذه من أسلافِه، وكان لهم سواها من البلاد فخرج الجميعُ من أيديهم، فعطف عليه ورقَّ له، وأبقى عليه مدينة أرزن، وأخذ عليه العهودَ والمواثيق أنه لا يقاتِلُه، فلما جاء الملك الأشرف وعلاء الدين محاربين لجلال الدين لم يحضُرْ معهم في الحرب، فلما انهزم جلال الدين سار شهاب الدين غازي بن الملك العادل، وهو أخو الأشرف، وله مدينة ميافارقين، ومدينة حاني، وهو بمدينة أرزن، فحصره بها، ثم ملكها صلحًا، وعوَّضَه عنها بمدينة حاني من ديار بكر."},{"id":2477,"title":"الأسبان يستولون على الجزر الشرقية .","date":["العام الهجري :627","العام الميلادي :1229"],"text":"استولى الأسبان على الجزر الشرقيَّة الباليار واحتلُّوا مدينة ماردة."},{"id":2478,"title":"نهاية دولة الأيوبيين وقيام دولة بني رسول في اليمن .","date":["العام الهجري :627","العام الميلادي :1229"],"text":"مات المَلِكُ المسعود يوسف بن الملك الكامل بمكة، وكانت مدة ملكه باليمن أربع عشرة سنة، وهو آخر ملوك بني أيوب ببلاد اليمن، وترك المسعود ابنًا يقال له صلاح الدين يوسف، ولُقِّب بالملك المسعود، لقبَ أبيه، وبقي يوسف هذا حتى مات في سلطنة عَمِّه الملك الصالح نجم الدين أيوب، صاحب مصر، ثم ولي ابنُه موسى بن يوسف بن يوسف بن الكامل مملكة مصر، ولُقِّبَ بالأشرف، وكان المسعود قد استخلف على اليمن نورَ الدين علي بن رسول التركماني، فتغلَّبَ عليها، وبعث إلى الملك الكامل عدةَ هدايا، وقال: أنا نائب السلطان على البلاد، فاستمَرَّ ملك اليمن في عقبه بعد ذلك."},{"id":2479,"title":"انهزام جلال الدين  بن خوارزم شاه من كيقباذ والأشرف الأيوبي .","date":["العام الهجري :627","الشهر القمري : رمضان","العام الميلادي :1230"],"text":"انهزم جلال الدين بن خوارزم شاه من عبد الله بن كيقباذ بن كيخسرو بن قلج أرسلان، صاحب بلاد الروم، ومن الملك الأشرف، صاحب دمشق، وسببُ ذلك أن جلال الدين كان قد أطاعه صاحب أرزن الروم، وهو ابن عم علاء الدين، ملك الروم، وبينه وبين ملك الروم عداوة مستحكمة، وحضر صاحبُ أرزن الروم عند جلال الدين على خلاط، وأعانه على حصرِها، فخافهما علاء الدين، فأرسل إلى الملك الكامل، وهو حينئذ بحرَّان، يطلبُ منه أن يحضر أخاه الأشرف من دمشق، فإنَّه كان مقيمًا بها بعد أن ملَكَها، وتابع علاء الدين الرسُلَ بذلك خوفًا من جلال الدين، فأحضر الملك الكامل أخاه الأشرفَ من دمشق، فحضر عنده، ورسُلُ علاء الدين إليهما متتابعةٌ، يحثُّ الأشرف على المجيء إليه والاجتماع به، فجمع عساكِرَ الجزيرة والشام وسار إلى علاء الدين، فاجتمعا بسيواس، وسارا نحو خلاط، فسمع جلال الدين بهما، فسار إليهما مجدًّا في السير، فوصل إليهما بمكان يعرف بباسي حمار، وهو من أعمال أرزنكان، فالتقوا هناك، وكان مع علاء الدين خلقٌ كثير، فلما التقوا، وجلال الدين لما رأى من كثرة العساكر، ولا سيما لما رأى عسكر الشام، ملئ صدرُه رعبًا، فأنشب عز الدين بن علي القتال، ومعه عسكر حلب، فلم يقُمْ لهم جلال الدين ولا صبَرَ، وولى منهزمًا هو وعسكرُه وعادوا إلى خلاط فاستصحبوا معهم من فيها من أصحابهم، وعادوا إلى أذربيجان فنزلوا عند مدينة خوي، ولم يكونوا قد استولوا على شيءٍ مِن أعمال خلاط سوى خلاط، ووصل المَلِكُ الأشرف إلى خلاط وقد استصحبوا معهم من فيها فبَقِيَت خاوية على عروشها، خاليةً من الأهل والسكان."},{"id":2480,"title":"قدوم بني رسول مع الأيوبيين إلى اليمن، واستيلاؤهم على اليمن .","date":["العام الهجري :628","العام الميلادي :1230"],"text":"قَدِمَ بَنو رَسولٍ اليَمنَ ضِمنَ الحَملةِ الأيُّوبيَّةِ إليها، فإنَّه لَمَّا استَوثَقَ المُلْكُ لبَني أيُّوبَ في مِصرَ لم يَزَلْ معهم عُصبةٌ مِن بَني رَسولٍ؛ لِعِلْمِهم بتَقدُّمِ مَنصِبِهم في المُلكِ وعُلوِّ هِمَمِهم وشدةِ بَسالَتِهم، فاجتَمع رأيُ بَني أيُّوبَ على تسييرِهم إلى اليَمنِ صُحبةَ المَلكِ المعظَّمِ تُورانْشاهْ بنِ أيُّوبَ، وكانَ دُخولُه اليَمنَ في سنةِ 569هـ، وتوالى مُلوكُ الأيُّوبيةِ على اليَمنِ، ولَمَّا توَلَّى المُلكُ العادِلُ أبو بَكرِ بنُ أيُّوبَ المُلكَ في مِصرَ أرسَلَ ابنَ ابنِه المَلكَ المَسعودَ صلاحَ الدِّينِ يُوسفَ إلى اليَمنِ، فاستَولى على اليَمنِ بأسْرِها، وأنِسَ ببَني رَسولٍ ووَثِقَ بهم، ووَلَّاهمُ الوِلاياتِ الجليلةَ، وتجهَّزَ المَلكُ المَسعودُ إلى مِصرَ، وتركَ في اليَمنِ نورَ الدِّينِ عُمَرَ بنَ علِيِّ بنِ رَسولٍ نائبًا نيابةً عامةً، وفي سنةِ 626هـ تُوفِّي المَلكُ المَسعودُ، وتملَّكَ اليَمنَ بعدَه نائِبُه نورُ الدِّينِ عُمَرُ بنُ علِيٍّ الرَّسوليُّ، وبعدَ أن تمكَّنَ مِنَ احتِواءِ مُناهِضيه، وبَسَط نفوذَه على مُعْظمِ بِلادِ اليَمنِ، استَقلَّ باليَمنِ عن بَني أيُّوبَ سنةَ 628هـ، ولُقِّبَ بالمَنصورِ، واتَّخَذَ مِن تَعِزَّ عاصمةً له، وأخَذَ في تَثبيتِ مُلكِه، وإخمادِ الحَركاتِ الِانفِصاليةِ، وطَرَدَ العَساكرَ المِصريةَ عن مَكةَ والحِجازِ، وراسَلَ الخَليفةَ العباسيَّ المُستَنصِرَ باللهِ سنةَ 631هـ لِيكونَ تابِعًا لِدارِ الخِلافةِ العباسيةِ، وفي سنةِ 647هـ، اغتيلَ السُّلطانُ نورُ الدِّينِ على يَدِ جَماعةٍ مِن مماليكِه، بتدبيرٍ مِنَ ابنِ أخيه أسدِ الدِّينِ محمدِ بنِ الحَسَنِ بنِ علِيِّ بنِ رَسولٍ، وكانَ الوَضعُ بعدَ مَقتَلِه يُنذِرُ بالانقِسامِ والتَّفكُّكِ، حيث بدأ الصِّراعُ في البَيتِ الرَّسوليِّ على الحُكمِ بينَ أبناءِ نورِ الدِّينِ وبَينَهم وبينَ أبناءِ عُمومَتِهم، ومِن جِهةٍ أُخرى استَغلَّ الإمامُ الزَّيديُّ أحمدُ بنُ الحُسَينِ الوَضعَ الداخليَّ المُضطرِبَ في الدَّولةِ الرَّسوليةِ، واستَولى على صَنعاءَ،  فتَحرَّكَ السُّلطانُ المظَفَّرُ يُوسفُ بنُ عُمَرَ، فجَمَعَ جُندَه وأحكَمَ قَبضَتَه على السُّلطةِ في اليَمنِ بشكلٍ كاملٍ في سنةِ 648هـ، وفي عَهدِه بَسَطت الدولةُ الرَّسوليةُ نُفوذَها على إقليمِ حَضرَموتَ، وبَعضِ المَناطِقِ الواقعةِ في جَنوبِ سَلطنةِ عُمانَ في الوَقتِ الحاليِّ، مِثلَ ظَفارِ وغَيرِها، ثم تُوفِّي السُّلطانُ المظَفَّرُ سنةَ 694هـ، وقام الصِّراعُ بينَ أبنائِه، وتوالى سَلاطينُ الدولةِ الرسوليةِ، حتى جاءَ عَهدُ السُّلطانِ المُجاهِدِ سنةَ 721هـ وتَفكَّكتِ الدولةُ الرسوليةُ في أيامِه؛ نتيجةَ صِراعاتِ البَيتِ الرَّسوليِّ، واستَغلَّ الأئِمةُ الزيديةُ ذلك واستَوْلَوْا على العَديدِ مِنَ المناطقِ والمُدنِ اليَمنيةِ، كانَ مِن أبرَزِها استيلاؤُهم على صَنعاءَ سنةَ 723هـ، ثم تولَّى السُّلطانُ الأفضلُ بعدَ وفاةِ أبيه السُّلطانِ المُجاهِدِ سنةَ 764هـ، وقد وَرِثَ دولةً آيلةً لِلانهيارِ، فحاوَلَ استِعادةَ نُفوذِ الدَّولةِ الرَّسوليةِ، والقَضاءَ على الثَّوَراتِ الداخليةِ، وتَلاه على ذلك عَددٌ مِن سَلاطينِ الدولةِ الرسوليةِ، مُحاولينَ تَرتيبَ أُمورِ الدولةِ وتَوفيرَ الأمنِ والاستِقرارِ، وذلك بإخضاعِ المَناطِقِ والقَبائِلِ الثائِرةِ، حتى جاءَ عَهدُ السُّلطانِ الناصِرِ الذي استَطاعَ إقرارَ أوضاعِ البِلادِ الداخليةِ، واستَعادَ قُوَّةَ الدَّولةِ وهَيبَتَها، ورَغمَ ذلك تُعَدُّ وَفاتُه بدايةَ عهدِ المُلوكِ الضُّعفاءِ في الأُسرةِ الرسوليةِ، والانحدارِ بالنسبةِ لِلدَّولةِ الرسوليةِ، إلى أنِ استَغلَّ الطاهريُّون الخِلافاتِ بينَ الأُسرةِ الرسوليةِ الحاكِمةِ؛ لِيُسيطِروا على عَدَنٍ ولَحْجٍ، وبحُلولِ عامِ 855هـ أعلنوا أنفُسَهمُ الحُكامَ الجُددَ لِليَمنِ."},{"id":2481,"title":"خروج التتر إلى أذربيجان .","date":["العام الهجري :628","العام الميلادي :1230"],"text":"وصل التتر من بلاد ما وراء النهر إلى أذربيجان، وقد كان استقَرَّ مُلكُهم بما وراء النهر، وعادت بلادُ ما وراء النهر فانعمرت، وعمروا مدينة تقارب مدينة خوارزم، وبَقِيَت مدن خراسان خرابًا لا يجسر أحدٌ من المسلمين أن يسكُنَها، وأما التتر فكانت تَغيرُ كلَّ فترة طائفة منهم ينهبون ما يرونه بها، فالبلاد خاوية على عروشها، فلم يزالوا كذلك إلى أن ظهر منهم طائفةٌ سنة خمس وعشرين، فكان بينهم وبين جلال الدين ما كان، وبقُوا كذلك، فلما كان سنة سبع وعشرين وانهزم جلال الدين من علاء الدين كيقباذ ومن الأشرف، أرسل مقدَّم الإسماعيليَّة الملاحدة إلى التتر يُعَرِّفُهم ضعف جلال الدين بالهزيمة الكائنة عليه، ويحثُّهم على قَصدِه عَقيبَ الضعف، ويضمَنُ لهم الظفر به؛ للوهن الذي صار إليه، وكان جلال الدين سيئ السيرة، قبيح التدبير لملكه، لم يترك أحدًا من الملوك المجاورين له إلا عاداه، ونازعه الملك، وأساء مجاورته، فلما وصل كتاب مقدَّم الإسماعيلية إلى التتر يستدعيهم إلى قصد جلال الدين، بادر طائفة منهم فدخلوا بلاده واستولوا على الري وهمذان وما بينهما من البلاد، ثم قصدوا أذربيجان فخربوا ونهبوا وقتلوا من ظفروا به من أهلها، وجلال الدين لا يُقدِم على أن يلقاهم، ولا يقدر أن يمنعهم عن البلاد، قد ملئ رعبًا وخوفًا، وانضاف إلى ذلك أن عسكَرَه اختلفوا عليه، وخرج وزيرُه عن طاعته في طائفة كثيرة من العسكر، فبقي حيران لا يدري ما يصنع."},{"id":2482,"title":"دخول التتر ديار بكر والجزيرة .","date":["العام الهجري :628","العام الميلادي :1230"],"text":"لما انهزم جلال الدين من التتر على آمد نهب التتر سوادَ آمد وأرزن الروم وميافارقين، وقصدوا مدينةَ أسعرد، فقاتلهم أهلُها، فبذل لهم التترُ الأمان، فوَثِقوا منهم واستسلَموا، فلما تمكَّنَ التتر منهم وضَعُوا فيهم السيفَ وقتلوهم حتى كادوا يأتونَ عليهم، فلم يسلَمْ منهم إلَّا من اختفى، وقليل ما هم، ومدَّة الحصار كانت خمسة أيام، ثمَّ ساروا منها إلى مدينة طنزة، ففعلوا فيها كذلك، وساروا من طنزة إلى وادٍ بالقرب من طنزة يقال له وادي القريشية، فيه مياه جارية، وبساتين كثيرة، والطريق إليه ضيق، فقاتلهم أهل القريشية، فمنعوهم عنه، وامتنعوا عليهم، وقُتل بينهم كثيرٌ، فعاد التتر ولم يبلغوا منهم غرضًا، وساروا في البلاد لا مانع يمنَعُهم، ولا أحدَ يقِفُ بين أيديهم، فوصلوا إلى ماردين فنهبوا ما وجدوا من بلدها، واحتمى صاحِبُ ماردين وأهل دنيسر بقلعة ماردين، وغيرهم ممن جاور القلعة احتمى بها أيضًا، ثم وصلوا إلى نصيبين الجزيرة، فأقاموا عليها بعضَ نهار، ونهبوا سوادَها وقتلوا مَن ظَفِروا به، وغُلِّقَت أبوابها، فعادوا عنها، ومَضَوا إلى بلد سنجار، ووصلوا إلى الجبال من أعمال سنجار، فنهبوها ودخلوا إلى الخابور، فوصلوا إلى عرابان، فنَهَبوا وقتلوا وعادوا، ومضى طائفة منهم على طريق الموصل، فوصل القومُ إلى قرية تُسمَّى المؤنسة، وهي على مرحلة من نصيبين، بينها وبين الموصِل، فنهبوها واحتمى أهلُها وغيرهم بخان فيها، فقَتَلوا كلَّ من فيه، ومضى طائفةٌ منهم إلى نصيبين الروم، وهي على الفرات، وهي من أعمال آمد، فنهبوها وقتلوا من فيها، ثم عادوا إلى آمد، ثم إلى بلد بدليس، فتحصَّن أهلها بالقلعة وبالجبال، فقتلوا فيها يسيرًا، وأحرقوا المدينةَ، ثم ساروا من بدليس إلى خلاط، فحَصَروا مدينة من أعمال خلاط يقال لها: باكرى، وهي من أحصن البلاد، فملكوها عنوةً، وقتلوا كلَّ من بها، وقصدوا مدينة أرجيش من أعمال خلاط، وهي مدينة كبيرة عظيمة، ففعلوا كذلك."},{"id":2483,"title":"التتر يسيطرون على مدينة مراغة من أذربيجان .","date":["العام الهجري :628","العام الميلادي :1230"],"text":"حصر التترُ مراغة من أذربيجان، فامتنع أهلها، ثم أذعن أهلُها بالتسليم على أمانٍ طلبوه، فبذلوا لهم الأمان، وتسلَّموا البلدَ وقتلوا فيه إلَّا أنهم لم يُكثِروا القتل وجعلوا في البلد شحنةً، وعظُمَ حينئذ شأن التتر، واشتد خوفُ الناس منهم بأذربيجان، وليس في ملوك الإسلام من له رغبةٌ في الجهاد، ولا في نصرةِ الدين، بل كلٌّ منهم مُقبِلٌ على لهوه ولعبه وظُلمِ رَعيَّتِه، وقال الله تعالى: {وَاتَّقُوا فِتْنَةً لَا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنْكُمْ خَاصَّةً} [الأنفال: 25]."},{"id":2484,"title":"وفاة سليمان شاه التركماني جد عثمان مؤسس الدولة العثمانية .","date":["العام الهجري :628","العام الميلادي :1230"],"text":"هو سُليمان شاه بن قتلمش القايوي التركماني جَدُّ مُؤَسِّس الدَّولة العُثمانيَّة، السُّلطان عثمان الأوَّل بن أرطغرل. كان حاكِمًا في بلدة ماهان, لَمَّا وقعت فتنةُ جنكيز خان سنة 621 ترك تلك سليمان مع قومه البلادَ مع من تركها من الملوكِ، وقصد بلادَ الروم، وكان قد سمع بدولةِ السلجوقية بها وعِظَمِ شَوكتِهم، وتَبِعَه خلقٌ كثير، فلمَّا وصلوا إلى أرزنجان قاتلوا الكفَّار وغنموا منهم شيئًا كثيرًا ثمَّ قَصَدوا صوبَ حَلَب من ناحية ألبستان، فوصلوا إلى نهر الفُرات أمام قلعة جعبر، ولم يعلموا المعبَرَ، فعبروا النهر فغلب عليهم الماءُ، فغرق سليمان شاه سنة 628، ثم أخرجوه ودفَنوه عند القلعة, وكان معه أولاده الثلاثة سنقور تكين، وكون طوغدي، وأرطغرل، فلما أصيبوا بأبيهم وتشَوَّش بالُهم رجعوا إلى إثرِهم، فلما وصلوا إلى موضعٍ يقال له بَاسين أُواسِي مضى سنقور وكون طوغدي إلى موطنهما الأصلي, وأما أرطغرل بك مع أبنائه الثلاثة كُندز وصارو بالي وعثمان، فمكثوا في نفس الموضع يجاهِدونَ فيه الكُفَّار."},{"id":2485,"title":"استيلاء ابن هود على غرناطة .","date":["العام الهجري :628","العام الميلادي :1230"],"text":"قام الأمير محمد بن يوسف بن هود بالاستيلاء على غرناطة وانتزعها من دولة الموحدين بعد أن استولى على مرسية وما جاورها من بلاد الشَّرقِ."},{"id":2486,"title":"نهاية الدولة الخوارزمية .","date":["العام الهجري :628","العام الميلادي :1230"],"text":"بعد دخول التتر أذربيجان وغيرها من المدن، وتفَرُّق عساكر جلال الدين خوارزم شاه واختفائه، ولم يعرف له سبيل؛ كان ذلك نهاية للدولة الخوارزميَّة."},{"id":2487,"title":"وصول طائفة من التتر إلى إربل ودقوقا .","date":["العام الهجري :628","الشهر القمري : ذي الحجة","العام الميلادي :1231"],"text":"وصل طائفةٌ من التتر من أذربيجان إلى أعمال إربل، فقتلوا من على طريقِهم من التركمان الإيوانية والأكراد الجوزقان وغيرهم إلى أن دخلوا بلدَ إربل، فنهبوا القرى، وقتَلوا من ظَفِروا به من أهلِ تلك الأعمال، وعَمِلوا الأعمالَ الشنيعة التي لم يُسمَع بمثلِها من غيرهم، وبرز مظفر الدين، صاحب إربل، في عسكره، واستمدَّ عساكِرَ الموصل فساروا إليه، فلمَّا بلَغَه عودَ التتر إلى أذربيجان أقام في بلاده ولم يتبعْهم، فوصلوا إلى بلد الكرخيني، وبلد دقوقا، وغير ذلك، وعادوا سالمينَ لم يذعرْهم أحدٌ، ولا وقف في وجوههم فارسٌ."},{"id":2488,"title":"طاعة أهل أذربيجان للتتر .","date":["العام الهجري :628","الشهر القمري : ذي الحجة","العام الميلادي :1231"],"text":"في أواخر هذه السنة أطاع أهل بلاد أذربيجان جميعها للتتر، وحملوا إليهم الأموالَ والثياب الخطائي، والخوبي، والعتابي، وغير ذلك، وسبب طاعتِهم أن جلال الدين لَمَّا انهزم على آمد من التتر، وتفَرَّقت عساكره، وتمزَّقوا كلَّ مُمزَّق، وتخطَّفَهم الناس، وفعل التترُ بديار بكر والجزيرة وإربل وخلاط ما فعلوا، ولم يمنَعْهم أحد، ولا وقف في وجوههم واقف، وملوكُ الإسلام منجحرون في الأثقاب، وانضاف إلى هذا انقطاعُ أخبار جلال الدين، فإنَّه لم يظهر له خبر، ولا علموا له حالة، سُقِطَ في أيديهم، وأذعنوا للتتر بالطاعة، وحملوا إليهم ما طلبوا منهم من الأموالِ والثياب، وكذلك مدينة تبريز التي هي أصل بلاد أذربيجان، ومرجع الجميعِ إليها وإلى من بها، فإنَّ ملك التتر نزل في عساكره بالقرب منها، وأرسل إلى أهلِها يدعوهم إلى طاعته، ويتهدَّدُهم إن امتنعوا عليه، فأرسلوا إليه المال الكثير، والتُّحَف من أنواع الثياب الإبريسم وغيرها، وكلُّ شيء حتى الخمر، وبذلوا له الطاعة، فأعاد الجوابَ يشكُرُهم، ويطلب منهم أن يحضُرَ مُقَدَّموهم عنده، فقصده قاضي البلد ورئيسُه، وجماعة من أعيان أهله، وتخلَّفَ عنهم شمس الدين الطغرائي، وهو الذي يرجع الجميعُ إليه، إلَّا أنه لا يظهر شيئًا من ذلك، فلمَّا حضروا عنده سألهم عن امتناع الطغرائي من الحضور فقالوا: إنه رجل منقطع، ما له بالملوك تعلُّق، ونحن الأصل، فسكت ثم طلب أن يحضروا عنده من صناع الثيابِ الخطائي وغيرها، ليستعمل لمَلِكهم الأعظم، فأحضروا الصُّنَّاع، فاستعملهم في الذي أرادوا، ووزن أهل تبريز الثمَن، وطلب منهم خركاة لملكه أيضًا، فعملوا له خركاة- بيت من الخشب- لم يُعمَل مِثلُها، وعملوا غشاءَها من الأطلس الجيد المزركش، وعملوا من داخلها السمور والقندر، فجاءت عليهم بجملة كثيرة، وقرر عليهم شيئًا من المال كلَّ سنة، وترددت رسلهم إلى ديوان الخلافة وإلى جماعة من الملوك يطلُبون منهم أنهم لا ينصرون خوارزم شاه. قال ابن خلكان: \"ولقد وقفتُ على كتاب وصل من تاجرٍ مِن أهل الري في العام الماضي، قبل خروج التتر، فلما وصل التتر إلى الري وأطاعهم أهلها، وساروا إلى أذربيجان، سار هو معهم إلى تبريز، فكتب إلى أصحابه بالموصل يقول: إن الكافِرَ- لعنه الله- ما نَقدِرُ نَصِفُه، ولا نذكر جموعه حتى لا تنقطع قلوبُ المسلمين، فإن الأمر عظيم، ولا تظنوا أن هذه الطائفةَ التي وصلت إلى نصيبين والخابور، والطائفة الأخرى التي وصلت إلى إربل ودقوقا، كان قصدُهم النهب، إنما أرادوا أن يعلموا هل في البلاد من يردُّهم أم لا، فلما عادوا أخبروا ملكهم بخلو البلادِ مِن مانع ومدافع، وأنَّ البلاد خالية من ملك وعساكر، فقوي طمعُهم، وهم في الربيع يقصدونَك، وما يبقى عندكم مقامٌ إلَّا إن كان في بلد الغرب، فإنَّ عَزمَهم على قصدِ البلاد جميعها، فانظروا لأنفُسِكم، هذا مضمون الكتاب، فإنَّا لله وإنا إليه راجعون، ولا حول ولا قوة إلا بالله العلي العظيم\"."},{"id":2489,"title":"امتداد الغزو المغولي وتصدي الخليفة لهم .","date":["العام الهجري :629","العام الميلادي :1231"],"text":"تكامَلَ استيلاءُ التتر على إقليم أرمينية وخلاط وسائر ما كان بيد الخوارزمي، فوصلوا إلى شهزور فاهتَمَّ الخليفة المستنصر بالله غايةَ الاهتمام، وسيَّرَ عِدَّة رسل يستنجد الأشرفَ مِن مصر، ويستنجد العربان وغيرهم، وأخرج الخليفةُ الأموال، فوقع الاستخدام في جميع البلاد لحركة التتر، فندب الخليفةُ صاحب إربل مظفر الدين كوكبري بن زين الدين، وأضاف إليه عساكِرَ مِن عنده، فساروا نحوهم فهربت منهم التتار وأقاموا في مقابلتهم عدةَ شهور، ثم تمَرَّض مظفر الدين وعاد إلى بلده إربل، وتراجَعَت التتار إلى بلادِها."},{"id":2490,"title":"اجتماع الملوك لقتال التتار .","date":["العام الهجري :629","العام الميلادي :1231"],"text":"خرج المَلِكُ الكامِلُ مِن القاهرة في جمادى الآخرة، واستخلفَ على مصر ابنَه المَلِك العادلَ أبا بكر، وقَدِمَ الأشرف والمعظم صاحِب الجزيرة بالعساكر، ومضى الكاملُ جريدة-الجريدة خَيْلٌ لا رَجَّالة فيها- إلى الشوبك والكرك، وسار إلى دمشقَ، ومعه الناصرُ داود بن الملك المعظَّم صاحب الكرك بعساكره، وأقام الكامِلُ بدمشق يسَرِّح العساكِرَ، وجعل في مقدِّمتِها ابنه الملك الصالح أيوب، وورد الخبر بدخول التتر بلاد خلاط، فأسرع الكامِلُ في الحركة، وخرج من دمشق، فنزل سلمية وقد اجتمع فيها بعساكِرَ يضيق بها الفضاءُ وسار منها في آخر رمضان على البرية، وتفرَّقَت العساكر في عدة طرق لكثرتِها، فهلك منها عدةٌ كثيرة من الناس والدواب، لقلَّة الماء، وأتته رسلُ ملوك الأطراف، وهم عز الدين بيقرا، وفخر الدين بن الدامغاني، ورسل الخليفة المستنصر بالله، وألبسوه خِلعة السلطنة، فاستدعى الكامل عند ذلك رسلَ الخوارزمي، ورسول الكرج، ورسل حماة وحمص، ورسول الهند ورسل الفرنج، ورسل أتابك سعد صاحب شيراز، ورسل صاحب الأندلس ولم تجتَمِعْ هذه الرسلُ عند ملك في يومٍ واحدٍ قَطُّ غيره، وقَدِمَ عليه بهاء الدين اليزدي - شيخ رباط الخلاطية - من بغداد وجماعة من النخاس، يحثُّونه على الغزاة، فرحل التتر عن خلاط، بعد منازلتها عدَّةَ أيام، وجاء الخبَرُ برحيلهم والكامل بحرَّان، فجهَّز عماد الدين بن شيخ الشيوخ رسولًا إلى الخليفة، وسار إلى الرَّها، وقَدَّم الكامِلُ العساكِرَ إلى آمد، وسار بعدهم، فنزل على آمد، ونصبَ عليها عِدَّة مجانيق، فبعث إليه صاحِبُها يستعطِفُه، ويبذل له مائة ألف، وللأشرفِ عشرين ألف دينار، فلم يقبَلْ، وما زال عليها حتى أخذها، في سادس عشر ذي الحجة، وحضر صاحبُها إليه بأمان، فوكل به حتى سلم جميعَ حصونها، فأعطى السلطانُ حصن كيفا لابنه الملكِ الصالح نجم الدين أيوب."},{"id":2491,"title":"إقامة دولة بني الأحمر بغرناطة .","date":["العام الهجري :629","العام الميلادي :1231"],"text":"أقام محمد بن يوسف بن نصر جد بني الأحمر دولةَ بني الأحمر في غرناطة بعد أن تغلَّبَ على محمد بن يوسف بن هود."},{"id":2492,"title":"محاولة صاحب اليمن الاستيلاء على مكة .","date":["العام الهجري :629","الشهر القمري : ربيع الآخر","العام الميلادي :1232"],"text":"بعث الملكُ المنصور عمر بن علي بن رسول، صاحبُ اليمن، عسكرًا إلى مكة، وفيها الشَّريفُ راجح بن قتادة، فمَلَكَها من الأمير شجاع الدين طغتكين، نائب الملك الكامل، وفرَّ شجاع الدين إلى نخلة ثم إلى ينبع، وكتب يُعلِمُ الملك الكامل بذلك، فبعث إليه الكامِلُ عسكرًا سار بهم إلى مكَّة، فقدموها في شهر رمضان، ومَلَكوها بعدما قتلوا جماعة، وكان مُقَدَّم العسكر الأمير فخر الدين يوسف بن الشيخ."},{"id":2493,"title":"تأسيس دولة بني الأحمر في غرناطة وبناء قصر الحمراء .","date":["العام الهجري :630","العام الميلادي :1232"],"text":"بعد أن تخلى الموحِّدون عن الأندلس بدأت تتساقَطُ المدن الإسلامية فيها واحدة تلوَ الأخرى في أيدي القوى الصَّليبية غيرَ أنَّ مقاطعة غرناطة استطاع أن يسيطرَ عليها محمد الغالب بن يوسف بن أحمد بن نصر بن الأحمر الذي اعتصم بها، وأقام قلعةً عُرِفَت باسم قلعة الحمراء أو قصر الحمراء وجعلها مركزًا له ولأسرته من بعده، وملجأً لجموع المسلمين الهاربين من أنحاءِ الأندلس، ثمَّ أعلن نفسَه أميرًا على الأندلس بعد أن استولى على جيان ووادي آش وبسطة، وتمت له غرناطة تمامًا والتي أصبحت عاصمتَه، واستطاع أن يضمَّ لها عددًا من الدويلات الأخرى, وظلَّت دولةُ الإسلام في الأندلُسِ بغرناطة إلى سقوطها بيد الفرنج سنة 897 (1492م)."},{"id":2494,"title":"اتساع دولة بني حفص في الجزائر .","date":["العام الهجري :630","العام الميلادي :1232"],"text":"قام أبو زكريا الأول الحفصي أمير تونس مؤسس الدولة الحفصية بتوسيعِ رقعة دولته باستيلائِه على بجاية وقسنطينة."},{"id":2495,"title":"نهاية دولة بني أرتق في بلاد آمد .","date":["العام الهجري :630","الشهر القمري : صفر","العام الميلادي :1232"],"text":"قام الملك الكامِلُ الأيوبي صاحِبُ مصر بفتح آمد، وأخرجَ منها صاحبها الملك المسعود بن مودود بعد حصار طويل، وتسلم منه جميعَ القلاع التي كانت بيده، وبَقِيَ حِصنُ كيفا عاصيًا، فبعث الكامل أخاه الأشرف وأخاه شهاب الدين غازي، ومعهما صاحب آمد تحت الحوطة، فسألهم صاحِبُ آمد في تسليمِ الحصن فلم يسَلِّموا البلد، فعذَّبَه الأشرفُ عذابًا عظيمًا، وكان يُبغِضُه، ولا زال الأشرف يحاصر حصن كيفا حتى تسَلَّمَها، ووجد عند مسعود المذكور خمسمائة بنت من بنات الناس للفِراش، وكان الملك المسعود هو آخِرُ ملوك بني الأرتق، ثمَّ قام الملك الكامل بتوليةِ ابنه نجم الدين أيوب آمد وحصن كيفا، وأبقى الملك المسعود عنده في مصر، حبسه مدةً ثم أفرج عنه وأقطعه إمرةً في مصر."},{"id":2496,"title":"وفاة ابن الأثير الجزري صاحب التاريخ .","date":["العام الهجري :630","الشهر القمري : شعبان","العام الميلادي :1233"],"text":"هو الشيخ الإمام العلامة المحدِّث، الأديبُ النَّسَّابة: عز الدين أبو الحسن علي بن محمد بن عبد الكريم بن عبد الواحد الشيباني الجزري الموصلي المعروف بابن الأثير، مصنف كتاب (أُسْد الغابة في أسماء الصحابة)، وكتاب (الكامل في التاريخ)، وهو من أحسنها سردًا للحوادث ابتدأه من المبتدأ إلى سنة ثمان وعشرين وستمائة، ولد بجزيرة ابن عمر، في سنة 550، ونشأ بها، وأخواه العلامة مجد الدين والوزير ضياء الدين، ثم تحوَّلَ بهم أبوهم إلى الموصل، فسَمِعوا بها، واشتغلوا وبرعوا وسادوا. كان ابن الأثير إمامًا علامة، أخباريًّا أديبًا، متفنِّنًا رئيسًا محتشمًا، عالِمًا بالأنساب والتواريخ وأيام العرب، وله كتاب خاص بتاريخ الأتابكة الذين عاش في ظلهم، وكان منزله مأوى طلبة العلم، ولقد أقبل في آخر عمره على الحديث إقبالًا تامًّا، وسمع العاليَ والنازل, ووزر لبعض أتابكة الموصل وأقام بها في آخر عمره موقرًا مُعظَّمًا إلى أن توفي بها، وكان يتردد إلى بغداد. قدم ابن الأثير الشام رسولًا، فحدَّث بدمشق وحلب. قال ابن خلكان: \" لَمَّا وصلت إلى حلب في أواخر سنة 626 كان عز الدين ابن الأثير مقيمًا عند الطواشي شهاب الدين طغريل الخادم أتابك الملك العزيز بن الملك الظاهر صاحب حلب، وكان الطواشي كثير الإقبال عليه حَسَنَ الاعتقاد فيه مُكْرِمًا له، فاجتمعت به فوجدته رجلًا مكملًا في الفضائل وكرم الأخلاق وكثرة التواضع، فلازمت التردادَ إليه\" وأمَّا ابن الأثير الجزري الآخر فهو أخوه أبو السعادات المبارك مصنف كتاب جامع الأصول، وأخوهما الوزير ضياء الدين أبو الفتح نصر الله كان وزيرًا للملك الأفضل علي بن صلاح الدين، توفي ابن الأثير عن خمس وسبعين سنة- رحمه الله- في الموصل، ودُفِنَ بها."},{"id":2497,"title":"وفاة الملك المظفر صاحب إربل .","date":["العام الهجري :630","الشهر القمري : رمضان","العام الميلادي :1233"],"text":"هو السلطانُ المَلِكُ المعَظَّم: مظفر الدين أبو سعيد كوكبري بن علي بن بكتكين بن محمد التركماني، صاحب إربل، وابنُ صاحبها, وقد مصرَها الملك زين الدين علي كوجك. ثمَّ وهبها لأولاد مظفر الدين صاحب الموصل، وكان يوصَفُ بقوةٍ مُفرِطة، وطال عمره، وله أوقافٌ وبر ومدرسة بالموصل. ولد مظفر الدين في المحرم، 549، بإربل. تولى مظفَّرُ الدين إربل بعد وفاةِ أبيه وأقام بها مدَّةً وانتقل إلى الموصِلِ، ثمَّ دخل الشام واتصل بالملك الناصرِ صلاحِ الدين فأكرمه كثيرًا، وكانت له آثارٌ حسنة، وقد عمر الجامِعَ المظفري بسفحِ قاسيون، وكان قد هَمَّ بسياقة الماء إليه من ماء بذيرة، فمنعه المعظم من ذلك، واعتَلَّ بأنه قد يمُرُّ على مقابر المسلمين بالسفوح، وكان يهتَمُّ بعمل المولد الشريف اهتمامًا زائدًا حتى إنه كان يرقُصُ بنفسِه ويمارس هذه البدعةَ بنَفسِه، وقد صنَّف الشيخ أبو الخطاب ابن دحية له مجلدًا في المولد النبوي سماه \" التنوير في مولد البشير النذير \"، فأجازه على ذلك بألف دينار، وقد طالت مدته في الملك في زمان الدولة الصلاحية، وقد كان محاصِرًا عكا، وإلى هذه السنة محمود السيرة والسريرة، وكانت له دار ضيافة للوافدين من أي جهة على أي صفة، وكانت صدقاته في جميع القرب والطاعات على الحرمينِ وغيرهما. بنى أربع خوانك للزمنى- ذوو الأمراض المزمنة- والأضراء، وكان يأتيهم كل اثنين وخميس، ويسألُ كل واحد عن حاله، ويتفقده، ويباسطه ويمزح معه, وبنى دارًا للنساء، ودارًا للأيتام، ودارًا للُّقَطاء، ورتَّب بها المراضع, وكان يدورُ على مرضى البيمارستان, وله دار مضيف ينزلها كل وارد، ويعطى كل ما ينبغي له, وبنى مدرسة للشافعية والحنفية، وكان يمدُّ بها السماط، ويحضر السماعَ كثيرًا، لم يكن له لذَّةٌ في شيء غيره. وكان يمنع من دخول منكَر بلدَه، وبنى للصوفية رباطين، وكان ينزل إليهم لأجل السَّماعات, ويفتَكُّ من الفرنجِ في كلِّ سنةٍ خَلقًا من الأُسارى، حتى قيل: إن جملة من استفَكَّه من أيديهم ستون ألف أسير، مات ليلة الجمعة، رابع عشر رمضان, وكانت وفاته بقلعة إربل، وأوصى أن يُحمَل إلى مكة فلم يتَّفِقْ، فدفن بمشهد علي, وقد عاش اثنتين وثمانين سنة."},{"id":2498,"title":"الملك الكامل صاحب مصر يرسل جيشا لاسترداد مكة .","date":["العام الهجري :630","الشهر القمري : شوال","العام الميلادي :1233"],"text":"جهَّز الملكُ الكامِلُ عسكرًا من الغزِّ والعربان إلى ينبع، من أرضِ الحجاز عليهم علاء الدين آق سنقر الزاهدي في شوَّال وعِدَّتُهم سبعمائة، وسبَبُ ذلك ورودُ الخبر بمسير الشريف راجح من اليمن بعسكر إلى مكةَ، وأنَّه قَدِمَها في صفر، وأخرج من بها من المصريين بغيرِ قتال، ثم إنَّ ابن رسول بعث إلى الشريف راجح بن قتادة بخزانة مالٍ، ليستخدم عسكرًا، فلم يتمكَّنْ من ذلك؛ لأنَّه بلغه أنَّ السلطان الملك الكامل بعث الأميرَ أسد الدين جغريل، أحدَ المماليك الكاملية، إلى مكة بسبعمائة فارس، وحضر جغريل إلى مكة، ففَرَّ منه الشريف راجح بن قتادة إلى اليمن، وملك جغريل مكَّةَ في شهر رمضان، وأقام العسكَرَ بها، وحجَّ بالنَّاسِ، وترك بمكةَ ابن محلي، ومعه خمسون فارسًا، ورجع إلى مصر، ثم بعثَ الملك المنصور عمرُ بن علي بن رسول ملك اليمن عسكرًا إلى مكة، مع الشهاب بن عبد الله، ومعه خزانةُ مال، فقاتله المصريون وأسَروه، وحملوه إلى القاهرة مُقَيَّدًا."},{"id":2499,"title":"استيلاء الخليفة على الموصل .","date":["العام الهجري :630","الشهر القمري : شوال","العام الميلادي :1233"],"text":"سارت العساكر المستنصرية بصحبة الأمير سيف الدين أبي الفضائل إقبال الخاص المستنصري إلى مدينة إربل وأعمالها، وذلك لمرض مالكِها مظفر الدين كوكبري بن زين الدين، وأنَّه ليس له من بعده من يملك البلاد، فحين وصَلَها الجيشُ منَعَه أهلُ البلد فحاصروه حتى افتتحوه عنوةً في السابع عشر من شوال، وجاءت البشائرُ بذلك فضُرِبَت الطبول ببغداد بسَبَبِ ذلك، وفَرِحَ أهلُها، وكتب التقليدُ عليها لسيف الدين أبي الفضائل إقبال، فرتَّبَ فيها المناصِبَ وسار فيها سيرةً جيدة، وامتدح الشعراءُ هذا الفتحَ مِن حيث هو، وكذلك مدحوا فاتحَها سيف الدين أبا الفضائل."},{"id":2500,"title":"إنشاء المدرسة الجوزية .","date":["العام الهجري :631","العام الميلادي :1233"],"text":"أنشأها القاضي أستاذ دار الخليفة المستعصم الصاحب محيي الدين ابن الشيخ جمال الدين أبي الفرج عبد الرحمن ابن الجوزي أيَّامَ الملك الصالح عماد الدين، كان قد حصل على أموالٍ وكراماتٍ من بني أيوب بالشامِ- أثناء قيامه بالسِّفارة بين الخليفة وبني أيوب- ابتنى بها المدرسةَ الجوزيَّة بالنشابين بدمشق بسوق القمح بالقرب من الجامِعِ، وقد نسب إليها ابنُ قَيِّم الجوزيَّة رحمه الله، فهو إمامُها ووالدُه كان قَيِّمَها."},{"id":2501,"title":"وفاة العلامة المتكلم سيف الدين الآمدي .","date":["العام الهجري :631","الشهر القمري : صفر","العام الميلادي :1233"],"text":"هو العلامة المتكلم أبو الحسن علي بن أبي علي ابن محمد بن سالم الثعلبي سيف الدين الآمدي، الحنبلي ثم الشافعي. الحموي الدمشقي، صاحبُ المصَنَّفات في الأصلين وغيرهما، ومن مصنفاته: \" أبكار الأفكار في الكلام \" و\" دقائق الحقائق في الحكمة \" و\" إحكام الأحكام في أصول الفقه \" ولد بعد 550 بيسيرٍ بآمد، وقرأ بها القراءات على الشيخ محمد الصفار، وعمار الآمدي. وحفظ \"الهداية\" في مذهب أحمد. كان حنبليَّ المذهب فصار شافعيًّا أشعريًّا أصوليًّا منطقيًّا جدليًّا خلافيًّا، وكان حسن الأخلاق، وقد تكَلَّموا فيه بأشياءَ اللهُ أعلم بصحتها، وقد كانت ملوك بني أيوب كالمعظَّم والكامل يُكرمونَه وإن كانوا لا يحبُّونه كثيرًا، وقد فوَّضَ إليه المعَظَّم تدريس العزيزية، فلما ولي الأشرفُ دمشق عزله عنها ونادى بالمدارس أن لا يشتغل أحدٌ بغير التفسير والحديث والفقه، ومن اشتغل بعلومِ الأوائل نفيتُه، فأقام الشيخ سيف الدين بمنزله إلى أن توفِّي بدمشق، ودُفِنَ بتربته بسفح قاسيون، وكان قد اشتغل ببغداد على أبي الفتح نصر بن فتيان بن المنى الحنبلي، ثم انتقل إلى مذهبِ الشافعي فأخذ عن ابن فضلان وغيره، وحَفِظَ طريقة الخلاف للشريف، وزوائد طريقة أسعد الميهني، ثم انتقل إلى الشام واشتغل بعلوم المعقول. قال الذهبي: \"تفنَّنَ في علم النظر، والفلسفة وأكثَرَ من ذلك. وكان من أذكياءِ العالم, ثم دخل الديارَ المصرية وتصَدَّرَ بها لإقراء العقليات بالجامع الظافري. وأعاد بمدرسةِ الشافعي. وتخرَّج به جماعة. وصنَّف تصانيفَ عديدة. ثم قاموا عليه، ونسبوه إلى فساد العقيدة والانحلال والتعطيل والفلسفة. وكتبوا محضرًا بذلك. قال القاضي ابن خلكان: وضعوا خطوطَهم بما يستباحُ به الدم، فخرج مستخفيًا إلى الشام فاستوطن حماة\" ثم تحوَّل إلى دمشق فدرس بالعزيزية، ثم عُزِلَ عنها ولزم بيته إلى أن مات، وله ثمانون عامًا- رحمه الله تعالى وعفا عنه."},{"id":2502,"title":"اكتمال بناء المدرسة المستنصرية .","date":["العام الهجري :631","الشهر القمري : رجب","العام الميلادي :1234"],"text":"كَمُل بناء المدرسة المستنصرية ببغداد ولم يُبنَ مدرسةٌ قبلَها مِثلُها، ووقفت على المذاهب الأربعة من كل طائفة اثنان وستون فقيهًا، وأربعة معيدين، ومدرس لكل مذهب، وشيخ حديث وقارئان وعشرة مستمعين، وشيخ طب، وعشرة من المسلمين يشتغلون بعلم الطب، ومكتب للأيتام، وقدر للجميع من الخبز واللحم والحلوى والنفقة، ما فيه كفاية وافرة لكل واحد، ولما كان يوم الخميس خامس رجب حضرت الدروس بها وحضر الخليفة المستنصر بالله بنفسه الكريمة وأهل دولته من الأمراء والوزراء والقضاة والفُقَهاء والصوفية والشعراء، ولم يتخلَّفْ أحد من هؤلاء، وعمل سماط عظيم بها أكل منه الحاضرون، وحُمِلَ منه إلى سائر دروب بغداد من بيوتات الخواصِّ والعوام، وخلع على جميع المدرسين بها والحاضرين فيها، وعلى جميعِ الدولة والفقهاء والمعيدين، وكان يومًا مشهودًا، وأنشدت الشعراء الخليفةَ المدائح الرائقة والقصائد الفائقة، وقد ذكَرَ ذلك ابن الساعي في تاريخه مطولًا مبسوطًا شافيًا كافيًا، وقرَّر لتدريس الشافعية بها الإمام محيي الدين أبو عبد الله بن فضلان، وللحنفية الإمام العلامة رشيد الدين أبو حفص عمر بن محمد الفرغاني، وللحنابلة الإمام العالم محيي الدين يوسف بن الشيخ أبي الفرج بن الجوزي، ودرَّسَ عنه يومئذ ابنُه عبد الرحمن نيابة لغيبته في بعض الرسالات إلى الملوك، ودرس للمالكية يومئذ الشيخ الصالح العالم أبو الحسن المغربي المالكي نيابة أيضًا، حتى يعيَّنَ شَيخٌ غيره، ووُقِفَت خزائنُ كتب لم يُسمَعْ بمثلها في كثرتِها وحسن نسخها وجودة الكتب الموقوفة بها، وكان المتوليَ لعمارة هذه المدرسة مؤيد الدين أبو طالب محمد بن العلقمي الذي وزر بعد ذلك، وقد كان إذَّاك أستاذ دار الخلافة."},{"id":2503,"title":"قصد كيقباذ صاحب بلاد الروم السلجوقي لقتال خلاط .","date":["العام الهجري :631","الشهر القمري : شعبان","العام الميلادي :1234"],"text":"قصد السلطان علاء الدين كيقباذ بن كيخسرو السلجوقي، صاحب بلاد الروم، مدينةَ خلاط، فخرج المَلِكُ الكامل من القاهرة بعسكره، ليلة السبت خامس شعبان، واستناب ابنَه الملك العادل، فوصل إلى دمشق، وكتب إلى ملوك بني أيوب يأمرُهم بالتجهز، للمسير بعساكرهم إلى بلاد الروم، وخرج الكامِلُ من دمشق، فنزل على سلمية في شهر رمضان، ورتَّب عساكِرَه، وسار إلى منبج، فقَدِمَ عليه عسكر حلب، وغيرُه من العساكر، فسار وقد صار معه ستة عشر ملكًا، وقيل: بل كانوا ثمانية عشر ملكًا، فعرَضَهم الكامل على إلبيرة أطلابًا بأسلحتهم، فلكثرة ما أعجب بنفسِه قال: هذه العساكر لم تجتَمِعْ لأحد من ملوك الإسلام، وأمر بها فسارت شيئًا بعد شيءٍ نحو الدربند، وقد جدَّ السلطان علاء الدين في حِفظِ طرقاته بالمقاتلة، ونزل الكامِلُ على النهر الأزرق، وهو بأول بلد الروم، ونزل عساكر الروم فيما بينه وبين الدربند وصعد الرجَّالة إلى فم الدربند، بالقرب من نور كغال، وبنوا عليه سورًا يمنع العساكِرَ من الطلوع، وقاتلوا من أعلاه، فقلَّت الأقوات عند عسكر الكامل، واتَّفَق مع قلة الأقوات وامتناع الدربند نفورُ ملوك بني أيوب من الملك الكامل، بسبب أنَّه حَفِظَ عنه أنَّه لما أعجبته كثرة عساكره بالبيرة، قال لخواصه: إن صار لنا مُلك الرومِ فإنَّا نعوض ملوك الشام والشرق مملكةَ الروم، بدل ما بأيديهم، ونجعل الشامَ والشرق مضافًا إلى مُلك مصر، فحَذِرَ من ذلك المجاهد صاحب حمص، وأعلم به الأشرف موسى صاحب دمشق، وأحضر بني عمِّه وأقاربَه من الملوك وأعلمَهم ذلك، فاتفقوا على الملك الكامل، وكتبوا إلى السلطان علاء الدين بالميلِ معه وخذلان الكامل، وسيَّروا الكتب بذلك، فاتفق وقوعُها في يد الملك الكامل، فكتمها ورحل راجعًا، فأخذ السلطانُ علاء الدين كيقباذ ملك الروم قلعةَ خرتبرت وست قلاع أخر كانت مع الملوك الأرتقية، في ذي القعدة، فاشتدَّ حنقُ الملك الكامل؛ لِما حصل على أمرائه وعساكره من صاحبِ الروم في قلاع خرتبرت، ونسب ذلك إلى أهلِه من الملوك، فتنكَّرَ ما بينه وبينهم."},{"id":2504,"title":"وباء عظيم في مصر مات فيه الألوف .","date":["العام الهجري :632","العام الميلادي :1234"],"text":"كان في مصر الوباء العظيم؛ حيث مات في شهر نيف وثلاثون ألف إنسان، واستمَرَّ هذا الوباء مدة ثلاثة أشهر، فمات بالقاهرة خلقٌ كثُر، بلغت عدتُهم زيادة على اثني عشر ألفًا، سوى من مات بالريف."},{"id":2505,"title":"الملك الكامل صاحب مصر وخلافه مع الأمراء .","date":["العام الهجري :632","الشهر القمري : جمادى الأولى","العام الميلادي :1235"],"text":"عاد الملكُ الكامل إلى قلعة الجبل من بلاد الشرق، وقد توحَّشَ ما بينه وبين أخيه الأشرف صاحب دمشق وغيره من الملوك، فقبَضَ الكامل على المسعود صاحب آمد واعتقله في برجٍ هو وأهلَه، يوم الاثنين سادس عشر جمادى الأولى، لممالأتِه لهم، فملك صاحبُ الروم حرَّان بالسيف، وعاد إلى بلاده، بعدما استولى على ما كان بها من الأموال، فلما بلغ الكامل ذلك أمر العساكر أن تتجهز للمسير إلى الشرق، وأقطع ابنَ الأمير صلاح الدين الإربلي صنافيرَ بالقليوبية، وجعل أقاربَ والده ومماليكه معه، وعدتهم سبعة عشر رجلًا."},{"id":2506,"title":"وفاة ابن الفارض الصوفي .","date":["العام الهجري :632","الشهر القمري : جمادى الأولى","العام الميلادي :1235"],"text":"هو أبو حفص عمر بن أبي الحسن علي بن المرشد بن علي، الحموي الأصل، المصري المولد والدار والوفاة، ولد في الرابع من ذي القعدة سنة 576 بالقاهرة. وكان أبوه يكتب فروض النساء والرجال، ناظم التائية, وهي قصيدة طويلةٌ أكثر من سبعمائة بيت في السلوك على طريقة المتصوفة المنسوبين إلى الاتحاد، وقد تكلَّمَ فيه غير واحد من المشايخ بسبب قصيدته المشارِ إليها، وقد ذكره الذهبي وحطَّ عليه فقال: \"إن لم يكن في تلك القصيدةِ صريحُ الاتحاد الذي لا حيلةَ في وجوده، فما في العالم زندقةٌ ولا ضلال، اللهمَّ ألهمنا التقوى، وأعذنا من الهوى، فيا أئمَّة الدين ألا تغضبون لله؟! فلا حول ولا قوة إلا بالله\". مات وقد قارب السبعين، توفي بالقاهرة في يوم الثلاثاء الثاني من جمادى الأولى، ودفن من الغد بسفح المقطم، وقبره معروف به يُقصَد للزيارة، وكان قد سافر إلى مكة وبقي فيها قرابة الخمسة عشر سنة متصلًا فيها بالصوفية، ولكن له شطحات كثيرة في قصائده على عادة المتصوفة، وخاصة في هيامِهم وغزلهم مع قَصدِهم الذاتَ الإلهيَّةَ- تعالى الله عما يقولون علوًّا كبيرًا."},{"id":2507,"title":"سقوط قرطبة في يد الأسبان .","date":["العام الهجري :633","العام الميلادي :1235"],"text":"قام الأسبان بقيادة فرديناند الثالث ملك قشتالة بالاستيلاء على قرطبة وحوَّلوا جامعها إلى كنيسة."},{"id":2508,"title":"نهاية حكم الموحدين بالأندلس .","date":["العام الهجري :633","العام الميلادي :1235"],"text":"كانت دولة الموحدين قد قويت أولًا في الأندلس، ولكنها لم تستطع أن تقفَ لوحدها في وجه التوسُّعِ الصليبي بصورةٍ دائمةٍ، كما لم يدُمْ صُمودُهم طويلًا إثر ذلك النصر الذي أحرزوه في معركة الأرك سنة 591 فقد جاءت هزيمتهم الماحقة في معركة العقاب سنة 609 على أيدي تحالف ملوك الصليبيين في الأندلس، والذي نجم عنه انسحاب الموحدين من الأندلس شيئًا فشيئًا، وخاصة أن الصليبيين بقوا في حروبهم التي سموها حروبَ الاسترداد، فأخذت المدن الأندلسية تتساقط شيئًا فشيئًا، وانمحت دولةُ الموحدين من الأندلس وخرجوا منها نهائيًّا ولم يبق في الأندلسِ سوى بني الأحمر في غرناطة."},{"id":2509,"title":"القوات البرتغالية تحتل مدينة طلبيرة .","date":["العام الهجري :633","العام الميلادي :1235"],"text":"قامت القوات البرتغالية بقيادة مَلِكِهم باحتلال طلبيرة وغيرها من البلاد التي سيطرت عمليًّا عليها وعلى جميع المناطقِ التي تشكِّلُ اليوم بلاد البرتغال."},{"id":2510,"title":"وفاة ابن دحية الكلبي .","date":["العام الهجري :633","الشهر القمري : ربيع الأول","العام الميلادي :1235"],"text":"هو أبو الخطاب عمر بن الحسن بن علي بن محمد بن فرج بن خلف بن قومس بن أحمد بن دحية بن خليفة الكلبي الحافظ، شيخ الديار المصرية في الحديث، ولد سنة 546. كان يذكر أنه من ولد دحية الكلبي، وأنه سبطُ أبي البسام الحسيني الفاطمي. كان بصيرًا بالحديث معتنيًا بتقييده، مكبًّا على سماعه، حسنَ الحَطِّ معروفًا بالضبط، له حظٌّ وافر من اللغة، ومشاركة في العربية وغيرها. وهو أول من باشر مشيخة دار الحديث الكامليَّة بها، وقد كان يتزيد في كلامه، فترك الناس الرواية عنه وكذَّبوه، وقد كان الكامِلُ مقبلًا عليه، فلما انكشف له حاله أخذ منه دار الحديث وأهانه، توفي بالقاهرة ودفن بقرافة مصر، قال ابن خلكان: وكان من أعيان العلماء ومشاهير الفضلاء، متقنًا لعلم الحديث وما يتعلَّقُ به، عارفًا بالنحو واللغة وأيَّام العرب وأشعارها، اشتغل ببلادِ المغرِب، ثمَّ رحل إلى الشام ثم إلى العراق، واجتاز بإربل سنة 604، فوجد ملكها المعظم مظفر الدين بن زين الدين يعتني بالمولد النبوي، فعمل له كتاب \" التنوير في مولد السراج المنير \" وقرأه عليه بنفسه، فأجازه بألف دينار، ولي قضاء دانية مرتين، ثم صُرِف عن ذلك لسيرة نُعِتَت عليه، فرحل منها. روى عنه الدبيثي فقال: \"كان له معرفة حسنة بالنحو واللغة، وأنسة بالحديث، فقيهًا على مذهب مالك، وكان يقول: إنه حفظ \" صحيح مسلم \" جميعه، وأنه قرأه على بعض شيوخ المغرب من حفظه، ويدعي أشياء كثيرة. قلت (الذهبي): كان صاحب فنون، وله يد طولي في اللغة، ومعرفة جيدة بالحديث على ضعف فيه. قرأت بخط الضياء الحافظ قال: لقيت الكلبيَّ بأصبهان، ولم أسمع منه شيئًا، ولم يعجبني حالُه، وكان كثير الوقيعة في الأئمة، وأخبرني إبراهيم السنهوري بأصبهان أنه دخل المغرب، وأن مشايخ المغرب كتبوا له جرحه وتضعيفَه. وقد رأيتُ منه أنا غير شيء ممَّا يدل على ذلك\" قال ابن نقطة: \"كان موصوفًا بالمعرفة والفضل، ولم أره إلَّا أنه كان يدعي أشياء لا حقيقة لها. ذكر لي أبو القاسم بن عبد السلام - ثقة - قال: نزل عندنا ابنُ دحية، فكان يقول: أحفظ \" صحيح مسلم \"، و\" الترمذي \"، قال: فأخذت خمسة أحاديث من \" الترمذي \"، وخمسة من \" المسند \" وخمسة من الموضوعات فجعلتها في جزء، ثم عرضتُ عليه حديثًا مِن \" الترمذي \"، فقال: ليس بصحيح، وآخر فقال: لا أعرفه. ولم يعرف منها شيئًا. قلت (الذهبي): ما أحسن الصدق، لقد أفسد هذا المرءُ نَفسَه\". قال ابن كثير: وقد تكلَّمَ الناس فيه بأنواع من الكلام، ونسبه بعضهم إلى وضعِ حديثٍ في قَصرِ صلاة المغرب، ولابن دحية مصنفات منها: المطرب في أشعار أهل المغرب، ونهاية السول في خصائص الرسول، والنبراس في خلفاء بني العباس، وغيرها."},{"id":2511,"title":"مسير الملك الكامل الأيوبي نحو الشرق .","date":["العام الهجري :633","الشهر القمري : جمادى الأولى","العام الميلادي :1236"],"text":"سار الملك الكامل من القاهرة بعساكره يريد بلاد الشرق، فنازل الرَّها حتى أخذها يوم الأربعاء ثالث عشر جمادى الأولى، وأسَرَ منها زيادةً على ثمانمائة من الأمراء، وهدم قلعتَها، ونازل حران، وأخذها بعد حصارٍ وقتال في رابع عشر جمادى الآخر، وأسَرَ من كان بها من أجناد السلطان علاء الدين كيقباذ، وأمرائه ومقدميه الصوباشية، وكانوا سبعمائة وخمسة وعشرين رجلًا، فمات كثير منهم في الطرقات، ثم نزل الكامِلُ على دنيسر وخربها، فورد عليه الخبَرُ بأن التتر قد وصلوا إلى سنجار، في مائة طلب، كل طلب خمسمائة فارس، وأخذ الكامِلُ قلعة السويداء عَنوةً، وأسر من بها في سابع عشر جمادى الآخر، وهدمَها، وأخذ قطينًا، وأسر من بها في رجب، وفي تاسع عشره: بعث الكامل جميع الأسرى إلى ديار مصر، وعِدَّتهم تزيد على الثلاثة آلاف، وعاد إلى دمشق، وسلم الشرق لابنه الملك الصالح أيوب."},{"id":2512,"title":"استعادة الكامل الأيوبي الرها وحران من الروم .","date":["العام الهجري :633","الشهر القمري : جمادى الأولى","العام الميلادي :1236"],"text":"قطع الكامِلُ وأخوه الأشرف الفرات وأصلحا ما كان أفسَدَه جيش الروم من بلادهما، فاستعاد من الروم حران والرها وغيرهما، وأخرب قلعةَ الرها ونزل على دنيسر فأخربها ومعه أخوه الأشرف، وبينما هم في ذلك جاء كتاب بدر الدين لؤلؤ إلى الأشرف يقول: قد قطع التتارُ دجلة في مائة طلب كل طلب خمسمائة فارس، ووصلوا إلى سنجار، فخرج إليهم معين الدين بن كمال الدين بن مهاجر فقتلوه على باب سنجار، ثم رجع التتارُ، ثمَّ عادت، فأمَّنَهم الأشرف للتوجُّه إلى جهة الشرق."},{"id":2513,"title":"أبو عبد الله الحفصي يعلن استقلاله عن دولة الموحدين في تونس .","date":["العام الهجري :634","العام الميلادي :1236"],"text":"عاد أبو زكريا الحفصي إلى تونس بعد حملته المظفرة، وأعلن على رؤوس الملأ استقلالَه بالملك، وانقطاع تبعيَّته للموحِّدين رسميًّا، وبايع لنَفسِه بيعةً عامَّةً في هذه السَّنة وضرب السكَّة باسمِه، وأمر أن يُخطَبَ له باسمِه على كل منابِرِ بلاده، ثم بايع لابنه أبي يحيى وليًّا للعهدِ سنة 638(1246م)."},{"id":2514,"title":"دخول التتار لإربل .","date":["العام الهجري :634","العام الميلادي :1236"],"text":"حاصرت التتار إربل بالمجانيق ونقبوا الأسوارَ حتى فتحوها عَنوةً فقَتَلوا أهلها وسَبَوا ذراريهم، وامتنعت عليهم القلعةُ مُدَّةً، وفيها النائبُ من جهة الخليفة، فدخل فصلُ الشتاء فأقلعوا عنها وانشَمَروا إلى بلادهم، وقيل إنَّ الخليفة جهَّزَ لهم جيشًا فانهزم التتار."},{"id":2515,"title":"وفاة الملك العزيز صاحب حلب وتولي ابنه بعده .","date":["العام الهجري :634","الشهر القمري : صفر","العام الميلادي :1236"],"text":"هو الملك العزيز الظاهر صاحِبُ حلب محمد بن السلطان الملك الظاهر غياث الدين غازي بن الملك الناصر صلاح الدين الأيوبي، وهو وأبوه وابنه الناصر أصحاب حلب من أيام الناصر، توفي وله من العمر أربع وعشرون سنة، وكان مدبِّرُ دولته الطواشي شهاب الدين، وقام في الملك بعده ولده الناصر صلاح الدين يوسف وعمره نحو السبع سنين، وقام بتدبير أمره الأميران لؤلؤ الأميني، وعز الدين عمر بن محلي، وبينهما وزيرُ الدولة جمال الدين الأكرم، يراجع السترَ الرفيع صفية خاتون ابنة الملك العادل، على لسان جمال الدولة إقبال، وقد حضر الأمير بدر الدين بدر بن أبي الهيجاء وزين الدين قاضي حلب، إلى الملك الكامل، بزردية العزيز وكزاغنده، وخوذته ومركوبه، فأظهر الكامِلُ الألم لموته، وقصَّرَ في إكرامهما، وحلَفَ للناصر، وشرط أشياءَ، وأعاد الرسولين، ثم أرسل خلعةً للناصر بغير مركوب، ومعها عِدَّة خِلَع للأمراء الحلبيين، وخِلعةً للصالح صلاح الدين أحمد بن الظاهر غازي، صاحِب عينتاب، فاستوحشت أم الظاهر من أخيها الكامل، ولم توافِقْ على لبس أحد من الأمراء الخِلَع، فلبس الناصِرُ وحده خِلعةَ الكامل، وردَّ الرسول الوارِدَ إلى الصالح صلاح الدين بخِلعتِه."},{"id":2516,"title":"محاولة الملك الكامل الأيوبي أخذ حلب .","date":["العام الهجري :635","العام الميلادي :1237"],"text":"لَمَّا شرَعَ الملك الكامل بالتجهز لأخذ حلب، خافه المجاهِدُ أسد الدين شيركوه الصغيرُ صاحب حمص، وبعث ابنَه المنصورَ إبراهيم فتقَرَّر الأمرُ على أن يحمِلَ المجاهِدُ كُلَّ سنة للملك الكامل ألفي ألف درهم، فعفا عنه، وكان منذ دخلَ الكامِلُ إلى قلعة دمشق قد مَرِضَ وتوفِّي فيها."},{"id":2517,"title":"اضطرابات بين الأيوبيين بعد وفاة الكامل صاحب مصر .","date":["العام الهجري :635","العام الميلادي :1237"],"text":"قوي المجاهِدُ أسد الدين شيركوه الأصغر صاحب حمص بعد موت الكامل، وأغار على حماة وحصرها واستعدَّ أهل حلب، واستنجدوا عسكرًا من الخوارزمية، وعسكرًا من التركمان، كان قد صار إليهم عِدَّة من أصحاب الملك الكامل، فأكرموهم، وبَعَثوا إلى السلطان غياث الدين كيخسرو بن كيقباذ، ملك الروم، يسألونه إرسالَ نجدة، فأمدَّهم بخيار عسكره، وخرجوا فمَلَكوا المعرَّة، ونازلوا حماة، وقاتلوا المظفَّر صاحبَها، فثبت لهم وامتنع عليهم وقاتلهم، وكان الملك الصالح نجم الدين أيوب بن الكامل على الرحبةِ منازلًا لها، فلما بلغه موتُ أبيه الملك الكامل رحل عنها، فطَمِعَ فيها مَن معه من الخوارزمية، وخرجوا عن طاعته، وهموا بالقَبضِ عليه، فقصد سنجار، وامتنع بها مُدَّة، وترك خزائنَه وأثقاله، فانتهبها الخوارزميَّة، وتحكموا في البلاد الجزرية، وطَمِعَ فيه السلطان غياث الدين كيخسرو بن كيقباذ ملك بلاد الروم، وبعث إلى الناصر صلاح الدين أبي المظفر يوسف صاحب حلب توقيعًا بالرَّها وسروج، وكانا مع الصالحِ نجم الدين أيوب، وأقطع المنصورُ ناصر الدين الأرتقي، صاحب ماردين، مدينةَ سنجار ومدينة نصيبين، وهما من بلاد الصالحِ أيضًا، وأقطع المجاهِدُ أسد الدين شيركوه، بلدة عانة وغيرها من بلاد الخابور، وعزم السلطانُ غياث الدين كيخسرو على أن يأخذ لنَفسِه من بلاد الصالح أيضًا آمد وسميساط، وصار الملك الصالح محصورًا بسنجار، فطمع فيه الملك الرحيم بدر الدين لؤلؤ صاحب الموصل وحصره بسنجار في ذي القعدة، وأراد حمْلَه إلى بغداد في قفص حديد؛ كراهةً فيه، لِما كان عنده من التجبر والظلم والتكبر، فلما أشرف بدر الدين لؤلؤ على أخذ سنجار بعث الصالح إليه القاضي بدر الدين يوسف بن الحسن الزرزاري قاضي سنجار، بعد ما حَلَق لحيته، ودلَّاه من السور، وكان القاضي الزرزاري متقدمًا في الدولةِ الأشرفية، فتوجه القاضي في خفيةٍ إلى الخوارزمية، واستمالهم وطيَّبَ خواطِرَهم، بكثرة ما وعدهم به فمالوا إليه، بعد ما كانوا قد اتفَقوا مع صاحب ماردين، وقصدوا بلاد الملك الصالح نجم الدين أيوب، واستولوا على العُمَّال، ونازلوا حران وكان الملك الصالح قد ترك بها ولده المغيث فتح الدين عمر بن الصالح فخاف من الخوارزمية، وسار مختفيًا حتى فرَّ إلى قلعة جعبر، فساروا خَلْفَه، ونهبوا ما كان معه، وأفلَتَ منهم في شرذمة يسيرةٍ إلى منبج، فاستجار بعمة أبيه، الصاحبة ضيفة خاتون، أم الملك العزيز، صاحب حلب، فلم تقبَلْه، ففَرَّ إلى حران، وفيها أتاه كتابُ أبيه يأمره بموافقة الخوارزمية، والوصولِ بهم إليه لدفع بدر الدين لؤلؤ صاحبِ الموصل، فاجتمع المغيثُ عمر، والقاضي بدر الدين قاضي سنجار بالخوارزمية، والتزم لهم القاضي أن يُقطَعوا سنجارَ وحران والرها، فطابت قلوبُهم، وحلفوا للملك الصالح، وقاموا في خدمةِ ابنه الملك المغيث، وساروا معه إلى سنجار، فأفرج عنها عسكر الموصِل، يريدون بلادهم، وأدركهم الخوارزميَّة، وأوقعوا بهم وقعةً عظيمة، فر فيها بدر الدين لؤلؤ بمفردِه على فرس سابق، ثم تلاحقَ به عسكره، واحتوت الخوارزميَّة على سائرِ ما كان معه، فاستغنوا بذلك، وقوِيَ الملك الصالح بالخوارزميَّة وبالفتح قوةً زائدة، وعظُمَ شأنه، وسيَّرَ الخوارزمية إلى آمد، وعليها عسكر السلطان غياث الدين كيخسرو صاحب الروم، وبها المعظم غياث الدين تورانشاه بن الملك الصالح نجم الدين أيوب وهو محصورٌ منهم، فأوقعوا بهم ورحَّلوهم عن آمد فخرج الصالح من سنجار إلى حصن كيفا، وبعث الملكُ العادل بن الملك الكامل من مصرَ إلى أهل حلبٍ يريد منهم أن يجروا معه على ما كانوا عليه مع أبيه الملك الكامل من إقامة الخطبة له على منابر حلَب، وأن تُضرَبَ له السكة فلم يُجِبْ إلى ذلك، وقَدِمَ رسول غياث الدين كيخسرو ملك الروم، فزوج غازية خاتون ابنة العزيز السلطان غياث الدين، وأنكح الملك الناصر صاحب حلب أخت السلطان غياث الدين، وتولى العقدَ الصاحِبُ كمال الدين بن أبي جرادة بن العديم، وخرجَ في الرسالة إلى بلاد الروم، وعقد للملك الناصرِ صاحِبِ حلب على ملكة خاتون أخت السلطان غياث الدين، فبعث غياثُ الدين رسولًا إلى حلب، فأُقيمَت له بها الخطبة، وخرج الملكُ الجواد من دمشق في أول ذي الحجة، يريد محاربةَ النَّاصِرِ داود بن الملك المعَظَّم صاحب كرك، بأذنبا بالقرب من نابلس، فانكسر الناصر كسرةً قبيحة، في يوم الأربعاء رابع عشر ذي الحجة، وانهزم إلى الكرك، فغَنِمَ الجواد ما كان معه، وعاد إلى دمشقَ، وفرَّقَ ستَّمائة ألف دينار وخمسة آلاف خلعة، وأبطل المكوس والخمور، ونفى المغاني، وعاد من كان في دمشق من عسكر مصرَ ومعهم الأميرُ عماد الدين بن شيخ الشيوخ إلى القاهرة، بسناجق الناصر، في السادس والعشرين من ذي الحجة، فلم يعجب الملك العادل ذلك، وخاف من تمكُّن الملك الجواد."},{"id":2518,"title":"انهيار دولة بني هود في الأندلس وقيام دولة بني الأحمر في غرناطة .","date":["العام الهجري :635","العام الميلادي :1237"],"text":"بعد اغتيال محمد بن يوسف بن هود انهارت دولتُه وانتهت، فقامت في غرناطة دولةُ بني نصر من بني الأحمر بعد أن تحرَّرَت من سيطرة بني هود, بزعامة أبي عبد الله بن يوسف بن نصر, ودولة بني الأحمر هي آخرُ دول الطوائفِ في الأندلس."},{"id":2519,"title":"قصد التتار بغداد .","date":["العام الهجري :635","العام الميلادي :1237"],"text":"ورد الخَبَرُ باستيلاء الصالح نجم الدين أيوب بن الكامل على سنجار ونصيبين والخابور، وقدم رسول الخليفة بمالٍ إلى الملك الكامل، ليستخدِمَ به عسكرًا للخليفة، فإنَّه بلغه توجه التتر إلى بغداد، فقام الملك الكامل لَمَّا سلم إليه كتاب الخليفة، ووضعه على رأسه، وكان جملةُ ما حضر من المال مائة ألف دينار مصرية، فأمرَ الملك الكامل أن يخرج من بيت المال مائتا ألف دينار، ليستخدم بها العساكر، وأن يجرَّد من عساكر مصر والشام عشرة آلاف، نجدةً للخليفة، وأن يكون مُقَدَّم العساكر الناصر داود بن الملك المعظم، وألا يُصرَف مما حضر من المال شيء، بل يعاد بكمالِه إلى خزانة الخليفة، فتولى استخدامَ الأجناد الأميران ركن الدين الهيجاوي، وعمادُ الدين بن موسك، وأن يكونا مع الناصِرِ داود في خدمته، فاستخدم الناصرُ العسكر، وسار إلى بغداد، وهم نحو ثلاثة آلاف فارس."},{"id":2520,"title":"استيلاء الأسبان على مدن المسلمين الأندلسية .","date":["العام الهجري :635","العام الميلادي :1237"],"text":"من حين تخلى الموحِّدون عن الأندلس إثرَ هزيمتهم المُرَّة أمام التحالف الصليبي الأسباني في معركة العقابِ وبعدها بدأت المدنُ الأندلسيَّة الإسلامية تتساقَطُ وتقع في أيدي الأسبانِ الصليبيين، وسَمَّوا حركتَهم تلك بحروب الاسترداد فسَقَطت قرطبة وبطليوس هذه السنة، وسقطت ماردةُ قبلها بسنوات، وكذلك جزر البليار، ثم سقطت بلنسية ومرسية سنة 641 ثم إشبيلية سنة 646 ثم شلب سنة 648 ثم قادس سنة 660."},{"id":2521,"title":"وفاة الملك الأشرف صاحب دمشق وملك أخيه بعده .","date":["العام الهجري :635","الشهر القمري : محرم","العام الميلادي :1237"],"text":"هو أبو الفتح موسى بن الملك العادل سيف الدين أبي بكر بن أيوب، الملقب بالملك الأشرف مظفر الدين. ولد سنة 576، بالديار المصرية بالقاهرة، وقيل بقلعة الكرك, ونشأ بالقُدس الشريف بكفالة الأمير فخر الدين عثمان الزنجاري، وكان أبوه يحبه، وكذلك أخوه المعظَّم, مليحَ الهيئة، حلو الشمائل، وكان فيه دينٌ وخوف من الله وفضيلة، على لَعِبِه, وعكوف على الملاهي- عفا الله عنه - وكان جوادًا سمحًا فارسًا شجاعًا. وكان يبالغ في الخضوع للفقراء ويزورهم ويعطيهم، ويجيز على الشعر، ويبعث في رمضان بالحلاوات إلى أماكن الفقراء. كان محبوبًا إلى الناس مسعودًا مؤيَّدًا في الحروب، قيل: ما هُزِمَت له راية, لقِيَ نور الدين أرسلان شاه صاحب الموصل، وكان من الملوك المشاهير الكبار، وتواقعا في مصافَّ فكَسَره الأشرف، وذلك سنة 600, وله فهمٌ وذكاء وسياسة, وهو باني دار الحديث الأشرفية، وجامع التوبة، وجامع جراح، وكان قد بنى دار حديث بالسفح وبالمدينة للشافعية أخرى، ونقل إليها كتبًا سَنيَّة نفيسة، وبنى جامع التوبة بالعقبية، والذي كان محله خانًا للزنجاري فيه من منكرات كثير، وبنى مسجِدَ القصب وجامع جراح ومسجد دار السعادة, وقد استنابه أبوه على مدن كثيرة بالجزيرة، منها الرها وحران، ثم اتسعت مملكته حين ملك خلاط وميافارقين، وبسط العدل على الناس وأحسن إليهم إحسانًا لم يعهدوه ممَّن كان قبله، وعَظُمَ وَقعُه في قلوب الناس، وبَعُدَ صِيتُه، ثم ملك نصيبين وسنجار ومعظم بلاد الجزيرة. لَمَّا أخذت الفرنج دمياط سنة 616 تأخَّر عن إنجاد أخيه الملك الكامل؛ لِمنافرةٍ كانت بينهما، فجاءه أخوه الملك المعظَّم وأرضاه، ولم يزل يلاطفه حتى استصحبه معه، فصادف عقيبَ وُصولِه إلى مصر بأشهر انتصار المسلمين على الفرنج وانتزاع دمياط من أيديهم، وكانوا يرَون ذلك بسبب يُمن غرة الأشرف, ولما مات الملك المعظم سنة 624 قام بالأمر بعده ولده الملك الناصر داود، فقصده عمه الملك الكامل من الديار المصرية ليأخُذَ دمشق منه، فاستنجد بعَمِّه الملك الأشرف، فوصل إليه، واجتمع به في دمشق، ثم توجَّه إلى الكامل واتفقا على أخذ دمشق من الناصر وتسليمها إلى الأشرف، ويبقى للناصر الكرك والشوبك ونابلس وبيسان وتلك النواحي، وينزل الأشرفُ عن حران والرها وسروج والرقة ورأس عين، ويسَلِّمها إلى الكامل، فاستتب الحالُ على ذلك, وانتقل الأشرف إلى دمشق واتخذها دارَ إقامة وأعرض عن بقية البلاد، ولَمَّا ملك الأشرف دمشق في سنة 626 نادى مناديه فيها أن لا يشتغل أحد من الفقهاء بشيء من العلوم سوى التفسير والحديث والفقه، ومن اشتغل بالمنطقِ وعلوم الأوائل نفي من البلد، وكان البلد به في غاية الأمن والعدل، توفِّيَ الأشرف يوم الخميس رابع المحرم، بقلعة المنصورة، ودُفِنَ بها حتى أنجزت تربته التي بنيت له شمالي الكلاسة، ثم حُوِّلَ إليها في جمادى الأولى، وقد كان ابتداء مرضه في رجب من السنة الماضية، واختلفت عليه الأدواءُ، فلما كان آخر السنة تزايد به المرض واعتراه إسهال مفرط، فخارت قوته حتى توفي، وكانت مدة ملكه بدمشق ثماني سنين وأشهر, وقد أوصى الأشرف بالملك من بعده لأخيه الصالح إسماعيل، فلما توفي أخوه ركب في أبهة الملك ومشى الناسُ بين يديه، وركب إلى جانبه صاحب حمص وعز الدين أيبك المعظمي حامل الغاشية على رأسه."},{"id":2522,"title":"استيلاء الملك الكامل على دمشق .","date":["العام الهجري :635","الشهر القمري : جمادى الأولى","العام الميلادي :1238"],"text":"بعد موت الأشرف موسى بن العادل أبي بكر بن أيوب صاحب دمشق قام من بعده بدمشق أخوه الملك الصالح عماد الدين إسماعيل، صاحِبُ بصرى، بعهدٍ من أخيه له، فاستوفى الملك الصالح عماد الدين على دمشقَ وبعلبك، وبعث ابنه الملك المنصور محمودًا إلى الشرق، ليتسَلَّم سنجار ونصيبين والخابور من نوَّاب الشرق، وبعث إلى المجاهد صاحب حمص، وإلى المظفر صاحب حماة، وإلى الحلبيين أيضًا، ليحلفوا له ويتفقوا معه على القاعدة التي تقَرَّرت بينهم وبين الأشرف على مخالفة الكامل، فأجابوا إلَّا صاحب حماة، فإنَّه مال مع الكامل، وبعث إليه يُعلِمُه بميله إليه، فسُرَّ الكامل بذلك، ثمَّ إن الملك الصالح عماد الدين صادر جماعة من الدماشقة، الذين قيل عنهم إنهم مع الملك الكامل، منهم العلم تعاسيف، وأولاد مزهر، وحبسَهم في بصرى، فتجهز الكامِلُ، وخرج من قلعة الجبل بعساكره، بكرةَ يوم الخميس في الثالث والعشرين من صفر، واستناب على مصر ابنه الملك العادل، وأخذ معه الناصر داود بن الملك المعظم، وهو لا يشُكُّ أن الملك الكامل يسلم إليه دمشق، لما كان قد تقرَّرَ بينهما، فكاتب الكامِلُ نائب قلعة عجلون حتى سَلَّمها، ونزل على دمشق بمسجد القدم، في الثالث والعشرين من ربيع الأول، وقد تحصنت وأتتها النجدات، فحاصرها وقطع عنها المياه، وضايقَها حتى غلت بها الأسعار، وأحرق العقيبة والطواحين، وألحَّ على أهلها بالقتال، وكان الوقتُ شتاء فأذن الصالح إسماعيل، وسَلَّم دمشق لأخيه الكامل، فعَوَّضَه عنها بعلبك والبقاع، وبصرى والسواد، فتسَلَّم الكامل دمشق في عاشر جمادى الأولى، وسار الصالح إسماعيل إلى بعلبك، لإحدى عشرة بقيت من جمادى الأولى، فنزل الملك الكامل بالقلعة، وأمر بنصب الدهليز بظاهر دمشق، وسيَّرَ المظفر صاحب حماة إلى حمص، وأطلق الفلك المسيري من سجن قلعة دمشق. كان قد سجنه الملك الأشرف, ونقل الأشرف إلى تربته، وأمر الكامِلُ في يوم الاثنين سادس جمادى الآخرة ألَّا يصلي أحد من أئمة الجامع المغربَ سوى الإمام الكبير فقط؛ لأنَّه كان يقع بصلاتهم تشويشٌ كبير على المصلين."},{"id":2523,"title":"وفاة الملك الكامل صاحب مصر .","date":["العام الهجري :635","الشهر القمري : رجب","العام الميلادي :1238"],"text":"هو أبو المعالي محمد بن الملك العادل، الملقب بالملك الكامل ناصر الدين، ولد سنة 576، وكان أكبر أولاد العادل بعد مودود، وإليه أوصى العادل لعلمه بشأنه وكمال عقله، وتوفُّر معرفته، ملك مصر ثلاثينَ سنة، وكانت الطرقاتُ في زمانه آمنة، والرعايا متناصفة، لا يتجاسَرُ أحد أن يظلم أحدًا، وكانت له اليد البيضاء في رد ثغرِ دمياط إلى المسلمين بعد أن استحوذ عليه الفرنج، فرابطهم أربعَ سنين حتى استنقذه منهم، وكان يومُ أخْذِه له واسترجاعه إياه يومًا مشهودًا، مع أنه هو من سلم القدسَ مرة أخرى للفرنج بصلحٍ معهم. قال ابن خلكان: \"رأيت الكامل والأشرف، وكانا يركبان معًا ويلعبان بالكرةِ في الميدان الأخضر الكبير كلَّ يوم، ولقد كنت أرى من تأدب كل واحد منهما مع الآخر شيئًا كثيرًا، ثمَّ وقعت بينهما وحشة، وخرج الأشرفُ عن طاعة الكامل، ووافقَته الملوكُ بأسرها على الخروج على الملك الكامل، ولم يبقَ مع الملك الكامل سوى ابن أخيه الملك الناصر صاحبِ الكرك؛ فإنه توجه إلى خدمته بالديار المصرية. فتحالفوا وتحزَّبوا واتفقوا وعزموا على الخروج على الملك الكامل\" لما استراح خاطرُ الملك الكامل من جهة الفرنج تفرَّغ للأمراء الذين كانوا متحاملين عليه فنفاهم عن البلاد، وبدَّد شملهم وشَرَّدَهم، ثم دخل إلى القاهرة, وشرع في عمارة البلاد وبنى بها دار حديث ورتَّب لها وقفًا جيدًا، واستخرج الأموال من جهاتها، وكان سلطانًا عظيم القدر جميل الذكر محبًّا للعلماء متمسكًا بالسنة النبوية، حسن الاعتقاد معاشرًا لأرباب الفضائل، حازمًا في أموره، لا يضع الشيءَ إلا في موضعه من غير إسراف ولا إقتار، وكانت تبيت عنده كل ليلة جمعة جماعة من الفضلاء، ويشاركهم في مباحثاتهم، ويسألهم عن المواضع المشكلة من كل فنٍّ، وهو معهم كواحد منهم. في سنة 629 قصد آمد، وأخذها مع حصن كيفا من الملك المسعود ركن الدين مودود بن الملك الصالح, قال ابن خلكان: \"لقد رأيتُه بدمشق في سنة 633 عند رجوعه من بلاد الشرق واستنقاذه إياها من يد علاء الدين بن كيخسرو السلجوقي صاحب بلاد الروم، في خدمته يومئذ بضعةَ عشر ملكًا، منهم أخوه الملك الأشرف. ولم يزَلْ في علو شأنه وعظم سلطانه إلى أن مَرِضَ بعد أخذ دمشق ولم يركَبْ بعدها\", وقد تملك الكامل دمشق سنة 635 مدة شهرين بعد وفاة الأشرف صاحبها، ثم أخذته أمراض مختلفة، من ذلك سعال وإسهال ونزلة في حلقه، ونقرس في رجليه، فاتفق موتُه في بيت صغير من دار القصبة، وهو البيت الذي توفِّيَ فيه عمه الملك الناصر صلاح الدين، ولم يكن عند الكامل أحد عند موته من شدة هيبته، بل دخلوا فوجدوه ميتًا، وقيل: بل حدث له زكام، فدخل في ابتدائه إلى الحمام، وصبَّ على رأسه الماء الحار، فاندفعت المراد إلى معدته، فتورم وعرضت له حمى، فنهاه الأطباء عن القيء، وحذروه منه، فاتفق أنه تقيأ لوقته، في آخر نهار الأربعاء حادي عشر شهر رجب، وكانت وفاته في ليلة الخميس الثاني والعشرين من رجب من هذه السنة، ودفن بالقلعة حتى كملت تربته التي بالحائط الشمالي من الجامع، فنقل إليها ليلة الجمعة الحادي والعشرين من رمضان من هذه السنة، وكان قد عهد لولده العادل- وكان صغيرًا- بالديار المصرية، وبالبلاد الدمشقية، ولولده الصالح أيوب ببلاد الجزيرة، فأمضى الأمراء ذلك، فأما دمشق فاختلف الأمراء بها."},{"id":2524,"title":"السلطان العادل الثاني بن الكامل الأيوبي يمتلك مصر بعد وفاة أبيه .","date":["العام الهجري :635","الشهر القمري : رجب","العام الميلادي :1238"],"text":"استقر الأمر للملك العادل الثاني بن الملك الكامل بمصر ودمشق يوم الخميس في الثاني عشر من رجب، وهو السلطان السابع من بني أبوب بديار مصر، فقدمت عليه القصاد من دمشق بوفاة أبيه واستقراره من بعده، فشرع الأميرُ سيف الدين قلج في تحليف الأمراء للملك العادل في داره، وحطَّ الملك العادل المكوس، ووسَّع في العطاء وفي الأرزاق على كلِّ أحدٍ، وفي رابع شعبان خطب له بمصر، وأعلن بموت الملك الكامل، وفي رابع عشر شعبان ضُرِبَت السكة باسمه، وفي ثامن عشر رمضان: نقش الدينار والدرهم باسمه، وفي عشريه قرئ توقيعُه على المنبر بإبطالِ جميع المكوس، وفي سابع عشرين شوال وصل محيي الدين أبو محمد يوسف بن الجوزي، رسولًا من بغداد، بتعزية الملك العادل، وهنَّأه بالملك من قبل الخليفة، وكان العادِلُ قد بعث إلى دمشق بالخِلَع والسنجق، فركب الجواد بالخِلَع في تاسع عشر رمضان وأنفق الملك العادل على العساكر."},{"id":2525,"title":"نهاية الدولة العيونية في البحرين .","date":["العام الهجري :636","العام الميلادي :1238"],"text":"استمَرَّت سيطرة عبد القيس على إقليم البحرين وبينونة الدنيا ومزيرعة إلى وقت نهاية الدولة العيونيَّةِ العبقسية، وقد استمَرَّ حكم الدولة العيونية من سنة 470 (1077م) إلى سنة 636 (1238م) ثم أخذ الضَّعفُ ينخر في أركان هذه الدولة فتوالى سقوط مناطقِها واحدةً تلو الأخرى على يد العصفوريين، وقُتِلَ آخِرُ أمرائهم محمد بن محمد بن ماجد العيوني، بعد أن حكموا بلاد البحرين قرابة 167سنة."},{"id":2526,"title":"قيام إمبراطورية مالي الإسلامية في أفريقيا الغربية .","date":["العام الهجري :636","العام الميلادي :1238"],"text":"عندما قوي أمر الصوصو الذين قضوا على إمبراطورية غانا ضَمُّوا إليهم أكثَرَ الممالك التي كانت تتبع لغانا، ومنها مملكة كانغابا (مالي) وقُتِلَ ملك الصوصو سومانغارو ملكهم وأولاده الأحد عشر باستثناء الصغير منهم، وهو سندياتا إذ عرف فيما بعد بماري جاطه الذي تمكن بعد أن كبر من إحراز النصر على الصوصو، وقتل فيها إمبراطور الصوصو عام 633, فانتهى أمر الصوصو وسار ماري جاطه إلى عاصمة إمبراطورية غانا ودمر ما كان بقي منها، لكنَّه ترك المسلمين، ثم شكَّلَ ماري هذا مملكةً واسعة حكَمَتْها أسرة كيتا وجعل عاصمتَه سانكاراني، وسميت نياتي واشتهرت باسم مالي، وأما أصل أسرة كيتا فيعود إلى موسى ديجيو الذي يلقب بكيتا، وهو أول من دخل الإسلام من ملوك دولة كانغابا أو ماندينغ. ثم تولى أمر أسرة كيتا أو مملكة مالي بعد ماري جاطه ابنه منسي علي، الذي عُرِفَ بالصلاح وأدى فريضة الحجِّ سنة 658."},{"id":2527,"title":"سقوط مدينة بلنسية الأندلسية في يد نصارى الأسبان .","date":["العام الهجري :636","الشهر القمري : صفر","العام الميلادي :1238"],"text":"بلنسية مدينة شهيرة بالأندلس، تقع شرقيَّ مدينتي تدمير، وقرطبة، وتتَّصِلُ بزمام إقليم مدينة تدمير. وفي بلنسية تأسَّست مملكة إسلامية عام 401 (1010م) على يدِ اثنين من موالي المنصور بن عامر ووقعت بلنسية في القرون التالية تحت سيطرة حكام ملوك الطوائف. ثمَّ المرابطين، ثم الموحدين، إلى أن سقطت في أيدي الفرنجة سنة 636 (1238م) بعد سقوط قرطبة. وفي يوم الجمعة 27 صفر سنة 636 (9 أكتوبر 1238م) دخل خايمي ملك أراجون بلنسية ومعه زوجته وأكابر الأحبار والأشراف والفرسان، بعد أن قام بحصارِ مدينة بلنسية التي تعتبر كبرى قواعد شرقي الأندلس، فاستولى عليها الإفرنج الأسبان بعد هذا الحصارِ، وكان أميرُها أبو جميل زيان بن سعد بن مردنيش يرسِلُ إلى أبي زكريا يحيى الحفصي صاحبِ تونسَ وفدًا برئاسة كاتبه عبد الله بن الأبار القضاعي يستنجِدُه ويطلُبُ عَونَه، فلم تغن هذه الاستغاثة شيئًا، ويذكر أن البابا غريغوار التاسع قد أسبغ على هذا الاستيلاء صفةَ الحرب الصليبية، ورفع علم أراجون على المدينة المنكوبة، وحُوِّلت المساجد إلى كنائس، وطُمِسَت قبور المسلمين، وقضى المَلِك عدةَ أيام يقسم دور المدينة وأموالها بين رجاله وقادته ورجال الكنيسة, وهكذا سقطت بلنسية في أيدي نصارى الأسبان بعد أن حكَمَها المسلمون أكثر من 5 قرون."},{"id":2528,"title":"استيلاء الصالح نجم الدين أيوب على دمشق ومحاولته الاستيلاء على مصر .","date":["العام الهجري :636","الشهر القمري : جمادى الأولى","العام الميلادي :1239"],"text":"جهز الملك العادِلُ بن الملك الكامل جماعة من الأمراء، وعدة من العساكر بديار مصر لتأخذ دمشق، وقدَّم الملك العادل إلى الملك الجواد نائبِه على دمشق رسولًا بكتابٍ فيه أنَّه يعطيه قلعةَ الشوبك وبلادها، وثغرَ الإسكندرية، وأعمال البحيرة وقليوب، وعشر قرى من بلاد الجيزة بديار مصر، لينزِلَ عن نيابة السلطة بدمشق، ويحضُرَ إلى قلعة الجبل، ليعمَلَ برأيه في أمور الدولة، فلما وفى ذلك أوهمه نائبُه عماد الدين قلج من أنه متى دخل مصر قبض عليه الملك العادل، فامتنع من تسليم دمشق، فبَرَز الملك العادل من القاهرة يريد دمشق، آخر ذي الحجة، ونزل بلبيس، فخاف الملك الجواد، وعَلِمَ عَجْزَه عن مقاومة العادل، فبعث إلى الملك الصالح نجم الدين أيوب بن الكامل صاحب حصن كيفا وديار بكر يطلبُ منه أن يتسَلَّمَ دمشق، ويعوِّضَه عنها سنجار والرقة وعانة، فوقع ذلك من الملك الصالح أحسَنَ مَوقِعٍ، وأجابه إليه، وزاده الجديدة، وحلف له على الوفاء، ورتَّب الملك الصالح ابنَه الملك المعظَّم توران شاه على بلاد الشرق، وألزمه بحصنِ كيفا، وأقام نوابًا بآمد وديار بكر، وسَلَّم حران والرها وجميع البلاد للخوارزمية الذين في خدمته، وطلب نجدةً من الأمير بدر الدين لؤلؤ صاحب الموصل، وكان قد صالحه فبعث إليه بدر الدين نجدةً، وسار الملك الصالح من الشرق يريد دمشقَ، فقطع الملك الجواد اسم الملك العادل من الخطبة، وخطب للملك الصالحِ نجم الدين أيوب، وضرب السكَّةَ باسمه، ودخل الصالحُ إلى دمشق في مستهَلِّ جمادى الأولى، ومعه الجواد بين يديه بالناشية، وقد نَدِمَ الجواد على ما كان منه، وأراد أن يستدرِكَ الفائت فلم يقدِرْ، وبعث الصالح إليه بردِّ أموال الناس إليهم، فأبى وسار، وكان قد وصل مع الصالح أيضًا الملك المظفَّر صاحب حماة، وقد تلقَّاه الجواد، فكان دخوله يومًا مشهودًا، فاستقَرَّ في قلعة دمشق، وخرج الجوادُ إلى بلاده، فكانت مدةُ نيابته دمشق عشرة أشهر وستة عشر يومًا، فلما استقَرَّ الملك الصالح بدمشق سار المظفر إلى حماة، وقدمت الخوارزمية، فنازلوا مدينةَ حمص وهو معهم مدةً ثَّم فارقوها بغير طائلٍ، وعادوا إلى بلادهم بالشَّرقِ، وفي أثناء ذلك تواترت رسلُ المظفَّر صاحب حماة إلى الملك الصالحِ يستحِثُّه على قصد حمص، وكتب الأمر من مصر يستدعيه إلى القاهرة، وتعِدُه بالقيام بتصَرُّفه، فبرز الملك الصالح من دمشق إلى البثنية، وكانت الخوارزميَّة، وصاحب حماة، على حصار حمص، فأرسل المجاهدُ أسد الدين شيركوه مالًا كثيرًا فرَّقه في الخوارزمية، فرحلوا عنه إلى الشرق، ورحل صاحِبُ حماة إلى حماة، وعاد الملك الصالحُ إلى دمشق طالبًا مصر، وخرج منها إلى الخربة وعيَّدَ بها عيدَ الفطر، وعسكَرَ تحت ثنية العقاب، وقد تحيَّرَ فلا يدري أيذهب إلى حمص أم إلى مصر، وما زال بمعسكره إلى أول شهر رمضان، فعاد إلى دمشق وتقَدَّمَ إلى الأمير حسام الدين أبي علي بن محمد بن أبي علي الهذباني، أن يرحَلَ بطائفة من العسكر إلى جينين، فرحل، ولم يزل هو تحت عقبة الكرسي، على بحيرة طبرية، إلى آخرِ رمضان، فلما وردت الأخبارُ بحركة الملك الصالح إلى القاهرة، خرج من أمراء مصرَ سبعة عشر أميرًا في عِدَّة كبيرة من أتباعهم وأجنادهم، وخلقٌ مِن مُقَدَّمي الحلقة والمماليك السلطانية، وساروا يريدون الملك الصالح بدمشق، واضطربت مصر اضطرابًا زائدًا، وخرج فخر القضاة بن بصاقة في الرِّسالة إلى الملك الصالح من الكرك عن الناصر داود بأنَّه في نصرة الملك الصالح ومعاونته، ويسألُه دمشق وجميعَ ما كان لأبيه، فلم تقَعْ موافقة على ذلك، فسار الناصر إلى الملك العادل، ونزل بدار الوزارة من القاهرة، ليعينَه على محاربة أخيه الملك الصالح، فقَدِمَ في ذي الحجة الصاحبُ محيي الدين بن الجوزي برسالة الخليفةِ إلى الملك الصالح، ليصالِح أخاه الملك العادل فأجلَّ الملك الصالح قدومه إجلالًا كثيرًا، ومع ذلك فإنَّ كُتُب الأمراء وغيرهم تَرِدُ في كل قليل على الملك الصالح من مصر، تعِدُه بالقيام معه، وأنَّ البلاد في يده، لاتفاق الكلمةِ على سلطنتِه."},{"id":2529,"title":"استيلاء الفرنج على مدينة قرطبة .","date":["العام الهجري :636","الشهر القمري : شوال","العام الميلادي :1239"],"text":"استولى أعداءُ الله من الفرنج على مدينة قرطبة قاعدة بلاد الأندلسِ ودارِ مملكتها، وذلك يوم الأحد الثالث والعشرين من شوال."},{"id":2530,"title":"وفاة السلطان المجاهد أسد الدين شيركوه الصغير صاحب حمص .","date":["العام الهجري :637","العام الميلادي :1239"],"text":"هو السلطان الملك المجاهد أسد الدين شيركوه الصغير، أبو الحارث بن ناصر الدين محمد بن أسد الدين شيركوه بن شادي، صاحبُ حمص، ولَّاه إياها الملك الناصر صلاح الدين بعد موت أبيه سنة إحدى وثمانين وخمسمائة، فمكث فيها سبعًا وخمسين سنة، ولد بمصر سنة 569 وكان من أحسن الملوك سيرةً، طَهَّر بلاده من الخمور والمكوس والمنكرات، وهي في غايةِ الأمن والعدل، لا يتجاسر أحدٌ من الفرنج ولا العرب يدخلُ بلاده إلا أهانه غايةَ الإهانة، وكانت ملوكُ بني أيوب يتَّقونه؛ لأنه يرى أنه أحق بالأمرِ منهم، لأنَّ جده أسد الدين شيركوه هو الذي فتح مصرَ، وأوَّلُ من ملك منهم، شَهِدَ غزو الفرنج لدمياط، ورابَطَ عليها, وسكن المنصورةَ إلى انقضاء الغزاة، واستنقاذ دمياط, وكان شهمًا مهيبًا بطلًا شُجاعا، مِقدامًا معروفًا بالشجاعة. استخدم الحَمَام في نواحي بلاده لنقل الأخبار, وكانت بلادُه طاهرة من الخمر والمكوس, ومنعَ النساءَ من الخروج من أبواب حمص مُدَّة إمرته عليها خوفًا أن يأخذ أهل حمص أهاليهم وينزحون عنها لجَوِره, وله أخبارٌ في الظلم والتعذيب والاعتقال. إلَّا أنه كان لا يشرب الخمر أبدًا، ويلازم الصلوات في أوقاتها، ولا يُقبلُ على اللهو، بل همَّتُه في مصالح ملكه, وكان ذا رأي ودهاء, وله هيئة جميلة وجلالة وصورة مليحة، وكان الملوك يراعونه ويخافونه، وكان الملك الكاملُ قد استوحش منه واتَّهَمه بأنه أوقع بينه وبين الأشرف، فلما مات الأشرفُ وتمَلَّك الكامل دمشق، طلب من شيركوه مالًا عظيمًا، فبعث إليه نساءه يشفعن فيه، فما أجاب وقال: لا بدَّ من المال، فأيس وهيَّأَ الأموال، ولم يبقَ إلَّا تسييرها فأتته بطاقةٌ بموت الكامل، فجاء وجلس عند قبرِ الكامل وتصَرَّف في أمواله وخَيلِه، كانت وفاته بحمص، وعُمِلَ عزاؤه بجامع دمشق، واستخلف بعده ابنُه المنصور ناصِرُ الدين إبراهيم."},{"id":2531,"title":"حملة صليبية فرنسية فاشلة على بلاد الشام .","date":["العام الهجري :637","العام الميلادي :1239"],"text":"دعا البابا غريغوار التاسع لحملة صليبية جديدة، فاستجاب لها عددٌ من الأمراء الفرنسيين، منهم أمير شامباني، وملك نافار، وأمير برغوني، وغيرهم، فتجَهَّزَ هؤلاء الأمراءُ الفرنسيون بحملةٍ فاتَّجهوا إلى بلادِ الشَّامِ بحرًا ونزلوا في عكا، ثم اعتَرَضت في غزة قافلةٌ تجارية متجهة إلى دمشق فنَهَبوا ما فيها، فسَيَّرَ الملك العادل صاحِبُ مصر جيشًا لقتالهم، فأفنوا كثيرًا من رجالها واضطرَّ من بقي منهم إلى الانسحاب إلى عكَّا عائدين إلى الغرب."},{"id":2532,"title":"المغول يغزون أوروبا .","date":["العام الهجري :637","العام الميلادي :1239"],"text":"وجَّهَ أوجتاي بن جنكيزخان ثلاثةَ جيوش أحدها إلى كوريا، والثاني إلى إمبراطورية سونغ في جنوب الصين الذين ساعدوه بالأمس ضد إمبراطورية كين في شمال الصين، والجيش الثالث إلى شرقي أوروبا وقائد هذا الجيش الأخير هو باتو بن أخيه جوجي، فدخل باتو بلاد البلغار، وهي قازان، ثم دخل موسكو واتجهوا إلى كييف أكبر مدنِ روسيا آنذاك، فأبادوها وقتلوا أهلَها وقطعوا آذانَهم وجمعوها في أكياسٍ، ثم انقسم جيشُ باتو إلى قسمين: قسمٍ بقي في إمرته وسار ناحية بلاد المجر، والآخر بإمرة بيدار واتجه نحو بولندا، فانتصر الأوَّلُ على المجر، وذُبِحَ الجيش المجري كاملًا، أمَّا الجيش الثاني فأحرق ما استطاع عليه من مدن بولندا."},{"id":2533,"title":"البابا يدعو إلى حرب صليبية ضد المغول .","date":["العام الهجري :637","العام الميلادي :1239"],"text":"بعد أن رأى الصليبيون أعمال المغول التتار في البلاد التي يسيرون إليها ويحتلُّونها وشناعَتَهم ووحشيَّتَهم وما فعلوه في روسيا وبولندا من غزوهم أوروبا. قام البابا غريغور التاسع بالدعوة إلى حرب صليبية، ولكن هذه المرة ضد المغول، وليس ضد المسلمين، علمًا بأنَّه قد قيل إن الصليبيين هم من حرَّضوا المغول على التحرك إلى بلاد المسلمين خوارزم وأذربيجان وغيرها؛ وذلك حتى يجعلوا المسلمين بين فكَّي كماشة: من الشرق المغول، ومن الغرب الصليبيين، ولكن لما رأوا استفحالَ أمر المغول واختلاطهم بالمسلمين، أصبحوا يخافون أن يُسلِموا، وبالتالي يصبح مصيرهم مصير التتر الذين أسلموا وأصبحوا قوَّةً للإسلام بعد أن كانوا قوةً عليها."},{"id":2534,"title":"استيلاء الصالح إسماعيل والمجاهد أسد الدين على دمشق .","date":["العام الهجري :637","الشهر القمري : صفر","العام الميلادي :1239"],"text":"استهلت هذه السَّنةُ وسلطانُ دمشق نجم الدين الصالح أيوب بن الكامل مخيِّم عند نابلس، يستدعي عمَّه الصالح إسماعيل؛ ليسيرَ إلى الديارِ المصريةِ؛ لأخْذِها من صاحبها العادل بن الكامل، فلما كان يومُ الثلاثاء السابع والعشرين من صفر هجم الملك الصالح إسماعيل وفي صحبته المجاهِدُ أسد الدين شيركوه صاحب حمص على دمشقَ، فدخلاها بغتةً من باب الفراديس، فنزل الصالح إسماعيل بدارِه من درب الشعارين، ونزل صاحِبُ حمص بداره، وجاء نجم الدين بن سلامة فهنأ الصالحَ إسماعيل، وأصبحوا فحاصروا القلعةَ وبها المغيث عمر بن الصالح نجم الدين، ونَقَبوا القلعة من ناحية باب الفرج، وهتَكوا حُرمَتَها ودخلوها وتسَلَّموها واعتقلوا المغيثَ في برج هنالك، ولما وصل الخبَرُ بما وقع إلى الصالح أيوب تفَرَّق عنه أصحابه والأمراء خوفًا على أهاليهم من الصالحِ إسماعيلَ، وبَقِيَ الصالح أيوب وحده بمماليكِه."},{"id":2535,"title":"وقعة بين الفرنج والعسكر المصري .","date":["العام الهجري :637","الشهر القمري : ربيع الأول","العام الميلادي :1239"],"text":"في يوم الأحد رابع عشر ربيع الأول وقع بين الفرنج وبين العسكر المصري المقيم بالساحلِ حَربٌ، انحسَرَ فيها الفرنج، وأُخِذَ من الفرنج ملوكُهم وأكنادُهم، وثمانون فارسًا، ومائتان وخمسون راجلًا وصَلوا إلى القاهرة، وقُتِلَ منهم ألف وثمانمائة، ولم يُقتَل من المسلمين غيرُ عشرة رجال."},{"id":2536,"title":"انتهاء مدة صلح يافا مع الصليبيين .","date":["العام الهجري :637","الشهر القمري : ربيع الأول","العام الميلادي :1239"],"text":"انتهت مدةُ الصلح المعقود بين الملك الكامل بن الملك العادل وبين فردريك الثاني ملك الألمان على ما ذكرناه سنة 624، وكانت المدة عشر سنوات، وكان بموجبه قد تسلم الصليبيون القدس، وبه نَصَّب فردريك نفسه ملكًا على القُدسِ."},{"id":2537,"title":"تولي الشيخ عز الدين بن عبدالسلام الخطابة بجامع دمشق .","date":["العام الهجري :637","الشهر القمري : ربيع الآخر","العام الميلادي :1239"],"text":"في يوم الأربعاءِ ثالث ربيع الآخر وليَ الشيخ عز الدين عبد العزيز بن عبد السلام بن أبي القاسم السلمي خَطابةَ جامِعِ دمشقِ."},{"id":2538,"title":"استرداد القدس من الصليبيين .","date":["العام الهجري :637","الشهر القمري : جمادى الأولى","العام الميلادي :1239"],"text":"في أثناءِ الاختلاف بين الملوك التركمان استغل الفرنجُ الوضع فعَمَروا في القُدسِ قلعةً، وجعلوا برجَ داود أحدَ أبراجها، وكان قد تُرِكَ لَمَّا خرب الملك المعظم أسوارَ القُدس، فلما بلغ الناصرَ داود بن الملك المعظَّم صاحب الكرك والأردن عمارةُ هذه القلعة، سار إلى القدسِ ورمى عليها بالمجانيقِ حتى أخَذَها، بعد واحد وعشرين يومًا في يوم تاسع جمادى الأولى عَنوةً بمن معه من عسكر مصر، وتأخَّر أخْذُ برج داود إلى خامس عشر فأُخِذَ من الفرنج صلحًا على أنفُسِهم دون أموالهم، وعَمَر الناصِرُ برج داود واستولى على القُدسِ، وأخرج منه الفرنجَ، فساروا إلى بلادِهم."},{"id":2539,"title":"خلع الملك العادل صاحب مصر وتعيين الملك الصالح نجم الدين .","date":["العام الهجري :637","الشهر القمري : رمضان","العام الميلادي :1240"],"text":"بعد استيلاء الصالح إسماعيل والمجاهد أسد الدين شيركوه على دمشقَ ولَمَّا وصل الخبر إلى الصالح نجم الدين وهو مقيمٌ في نابلس يتجهَّزُ للمسير إلى مصر، افتَرَق عنه عسكرُه وبقي وحيدًا، فاستغل الفرصةَ الملك الناصر داودُ بن الملك المعظَّم صاحب الكرك والأردن فأرسل إليه من أخَذَه من نابلس مهانًا على بغلةٍ بلا مهماز ولا مُقَدمة، فاعتقله عنده سبعةَ أشهر، فأرسل العادِلُ من مصر إلى الناصر ِيطلب منه أخاه الصالحَ أيوبَ، ويعطيه مائة ألف دينار، فما أجابه إلى ذلك، بل عكس ما طلب منه بإخراجِ الصالحِ مِن سجنه والإفراج عنه وإطلاقه من الحبسِ، فعند ذلك حاربت الملوك من دمشق ومصر وغيرهما الناصرَ داود، وبرز العادِلُ من الديار المصرية إلى بلبيس قاصدًا قتال الناصر داود، فاضطرب الجيشُ عليه واختلفت الأمراءُ، وقَيَّدوا العادل واعتقلوه في خركاه- بيت من الخشب- وخُلِعَ العادل في يوم الجمعة تاسع شوال، فكانت مُدَّة ملكه سنتين وشهرين وثمانية عشر يومًا، وأرسلوا إلى الصالحِ أيوب يستدعونه إليهم، فامتنع الناصرُ داود من إرساله حتى اشتَرَط عليه أن يأخذ له دمشق وحمص وحلب وبلاد الجزيرة وبلاد ديار بكر ونصف مملكة مصر، ونصف ما في الخزائن من الحواصل والأموال والجواهر، فأجاب الصالحُ أيوب إلى ذلك مُكرهًا، وهو خائِفٌ أن تكونَ هذه الكائنة من المصريين مكيدةٌ، فلمَّا وصل الصالح أيوب إلى المصريين مَلَّكوه عليهم ودخل الديار المصرية سالِمًا مُؤيَّدًا منصورًا، مظفرا محبورًا مسرورًا، فأرسل إلى الناصر داود عشرين ألف دينار فرَدَّها عليه ولم يقبَلْها منه، واستقَرَّ مُلكه بمصر."},{"id":2540,"title":"ولاية الملك الصالح نجم الدين أيوب على مصر .","date":["العام الهجري :637","الشهر القمري : ذي الحجة","العام الميلادي :1240"],"text":"بعد وفاة الملك الكامل محمد سنة 635 (1238م) تعرضت الدولة الأيوبية في مصر والشام لخطر الانقسام والفوضى، فاستولى الصالح نجم الدين أيوب على دمشق سنة 636 (1239م)، وكان هذا إيذانًا بدخوله في صراعٍ مع أخيه الملك العادل الصغير بن الكامل الذي خلَف أباه على حكم مصر والشام، واستعان كلٌّ منهما بأنصارٍ مِن البيت الأيوبي للوقوفِ في وجه الآخر، وفي غمرة الصراع قفَزَ عمُّهما الصالح إسماعيل على دمشق واستولى عليها، وطرد الصالحَ أيوب منها، والذي وقع في قبضة الناصرِ داود بن الملك المعظم صاحب الأردن والكرك، ثمَّ لم يلبث أن أفرَجَ عنه، واتفقا معًا على القيام بحملةٍ عسكرية على مصر والاستيلاء عليها من قبضة العادِلِ الصغير, وقد كانت الظروفُ مُهَيَّأة تمامًا لنجاح حملة الصالحِ أيوب؛ فكبار أمراء العادلِ الصغير مستاؤون منه لاحتجابه عنهم، وانشغاله باللهو واللعب عن تدبير شئون الدولة، فقبضوا على سلطانهم اللاهي واستدعوا أخاه الصالح نجم الدين أيوب لتولي مقاليد البلاد الذي دخل القاهرة في 25 ذي الحجة 637 (17 يوليو 1238م) وجلس على عرشها، واستأثر بها دون الناصر داود."},{"id":2541,"title":"ثورة المسلمين على الملك الصالح إسماعيل في دمشق .","date":["العام الهجري :638","العام الميلادي :1240"],"text":"بعد أن بدأ الخلاف في البيت الأيوبي وخاف كل أميرٍ من الآخر، لم يجدوا سبيلًا إلا الاستنجاد بالكُفَّار على إخوانهم، وتعهدوا لهم بعهودٍ ومواثيق وتسليمِ للبلاد, فسَلَّم الملك الصالح إسماعيل صاحب دمشق حصن شقيف أرنون لصاحب صيدا الفرنجي وسلَّمه غيرها من المدن، فاشتد الإنكارُ عليه من الناس عامَّةً؛ بسبب ذلك، حتى إن الشيخ عز الدين بن عبد السلام خطيب البلد، والشيخ أبا عمرو بن الحاجب شيخ المالكية ندَّدا به وقطعا الخطبة له، فاعتقلهما مدةً ثم أطلقهما وألزمهما منازِلَهما، وولى الخطابةَ وتدريس الغزالية لعماد الدين داود بن عمر بن يوسف المقدسي خطيب بيت الأبار، ثم خرج الشيخان من دمشق، فقصد أبو عمرو الناصر داود بن الملك المعظَّم بالكرك، ودخل الشيخ عز الدين الديارَ المصريَّة."},{"id":2542,"title":"انتقال الشيخ عز الدين بن عبدالسلام إلى مصر  .","date":["العام الهجري :638","العام الميلادي :1240"],"text":"لَمَّا أطلق الملك الصالح إسماعيل صاحب دمشق سراح الشيخ عز الدين بن عبد السلام من سجنه بسبب إنكاره عليه تسليمَه أراضي المسلمين للصليبيين، ترك الشام وانتقل إلى الديار المصريَّة، فتلقاه صاحبها الملك الصالح نجم الدين أيوب بالاحترامِ والإكرامِ، وولَّاه خطابة القاهرة وقضاءَ مصر، واشتغل عليها أهلُها، فكان ممن أخذ عنه الشيخ تقي الدين بن دقيق العيد- رحمهما الله تعالى."},{"id":2543,"title":"النزاع بين الملوك الأيوبيين واستنجادهم بالصليبيين .","date":["العام الهجري :638","العام الميلادي :1240"],"text":"استولى الصالح نجم الدين أيوب على مصر، ثم استولى عمه الصالح إسماعيل على دمشق، ثم إن الناصر داود بن الملك المعظَّم الذي كان أطلق الصالح نجم الدين أيوب مِن أسرِه إلى مصر فمَلَكها على أن يعطيه بعضَ البلاد فخلفه، فانحاز إلى الصالح إسماعيل ومعهم كذلك صاحب حمص، كل هذه الأمور من النزاعات بين أمراء البيت الأيوبي أدت إلى تولد شرارة الحرب بينهم، فخاف الصالح عماد الدين صاحب دمشق من الملك الصالح نجم الدين صاحب مصر، فكاتب الفرنج، واتفق معهم على معاضدته ومساعدتِه، ومحاربة صاحب مصر، وأعطاهم قلعةَ صفد وبلادها، وقلعة الشقيف وبلادها، ومناصفة صيدا وطبرية وأعمالها، وجبلَ عاملة وسائر بلاد الساحل، وعزم الصالح عماد الدين على قصد مصر لِمَا بلغه من القبض على المماليك الأشرفية والخُدَّام ومُقَدَّمي الحلقة وبعض الأمراء، وأن من بقي من أمراء مصر خائف على نفسه من السلطان، فتجهَّز وبعث إلى المنصور صاحب حمص، وإلى الحلبيين وإلى الفرنج يطلب منهم النجدات، وأذن الصالح إسماعيل للفرنج في دخول دمشق وشراء السلاحِ، فأكثروا من ابتياع الأسلحة وآلات الحرب من أهل دمشق، فأنكر المسلمون ذلك، ثمَّ برز الصالح إسماعيل من دمشق، ومعه عساكِرُ حمص وحلب وغيرها، وسار حتى نزل بنهر العوجاء، فبلغه أن الناصر داود قد خيم على البلقاء، فسار إليه، وأوقع به، فانكسر الناصرُ داود، وانهزم إلى الكرك وأخذ الصالحُ أثقاله، وأسَرَ جماعة من أصحابه، وعاد إلى العوجاء وقد قَوِيَ ساعده واشتدت شوكتُه، فبعث يطلب نجدات الفرنج، على أنَّه يعطيهم جميع ما فتحه السلطان صلاح الدين يوسفُ، ورحل ونزل تل العجول فأقام أيامًا، ولم يستطع عبور مصر، فعاد إلى دمشق؛ وذلك أن الملك الصالح نجم الدين لما بلغه حركة الصالح إسماعيل من دمشق ومعه الفرنج، جرَّد العساكِرَ إلى لقائه، فألقاهم، وعندما تقابل العسكران ساقت عساكر الشام إلى عساكر مصر طائعةً، ومالوا جميعًا على الفرنج، فهزموهم وأسَرُوا منهم خلقًا لا يُحصَون، وبهؤلاء الأسرى عَمَرَ السلطان الملك الصالح نجم الدين قلعةَ الروضة، والمدارس الصالحية بالقاهرة، ثم تمَّ الصلح مع الفرنج، وأطلق الملك الصالح نجم الدين الأسرى بمصر من الجنود والفرسان والرجَّالة."},{"id":2544,"title":"وصول رسالة من ملك المغول إلى المسلمين .","date":["العام الهجري :638","العام الميلادي :1240"],"text":"وصل رسول التتار من ملكهم خاقان إلى الملك المظفَّر شهاب الدين غازي بن العادل، صاحب ميافارقين، ومعه كتاب إليه وإلى ملوك الإسلام، عنوانه: من نائب رب السماء، سامح وجه الأرض، ملك الشرق والغرب، قاقان، فقال الرسول لشهاب الدين صاحب مياقارفين: قد جعلك قاقان سلاحَ داره، وأمرك أن تخربَ أسوار بلدِك، فقال له شهاب الدين: أنا من جملةِ الملوك، وبلادي حقيرةٌ بالنسبة إلى الروم والشام ومصر، فتوجَّهْ إليهم، وما فعلوه فعَلْتُه، وكان يريد مَلِكُ المغول من كل أمراء المسلمين أن يُخرِبوا أسوار كل المدن الإسلامية ويدخلوا في طاعتِه."},{"id":2545,"title":"الحملة الصليبية الإنجليزية .","date":["العام الهجري :638","العام الميلادي :1240"],"text":"هذه الحملة الصليبية كانت مكونة من المتطوعة الإنكليز بقيادة ريتشارد كورنفيل أخو هنري الثالث ملك إنكلترا، وقد وصلت هذه الحملة إلى عكا، وقامت بتحصين عسقلان، فاعترف لها الملك الصالح نجم الدين أيوب بحق الصليبيين في ملكيَّة إقليم الجليل فضلًا عن بيت المقدس وعسقلان ولكن ريتشارد اكتفى بما استولى عليه، ثم إنه أبحر عائدًا إلى بلاده."},{"id":2546,"title":"ظهور متنبئ في بلاد الروم .","date":["العام الهجري :638","العام الميلادي :1240"],"text":"ظهر في بلاد سلاجقة الروم متنبئ يدعى بابا إسحاق تركماني الأصل ادعى أنه نبي، فكان يقول للناس: قولوا لا إله إلا الله بابا ولي الله، ثم إنه انخدع به أناس كثيرون فصار له أتباع وقوي أمره فأرسل إليه السلطان غياث الدين كيخسرو سلطان سلاجقة الروم جيشًا فاقتتلوا، فكان فيها قتل المتنبئ وقتل أربعة آلاف رجل."},{"id":2547,"title":"وفاة السلطانة رضية الدين إحدى سلاطين دولة المماليك بالهند .","date":["العام الهجري :638","الشهر القمري : ربيع الأول","العام الميلادي :1240"],"text":"هي رضية الدين بنت السلطان شمس الدين ألتمش المؤسس الحقيقي لدولة المماليك بالهند، وقد اشتهر ألتمش بالعدل وتحقيق الأمن في دولته. وكان ألتمش يحب ابنته ويقدمها على إخوانها الذكور لما يتوسم فيها من النجابة والهمة العالية, كما أنها كانت غاية في الحسن والجمال وعذوبة المنطق؛ لذا كان يسند إليها بعض المهام، حتى إنه فكَّر في أن يجعلها وليَّة للعهد دون إخوانها الذكور الذين انشغلوا باللهو والملذات، فلما مات ألتمش خلفه ابنه ركن الدين فيروز، غير أنه كان منشغلًا عن مسئولية الحكم وتبعاته باللهو واللعب، تاركًا تصريف أمور دولته إلى أمِّه التي استبدَّت بالأمر وهو ما جعل الأحوال تزداد سوءًا، وتشتعل المعارضة ضده، وانتهت الأزمة بأن بايع كثير من الأمراء رضية الدين بنت ألتمش، وأجلسوها على عرش السلطنة. وقد تحقق ما كان يراه أبوها ولا يراه سواه ممن كانوا يعترضون عليه إيثاره لها. جلست رضية الدين على عرش سلطنة دلهي نحو أربع سنوات 634-637 (1236-1369م) بذلت ما في وسعها من طاقة لتنهض بالبلاد التي خوت خزائنها من المال لإسراف أخيها، وسارت على خطا أبيها في سياسته الحكيمة العادلة في بداية الأمر، لكنها اصطدمت بالعلماء وكبار أمراء الملوك الذين يشكلون جماعة الأربعين، ويستأثرون بالسلطة والنفوذ، وحاولت الملكة جاهدة أن تسوسهم، وتحتال على تفريق كلمتهم، وتعقُّب المتمردين والثائرين عليها، وكانت تظهر بمظهر الرجال، وتجلس على العرش والعباءة عليها، والقلنسوة على رأسها وتقود جيشها وهي تمتطي ظهر فيلِها. ولما استقرت أحوال مملكتها انصرفت إلى تنظيم شؤونها، فعينت وزيرًا جديدًا للبلاد، وفوَّضت أمر الجيش إلى واحد من أكفأ قادتها هو سيف الدين أيبك، ونجحت جيوشها في مهاجمة قلعة رنتهبور وإنقاذ المسلمين المحاصرين بها، وكان الهنود يحاصرون القلعة بعد وفاة أبيها السلطان التمش. غير أن هذه السياسة لم تلق ترحيبًا من مماليك سلطنتها الذين أنِفوا أن تحكمهم امرأة، وزاد من بغضهم لهذا الأمر أن السلطانة رضية أخذت تتمرد على قيم الدين الإسلامي وحاربت الناصحين لها خاصة من العلماء. كما قرَّبت إليها رجلًا حبشيًّا مملوكا يُدعى جمال الدين ياقوت، كان يشغل منصب قائد الفرسان، ولم تستطع السلطانة أن تُسكت حركات التمرد التي تقوم ضدها، كما كانت تفعل في كل مرة، فاجتمع عليها المماليك وأشعلوا الثورة ضدها، وحاولت أن تقمعها بكل شجاعة، لكنها هُزمت، وانتهى الأمر بقتلها في 25 ربيع الأول 637 (25 أكتوبر 1239م) وتولِّي أخيها السلطان معز الدين عرش البلاد."},{"id":2548,"title":"وفاة الصوفي الملحد محي الدين ابن عربي .","date":["العام الهجري :638","الشهر القمري : ربيع الآخر","العام الميلادي :1240"],"text":"هو محمد بن علي بن محمد بن عربي أبو عبد الله الطائي الأندلسي، ولد في مرسية بالأندلس سنة 560 ثم انتقل إلى إشبيلية، ودرس القرآن والفقه والحديث، ومال إلى المذهب الظاهري، ثم رحل إلى الحجاز وأقام بمكة مدة سنتين، ثم رحل مع الحجاج الأتراك إلى قونية، ثم قصد بغداد، ثم استقر في دمشق، وله مصنفاتٌ كثيرة جدًّا، أشهرها كتابه المسمى بـ \"الفتوحات المكية وفصوص الحكم\" وفيها أشياء كثيرة ظاهرها كفر صريح، وله كتاب \"العبادلة وديوان شعر\"، وله مصنفات أخر كثيرة جدًّا، كان يقول بوحدة الوجود على مذهب الحلاج الملحد، وهو أن اللاهوت أي الله قد حل وامتزج بالناسوت أي الناس، كما تمزج الخمر بالماء فلا يتميز واحد عن الآخر، وله كلمات ظاهرها الكفر الصريح، والصوفية ما زال دأبهم تأويل هذه العبارات بكل وجه بتعسف وإسفاف. رد عليه كثير من العلماء وبينوا انحرافه وزندقتَه، ونقلوا عنه أفعالًا تدل على تركه للشريعة كترك الصلاة، وزعمه أنه يصلِّيها حاضرًا في مكة وهو ساكن في دمشق، وغير ذلك مما تطفحُ به كتبه وشِعرُه من الكفر الصريح، توفي في دمشق ودفن في سفح قاسيون في دمشق بمسجد معروف باسمه، وفيه قبره وهو يزار ويرتكب عنده من الشركيات ما الله به عليم. قال أبو شامة: \"له تصانيفُ كثيرة وعليه التصنيف سهل، وله شعر حسن وكلام طويل على طريق التصوف، وكانت له جنازة حسنة، ودُفِن بمقبرة القاضي محيي الدين بن الزكي بقاسيون، وكانت جنازته في الثاني والعشرين من ربيع الآخر\"، وقال ابن السبط: \"كان يقول إنه يحفظ الاسم الأعظم ويقول إنه يعرف الكيمياء بطريق المنازلة لا بطريق الكسب \"."},{"id":2549,"title":"إغارة الخوارزمية على حلب .","date":["العام الهجري :638","الشهر القمري : ذي الحجة","العام الميلادي :1241"],"text":"أغار الخوارزمية على بلاد قلعة جعبر وبالس ونهبوها، وقتلوا كثيرًا من الناس، ففرَّ من بقي إلى حلب ومنبج، واستولى بدر الدين لؤلؤ صاحب الموصل على سنجار، وأخرج منها الملك الجواد يونس بن مودود بن العادل بن نجم الدين أيوب، فسار الجواد إلى الشام، حتى صار في يد الناصر داود بن الملك المعظم، فقبض عليه بغزة يوم الأحد ثامن عشر ذي الحجة، وبعث به إلى الكرك، وانضمَّت الخوارزمية على صاحب الموصل، فصاروا نحو الاثني عشر ألفًا، وقصدوا حلب، فخرج إليهم من حلب، فانكسر وقتل أكثره، وغَنِمَ الخوارزمية ما معهم، فامتنع الناسُ بمدينة حلب، وانتهبت أعمال حلب، وفعل فيها كل قبيح من السبي والقتل والتخريب، ووضعوا السيفَ في أهل منبج، وقتلوا فيها ما لا يحصى عددُه من الناس، وخَرَّبوا وارتكبوا الفواحش بالنساء في الجامع علانيةً، وقتلوا الأطفال, ولا حولا ولا قوة إلا بالله, وعادوا وقد خرب ما حول حلب، وكان الخوارزميَّةُ يظهرون للناس أنهم يفعلون ما يفعلون خدمةً لصاحب مصر، فإنَّ أهل حلب وحمص ودمشق كانوا حربًا على الصالحِ صاحِبِ مصر، فسير المنصور إبراهيم بن الملك المجاهد صاحب حمص، عساكِرَه وعساكر حلب ودمشق، وقطع الفرات إلى سروج والرَّها، وأوقع بالخوارزمية، وكَسَرهم واستولى على ما معهم، ومضوا هاربين إلى عانة."},{"id":2550,"title":"إغارة الخوارزمية على الموصل .","date":["العام الهجري :639","العام الميلادي :1241"],"text":"سار الخوارزمية إلى الموصل، فسالمهم صاحبها بدر الدين لؤلؤ، ووافقهم المظفَّر شهاب الدين غازي بن العادل، صاحب ميافارقين، ثم ساروا إلى آمد فخرج إليهم عسكرُ حلب عليه المعظَّم فخر الدين توران شاه بن صلاح الدين، فدفعوهم عنها، ونهَبوا بلاد ميافارقين، وجرت بينهم وبين الخوارزميَّة وقائع، ثم عاد العسكرُ إلى حلب، فغار الخوارزمية على رساتيق الموصل, ثم اصطلح شهابُ الدين غازي صاحب ميافارقين معهم وآواهم إلى بلده ليكونوا من حزبِه."},{"id":2551,"title":"أبو زكريا الحفصي يوسع حكمه في إفريقية على حساب الموحدين .","date":["العام الهجري :639","العام الميلادي :1241"],"text":"قام أبو زكريا الحفصي على رأس حملةٍ ضَخمةٍ قَدَّرَها بعض المؤرخين بستين ألف مقاتل، فدخل تلمسان، وأجبر واليها يغمراسن على الدخول في طاعتِه، والخُطبةِ باسمه، كما أدخل في طاعتِه القبائِلَ العربية والبربريَّة في المناطق المحيطة. وكان من أثر ازدياد قُوَّته واتساع نفوذه أن هادنه بنو مرين في المغرب الأقصى، وأقيمت الخطبةُ باسمه في عددٍ كبيرٍ مِن بلاد الأندلس التي لم تقع في براثن الأسبانِ، واحتفظت بحرِّيَّتها واستقلالها مثل: بلنسية، وإشبيلية، وشريش، وغرناطة, وبسبب هذه البيعات التي انثالت على أبي زكريا من سائر الجهاتِ وحَدَّثَته نفسه بالتوثُّب على كرسي خلافةِ الموحِّدين بمراكش وغَصَّ بنو عبد المؤمن بمكانه وعَظُم عليهم استبدادُه ثم طَمَعُه في كرسيِّهم، وقرارة عزهم مع أنه ما كان إلا جدولًا مِن بَحرِهم وفرعًا من دوحتِهم، والأمر كله لله. وأصبحت الدولة الحفصيَّة التي قام عليها مرهوبةَ الجانب، تسعى الدول الأوروبية إلى كسب وُدِّها، خاصةً التي تربطها بها مصالحُ اقتصاديَّةٌ وسياسية، فعقد مع البندقية، وبيزة، وجنوة معاهدات صداقة وسلامة. وقد ظلَّ أبو زكريا متوفرًا على شؤون الدولة حتى توفي سنة 647."},{"id":2552,"title":"القتال بين الموحدين وبني مرين في المغرب .","date":["العام الهجري :639","العام الميلادي :1241"],"text":"سيَّرَ أبو محمد عبد الواحد الرشيد بن أبي العلاء المأمون الموحدي جيشًا لقتال بني مرين، فهزمهم واستولى على عسكرهم، فتدالت الحروب بينهم إلى أن انتهت إلى استيلاءِ بني مرين على مكناس وفاس التي كانت حاضرةَ الموحدين، كما استولوا بعد ذلك على سجلماسة ودرعة."},{"id":2553,"title":"اقتتال عسكر مصر مع عسكر الشام .","date":["العام الهجري :639","الشهر القمري : صفر","العام الميلادي :1241"],"text":"بلغ السُّلطانُ صاحِبُ مصر أنَّ الناصِرَ داود بن الملك المعظَّم صاحب الكرك قد وافق الصالحَ إسماعيل صاحب دمشق، والمنصور إبراهيم صاحب حمص، وأهل حلب، على محاربته، فسير السلطان كمال الدين بن شيخ الشيوخ على عسكر إلى الشام، فخرج إليه الناصرُ وقاتله ببلاد القدس، وأسَرَه في عدة من أصحابه، ثم أطلقهم وعادوا إلى القاهرة، وكان من خبر ذلك أنَّه في يوم الأربعاء ثاني عشر صفر، وقع عسكر الناصر داود على الأمير عز الدين أيبك صاحب صرخد، وقد نزل على الغوار، فكسره وأخذ الأثقالَ، وكان معه الأميرُ شمس الدين شرف- المعروف بالسبع مجانين- وشمس الدين أبو العلاء الكرديان، وشرف الدين بن الصارم صاحب بنين، وكان مقدَّم عسكر الناصر سيف الدين بن قلج، وجماعة من الأيوبية من عسكر مصر."},{"id":2554,"title":"وقعة بين الحلبيين وبين الخوارزمية .","date":["العام الهجري :640","العام الميلادي :1242"],"text":"كانت وقعة عظيمة بين الحلبيين وبين الخوارزمية، ومع الخوارزمية شهاب الدين غازي صاحب ميافارقين، فكسرهم الحلبيون كسرةً عظيمةً مُنكرةً، وغَنِموا من أموالهم شيئًا كثيرًا جدًّا."},{"id":2555,"title":"نهب الخوارزمية نصيبين .","date":["العام الهجري :640","العام الميلادي :1242"],"text":"نهب الخوارزمية نصيبين مرة أخرى، وهذه سابع عشر مرة تنهب نصيبين في هذه السنين، وعاد شهاب الدين غازي إلى ميافارقين، وتفَرَّقت الخوارزمية يفسدون في الأرض بصحبة مُقَدَّمهم بركات خان، وقَدِمَ على شهاب الدين غازي منشور بمدينة خلاط فتسَلَّمَها وما فيها من الحواصل."},{"id":2556,"title":"استيلاء الحفصيين على مدن جزائرية .","date":["العام الهجري :640","العام الميلادي :1242"],"text":"قام الحفصيون بهزيمة يغمراسن بن زيان زعيم دولةِ آل زيان من بني عبد الواحدِ، واستولوا على حاضرته تلمسان، ثم قاموا بالاستيلاء على مدن جزائريَّة أخرى."},{"id":2557,"title":"وفاة الخليفة العباسي المستنصر بالله .","date":["العام الهجري :640","الشهر القمري : جمادى الآخرة","العام الميلادي :1242"],"text":"هو أميرُ المؤمنين الخليفة العباسي المستنصر بالله أبو جعفر منصور بن الخليفة الظاهر بأمر الله محمد بن الخليفة الناصر لدين الله أبي العباس أحمد. واقف المستنصريَّة التي لا نظيرَ لها. ولد سنة 588, وأمه تركية، وكان جده الناصر يحبُّه ويسميه القاضي؛ لحبه للحقِّ، وعقلِه, وبويعَ عند موت والده يوم الجمعة، ثالث عشر رجب، سنة 623 البيعة الخاصة من إخوته وبني عمه وأسرته، وبايعه من الغد الكبراء والعلماء والأمراء. وكان أبيضَ أشقرَ، سمينًا ربعةً مليح الصورة، عاقلًا حازمًا سائسًا ذا رأي ودهاء ونهوض بأعباء الملك، كان جدُّه الناصر قد جمع ما يتحصل من الذهب في بركة في دار الخلافة، فكان يقفُ على حافتِها ويقول: أتُرى أعيش حتى أملأَها، وكان المستنصر يقِفُ على حافتها ويقول أترى أعيش حتى أنفِقَها كُلَّها, فكان يبني الربُطَ والخانات والقناطر في الطرقات من سائر الجهات، وقد عَمِلَ بكل محلَّة من محال بغداد دارَ ضيافة للفقراء، لا سيَّما في شهر رمضان، وكان يتقصد الجواري اللائي قد بلغن الأربعين فيُشترين له فيُعتقُهنَّ ويُجهزهنَّ ويُزوجُهنَّ، وفي كل وقت يُبرِزُ صِلاتِه ألوفًا متعددة من الذهب، تُفَرَّق في المحال ببغداد على ذوي الحاجات والأرامل والأيتام وغيرهم، تقبَّلَ الله تعالى منه وجزاه خيرًا، وقد وضع ببغداد المدرسة المستنصرية للمذاهب الأربعة، وجعل فيها دار حديث وحمامًا ودار طب، وجعل لمستحقيها من الجوامك- رواتب الموظفين- والأطعمة والحلاوات والفاكهة ما يحتاجون إليه في أوقاته، ووقف عليها أوقافًا عظيمة حتى قيل إن ثمن التبن من غلات ريعها يكفي المدرسة وأهلَها, ووقف فيها كتبًا نفيسة ليس في الدنيا لها نظير، فكانت هذه المدرسة جمالًا لبغداد وسائر البلاد, فكان المستنصرُ رحمه الله كريمًا حليمًا رئيسًا متودِّدًا إلى الناس، حازمًا عادلًا، وفي أيامه عَمَرت بغداد عمارة عظيمة. قال ابن النجار: \"نشر المستنصر بالله العدلَ، وبثَّ المعروف، وقَرَّب العلماء والصلحاء، وبنى المساجد والمدارس والربط، ودور الضيافة والمارستانات، وأجرى العطيَّات، وقمع المتمَرِّدة، وحمل الناسَ على أقوَمِ سَنَن، وعمر طرق الحاجِّ، وعمر بالحرمين دورًا للمرضى، وبعث إليها الأدوية, ثم قام بأمر الجهاد أحسن قيام، وجمع العساكر، وقمع الطغام، وبذل الأموال، وحَفِظَ الثغور، وافتتح الحصون، وأطاعه الملوك, وبيعت كتبُ العلم في أيامه بأغلى الأثمان لرغبته فيها، ولوقفها, وَخَطَه الشيب، فخضب بالحناء، ثم تركه, قلت (الذهبي): (كانت دولته جيدة التمكن، وفيه عدلٌ في الجملة، ووقع في النفوس) استجد عسكرًا كثيرًا لَمَّا علم بظهور التتار، بحيث إنه يقال: بلغ عدَّةُ عَسكَرِه مائة ألف، وكان يُخطَبُ له بالأندلس والبلاد البعيدة, وبلغ غلَّة وقف المستنصرية مرة نيفًا وسبعين ألف دينار في العام، واتفق له أنه لم يكن في أيامه معه سلطان يحكُم عليه، بل ملوك الأطراف خاضعون له، وفكرهم منشغلٌ بأمر التتار\". توفي يوم الجمعة عاشر جمادى الآخرة، وكُتِم موتُه حتى كان الدعاء له على المنابر ذلك اليوم، وكانت مدة ولايته ست عشرة سنة وعشرة أشهر وسبعة وعشرين يوما، ودُفِنَ بدار الخلافة، ثم نُقِلَ إلى الترب من الرصافة، بويع لابنه المستعصم بالله بعد صلاة الجمعة."},{"id":2558,"title":"خلافة المستعصم بالله آخر خلفاء بني العباس  .","date":["العام الهجري :640","الشهر القمري : جمادى الآخرة","العام الميلادي :1242"],"text":"تولى الخلافةَ المستعصمُ بالله وهو آخر خلفاء بني العباس ببغداد، وهو الخليفة الذي قتله التتار بأمر هلاكو بن تولي ملك التتار بن جنكيزخان، سنة 656، وآباؤه ثمانية نسقًا وَلُوا الخلافة لم يتخلَّلهم أحد، وهو التاسِعُ، ولما توفي أبوه بكرةَ الجمعة عاشر جمادى الآخرة استدعي هو من التاج يومئذ بعد الصلاة، فبويع بالخلافة، ولقب بالمستعصم بالله، وله من العمر يومئذ ثلاثون سنة وشهور، وقد أتقن في شبيبته تلاوة القرآن حفظًا وتجويدًا، وأتقن العربية والخطَّ الحسن وغير ذلك من الفضائل، وكان مشهورًا بالخير مشكورًا مقتديًا بأبيه المستنصر بالله جهده وطاقتَه، وكان القائمُ بهذه البيعة المستعصمية شرف الدين أبو الفضائل إقبال المستنصري، فبايعه أولًا بنو عمه وأهله من بني العباس، ثم أعيان الدولة من الأمراء والوزراء والقضاة والعلماء والفقهاء ومَن بعدهم من أولي الحَلِّ والعقد والعامة وغيرهم، وجاءت البيعةُ من سائر الجهات والأقطار والبلدان والأمصار، وخُطِب له في سائر البلدان."},{"id":2559,"title":"اجتياح المغول دولة سلاجقة الروم .","date":["العام الهجري :641","العام الميلادي :1243"],"text":"قدم التتار بلاد الروم، وأوقعوا بالسلطانِ غياث الدين كيخسرو بن كيقباذ بن يخسرو بن قلج أرسلان، وهزموه وملكوا بلادَ الروم وخلاط وآمد، فدخل غياثُ الدين في طاعتِهم، على مالٍ يحملُه إليهم، وملكوا أيضًا سيواس وقيسارية بالسيف وقرَّروا على صاحبهما في كل سنة أربعمائة ألف دينار ففَرَّ غياث الدين منهم إلى القسطنطينية، وقام من بعده ركنُ الدين ابنه وهو صغيرٌ إلى أن قُتِل."},{"id":2560,"title":"فشل محاولة الصلح بين الصالح صاحب دمشق والصالح صاحب مصر .","date":["العام الهجري :641","العام الميلادي :1243"],"text":"تكرَّرَت المراسلةُ بين الصالح نجم الدين أيوب صاحب مصر، وبين عَمِّه الصالح إسماعيلَ صاحبِ دمشق، وبين المنصورِ صاحِبِ حمص، على أن تكون دمشقُ وأعمالها للصالح إسماعيل، ومصر للصالح أيوب، وكلٌّ من صاحب حمص وحماة وحلب على ما هو عليه، وأن تكون الخطَّة والسكَّة في جميع هذه البلاد للملك الصالح نجم الدين أيوب، وأن يُطلِق الصالح إسماعيل الملك المغيث فتح الدين عمر بن الملك الصالح نجم الدين من الاعتقالِ، وأن يخرج الأمير حسام الدين أبو علي بن محمد بن أبي علي باشاك الهذباني، المعروف بابن أبي علي من اعتقالِه ببعلبك، وأن ينتزع الصالحُ إسماعيل الكرك من الملك الناصر داود بن الملك المعظم، فلما تقرَّرَ هذا خرج من القاهرة الخطيب أصيل الدين الإسعردي إمام السلطان في جماعةٍ، وسار إلى دمشق، فخطب للسلطانِ الملك الصالح نجم الدين أيوب بجامِعِ دمشق وبحمص، وأفرجَ عن المغيث بن السلطان، وأركبَ ثم أعيد إلى القلعة بمشورةٍ من وزير الصالح إسماعيل، حتى يتِمَّ بينهما الحلف، وأفرج عن الأميرِ حسام الدين، وكان قد ضيَّق عليه وجعله في جُبٍّ مُظلمٍ، فلما وصل حسام الدين إلى دمشق خلع عليه الصالحُ إسماعيل، وسار إلى مصر، ومعه رسولُ الصالح إسماعيل، ورسولُ صاحب حمص وهو القاضي عماد الدين بن القطب قاضي حماة، ورسول صاحب حلب، فقَدِموا على الملك الصالح نجم الدين، ولم يقَع اتفاق، فعادت الفتنةُ بين الملوك، فاتفق الناصرُ داود صاحب الكرك، مع الصالحِ إسماعيل صاحب دمشق، على محاربة الملك الصالح نجمِ الدين وعاد رسولُ حلب، وتأخَّرَ ابن القطب بالقاهرة، فبعث الناصرُ داود والصالح إسماعيل، ووافقا الفرنجَ على أنَّهم يكونون عونًا لهم على الملك الصالح نجمِ الدين، ووعداهم أن يسلما إليهم القُدسَ وسَلَّماهم طبرية وعسقلان أيضًا فعمَرَ الفرنجُ قلعتيهما وحصونهما، وتمكَّن الفرنج من الصخرة بالقدسِ، وجلسوا فوقها بالخَمرِ، وعَلَّقوا الجرس على المسجد الأقصى، فبرز الملك الصالح نجم الدين أيوب من القاهرة، ونزل بركةَ الجُبِّ وأقام عليها، وكتب إلى الخوارزمية يستدعيهم إلى ديارِ مِصرَ لمحاربة أهلِ الشام، فخرجوا من بلاد الشَّرقِ."},{"id":2561,"title":"البابا يدعو المغول لاعتناق النصرانية .","date":["العام الهجري :642","العام الميلادي :1244"],"text":"لَمَّا رأى الصليبيون قوةَ التَّتار وأنَّهم لا قِبَل لهم بهم وخافوا عليهم من أن يُسلِموا بحكم احتكاكهم بالمسلمين، أرادوا أن يَجُرُّوهم إلى النصرانيَّة، فقام البابا إينوسان الرابع بإرسال بعثة إلى خاقان ملك المغول إلى عاصمتِهم قره كروم يدعوه فيها إلى اعتناق النصرانيَّة، فاشترط الخاقان لاعتناقها دخول البابويَّة وجميع ملوك وأمراء الغرب تحت سيادتِه."},{"id":2562,"title":"حصار غرناطة .","date":["العام الهجري :642","العام الميلادي :1244"],"text":"قام ألفونسو بن فريناند ملك قشتالة بالاستيلاء على حصن أراغونة وعدة حصون أخرى وحاصر غرناطة، فقام ابن الأحمر أبو عبد الله محمد بن نصر بمهادنته بعد أن أيقَنَ أنَّه لا قِبَلَ له به وبمنازلتِه، ففَكَّ الحصار عن غرناطة بصلحٍ بينهما يقضي فيه أن يبقى ابن الأحمر حاكمًا على غرناطة، لكن باسم ملك قشتالة وتحت ظله، ويؤدي جزيةً سنوية ويُعينه على أعدائه وقت يريدُ، وأن يشهَدَ معه اجتماعَ مجلس قشتالة الكورتيس باعتباره بهذا العقد أميرًا من أمراء الملك التابعين له، ثمَّ سَلَّمه جيان وأراغونة وقلعة جابر وأبرم الصلح لمدة عشرين سنةً."},{"id":2563,"title":"الخوارزمية يستردون بيت المقدس .","date":["العام الهجري :642","الشهر القمري : صفر","العام الميلادي :1244"],"text":"نشب النزاعُ بين الصالحَينِ إسماعيلَ ونجمِ الدين أيوب مرة أخرى، ووقف الناصرُ داود بن الملك المعظَّم هذه المرة مع الصالح إسماعيل، واتفقا على الاستعانة بالصليبيين ضِدَّ إخوانهم المسلمين، ولم يجدِ الصالح أيوب قُوَّةً تَقِفُ إلى جواره غيرَ الخوارزمية الذين تَفَرَّقت بهم السبل بعد انهيار دولتِهم ومقتل سلطانهم جلال الدين خوارزم شاه، فاستجابوا لدعوته، وقَدِموا بأعدادٍ كبيرة إلى الشام، فقطعوا الفراتَ، ومُقَدَّموهم: الأمير حسام الدين بركة خان، وخان بردى، وصاروخان، وكشلوخان، وهم زيادة على عشرة آلاف مقاتل، فسارت منهم فرقة على بقاع بعلبك، وفرقة على غوطة دمشق، وهم ينهبون ويقتُلون ويَسْبُون، فانجفل الناسُ من بين أيديهم، وتحصَّنَ الصالح إسماعيل بدمشق، وضمَّ عساكره إليه، بعدما كانت قد وصلَت غزة, واتَّجه الخوارزمية إلى دمشقَ فوجدوها قويَّة التحصين فتركوها، واستولوا على طبرية ونابلس، وواصلوا سيرَهم حتى دخلوا مدينة بيت المقدس في الثالثِ من صفر واستولوا عليها دون مقاومةٍ، وبذلوا السيفَ فيمن كان به من النصارى، حتى أفنوا الرِّجالَ، وسَبَوا النساء والأولاد، وهدموا المبانيَ التي في قمامة، ونبشوا قبورَ النصارى، وأحرقوا رِمَمَهم، وكانت هذه آخرَ مرة يسترد فيها المسلمونَ بيت المقدس في عصرِ الحروب الصليبيَّة، وظَلَّت بأيدي المسلمين حتى سقطت في قبضة اليهود في عصرنا الحديثِ، وبعدَ أن استَرَدَّ الخوارزميون بيت المقدس واصلوا سيرَهم إلى غزة واجتمعوا مع الجيشِ المصري الذي أرسله الصالحُ أيوب لمحاربة قوات الشام ومن ناصرها من القواتِ الصليبيَّة، سير الخوارزمية إلى الملك الصالح نجم الدين أيوب في صفر يخبرونَه بقدومهم، فأمرهم بالإقامةِ في غزة، ووعدهم ببلادِ الشامِ، بعدما خلع على رُسُلِهم."},{"id":2564,"title":"انتصار الخوارزمية ونجم الدين أيوب على عساكر الشام والفرنج .","date":["العام الهجري :642","الشهر القمري : جمادى الأولى","العام الميلادي :1244"],"text":"جهَّزَ الملك الصالح نجمُ الدين أيوب عسكرًا من القاهرة عليه الأمير ركنُ الدين بيبرس، أحد مماليكِه الأخصَّاء الذين كانوا معه وهو محبوسٌ بالكرك، فسار إلى غزَّة، وانضم إلى الخوارزمية جماعةٌ من القميرية، كانوا قد قَدِموا معهم من الشرق، ثم خرج الأميرُ حسام الدين أبو علي بن محمد بن أبي علي الهذباني بعسكر، ليقيم على نابلس، وجهَّزَ الصالح إسماعيل عسكرًا من دمشق، عليه الملك المنصور صاحِبُ حمص، فسار المنصور جريدة إلى عكا، وأخذ الفرنجَ ليحاربوا معه عساكرَ مصر، وساروا إلى نحو غزة، وأتتهم نجدةُ الناصر داود بن الملك المعظَّم صاحب الكرك مع الظهيرِ بن سنقر الحلبي والوزيري، فالتَقَت العساكر المصرية مع الخوارزمية بظاهر غزة، وقد رفع الفرنجُ الصُّلبان على عسكر دمشق، وفوق رأسِ المنصور صاحِبِ حمص، وكان في الميمنة الفرنجُ، وفي الميسرة عسكر الكرك، وفي القلب المنصورُ صاحب حماة، فدارت بين الفريقين حربٌ شديدة، انكسر فيها الملك المنصور، وفَرَّ الوزيري، وقُبِضَ على الظهير وجُرح، وأحاط الخوارزمية بالفرنجِ، ووضعوا فيهم السيف حتى أتوا عليهم قتلًا وأسرًا، ولم يُفلِت منهم إلا من شَرَد، فكان عدة من أسر منهم ثمانمائة رجل، وقتل منهم ومن أهل الشام زيادةٌ على ثلاثين ألفًا، وحاز الخوارزميَّة من الأموال ما يجِلُّ وصفُه، ولحق المنصورُ بدمشق في نفرٍ يسير، وقَدِمَت البشارة إلى الملك الصالح نجم الدين بذلك في خامس عشر جمادى الأولى، فأمرَ بزينة القاهرة ومصر وظواهِرِهما، وقلعتي الجبل والروضة، فبالغ الناسُ في الزينة، وضربت البشائر عدَّةَ أيام، وقَدِمَت أسرى الفرنج ورؤوسُ القتلى، ومعهم الظهيرُ بن سنقر وعِدَّة من الأمراء والأعيان، وقد أركب الفرنجُ الجمالَ، ومن معهم من المقَدَّمين على الخيول، وشَقُّوا القاهرة، فكان دخولُهم يوما مشهودًا، وعُلِّقَت الرؤوس على أبواب القاهرة ومُلِئَت الحبوس بالأسرى، وسار الأميرُ بيبرس، والأميرُ ابن أبي علي بعساكِرِهما إلى عسقلان، ونازلاها فامتَنَعَت عليهم لحصانتِها، فسار ابن أبي علي إلى نابلس، وأقام بيبرس على عسقلان، واستولى نوابُ الملك الصالح نجم الدين على غزة والسواحل، والقدس والخليل، وبيت جبريل والأغوار، ولم يبقَ بيد الناصر داود بن الملك المعظَّم سوى الكرك والملقاء، والصلت وعجلون."},{"id":2565,"title":"محاصرة الخوارزمية لدمشق .","date":["العام الهجري :643","العام الميلادي :1245"],"text":"أخذ الملكُ الصالحُ نجمُ الدين أيوب صاحِبُ مصر دمشقَ بعد أن حاصرها بمساعدةِ الخوارزميَّة، وكان الخوارزميَّة يظنون أنَّ السلطانَ إذا انتصر على عَمِّه الملك الصالح إسماعيل يقاسِمُهم البلادَ حتى دمشق، فلما منعوا من دمشقَ، وصاروا في الساحِلِ وغيره من بَرِّ الشام، تغيَّرت نياتُهم، واتفقوا على الخروجِ عن طاعة الملكِ الصالح نجم الدين، وساروا إلى داريا وانتهبوها، وكاتَبوا الأميرَ ركنَ الدين بيبرس وهو على غَزَّة بعسكرٍ جَيِّدٍ مِن عساكر مصر، وحَسَّنوا له أن يكونَ معهم يدًا واحدةً ويزوِّجوه منهم، فمال إليهم، وكاتبوا الناصِرَ داود صاحِبَ الكرك، فوافَقَهم ونزل إليهم واجتمع بهم وتزوَّج منهم، وعاد الناصرُ إلى الكرك واستولى على ما كان بيد الأمير حسامِ الدينِ بنِ أبي علي، من نابلس والقُدس والخليل، وبيت جبريلَ والأغوار، وخاف الصالحُ إسماعيل، فكاتب الخوارزميَّة وقَدِم إليهم، فحلفوا له على القيامِ بنُصرتِه، ونزلوا دمشقَ، فقام الأميرُ حسام الدين بن أبي علي بحفظِ البلدِ أحسَنَ قيام، وألحَّ الخوارزمية ومعهم الصالحُ إسماعيل في القتال ونهْبِ الأعمال، وضايقوا دمشقَ، وقطعوا عنها الميرةَ، فاشتَدَّ الغلاءُ بها، ومات كثيرٌ من الناس جوعًا، ثم عَدِمَت الأقواتُ بالجملة، وأكل الناسُ القِطَط والكلابَ والميتاتِ، ومات شخصٌ بالسجن فأكله أهلُ السِّجنِ! وهلك عالمٌ عظيم من الجوع والوباء، واستمر هذا البلاء ثلاثة أشهرٍ، وصار من يمُرُّ من الجبل يشتَمُّ ريحَ نتنِ الموتى، لعجز الناس عن مواراة موتاهم، وأخذ الملك الصالح نجم الدين مع ذلك في إعمالِ الحِيَل والتدبير، وما زال بالمنصور إبراهيمَ صاحب حمص حتى مال إليه، واتفق أيضًا مع الحلبيِّينَ على محاربة الخوارزميَّة، فخرج الملك الصالح نجم الدين من القاهرةِ بعساكِرِ مصر، ونزل العباسة، فوافاه بها رسلُ الخليفة، وهما محمَّد بن وجه السبع، وجمالُ الدين عبد الرحمن بن محيي الدين أبي محمد يوسف بن الجوزي في آخر شوال، ومعهما التقليدُ والتشريف الأسود: وهو عمامة سوداء وجبة وطوق ذهب، وفرس بمركوبٍ بحلية ذَهَب، فنصب المنبرَ، وصعد عليه جمال الدين عبد الرحمن محيي الدين بن الجوزي الرَّسول، وقرأ التقليدَ بالدهليز السلطاني، والملك الصالحُ نجم الدين قائم على قَدَميه، حتى فرغ من القراءة، ثم ركِبَ والملك الصالحُ نجم الدين بالتشريفِ الخليفتي، فكان يومًا مشهودًا، وكان قد حضر أيضًا من عند الخليفة تشريفٌ باسم الصاحب معين الدين بن شيخ الشيوخ، فوجد أنه قد مات، فأمر السلطانُ أن يفاض على أخيه الأميرِ فخرِ الدين يوسف بن شيخ الشيوخ، فلبسه، فلما بلغ الخوارزميَّةَ مسيرُ السلطان من مصر، ومسير الملك المنصور إبراهيم صاحِب حمص بعساكر حلب، رحلوا عن دمشق يريدون لقاء المنصورِ، فوجد أهلُ دمشق برحيلهم فَرَجًا، ووصلت إليهم الميرةُ، وانحلَّ السِّعرُ."},{"id":2566,"title":"وفاة الإمام تقي الدين أبي عمرو بن الصلاح .","date":["العام الهجري :643","الشهر القمري : ربيع الآخر","العام الميلادي :1245"],"text":"هو الإمامُ مفتي الإسلام تقي الدين أبو عمرو عثمان بن الإمام البارع أبي القاسم صلاح الدين عبد الرحمن بن عثمان بن موسى بن أبي نصر النصري الكردي، الشهرزوري، الشافعي. المعروف بابن الصلاح، مفتي الشام ومحدِّثُها، سمع الحديثَ ببلادِ الشَّرقِ وتفَقَّه بالموصِلِ وحلب وغيرها، وُلِدَ سنة 577 بشرخان – وهي قريةٌ من أعمال إربل قريبةٌ مِن شهرزور- تفقَّه على والِدِه صلاح الدين بشهرزور، وكان والدُه شيخَ تلك الناحية، ومدرِّسًا بالأسديَّة التي بحَلَب، وواقفها أسد الدين شيركوه بن شادي. قال ابن خلكان: \"كان ابنُ الصَّلاحِ أحدَ فُضَلاء عصرِه في التفسير والحديثِ والفقه وأسماء الرجالِ وما يتعلق بعلم الحديثِ ونَقلِ اللغة، وكانت له مشاركةٌ في فنون عديدةٍ، وكانت فتاويه مسدَّدةً، وهو أحد أشياخي الذين انتفعتُ بهم. قرأ الفقه أولًا على والده الصلاح، وكان من جلَّة مشايخ الأكراد المشارِ إليهم، ثم نقله والدُه إلى الموصل واشتغل بها مدَّة، وبلغني أنه كرر على جميع كتاب \" المهذَّب \" ولم يطر شاربُه، بالموصل, ثم سافر إلى خراسان فأقام بها زمانًا وحصَّل علمَ الحديث هناك\" قدم ابنُ الصلاح الشام وهو في عدادِ الفُضَلاء الكِبار، وأقام بالقُدسِ مُدَّة ودرس بالصلاحيَّة، ثم تحوَّل منه إلى دمشق، ودرس بالرواحيَّة ثم بدار الحديث الأشرفيَّة، وهو أول من وَلِيَها من شيوخ الحديثِ، وهو الذي صنَّف كتاب وقفِها، ثمَّ بالشامية الجوانيَّة، وقد صنف كتبًا كثيرةً مفيدةً في علوم الحديث- أشهرُها معرفةُ أنواع علوم الحديث المعروف بمقدِّمة ابن الصلاح، وله كتاب أدبُ المفتي والمستفتي- وفي الفقهِ، وله تعاليق حسنة على الوسيط وغيره من الفوائد التي يرحل إليها. كان ابن الصلاح إمامًا بارعًا، حجة، متبحرًا في العلوم الدينية، بصيرًا بالمذهب ووجوهه، خبيرًا بأصولِه، عارفًا بالمذاهبِ، جيدَ المادَّة من اللغة والعربية، حافظًا للحديث متفننًا فيه، حَسَن الضبطِ، كبيرَ القَدرِ، وافرَ الحُرمة، فكان عديمَ النظيرِ في زمانِه مع ما هو فيه من الدين والعبادة والنسك والصيانة، والورع والتقوى على طريق السَّلف الصالح، كما هو طريقة متأخري أكثر المحدِّثين، مع الفضيلة التامَّة في فنون كثيرة. قال ابن الحاجب في معجمه: \" ابن الصلاح إمامٌ وَرِع، وافِرُ العقل، حسَنُ السَّمت، متبحِّرٌ في الأصول والفروع، بالغٌ في الطلب حتى صار يُضرَبُ به المثل، وأجهد نفسَه في الطاعة والعبادة. – قلت (الذهبي): وكان حسَنَ الاعتقاد على مذهَبِ السَّلف، يرى الكف عن التأويل، ويؤمِنُ بما جاء عن الله ورسوله على مرادِهما. ولا يخوض ولا يتعمَّق- وفي فتاويه: سئل عمن يشتغل بالمنطق والفلسفة؟ فأجاب: الفلسفة أسُّ السَّفه والانحلال، ومادة الحيرة والضلال، ومثار الزيغ والزندقة. ومن تفلسف عَمِيَت بصيرته عن محاسِنِ الشريعة المؤيَّدة بالبراهين. ومن تلبَّسَ بها قارنه الخِذلانُ والحِرمانُ، واستحوذ عليه الشَّيطانُ، وأظلم قلبُه عن نبوة محمَّد صلى الله عليه وسلم إلى أن قال(ابن الحاجب): واستعمال الاصطلاحات المنطقيَّة في مباحث الأحكام الشرعيَّة من المُنكَرات المستبشَعة، والرَّقاعات المستحدَثة، وليس بالأحكامِ الشرعيَّة- ولله الحمد- افتقارٌ إلى المنطق أصلًا، وهو قعاقِعُ قد أغنى الله عنها كلَّ صحيح الذهن؛ فالواجِبُ على السلطان أعَزَّه الله أن يدفَعَ عن المسلمينَ شَرَّ هؤلاء المشائيم، ويخرِجَهم من المدارس ويُبعِدَهم, ولابن الصلاح فتاوى مسددة, وكان معظَّمًا في النفوس، حَسَن البِزَّة، كثيرَ الهيبةَ، يتأدَّبُ معه السلطانُ فمَن دونه. تفقَّه عليه خلقٌ كثير، منهم: الإمام شمس الدين عبد الرحمن بن نوح المقدسي، والإمامُ شِهابُ الدين عبدُ الرحمن بن إسماعيل أبو شامة، والإمام كمال الدين سلار، والإمام كمال الدين إسحاق، والإمامُ تقيُّ الدين بن رزين قاضي الديار المصرية، والعلَّامة شمس الدين بن خَلِّكان قاضي الشام وغيرهم \"ولم يزل على طريقةٍ جيِّدة حتى كانت وفاتُه بمنزلِه في دار الحديث الأشرفيَّة في سَحَر الأربعاء الخامس والعشرين من ربيع الآخر، وحُمِل على الرؤوس، وازدحم عليه الخلقُ، وكانت على جنازته هيبةٌ وخشوع، فصُلِّيَ عليه بالجامع، وشيعوه إلى عند باب الفرَج، فصُلِّيَ عليه بداخله ثانيًا، ورجع الناس لأجل حصار البلد بالخوارزميَّة، وما صَحِبَه إلى جبانة الصوفية إلا نحوُ العشرة."},{"id":2567,"title":"الملك الصالح نجم الدين يحاصر عمه الصالح إسماعيل بدمشق .","date":["العام الهجري :643","الشهر القمري : جمادى الأولى","العام الميلادي :1245"],"text":"كَثُرَت محاربة الصاحب معين الدين بن شيخ الشيوخ ومعه الخوارزمية الذين كان مجيئُهم بناءً على طلب الملك الصالحِ نجم ِالدين  أيوب صاحبِ مصر، فحاصروا دمشقَ وقطعوا عنها الميرةَ فتضايقت البلدُ، ثم أحرقوا قصرَ الحجَّاج في ثاني محرم، ورمي بالمجانيق وألحَّ بالقتال، فأحرق الصالحُ إسماعيل صاحب دمشق في ثالثه عدَّة مواضع، ونُهِبَت أموال الناس، وجرت شدائدُ إلى أن أهل شهر ربيع الأول، ففيه خرج المنصورُ صاحب حمص من دمشق، وتحدَّثَ معه بركة خان مقدم الخوارزمية في الصَّفحِ، وكذلك طلبوا إلى ابن شيخ الشيوخ الأمانَ ثم قرر أن الصالح إسماعيلَ يسلِّم دمشق، على أن يخرج منها هو والمنصور بأموالهم، ولا يعرض لأحدٍ مِن أصحابهم ولا لشيءٍ ممَّا معهم، وأن يعوَّض الصالحُ إسماعيل عن دمشق ببعلبك وبُصرى وأعمالها، وجميع بلاد السواد، وأن يكون للمنصور حمص وتدمر والرحبة، فأجاب أمين الدولة وزير دمشق إلى ذلك، وحلف الصاحِبُ معين الدين وزير مصر لهم، فخرج الصالحُ إسماعيل والمنصور من دمشق، ودخل الصاحِبُ معين الدين في يوم الاثنين ثامن جمادى الأولى، ومنع الخوارزميَّة من دخول دمشق ودبَّرَ الأمير أحسَنَ تدبير، وأقطع الخوارزميَّة الساحلَ، وخطب بدمشق وبجامعِ دمشق وعامَّة أعمالها للمَلِك الصالح نجم الدين، وسلم أيضًا الأمير سيف الدين علي بن قلج قلعة عجلون لأصحاب الملك الصالح، وقدم إلى دمشقَ، فلما وردت الأخبارُ بذلك على الملك الصالح نجم الدين أنكر على الطواشي شهاب الدين والأمراء كيف مكَّنوا الصالح إسماعيل من بعلبك، وقال: إنَّ الصاحِبَ معين الدين حَلَف له، وأما أنتم فما حلفتم، وأمَرَ الملك الصالح نجم الدين أن يسيرَ ركن الهيجاوي، والوزير أمين الدولة السامري، تحت الحوطة إلى قلعة الروضة، فسُيِّرَا من دمشق إلى مصر، واعتُقِلا بقلعة الجبل فاتفق مرض الصاحبِ معين الدين ووفاته بدمشق، في الثاني والعشرين من شهر رمضان، فكتب السلطان إلى الأمير حسام بن أبي علي الهذباني، وهو بنابلس، أن يسير إلى دمشق ويتسلمها، فسار إليها وصار نائبًا بدمشق، والطواشي رشيد بالقلعة."},{"id":2568,"title":"وفاة الشيخ علم الدين أبي الحسن السخاوي .","date":["العام الهجري :643","الشهر القمري : جمادى الآخرة","العام الميلادي :1245"],"text":"هو الإمام العلَّامة، شيخ القرَّاء والأدباء، عَلَمُ الدين أبو الحسن علي بن محمد بن عبد الصمد بن عبد الأحد بن عبد الغالب الهمذاني المصري السخاوي، ثم الدمشقي المقرئُ النحوي شيخُ القراء بدمشق، ولد سنة 558 وقيل سنة تسع وخمسين. كان قد اشتغل بالقاهرةِ على الشيخِ أبي محمد القاسم الشاطبي المقرئ، وأتقن عليه علم القراءات والنَّحو واللُّغة، وشرح قصيدتَه الشاطبيَّة، كان إمامًا في العربية، بصيرًا باللغةِ، فقيهًا مفتيًا عالمًا بالقراءات وعِلَلِها، مجوِّدًا لها، بارعًا في التفسير. صنف وأقرأ وأفاد، وروى الكثير، وبَعُد صيتُه، وتكاثر عليه القراء. وختم عليه ألوفٌ من الناس، وله شرحُ المفصَّل للزمخشري, وله تفاسير وتصانيف كثيرة، ومدائح في رسول الله صلى الله عليه وسلم، وكانت له حلقةٌ بجامع دمشق، قال ابن خلكان: \"رأيته بدمشقَ والناس يزدحمونَ عليه في الجامِعِ لأجل القراءة، ولا تصِحُّ لواحدٍ منهم نوبةٌ إلَّا بعد زمان، ورأيتُه مرارًا يركَبُ بهيمةً وهو يصعد إلى جبلِ الصالحين وحولَه اثنان وثلاثة وكل واحدٍ يقرأ ميعاده في موضعٍ غير الآخر، والكل في دفعةٍ واحدة، وهو يردُّ على الجميعِ، ولم يزل مواظبًا على وظيفته إلى أن توفِّيَ بدمشق\" قال الذهبي: \" وكان يترخَّصُ في إقراء اثنين فأكثَرَ، كل واحدٍ في سورة، وفي هذا خلافُ السنَّة، لأنَّنا أُمِرنا بالإنصاتِ إلى قارئٍ لنفهَمَ ونعقِلَ ونتدبر\" ومع حلقته بجامع دمشق ولي مشيخةَ الإقراء بتربة أم الصالح، وبها كان مسكنُه ووفاته, وكان مع سعة علومِه وفضائله دَيِّنًا حَسَن الأخلاقِ، مُحبَّبًا إلى الناسِ، وافِرَ الحرمةِ، مُطَّرِحًا للتكلُّف، ليس له شغل إلا العلم ونشرُه. قال الإمام أبو شامة: \"في ثاني عشر جمادى الآخرة، سنة 643، توفي شيخنا علم الدين علَّامة زمانه وشيخُ أوانه بمنزله بالتربة الصالحيَّة، وكان على جنازتِه هيبةٌ وجَلالةٌ وإخبات، ومنه استفدت علومًا جمة كالقراءات، والتفسير، وفنون العربية\" ودُفِنَ بقاسيون، وهو غيرُ السخاوي المشهور بالحديث."},{"id":2569,"title":"وفاة الحافظ ضياء الدين المقدسي .","date":["العام الهجري :643","الشهر القمري : جمادى الآخرة","العام الميلادي :1245"],"text":"هو الشَّيخُ الإمامُ الحافِظُ القدوة المحقِّق، المجَوِّد الحُجَّة، بقية السلف، أبو عبد الله ضياء الدين، محمد بن عبد الواحد بن أحمد بن عبد الرحمن بن إسماعيل، السعدي المقدسي، الجماعيلي، ثم الدمشقي، الصالحي، الحنبلي، صاحبُ التصانيف والرحلة الواسعة. ولد سنة 569 بدمشق في الدير المبارك، بقاسيون، سمع الحديث الكثير وكتب كثيرًا, وطوَّفَ بالبلاد وبَقِيَ في الرحلة المشرقيَّة مدَّة سنين، وحصَّل فيها الأصولَ الكثيرة وجرَّح وعدَّل، وصحَّح وعلَّل، وقيَّد وأهمل، مع الديانة والأمانة والتقوى، والصيانة والورع والتواضُع، والصدق والإخلاص وصحَّة النقل. وجمَع وصَنَّف، وألف كتبًا مفيدةً حسنة كثيرة الفوائد، من ذلك كتابُ الأحكام ولم يتِمَّه، وكتاب المختارة وفيه علوم حسنة حديثيَّة، وهي أجودُ من مستدرك الحاكم لو كَمُل، وله فضائِلُ الأعمال, وفضائل القرآن ومناقبُ أهل الحديث، وغيرُ ذلك من الكتب الحَسَنة الدالَّة على حِفظِه واطِّلاعِه وتضلُّعِه من علوم الحديث متنًا وإسنادًا، قال الذهبي: \"ولم يزَلْ ملازمًا للعلم والرواية والتأليفِ إلى أن مات، وتصانيفُه نافعة مهذبة. أنشأ مدرسةً إلى جانب الجامِعِ المظفري، وكان يبني فيها بيَدِه ويتقنَّع باليسير، ويجتهِدُ في فعل الخير ونشْرِ السنَّة، وفيه تعبٌد وانجماع عن الناس، وكان كثيرَ البر والمواساة، دائِمَ التهجد، أمَّارًا بالمعروف، بهيَّ المنظر، مليحَ الشَّيبة، محببًا إلى الموافق والمخالف، مشتغلًا بنَفسِه\" قال الحافظ شرف الدين يوسف بن بدر: \"رحم الله شيخَنا ابن عبد الواحد، كان عظيمَ الشأن في الحفظِ ومعرفة الرجال، هو كان المشارَ إليه في علم صحيح الحديث وسقيمه، ما رأت عيني مِثلَه\". وقال عمرُ بنُ الحاجِبِ: \"شيخنا الضياء شيخُ وقته، ونسيجُ وحده علمًا وحفظًا وثقةً ودينًا، من العلماء الربانيين، وهو أكبر من أن يدِلَّ عليه مثلي\" وقد وقف كتبًا كثيرة عظيمةً لخزانة المدرسة الضيائيَّة التي وقفها على أصحابِهم من المحدِّثين والفقهاء. توفي بدمشق."},{"id":2570,"title":"وفاة الحافظ ابن النجار .","date":["العام الهجري :643","الشهر القمري : شعبان","العام الميلادي :1246"],"text":"هو الإمامُ الحافظُ الكبيرُ، محَدِّث العراق، ومؤرِّخُ العصر، محبُّ الدين، أبو عبد الله محمَّد بن محمود بن حسن بن هبة الله بن محاسن بن النجار البغدادي, مولِدُه سنة 578. كان والدُه مقدمَ النجَّارين بدار الخلافة، وكان من العوام. أولُ سماع لابن النجار سنة ثمان وثمانين، وأول دخولِه في الطلب وهو حَدَثٌ سنة ثلاث وتسعين، سمع الكثيرَ ورحل شرقًا وغربًا، وهو صاحب كتاب ذيل التاريخ المعروف جعَلَه ذيلًا لتاريخ بغداد للخطيب البغدادي. قال ابن النجار في أول (تاريخه): \"كنت وأنا صبيٌّ عَزَمتُ على تذييل (الذيل) لابنِ السَّمعاني، فجمعتُ في ذلك مسوَّدة، ورحلت وأنا ابن ثمان وعشرين سنة، فدخلت الحجازَ والشام ومصر والثغر وبلاد الجزيرة والعراق والجبال وخراسان، وقرأت الكتبَ المطولات، ورأيتُ الحفَّاظَ، وكنتُ كثير التتبُّع لأخبار فضلاء بغداد ومَن دخَلَها\". قال الذهبي: \"ساد ابنُ النجَّار في هذا العلم, واشتهر، وكتب عمَّن دَبَّ ودرج من عالٍ ونازل، ومرفوعٍ وأثَر، ونظمٍ ونَثر، وبرَعَ وتقدم، وصار المشارَ إليه ببلده، ورحل ثانيًا إلى أصبهان في حدود العشرينَ، وحجَّ وجاور، وعمل (تاريخًا) حافلًا لبغداد ذيَّلَ به على الخطيب واستدرك عليه فيه، وهو في مائتي جزء، ينبئ بحِفظه ومعرفتِه، وقد قرأتُ عليه (ذيل التاريخ) وكان مع حفظِه فيه دينٌ وصيانةٌ ونُسُك\". وقد شرع في كتابة التاريخ وعمره خمس عشرة سنةً، وقرأ بنفسِه على المشايخِ كثيرًا حتى حصل نحوًا من ثلاثة آلاف شيخٍ، من ذلك نحوٌ من أربعمائة امرأة، وتغَرَّب ثماني وعشرين سنة، ثم جاء إلى بغداد وقد جمع أشياءَ كثيرة، من ذلك القَمَر المنير في المسند الكبير، يذكُرُ لكلِّ صحابيٍّ ما روى، وكَنز الأيام في معرفة السُّنَن والأحكام، والمختَلِف والمؤتَلِف، والسابق واللاحق، والمتَّفِق والمفترِق، وكتاب الألقاب، ونهْج الإصابة في معرفة الصَّحابة، والكافي في أسماء الرِّجال، وغير ذلك مما لم يتمَّ أكثرُه, وله أخبارُ مكَّة والمدينة وبيت المقدس، وغُرَر الفوائد وأشياء كثيرة جدًّا، وذكر أنَّه لما عاد إلى بغداد عُرِضَ عليه الإقامة في المدارس فأبى وقال: معي ما أستغني به عن ذلك، وكانت وفاتُه يوم الثلاثاء الخامس من شعبان، وله من العمر خمسٌ وسبعون سنة وصُلِّيَ عليه بالمدرسة النظامية، وشهِدَ جنازته خلقٌ كثير، وكان ينادى حول جنازته هذا حافِظُ حديث رسولِ الله صلى الله عليه وسلم، الذي كان ينفي الكذبَ عنه، ولم يترك وارثًا."},{"id":2571,"title":"البابا يبيح دم ملك القدس .","date":["العام الهجري :644","العام الميلادي :1246"],"text":"قَدِمَت الرسلُ من عند البابا تخبِرُ بأنه قد أباح دمَ الأبدور ملكِ الفِرنجِ في القُدسِ لتهاونِه في قتال المسلمين، وأرسل البابا طائفةً مِن عنده ليقتُلوه، فلما انتهوا إلى المَلِك كان قد استعَدَّ لهم وأجلس مملوكًا له على السَّريرِ فاعتقدوه المَلِكَ فقتلوه، فعند ذلك أخَذَهم الأبدور فصَلَبَهم على باب قَصرِه بعد ما ذبحَهم وسلخَهم وحشى جلودَهم تبنًا، فلما بلغ ذلك البابا أرسَلَ إليه جيشًا كثيفًا لقتاله فأوقع الله الخلافَ بينهم بسبب ذلك."},{"id":2572,"title":"قتال الخوارزمية جيش الصالح أيوب صاحب مصر ودمشق .","date":["العام الهجري :644","الشهر القمري : محرم","العام الميلادي :1246"],"text":"بعد رحيل الخوارزميَّة عن دمشق بعدما حاصروها حين أرسلَ الملك الصالحُ نجمُ الدين أيوب مِن مصرَ جيشًا لقتالهم وبعد تحالُفِ بيبرس معهم، وكذلك صاحب حمص، وكذلك الصالح إسماعيلُ كُلُّهم ضد صاحِبِ مصر، حيث أرسل الملِكُ الصالح أيوب القاضي نجمَ الدين محمد بن سالم النابلسي، المعروف بابن قاضي نابلس- وكان متقدمًا عنده- إلى مملوكِه الأمير ركن الدين بييرس، فما زال يخدعُه ويُمَنِّيه، حتى فارق الخوارزميَّة، وقَدِمَ معه إلى ديار مصرَ، فاعتُقِلَ بقلعة الجبل، وكان آخِرَ العهد به، فالتَقَوا مع الملك المنصورِ إبراهيم صاحِبِ حمص وعساكر حلب، وقد انضَمَّ إليهم عربٌ كثيرٌ وتركمان؛ نُصرةً للملك الصالحِ نجم الدين، وذلك بظاهِرِ حمص أوَّلَ يومٍ مِن المحرم، وقيل ثانِيَه، فكانت بينهم وقعةٌ عظيمةٌ انهزم فيها الخوارزميَّة هزيمةً قبيحة، تبَدَّد منها شملُهم، ولم يقُمْ لهم بعدها قائمةٌ، وقُتِلَ مُقَدَّمُهم بركة خان وأُسِرَ كثيرٌ منهم واتَّصلَ مَن فرَّ منهم بالتَّتار، ووردت البشرى بهذه الهزيمةِ إلى السلطانِ الملك الصالحِ نجم الدين أيوب في المحَرَّم، فزُيِّنَت القاهرة ومِصرُ والقلعتان،"},{"id":2573,"title":"وفاة الملك المنصور صاحب حمص .","date":["العام الهجري :644","الشهر القمري : صفر","العام الميلادي :1246"],"text":"هو الملك المنصور، ناصر الدين إبراهيم بن الملك المجاهد أسد الدين شيركوه الصغير بن محمد بن أسد الدين شيركوه الكبير. كان الملك المنصور بطلًا شجاعًا مُتواضعًا، عاليَ الهمة، وافر الهيبةِ. كان في بدايةِ أمرِه موافقًا للمَلِك الصالح إسماعيلَ ومُصاهِرًا له، سار بعَسكرِه وعسكر حلب، وعمل المصاف مع الخوارزمية والمظفر صاحب ميافارقين، فالتَقَوا في صفَر سنة أربعين، فهزمهم المنصورُ أقبَحَ هزيمةٍ، وتعثَّرت الخوارزميَّة، ونزل المنصورُ في مخيَّم المظفَّر، واحتوى على خزائنِه، توفي الملك المنصورُ بدمشق في يوم الأربعاء حاديَ عشر صفر حيث كان يريد المسيرَ إلى مصر داخلًا في طاعة الصالحِ نجمِ الدين صاحب مصر بعد ما جرى بينهم من الخلافِ والحربِ، ثمَّ حُمِلَ في تابوت إلى حمص ودُفِنَ هناك، وكانت سلطنتُه ست سنين ونصفًا، وقام بعده على حمص ولَدُه الأشرف موسى، فأقام بها سنتين وشهورًا وأُخِذَت منه."},{"id":2574,"title":"اعتلاء \"كيوك خان\" عرش المغول خلفًا لأبيه \"أوكتاي خان\" .","date":["العام الهجري :644","الشهر القمري : ربيع الآخر","العام الميلادي :1246"],"text":"بعد وفاة \"جنكيز خان\" سنة 624 (1226م)، ظل مكانُه خاليًا مدَّة عامين، كان يقومُ خلالها الابنُ الأصغرُ \"تولوي\" بحكمِ الإمبراطوريَّة المغوليَّة بصفتِه وصيًّا على العرش، إلى أن اجتمَعَ كبار أمراء البيت الحاكم، وأجمعوا على اختيار \"أوكتاي\" خاقانًا للمغول خلفًا لأبيه جنكيز خان. واستمر أوكتاي يحكمُ المغول ثلاثَ عشرة سنة إلى أن تُوفي سنة 639 (1241م) بعد أن أتمَّ المغول في عهده فتحَ الصين الشمالية وجنوب روسيا وبلاد فارس؛ حيث قضى المغول على الدولة الخوارزميَّة. وبعد وفاته تمكَّنَت زوجته النصرانية \"توراكينا خاتون\" من أن تحافِظَ على عرش المغولِ لابنها \"كيوك\" الابنِ الأكبر لأوكتاي، وعَمِلَت في الفترة التي باشرت فيها الحكم بعد وفاة زوجِها على تحقيق هذا الغرض، فاستمالت قلوبَ كبارِ أمراء البيتِ الحاكِمِ، حتى إذا أدركت أن الفرصة قد سنحت لتحقيقِ ما تصبو إليه، دَعَت إلى عقد مجلس الشورى (القوريلتاي) لانتخابِ الخان الجديد، وحضر حفلَ تنصيب الخان في \"قرا قورم\" وفودٌ من مختَلِف أرجاء مملكتِهم. وفي هذا الاجتماعِ انتُخِبَ كيوك خانًا أعظَمَ للمغول، وذلك في التاسع من ربيع الآخر 644 (24 من أغسطس 1246م)."},{"id":2575,"title":"إرسال ثاني سفارة نصرانية من البابا \"أنوسنت الرابع\" إلى المغول. .","date":["العام الهجري :644","الشهر القمري : ربيع الآخر","العام الميلادي :1246"],"text":"أرسل البابا سفارةً ثانية، غادرت ليون ووصَلَت منغوليا وحضرت حفلَ تتويج \"كيوك خان\" على عرشِ المغولِ في مدينة \"قرا قورم\" عاصمة المغول في 9 من ربيع الآخر 644  (24 من أغسطس 1246م)، وقد أكرم كيوك خان وفادةَ سفارة البابا، وردَّ على المطالب البابويَّة بالرَّفضِ، وطلب من البابا أن يخضَعَ هو وسائِرُ ملوك أوروبا المسيحيين للسيادة المغوليَّة."},{"id":2576,"title":"القتال بين الملك الصالح أيوب صاحب مصر والصالح إسماعيل  .","date":["العام الهجري :644","الشهر القمري : رجب","العام الميلادي :1246"],"text":"سار الأميرُ حسام الدين بنُ أبي علي الهذباني من دمشق، واستولى على بعلبكَّ بغير حربٍ في رجب، وحَمَل منها الملك المنصورُ نورَ الدين محمود بن الملك الصالح إسماعيل، وأخَذَه الملك السعيدُ عبد الملك إلى الديار المصريةِ تحت الاحتياط، ثمَّ صَلَحت الحالُ بين السلطانِ الصالح نجمِ الدين أيوب وبين المنصور صاحِبِ حمصَ والناصِر صاحب حلب، واتفَقَت الكلمة وبَعَث الصالح نجم الدين أيوب إلى حلب يطلب تسليمَ الصالح إسماعيل، فلم يجِبْ إلى تسليمه وأخرج السلطانُ عسكرًا كبيرًا، قدَّمَ عليه الأمير فخرَ الدين يوسف بن شيخ الشيوخ وسَيَّرَه لمحاربة الكرك، فسارَ إلى غزة، وأوقع بالخوارزميَّة، ومعهم الناصرُ داود صاحِبُ الكرك في ناحيةِ الصَّلت، وكَسَرَهم وبدَّدَ شَملَهم، وفَرَّ الناصِرُ إلى الكرك في عِدَّة، وكانت الكسرةُ على الصلت في ربيع الآخر، وسار فخر الدين عنها بعد ما حَرَقها واحتاط على سائِرِ بلاد الناصِرِ، وولى عليها النوَّابَ ونازل فخرُ الدين الكركَ، وخرَّبَ ما حولها، واستولى على البلقاء، وأضعف الناصرَ حتى سأله الأمان، فبعث فخرُ الدين يطلُبُ منه مَن عنده مِن الخوارزميَّة، فسَيَّرَهم الناصِرُ إليه، فسار عن الكركِ وهم في خدمتِه ثمَّ نازل فخرُ الدين بُصرى، حتى أشرفَ على أخْذِها، فنزل به مرض أشفى منه على الموتِ وحُمِل في محفَّة إلى القاهرة، وبقِيَ العسكَرُ حتى استولوا عليها، وقَدِمَ المنصورُ إبراهيم صاحِبُ حمص إلى دمشق منتميًا إلى السلطانِ الملك الصالحِ نجم الدين أيوب فنزل به مرض مات به في صَفَر."},{"id":2577,"title":"دخول السلطان نجم الدين أيوب صاحب مصر إلى دمشق والقدس .","date":["العام الهجري :644","الشهر القمري : ذي القعدة","العام الميلادي :1247"],"text":"خرج السُّلطانُ الملك الصالح نجمُ الدين أيوب بالعساكِرِ في شوال يريدُ دمشق واستناب بديارِ مِصرَ الأميرَ حُسام الدين بن أبي علي، فدخل إلى دمشقَ في سابع عشر ذي القعدة، وكان دخولُه يومًا مشهودًا، فأحسن إلى النَّاسِ، وخلع على الأعيانِ، وتصَدَّقَ على أهل المدارِسِ والرُّبُط وأرباب البيوت وسار بعد خمسة عشر يومًا إلى بعلبكَّ، فرَتَّبَ أحوالها، وسار إلى بُصرى، وقد تسَلَّمها نوابُ السلطان أيوب من الأمير شهاب الدين غازي، نائبِ الملك الصالح إسماعيل، فتصَدَّقَ على مدارس بصرى ورُبُطِها وأرباب البيوت وجَهَّز السلطانُ الأميرُ ناصر الدين القيمري، والصاحِبُ محي الدين بن مطروح، إلى صلخد، وبها الأميرُ عز الدين أيبك المعظمي، فما زالا به حتى سلَّم صلخد، وسار إلى مصر، وتصَدَّق السلطانُ في القدس بألفي دينار مصرية، وأمر بذرع سور القدس، فكان ذراعه ستة آلاف ذراع بالهاشمي، فأمر بصرف غلَّات القدس في عمارتِه، وإن احتاج إلى زيادةٍ حُمِلَت من مصر."},{"id":2578,"title":"الدعوة لحرب صليبية سابعة .","date":["العام الهجري :645","العام الميلادي :1247"],"text":"بعد أن استخلص المسلمونَ بيتَ المقدس من يد الفرنجِ وبلغ الخبَرُ إلى أوربا لاستنفارِ أُمَرائِها وملوكِها، انعقد مجلسٌ كَنَسي في ليون تقَرَّر فيه إرسالُ حملة صليبيَّة سابعة بزعامة ملك فرنسا لويس التاسع المشهور بوَرَعِه حتى لُقِّبَ بالقديس، فأعَدَّ هذا الملك العُدَّة وجهَّز جيشًا أبحر أواخِرَ هذه السنة متجهًا إلى الشرقِ، وقد تم وصولُ خبر هذه الحملة إلى الملك الصالحِ نجمِ الدين أيوب صاحبِ مصرَ عن طريق ملك ألمانيا فردريك الثاني."},{"id":2579,"title":"إرسال سفارة نصرانية ثالثة من البابا \"أنوسنت الرابع\" إلى المغول .","date":["العام الهجري :645","الشهر القمري : محرم","العام الميلادي :1247"],"text":"في الوقتِ الذي خَرَجت فيه السفارة الثانية للمغول في 9 من ربيع الآخر 644 (24 من أغسطس 1246م) كانت هناك سفارة ثالثة خرجت في إثرِها، ضَمَّت رهبانًا من جماعة \"الدومنيكان\" وأوكلَت إليها مهمَّة مختلفة عن مهمَّة السفارتينِ السَّابقتَينِ، فقد أمَرَ البابا هذه السفارةَ أن تَصِلَ إلى أوَّلِ جيشٍ مغوليٍّ تُقابِلُه في فارس، وأن يحضَّ قائدَه على الامتناعِ عن نَهبِ النَّاِس، وبخاصَّةٍ النَّصارى منهم، وأن يعتَنِقَ النصرانيَّة، وأن يتوبَ عن خطاياه، فالتَقَت السِّفارةُ بجيشِ المغولِ في \"تبريز\" في 17 من المحرم 645 (24 من مايو 1247م) وكان ردُّ قائد الجيشِ المغولي أنَّ رسالة البابا أدَّت إليه النصيحةَ بعدم القتلِ، وأنَّه يرفُضُ دعوته إلى اعتناقِ النصرانية، وعلى البابا وملوكِ أوروبا أن يُعلِنوا خضوعَهم لسلطانِ المغول. ومِن ثمَّ لم تؤدِّ السفاراتُ الثلاث ما كان يطمَحُ له البابا من جذبِ المغول الوثنيِّين إلى النصرانيَّة ووقوفِهم معه ضِدَّ المسلمين."},{"id":2580,"title":"الصالح أيوب يحرر طبرية وعسقلان من الصليبيين .","date":["العام الهجري :645","الشهر القمري : صفر","العام الميلادي :1247"],"text":"سار الأميرُ فخر الدين بن شيخ الشيوخ أمير عسكر المَلِك الصالحِ نجم الدين أيوب صاحِب مصرَ بعسكرٍ إلى طبرية، ونزلت الجيوشُ لحصار الفرنج ففَتَحَت طبريَّةَ عَنوةً في عاشر صفر، وفَتَحَت عسقلان بعدَ حصارٍ شديد وأُخِذَت من يد الفرنجِ في أواخِرِ جُمادى الآخرةِ."},{"id":2581,"title":"محاولة استيلاء نجم الدين أيوب صاحب مصر على حمص .","date":["العام الهجري :646","العام الميلادي :1248"],"text":"قايض الملكُ الأشرف موسى صاحِبُ حمص تل باشر بحمص مع الملك الناصِر يوسُفَ بنِ العزيز بن الظاهر بن صلاح الدين، صاحِبِ حلب؛ ولذلك خرج الملكُ الصالح نجم الدين أيوب صاحِبُ مصر من مصرَ بالعساكِرِ إلى دمشقَ وجَهَّزَ الجيوشَ والمجانيقَ إلى حمص، ولَمَّا عَلِمَ الحلبيونَ بخروج الدماشِقة برزوا أيضًا في جَحفلٍ عظيمٍ ليَمنَعوا حمصَ منهم، واتَّفَق وصول الشيخِ نجم الدين البادرائي مدرس النظاميَّة ببغداد في رسالةٍ مِن الخليفة العباسي للإصلاحِ بين الطرفين فأصلَحَ بين الفريقين، وردَّ كلًّا من الفئتينِ إلى مستقَرِّها."},{"id":2582,"title":"عزل أمير مكة من قبل صاحب اليمن .","date":["العام الهجري :646","العام الميلادي :1248"],"text":"عزل الملكُ المنصورُ نورُ الدين عمر بن علي بن رسول صاحِبُ اليمن الأميرَ فخرَ الدين بن الشلاحِ عن مكَّةَ وأعمالِها، وولَّى محمد بن أحمد بن المسيب على مالٍ يقومُ به وقود عدده مائة فرسٍ كلَّ سنة، فقَدِمَ ابنُ المسيب مكة، وخرج الأميرُ فخر الدين، فسار بنفسِه إلى ابن المسيب وأعاد الجباياتِ والمكوس بمكَّة، وأخذ الصَّدَقةَ الواردة من اليمن، عن مالِ السلطان وبنى حصنًا بنخلةَ يسمى العطشان وحَلَّف هُذيلًا لنَفسِه، ومنع الجندَ النفقةَ فوثب الشريفُ أبو سعد بن علي بن قتادة على ابن المسيب، وقَيَّده وأخذ مالَه، وقال لأهلِ الحرم: إنما فعلتُ به هذا لأني تحقَّقتُ أنه يريد الفرارَ بالمال إلى العراق، وأنا غلامُ مولانا السلطان نور الدين عمر بن رسول والمالُ عندي محفوظٌ والخيلُ والعدد، إلى أن يَصِلَ مرسومه، فلم يكنْ غير أيام، وورد الخبَرُ بموت السلطان نور الدين."},{"id":2583,"title":"سقوط أشبيلية في يد الفرنجة  .","date":["العام الهجري :646","العام الميلادي :1248"],"text":"حاصر الأسبانُ إشبيليَّةَ مُدَّة ثمانية عشر شهرًا حتى سقَطَت في أيديهم فقاموا بتحويلِ جامِعِها إلى كنيسة وأزالوا كل معالمِ الإسلامِ فيها، ويُذكَرُ أن بعض المسلمين قد شاركوا في هذا الحصارِ بناءً على اتفاقهم مع النصارى، مثل محمد بن يوسف بن نصر أمير غرناطة من بني الأحمر، وقد تم هذا الاتفاقُ سنة 642، كما قام رامون ملك أراغون بإعلانِ حَربٍ صليبيَّةٍ على المسلمين بمباركة البابا واستولى بحملتِه تلك على لاردةَ وطرطوشةَ، وبعد هذه الحوادِثِ نَظَم أبو البقاء الرندي قصيدتَه المشهورة يرثي فيها المسلمين ببلاد الأندلس: لكلِّ شيءٍ إذا ما تمَّ نقصانُ  فلا يُغَرَّ بطِيبِ العَيشِ إنسانُ"},{"id":2584,"title":"اتصال ملك الأرمن بالمغول .","date":["العام الهجري :646","العام الميلادي :1248"],"text":"قام هيثوم الأول ملك أرمينية الصغرى بإرسال أخيه سمباط إلى منكو خاقان المغولِ الأكبر في عاصمتِه قره كروم، ثم تَبِعَه بنَفسِه مُقَدِّمًا للخاقان فروضَ الطاعةِ والولاء ووضَعَ الكنيسة ورعاياها تحتَ حمايته ورعايته."},{"id":2585,"title":"وفاة ضياء الدين بن البيطار .","date":["العام الهجري :646","الشهر القمري : شعبان","العام الميلادي :1248"],"text":"هو العلامةُ ضياءُ الدين أبو محمَّد عبد الله بن أحمد المالقي النباتي المعروفُ بابن البيطار، الطبيبُ، ولد في مالقةَ بالأندلس، كان عالمًا بالنبات وصفاتِه ومنافِعِه وأماكِنِه، سافر في البلادِ إلى اليونان والمغرب ومصر وبلاد الشام، وكان كلَّ ذلك يدرس علمَ النبات ويجمع العيِّنات، كان ثقةً فيما ينقُلُه حُجَّةً, وإليه انتهت معرفة النباتِ وتحقيقه وصفاته وأسمائه وأماكنه. كان لا يجارَى في ذلك. سافر إلى بلاد الأغارقة وأقصى بلاد الروم. وأخذ فنَّ النبات عن جماعة، وكان ذكيًّا فَطِنًا. قال الموفق أحمد بن أبي أصيبعة: \"شاهدت معه كثيرًا من النبات في أماكِنِه بظاهر دمشق. وقرأت عليه تفسيرَه لأسماء أدوية كتاب ديسقوريدس، فكنت أجِدُ من غزارة علمه ودرايته وفهمه شيئًا كثيرًا جِدًّا. ثم ذكر الموفَّقُ فَصلًا في براعته في النبات والحشائش، ثم قال: وأعجَبُ من ذلك أنه كان ما يذكرُ دواء إلا ويُعَيِّن في أي مقالة هو في كتاب ديسقوريدس وجالينوس، وفي أي عدد هو من جملة الأدوية المذكورة في تلك المقالة\". وكان في خدمة الملكِ الكامِلِ، وكان يَعتَمِدُ عليه في الأدوية المفردة والحشائِش، ثم خَدَمَ بعده ابنَه الملك الصالح. وكان متقدِّمًا في أيامه، حظيًّا عنده. عُيِّنَ في مصر رئيسًا للعشَّابين وأصحاب البسطات, ثم رحل إلى دمشق، ومن أشهر مصنَّفاته: الجامع لمفردات الأدوية والأغذية،كتاب الأدوية المفردة الذي لم يصنف مثله. وصَفَ فيه لألف وأربعمائة نوع من أنواع النبات والعقاقير بتراكيبها الكيميائية مع ملاحظات دقيقة على طرق الاستخدام في العلاج، وله المغني في الأدوية المفردة والأغذية، وله ميزان الطبيب، وكتاب الأفعال الغريبة والخواص العجيبة، فكان ابنُ البيطار يعتبَرُ من أشهر أطباء الأعشاب في عصره، توفِّيَ في دمشق."},{"id":2586,"title":"الاتصال بين لويس التاسع والمغول .","date":["العام الهجري :646","الشهر القمري : شعبان","العام الميلادي :1248"],"text":"في أثناء مسير الحملة الصليبية السابعة المتَّجِهة إلى الشرق بقيادة الملك لويس التاسع ملك فرنسا توقَّفَ في قبرص فأجرى اتصالاتِه مع المغول ليساعِدُوه على تطويق المسلمينَ في الشرق الأدنى ولِعَقدِ تحالف عسكري مع المغول ضد الأيوبيِّينَ في الشام وضدَّ الخلافة العباسيَّة في بغداد."},{"id":2587,"title":"وفاة الإمام العلامة جمال الدين بن الحاجب المالكي .","date":["العام الهجري :646","الشهر القمري : شوال","العام الميلادي :1249"],"text":"هو الشَّيخُ، الإمام، العلَّامة، المقرئ، الأصولي، الفقيه، النحوي، جمال الأئمَّة والمِلَّة والدين أبو عمرو بن الحاجب عثمانُ بن عُمَر بن أبي بكر بن يونس الدويني الكردي الأصل، الإسنائي المولد، ثمَّ المصري, المالكي. كان مولده في آخر سنة 570 بأسْنا وهي بلدة صغيرة بصعيد مصر، كان والده حاجبًا للأمير عز الدين موسك الصلاحي. اشتغل أبو عمرو بالقاهرة في صغره بالقرآنِ الكريم، ثم بالفقهِ على مذهب الإمام مالك، رضي الله عنه، ثم اشتغلَ بالعلم فحَرَّرَ النحو تحريرًا بليغًا، ثم قرأَ القراءات، وبرع في علومِه وأتقنها غايةَ الإتقان. تفقه فسادَ أهل عصرِه، وكان رأسًا في علوم كثيرة، منها الأصول والفروع والعربية والتصريف، والعروض والتفسير، وغير ذلك، وقد استوطن دمشق سنة 617، ودرَّس بها للمالكية جامعها وبالنورية المالكية، وتخرج به الأصحاب، حتى كان خروجُه من دمشق بصحبةِ الشيخ عز الدين بن عبد السلام سنةَ ثمان وثلاثين، فصارا إلى الدِّيار المصرية، وكان من أذكى الأئمَّة قريحةً، وكان حُجَّةً متواضعًا عفيفًا كثير الحياء منصفًا محبًّا للعلم وأهله، بارعًا في العلوم متقنًا لمذهب مالك بن أنس، وله مختصر في الفقه انتظم فيه فوائد ابن شاش، ومختصر في أصول الفقه، استوعب فيه عامة فوائد الإحكام لسيف الدين الآمدي، وشرح المفصل والأمالي في العربية، والمقدمة المشهورة في النحو، اختصر فيها مفصَّل الزمخشري وشَرَحَها، والتصريف وشرحه، وعروض على وزن الشاطبية. وسار بمصنفاته الركبانُ. قال القاضي ابن خلكان: \" وصنَّفَ في أصول الفقه، وكلُّ تصانيفه في نهاية الحسن والإفادة، وخالف النحاةَ في مواضِعَ، وأورد عليهم إشكالاتٍ وإلزاماتٍ تَبعُد الإجابة عنها، وكان من أحسَنِ خَلقِ الله ذهنًا, ولما عاد إلى القاهرة جاءني مرارًا بسبب أداء شهاداتٍ، وسألته عن مواضِعَ في العربية مُشكِلة، فأجاب أبلغَ إجابة بسكونٍ كثيرٍ وتثَبُّت تام\"  توفي بالإسكندرية ضاحي نهار الخميس 26 شوال، ودفن خارج باب البحر بتربة الشيخ الصالح ابن أبي شامة."},{"id":2588,"title":"استعداد التتار لغزو الصين وبلاد المسلمين .","date":["العام الهجري :647","العام الميلادي :1249"],"text":"اعتلى \"كيوك\" عرش دولةِ المغولِ, ولم يكنْ مِثلَ أبيه \"أوكتاي\" ملكًا كريمًا، نبيلَ الخُلق، طيبَ المعاملةِ مع المسلمين؛ وإنما كان رجلًا مغامرًا محاربًا، يميلُ إلى الغزو والفتحِ مِثلَ جَدِّه جنكيز خان، وما إن استقَرَّ في الحكم حتى دعا الأمراء إلى ضرورة مراعاة أحكام القانون المغولي (الياسا)، وحذَّرَ من الخروج عليه، ثم قام بتجهيزِ الجيوشِ لمواصلةِ فتحِ الصين الجنوبيَّة، وأوكل هذه المهمَّةَ إلى القائِدِ المغولي الشهير \"سوبوتاي\"، وأوفد \"إيلجتكاي\" إلى إيران لفتحِ بقية البلادِ الإسلاميَّة، وجعل له السُّلطةَ العليا في الإشرافِ على شؤون بلاد الروم والكرج والموصل، وديار بكر، ونصب عددًا من أمرائِه والموالين له على المناطقِ التابعةِ لسلطانه. وكانت آخِرَ أعماله أنَّه عقد تحالفًا مع الأرمنِ النصارى؛ وذلك استعدادًا لحملة كان يعدُّها لغزو الشامِ ومصر، غيرَ أنه هلك في 9 من ربيع الآخر 647 (22 من يوليو 1249م) فتوقف مشروعُه."},{"id":2589,"title":"فيضان الماء ببغداد .","date":["العام الهجري :647","العام الميلادي :1249"],"text":"طغى الماء ببغداد حتى أتلف شيئًا كثيرًا من المحالِّ والدُّور الشهيرة، وتعَذَّرت الجُمَعُ في أكثر الجوامع بسبب ذلك سوى ثلاثِة جوامِعَ، ونُقِلَت توابيت جماعة من الخلفاء إلى الترب من الرصافة خوفًا عليهم من أن تغرق محالُّهم، منهم المقتصد بن الأمير أبي أحمد المتوكل، وذلك بعد دفنه بأكثَرَ من 350 سنة، وكذا نُقِلَ ولَدُه المكتفي وكذا المقتفي بن المقتدر بالله."},{"id":2590,"title":"الحملة الصليبية السابعة تصل إلى دمياط وتحتلها .","date":["العام الهجري :647","الشهر القمري : صفر","العام الميلادي :1249"],"text":"قَدِمَ السلطان الملك الصالحُ نجم الدين أيوب من دمشق، وهو مريضٌ، لَمَّا بلغَه من حركةِ الفرنج، فنزل بأشموم طناح في المحرم، وجمع في دمياط من الأقواتِ والأسلحة شيئًا كثيرًا، وبعث إلى الأميرِ حسام الدين بن أبي علي نائبِه بالقاهرة، أن يجهِّزَ الشواني من صناعةِ مصر، فشرع في تجهيزِها، وسَيَّرَها شيئًا بعد شيء، وأمر الملك الصالح نجم الدين أيوب الأمير فخر الدين بن شيخ الشيوخ أن ينزل على جيزةِ دمياط بالعساكرِ ليصيرَ في مقابلة الفرنج إذا قَدِموا فتحوَّل الأمير فخر الدين بالعساكر، فنزل بالجيزةِ تجاهَ دمياط، وصار النيلُ بينه وبينها، ثم في الساعة الثانية من يوم الجمعة لتسعٍ بَقِينَ مِن صفر وصلت مراكِبُ الفرنج البحرية، وفيها جموعُهم العظيمة بصحبة لويس التاسع ملك فرنسا، وقد انضَمَّ إليهم فرنجُ الساحل كله، فأرسَوا في البحر بإزاء المسلمين، وسَيَّرَ ملك الفرنج إلى الملك الصالحِ كتابًا يتهَدَّدُ فيه ويتوعَّدُه بقتله واحتلالِ مصر، فلمَّا وصل الكتاب إلى السلطان الملك الصالحِ وقرئ عليه، كتب الجوابَ فيه أنهم أصحابُ الحربِ والسيوفِ، وأنَّه كم من فئةٍ قليلةٍ غلبت فئةً كثيرةً بإذن الله، وفي يوم السبت نزل الفرنجُ في البر الذي عسكَرَ فيه المسلمون، وضُرِبَت للويس التاسع خيمةٌ حمراء، فناوشهم المسلمون الحربَ، فلما أمسى الليل رحل الأميرُ فخر الدين يوسف بن شيخ الشيوخ بمن معه من عساكِرِ المسلمين، وقطع بهم الجسرَ إلى الجانب الشرقي، الذي فيه مدينةُ دمياط، وخلا البَرُّ الغربي للفرنج، وسار فخر الدين بالعسكر يريد أشموم طناح، فلما رأى أهلُ دمياط رحيل العسكر، خرجوا كأنما يسحبونَ على وجوهِهم طول الليلِ، ولم يبقَ بالمدينة أحدٌ البتة، وصارت دمياط فارغةً مِن الناس جملةً، وفروا إلى أشموم طناح مع العسكَرِ، وهم حفاةٌ عراةٌ جياعٌ فقراء حيارى بمن معهم من الأطفال والنساء، وساروا إلى القاهرة، فنهبهم الناسُ في الطريق، ولم يبقَ لهم ما يعيشون به فعُدَّت هذه الفعلة من الأمير فخر الدين من أقبَحِ ما يُشَنَّع به، وأصبح الفرنجُ يوم الأحد لسبعٍ بقين من صفر، سائرينَ إلى مدينة دمياط، فعندما رأوا أبوابها مفتحةً ولا أحد يحميها، خشُوا أن تكون مكيدة، فتمَهَّلوا حتى ظهر أنَّ النَّاسَ قد فروا وتركوها، فدخلوا المدينةَ بغير كلفة ولا مؤنة حصارٍ، واستولوا على ما فيها من الآلات الحربية، والأسلحة العظيمة والعُدَد الكثيرة، والأقوات والأزواد والذخائر، والأموال والأمتعة وغير ذلك، صَفْوًا، وبلغ ذلك أهلَ القاهرة ومصر، فانزعج الناس انزعاجًا عظيمًا، ويَئِسوا من بقاء كلمة الإسلامِ بديار مصر، لتمَلُّك الفرنجِ مدينة دمياط، وهزيمة العساكر، وقوَّة الفرنج بما صار إليهم من الأموالِ والأزواد والأسلحة، والحصن الجليل الذي لا يقدر على أخذه بقوة، مع شِدَّة مرض السلطان الصالح أيوب، وعَدَمِ حركته، وعندما وصلت العساكرُ إلى أشموم طناح، ومعهم أهل دمياط، اشتَدَّ حنق الملك الصالح أيوب على الكنانيين، وأمر بشنقهم فقالوا: وما ذنبُنا إذا كانت عساكِرُ السلطان جميعهم وأمراؤه هربوا وأحرَقوا الزردخاناه فلأي شيء نحن فشُنِقوا, فكانت نقمةُ السلطان عليهم أنهم خرجوا من المدينة بغيرِ إذنٍ حتى تسلَّمَها الفرنج، فكانت عِدَّةُ مَن شُنِقَ زيادة على خمسين أميرًا من الكنانيين، وتغيَّرَ السلطان على الأمير فخر الدين بن شيخ الشيوخ، وقامت الشناعةُ من كل أحدٍ على الأمير فخر الدين، فخاف كثيرٌ من الأمراء وغيرهم سطوةَ السلطان، وهَمُّوا بقتله، فأشار عليهم فخر الدين بالصبر، حتى يتبين أمر السلطان ومَرَضه."},{"id":2591,"title":"وفاة الملك يحيى مؤسس الدولة الحفصية بتونس وتولي ابنه بعده .","date":["العام الهجري :647","الشهر القمري : جمادى الآخرة","العام الميلادي :1249"],"text":"هو الملِكُ صاحِبُ تونس أبو زكريا يحيى بن الأميرِ عبد الواحد بن الشيخ أبي حفص عمَرَ الهنتاني، الموحِّدي كان أبوه متوليًا لمدائن إفريقيَّة لآلِ عبد المؤمن، فمات ووَلِيَ بعده ابنُه الأمير أبو محمد عبد الله الحفصي، فوَلِيَ مُدَّة، ثم وثب عليه أخوه أبو زكريا يحيى بدعم من الموحِّدين، واستولى على إفريقيَّةَ، واستبد أبو زكريا بأمر إفريقية ودعا لنفسه، وامتدت دولته بضعًا وعشرين سنة، واشتغل عنه بنو عبد المؤمِنِ بأنفسهم، الذين ضَعُف أمرُ مَلِكِهم في الأندلس والمغرب، وامتَدَّت مملكةُ أبي زكريا الحفصي إلى تلمسان وسجلمامة وسبتة، وبايعه أهلُ إشبيلية وشاطبة والمرية ومالقة وغرناطة، وخلف مالًا جمًّا، فبويع بعده ابنُه محمد المستنصر، وأبو زكريا هذا هو أوَّلُ من ملك تونس من الملوك الحفصيِّينَ، وأما من كان قبله منهم فإنما كانوا عُمَّالًا لبني عبد المؤمن. مات أبو زكريا يحيى بمدينة بونة من إفريقية، في آخر جمادى الآخرة، عن تسعٍ وأربعين سنة."},{"id":2592,"title":"ضم الملك الصالح أيوب  صاحب مصر الكرك لحكمه .","date":["العام الهجري :647","الشهر القمري : جمادى الآخرة","العام الميلادي :1249"],"text":"إن الناصر داودَ صاحب الكرك لما ضاقت به الأمورُ استخلف ابنَه الملكَ المعظم شرفَ الدين عيسى، وأخذ معه جواهِرَه، وسار في البر إلى حَلَب مستجيرًا بالملك الناصرِ يوسف بن الملك العزيز فأنزله وأكرَمَه وسيَّرَ النَّاصِرَ بجواهره إلى الخليفةِ المستعصم بالله؛ لتكون عنده وديعة، فقبض الخليفةُ ذلك، وسير إليه الخطَّ بقبضه وأراد الناصرُ بذلك أن يكون الجوهَرُ في مأمن، فإذا احتاج إليه طلَبَه، وكانت قيمتُه ما ينيِّف على مائة ألف دينار، فحنق ولدا الناصرِ وهما الملك الظاهر شادي والملك الأمجد حسن على أبيهما، لكونِه قَدَّمَ عليهما المعظَّم، وقبضا على المعظَّم، واستوليا على الكرك وأقام الملكُ الظاهر شادي-  وهو أسنُّ إخوتِه- بالكرك وسار الملك الأمجدُ حَسَن إلى الملك الصالح نجم الدين، فوصل إلى العسكرِ بالمنصورة، يوم السبت لتسعٍ مَضَين من جمادى الآخرة، وبَشَّره بأنه هو وأخوه الظاهر أخذا الكرك له، فأكرمه السلطانُ، وأعطاه مالًا كثيرًا، وسيَّرَ الطواشي بدر الدين الصوابي إلى الكرك نائبًا بها وبالشوبك، فتسَلَّمَها بدر الدين، وسيَّرَ أولاد الناصر داود جميعهم، وأخويه الملك القاهر عبد الملك، والملك المغيث عبد العزيز، ونساءهم وعيالاتهم كُلَّها، إلى المعسكر بالمنصورة، فأقطعهم السلطانُ إقطاعًا جليلًا، ورتَّب لهم الرواتَب، وأنزل أولادَ الناصر في الجانب الغربيِّ قُبالة المنصورة، وكان استيلاءُ نائب السلطان على الكرك يوم الاثنين، لاثنتي عشرة بَقِيَت من جمادى الآخرة، وسُرَّ السلطان بأخذ الكرك سرورًا عظيمًا، وأمَرَ فزينت القاهرة ومصر، وضُرِبَت البشائر بالقلعتين، وجهَّزَ السلطان إلى الكرك ألف ألف دينار مصرية، وجواهر وذخائر وأسلحة، وشيئًا كثيرًا مما يعِزُّ عليه."},{"id":2593,"title":"وفاة السلطان الملك الصالح نجم الدين أيوب وتولي ابنه توران شاه .","date":["العام الهجري :647","الشهر القمري : شعبان","العام الميلادي :1249"],"text":"هو السُّلطانُ الملك الصالحُ نجمُ الدين أيوب بن السلطان الملك الكامِل ناصِرِ الدين محمد بن السلطان الملك العادل أبي بكر محمد بن الأمير نجم الدين أيوب بن شاذي. وُلِدَ سنة 603 بالقاهرة، فلمَّا قَدِمَ أبوه دمشقَ في آخر سنة خمس وعشرين استنابه على ديار مصر، فلمَّا رجع انتقَدَ عليه أبوه أحوالًا، ومال عنه إلى ولَدِه الملك العادل الثاني. ولما استولى الكامِلُ على حران، وعلى حِصنِ كيفا وآمد وسنجار سلطَنَه على هذه البلادِ، أرسل الملك الصالح أيوب إليها, فلما توفِّيَ الكامل تملَّك بعده ديارَ مصر ابنُه العادل الثاني أبو بكر، فطَمِعَ الملك الصالح وقَوِيَت نفسُه، وكاتَبَ الأمراء، واستخدم الخوارزميَّة, واستقَرَّت له الأحوال، وسَلَّم له أمراء بني أيوب، وتفرَّغ لجهاد الصليبيين حتى استردَّ بيت المقدسِ منهم مرةً ثانيةً في أيَّامه, وأستكثر من استجلاب المماليك لمساعدتِه في حروبه ضِدَّ الصليبيين. كان السلطان أيوب في دمشق ثمَّ سار عنها في المحرَّم إلى مصرَ بعد أن سَمِعَ بوصول الفرنجِ إلى سواحل مصر من دمياط، وكان قد أصابه المرضُ ولم يقدر السلطاُن على الحركة لمرضه، ونودي في مصر من كان له على السلطانِ أو عنده له شيءٌ، فليحضر ليأخُذَ حَقَّه، فطلع الناسُ وأخذوا ما كان لهم، ثم لما كان ليلة الاثنين نصف شعبان مات السلطان الملك الصالح بالمنصورة، وهو في مقابلةِ الفرنج، عن أربع وأربعين سنة، بعدما عهد لولده الملك المعظَّم توران شاه، وكانت مُدَّة ملكه بمصر عشر سنين إلا خمسين يومًا، فغسَّلَه أحد الحكماء الذين تولوا علاجه، لكي يخفى موتَه، وحُمِلَ في تابوت إلى قلعة الروضة، وأخفى موتَه، فلم يشتهر إلا في شوَّال بعد وصول ابنه المعظم توران شاه مصر، ثم نُقِلَ بعد ذلك بمدة إلى تربته بجوارِ المدارس الصالحية بالقاهرة، وقد كانت كَتَمَت جاريته أم خليل المدعوَّة شجرةَ الدرِّ مَوتَه، وأظهرت أنَّه مريضٌ لا يُوصَلُ إليه، وبَقِيَت تُعلِمُ عنه بعلامتِه سواء، وأعلمت إلى أعيان الأمراء فأرسلوا إلى ابنه الملك المعظم توران شاه وهو بحصن كيفا فأقدموه إليهم سريعًا، وذلك بإشارةِ أكابر الأمراء منهم فخر الدين بن الشيخ الشيوخ، فلما قَدِمَ عليهم مَلَّكوه عليهم وبايعوه أجمعينَ."},{"id":2594,"title":"قدوم توران شاه بن الملك الصالح أيوب لحكم مصر بعد وفاة أبيه .","date":["العام الهجري :647","الشهر القمري : ذي القعدة","العام الميلادي :1250"],"text":"بعد وفاةِ الملك الصالحِ نجمِ الدين أيوب قَدِمَ ابنُه المعظَّم توران شاه, وكان في حصنِ كيفا، فسار من حصنِ كيفا إلى دمشق، لإحدى عشرةَ ليلةً مضت من شهر رمضان، فنزل عانةً في خمسين فارسًا من أصحابه، يوم الخميس النِّصفَ من شهر رمضان وخرج منها يوم الأحدِ يريد دمشق على طريقِ السماوة في البرية فنَزَل القصيرَ في دهليز ضربه له الأميرُ جمال الدين موسى بن يغمور نائب دمشق يوم الجمعة لليلتين بَقِيَتا من شهر رمضان، ودخل المعظَّم توران شاه من الغد - وهو يوم السبتِ آخره - إلى دمشقَ، ونزل بقلعتِها، فكان يومًا مشهودًا وأفرَجَ عَمَّن كان بدمشق في حَبسِ أبيه، وأتته الرسلُ مِن حَماة وحَلَب تهنئه بالقدوم، ولأربع مضينَ من شوال سقطت البطائقُ إلى العسكر والقاهرة، بوصول الملك المعظَّم إلى دمشق وسلطته بها فضُرِبَت البشائر بالمعسكر وبالقاهرة، وسار السلطانُ توران شاه من دمشق يوم الأربعاء السابع عشر يريدُ مِصرَ، وقَدِمَ معه القاضي الأسعد شرف الدين هبة الله بن صاعد الفائزي، وكان مقيمًا بدمشقَ عند الأمير جمال الدين، وقَدِمَ معه أيضًا هبة الله بن أبي الزهر بن حشيش الكاتب النصرانيُّ، وقد وعده السلطان بوزارة مصر، فأسلم وتلقَّب بالقاضي مُعين الدين، وعندما تواترت الأخبارُ في القاهرة بقدوم السلطان، خرج قاضي القضاة بدر الدين السنجاري، فلَقِيَه بغزة وقَدِمَ معه وخرج الأميرُ حسام الدين بن أبي علي نائب السلطان إلى الصالحية، فلقيه بها يوم السبت لأربع عشرة ليلة بَقِيَت من ذي القعدة، ونزل السلطان المعظم توران شاه في قصر أبيه، ومنه يومئذٍ أعلن بموتِ الملك الصالحِ نجم الدين أيوب ولم يكنْ أحدٌ قبل هذا اليوم ينطق بموتِه، بل كانت الأمور على حالها، فتسَلَّم السلطان المعظم مملكةَ مصر، ثم إنه رحل من الصالحية ونزل تلبانة، ثم نزل بعدها منزلة ثالثةً، وسار منها إلى المنصورة، وقد تلقَّاه الأمراء المماليك، فنزل في قصرِ أبيه وجَدِّه يوم الخميس لتسعٍ بَقِينَ من ذي القعدة، فأوَّل ما بدأ أن أخذ مماليكَ الأمير فخر الدين بن شيخ الشيوخ الصغار بدون القيمة، ولم يعطِ ورثته شيئًا، وكان ذلك بنحوِ الخمسة عشر ألف دينار، وأخذ يسُبُّ فخر الدين ويقول: أطلق السكَّر والكتان، وأنفِقِ المال وأطلق المحابيسَ إيش ترك لي."},{"id":2595,"title":"وفاة الأمير الفخر يوسف بن شيخ الشيوخ .","date":["العام الهجري :647","الشهر القمري : ذي القعدة","العام الميلادي :1250"],"text":"هو الصاحِبُ الكبير، ملك الأمراءِ، فَخرُ الدين يوسف بن شيخ الشيوخ بن حمويه. مولده: بدمشق، سنة582. كان فاضلًا صدرًا مُعظمًّا عاقِلًا شُجاعًا جَوادًا دَيِّنًا مَهيبًا وقورًا خَليقًا للإمارةِ والملك، كانت الأمراءُ تعَظِّمُه جدًّا، ولو دعاهم إلى مبايعتِه بعد الصالحِ لما اختُلِفَ عليه اثنان، ولكنه كان لا يرى ذلك حمايةً لجانب بني أيوب، غَضِبَ عليه السلطان نجم الدين سنة أربعين وسجنَه ثلاث سنين، وقاسى شدائدَ، ثم أنعم عليه، وولَّاه نيابةَ المملكة، ولما توفي السلطان ندب الأمراء والقادة فخرَ الدين إلى السلطنة، فامتنع، ولو أجاب لتمَّ له. نهض بأعباء الأمر بعدَ وفاة الملك الصالح وأحسَنَ، وأنفق في الجند مائتي ألف دينار، وأبطَلَ بعضَ المكوس، وركب بالشاويشية، وبعث فارس الدين أقطاي  إلى حصنِ كيفا لإحضارِ ولد الملك الصالح, المعظَّم توران شاه، فأقدمه، ولقد هم توران شاه بإمساكِه لَمَّا بلغه مِن تمكُّنِه فصادر مماليكَه وبعضَ أملاكه. خرج فخر الدين لقتال الفرنجِ وزَحفهم على الجيش، فتقهقر الجيشُ وانهزموا، فقتَلَتْه الداوية من الفرنج شهيدًا في ذي القعدة، ثم نَهَبت أمواله وحواصِلَه وخُيوله، وخَرَّبت داره ولم يتركوا شيئًا من الأفعال الشنيعة البَشِعة إلَّا صنعوه به، مع أن الذين تعاطوا ذلك من الأمراء كانوا معظِّمينَ له غايةَ التعظيم. وحُمِل فدفن بالقاهرة."},{"id":2596,"title":"الحملة الصليبية السابعة بقيادة ملك فرنسا وهزيمتهم في المنصورة .","date":["العام الهجري :648","الشهر القمري : محرم","العام الميلادي :1250"],"text":"كان لسقوط بيت المقدس في أيدي المسلمين سنة642 هـ (1244م) صدى كبير في أوروبا فأخذت أوروبا تجَهِّزُ لحملة صليبيةٍ جديدةٍ كبيرةٍ هي الحملةُ الصليبية السابعة للاستيلاءِ على مصر, حيثُ إنهم أدركوا بعد هزيمةِ حَملتِهم الصليبية الخامسةِ على مصر، ثم هزيمتهم في معركة الحربيَّة عند غزة، وضياع بيت المقدس منهم، أنَّ مِصرَ هي التي تمثل مركزَ قُوَّة المسلمين وقلعة التصدِّي لطموحاتِهم في الاستيلاءِ على بيتِ المقدسِ والشَّرق, وكان لويس التاسع ملك فرنسا الذي عُرِفَ لاحقًا بالقديس لويس، من أشد المتحمِّسين لقيام تلك الحملة، فراح يروِّجُ لها في أنحاء أوروبا. خرج لويس التاسع قاصدًا الديار المصرية في جموعٍ عظيمة فسار عن بلاده بأموالٍ جزيلة وأُهبة عظيمة، وأرسى بعكَّا وانبثَّ أصحابُه في جميع بلاد الساحل. فلمَّا استراحوا جاؤوه حاشدينَ حافلين وساروا في البحرِ إلى دمياط ومَلَكوها بغيرِ تَعَب ولا قتالٍ؛ لأنَّ أهلَها لَمَّا بلَغَهم ما الفرنجُ عليه من القوة والكثرة والعُدَّة الكاملة هالهم أمرُهم فرحلوا عنها مخفِّين. فوصل إليها الفرنجُ ولَقُوها خالية عن المقاتلين مليئةً بالأرزاق والسِّلاح، فدخلوها وغَنِموا ما فيها من الأموال. وكان الملكُ الصالح أيوب بن الملك الكامل صاحبُ مصر يومئذ بالشَّامِ يحاصر مدينة حمص. فلمَّا سَمِعَ بمقدم الفرنج رحل عن حمصَ وسار مسرعًا إلى الديار المصرية ومرض في الطريقِ وعند وصوله إلى المنصورة وافاه مقدَّمو دمياط الذين أخلوها منهزمين، فلما قيل له ما صنعوا لأنَّهم فرُّوا عنها من غير أن يباشروا حربًا وقتالًا، عظم ذلك عليه فأمر بصَلبِهم وكانوا أربعة وخمسين أميرًا فصُلِبوا كما هم بثيابِهم ومناطِقِهم وخفافِهم. ثم مات من الغدِ في الخامس عشر من شعبان. وتولَّى تدبير المملكة الأمير عزُّ الدين المعروف بالتركمانيِّ، وهو أكبر المماليك الترك. وكان مرجعه في جميع ذلك ممَّا يعتمده من الأمور إلى حظيَّة الملك الصالح أيوب المسمَّاة شجرة الدرِ،ّ وكانت تركية داهيةَ الدَّهرِ لا نظير لها في النساءِ حُسنًا، وفي الرجال حزمًا. فاتفقا على تمليك الملك المعظم توران شاه بن الملك الصالح. وكان يومئذٍ بحِصن كيفا من ديارِ بكر, فسار إلى الدِّيار المصريَّة وبايعوه وحَلَفوا له وسَلَّموا إليه مُلكَ أبيه. وفي مطلع سنة 648 سيَّرَ لويس التاسع ألفي فارس نحو المنصورة ليجسَّ بهم ما عليه المصريون من القوَّة. فلَقِيَهم طرفٌ مِن عسكر المسلمينَ فاقتتلوا قتالًا ضعيفًا فانهزم المسلمون بين أيديهم فدخل الفرنجُ المنصورةَ ولم ينالوا منها نيلًا طائلًا؛ لأنهم حَصلوا في مضايق أزقَّتِها وكان العامَّةُ يقاتلونهم بالحِجارة والآجُرِّ والتراب وخيولهم الضَّخمة لم تتمكَّن من الجولان بين الدُّروبِ، وكان القائد لعسكر المسلمين فخر الدين عثمان المعروف بابن شيخ الشيوخ أحد الأمراء المصريين شيخًا كبيرًا، أحاط به الفرنجُ وهو في الحمام يصبغُ لحيَتَه فقتلوه هناك. وعادوا إلى لويس التاسع وأعلموه بما تمَّ لهم مع ذلك العسكر وبالمدينة. فزاد طمعه وطمَعُ من معه من البطارقة ظانِّينَ أنه إذا كان الالتقاء خارج الجدران بالصحراء لم يكن للمسلمين عليهم مقدرة. فعبَّى جيوشه وسار بهم طالبًا احتلال أرض مصر. فصبر المصريون إلى أن عبر الفرنج الخليجَ مِن النيل المسمى أشموم طناح وهو بين البرَّين: برِّ دمياط وبرِّ المنصورة. في ليلة الأربعاء الثالث من محرم رحل الفرنج بأسرِهم من منزلتهم وانحدرت مراكِبُهم في البحر قبالةَ المسلمين، فركب المسلمونَ أقفيَتَهم، بعد أن عَدَّوا برَّهم واتبعوهم، فطلع صباحُ نهار يوم الأربعاء وقد أحاط بهم المسلمون، وبَلَوا فيهم سيوفَهم، واستولوا عليهم قتلًا وأسرًا، وكان معظمُ الحرب في فارسكور، فبلغت عدة القتلى عشرةَ آلاف في قَولِ المقِلِّ، وثلاثين ألفًا في قولِ المكثر، وأُسِرَ من خيَّالة الفرنج ورجالتهم المقاتلة، وصناعهم وسُوقتِهم، ما يناهِزُ مائة ألف إنسان، وغَنِمَ المسلمون من الخيل والبغال والأموال ما لا يحصى كثرةً، واستُشهِدَ من المسلمين نحو مائة رجل، وأبلت الطائفةُ البحرية لاسيما بيبرس البندقداري في هذه النوبة بلاءً حسنًا، وبان لهم أثرٌ جميل، والتجأ الملك الفرنسيُّ وعِدَّة من أكابر قومه إلى تل المنية، وطلبوا الأمانَ فأمَّنهم الطواشي جمال الدين محسن الصالحي، ونزَلوا على أمانه، وأُخِذوا إلى المنصورة، فقُيِّد الملك الفرنسي بقيدٍ مِن حديدٍ واعتُقِلَ في دار القاضي فخر الدين إبراهيم بن لقمان كاتبِ الإنشاء، التي كان ينزل بها من المنصورةِ ووكَلَ بحفظه الطواشي صبيح المعظمي، واعتُقِلَ معه أخوه، وأجرى عليه راتبًا في كل يوم، وتقَدَّم أمر الملك المعظم توران شاه لسيف الدين يوسف بن الطودي أحد من وصل معه من بلاد الشرق بقَتلِ الأسرى من الفرنج، وكان سيفُ الدين يُخرِجُ كُلَّ ليلة منهم ما بين الثلاثمائة والأربعمائة ويَضرِبُ أعناقَهم ويرميهم في البحر، حتى فَنُوا بأجمعهم، ورحل السلطانُ من المنصورة، ونزل بفارسكور وضرب بها الدهليزَ السلطاني، وعَمِلَ فيه برجًا من خَشَبٍ."},{"id":2597,"title":"اغتيال المماليك الملك المعظم توران شاه ونهاية الدولة الأيوبية .","date":["العام الهجري :648","الشهر القمري : محرم","العام الميلادي :1250"],"text":"هو السُّلطانُ الملك المعظم، غياث الدين توران شاه بن السلطان الملك الصالح أيوب بنِ الكامل بن العادل. وُلِدَ بمصر، وعَمِل نيابة أبيه، ثم تملك بحِصن كيفا وآمد، وكان أبوه لا يُعجِبُه هَوَجُه ولا طَيشُه، وكان السلطانُ يقول: توران شاه ما يَصلُحُ للمُلك, ولما مات أبوه سار لإحضارِه لمصر الأميرُ فارس أقطاي، فاتفَقَت كسرة الفرنج عند وصولِه مصر، فتيمَّنَ الناس به، فبدا منه حركاتٌ مُنَفِّرة، ووجدوه خفيفَ العَقلِ، سَيِّئَ التدبير، وكان الأمراء قد تطَلَّعوا إلى أن يُنفِقَ فيهم كما فعل بدمشق، فما أعطاهم شيئًا، ومتى سَكِرَ ضرب الشموعَ بالسَّيفِ، ويقول: هكذا أفعَلُ بمماليك أبي, ويتهَدَّدُ الأمراءَ بالقتل، فتنَكَّروا له، واحتجب عن أمورِ الناس، وانهمك في الفسادِ بالغِلمان، وما كان أبوه كذلك, وقَدَّم الأرذالَ، ووعَدَ فارِسَ الدين أقطاي بالإمرة، فما أمَّرَه، فنَفِرَت قلوبُ المماليك البحرية منه، واتفقوا على قتله، وما هو إلا أن مَدَّ السماط بعد نزوله بفارسكور، في يوم الاثنينِ سادس عشر المحرم، وجلس السلطان على عادته، فتقَدَّم إليه واحدٌ مِن البحرية وهو بيبرس البندقداري، وضربه بالسَّيفِ فتلقاه المعظم بيَدِه فبانت أصابعُه، والتجأ إلى البرج الخَشَب الذي نُصِبَ له بفارسكور وهو يَصيحُ مَن جرحني، قالوا: الحشيشة- يعني الإسماعيلية- فقال: لا والله إلا البحرية! واللهِ لا أبقيتُ منهم بقيَّة، واستدعى المزين ليداويَ يَدَه، فقال البحريَّة بعضهم لبعض: تَمِّموه وإلا أبادكم، فدخلوا عليه بالسيوفِ، ففَرَّ المعظَّم إلى أعلى البرج وأغلق بابه، والدَّمُ يسيل من يده، فأضرموا النَّارَ في البرج، ورَمَوه بالنشاب فألقى نَفسَه من البرج، وتعلق بأذيالِ فارس الدين أقطاي، واستجار به فلم يُجِرْه، وفَرَّ المعظم هاربًا إلى البحر، وهو يقول: ما أريد مُلكًا، دعوني أرجِعُ إلى الحصن يا مسلمين، ما فيكم من يجيرني؟ هذا وجميعُ العسكر واقفون، فلم يجِبْه أحدٌ والنشَّاب يأخذه من كل ناحية، وسَبَحوا خلفه في الماء، وقطَّعوه بالسيوفِ قِطَعًا، حتى مات جريحًا حريقًا غريقًا، وفَرَّ أصحابه واختفوا، وتُرِكَ توران شاه على جانب البحرِ ثلاثة أيامٍ منتفخًا، لا يقدِرُ أحد أن يتجاسَرَ على دفنه، إلى أن شَفَع فيه رسولُ الخليفة، فحُمِلَ ودُفِنَ، وكانت مُدَّة ملكه أحدًا وسبعين يومًا، وكان المباشرُ لقتله أربعةٌ من مماليك أبيه، وكان اغتيالُه هو نهايةَ الدولة الأيوبيَّة في مصر."},{"id":2598,"title":"تنصيب شجرة الدر ملكة على مصر  .","date":["العام الهجري :648","الشهر القمري : صفر","العام الميلادي :1250"],"text":"هي المَلِكةُ عِصمةُ الدين أمُّ خليل شَجَرةُ الدر كانت تركيةَ الجنس، وقيل بل أرمنيَّة، اشتراها الملِكُ الصالح نجم الدين أيوب، وحَظِيَت عنده بحيث كان لا يفارِقُها سفرًا ولا حضرًا، هي أوَّلُ مَن ملك مصر من ملوكِ الترك المماليكِ، وذلك أنَّه لما قُتِلَ الملك المعظم غياث الدين توران شاه بن الملك الصالح نجم الدين أيوب، اجتمع الأمراءُ المماليك البحرية، وأعيانُ الدولة وأهل المشورة، بالدهليز السلطاني، واتفقوا على إقامةِ شَجرةِ الدر أمِّ خليل زوجةِ الملك الصالح نجم الدين أيوب، في مملكةِ مِصرَ، وأن تكونَ العلاماتُ السلطانيَّة على التواقيعِ تَبرُز مِن قِبَلِها، وأن يكون مُقَدَّم العسكر الأميرَ عِزَّ الدين أيبك التركماني الصالحيَّ أحدَ البحرية، وحَلَفوا على ذلك في عاشر صفر، وخرج عزُّ الدين التركماني من المعسكَرِ إلى قلعة الجبل، وأنهى إلى شَجرةِ الدر ما جرى من الاتفاقِ، فأعجَبَها، وصارت الأمورُ كُلُّها معقودةً بها، والتواقيعُ تبرز من قلعة الجبل، وعلامتُها عليها والدةُ خليل، وخُطِبَ لها على منابِرِ مصر والقاهرة، ونُقِشَ اسمها على السكة، ومثالُه المستعصمة الصالحيَّة، ملكةُ المسلمين، والِدةُ الملك المنصورِ خليلٍ أمير المؤمنين، وكان الخطباءُ يقولون في الدعاء: اللهمَّ أدِمْ سلطان السِّترِ الرفيع، والحِجابِ المنيع، مَلِكة المسلمين، والِدَة الملك الخليل، وبَعضُهم كان يقول بعد الدعاء للخليفة: واحفَظِ اللهم الجُبَّةَ الصالحيَّة، ملكةَ المسلمين، عِصمةَ الدنيا والدين، أمَّ خليل المستعصميَّة صاحبة الملك الصالحِ."},{"id":2599,"title":"المصريون يطلقون سراح ملك فرنسا لويس التاسع مقابل فدية كبيرة .","date":["العام الهجري :648","الشهر القمري : صفر","العام الميلادي :1250"],"text":"لما حلف الأمراء والأجناد واستقرت القاعدة على تملُّك شجرة الدر، نَدَب الأميرُ حسام الدين محمد بن أبي علي للكلامِ مع الملك لويس التاسع في تسليمِ دمياط، فجرى بينه وبين الملك مفاوضاتٌ ومحاورات ومراجعات، آلت إلى أن وقع الاتفاقُ على تسليمها من الفرنجِ، وأن يخلى عنه ليذهَبَ إلى بلاده، بعدما يؤدِّي نصفَ ما عليه من المالِ المقَرَّر، فبعث الملك الفرنسي إلى من بها من الفرنجِ يأمُرُهم بتسليمِها، فأبوا وعاوَدَهم مرارًا، إلى أن دخل العَلَمُ الإسلاميُّ إليها، في يوم الجمعة لثلاث مضينَ مِن صفر، ورفع على السُّورِ وأُعلِنَ بكلمة الإسلام وشهادةِ الحَقِّ، فكانت مدةُ استيلاء الفرنج عليها أحد عشر شَهرًا وتسعة أيام، وأُفرِجَ عن الملك لويس التاسع، بعدما فدى نفسَه بأربعمائة ألف دينار، وأفرج عن أخيه وزوجته ومن بقي من أصحابِه، وسائر الأسرى الذين بمصر والقاهرة، ممَّن أُسِرَ في هذه الواقعة، ومن أيام العادل والكامِلِ والصالح وكانت عِدَّتُهم اثني عشر ألف أسير ومائة أسير وعشر أسارى، وساروا إلى البر الغربي، ثم ركبوا البحرَ في يوم السبت تاليه، وأقلَعوا إلى جهة عكَّا."},{"id":2600,"title":"استيلاء الملك الناصر صاحب حلب على دمشق .","date":["العام الهجري :648","الشهر القمري : ربيع الآخر","العام الميلادي :1250"],"text":"كتب الأمراءُ القيمريَّة مِن دمشق إلى المَلِك النَّاصِر صلاح الدين يوسُف بن العزيز محمَّد بن الظاهر غازي بن السُّلطان صلاح الدين يوسُف بن أيوب صاحِب حلب، يحذرونَه بامتناعِهم من الحَلِف لشَجرةِ الدُّرِّ، ويحثُّونَه على المسيرِ إليهم حتى يملِكَ دمشق، فخرج من حَلَب في عساكِرِه مُستهَلَّ شَهرَ ربيع الآخر، ووصل إلى دمشقَ يوم السبت ثامِنَه، ونازلها إلى أن كان يومُ الاثنين عاشِرَه زحف عليها، ففتح الأمراءُ القيمرية له أبواب البلد وكان القائمُ بذلك من القيمريَّة الأمير ناصر الدين أبو المعالي حسين بن عزيز بن أبي الفوارس القيمري الكردي، فدخلها الناصرُ صلاح الدين هو وأصحابه بغير قتالٍ، وخلع على الأمراءِ القيمرية، وعلى الأميرِ جمال الدين بن يغمور، وقبَضَ على عِدَّة من الأمراء المماليك الصالحيَّة وسجَنَهم، ومَلَك الناصر صلاح الدين قلعةَ دمشق، وكان بها مجاهدُ الدين إبراهيم أخو زين الدين أمير جندار، فسَلَّمها إلى الناصر، وبها من المالِ مائة ألف دينار وأربعمائة ألف درهم سوى الأثاث، ففرق الناصِرُ جميعَ ذلك على الملوك والأمراء، وتسَلَّموا ما حولها كبعلبك وبُصرى والصلت وصرخد، وامتنعت عليهم الكرك والشوبك بالملك المغيثِ عمر بن العادل بن الكامل، كان قد تغلب عليهما في هذه الفتنة حين قُتِلَ المعظم توران شاه، فطلبه المصريون ليُمَلِّكوه عليهم فخاف مما حَلَّ بابنَي عَمِّه، فلم يذهب إليهم ولما استقَرَّت يد الحلبيين على دمشق وما حولها جلس الناصِرُ في القلعة وطَيَّب قلوب الناس، ثم ركبوا إلى غزة ليتسَلَّموا الديار المصرية، فبرز إليهم الجيشُ المصري فاقتتلوا معهم أشَدَّ القتال، فكُسر المصريونَ أوَّلًا بحيث إنه خُطِبَ للناصر في ذلك بها، ثم كانت الدائرة على الشاميِّين فانهزموا وأسروا من أعيانهم خلقًا كثيرًا، وعَدِمَ من الجيش الصالح إسماعيل."},{"id":2601,"title":"عز الدين أيبك يملك مصر بعد بني أيوب ويتزوج شجرة الدر .","date":["العام الهجري :648","الشهر القمري : جمادى الأولى","العام الميلادي :1250"],"text":"عِزُّ الدين أيبك الجاشنكير التركماني الصالحي تركي الأصلِ والجنس، انتقل إلى مِلكِ السلطان المَلِك الصالحِ نجم ِالدين أيوب من بعض أولاد التركماني، فعُرِفَ بين المماليك البحريَّة بأيبك التركماني، وترقى عنده في الخَدَم، حتى صار أحدَ الأمراء الصالحية، وعَمَلُه جاشنكيرا - متذوّق الطعام السُّلطان- وهو من أخَصِّ موظفي القصر السلطاني إلى أن مات الملك الصالح، وبعد قَتْلِ ابنه توران شاه توَلَّت شجرة الدر السلطنة ومعها عزُّ الدين أيبك، ولما وصل الخبَرُ بذلك بغداد، بعث الخليفةُ المستعصم بالله من بغداد كتابًا إلى مصر، وهو ينكِرُ على الأمراء ويقولُ لهم: إن كانت الرجالُ قد عَدِمَت عندكم، فأعلِمونا حتى نسَيِّرَ إليكم رجلًا، واتفق ورودُ الخبر باستيلاء الملك الناصِرِ على دمشق، فاجتمع الأمراءُ والبحريَّة للمشورة، واتَّفَقوا على إقامة الأمير عزِّ الدين أيبك مُقَدَّم العسكر في السلطنة، ولَقَّبوه بالملك المعز وكان مشهورًا بينهم بدينٍ وكَرَمٍ وجَودةِ رأي، فأركبوه في يومِ السبت آخر شهر ربيع الآخر، وحمل الأمراءُ بين يديه الغاشية –غطاءً للسرج من جلد مخروز بالذهب يُحمَل أمام السلطان- نوبًا واحدًا بعد آخَرَ إلى قلعة الجبل، وجلَسُوا معه على السماط، ونودي بالزينةِ فزُيِّنَت القاهرة ومصر، فورد الخبَرُ في يوم الأحد تاليه تسليم الملك المغيث عمر الكرك والشوبك، وبتسلُّم الملك السعيد قلعة الصبيبة، فلما كان بعد ذلك تجمَّع الأمراء، وقالوا: لا بد من إقامة شخصٍ مِن بيت الملك مع المعِزِّ أيبك ليجتَمِعَ الكل على طاعتِه ويطيعه الملوكُ مِن أهله، فاتفقوا على إقامة المَلِك شرف مظفر الدين موسى بن الملك المسعودِ- ويقال له الناصر صلاح الدين- يوسف بن الملك المسعود يوسف - المعروف باسم القسيس - بن الكامل محمد بن العادل أبي بكر بن أيوب، وله من العمر نحو ستُّ سنين، شريكًا للمَلِك المعز أيبك، وأن يقوم المَلِك المعز بتدير الدولة، فأقاموه سلطانًا في ثالث جمادى الأولى، وجلس على السماط وحضر الأمراء، فكانت المراسيمُ والمناشير تخرج عن الملكين الأشرف والمعز، إلا أن الأشرف ليس له سوى الاسم في الشركة لا غير ذلك، وجميعُ الأمور بيد المعز أيبك، فلما ورد الخبَرُ بذلك نودي في القاهرة ومصر أن البلادَ للخليفةِ المستعصم بالله العباسي، وأن المَلِكَ المعز عز الدين أيبك نائبُه بها، وذلك في يوم الأحد سادسه، ووقع الحثُّ في يوم الاثنين على خروج العساكِر، وجُدِّدَت الأيمان للمَلِك الأشرف موسى والملك المعز أيبك، وأن يبرز اسمُهما على التواقيع والمراسيم، ويُنقَش اسمُهما على السكة، ويُخطَب لهما على المنابر، وكانت شجرةُ الدر قد تزوجت الأمير عز الدين أيبك، في تاسع عشر شهر ربيع الآخر، وخَلَعَت شجرة الدر نفسَها من مملكة مصرَ، ونزلت له عن المُلْك، فكانت مُدَّة دولتِها ثمانين يومًا."},{"id":2602,"title":"مسير الناصر للاستيلاء على مصر بعدما ملك دمشق .","date":["العام الهجري :648","الشهر القمري : رمضان","العام الميلادي :1250"],"text":"أخذ الملك الناصر صاحِبُ الشام في الحَرَكةِ لأخذ مصر، بتحريضِ الأمير شمس الدين لؤلؤ الأرمني له على ذلك، فخرج الناصرُ من دمشق بعساكِرِه، يوم الأحد النصفَ من شهر رمضان، ومعه الملك الصالح عماد الدين إسماعيل بن العادل أبي بكر بن أيوب ثم برز الأميرُ حسام الدين أبو علي من القاهرة، وكان الوقتُ شِتاءً، وفي تاسع شوال برز الأميرُ فارس الدين أقطاي الجمدار - مقَدَّم البحرية - في جمهورِ العسكر من الترك، وسارت العساكِرُ في الحادي عشر، واجتمعت بالصالحيَّة، ثم في الثالث من ذي القعدة نزل الملِكُ المعز من قلعةِ الجبل فيمن بَقِيَ عنده من العساكرِ، وسار إلى الصالحيَّة، وبها العساكر التي خرجت قَبلَه، وترك بقلعةِ الجبل الملِكَ الأشرف موسى فاستقَرَّت عساكرُ مصر بالصالحيَّة إلى يوم الاثنينِ سابِعَه، فوصل الملكُ الناصر بعساكره إلى كراع وهي قريبة من العباسيَّة، فتقارب ما بين العسكرين وكان في ظَنِّ كل أحد أن النصرةَ إنما تكون للمَلِك الناصر على البحريَّة، لكثرة عساكِرِه ولمَيلِ أكثر عسكرِ مِصرَ إليه، فاتَّفَق أنَّه كان مع الناصر جمعٌ غفير من ممالك أبيه الملك العزيز، وهم أتراكٌ يميلون إلى البحريَّة لعِلَّة الجنسيَّة، ولكراهتهم في الأمير شمس الدين لؤلؤ مديرِ المملكة، فعندما نزل الناصِرُ بمنزلة الكراع، قريبًا من الخشبي بالرمل، رحل المعزُّ أيبك بعساكِرِ مِصرَ مِن الصالحية، ونزل اتجاهَه بسموط إلى يومِ الخميس عاشره، فركب الملكُ الناصر في العساكر، ورتَّبَ مَيمنةَ وميسرةَ وقلب جيشه، ورَكِبَ المعز، ورتَّب أيضًا عساكِرَه، وكانت الوقعةُ في الساعة الرابعة، فاتفق فيها أن الكَرَّة كانت أولًا على عساكر مصر، ثم صارت على الشاميين، وذلك أن ميمنة عسكر الشام حمَلَت هي والميسرة على مَن بإزائها حملة شديدة، فانكَسَرت ميسرة المصريين وولَّوا منهزمين، وزحف أبطالُ الشاميين وراءهم، وما لهم عِلمٌ بما جرى خلفَهم، وانكسرت ميمنةُ أهل الشام، وثبت كلُّ من القلبين واقتَتَلوا، ومر المنهزمون من عسكر مصر إلى بلاد الصعيد، وقد نُهِبَت أثقالهم، وعندما مرُّوا على القاهرة خُطِبَ بها للملك الصالح إسماعيل صاحب دمشق، وخُطِبَ له بقلعة الجبل ومصر، وأما ميمنة أهل الشام فإنها لما كُسِرَت قتَلَ منهم عسكر مصر خلقًا كثيرًا في الرمل، وأسَروا أكثَرَ مما قتلوا، وتعيَّنَ الظَّفَرُ للناصر وهو ثابتٌ في القلب، واتجاهَه المعز أيبك أيضًا في القلبِ، فخاف أمراء الناصر منه أن ينحِّيَهم إذا تم له الأمر، وخامَروا عليه وفَرُّوا بأطلابِهم إلى الملك المعز، فخارت قوى الناصر من ذَهابِ المذكورين إلى الملك المعز، فحمل المعزُّ بمن معه على سناجق-رماح- الناصر، ظنًّا منه أن الناصِرَ تحتها، فحمل المعزُّ عليهم وثبتوا له، ثم انحاز إلى جانبٍ يريد الفرار إلى جهة الشوبك، ووقف الناصرُ في جمع من العزيزية وغيرهم تحت سناجقه وقد اطمأن، فخرج عليهم المعزُّ ومعه فارس الدين أقطاي في ثلاثمائة من البحرية، وقَرُبَ منه فخامر عِدَّةً مِمَّن كان مع الناصر عليه، ومالوا مع المعزِّ والبحرية، فولى الناصِرُ فارًّا يريد الشام في خاصَّتِه وغلمانِه، واستولى البحريَّةُ على سناجقه، وكسروا صناديقَه ونَهَبوا أمواله، فأمر الملكُ بضَربِ عُنُقِ الأمير شمس الدين لؤلؤ، فأخذته السيوفُ حتى قُطِّع، وضُرِبَت عنق الأمير ضياء الدين القيمري وأتيَ بالملك الصالح إسماعيل وهو راكب، فسَلَّمَ عليه الملك المعز وأوقَفَه إلى جانبه، وتمَزَّق أهل الشام كلَّ مُمَزَّق، وأما العسكر الشامي الذي كَسَر ميسرة المصريين، فإنَّه وصل إلى العباسية ونزل بها، وضَرَب الدهليز الناصريَّ هناك، وفيهم الأميرُ جمال الدين بن يغمور نائب السلطنة بدمشق وعِدَّة من أمراء الناصر، وهم لا يشكُّون أنَّ أمر المصريين قد بَطَل وزال، وأنَّ المَلِكَ الناصر مُقدِمٌ عليهم ليسيروا في خدمتِه إلى القاهرة، فبينا هم كذلك إذ وصل إليهم الخبَرُ بهروب الملك الناصر، وقَتْل الأمراء وأسْر الملوك وغيرهم، فهَمَّ طائفة منهم أن يسيروا إلى القاهرة ويستولوا عليها، ومنهم من رأى الرجوعَ إلى الشام، ثمَّ اتَّفَقوا على الرجوعِ."},{"id":2603,"title":"وفاة الملك الصالح إسماعيل بن الملك العادل صاحب دمشق .","date":["العام الهجري :648","الشهر القمري : ذي القعدة","العام الميلادي :1251"],"text":"هو السُّلطانُ الملك الصالح عماد الدين، أبو الخيش إسماعيل بن الملك العادل محمد بن نجم الدين أيوب بن شاذي صاحب دمشق. تمَلَّك بصرى وبعلَبَّك، وتنقَّلَت به الأحوال، واستولى على دمشقَ أعوامًا، فحارَبَه ابنُ أخيه الملك الصالح نجم الدين أيوب صاحب مصر، وجرت له أمورٌ طويلة، ما بين ارتفاعٍ وانخفاضٍ، وكان بطلًا شُجاعًا، مَهيبًا شديدَ البطشِ، مليحَ الشَّكلِ، كان في خدمةِ أخيه الأشرفِ، فلما مات الأشرفُ، توثَّبَ على دمشق، وتملَّكَها، فجاء أخوه المَلِكُ الكامِلُ، وحاصَرَه، وأخذ منه دمشقَ، وردَّه إلى بعلبك, وكان فيه جَورٌ, واستقضى على النَّاسِ الرفيع الجيلي، وتضَرَّرَت الرعيةُ بدمشق أثناء حصارِ الخوارزمية في عَهدِه حتى بِيعَ رِطلُ الخبز بستة دراهم، والجُبن واللحم بنسبة ذلك، وأكلوا الميتةَ، ووقع فيهم وباءٌ شديد. وفي (معجم القوصي) في ترجمة الأشراف: \"فأخوه الصالح إسماعيل نصر الكافرينَ، وسَلَّم إليهم القلاعَ، واستولى على دمشقَ سَرِقةً، وحَنَث في يمينه، وقتَلَ مِن الملوك والأمراء من كان ينفَعُ في الجهاد، وصادَرَ على يد قضاتِه العِبادَ، وخَرَّب الأملاك، وطَوَّل ذيلَ الظُّلم، وقَصَّر ذيل العدل، وظَنَّ أن المُلك له مُستمِرٌّ، فسقَطَ الدهرُ لغفلتِه، وأراه بلايا\", ثم ذهبت منه بعلبك وبُصرى، وتلاشى أمره، فمضى إلى حَلَب، وافدًا على ابنِ أخته، وصار من أمرائه، فلما ساروا ليأخذوا مصر، فغُلب الشاميون، وأُسِرَ جماعة، منهم الملك الصالحُ إسماعيل، في سنة ثمانٍ وأربعين، فسُجِنَ بالقاهرة، ومرُّوا به على تربة السلطان نجم الدين أيوب، فصاحت البحريةُ: يا خوند- سيد أو أمير- أين عينك تنظر إلى عدوِّك؟! وفي آخر ذي القعدة من سنة ثمان أخرجوا الصالحَ ليلًا، ومضوا به إلى الجبَل، فقتلوه، وعُفِيَ أثره. وكانت أمُّه رومية، وكان رئيسَ النَّفسِ نبيلَ القَدرِ، مطاعًا له حُرمة وافرة، وفيه شجاعة."},{"id":2604,"title":"معارضة الأمراء الأيوبيين قيام دولة المماليك .","date":["العام الهجري :649","العام الميلادي :1251"],"text":"اقتتل العسكرُ الأيوبي مع عسكرِ مِصرَ وانهزم عسكرُ الأيوبيِّينَ، ودمشق بيدِ الناصر صلاحِ الدين فعاد المَلِكُ الناصرُ إلى دمشق وقَدِمَت عساكر المصريين فحَكَموا بلاد السواحل حيث استولى الأميرُ فارس الدين أقطاي على الساحِلِ ونابلس إلى نهر الشريعة، فجهَّز لهم الملك الناصِرُ جَيشًا طردهم حتى رَدَّهم إلى الدِّيارِ المصرية، وقَصَرَهم إلى حَدِّ نهر الشريعة، وسَيَّرَ الملكُ الناصرُ عَسكرًا من دمشقَ إلى غزة ليكونَ بها، فأقاموا على تلِّ العجول، فخرَجَ المعزُّ عز الدين أيبك، ومعه الأشرفُ موسى والفارس أقطاي وسائر البحرية، ونزل بالصالحيَّة، فأقام العسكرُ المصري بأرض السانح قريبًا من العبَّاسة، والعسكر الشامي قريبًا من سنتينِ، وتردَّدَت بينهما الرسُلُ."},{"id":2605,"title":"المغول يقررون غزو بلاد الإسلام ويختارون هولاكو لهذه المهمة .","date":["العام الهجري :650","العام الميلادي :1252"],"text":"قام أمراء المغول ورؤساؤهم بالاجتماعِ برئاسةِ الخاقان الأكبر منكو في جمعيةٍ عامَّةٍ تُدعى قوريلتاري فقرروا فيها القيامَ ببَعثةٍ حربية بقيادة هولاكو مهمتها غزو الدولِ الإسلاميَّة مبتدئين قبل ذلك ببلاد الإسماعيليَّة من ألموت وغيرها."},{"id":2606,"title":"تحرك المغول باتجاه الولايات الإسلامية .","date":["العام الهجري :650","العام الميلادي :1252"],"text":"وصل التتارُ إلى الجزيرة وسروج ورأس العينِ وما والى هذه البلادَ، فقتلوا وسَبَوا ونهبوا وخَرَّبوا ووَقَعوا بسنجار يسيرونَ بين حران ورأس العين، وكان عِدَّة من قتلوا من أهل الجزيرة نحًوا من عشرة آلاف قتيل، وأسروا من الولدان والنساء ما يقارب ذلك، وسيَّرَ منكوخان ملك التتر أخاه هولاكو لأخذ العراق فسار وأباد أهلَ بلاد الإسماعيلية قتلًا ونهبًا، وأسرًا وسبيًا، ووصَلَت غاراته إلى ديار بكرٍ وميافارقين، وصادفوا قافلةً سارت من حران تريد بغداد، فأخذوا منها أموالًا عظيمة، من جملتها ستُّمائة حمل سكر من عمل مصر، وستمائة ألف دينار."},{"id":2607,"title":"الحرب بين المماليك وأمراء الدول الأيوبية .","date":["العام الهجري :650","العام الميلادي :1252"],"text":"تمكَّن السلطان المملوكي عز الدين أيبك من احتلالِ غَزَّة، ودخلت هذ السَّنةُ وهم على نفسِ الأمر من التنافر والاقتتال، وقد التقى الفريقانِ في العباسيَّة على الطريق إلى القاهرة، ثمَّ إن طائفة من العسكر الشامي انحازوا إلى العسكر المصري، فكانت هزيمةً على العسكرِ الشامي أُسِرَ فيها عددٌ مِن الأمراء الذين حُمِلوا إلى مصر وسُجِنوا في القلعةِ."},{"id":2608,"title":"وفاة اللغوي الإمام، العلامة أبو الفضل الصاغاني .","date":["العام الهجري :650","الشهر القمري : شعبان","العام الميلادي :1252"],"text":"هو الشيخُ الإمامُ العلَّامة المحَدِّث، إمامُ اللغة رضي الدين أبو الفضائل الحسن بن محمد بن الحسن بن حيدر علي المعروف بالصاغاني، القرشي، العدوي، العمري، الصاغاني الأصل، الهندي اللهوري المولد، البغدادي الوفاة، المكي المدفن، الفقيه الحنفي، صاحب التصانيف. أحد أئمَّة اللغة في القرن السابع الهجري, وكان إليه المنتهى في معرفة اللِّسانِ العربي. وُلِدَ في لاهور بالهند في صفر سنة 577, ونشأ بغزنة من بلاد السند وقدم بغداد، ثم ذهب رسولًا من الخليفة إلى ملك الهند أكثر من مرة، ورحل إلى اليمن، وتوفي ودفن في بغداد بدارِه بالحريم الطاهري، وكان قد أوصى أن يُدفَنَ بمكة، فنُقِلَ إليها ودفن بها. له عدة مؤلَّفات لُغوية، من أشهرها: \"العُباب الزاخر\" وهو معجم كبير، و\"التكملة والذيل والصلة\" و\"تاج اللغة\" و\"صحاح العربية\"."},{"id":2609,"title":"الملك الناصر الثاني يستنجد بالملك فردريك الثاني لتسليمه القدس .","date":["العام الهجري :651","العام الميلادي :1253"],"text":"قام الملك الناصرُ صلاح الدين صاحِبُ دمشق بطَلَب العونِ مِن ملك الفرنجِ فريدريك الثاني وهو في عكَّا على أن يُسَلِّمَه القُدسَ مقابِلَ هذه المساعدة ضِدَّ العسكر المصري، ولكِنَّ فريدريك رفض طلبَه ذاك لوجودِ معاهدة بينه وبين المماليكِ تمنعُ مناصرةَ خُصومِهم في الحرب، وقد قال ابن كثير في تاريخه \"إن الجيشَ المصريَّ قد تمالأ أيضًا مع الفرنج على تسليمِهم القدس إن هم نصروهم على الشاميِّين, فالله أعلمُ بحقيقة الحال\"."},{"id":2610,"title":"ثورة الأعراب على حكم المماليك في الصعيد الشرقية .","date":["العام الهجري :651","العام الميلادي :1253"],"text":"ثار العُربان ببلاد الصعيدِ وأرضِ بحري، وقطعوا الطريق برًّا وبحرًا، فامتنع التجَّار وغيرُهم من السفر، وقام الشريفُ حِصنُ الدين ثعلب بن الأمير الكبير نجمِ الدين علي بن الأمير الشريف فخر الدين إسماعيل بن حصن الدولة مجد العرب ثعلب بن يعقوب بن مسلم بن جعفر بن موسى، وقال نحن أصحابُ البلاد، ومنع الأجنادَ مِن الخراج، وصَرَّح هو وأصحابُه بأنَّا أحَقُّ بالمُلكِ مِن المماليك، وقد كفى أنَّا خَدَمْنا بني أيوب، وهم خوارِجُ خرجوا على البلاد، وأنِفُوا من خدمةِ التركِ، وقالوا إنما هم عَبيدٌ للخوارِجِ، وكتبوا إلى الملك الناصِرِ صاحب دمشق يستحثُّونه على القدوم إلى مِصرَ، واجتمع العَرَبُ- وهم يومئذٍ في كثرة من المالِ والخيل والرجال- إلى الأمير حصنِ الدين ثعلب، وهو بناحيةِ دهروط صربان، وأتوه من أقصى الصعيدِ، وأطراف بلاد البحيرة والجيزة والفيوم، وحَلَفوا له كلُّهم، فبلغ عِدَّةُ الفرسان اثني عشر ألف فارس، وتجاوزت عدَّةُ الرجَّالة الإحصاء لكثرتهم، فجهَّزَ إليهم الملك المعز أيبك الأميرَ فارس الدين أقطاي المستعرب، في خمسةِ آلاف فارس، فساروا إلى ناحيةِ ذروة، وبرَزَ إليهم الأميرُ حصن الدين ثعلب، فاقتتل الفريقانِ مِن بكرة النهار إلى الظهر، فقَدَّرَ الله أنَّ الأمير حصن الدين تقنطَرَ عن فرسه، فأحاط به أصحابُه وأتت الأتراكُ إليه، فقُتِلَ حَولَه من العرب والعبيدِ أربعُمائة رجل، حتى أركبوه، فوجَدَ العرَبَ قد تفرَّقوا عنه، فولى منهزمًا، وركب التركُ أدبارهم، يقتُلونَ ويأسِرونَ حتى حال بينهم الليلُ، فحووا من الأسلابِ والنِّسوانِ والأولاد والخيول والجمال والمواشي ما عَجَزوا عن ضبطه، وعادوا إلى المخيَّم ببلبيس، ثم عَدَوا إلى عرب الغربية والمنوفية من قبيلتي سنبس ولواتة، وقد تجمَّعوا بناحية سخا وسنهور، فأوقعوا بهم وسَبَوا حريمَهم وقتلوا الرجال، وتبدَّدَ كل عرب مصر وخَمَدَت جمرتُهم من حينئذ، ولحِقَ الشريف حصنُ الدين مَن بَقِيَ مِن أصحابه، وبعث يطلبُ مِن الملك المعز الأمان، فأمَّنَه ووعده بإقطاعاتٍ له ولأصحابه، ليصيروا من جملةِ العسكرِ وعونًا له على أعدائه، فانخدع الشريفُ حصن الدين، وظن أنَّ التركَ لا تستغني عنه في محاربةِ الملك الناصر، وقَدِمَ في أصحابه وهو مطمئِنٌّ إلى بلبيس، فلما قرب من الدهليز نزل عن فرَسِه ليحضُرَ مجلِسَ السلطان، فقُبِضَ عليه وعلى سائِرِ مَن حضر معه، وكانت عِدَّتُهم نحوَ ألفَي فارس وستمائة راجل، وأمر الملك المعِزُّ فنُصِبَت الأخشابُ مِن بلبيس إلى القاهرة وشُنِقَ الجميع، وبَعَث بالشريفِ حِصن الدين إلى ثغرِ الإسكندرية، فحُبِسَ بها وسُلِّمَ لواليها الأمير شمس الدين محمد بن باخل، وأمر المعِزُّ بزيادة القطعية على العَرَب، وبزيادة القَوَد المأخوذ منهم، ومعاملتهم بالعُنفِ والقَهرِ، فذَلُّوا وقَلُّوا."},{"id":2611,"title":"الخليفة العباسي يتوسط في الصلح بين المماليك والأيوبيين .","date":["العام الهجري :651","الشهر القمري : صفر","العام الميلادي :1253"],"text":"قام الخليفةُ العباسيُّ المستعصم بالتوسُّط بين الأيوبيين أصحابِ الشَّامِ وبين المماليك أصحابِ مِصرَ لما كان بينهم من الحروب، فأرسل الشيخَ نجم الدين البادرائي للتوسُّط بينهم، الذي حمل رسالةً إلى الطرفين فتقرر الصلحُ بين الملك المعز أيبك وبين الملك الناصر صاحب دمشق، بسفارةِ نجم الدين البادرائي، وقد قَدِم نجمُ الدين إلى القاهرة، وصَحِبَه عز الدين أزدمر، وكاتبُ الإنشاء بحَلَب نظام الدين أبو عبد الله محمد بن المولى الحلبي، لتمهيدِ القواعد، فلم يبرحَا إلى أن انفصَلَت القضية على أن يكون للمصريِّينَ إلى الأردن، وللناصر ما وراء ذلك، وأن يدخُلَ فيها للمصريين غَزَّة والقدس ونابلس والساحلُ كله، وأن المعِزَّ يُطلِقُ جميع مَن أسَرَه من أصحاب الملك الناصر، وحَلَفَ كل منهما على ذلك، وكُتِبَت به العهود، وعاد المَلِكُ المعز وعسكره إلى قلعةِ الجبل في يوم الثلاثاء سابع صفر، ونزل البادرائي بالقاهرة، وأطلق الملك المعزُّ الملك المعظَّم توران شاه بن السلطان صلاح الدين يوسف بن أيوب، وأخاه نُصرة الدين، وسائرَ أولاد الملوك والأمراء، وأحضَرَهم دار الوزارة ليشهَدوا حَلِفَه للملك الناصر."},{"id":2612,"title":"خروج نار من عدن ظنها الناس النار التي تحشر الناس للقيامة .","date":["العام الهجري :652","العام الميلادي :1254"],"text":"وردت أخبارٌ في مكَّةَ شَرَّفَها الله تعالى بأنَّ نارًا ظَهَرَت في أرضِ عَدَن في بعض جبالِها بحيث إنَّه يطير شَرَرُها إلى البحر في الليل، ويصعدُ منها دخانٌ عظيم في أثناء النهار، فما شَكُّوا أنها النارُ التي ذكر النبيُّ صلى الله عليه وسلم أنها تظهرُ في آخِرِ الزمان، فتاب الناسُ وأقلعوا عمَّا كانوا عليه من المظالمِ والفسادِ، وشرعوا في أفعالِ الخير والصَّدَقاتِ."},{"id":2613,"title":"الصلح بين الملك الناصر صاحب دمشق وبين الفرنج .","date":["العام الهجري :652","الشهر القمري : محرم","العام الميلادي :1254"],"text":"وقع الصُّلحُ بين الملك الناصر صاحِبِ دمشق وبين الفرنجِ أصحابِ عكَّا، لمدة عشر سنين وستة أشهر وأربعين يومًا أولُها مُستهَلَّ المحرم، على أن يكونَ للفرنجِ مِن نهر الشريعة مغربًا، وحلف الفريقانِ على ذلك."},{"id":2614,"title":"التنازع على مكة بين الشَّريف راجح بن قتادة والشريف جماز .","date":["العام الهجري :652","الشهر القمري : ربيع الأول","العام الميلادي :1254"],"text":"أخذ الشَّريفُ راجح بن قتادة مكَّةَ من الشريف جماز بن حسن، بغيرِ قتال، ثم أخذها ابنُه غانم بن راجح في ربيعٍ الأول بغير قتالٍ، فقام عليه الشَّريفُ أبو نمي بن أبي سعيد بن علي بن قتادة في شوال ومعه الشريفُ إدريس، وحارباه ومَلَكَا مكة، فقدم في خامس عشر ذي القعدة مبارز الدين الحسين بن علي بن برطاس من اليمن، وقاتَلَهما وغَلَبَهما، وحجَّ بالنَّاسِ."},{"id":2615,"title":"اغتيال الأمير فارس الدين أقطاي الجمدار .","date":["العام الهجري :652","الشهر القمري : شعبان","العام الميلادي :1254"],"text":"هو الأميرُ الكبير فارس الدين التركي، أقطاي بن عبد الله الجمدار- حامل ملابس السلطان- الصالحي، النَّجمي، من كبار مماليك المَلِك الصالح نجم الدين أيوب. كان شجاعًا جَوادًا كريمًا مهابًا، وهابًا. ذكر شمس الدين الجزري في \" تاريخه \": \"أنه كان مملوكًا للزكي إبراهيم الجزري المعروف بالجبيلي، اشتراه بدمشق ورباه، ثم باعه بألف دينار، فلما صار أميرًا وأقطعوه الإسكندرية طَلَبَ من الملك الناصر إطلاقَ أستاذه المذكور، وكان محبوسًا بحمص، فأطلقه وأرسَلَه إليه، فبالغ في إكرامِه، وخلع عليه، وبعثَه إلى الإسكندرية، وأعطاه ألفي دينار. قلت(الذهبي): وكان طائشًا عاملًا على السلطنة، وانضاف إليه البحرية كالرشيدي وركن الدين بيبرس البندقداري الذي صار سلطانًا, وسار مرَّتين إلى الصعيد فظلم وعسَفَ وقتَلَ وتجَبَّرَ، وكان يركَبُ في دست يضاهي دست السَّلطنة ولا يلتفت على المَلِك المعز أيبك ولا يعده، بل يدخل إلى الخزائنِ ويأخُذُ ما أراد. ثمَّ إنه تزوج بابنة صاحب حماة، وبُعِثَت العروس في تجمُّل زائد، فطَلَب فارسُ الدين أقطاي القلعةَ من الملك المعز ليسكُنَ فيها وصَمَّم على ذلك، فقالت أم خليل شجرة الدر لزوجها المعِزِّ: هذا ما يجيءُ منه خير. فتعاملا على قَتلِه\". فلما استفحل أمرُ الأمير الفارس أقطاي الجمدار وانحازت إليه البحريَّة، بحيث إذا ركب أقطاي من دارِه إلى القلعة شَغَل بين يديه جماعةً بأمره، ولا يُنكر هو ذلك منهم فكانوا يأخذون أموالَ الناس ونساءَهم وأولادَهم بأيديهم، فلا يقدِرُ أحدٌ على منعهم، وكانوا يدخُلونَ الحَمَّامات ويأخذون النِّساءَ منها غصبًا، وكَثُرَ ضَرَرُهم كثيرا، هذا والمعِزُّ يحَصِّل الأموال، وقد ثَقُل عليه أقطاي، فواعد طائفةً مِن مماليكه على قَتلِه، وبعث المعِزُّ إليه وقت القائلةِ مِن يوم الأربعاء ثالث شعبان، ليحضُرَ إليه بقلعة الجبل في مشورةٍ يأخذ رأيَه فيها، فركب أقطاي على غيرِ أُهبة ولا اكتراث، فعندما دخل من باب القلعة، وصار في القاعة أُغلِقَ باب القلعة، ومُنِعَ مماليكُه من العبور معه، فخرج عليه جماعةٌ بالدهليز قد أعدوا لقَتلِه وهم قطز وبهادر وسنجر الغنمي، فهبروه بالسُّيوفِ حتى مات، فوقع الصريخُ في القلعة والقاهرة بقَتلِه، فركب في الحالِ مِن أصحابه نحوُ السبعمائة فارس ووقفوا تحت القلعةِ، وفي ظنهم أنَّه لم يُقتَل وإنما قُبِضَ عليه، وأنهم يأخذونَه من المعِزِّ، وكان أعيانُهم بيبرس البندقداري، وقلاوون الألفي، وسنقر الأشقر، وبيسرى، وسكز، وبرامق، فلم يشعروا إلا ورأسُ أقطاي قد رمى به المعزُّ إليهم، فسُقِطَ في أيديهم وتفَرَّقوا بأجمعهم، وخرجوا في الليلِ مِن القاهرة وحَرَقوا باب القراطين، فعرف بعد ذلك بالباب المحروقِ، فمنهم من قصد المَلِكَ المغيث بالكرك، ومنهم من سار إلى الملك الناصِر بدمشق، ومنهم من أقام ببلاد الغورِ والبلقاء والكرك والشوبك والقدس، يقطَعُ الطريق ويأكل بقائِمِ سَيفِه. وهو غيرُ الأمير فارس الدين أقطاي المستعرب نائب السلطنة بالشام."},{"id":2616,"title":"وفاة بدرة بنت الإمام فخر الدين محمد بن تيمية جدة شيخ الإسلام .","date":["العام الهجري :652","الشهر القمري : شوال","العام الميلادي :1254"],"text":"هي بدرةُ بنتُ الإمامِ فخرِ الدين محمد بن أبي القاسم بن تيميَّة، أم البدر، زوجةُ العلَّامة المفتي مجدِ الدين أبي البركات عبد السلام بن عبد الله ابن أبي القاسم ابن تيميَّة، جَدَّةُ شيخ الإسلامِ أبي العباس بن تيميَّة. توفيت قبل زوجها بليلة، وقد روت بالإجازةِ عن بعضِ أصحاب أبي علي الحدَّاد. سمع منها: الدمياطي بإجازتها من أبي المكارم اللبَّان"},{"id":2617,"title":"وفاة مجد الدين بن تيمية جد شيخ الإسلام بن تيمية .","date":["العام الهجري :652","الشهر القمري : شوال","العام الميلادي :1254"],"text":"هو الشَّيخُ الإمامُ العلَّامة، فقيهُ العصر، شيخُ الحنابلة، مجدُ الدين أبو البركات عبد السلام بن عبد الله بن أبي القاسم الخضر بن محمد بن علي بن تيمية الحراني الحنبلي، جد الشيخ تقي الدين بن تيميَّة المشهور بشيخِ الإسلام، ولِدَ في حدود سنة 590 وتفَقَّه في صغره على عَمِّه الخطيب فخر الدين، ففقه وبرع، واشتغل وصنف التصانيف، وانتهت إليه الإمامةُ في الفقه، وكان يجيدُ القراءاتِ، وصنَّف فيها أرجوزةً, وقد حَجَّ في سنة إحدى وخمسين على درب العراق، وانبهر علماءُ بغداد لذكائه وفضائله. قال شيخ الإسلام تقي الدين أبو العباس: كان الشيخُ جمال الدين بن مالك يقول: أُلينَ للشَّيخِ المجد الفقهُ كما أُلينَ لداود الحديد, ثم قال الشيخُ: وكانت في جَدِّنا حدة, وعَجَبٌ في سرد المتون، وحِفظُ مذاهب الناس، وإيرادُها بلا كُلفة. حدثني الإمام عبد الله بن تيمية: أن جدَّه ربِّيَ يتيمًا، ثم سافر مع ابن عمه إلى العراق ليخدُمَه وينفِقَ عليه، وله ثلاث عشرة سنة، فكان يبيت عنده ويسمَعُه يكرر على مسائل الخلافِ فيحفَظُ المسألة, فقال الفخر إسماعيل بن عساكر يومًا: أيش حفظ الننين – الصبي- فبدر المجد، وقال: حفظتُ يا سيدي الدرس. وسرده، فبُهِتَ الفخر، وقال: هذا يجيءُ منه شيء, ثم عرض على الفخر مصنفه (جنة الناظر)، وكتب له عليه في سنة 606 وعظَّمَه، فهو شيخُه في علم النظر، وأبو البقاء شيخُه في النحو والفرائض، وأبو بكر بن غنيمة صاحب ابن المني شيخه في الفقه، وابن سلطان شيخه في القراءات، وقد أقام ببغداد ستة أعوام مكبًّا على الاشتغال، ورجع ثم ارتحل إلى بغدادَ قبل 620، فتزيَّدَ من العلم، وصَنَّف التصانيفَ، مع الدِّينِ والتقوى، وحُسنِ الاتباع، وجلالةِ العِلمِ. سمعَ المجدُ أبو البركات الكثيرَ ورحل إلى البلاد، ودرَّس وأفتى وانتفَعَ به الطلبة، له تفسيرٌ للقرآن وهو صاحب الكتاب المشهور المنتقى في أحاديث الأحكام، توفِّيَ يوم الفطر بحرَّان."},{"id":2618,"title":"تآمر المماليك العزيزية على الملك المعز .","date":["العام الهجري :653","العام الميلادي :1255"],"text":"كانت المماليكُ العزيزيَّةُ قد عزمت بالقبضِ على الملك المعزِّ عِزِّ الدين أيبك وكاتبوا المَلِكَ الناصر واستشعر المَلِكُ المعز منهم بذلك وعَلِمَ الخبر، وعَلِموا هم أيضًا فهربوا على حمية، وكبيرُهم آقوش البرنلي، وقبض أيضًا على الأمير الأتابكي ونهِبَت خيامُ العزيزية وكانوا بالعباسيَّة."},{"id":2619,"title":"خروج الأمير عز الدين على الملك المعز أيبك صاحب مصر .","date":["العام الهجري :653","العام الميلادي :1255"],"text":"سار الأميرُ عز الدين أيبك الأفرم الصالحي إلى بلاد الصعيدِ، وأظهر الخروجَ عن طاعة الملِك المعزِّ عِزِّ الدين أيبك، وجمع العُربان، فسيَّرَ إليه الملك المعز الوزيرَ الصاحِبَ الأسعد شرف الدين الفائزي، ومعه طائفةٌ من العسكر، حتى سكَّنَ الأمور."},{"id":2620,"title":"انضمام الأمراء الهاربين من مصر إلى الناصر بدمشق لمواجهة المعز آيبك .","date":["العام الهجري :653","العام الميلادي :1255"],"text":"أخرج الملِكُ الناصِرُ عسكرًا إلى جهةِ ديار مصر، ومعهم البحريَّة الذين كانوا قد هَرَبوا من مصرَ مِن المعز بعد أن قُتِلَ صاحِبُهم فارسُ الدين أقطاي الجمداري، وهم الأميرُ سيف الدين بلبان الرشيد، وعز الدين أزدمر، وشمس الدين سنقر الرومي، وشمس الدين سنقر الأشقر، وبدر الدين بيسري، وسيف الدين قلاوون، وسيف الدين بلبان المسعودي، وركن الدين بيبرس البندقداري، وعدة من مماليك الفارس أقطاي."},{"id":2621,"title":"قيام حروب داخلية بين الصليبيين .","date":["العام الهجري :653","العام الميلادي :1255"],"text":"جرت بين الصليبيِّينَ حُروبٌ داخلية أضعَفَت قواهم بحَمدِ الله، فقامت حروبٌ بين البندقية وجنوة امتدت إلى عام 660 انضَمَّت فيها جميعُ الأحزاب المتنافرة إلى أحَدِ الجانبين وأنهكَتْهم ممَّا كان له الأثَرُ في استعادة الظاهر بيبرس في حينها أنطاكية منهم."},{"id":2622,"title":"هولاكو يجتاح بلاد فارس ويقتل جماعة الحشاشين الإسماعيلية .","date":["العام الهجري :654","العام الميلادي :1256"],"text":"بعد الاتِّفاقِ المغولي على الزَّحفِ إلى بلاد الإسماعيلية وغيرها, حدث في هذه السَّنة أن استولى هولاكو على حصنينِ مِن حُصونِ الإسماعيليَّة بولاية قهستان وأمَرَ بإعدام كلِّ مَن يزيد عمره على عشرِ سنوات، ثم استولى على قلعتي ألموت وميمون دز وقبضَ على زعيمِ الإسماعيليَّة ركن الدين خورشاه وأرسَلَه إلى قره كروم عاصمة المغول، فأمر منكو زعيمُهم بقتله وقتْل أتباعِه الذين كانوا معه."},{"id":2623,"title":"فيضانات أغرقت بغداد .","date":["العام الهجري :654","الشهر القمري : ربيع الآخر","العام الميلادي :1256"],"text":"أصاب بغدادَ غَرَقٌ عظيمٌ حتى طفح الماء من أعلى أسوارِ بغداد إليها، وغرق كثيرٌ منها، ودخل الماءُ دار الخلافة وسَطَ البلد، وانهدمت دارُ الوزير وثلاثمائة وثمانون دارًا، وانهدم مخزنُ الخليفة، وهلك مِن خزانة السلاحِ شيء كثير، وأشرف الناسُ على الهلاك وعادت السفُنُ تدخل إلى وسط البلدة، وتخترق أزقَّة بغدادَ."},{"id":2624,"title":"احتراق المسجد النبوي الشريف .","date":["العام الهجري :654","الشهر القمري : رمضان","العام الميلادي :1256"],"text":"في ليلةِ الجُمُعةِ مُستهَلَّ رَمَضانَ احترق المسجدُ النبوي بالمدينةِ- على ساكِنِه أفضَلُ الصلاة والسلام، ابتدأ حريقُه من زاويتِه الغربيَّة من الشمال، وكان دخل أحدُ القومةِ إلى خزانةٍ ومعه نار فعَلِقَت في الأبوابِ ثم اتصلت بالسَّقفِ بسُرعةٍ، ثم دبَّت في السقوف، وأخذت قبلةً فأعجلت النَّاسَ عن قطعها، فما كان إلا ساعةٌ حتى احترقت سقوفُ المسجِدِ أجمع، ووقعت بعض أساطينِه وذاب رصاصُها، وكلُّ ذلك قبل أن ينامَ النَّاسُ، واحترق سقف الحُجرةِ النبويَّة ووقع ما وقع منه في الحُجرة، وقد خرَّب الحريقُ المسجِدَ، ولم يُفلِتْ منه إلاَّ قبَّةُ الناصر لدين الله التي كانت في رحبتِه، وبقي على حالِه حتى شرع في عمارةِ سَقفِه وسَقفِ المسجِدِ النبوي، وأصبح الناسُ فعزلوا موضعًا للصلاة، وعُدَّ ما وقع من تلك النَّار ِالخارجة وحريقِ المسجد من جملة الآيات، وكأنها كانت منُذِرةً بما يعقُبُها في السنة الآتية من الكائناتِ، وحين بلغ المستعصِمَ العباسيَّ الخبَرُ أرسل الصنَّاعَ والآلاتِ في موسم الحج، وبدأ العمل عام 655هـ. وقد حدثت في هذا العامِ أحداثُ التتار وحروبهم، ولكِنَّ عمل البناءِ لم يتوقَّفْ؛ إذ اشترك فيه الملك المظفَّر ملك اليمن، وملك مصر نور الدين علي بن المعز الصالحي، وإن كانت العمارةُ لم تنتهِ إلا في عهد الملك الظاهر بيبرس."},{"id":2625,"title":"فتنة بين السنة والشيعة في بغداد .","date":["العام الهجري :655","العام الميلادي :1257"],"text":"وقوع فتنة عظيمة ببغداد بين الرافضة وأهل السنة، قال ابن كثير: \"فنُهِبَ الكرخ ودُورُ الرافضة حتى دورُ قرابات الوزير ابنِ العلقمي، وأنَّ ذلك من أقوى الأسبابِ في ممالأتِه للتتار\"."},{"id":2626,"title":"إسلام ملك بلاد القبجاق بركة خان المغولي .","date":["العام الهجري :655","العام الميلادي :1257"],"text":"اعتنق الإسلامَ بَرَكةُ خان بن جوجي بن جنكيز خان المغولي متمَلك بلاد القبجاق, وزعيمُ القبيلة الذهبيَّة المغولية, وهو ابنُ عم هولاكو، وكذلك أسلَمَت زوجتُه ججك. أسلم بركةُ خان على يد الشَّيخِ أبو المعالي سعيد بن المطهر الباخرزي, وكان عنده ستون زوجة، فأمره باتخاذِ أربعٍ فقط وفراق الباقيات، ففعل، ورجع إلى بلاده، وأظهر شعائر الملة الإسلامية، وأسلم معه جماعةٌ من أمرائه وأهل بيته، وأخذوا في تعلُّمِ الفرائض."},{"id":2627,"title":"بداية قصد المغول بغداد .","date":["العام الهجري :655","العام الميلادي :1257"],"text":"جرت فتنةٌ مهولة ببغدادَ بين الناس وبين الرَّافضة، وقُتِلَ عدة من الفريقين، وعَظُم البلاء، ونهب الكرخ، فحنق ابن العلقمي الوزير الرافضي، وكاتَبَ هولاكو، وطَمَّعَه في العراق، فجاءت رسُلُ هولاكو إلى بغدادَ، وفي الباطِنِ معهم فرماناتٌ لغير واحد، وَصَلت جواسيس هولاكو إلى وزير الخليفة العباسي المستعصم بالله مؤيد الدين محمد بن العلقمي الرافضي ببغداد، وتحَدَّثوا معه ووعدوا جماعةً مِن أمراء بغداد مواعيدَ، والخليفةُ لا يدري ما يتمُّ، وأيَّامُه قد ولت ثم قَوِيَ قَصدُ هولاكو بن طولو بن جنكيزخان بغداد، وبعث يطلبُ الضيافةَ مِن الخليفة فكَثُرَ الإرجافُ ببغداد، وخرج الناسُ منها إلى الأقطار، ونزل هولاكو تجاهَ دار الخلافة وملك ظاهِرَ بغداد، وقتل من الناسِ عالَمًا كثيرًا."},{"id":2628,"title":"وفاة الملك المعز عز الدين أيبك صاحب مصر وأول سلطان مملوكي .","date":["العام الهجري :655","الشهر القمري : ربيع الأول","العام الميلادي :1257"],"text":"هو السُّلطانُ الملك المعز عِزُّ الدنيا والدين، أيبك التركماني، الصالحي الجاشنكير- جاشنكير متذوِّق طعام السلطان-  صاحب مصر. لما قتل المماليكُ المعظَّم توران شاه، خَطَبوا لشجرةِ الدر أمِّ خليل أيامًا، وكانت تعلِّمُ على المناشير، وتأمُرُ وتنهى، ويُخطَبُ لها بالسلطنة. ولما وصل الخبَرُ بذلك إلى بغداد فبعث الخليفة المستعصم بالله من بغداد كتابا إلى مصر وهو ينكِرُ على الأمراء ويقولُ لهم: \"إن كانت الرجالُ قد عَدِمَت عندكم فأعلِمونا حتى نسَيِّرَ إليكم رجلًا\" فاجتمع الأمراءُ والبحرية للمشورة واتفقوا على إقامة الأمير عز الدين أيبك مقَدَّم العسكر في السلطنة ولقَّبوه بالملك المعز. كان المعزُّ أكبر الصالحية، دَيِّنًا عاقلًا ساكًنا، كريمًا تاركًا للشرب. ملكوه في أواخر ربيع الآخر سنة ثمان وأربعين، وتزوَّجَ بأم خليل، فأنِفَ من سلطنتِه جماعة، فأقاموا في الاسمِ الملك الأشرف موسى بن الناصر يوسف ابن المسعود أطسز بن السلطان الملك الكامل وله عشرُ سنين، وذلك بعد خمسة أيام، فكان التوقيع يبرز وصورته: رسم بالأمر العالي السلطاني الأشرفي والملكي المعزي. واستمَرَّ ذلك والأمور بيد المعز، وكان في المعِزِّ تُؤَدة ومداراة، ثم استقَلَّ بالملك بلا منازعة، وكسر الناصِرَ لَمَّا أراد أخذ الديار المصرية وقَتَلَ فارِسَ الدين أقطاي الجمدار- جمدار حامل ملابس السلطان- سنة ثنتين وخمسين، وخلع بعده الأشرفَ، واستقَلَّ بالملك وحده، وهو واقِفُ المدرسة المعزية بمصرَ ومجازُها من أحسن الأشياء. كان موتُه في يوم الثلاثاء  الثالث والعشرين من ربيع الأول، أصبح المعز بداره ميتًا فاتَّهَم مماليكُه زوجته شجرة الدر، وقد كان عَزَم على تزوُّجِ ابنة صاحب الموصل بدر الدين لؤلؤ، فأمرت جواريها أن يمسِكنَه لها فما زالت تضربُه بقباقيبِها والجواري يَعركنَ في أنثَيَيه حتى مات وهو كذلك، وقيل بل أعدت له شجرة الدرِّ خمسةً ليقتلوه منهم محسن الجوجري، وخادمٌ يعرف بنصر العزيزي، ومملوكٌ يسمى سنجر، فلما كان يوم الثلاثاء ركب الملك المعز من الميدان بأرضِ اللوق، وصَعِدَ إلى قلعة الجبل آخِرَ النهار، ودخل إلى الحمام ليلًا، فأغلق عليه الباب محسن الجوجري، وغلام كان عنده شديدُ القوة ومعهما جماعة، وقتلوه بأن أخذه بعضُهم بأنثييه وبخناقه، فاستغاث المعز بشَجَرةِ الدر فقالت اتركوه، فأغلظ لها محسن الجوجري في القول، وقال لها: متى ترَكْناه لا يبقي علينا ولا عليك، ثم قتلوه، وأقامت الأتراكُ بعده ولَدَه عليًّا، بإشارةِ أكبر مماليكه الأمير سيف الدين قطز، ولَقَّبوه الملك المنصور، وخُطِبَ له على المنابر وضُرِبَت السكة باسمه وجَرَت الأمور على ما يختاره برأيه ورسمه، عاش المعِزُّ نيفًا وخمسين سنة، وكان قد مكث في الملك نحوًا من سبع سنين."},{"id":2629,"title":"مقتل شجرة الدر بسبب قتلها زوجها الملك المعز عز الدين أيبك .","date":["العام الهجري :655","الشهر القمري : ربيع الآخر","العام الميلادي :1257"],"text":"هي شجرةُ الدر الصالحيَّة بنت عبد الله أم خليل التركيَّة، ذاتُ حُسنٍ وظرف ودهاء وعقل، ونالت من العِزِّ والجاه ما لم تنَلْه امرأة في عصرها، كانت جاريةً اشتراها الملك الصالح نجم الدين أيوب، وحَظِيَت عنده بمكانةٍ كبيرة، وكانت أمَّ ولدٍ عنده؛ فقد ولدت منه خليلًا، من أحسن الصور، فمات صغيرًا، وكانت تكونُ في خدمة الملك الصالحِ لا تفارقه حضرًا ولا سفرًا من شدة محبته لها, فأعتَقَها وتزوَّجَها. وكانت تقومُ بتدبير شؤون الدولة في أثناء مرض زوجِها، فلما تُوفى الملك الصالح بدمياط في أثناء حربه مع الإفرنج سنة 647 كتمت خبَرَ موته، وأرسلت إلى ابنه توران شاه ليتولى أمورَ الملك من بعده، إلَّا أن توران شاه هدَّدها، وطالبها بأموال الملك الصالح، فدبَّرت لقَتلِه، وبعد مقتَلِه اجتمعت الآراء على توليتها السلطنة في صفر سنة 648, وكان مماليك الصالح يخضعون لها، فمَلَّكوها بعد قتل المعظَّم توران شاه ثمانين يومًا، وكان المعِزُّ لا يقطع أمرًا دونها، ولها عليه صولةٌ، وكانت جريئةً وَقِحة، قتَلَت وزيرَها الأسعَدَ، وكانت تحجُر على الملك المعز، فأنِفَ من ذلك, ولما بَلَغَها عزمُ المعز الزواجَ مِن بنت بدر الدين لؤلؤ صاحب الموصل قتَلَتْه, ولما توفِّيَ لم يصَدِّقْ مماليك عز الدين بأنه توفي بغير سببٍ، وقام الأمير علم الدين سنجر الغتمي - وهو يومئذٍ شَوكةُ البحرية وشديدُهم- وبادر هو والمماليك إلى الدور السلطانية، وقبضوا على الخُدَّام والحريم وعاقبوهم، فأقَرُّوا بأن شجرة الدر أمرت مماليكَها بقتله، وعند ذلك قبضوا على شجرةِ الدر، ومحسن الجوجري، وناصر الدين حلاوة، وصدر الباز، وفر العزيزي إلى الشام، فأراد مماليكُ المعز قَتْلَ شجرة الدر، فحماها الصالحيَّة، ونُقِلَت إلى البرج الأحمر بالقلعة، ثم لما أقيم ابنُ المعز في السلطنة، حُمِلَت شجرةُ الدر إلى أمِّه في اليومِ السابع عشر، فضرَبَها الجواري بالقباقيبِ إلى أن ماتَت، وألقوها من سور القلعة إلى الخندقِ، وليس عليها سراويل وقميص، فبَقِيَت في الخندق أيامًا، ثم دفنت بعد أيام - وقد نتنت، وحُمِلَت في قفة- بتربتها قريب المشهد النفيسي، وكانت من قُوَّةِ نَفسِها، لما عَلِمَت أنها قد أحيطَ بها، أتلفت شيئًا كثيرًا من الجواهِرِ واللآلئ، كسَّرَته في الهاون، وقد قيل إنه لما سمع مماليك عز الدين أيبك بخبر وفاته أقبلوا بصحبة مملوكه الأكبر سيف الدين قطز، فقتلوها وألقوها على مزبلةٍ غيرَ مستورةِ العورةِ."},{"id":2630,"title":"القتال بين المماليك البحرية الذين هربوا من مصر وبين عسكر مصر .","date":["العام الهجري :655","الشهر القمري : شوال","العام الميلادي :1257"],"text":"وقَعَت الوحشةُ بين الملك الناصر وبين من عنده من المماليك البحريَّة، ففارقوه في شوال، وقصدوا الملك المغيثَ صاحب الكرك، فأخرج الأميرُ سيف الدين قطز العسكَرَ الصالحية، فواقعوهم في يوم السبت خامِسَ عشر ذي القعدة، وأسَرُوا الأمير سيف الدين قلاوون، والأميرَ سيف الدين بلبان الرشيدي، وقتل الأمير سيف الدين بلغان الأشرفي، وانهزم عَسكَرُ الكرك وفيهم بيبرس البندقداري، وعاد العسكرُ إلى القاهرة، فضمن الأميرُ شرف الدين قيران- المعزي وهو أستادار السلطان- الأمير قلاوون وأطلقه، فأقام قلاوون بالقاهرة قليلًا، ثم اختفى بالحُسَينية عند سيف الدين قطليجا الرومي، فزوَّدَه وسار إلى الكرك."},{"id":2631,"title":"استيلاء المغول على بلاد الجزيرة وغيرها .","date":["العام الهجري :656","العام الميلادي :1258"],"text":"نزل هولاكو بجيشِه المغولي بعدَ مذبحةِ بغداد حرَّان واستولى عليها ومَلَك بلادَ الجزيرة، ثم سيَّرَ ولده أشموط إلى الشامِ وأمره بقطعِ الفرات وأخْذ البلاد الشامية، وسيَّرَه في جمعٍ كثيف من التتار فوصَلَ أشموط إلى نهرِ الجوز وتل باشر، ووصل الخبَرَ إلى حلب من البيرة بذلك، وكان نائبُ السلطان صلاح الدين يوسف بحلب ابنه الملك المعظم توران شاه، فجفَل النَّاسُ بين يدي التتارِ إلى جهة دمشق وعظم الخطب، واجتمع الناسُ من كلِّ فجٍّ عند الملك الناصر بدمشق، واحترز الملك المعظَّم توران شاه بن الملك الناصر بحَلَب غاية الاحتراز، وكذلك جميعُ نوَّاب البلاد الحلبيَّة، وصارت حَلَب في غاية الحصانة بأسوارها المحكَمة البناءِ وكثرة الآلات، فلمَّا كان العشر الأخير من ذي الحِجَّة قصد التتارُ حَلَب ونزلوا على قريةٍ يقال لها سلميَّة وامتَدُّوا إلى حيلان والحادي، وسيَّروا جماعةً مِن عَسكَرِهم أشرفوا على المدينة، فخرج عسكرُ حلب ومعهم خلقٌ عظيم من العوام والسُّوقة، وأشرفوا على التتار وهم نازلونَ على هذه الأماكِنِ، وقد رَكِبوا جميعُهم لانتظار المسلمينَ، فلمَّا تحقَّق المسلمون كثرتَهم كَرُّوا راجعين إلى المدينة، فرسم المَلِكُ المعظَّم بعد ذلك ألا يخرُجَ أحد من المدينة، ولما كان غدُ هذا اليوم رحلت التتارُ من منازلهم طالبين مدينةَ حلب، واجتمع عسكرُ المسلمين بالنواشير وميدان الحصا وأخذوا في المشورة فيما يعتَمِدونه، فأشار عليهم الملك المعظَّم أنهم لا يخرجون أصلًا لكثرة التتار ولقوَّتهم وضعف المسلمين على لقائهم، فلم يوافِقْه جماعة من العسكر وأبوا إلَّا الخروج إلى ظاهر البلد لئلَّا يطمع العدو فيهم، فخرج العسكرُ إلى ظاهر حلب وخرج معهم العوامُّ والسوقة، واجتمع الجميعُ بجبل بانقوسا، ووصل جمع التتار إلى أسفَلِ الجبل فنزل إليهم جماعة من العسكر ليقاتِلوهم، فلما رآهم التتار اندفعوا بين أيديهم مكرًا منهم وخديعةً، فتبعهم عسكرُ حلب ساعةً من النهار، ثم كرَّ التتار عليهم فوَلَّوا منهزمينَ إلى جهة البلد والتتارُ في أثرهم، فلما حاذوا جبل بانقوسا وعليه بقية عسكر المسلمين والعوام اندفعوا كلُّهم نحو البلد والتتار في أعقابِهم، فقتلوا من المسلمينَ جمعًا كثيرًا من الجند والعوام، ونازل التتارُ المدينة في ذلك اليوم إلى آخره، ثم رحلوا طالبينَ أعزاز فتسَلَّموها بالأمانِ."},{"id":2632,"title":"وفاة أبي الحسن الشاذلي مؤسس الطريقة الصوفية الشاذلية .","date":["العام الهجري :656","العام الميلادي :1258"],"text":"هو شَيخُ الطائفة الشاذليَّة الزاهد أبو الحَسَن علي بن عبد الله بن عبد الجبَّار بن تميم المغربي الشاذلي المالكي، نزيلُ الإسكندرية، مؤسِّس الطريقة الصوفيَّة المشهورة بالشاذليَّة، ولد في غمارة قرب سبتة بالمغرب، وفيها نشأ وتعلم، رافق أبا القاسم الجُنَيد البغداديَّ الصوفيَّ، فأخذ عنه التصوفَ، ثم اتخذ في تونس رباطًا له في جبل وبدأ ينشُرُ أفكاره في بلدة شاذلة القريبةِ مِن رباطه فكَثُرَ أتباعه، ثم نُفِيَ إلى مصر واستقَرَّ في الإسكندرية، وتبعه خلقٌ كثير في مصر والشام. قال الذهبي: \"وقد انتسَبَ في بعض مؤلفاته في التصوُّف إلى علي بن أبي طالب، وكان الأولى به تركَه هذا الانتسابَ وتَرْكَ كثيرٍ ممَّا قاله في تواليفِه من الحقيقة، وهو رجلٌ كبيرُ القدر، كثيرُ الكلام، عالي المقام. له شِعرٌ ونَثرٌ فيه متشابهات وعبارات، يُتكَلَّف له في الاعتذار عنها. ورأيت شيخنا عمادَ الدين قد فتَرَ عنه في الآخر، وبَقِيَ واقفًا في عباراته، حائرًا في الرجل؛ لأنه كان قد تصَوَّف على طريقتِه، وكان الشاذلي ضريرًا، ولخلقٍ فيه اعتقاد كبير\". له تصانيف منها (عمدة السالك على مذهب الإمام مالك) وله (التسلي والتصبر على ما قضاه الله من أحكام التجبر والتكبر) وله أحزابٌ خاصة به، منها (الحزب الكبير) أو حزب البِرِّ، وحزب البحر، وحزب الإخفاء، وحزب النصر، وحزب الطمس على عيون الأعداء، وحزب اللطف وغيرها، توفي في حميترة من صحراء عيذاب في صعيد مصر، وفيها دفن."},{"id":2633,"title":"سقوط بغداد على يد هولاكو قائد المغول .","date":["العام الهجري :656","الشهر القمري : محرم","العام الميلادي :1258"],"text":"كان الوزيرُ ابن العلقمي يجتَهِدُ في صرف الجيوش وإسقاطِ اسمِهم من الديوان، فكانت العساكِرُ في آخر أيام المستنصر قريبًا من مائة ألف مقاتل، منهم من الأمراء ومن هو كالملوك الأكابر الأكاسر، فلم يزل يجتهد في تقليلِهم إلى أن لم يبقَ سوى عشرة آلاف، ثم كاتب التتارَ وأطمعهم في أخذِ البلاد، وسَهَّل عليهم ذلك، وحكى لهم حقيقةَ الحال، وكشَفَ لهم ضعف الرجال، وذلك كلُّه طمعًا منه أن يزيل السُّنَّة بالكُلِّيَّة، وأن يُظهِرَ البِدعةَ الرَّافضية، وأن يقيمَ خليفةً مِن الفاطميِّينَ، وأن يُبيدَ العلماء والمُفتين- والله غالبٌ على أمرِه- كانت الفِتَنُ قد استعرت بين السُّنة والرافضة في بغداد حتى تجالَدوا بالسيوف، وشكا أهلُ باب البصرة إلى الأمير ركن الدين الدويدار والأمير أبي بكر بن الخليفة فتَقَدَّما إلى الجند بنَهبِ الكرخ، فهَجَموه ونهبوا وقتلوا، وارتكبوا من الشنعة العظائم، فحنق ابنُ العلقمي ونوى الشرَّ، وأمر أهل الكرخ بالصَّبرِ والكف. فمالأ- قبَّحَه اللهُ- على الإسلامِ وأهلِه المغولَ الكَفَرةَ وزَعيمَهم هولاكو، حتى فعل ما فعل بالإسلامِ وأهلِه، خاصة في بغداد- عليه من الله ما يستحقُّ- كان قدوم هولاكو بجنوده كلها- وكانوا نحو مائتي ألف مقاتل- إلى بغداد في ثاني عشرَ المحرم من هذه السنة، وجاءت إليهم أمدادُ صاحب الموصل يساعِدونَهم على أهل بغداد, وميرته وهداياه وتُحَفه، وكل ذلك خوفًا على نفسه مِن التتار، ومصانعةً لهم، وقد سُتِرَت بغداد ونُصِبَت فيها المجانيق والعرادات وغيرها من آلات الممانعة، فأحاطوا ببغدادَ مِن ناحيتها الغربيَّة والشرقية، وجيوش بغداد في غايةِ القِلَّة ونهاية الذِّلَّة، لا يبلغونَ عَشرةَ آلاف فارس، وهم وبقيَّة الجيش، كلهم قد صرفوا عن إقطاعاتِهم وذلك كلُّه عن آراء الوزيرِ ابن العلقميِّ الرافضي، الذي دبَّر على الإسلام وأهله ما وقع من الأمر الفظيعِ، الذي لم يؤرخ أبشَعُ منه منذ بُنِيَت بغداد، وكان أوَّلَ مَن برز إلى التتار هو، فخرج بأهلِه وأصحابِه وخَدَمِه وحَشَمِه، فاجتمع بالسلطانِ هولاكو خان- لعنه الله- ثم عاد فأشار على الخليفةِ بالخروجِ إليه والمثول بين يديه لتقَعَ المصالحة على أن يكون نِصفُ خراج العراق لهم ونِصفُه للخليفة، فخرج الخليفةُ في سبعمائة راكبٍ مِن القضاة والفقهاء والصوفية ورؤوس الأمراء والدولة والأعيان، فلما اقتَرَبوا من منزل السلطان هولاكو خان حُجِبوا عن الخليفةِ إلا سبعة عشر نفسًا، فخَلَص الخليفة بهؤلاء المذكورين، وأُنزِلَ الباقون عن مراكبهم فنُهِبَت وقُتِلوا عن آخرهم، وأُحضِرَ الخليفة بين يدي هولاكو فسأله عن أشياء كثيرة، فيقال: إنَّه اضطرب كلامُ الخليفة من هَولِ ما رأى من الإهانةِ والجبروت، ثم عاد إلى بغداد وفي صُحبَتِه خوجه نصير الدين الطوسي، والوزير ابن العلقمي وغيرهما، والخليفةُ تحت الحوطة والمصادرة، فأحضَرَ مِن دار الخلافة شيئًا كثيرًا مِن الذهب والحُلِيِّ والمصاغ والجواهر والأشياء النفيسة، وقد أشار أولئك الملأ من الرَّافضة وغيرهم من المنافقين على هولاكو ألَّا يصالح الخليفة، وقال الوزير: متى وقع الصلحُ على المناصفة لا يستمِرُّ هذا إلا عامًا أو عامين، ثم يعود الأمر إلى ما كان عليه قبل ذلك، وحَسَّنوا له قتل الخليفة، فلما عاد الخليفةُ إلى السلطان هولاكو أمر بقَتلِه، ويقال: إن الذي أشار بقتله الوزير ابن العلقمي، والمولى نصير الدين الطوسي، وكان النصيرُ عند هولاكو قد استصحبه في خدمَتِه لما فتح قلاع ألموت التي للإسماعيلية، وانتزعها من أيديهم، وانتخب هولاكو الطوسيَّ ليكون في خدمته كالوزير المشير، فلما قَدِمَ هولاكو وتهيبَ مِن قَتلِ الخليفة هَوَّن عليه الوزير ذلك فقتلوه، فباؤُوا بإثمِه وإثم من كان معه من ساداتِ العُلَماءِ والقُضاة والأكابر والرؤساء والأمراء وأولي الحَلِّ والعقد ببلاده، ومالوا على البلد فقَتَلوا جميع من قدروا عليه من الرجال والنساء والولدان والمشايخ والكهول والشبَّان، ودخل كثيرٌ من الناس في الآبار وأماكِنِ الحشوش، وقنى الوسَخِ، وكَمَنوا كذلك أيامًا لا يظهرون، وكان الجماعةُ مِن الناس يجتمعون إلى الخانات ويُغلِقونَ عليهم الأبواب فتفتحها التتارُ إمَّا بالكسر وإما بالنار، ثم يدخلونَ عليهم فيهربون منهم إلى أعالي الأمكنةِ فيقتلونهم بالأسطُحِ، حتى تجري الميازيب من الدماءِ في الأزقة، فإنا لله وإنا إليه راجعون!! وكذلك في المساجد والجوامع والرُّبُط، ولم ينجُ منهم أحد سوى أهل الذمَّة من اليهود والنصارى ومَن التجأ إليهم وإلى دار الوزير ابن العلقمي الرافضي، وطائفةٌ مِن التجَّار أخذوا لهم أمانًا، بذلوا عليه أموالًا جزيلةً حتى سَلِموا وسَلِمَت أموالهم، وعادت بغدادُ بعد ما كانت آنَسَ المدن كلِّها كأنها خرابٌ ليس فيها إلا القليلُ مِن الناس، وهم في خوفٍ وجوعٍ وذِلَّة وقلة! وكان دخولهم إلى بغداد في أواخِرِ المحرم، وما زال السيف يقتُلُ أهلَها أربعينَ يومًا، وكان الرجلُ من بني العباس يُستدعى به مِن دار الخلافة فيخرج بأولادِه ونسائه فيُذهَبُ به إلى مَقبرةِ الخَلَّال تجاه المنظرة فيُذبَحُ كما تُذبَحُ الشاة، ويؤسَرُ من يختارون من بناتِه وجواريه، وتعطَّلَت المساجد والجمع والجمعات مدة شهورٍ ببغداد، ولما انقضى الأمرُ المقَدَّر وانقضت الأربعون يومًا بقيت بغداد خاويةً على عروشها ليس بها أحَدٌ إلا الشاذُّ من الناس، والقتلى في الطرقات كأنها التلول، وقد سقط عليهم المطَرُ فتغيرت صُوَرُهم وأنتنت من جِيَفِهم البلد، وتغيَّرَ الهواء فحصل بسببه الوباءُ الشديد حتى تعدى وسرى في الهواءِ إلى بلاد الشام، فمات خلقٌ كثير من تغيُّرِ الجو وفساد الريح، فاجتمع على الناس الغلاءُ والوَباءُ والفَناء والطعن والطاعون، فإنا لله وإنا إليه راجعون، ولما نودي ببغداد بالأمانِ خرج من تحت الأرضِ مَن كان بالمطامير والقنى والمقابر كأنهم الموتى إذا نُبِشوا من قبورهم، وقد أنكر بعضُهم بعضًا، فلا يعرف الوالد ولده ولا الأخ أخاه، وأخذهم الوباءُ الشديد فتفانوا وتلاحقوا بمن سبقَهم من القتلى، واجتمعوا تحت الثرى بأمرِ الذي يعلَمُ السر َّوأخفى، اللهُ لا إلهَ إلا هو له الأسماءُ الحسنى. حكى جمال الدين سليمان بن عبد الله بن رطلين قال: \"لما قُتِلَ الخليفة, وأَطلَقَ المغول السبعة عشر الذين كانوا معه وكان أبي معهم، قُتِلَ منهم رجلان وطلب الباقونَ بيوتهم فوجدوها بلاقِعَ. فأتوا المدرسةَ المغيثية، وقد كُنتُ ظَهرتُ مِن مخبئي, فبقيت أسألُ عن أبي، فدُلِلْتُ عليه، فأتيتُه وهو ورفاقه، فسَلَّمت عليهم، فلم يعرفني أحدٌ منهم، وقالوا: ما تريد؟ قلت: أريدُ فخر الدين ابن رطلين. وقد عرفتُه، فالتفَتَ إليَّ وقال: ما تريد منه؟ قلت: أنا ولَدُه. فنظر إليَّ وتحقَّقني، فلما عرفني بكى!!\". كان رحيل هولاكو خان عن بغداد في جمادى الأولى من هذه السنة إلى مقر مُلكِه، وفوَّضَ أمر بغداد إلى الأمير علي بهادر، فوَّضَ إليه الشحنكية بها وإلى الوزير ابن العلقمي الذي مات بعد أشهرٍ من هذه الحادثةِ غَمًّا وكَمَدًا, فولي بعده الوزارة ولدُه عز الدين بن الفضل محمد، فألحقه اللهُ بأبيه في بقيَّة هذا العام."},{"id":2634,"title":"وفاة القاضي محيي الدين يوسف بن الجوزي واقف المدرسة الجوزية .","date":["العام الهجري :656","الشهر القمري : صفر","العام الميلادي :1258"],"text":"هو أستاذ دار الخلافة الصاحِبُ القاضي محيي الدين يوسف ابن الشيخ جمال الدين أبي الفرج بن الجوزي عبد الرحمن بن علي بن محمد بن علي بن عبد الله بن حماد بن أحمد بن يعقوب بن جعفر بن عبد الله بن القاسم بن النصر بن محمد بن أبي بكر الصديق، المعروفُ بابنِ الجوزيِّ القرشيِّ التيمي البكري البغدادي الحنبلي، ولد في ذي القعدة سنة 580 ونشأ شابًّا حسنًا وحين توفِّيَ والِدُه وعَظَ في موضعه فأجاد وأحسن وأفاد، ثم تقَدَّمَ وولِيَ حِسبةَ بغداد مع الوَعظِ الرائِقِ والأشعار الحسنة الرائعة، وولي تدريسَ الحنابلة بالمستنصرية سنة 632 وكانت له مدارس أخرى، صار محيي الدين رسولَ الخلفاءِ إلى الملوكِ بأطرافِ البلادِ ولا سيَّما إلى بني أيوبَ بالشَّامِ وقد حصل منهم من الأموالِ والكراماتِ ما ابتغى من ذلك بناءَ المدرسة الجوزيَّة التي بالنشابين بدمشق, ولما وَلِيَ مؤيِّدُ الدين بن العلقمي الوزارةَ سنة 640 وشغر عنه الأستادارية، وَلِيَها عنه محيي الدين وانتصب ابنه عبد الرحمن للحسبة والوعظِ، فأجاد فيها وسار سيرةً حسنةً، ثم كانت الحسبةُ تنتَقِلُ في بنيه الثلاثة: جمال الدين عبد الرحمن، وشرف الدين عبد الله، وتاج الدين عبد الكريم، وقد قُتِلوا معه في هذه السَّنة, ولمحيي الدين مُصَنَّف في مذهب الإمام أحمد، وذكر له ابنُ الساعي أشعارًا حسنة يهنِّئ بها الخليفةَ في المواسم والأعياد تدُلُّ على فضيلةٍ تامةٍ وفصاحةٍ بالغة، وقد وقَفَ المدرسةَ الجَوزيَّةَ بدِمشقَ، وكان كثيرَ المحفوظ قويَّ المشاركة في العلومِ، وافر الحُرمةِ، ضُرِبَت عُنُقُه هو وأولاده تاج الدين والمحتسب جمال الدين وشرف الدين مع الخليفةِ المُستَعصِم بالله عام هولاكو ببغدادَ في صَفَر."},{"id":2635,"title":"مقتل المستعصم بالله آخر الخلفاء العباسيين على يد التتار .","date":["العام الهجري :656","الشهر القمري : صفر","العام الميلادي :1258"],"text":"هو الخليفةُ الشهيد أمير المؤمنين المستعصِم بالله أبو أحمد عبد الله بن المستنصر بالله منصور بن الظاهر محمد بن الناصر أحمد بن المستضيء الهاشمي، العباسي، البغدادي. ولد: سنة 609, واستُخلِفَ سنة أربعينَ يومَ مَوتِ أبيه في عاشر جمادى الآخرة، وكان فاضلًا تاليًا لكتاب الله، كان مليحَ الخَطِّ، قرأ القرآن على الشيخ علي بن النيار الشافعي، ويوم خَتَمَه خلع على الشَّيخِ، وأعطي ستة آلاف دينار. ويوم خلافته بلغت الخِلَع ثلاثة عشر ألف خلعة وسبعمائة وخمسين خلعة, وكان كريمًا حليمًا، سليمَ الباطن، حَسَن الديانة. قال الشيخ قطب الدين: \"كان المستعصمُ بالله متدينًا مُتمَسِّكًا بالسنَّة كأبيه وجَدِّه، ولكنه لم يكن على ما كان عليه أبوه المستنصر وجده الناصر من التيقُّظ والحزم وعلُوِّ الهمة؛ فإن المستنصر بالله كان ذا همة عالية، وشجاعةٍ وافرة، ونفسٍ أبيَّة، وعنده إقدامٌ عظيم, وكان له أخٌ يُعرَف بالخفاجي يزيدُ عليه في الشهامة والشجاعة، وكان يقول: إن ملَّكني الله الأمرَ لأعبُرَنَّ بالجيوش نهر جيحون وأنتزع البلاد من التتار واستأصلهم, فلما توفِّيَ المستنصر لم يَرَ الدويدار والشرابي والكبار تقليد الخفاجي الأمرَ، وخافوا منه، وآثروا المستعصِمَ لِمَا يعلمون من لينِه وانقياده وضَعفِ رأيه؛ ليكونَ الأمر إليهم. فأقاموا المستعصم، ثم ركَنَ إلى وزيره ابن العلقمي، فأهلك الحَرثَ والنَّسلَ، وحَسَّنَ له جمع الأموال، والاقتصارَ على بعض العساكر، وقطَعَ الأكثر, فوافقه على ذلك, وكان فيه شُحٌّ، وقلة معرفة، وعدم تدبيرٍ، وحُبٌّ للمال، وإهمالٌ للأمور. وكان يتَّكِلُ على غيره، ويُقدِمُ على ما لا يليق وعلى ما يُستقبَحُ\". قال الذهبي: \"كان يلعب بالحَمام، ويُهمِلُ أمر الإسلام، وابنُ العلقمي يلعَبُ به كيف أراد، ولا يُطلِعُه على الأخبار. وإذا جاءته نصيحةٌ في السر أطلع عليها ابنَ العلقمي؛ ليقضيَ الله أمرًا كان مفعولًا. حكى جمال الدين سليمان بن عبد الله بن رطلين قال: \"جاء هولاكو في نحو مائتي ألف، ثم طلب الخليفةَ، فطلع ومعه القُضاة والمدرِّسون والأعيان في نحو سبعمائة نفس، فلما وصلوا إلى الحربية جاء الأمرُ بحضور الخليفة ومعه سبعة عشر نفسًا، فاتفق أن أبي كان أحدهم، فحدثني أنهم ساقوا مع الخليفة، وأنزلوا مَن بَقِيَ عن خيلهم، وضَرَبوا رقابَهم. ووقع السيف في بغداد، فعَمِلَ القتل أربعين يومًا. وأنزلوا الخليفةَ في خيمةٍ صغيرة، والسبعة عشر في خيمة. قال أبي: فكان الخليفةُ يجيء إلى عندنا كل ليلة ويقول: ادعُوا لي. قال: فاتفَقَ أنَّه نزل على خيمته طائرٌ، فطلبه هولاكو وقال: أيش عَمَلُ هذا الطائر؟ وأيش قال لك؟ ثم جرت له محاوراتٌ معه ومع ابن الخليفةِ أبي بكر. ثم أمَرَ بهما فأُخرِجا، ورفسوهما في غرارة -كيس كبير من صوف أو شعر- حتى ماتا، وكانوا يسمُّونه: الأبْلَه. توفي الخليفةُ في أواخر المحرم، وما أظنه دُفِنَ، فإنا لله وإنا إليه راجعون. وكان الأمرُ أعظم من أن يوجَدَ مؤرخ لموته، أو موارٍ لجَسَدِه. وراح تحت السيف أممٌ لا يحصيهم أحَدٌ إلا الله، فيقال: إنَّهم أكثرُ من ألف ألف، واستغنت التتارُ إلى الأبد، وسَبَوا من النساء والولدان ما ضاق به الفَضاءُ. وقيل: إن الخليفة بقي أربعة أيام عند التتار، ثم دخل بغداد ومعه أمراء من المغول ونصير الطوسي، فأخرج إليهم من الأموال والجواهر والزركش والثياب والذخائر جملةً عظيمة، ورجَعَ ليَومِه، وقُتِلَ، وقُتِلَ ابناه أحمد وعبد الرحمن، وبَقِيَ ابنه الصغير مبارك، وأخواته فاطمة، وخديجة، ومريم، في أَسْرِ التتار\"، وقُتِلَ عدد من أعمام الخليفة وأقاربه, وقيل كانت المغول بقيادة هولاكو قد أخذوه وكانوا أولًا يهابون قَتْلَه، ثم هون عليهم ابن العلقمي والطوسي قَتْلَه فقُتل, وكان عمره يومئذ ستًّا وأربعين سنة وأربعة أشهر، ومدة خلافته خمس عشرة سنة وثمانية أشهر، به انتهت الخلافة العباسية وانقضت أيامُها، وبقي الناسُ بلا خليفة فكانت أيامُ الدولة العباسية جملةً خمسمائة سنة وأربع وعشرون سنة."},{"id":2636,"title":"وفاة الوزير الرافضي ابن العلقمي الذي كان سبباً في سقوط بغداد .","date":["العام الهجري :656","الشهر القمري : جمادى الآخرة","العام الميلادي :1258"],"text":"هو الوزيرُ, المُدْبر، المُبير, وزيرُ العراق، أبو طالب مؤيد الدين محمد بن أحمد بن علي بن أبي طالب بن محمد العلقمي البغدادي،  وزير المستعصم بالله. كان عنده فضيلةٌ في الإنشاء والأدب، لكنه كان رافضيًّا شيعيًّا جَلْدًا خَبيثًا داهيةً- لَعَنه اللهُ- استوزره الخليفةُ المستعصِمُ بالله سنة 642 وكان مشؤومًا على نفسِه، وعلى أهل بغداد، ورديء الطويَّة على الإسلام وأهله،  ولم يُعصَم المستعصم في وزارته، فإنه لم يكن وزيرَ صِدقٍ ولا مرضيَّ الطريقة؛ فإنه هو الذي أعان على المسلمينَ في قضية هولاكو وجنوده في سقوط بغداد، وارتكاب مذبحة فيها- قبَّحه الله. وقد حصل له من التعظيم والوجاهة في أيام المستعصم ما لم يحصُلْ لِغَيرِه من الوزراء. ثم إنَّ ابنَ العلقمي عَمِلَ على ألَّا يُخطَب بالجوامِعِ، ولا تُصَلى الجماعة، وأن يبني مدرسةً على مذهب الشيعة، فلم يحصل له أمَلُه، وفُتِحَت الجوامع، وأُقِيمَت الجماعات. وقد رد كيدَه في نحرِه، وأذَلَّه بعد العزة القعساء، وصار ذليلًا عند التَّتارِ بعد ما كان وزيرًا للخُلَفاء! واكتسب إثمَ من قُتِلَ ببغداد من الرجال والنساء والأطفال، فالحُكمُ لله العليِّ الكبيرِ رَبِّ الأرض والسماء، وأراد الوزيرُ ابن العلقمي- قَبَّحه الله ولَعَنَه- أن يعَطِّلَ المساجد والمدارس والرُّبُطَ ببغداد، ويستَمِرَّ بالمَشاهد ومحالِّ الرفض، وأن يبني للرَّافضة مدرسةً هائلة ينشرون عِلمَهم بها وعليها، فلم يُقدِرْه الله تعالى على ذلك، بل أزال نعمتَه عنه وقَصَفَ عمره بعد شهورٍ يسيرةٍ مِن سقوط بغداد على أيدي المغولِ، فلم يمهِلْه اللهُ ولا أهمَلَه، بل أخذه أخذَ عزيزٍ مُقتَدِرٍ، في مستهلِّ جمادى الآخرةِ عن ثلاث وستين سنة، فمات جَهدًا وغَمًّا وحزنًا وندمًا، حيث كان يظنُّ أنَّ التَّتارَ ستُكرِمُه أكثَرَ مما كان مُكرَّمًا في بني العباس، فأخزاه الله فنَزَل من رتبةِ الوزارة إلى رتبةِ الخَدَمِ، وقد رأته يومًا امرأةٌ وهو يقادُ به وهو راكبٌ على بِرذَون، وكان قبل ذلك يسيرُ في موكبٍ وأبَّهةٍ، فقالت له: أهكذا كان يعامِلُك بنو العبَّاسِ؟!! فكانت هذه الكَلِمةُ سَببًا في زيادة كَمَدِه وغَمِّه، فوقعت كلمتُها في قلبه وانقطع في دارِه إلى أن مات كمدًا وغبينةً وضيقًا، وقِلَّة وذِلَّة، فلم يلبث بعدها يسيرًا حتى هلك- عامله اللهُ بما يستحِقُّ- ودفن في قبور الروافض، وقد سَمِعَ بأذنيه، ورأى بعينيه من الإهانةِ مِن التتارِ والمسلمينَ ما لا يُحَدُّ ولا يوصف. وكانت دولتُه أربع عشرة سنة."},{"id":2637,"title":"وفاة الحافظ المنذري .","date":["العام الهجري :656","الشهر القمري : ذي القعدة","العام الميلادي :1258"],"text":"هو الإمام العلامة الحافظ المحقِّق شيخ الإسلام: أبو محمد زكي الدين عبد العظيم بن عبد القوي بن عبد الله بن سلامة بن سعد بن سعيد المنذري، الشامي الأصل، المصري، الشافعي. أصلُه من الشام وولد بمصر، وكان شيخَ الحديث بها مدةً طويلة، إليه الوِفادةُ والرحلة من سنين متطاولة، وقيل: إنه وُلِدَ بالشام في غرة شعبان، سنة 581. كان متينَ الديانة، ذا نسُك وورع وسَمت وجلالة, وسمِعَ الكثير ورحل وطلَب وعُني بهذا الشأن، حتى فاق أهلَ زَمانه فيه، قال الحافظُ الشريف عز الدين الحسيني: \"درَّس شيخُنا الحافظ المنذري بالجامع الظافري، ثم وليَ مشيخةَ الدار الكامليَّة، وانقطع بها عاكفًا على العلم، وكان عديمَ النظير في علم الحديث على اختلافِ فنونه. كان ثقةً حُجَّةً متحرِّيًا زاهدًا, ثَبتًا إمامًا ورِعًا عالِمًا بصحيحِ الحديث وسقيمِه، ومعلوله وطرقه، متبحرًا في معرفة أحكامه ومعانيه ومُشكِله، قيمًا بمعرفة غريبه وإعرابه واختلافِ ألفاظه، قرأتُ عليه قطعة حسنة من حديثه، وانتفعتُ به كثيرًا\". قال: الذهبي قال: شيخنا الدمياطي: \"الحافظُ المنذر هو شيخي ومخرجي، أتيته مبتدئًا، وفارقته معيدًا له في الحديث\" صنَّفَ وخرج، واختصر (صحيح مسلم)، و(سنن أبي داود وشرحه)، وله (كتاب الترغيب والترهيب) المشهور، وله كتاب (الجمع بين الصحيحين)، وله اليد الطولى في اللغة والفقه والتاريخ، توفي يوم السبت رابعَ ذي القعدة من هذه السنة بدار الحديث الكامليَّة بمصر، ودُفِن بالقرافة."},{"id":2638,"title":"المغول ينذرون صاحب دمشق ويطلبون منه تسليمها .","date":["العام الهجري :657","العام الميلادي :1258"],"text":"أرسل الملك الغاشم هولاكو خان إلى المَلِك الناصر صاحِبِ دمشق يستدعيه إليه، فأرسل إليه ولَدَه العزيز وهو صغيرٌ ومعه هدايا كثيرةٌ وتُحَف، فلم يحتَفِلْ به هولاكو خان بل غضب على أبيه إذ لم يُقبِلْ إليه، وأخذ ابنُه، وقال: أنا أسير إلى بلاده بنفسي، فانزعج الناصِرُ لذلك، وبعث بحريمِه وأهله إلى الكرك ليحَصِّنَهم بها وخاف أهلُ دمشق خوفًا شديدًا، ولا سيما لما بلغهم أن التتار قد قطعوا الفرات، فسافر كثيرٌ منهم إلى مصر في زمن الشتاء، فمات ناسٌ كثير منهم ونُهبوا، ثم رجع العزيزُ بن الملك الناصر من عند هولاكو، وعلى يده كتابُه ونصه: الذي يعلمُ به الملك الناصر صاحب حلب أنا نحن قد فتحنا بغدادَ بسيف الله تعالى، وقتَلْنا فُرسانَها وهَدَمْنا بُنيانَها وأسَرْنا سكانها، كما قال الله تعالى في كتابه العزيز: {قَالَتْ إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَةً أَفْسَدُوهَا وَجَعَلُوا أَعِزَّةَ أَهْلِهَا أَذِلَّةً وَكَذَلِكَ يَفْعَلُونَ}، واستحضرنا خليفتَها وسألناه عن كلماتٍ فكذب، فواقعه الندمُ واستوجب منا العَدَم، وكان قد جمع ذخائرَ نفيسة، وكانت نفسُه خسيسة فجمع المال ولم يعبأ بالرِّجال، وكان قد نمى ذكرُه وعظُمَ قدره، ونحن نعوذ بالله من التمام والكمال، إذا وقفت على كتابي هذا، فسارع برجالِك وأموالِك وفرسانك إلى طاعةِ سلطان الأرض شاهنشاه روي زمين، تأمن شرَّه وتنل خيرَه، كما قال الله تعالى في كتابه العزيز: {وَأَنْ لَيْسَ لِلْإِنْسَانِ إِلَّا مَا سَعَى * وَأَنَّ سَعْيَهُ سَوْفَ يُرَى * ثُمَّ يُجْزَاهُ الْجَزَاءَ الْأَوْفَى} ولا تعوِّقْ رُسُلَنا عندك كما عوَّقْت رسلَنا من قبل، فإمساكٌ بمعروفٍ أو تسريحٌ بإحسانٍ، وقد بلغنا أن تجار الشام وغيرهم انهزموا بأموالِهم وحريمهم إلى كروان سراي فإن كانوا في الجبالِ نسفناها، وإن كانوا في الأرضِ خسفناها، فانزعج الناصِرُ, وبعث عندما بلغه توجه هولاكو نحو الشام بالصاحِبِ كمال الدين عمر بن العديم إلى مصر، يستنجِدُ بعَسكَرِها."},{"id":2639,"title":"هولاكو يهدد السلطان المظفر سيف الدين قطز .","date":["العام الهجري :657","العام الميلادي :1258"],"text":"بعد أن سقطت بغدادُ بيد هولاكو زحف إلى الشَّامِ واستولى عليها وأنذر سيفَ الدين قطز حاكِمَ مِصرَ يريد بذلك إخافتَه، وذلك أنه يريد أن يُكمِلَ زَحفَه على مصر وإنهاءَ حكم المماليك بعد أن أنهى الدَّولةَ العباسيَّة، ولكن المظفَّرَ قطز كان يجهِّزُ جيشًا لملاقاتِه، ثم قدَّر الله أن يعودَ هولاكو بسبب عصيانِ الأمراءِ في بلادِه عليه فذهب وترك بعضَ عساكره في الشامِ والذين قاتَلَهم المظفر سيف الدين قطز في عينِ جالوت."},{"id":2640,"title":"سيف الدين قطز يقبض على الملك المنصور صاحب مصر .","date":["العام الهجري :657","الشهر القمري : ذي القعدة","العام الميلادي :1259"],"text":"بعد أن جاءت الأخبارُ بتحَرُّك المغول إلى الشام وبَعْثهم الرسائِلَ التهديديَّة للأمراء عقَدَ الأمير سيف الدين قطز في مصر اجتماعًا حضره الفُقَهاءُ وعلى رأسِهم العِزُّ بن عبد السلام بأخذ أموالٍ مِن العامَّة لتجهيز الجيوشِ, ثم قبض قطز على الملك نور الدين عليِّ بن المعز أيبك الملقَّب بالمنصور صاحب مصر، وذلك في غيبةِ أكثر الأمراءِ مِن مماليك أبيه وغيرِهم في الصيد، فلمَّا قبض على المنصور بَعَث به وبأخيه وأمِّه إلى دمياط، واعتَقَلَهم في برج عَمَرَه وسماه برجَ السلسلة، ثم سيَّرَهم إلى بلاد الأشكري وقبض على بعضِ الأمراء واعتقَلَهم وتسلطَنَ هو وسمَّى نفسَه بالملك المظفَّر، واعتذر إلى الفُقَهاءِ والقُضاة وإلى ابن العديم الرَّسول الذي جاء من الشامِ لمساعدتهم ضِدَّ المغول، فإنه قال: لا بدَّ للناسِ مِن سلطانٍ قاهرٍ يقاتِلُ عن المسلمين عَدُوَّهم، وهذا صبيٌّ صغير لا يعرفُ تدبير المملكةِ، فكانت مدَّة المنصور سنتين وثمانية أشهر وثلاثة أيام، وكانت قد كثُرَت مفاسد الملك المنصور علي، واستهتر في اللَّعِب وتحكَّمَت أمُّه فاضطربت الأمور، فجلس المظفَّر سيف الدين  قطز على سريرٍ بقلعة الجبل يوم السبت الرابع والعشرين من ذي القعدة، وهو ثالثُ ملوك المماليك بمصر، وقطز بضم القاف والطاء المهملة وسكون الزاي، وهو لفظٌ مَغولي."},{"id":2641,"title":"اتفاق أحوال عجيبة في ولاية الأمر بالشام  .","date":["العام الهجري :658","العام الميلادي :1259"],"text":"اتَّفَق في هذا العام أمورٌ عجيبة، وهي أن أوَّلَ هذه السنة كانت الشامُ للسلطان الناصر بن العزيز، ثمَّ في النصف من صفر صارت لهولاكو مَلِك التتار، ثمَّ في آخر رمضان صارت للمظَفَّر قطز، ثمَّ في أواخر ذي القَعدة صارت للظاهِرِ بيبرس، وقد شاركه في دمشقَ الملك المجاهد سنجر، وكذلك كان القضاءُ في أولها بالشام لابن سنى الدولة صدر الدين، ثم صار للكمال عمر التفليسي من جهة هولاكو، ثم لابن الزكي ثم لنجم الدين بن سنى الدولة."},{"id":2642,"title":"محاولة انقلاب فاشلة على المظفر سيف الدين قطز سلطان مصر .","date":["العام الهجري :658","العام الميلادي :1259"],"text":"ثار جماعةٌ مِن السودان والركبدارية والغِلمان على حاكِمِ مِصرَ السُّلطان سيفُ الدين قطز، وفتحوا دكاكينَ السيوفيِّين بين القصرين وأخذوا ما فيها من السِّلاحِ، واقتحموا اصطبلات الأجناد وأخذوا منها الخيولَ، وكان الحامِلُ لهم على هذا رجلٌ يعرف بالكوراني، أظهَرَ الزُّهدَ بيَدِه سبحةٌ وسكن قبة بالجبل، وتردَّد إليه الغلمان فحَدَّثَهم في القيام على أهل الدولة، وأقطعهم الإقطاعاتِ وكتب لهم بها رقاعًا، فلما ثاروا في الليل ركب العسكرُ وأحاطوا بهم وربطوهم، فأصبحوا مصلَّبينَ، خارج باب زويلة، وسكَنَت الثائرةُ."},{"id":2643,"title":"سقوط حلب بيد المغول واستباحتها .","date":["العام الهجري :658","العام الميلادي :1259"],"text":"كان التتارُ قد نزلوا على حَلَب في ذي القعدة سنة 556 ولم يدخُلوها, ثم عادوا إليها في ثاني صفر مِن هذه السَّنة, وحاصروها حتى استولَوا عليها في تاسِع صَفَر بالأمان، فلمَّا مَلَكوها غَدَروا بأهل حلب وقتَلوا ونَهَبوا وسَبَوا وفعلوا تلك الأفعالَ القبيحة على عادةِ فِعلِهم."},{"id":2644,"title":"كيف استهلت أول سنة للمسلمين بعد سقوط الخلافة العباسية .","date":["العام الهجري :658","الشهر القمري : محرم","العام الميلادي :1260"],"text":"استهلَّت هذه السَّنةُ بيوم الخميسِ، وليس للناس خليفةٌ، ومُلك العراقين وخراسان وغيرها من بلاد المشرق للطاغية هولاكو خان ملك التَّتار، وسُلطان ديار مصرَ للمظفَّر سيف الدين قطز، مملوكِ المعزِّ أيبك التركماني، وسلطانُ دمشقَ وحَلَب للملك الناصر بن العزيز بن الظاهر، وبلادُ الكرك والشوبك للمَلِك المغيث بن العادل بن الكامل محمد بن العادل أبي بكر بن أيوب، وهو حربٌ مع الناصِرِ صاحِبِ دمشق على المصريِّين، ومعهما الأميرُ ركن الدين بيبرس البندقداري، وقد عزموا على قتال المصريِّينَ وأخذِ مِصرَ منهم."},{"id":2645,"title":"سقوط دمشق في أيدي المغول وتمكين النصارى فيها .","date":["العام الهجري :658","الشهر القمري : صفر","العام الميلادي :1260"],"text":"أرسل هولاكو وهو نازلٌ على حلب جيشًا مع أميرٍ مِن كبار دولته يقال له كتبغانوين، فوردوا دمشقَ في آخر صفر فأخذوها سريعًا من غير ممانعة ولا مدافع، بل تلقَّاهم كبارها بالرَّحبِ والسعة، وقد كتب هولاكو أمانًا لأهل البلد، فقُرئ بالميدانِ الأخضر ونودي به في البلد، فأمِنَ الناس على وجَلٍ مِن الغدر، كما فعل بأهلِ حلب، هذا والقلعةُ ممتنعةٌ مستورة، وفي أعاليها المجانيقُ منصوبة والحالُ شديدة، فأحضر التتارُ منجنيقًا يُحمَلُ على عجل والخيولُ تجُرُّه، وهم راكبون على الخيلِ وأسلحتهم على أبقار كثيرة، فنصب المنجنيقَ على القلعة من غربيها، وخرَّبوا حيطانًا كثيرةً وأخذوا حجارتَها ورَموا بها القلعةَ رميًا متواترًا كالمطر المتدارك، فهدموا كثيرًا من أعاليها وشرفاتها وتداعت للسقوطِ فأجابهم متوليها في آخِرِ ذلك النهارِ للمصالحة، ففتحوها وخَرَّبوا كل بدنة فيها، وأعالي بروجِها، وذلك في نصف جمادى الأولى من هذه السنة، وقتلوا المتوليَ بها بدر الدين بن قراجا، ونقيبَها جمال الدين بن الصيرفي الحلبي، وسَلَّموا البلد والقلعة إلى أميرٍ منهم يقال له إبل سيان، وكان- لعنه الله- مُعظِّمًا لدين النصارى، فاجتمع به أساقفتُهم وقسوسهم، فعظَّمَهم جدًّا، وزار كنائِسَهم، فصارت لهم دولةٌ وصولة بسببه، وذهب طائفةٌ من النصارى إلى هولاكو وأخذوا معهم هدايا وتحفًا، وقَدِموا من عنده ومعهم أمانٌ مِن جهته، ودخلوا من بابِ توما ومعهم صليبٌ منصوب يحملونه على رؤوسِ النَّاسِ، وهم ينادون بشعارِهم ويقولون: ظهر الدين الصحيح دين المسيح، ويذمُّون دينَ الإسلام وأهله، ومعهم أوان فيها خمرٌ لا يمرون على باب مسجد إلا رشُّوا عنده خمرًا، وقماقم ملآنة خمرًا يرشون منها على وجوه الناس وثيابهم، ويأمرون كل من يجتازونَ به في الأزقَّة والأسواق أن يقوم لصليبِهم، ودخلوا من دربِ الحَجَر فوقفوا عند رباط الشيخِ أبي البيان، ورشوا عنده خمرًا، وكذلك على باب مسجدِ درب الحجر الصغير والكبير، واجتازوا في السوقِ حتى وصلوا درب الريحان أو قريبًا منه، فتكاثر عليهم المسلمونَ فردُّوهم إلى سوق كنيسة مريم، فوقف خطيبُهم إلى دكة دكان في عطفة السوق فمدح دينَ النصارى وذمَّ دين الإسلام وأهله، ثم دخلوا بعد ذلك إلى كنيسة مريمَ وكانت عامرة، ولكن هذا سببُ خرابها، وضربوا بالناقوسِ في كنيسة مريم ودخلوا إلى الجامع بخمرٍ وكان في نيَّتِهم إن طالت مدة التتار أن يخرِّبوا كثيرًا من المساجد وغيرها، ولما وقع هذا في البلد اجتمع قضاةُ المسلمين والشهود والفقهاء فدخلوا القلعةَ يشكون هذا الحالَ إلى متسِلِّمِها إبل سيان فأُهينوا وطُردوا، وقَدَّم كلامَ رؤساء النصارى عليهم، وهذا كان في أول هذه السَّنة وسلطان الشام الناصر بن العزيز مقيمٌ في وطأة برزة، ومعه جيوشٌ كثيرة من الأمراء وأبناء الملوك ليناجِزوا التتار إن قَدِموا عليهم، وكان في جملة من معه الأمير بيبرس البندقداري في جماعةٍ مِن البحرية، ولكِنَّ الكلمة بين الجيوش مختلفةٌ غير مؤتلفة، لِما يريدُه الله عزَّ وجلَّ، وقد عَزَمت طائفةٌ من الأمراء على خلعِ الناصر وسَجنِه ومبايعة أخيه وشقيقِه الملك الظاهِرِ علي، فلما عرف الناصِرُ ذلك هرب إلى القلعةِ وتفَرَّقت العساكر شذَرَ مَذَرَ، وساق الأمير ركن الدين بيبرس في أصحابِه إلى ناحية غزة، فاستدعاه الملك المظفَّر قطز إليه واستقدمه عليه، وأقطعه قليوبَ، وأنزله بدار الوزارة وعَظَّم شأنَه لديه."},{"id":2646,"title":"المماليك يهزمون المغول في موقعة عين جالوت بقيادة المظفر قطز .","date":["العام الهجري :658","الشهر القمري : رمضان","العام الميلادي :1260"],"text":"لمَّا بلغ الملك المظفَّر سيف الدين قُطز صاحِبَ مِصرَ أنَّ التتارَ قد فعلوا بالشَّامِ ما فعلوه، وقد نهَبوا البلاد كلَّها حتى وصلوا إلى غزَّة، وقد عزم كتبغانوين نائب هولاكو في الشام على الدخولِ إلى مصر، وكان إذ ذاك في البقاع فاستشار الأشرفَ صاحِبَ حمص والمجير بن الزكي، فأشاروا عليه بأنَّه لا قِبَل له بالمظفَّر حتى يستَمِدَّ هولاكو فأبى إلا أن يناجزه سريعًا، فبادرهم  المظفَّر قطز قبل أن يبادِروه ويبرز إليهم وقد اجتمعت الكلمةُ عليه، فبعد قدومِ الصاحب كمال الدين بن العديم رسولًا من الشام يطلبُ النَّجدةَ على التتار، جمعَ قُطز الأمراءَ‍ والأعيان، وحضر معهم الشيخُ عز الدين بن عبد السلام والقاضي بدر الدين السنجاري، وجلس المَلِكُ المنصور في دَست السلطنة، فاعتمدوا على ما يقولُه الشيخ عز الدين، فكان خلاصته: \"إذا طرق العدوُّ البلادَ وجب على العالمَ كُلِّهم قتالُهم، وجاز أن يؤخَذَ مِن الرعيَّة ما يُستعانُ به على جهادِهم، بشرط ألَّا يبقى في بيتِ المال شيءٌ، وأن تبيعوا ما لكم من الحوائِصِ والآلاتِ، ويَقتَصِر كل منكم على فَرَسِه وسلاحِه، ويتساووا في ذلك هم والعامَّة، وأما أخذ أموال العامة مع بقاءِ ما في أيدي الجُندِ مِن الأموال والآلاتِ الفاخرةِ فلا\"، ثم بعد أيامٍ يسيرةٍ قَبَضَ على المنصور علي بن المعز وقال: هذا صبيٌّ والوقت صعبٌ، ولا بد من أن يقوم رجلٌ شجاع ينتصب للجهادِ فقبض عليه، وتسلطَنَ وتلقَّبَ بالملك المظفر. ثم قَدِمَ الأمير ركن الدين بيبرس البندقداري من دمشق مهاجرًا إلى مصرَ؛ لخدمة الملك المظفر سيف الدين قطز, فدخل القاهرةَ يوم السبت ثاني وعشرين ربيع الأول سنة ثمان وخمسين، فركب المظفَّر للقائه وأنزله في دارِ الوَزارة وأقطعه قَصبةَ قيلوب لخاصَّتِه، وأشار عليه بيبرس بملاقاة التتار وقَوَّى جأشَه وحَرَّك عزائمه وحرَّضَه على التوجه للقائهم, فخرج المظفَّر قطز يوم الاثنين خامس عشر شعبان بجميع عساكِرِ مِصرَ مع ما انضاف إليهم من العَرَب وغيرهم لقصدِ التتار الذين بالشَّامِ، فلما وصل إلى مرج عكا بلغ بكتبغانوين، مُقَدَّمَ عسكر التتار بالشام خروجُ الملك المظفَّر، وكان في بلد حمص فتوجَّه إلى الغور، وبعث الملك المظفر للأمير ركن الدين البندقداري  في عسكرٍ ليتجَسَّس خبَرَ التتار،  فلما وقعت عينُه عليهم كتب للملك المظفر يعلِمُه بوصولهم ثمَّ انتهز الفرصةَ في مناوشتهم، فلم يزل يستدرجُهم تارة بالإقبال وتارة بالإحجام حتى وافى بهم إلى المَلِك المظفَّر على عين جالوت فكانت الوقعةُ التي أيَّدَ الله بها المُسلِمينَ على التتارِ،  وأخَذَ بها منهم ثأرَ أهلِ الوَبَر والمَدَر، وحاقَ بهم مَكرُ السَّيفِ، وحكَمَ فيهم الحَتفُ بالحَيفِ، وقَتَلوهم وأخذوهم ومعهم مَلِكُهم كتبغانوين، فقُتِلَ وأُخِذَ رأسُه وأُسِرَ ابنه، وكانت الوقعةُ بين المسلمين والتتار  على ((عين جالوت)) يومَ الجمعة خامس وعشرين من شهر رمضان المعظَّم، ووصل الخبَرُ إلى دمشق في ليلة السابع والعشرين من شهر رمضان فانهزم بتلك الليلة من كان بدمشقَ مِن التتار وأيل سبان نائب الملك وأتباعهم، وتبعهم النَّاسُ وأهل الضياع ينهبونهم ويقتلونَ مَن ظَفِروا به، فلله الحمدُ والشُّكر, ودخل السلطانُ الملك المظفَّر إلى دمشق يوم الأحد رابع شوال، فأقام بها إلى أن خرج منها طالبًا للدِّيار المصرية, ومن العجائِبِ أن التتار كُسِروا وأُهلِكوا بأبناء جنسِهم المماليكِ، وهم من التركِ!! وعَمِل الشيخُ شهاب الدين أبو شامة في ذلك شِعرًا:غلبَ التَّتارُ على البلادِ فجاءهم مِن مِصرَ تركيٌّ يجودُ بنَفسِهبالشَّامِ بدَّدَهم وفَرَّق شَملَهم ولكلِّ شَيءٍ آفةٌ مِن جِنسِه وقد قاتل الملكُ المنصورُ صاحِبُ حماة مع المَلِك المظفَّر قِتالًا شَديدًا، وكذلك الأميرُ فارس الدين أقطاي المستعرب، وكان أتابك العسكَر، وقد أُسِرَ من جماعة كتبغانوين المَلِك السعيد بن العزيز بن العادل فأمَرَ المظفَّر بضَرب عُنُقِه، واستأمن الأشرفُ صاحِبُ حمص، وكان مع التَّتارِ وقد جعله هولاكو خان نائبًا على الشام كُلِّه، فأمنه الملك المظفَّر ورَدَّ إليه حمص، وكذلك ردَّ حماة إلى المنصور وزاده المَعَرَّة وغيرها، وأطلق سلمية للأميرِ شَرَف الدين عيسى بن مهنا بن مانع أمير العرب، واتَّبَع الأميرُ بيبرس البندقداري  وجماعةٌ من الشجعان التتارَ يقتُلونَهم في كل مكان، إلى أن وصلوا خلفَهم إلى حَلَب، وهرب مَن بدمشقَ منهم يوم الأحد السابع والعشرين من رمضان، فتبعهم المسلمون من دمشق يقتلونَ فيهم ويفتِكونَ الأسارى من أيديهم، وجاءت بذلك البشارةُ، ولله الحمدُ على جبرِه إيَّاهم بلُطفِه فجاوبتها دقُّ البشائر من القلعة، وفرح المؤمنون بنصر الله فرحًا شديدًا، وأيَّدَ اللهُ الإسلامَ وأهله تأييدًا وكَبَت الله النصارى واليهودَ والمنافقين، وظهر دينُ الله وهم كارهون، فتبادر عند ذلك المسلمونَ إلى كنيسة النصارى التي خرج منها الصَّليبُ فانتَهَبوا ما فيها وأحرقوها وألقوا النَّارَ فيما حولها، فاحترق دُورٌ كثيرةٌ إلى النصارى، وملأ اللهُ بيوتَهم وقبورَهم نارًا، وأُحرِقَ بعضُ كنيسةِ اليعاقبة، وهمَّت طائفةٌ بنَهبِ اليهود، فقيل لهم إنَّه لم يكن منهم من الطغيانِ كما كان من عَبَدة الصُّلبان، وقَتَلَت العامَّة وسطَ الجامِعِ شَيخًا رافضيًّا كان مُصانِعًا للتتار على أموالِ النَّاسِ يقال له الفخر محمد بن يوسف بن محمد الكنجي، كان خبيثَ الطويَّة مشرقيًّا ممالئًا لهم على أموالِ المسلمين- قبَّحه الله- وقَتَلوا جماعةً مِثلَه من المنافقين، فقُطِعَ دابِرُ القَومِ الذين ظَلَموا والحمدُ لله رب العالَمينَ."},{"id":2647,"title":"هلاك قائد المغولي كتبغانوين نائب هولاكو بالشام .","date":["العام الهجري :658","الشهر القمري : رمضان","العام الميلادي :1260"],"text":"هو كتبغانوين نائب هولاكو على بلاد الشَّامِ- لعنه الله، ومعنى نوين يعني أمير عشرة آلاف، وكان هذا الخبيث قد فتح لأستاذه هولاكو من أقصى بلاد العَجَمِ إلى الشام، وقد أدرك جنكيزخان جد هولاكو، وكان كتبغا هذا يعتمد في حروبه للمسلمين أشياءَ لم يسبِقْه أحد إليها، فكان إذا فتح بلدًا ساق مقاتِلةَ هذا البلد إلى البلد الآخر الذي يليه، ويطلب من أهل ذلك البلد أن يُؤوا هؤلاء إليهم، فإن فعلوا حصل مقصودُه في تضييقِ الأطعمةِ والأشربةِ عليهم، فتقصُر مدَّة الحصارِ عليه لِما ضاق على أهلِ البلد أقواتُهم، وإن امتنعوا من إيوائِهم عندهم قاتَلَهم بأولئك المقاتِلة الذين هم أهلُ البلد الذي فتحه قبل ذلك، فإن حصل الفتحُ وإلَّا كان قد أضعَفَ أولئك بهؤلاء حتى يفني تلك المقاتِلةَ، فإن حصل الفتحُ وإلَّا قاتَلَهم بجُندِه وأصحابِه مع راحةِ أصحابِه وتَعَبِ أهلِ البلد المحاصَرِ وضَعفِهم فيفتَحُها سريعًا. كان شيخًا كبيرًا قد أسَنَّ وكان يميل إلى دين النصارى ولكن لا يمكِنُه الخروجُ مِن حكم جنكيزخان في الياسق. قال الشيخ قطب الدين اليونيني: وقد رأيتُه ببعلبك حين حاصر قلعتَها، وكان شيخًا حسنًا له لحية طويلة مسترسلة قد ضفَرَها مثل الدبوقة، وتارة يعلِّقُها من خَلفِه بأُذنِه، وكان مَهيبًا شديد السَّطوة، قال: وقد دخل الجامِعَ فصَعِدَ المنارة ليتأمَّل القلعة منها، ثم خرج من الباب الغربي فدخل دكانًا خرابًا فقضى حاجتَه والنَّاسُ ينظرون إليه وهو مكشوفُ العورة، فلما فرغ من حاجته مسحه بعضُ أصحابه بقطن ملبدٍ مَسحةً واحدة, وكان قاِئَد التتار في عين جالوت, فقُتِلَ في المعركة وأُسِرَ ابنُه، وكان شابًّا حسنًا، فأُحضِرَ بين يدي المظفَّر قطز فقال له أهَرَب أبوك؟ قال: إنَّه لا يهرب، فطلبوه فوجَدوه بين القتلى، فلما رآه ابنُه صرخ وبكى، فلما تحقَّقَه المظفر سجَدَ لله تعالى، ثم قال: أنامُ طَيِّبًا. كان هذا سعادةَ التتارِ وبقَتلِه ذهب سَعدُهم، وهكذا كان كما قال، ولم يفلحوا بعده أبدًا، وكان قتلُه يوم الجمعة الخامس والعشرين من رمضان، وكان الذي قتله الأميرُ جمال الدين آقوش الشمسي."},{"id":2648,"title":"اغتيال سيف الدين قطز سلطان دولة المماليك بمصر والشام .","date":["العام الهجري :658","الشهر القمري : ذي القعدة","العام الميلادي :1260"],"text":"هو السُّلطانُ الشهيدُ الملك المظفر، سيفُ الدين قطز محمود بن عبد الله التركي المعزي. كان أنبَلَ وأخَصَّ مماليك الملك المعز عز الدين أيبك التركماني، ثم صار نائِبَ السلطنة لوَلَدِه المنصور, ثالثِ سلاطين دولة المماليك في مصرَ والشام. كان شابًّا أشقرَ وافِرَ اللحية, فارسًا شجاعًا بطلًا، سائِسًا، دَيِّنًا، حازمًا، حسَنَ التدبيرِ، محَبَّبًا إلى الرعيَّة. كثير الخير ناصحًا للإسلام وأهله، وكان الناسُ يحبُّونَه ويدعون له كثيرًا. هزم التتار، وطهَّر الشام منهم يومَ عين جالوت، وهو الذي كان قَتَلَ فارس الدين أقطاي الجمداري، ويقال: إن قطز ابن أخت السلطان خوارزم شاه جلال الدين، وإنه حُرٌّ واسمُه محمود بن ممدود. لما قُتِلَ أستاذُه المعز عز الدين أيبك قام في توليةِ ولده المنصور علي، فلما سَمِعَ بأمر التتار خاف أن تختَلِفَ الكلمة لصِغَرِ سِنِّ المنصور علي, ودعا إلى نفسه، فبويع في ذي القعدة سنة 657، ثم سار إلى التتار فجعل اللهُ على يديه نصرة الإسلام والمسلمين. وكان اجتماعه مع عدوه في العشر الأخير من رمضان يوم الجمعة، حيث كان فيه نصرُ الإسلام والمسلمين. قال ابن كثير: \"لما كان يومُ المعركة بعين جالوت قُتِلَ جوادُه فترجَّلَ وبَقِيَ واقفًا على الأرض ثابتًا، والقتالُ يعمل في المعركة، وهو في موضِعِ القَلبِ، فلما رآه بعضُ الأمراء ترجَّل عن فرسه وحَلَف على السلطان ليركبَنَّها فامتنع، وقال لذلك الأمير: ما كنتُ لأحرِمَ المسلمينَ نَفعَك. ولم يزَلْ كذلك حتى جيءَ له بخيلٍ فرَكِبَه! فلامه بعض الأمراء وقال: يا خوند (يا سيد) لم لا ركبتَ فَرسَ فلان؟ فلو أنَّ بعض الأعداء رآك لقتلَكَ وهلك الإسلامُ بسَبَبِك، فقال: أمَّا أنا فكنتُ أروح إلى الجنة، وأمَّا الإسلامُ فله ربٌّ لا يضيعه، قد قُتِلَ فلان وفلان وفلان حتى عد خَلقًا من الملوك، فأقام للإسلامِ مَن يحفظُه غيرهم، ولم يضيِّع الإسلام\", ولما قدم دمشقَ في شوال أقام بها العَدلَ ورتَّبَ الأمور، وأرسل بيبرس خلف التتار ليخرِجَهم ويطرُدَهم عن حلب، ووعَدَه بنيابتِها فلم يفِ له لما رآه من المصلحةِ، فوقعت الوحشةُ بينهما, فلما فرَغ المظَفَّر من الشام ثم رجع إلى الديار المصرية والعساكر الإسلامية في خدمته، كان الأميرُ ركن الدين بيبرس البندقداري  قد اتَّفَق مع جماعةٍ مِن الأمراء على قتله، فلما وصلَ بين القرابي والصالحيَّة ضرب دهليزه وساق خَلفَ أرنب، وساق معه أولئك الأمراءَ فشَفَعَ عنده ركن الدين بيبرس في شيءٍ فشَفَّعَه، فأخذ يده ليُقَبِّلَها فأمسَكَها وحمل عليه أولئك الأمراءُ بالسيوف فضربوه بها، وألقوه عن فرَسِه ورشقوه بالنشَّاب حتى قتلوه ودفن بالقصر، وكان قُتله يوم السبت سادس عشر من ذي القعدة، وكانت مُدَّة ملكه من حين عَزَل ابنَ أستاذه المنصور عليِّ بن المعز التركماني إلى هذه المدة، وهي أواخِرُ ذي القعدة نحوًا من سنة، رحمه الله وجزاه عن الإسلامِ وأهله خيرًا."},{"id":2649,"title":"الركن بيبَرس البندقداري  يحكم مصر  .","date":["العام الهجري :658","الشهر القمري : ذي الحجة","العام الميلادي :1260"],"text":"بعد اغتيالِ سيف الدين قطز حار الأمراءُ فيما بينهم فيمن يوَلُّون المُلك، وصار كل واحد منهم يخشى غائلة ذلك، وأن يصيبه ما أصاب غيرَه سريعًا، فاتفقت كلمتُهم على أن بايعوا بيبرس البندقداري، ولم يكن هو مِن أكابِرِ المقَدَّمين، ولكن أرادوا أن يجرِّبوا فيه، ولقَّبَوه الملك الظاهِرَ، فجلس على سريرِ المملكة وحكمه، ودقت البشائِرُ وضُرِبَت الطبول والبوقات, وزعقت الشاووشية بين يديه، وكان يومًا مشهودًا ثم دخل مصرَ والعساكرُ في خدمته، فدخل قلعةَ الجبل وجلَسَ على كرسِيِّها، فحكَمَ وعدل، وقطع ووصل، وولَّى وعزل، وكان شهمًا شجاعًا, وكان أولًا لَقَّب نفسه بالملك القاهر، فقال له الوزير: إن هذا اللَّقَب لا يُفلِحُ من يلَقَّب به، تلقَّبَ به القاهرَ بن المعتمد فلم تطل أيامه حتى خُلِعَ وسُمِلَت عيناه، ولقب به القاهِرُ صاحب الموصل فسُمَّ فمات، فعدل عنه حينئذ إلى الملك الظاهر، ثم شرع في مَسكِ من يرى في نفسه رئاسةً مِن أكابر الأمراء حتى مهَّد المُلكَ لنَفسِه، ويُذكَرُ أن مولد بيبرس كان بصحراء القِبجاق, والقبجاق قبيلة عظيمة في الترك، وهو بكسر القاف وسكون الباء ثانية الحروف، أما بيبرس بسكون الياء المثناة من تحتها ثم فتح الباء الموحدة وسكون الراء والسين المهملتين ومعناه باللغة التركية: أمير فهد. أُخذ بيبرس من بلادِه وبِيعَ بدمشق للعِمادِ الصائغ، ثم اشتراه الأميرُ علاء الدين أيدكين الصالحي البندقداري وبه سمي البندقداري، ثم صادره منه المَلِكُ الصالح نجم الدين الأيوبي ثم أعتَقَه وجعله من جملةِ مماليكِه، وقَدَّمَه على طائفة الجمدارية-  الجمدار حامِلُ ملابس السلطانِ- لِما رأى من فِطنتِه وذكائِه."},{"id":2650,"title":"المغول يغيرون على حلب بعد هزيمتهم شمالي حمص .","date":["العام الهجري :659","العام الميلادي :1260"],"text":"أغار التتارُ على حلَب فلَقِيَهم صاحِبُها حسامُ الدين العزيزي، والمنصورُ صاحِبُ حماة، والأشرَفُ صاحِبُ حمص، وكانت الوَقعةُ شماليَّ حِمصَ قَريبًا من قَبرِ خالد بن الوليدِ، والتتار في ستة آلاف، والمسلمون في ألف وأربعمائة، فهزمهم الله عز وجل، وقتل المسلمونَ أكثَرَهم، فرجع التتار إلى حلب فحصروها أربعةَ أشهُر وضيَّقوا عليها الأقوات، وقَتَلوا من الغرباء خلقًا صبرًا، والجيوش الذين كسروهم على حمص مُقيمونَ لم يرجعوا إلى حلب بل ساقوا إلى مِصرَ، فتلقاهم الملك الظاهِرُ في أبَّهة السلطنة وأحسنَ إليهم، وبَقِيَت حلب محاصرة لا ناصِرَ لها في هذه المدة، ولكن سلم الله سبحانه وتعالى بتجهيز الظاهرِ بيبرس جيشًا إلى حلب ليطرُدَ التتار عنها، فلما وصل الجيشُ إلى غزة كتب الفرنجُ إلى التتار ينذِرونَهم، فرحلوا عنها مسرعينَ واستولى على حلب جماعةٌ من أهلها، فصادروا ونهبوا وبلغوا أغراضَهم، وقَدِمَ إليهم الجيش الظاهري فأزال ذلك كُلَّه، وصادروا أهلَها بألف ألف وستمائة ألف، ثم قَدِمَ الأمير شمس الدين آقوش التركي من جهة الظاهرِ فتسلم البلد فقطع ووصَل، وحكَمَ وعَدَل."},{"id":2651,"title":"كثرة الملوك والأمراء في البلدان الإسلامية بعد سقوط الخلافة العباسية .","date":["العام الهجري :659","الشهر القمري : محرم","العام الميلادي :1261"],"text":"استهَلَّت بيوم الاثنين لأيامٍ خَلَونَ مِن ديسمبر، وليس للمسلمينَ خليفة، وصاحب مكة أبو نمي بن أبي سعيد بن علي بن قتادة الحسني، وعمه إدريس بن علي شريكُه، وصاحِبُ المدينة الأميرُ عِزُّ الدين جماز بن شيحة الحسيني، وصاحِبُ مصر والشام السلطان الملك الظاهر بيبرس البندقداري، وشريكُه في دمشق وبعلبك والصبيبة وبانياس الأميرُ علم الدين سنجر الملقب بالملك المجاهد، وشريكُه في حلب الأمير حسام الدين لاشين الجوكنداري- حامل الجوكان مع السلطان في لعب الكُرة- العزيزي، والكرك والشوبك للملك المغيث فتح الدين عمر بن العادل بن سيف الدين أبي بكر الكاملِ محمد بن العادل الكبير سيف الدين أبي بكر بن أيوب، وحصن جهيون وبازريا في يد الأمير مظفر الدين عثمان بن ناصر الدين مكورس، وصاحِبُ حماة الملك المنصور بن تقي الدين محمود، وصاحِبُ حمص الأشرف بن المنصور إبراهيم بن أسد الدين الناصر، وصاحِبُ المَوصِل الملك الصالح بن البدر لؤلؤ، وأخوه الملك المجاهِد صاحِب جزيرة ابن عمر، وصاحبُ ماردين الملك السعيد نجم الدين ايل غازي بن أرتق، وصاحب بلاد الروم ركنُ الدين قلج أرسلان بن كيخسرو السلجوقي، وشريكُه في الملك أخوه كيكاوس والبلاد بينهما نصفَينِ، وسائرُ بلاد المشرق بأيدي التتار أصحاب هولاكو، وبلاد اليَمَن يملكها غيرُ واحد من الملوك، وكذلك بلادُ المغرب في كل قطر منها مَلِك."},{"id":2652,"title":"البيعة بالخلافة للمستنصر بالله في مصر  وتجهيزه لاستعادة بغداد .","date":["العام الهجري :659","الشهر القمري : رجب","العام الميلادي :1261"],"text":"كان المستنصِرُ بالله أبو القاسِمِ أحمَدُ بن أمير المؤمنين الظاهِر مُعتقَلًا ببغداد فأُطلِقَ، وكان مع جماعةِ الأعراب بأرض العراق، ثم قصَدَ الظاهر بيبرس حين بلغه تسلطُنَه بمصر، فقدم إليه بصحبته جماعةٌ مِن أمراء الأعراب عشرةٌ منهم الأمير ناصر الدين مهنا في ثامن رجب من هذه السنة، فخرج السلطانُ الظاهر ومعه الوزير والشهود والمؤذنون فتلَقَّوه وكان يومًا مشهودًا، وخرج أهلُ التوراة بتوراتهم، والنصارى بإنجيلهم، ودخل مِن باب النصر في أبهةٍ عظيمة، فلما كان يوم الاثنين ثالث عشر رجب جلس السلطان والخليفة بالإيوان بقلعةِ الجبل، والوزيرُ والقاضي والأمراء على طبقاتهم، وأثبت نَسَب الخليفة المستنصر بالله على الحاكِم تاج الدين بن الأعز، وهذا الخليفةُ هو أخو المستنصر باني المستنصريَّة، وعم المستعصِم بالله، فبويع بالخلافةِ بمصرَ، بايعه المَلِك الظاهر والقاضي والوزير والأمراء، وركب في دست الخلافةِ بديار مصر والأمراء بين يديه والناسُ حَولَه، وشَقَّ القاهرة في ذلك اليوم، وهو الخليفة الثامن والثلاثون من خلفاء بني العباس، بينه وبين العباس أربعة وعشرون أبًا، قال عز الدين بن عبد السلام: لما أخَذْنا في بيعة المستنصر باللهِ، قلت للملك الظاهر: بايِعْه، فقال: ما أُحسِنُ، لكن بايِعْه أنت أوَّلًا وأنا بعدك، فكان أوَّلَ من بايعه القاضي تاج الدين لما ثَبت نَسَبه، ثم السلطان ثم الشيخ عز الدين بن عبد السلام، ثم الأمراء والدولة، وخطب له على المنابر، وضُرِبَ اسمُه على السكة وكان مَنصِبُ الخلافة قد شغر منذ ثلاثِ سنين ونصف؛ لأنَّ المستعصم بالله قُتِلَ في أول سنة ست وخمسين وستمائة، وبويع هذا في يوم الاثنين في ثالث عشر رجب من هذه السنة، وقد أُنزل الخليفةُ المستنصر بالله  وحَشَمُه في البرج الكبير بقلعة الجبل، فلما كان يوم سابع رجب ركب في السواد وجاء إلى الجامِعِ بالقلعة فصَعِدَ المنبر وخطب خطبةً ذكر فيها شَرَفَ بني العباس، ثم استفتح فقرأ صدرًا من سورة الأنعام، ثم صلى على النبيِّ صلى الله عليه وسلم، ثم ترضى عن الصحابةِ ودعا للسلطان الظاهر، ثم نزل فصلى بالنَّاسِ فاستحسنوا ذلك منه، وكان وقتًا حسنًا ويومًا مشهودًا، ثم لما كان يوم الاثنين الرابع من شعبان، ركب الخليفةُ والسلطان والوزير والقضاة والأمراء وأهل الحَل والعَقدِ إلى خيمة عظيمةٍ قد ضُرِبَت ظاهِرَ القاهرةِ فجلسوا فيها، فأُلبِسَ الخليفةُ السلطان بيده خلعةً سوداء، وطوقًا في عنقه، وقيدًا في رجليه وهما من ذهب، ثمَّ إن الخليفة طلب من السلطان أن يجَهِّزَه إلى بغداد، فرتَّبَ السلطان له جندًا هائلة وأقام له من كل ما ينبغي للخلفاء والملوك، ثم سار السلطانُ بصحبته قاصدين دمشق فدخلوا دمشقَ يوم الاثنين سابع ذي القعدة، وكان يومًا مشهودًا، وصلَّيَا الجمعة بجامع دمشق، وكان دخولُ الخليفة من باب البريد، ودخل السلطانُ من باب الزيارة، وكان يومًا مشهودًا أيضًا، ثم جهَّزَ السلطان بيبرس الخليفةَ المستنصر بالله إلى بغداد ومعه أولاد صاحِبِ الموصل, وأنفق عليه وعليهم وعلى من استقَلَّ معه من الجيش الذين يَرِدونَ عنه من الذَّهَب العين ألف ألف دينار، وأطلق له وزاده، فجزاه الله خيرًا."},{"id":2653,"title":"بداية الخلاف بين هولاكو وابن عمه بركة خان .","date":["العام الهجري :660","العام الميلادي :1261"],"text":"كان سَبَبُ عداوة بركة خان وهولاكو أنَّ وقعةً كانت بينهما، قُتِلَ فيها ولد هولاكو وكُسِرَ عَسكَرُه وتمزَّقوا في البلاد، وصار هولاكو إلى قلعةٍ بوسط بحيرة أذربيجان محصورًا بها، وأرسَلَ إليه بركةُ يطلُبُ منه نصيبًا مما فتحه من البلاد وأخَذَه من الأموال والأسرار، على ما جرت به عادةُ ملوكهم، فقتَلَ رُسُلَه فاشتَدَّ غَضَبُ بركة، ومما زاد الخلافَ بينهما هو إسلامُ بركة خان وغَضَبُه على هولاكو مما فَعَله ببغداد وقَتْله للخليفة العباسي المستعصم بالله، وكاتب الظاهِرَ ليتَّفِقا على هولاكو، فلمَّا بلغ ذلك السلطانَ سُرَّ به، وفرح الناسُ باشتغال هولاكو عن قَصدِ بلاد الشام، وكتب السلطانُ إلى النواب بإكرام الوافديَّة من التتار، وكانوا مائتي فارسٍ بأهاليهم، فحَسُنَت حالهم، ودخل في الإسلامِ مَن لم يُسلِمْ مِن قبلُ، وكتب السلطانُ إلى الملك بركة كتابًا، وسيَّرَه مع الفقيه مجد الدين والأمير سيف الدين كسريك."},{"id":2654,"title":"قتل المغول الخليفة العباسي الجديد المستنصر بالله في بغداد .","date":["العام الهجري :660","الشهر القمري : محرم","العام الميلادي :1261"],"text":"هو أميرُ المؤمنينَ الخليفةُ المستنصِرُ بالله أبو القاسِمِ أحمد بن الظاهر بأمر الله محمد بن الناصر لدين الله أحمد بن المستضيء بالله الهاشمي العباسي، البغدادي، الأسود. ولي الخلافةَ بعد قتل ابن أخيه المستعصِم بالله بن المستنصر بالله منصور بثلاثِ سنينَ، في وقتٍ خلا فيه من خليفة للمسلمين. وكان شديدَ السُّمرة، جَسيمًا، عاليَ الهمة، شجاعًا، قال الإمام أبو شامة: في رجب قُرئ بالعادلية كتابُ السلطان الظاهِر بيبرس إلى قاضي القضاة نجمِ الدين بن سني الدولة بأنَّه قَدِمَ عليهم بمصر أبو القاسم أحمد بن الظاهر بن الناصر، وهو أخو المستنصر بالله، وأنه جمَعَ له الناسَ مِن الأمراء والعلماء والتجَّار، وأثبت نَسَبَه عند قاضي القضاة في ذلك المجلس، فلما ثبت بايعَه الناس، وبدأ بالبيعة القاضي تاج الدين، ثمَّ السلطان الملك الظاهر، ثم الكبار على مراتبهم، ونُقِشَ اسمُه على السكة، وخَطَب له ولُقِّبَ بلَقَب أخيه، وفَرِحَ النَّاسُ, ثم رتَّبَ له السلطان أتابكًا، وأستاذ دار، وشرابيًّا، وخزندارًا- ممسك خزانة المال-، وحاجِبًا، وكاتبًا، وعَيَّنَ له خزانةً وجُملةَ مماليك، ومائة فرس، وثلاثين بغلًا، وعشرة قطارات جمال، إلى أمثال ذلك, ثم عزم الخليفةُ على التوجه إلى العراق, فحَسَّن له السلطان ذلك وأعانه, وسار من مصر هو والسلطانُ في تاسع عشر رمضان فدخلوا دمشق في سابع ذي القعدة، ثم جهَّزَ السلطان الخليفةَ وأولاد صاحِبِ الموصل، وغَرِمَ عليه وعليهم من الذهب فوق الألف ألف دينار، فسار الخليفةُ ومعه ملوك الشرق: صاحِبُ الموصل، وصاحِبُ سنجار والجزيرة من دمشق في الحادي والعشرين من ذي القعدة، ثم نزل الخليفةُ بمن معه مشهدَ عليٍّ رضي الله عنه، ولما وصلوا إلى عانة وجدوا بها الحاكِمَ بأمر الله أحمد، ومعه نحوٌ من سبعمائة نفس فاستمالهم الخليفةُ المستنصر، وأنزل الحاكِمَ معه في دهليزه، وتسلَّم الخليفةُ عانة، فلما بلغ المغولَ وصولُ الخليفة المستنصر بالله العراق. خرج قرابغا مُقَدَّم التتار من بغداد- وكان قد استخلفه هولاكو عليها عند عودِه إلى بلاد الشرق- يريد لقاء الخليفة المستنصِر بالله ومحاربته، فنهب الأنبارَ وقَتَل جميعَ من فيها، وتلاحقت به بقيَّةُ التتار من بغداد، ولَقِيَهم الخليفة وقد رتَّب عسكره، فجعل التركمانَ والعرب جناحَي العسكر، واختص جماعةً جَعَلَهم في القلب، وحمَلَ بنفسه على التتار فكسَرَ مُقَدِّمَتَهم، وخذله العربُ والتركمان فلم يقاتِلوا، وخرج كمينٌ للتتار ففَرَّ العرب والتركمان، وأحاط التتار بمن بقي معه فلم يُفلِتْ منهم سوى الأميرِ أبي العباس أحمد الذي قَدِمَ إلى مصر بعد ذلك وتلَقَّب بالحاكم بالله، والأميرُ ناصر الدين بن مهنا، والأميرُ ناصر الدين بن صيرم، والأميرُ سابق الدين بوزبا الصيرفي، والأمير أسد الدين محمود، في نحو خمسينَ من الأجناد، ولم يُعرَف للخليفةِ خبَرٌ، فيقال قُتِلَ بالمعركة في ثالث المحرم، ويقال بل نجا مجروحًا في طائفةٍ مِن العرب فمات عندهم، وكانت هذه الواقعةُ في العشر الأول من المحرم، فكانت خلافتُه دون السَّنة، وبلغت نفقةُ الملك الظاهر على الخليفةِ والملوك المواصلة ألف ألف دينار وستين ألف دينار عينًا."},{"id":2655,"title":"وفاة الأمير الوزير كمال الدين بن العديم .","date":["العام الهجري :660","الشهر القمري : جمادى الأولى","العام الميلادي :1262"],"text":"هو الأميرُ الوزير والرئيس الكبير، كمال الدين أبو القاسم عمر بن أحمد بن هبة الله بن محمد بن هبة الله بن أحمد بن يحيى بن زهير بن هارون بن موسى بن عيسى بن العديم العقيلي الحنفي الحلبي، ولد سنة 586، سمع الحديث وحَدَّث وتفَقَّه وأفتى ودرَّس وصنف، وكان إمامًا في فنونٍ كثيرة، وقد ترسل إلى الخلفاء والملوك مرارًا عديدة، وكان يكتُبُ حَسنًا طريقة مشهورة، وصنف لحلب تاريخًا مفيدًا قريبًا في أربعين مجلدًا، وكان جيد المعرفة بالحديث، حسنَ الظَّنِّ بالفقراء والصالحين كثيرَ الإحسان إليهم، وقد أقام بدمشقَ في الدولة الناصرية المتأخرة، وكانت وفاتُه بمصر، ودُفِنَ بسفح الجبل المقطم بعد الشيخ عز الدين بعشرة أيام."},{"id":2656,"title":"وفاة العلامة سلطان العلماء العز بن عبد السلام   .","date":["العام الهجري :660","الشهر القمري : جمادى الأولى","العام الميلادي :1262"],"text":"هو العلَّامة أبو محمد عبد العزيز بن عبد السلام بن القاسم بن الحسن بن محمد المهذب، المشهورُ بالعز بن عبد السلام السلمي الدمشقي الشافعي شيخ المذهب ومُفيدُ أهله، وله مصنَّفاتٌ حِسانٌ، منها التفسير الكبير، واختصار النهاية، والقواعد الكبرى والصغرى قواعد الأحكام في مصالح الأنام، وكتاب الصلاة، والفتاوى الموصلية، وغير ذلك، ولد سنة 578 وقيل سنة سبع، وسَمِعَ كثيرًا، واشتغل على فخر الدين بن عساكر وغيره، وبرع في المذهَبِ وجَمَعَ عُلومًا كثيرة، وأفاد الطلبةَ ودَرَّسَ بعدة مدارس بدمشق، وولي خطابتَها ثم نفاه صاحِبُها إلى مصر بسَبَبِ أنَّه شنع عليه لتسليمه صفد والشقيف للصليبيين لقاءَ مساعدته على صاحبِ مصر، فدَرَّس بمصرَ وخَطَب وحكم. قال الذهبي: \" دخل الشيخ عز الدين بن عبد السلام الشافعي إلى ديار مصر، وأقبل عليه السلطانُ الملك الصالح نجم الدين أيوب إقبالًا عظيمًا، وولَّاه الخطابة والقضاء، فعزل نفسَه من القضاءِ مرتين وانقطع\" انتهت إليه رئاسة الشافعيَّةُ، وقُصِدَ بالفتاوى من الآفاق، وكان رحمه الله آمرًا بالمعروف ناهيًا عن المنكر لا يخافُ في الله لومة لائم، ذكر جلال الدين السيوطي: \"ولي الشيخُ عز الدين بن عبد السلام قضاءَ مِصرَ والوجه القبلي، وكان قَدِمَ في هذه السنة من دمشق بسبب أن سلطانَها الملك الصالح إسماعيل استعان بالفرنج وأعطاهم مدينةَ صيدا وقلعة الشقيف. فأنكر عليه الشيخُ عز الدين، وتَرَك الدعاء له في الخطبة، فغضب السلطانُ منه، فخرج إلى الديارِ المصريَّة، فأرسل السلطان الملك الصالح إسماعيل إلى الشيخ عز الدين؛ وهو في الطريق من يتلطَّفُ به في العَودِ إلى دمشق، فاجتمع به ولاينه، وقال له: ما نريد منك شيئًا إلا أن تنكَسِرَ للسلطان، وتقَبِّلَ يَدَه لا غير, فقال الشيخ له: يا مسكين، ما أرضاه يُقَبِّلُ يدي فضلًا عن أن أقبِّلَ يده! يا قوم، أنتم في وادٍ وأنا في وادٍ! والحمد لله الذي عافانا ممَّا ابتلاكم. فلما وصل إلى مصر، تلقَّاه سلطانها الصالحُ نجم الدين أيوب وأكرمه، وولَّاه قضاء مصر، فاتفق أن أستاذ داره  فخر الدين عثمان بن شيخ الشيوخ- وهو الذي كان إليه أمر المملكة- عمد إلى مسجدٍ بمصر، فعَمِلَ على ظهره بناء طبلخاناه– مكان تدق فيه الطبول والأبواق- وبَقِيَت تُضرَبُ هناك، فلما ثبت هذا عند الشيخِ عز الدين حكَمَ بهَدمِ ذلك البناء، وأسقطَ عدالةَ فخر الدين، وعزَلَ نفسه من القضاء، ولم تَسقُطْ بذلك منزلة الشيخ عند السلطان، ولَمَّا تولى الشيخ عز الدين القضاء تصَدَّى لبيع أمراء الدَّولةِ من المماليك الأتراك، وذكر أنه لم يَثبُت عنده أنهم أحرار، وأنَّ حُكمَ الرِّقِّ مُستصحَبٌ عليهم لبيت مالِ المسلمين، فبَلَغَهم ذلك، فعَظُمَ الخطبُ عندهم، والشيخُ مُصَمِّمٌ لا يُصَحِّحُ لهم بيعًا ولا شراءً ولا نكاحًا، وتعطَّلَت مصالحُهم لذلك؛ وكان من جملتِهم نائبُ السلطنة، فاستثار غضبًا، فاجتمعوا وأرسلوا إليه، فقال: نعقِدُ لكم مجلسًا، وننادي عليكم لبيتِ مال المسلمينَ، فرفعوا الأمرَ إلى السلطان، فبعث إليه فلم يرجِعْ، فأرسل إليه نائِبَ السلطنة بالملاطفةِ فلم يُفِدْ فيه، فانزعج النائبُ، وقال: كيف ينادِي علينا هذا الشَّيخُ، ويبيعُنا ونحن ملوكُ الأرضِ؟! واللهِ لأضربَنَّه بسيفي هذا، فرَكِبَ بنفسه في جماعته، وجاء إلى بيتِ الشيخ والسَّيفُ مسلول في يده، فطرق البابَ، فخرج ولدُ الشيخ، فرأى مِن نائبِ السلطان ما رأى، وشرحَ لأبيه الحال، فقال له: يا ولدي، أبوك أقلُّ من أن يُقتَلَ في سبيل الله، ثم خرج, فحين وقَعَ بصَرُه على النائِبِ يَبِسَت يدُ النائب، وسَقَط السيف منها، وأُرعِدَت مفاصِلُه، فبكى وسأل الشيخَ أن يدعو له، وقال: يا سيدي أيش تعمل؟ فقال: أنادي عليكم وأبيعُكم، قال: ففيم تَصرِفُ ثمَنَنا؟ قال: في مصالحِ المسلمينَ، قال: من يَقبِضُه؟ قال: أنا. فتَمَّ ما أراد، ونادى على الأمراءِ واحدًا واحدًا، وغالى في ثمَنِهم ولم يَبِعْهم إلَّا بالثَّمَن الوافي، وقَبَضَه وصَرَفه في وجوهِ الخير\". توفي في عاشر جمادى الأولى وقد نيف على الثمانين، ودُفِنَ مِن الغد بسفحِ المقَطَّم، وحضر جنازتَه السلطان الظاهِرُ وخَلقٌ كثير، وقد كان يُعرَفُ بسلطانِ العلماء؛ لأنه كان مهابًا من قِبَل السلاطينِ، وكان يقول الحقَّ أمامَهم ولا يخافُهم، ويُفتي بلا مداهنةٍ بما يراه، وأشهَرُ ذلك فتواه لَمَّا جاء ابنُ العديم إلى مصر يحمِلُ رسالة استنجاد من قِبَلِ الناصر صلاح الدين صاحِبِ دمشق ضِدَّ التتار فجمَعَ الفقهاء والقضاة ليستفتوهم بأخذ المالِ من العامة لتجهيزِ الجيوشِ، فكان كلامُ العِزِّ بن عبد السلام هو الذي عوَّلوا عليه، وهو أنَّه قال: لا يأخُذُ السلطانُ مِن العامة أيَّ مالٍ إلا بعد أن ينتهيَ المالُ الذي في بيت المال، ثمَّ تُنفَقُ الجواهر والذَّهَب وما إلى ذلك التي عند الملوكِ والأمراءِ حتى يُصبِحوا في القَدرِ كالعامَّة، فحينها يجوزُ لهم أخذُ المال من العامة؛ لأن واجِبَ الجهادِ بالمالِ والنَّفسِ أصبَحَ على الجميعِ، فرحمه الله وجزاه خيرًا."},{"id":2657,"title":"نهاية دولة الأتابكة بالموصل على يد قوات هولاكو .","date":["العام الهجري :660","الشهر القمري : شعبان","العام الميلادي :1262"],"text":"كان الصالحُ إسماعيل بن لؤلؤ صاحبُ الموصل من الذين ساروا مع المستنصِر الخليفة الجديد إلى بغداد، فلما حصلَ من الحرب ما حصَلَ هَرَب ورجع إلى بلادِه، فأرسل هولاكو طائفةً مِن جنده نحو عشرة آلاف وقائدهم صندغون وراءه فحاصروا الموصِلَ ونَصَبوا عليها خمسةً وعشرين منجنيقًا، وضاقت بها الأقواتُ، فأرسل الملك الصالحُ إسماعيل بن لؤلؤ إلى التركي يستنجِدُه فقَدِمَ عليه فهُزِمَت التتار ثم ثَبَتوا والتَقَوا معه، وإنما كان معه سبعُمائة مقاتل فهزموه وجرحوه وعاد إلى البيرةِ وفارقه أكثَرُ أصحابه فدخلوا الديارَ المصريَّة، وأما التتارُ فإنهم عادوا إلى الموصِل ولم يزالوا حتى استنزلوا صاحِبَها الملك الصالح إليهم ونادَوا في البلد بالأمان حتى اطمأن النَّاسُ ثم مالوا عليهم فقتلوهم تسعةَ أيام وقادوا الملِكَ الصالح إسماعيل وولده علاء الدين معهم إلى هولاكو ولكنَّهم قتلوه في الطريق، وخَرَّبوا أسوار البلد وتركوها بلاقِعَ، ثم كروا راجعين قبَّحهم الله، فكانت هذه نهايةَ دولة الأتابكة، وكان هذا الملك الصالح إسماعيل آخرَ ملوك الأتابكة."},{"id":2658,"title":"عساكر الظاهر بيبرس تهاجم الصليبيين في أنطاكية لإخراجهم منها .","date":["العام الهجري :660","الشهر القمري : رمضان","العام الميلادي :1262"],"text":"جهَّز الملكُ الظاهر عسكرًا إلى حَلَب، وكان مُقَدَّمُهم شمس الدين سنقر الرومي، فأَمِنَت بلاد حلب وعادت إلى الصَّلاح، ثم تقَدَّم الملك الظاهر بيبرس إلى سنقر الرومي إلى صاحِبِ حماة الملك المنصور، وإلى صاحِبِ حمص الملك الأشرف موسى أن يسيروا إلى أنطاكيةَ، للإغارة عليها، فساروا إليها ونَهَبوها وضايقُوا الفرنجَ فيها، ثم عادُوا، فتوجَّهَت العساكرُ المصريَّة بصُحبة سنقر الرومي إلى مصر، ووصلوا إليها في تاسع وعشرين رمضان من هذه السنة، ومعهم ما ينَيِّف عن ثلاثمائة أسير، فقابلهم الملكُ الظاهرُ بالإحسان والإنعام."},{"id":2659,"title":"وفاة الأمير سيف الدين بلبان الزردكاش .","date":["العام الهجري :660","الشهر القمري : ذي الحجة","العام الميلادي :1262"],"text":"هو الأمير الكبيرُ سَيفُ الدين بلبان المعروف بالزردكاش. من أمراء دمشقَ الأعيان، وكان دَينًا مشكورًا، وقد استنابه بيبرس موضِعَه بدار العدل على دمشق لما سافر إلى حصار أنطاكية، وكان دَيِّنًا خيِّرًا يحب العدل والصلاح. مات في الثامن من ذي الحجة من هذه السنة."},{"id":2660,"title":"الحرب بين هولاكو وابن عمه بركة خان ملك القبيلة الذهبية المغولية .","date":["العام الهجري :661","العام الميلادي :1262"],"text":"قَدِمَت رسلُ بركة خان إلى السلطانِ الظاهرِ بيبرس يقول له: قد عَلِمتَ محبَّتي للإسلام، وعَلِمتَ ما فعَلَ هولاكو بالمسلمين، فاركَبْ أنت من ناحيةٍ حتى آتيَه أنا من ناحيةٍ حتى نصطَلِمَه أو نخرِجَه من البلاد.  فالتقى بركة خان وهولاكو ومع كلِّ واحدٍ جيوشٌ كثيرة فاقتتلوا فهزم اللهُ هولاكو هزيمةً فظيعةً وقُتِلَ أكثر أصحابه وغَرِقَ أكثر من بقي، وهرب هو في شرذمةٍ يسيرةٍ، ولله الحمد، ولما نظَرَ بَركة خان كثرة القتلى قال: يعِزُّ علي أن يقتل المغولُ بعضُهم بعضًا، ولكن كيف الحيلةُ فيمن غيَّرَ سُنَّة جنكيز خان، ثم أغار بركة خان على بلادِ القسطنطينية فصانعه صاحِبُها وأرسل الظاهِرُ هدايا عظيمةً إلى بركه خان."},{"id":2661,"title":"تحالف الظاهر بيبرس مع بركة خان المغولي .","date":["العام الهجري :661","العام الميلادي :1262"],"text":"أرسل بركة خان المغولي رسلًا إلى السُّلطان الظاهر بيبرس يطلُبُ منه أن يتحالَفَ معه ضِدَّ هولاكو، وخاصَّةً أنه قد أسلَمَ ووقَعَ بينه وبين هولاكو من الخلافِ، فأكرم الظاهِرُ بيبرس الرسُلَ، ثمَّ أرسل هو بدوره رسلًا إلى بركة خان يعرِّفُه بموافقته على هذا الأمر مِن تحالُفِهما ضد هولاكو، وكتب الظاهِرُ إلى ملك شيراز وأهل تلك الديار، وإلى عرب خفاجة، يستحثُّهم على قتالِ هولاكو مَلَكِ التتار، وأن الأخبارَ قد وردت من البحرِ بكَسرِ الملكِ بركة له غيرَ مَرَّة."},{"id":2662,"title":"بيعة الخليفة العباسي الحاكم بأمر الله .","date":["العام الهجري :661","الشهر القمري : محرم","العام الميلادي :1262"],"text":"دخل الخليفة أبو العبَّاس الحاكِمُ بأمر الله أحمد بن الأمير أبي علي القبي بن الأمير علي بن الأمير أبي بكر بن الإمام المسترشد بالله بن المستظهر بالله أبي العباس أحمد, من بلاد الشرق وبصحبته جماعةٌ من رؤوس تلك البلاد، وقد شَهِدَ الوقعةَ بصحبة المستنصر الذي قُتِلَ فيها، وهرب هو في جماعةٍ مِن المعركة فسَلِمَ، فلما كان يومُ دخوله إلى مصر تلقَّاه السلطان الظاهر وأظهر السرورَ له والاحتفال به، وأنزله في البرجِ الكبير من قلعة الجبل، وأُجرِيَت عليه الأرزاق الدارَّة والإحسان، ثم في ثاني المحرم وهو يوم الخميس، جلس السلطانُ الظاهر والأمراء في الإيوان الكبير بقلعة الجبل، وجاء الخليفةُ الحاكم بأمر الله راكبًا حتى نزل عند الإيوان، وقد بسط له إلى جانب السلطان، وذلك بعد ثبوت نسبه، ثم قُرئَ نَسَبُه على الناس ثم أقبَلَ عليه الظاهر بيبرس فبايعه وبايعه الناس بعده، وكان يومًا مشهودًا، فلما كان يوم الجمعة ثانيه خطب الخليفةُ بالناس وكُتِبَ ببيعتِه إلى الآفاق ليُخطَبَ له وضُرِبَت السكة باسمه، فخُطِبَ له بجامع دمشق وسائر الجوامِعِ يوم الجمعة سادس عشر المحرم من هذه السنة، وهذا الخليفةُ هو التاسع والثلاثون من خلفاء بني العباس."},{"id":2663,"title":"نهاية الأيوبيين بعد أخذ الظاهر بيبرس مدينة الكرك وإعدام صاحبها .","date":["العام الهجري :661","الشهر القمري : جمادى الأولى","العام الميلادي :1263"],"text":"ركب الظاهِرُ بيبرس من مصرَ في العساكر المنصورة قاصدًا ناحية بلاد الكرك، واستدعى صاحِبَها الملك المغيث عمر بن العادل أبي بكر بن الكامل، فلما قَدِمَ عليه بعد جهدٍ أرسله إلى مصر معتقَلًا، فكان آخر العهد به، وذلك أنَّه كاتب هولاكو وحَثَّه على القدوم إلى الشَّامِ مَرَّةً أخرى، وجاءته كتبُ التتار بالثَّباتِ ونيابة البلاد، وأنهم قادِمونَ عليه عشرون ألفًا لفتح الديارِ المصريَّة، وأخرج السلطانُ فتاوى الفقهاء بقَتلِه وعَرَضَ ذلك على القاضي ابن خَلِّكان، وكان قد استدعاه من دمشقَ، وعلى جماعةٍ مِن الأمراء، ثم سار فتسَلَّمَ الكرك يوم الجمعة ثالث عشر جمادى الأولى ودخلها يومئذٍ في أبهة المُلك، ثم عاد إلى مصرَ مُؤَيَّدًا منصورًا، وبه تنتهي الدولةُ الأيوبيَّةُ في بلاد الشام."},{"id":2664,"title":"الظاهر بيبرس يأمر بعمارة المسجد النبوي بعد احتراقه .","date":["العام الهجري :661","الشهر القمري : رمضان","العام الميلادي :1263"],"text":"في رمضانَ جَهَّزَ الظاهِرُ صُنَّاعًا وأخشابًا وآلاتٍ كثيرة لعمارة مسجِدِ رَسولِ الله صلى الله عليه وسلم بعد حريقِه، فطيفَ بتلك الأخشاب والآلات بمصرَ فَرحةً وتعظيمًا لشأنها، ثم ساروا بها إلى المدينةِ النبوية."},{"id":2665,"title":"تحرير الظاهر بيبرس مدن ساحل الشام من الصليبيين .","date":["العام الهجري :662","العام الميلادي :1263"],"text":"لمَا خلا بالُ السلطان الظاهر بيبرس من هَمِّ المَلِك المغيث صاحب الكرك، توجَّهَ بكليته إلى الفرنجِ؛ فإنَّهم كانوا قد شرعوا في التعَلُّل وطلبوا زرعين- وهي قرية في سهل زرعين بصفد-  فأجابَهم السلطان بأنكم تعوَّضتُم عنها في الأيام الناصرية ضِياعًا من مرج عيون، وهم لا يزدادونَ إلا شكوى، وآخِرَ الحال طلب الفرنجُ من والي غزة كتابًا بتمكينِ رُسُلِهم إذا حضروا، فكتب لهم الكتابَ، وتواصلت بعد ذلك كتُبُهم، ووردت كتبُ النواب بشكواهم، وأنهم اعتمدوا أمورًا تفسِخُ الهدنة فلمَّا صار السلطان في وسط بلادِهم وردت عليه كتُبُهم، هذا وقد أمَرَ السلطان ألا ينزِلَ أحد في زرع الفرنجِ ولا يُسَيِّب فرسًا، ولا يؤذي لهم ورقةً خضراء، ولا يتعَرَّض إلى شيء من مواشيهم ولا إلى أحد من فلَّاحيهم، وكانت كتبهم أولًا تَرِدُ بندمهم على الهدنة وطلَبِهم فَسْخَها، فلما قرب السلطانُ منهم صارت تَرِدُ بأنهم باقون على العَهدِ مُتمَسِّكون بأذيال المواثيق، وفي اليوم الذي قُبِضَ فيه على الملك المغيث، أمَرَ السلطان بإحضار بيوت الفرنجيَّة، وقال: ما تقولون؟ قالوا: نتمَسَّك بالهدنة التي بيننا، فقال السلطان: لم لا كان هذا قبلَ حُضورنا إلى هذا المكان، وبالجملة فأنتم أخذتم هذه البلاد من المَلِك الصالح إسماعيل لإعانةِ مملكة الشام، وطاعةِ مَلِكِها ونصرته والخروجِ في خدمته، وإنفاقِ الأموال في نجدتِه، وقد صارت بحمد الله مملكةُ الشام وغيرها لي، وما أنا محتاج إلى نصرتكم ولا إلى نجدَتِكم، ولم يبقَ لي عدو أخافه، فرُدُّوا ما أخذتموه من البلاد، وفكُّوا أسرى المسلمين جميعهم، فإني لا أقبل غير ذلك، فلما سمع رسل الفرنج هذه المقالةَ بُهِتوا، وقالوا: نحن لا ننقُضُ الهدنة، وإنما نطلُبُ مَراحِمَ السلطان في استدامتِها، ونحن نزيل شكوى النواب، ونخرجُ مِن جميع الدعاوى ونفُكُّ الأسرى، ونستأنف الخِدمةَ، فقال السلطان: كان هذا قبل خروجي من مصرَ، في هذا الشتاءِ وهذه الأمطارِ، ووصول العساكرِ إلى هنا، وانفَصَلوا على هذه الأمور، فأمر السلطانُ بإخراجهم وألَّا يَبِيتوا في الوطاق، ووجَّه الأمير علاء الدين طيبرس إلى كنيسة الناصرة، وكانت أجلَّ مواطِنِ عباداتهم ويزعُمونَ أنَّ دينَ النصرانية ظهَرَ منها، فسار إليها وهدمها، فلم يتجاسَرْ أحدٌ من الفرنج أن يتحَرَّك، ثمَّ وجه السلطانُ الأمير بدر الدين الأيدمري في عسكر إلى عكا، فساروا إليها واقتَحَموا أبوابها وعادوا، ثم ساروا ثانيًا، وأغاروا على مواشي الفرنجِ، وأحضروا منها شيئًا كثيرًا إلى المخَيَّم، ثم ركب السلطان وجَرَّد من كل عشرة فارسًا، واستناب الأميرَ شجاع الدين الشبلي المهمندار- من يقوم بضيافة الرسل الواردين على السلطان- في الدهليز السلطاني، وساق من منزلة الطور نصف الليل، فصبَّحَ عكَّا وأطاف بها من جهة البر، وندب جماعةً لحصار برج كان قريبًا منه فشرعوا في نقبه، وأقام السلطانُ على ذلك إلى قريبِ المغرب وعاد، وكان قصدُه بذلك كشْفَ مدينة عكا؛ فإنَّ الفرنج كانوا يزعمونَ أن أحدًا لا يجسُرُ أن يقرب منها، فصاروا ينظرُونَ من أبواب المدينة ولا يستطيعون حركة، ولما عاد السلطان إلى الدهليز ركب لما أصبح، وأركب ناس معه، وساق إلى عكا، فإذا الفرنجُ قد حفروا خندقًا حول تل الفضول، وجعلوا معاثر في الطريق، ووقفوا صفوفًا على التلِّ، فلما أشرف السلطانُ عليهم رتَّب العسكرَ بنفسه، وشرع الجميعُ في ذكرِ الله وتهليلِه وتكبيرِه، والسلطان يحثُّهم على ذلك حتى ارتفعت أصواتهم، وللوقت رُدِمَت الخنادقُ بأيدي غلمان العساكِرِ وبمن حضر من الفقراءِ المجاهدين، وصَعِد المسلمون فوق تل الفُضول، وقد انهزم الفرنجُ إلى المدينة، وامتَدَّت الأيدي إلى ما حول عكا من الأبراج فهُدِمَت، وحُرِقَت الأشجارُ حتى انعقد الجوُّ من دخانها، وساق العسكرُ إلى أبوابِ عكا، وقَتَلوا وأسروا عِدَّةً مِن الفرنجِ، والسلطان قائمٌ على رأس التل يعملُ في أخذِ رأي المدينة، والأمراءُ تحمِلُ على الأبواب واحدًا بعد واحد، ثم حملوا حملةً واحدة ألقوا فيها الفرنجَ في الخنادق، وهلك منهم جماعةٌ في الأبواب، فلما كان آخرُ النهار ساق السلطانُ إلى البرج الذي نُقب، وقد تعلَّقَ حتى رُمِيَ بين يديه، وأُخِذَ منه أربعةٌ من الفرسان ونيف وثلاثون راجلًا، وبات السلطان على ذلك، فلما أصبح عاد على بلاد الفرنجِ وكشفها مكانًا مكانًا، وعبر على الناصرةِ حتى شاهد خرابَ كنيستِها وقد سوَّى بها الأرض، وصار إلى الصفَّة التي بناها قبالة الطور، فوافاها ليلًا وجلس عليها، وأحضر الشموع التي بالمنجنيقات ونصب عليها خمسة، ورحل السلطان من الطور يوم الاثنين ثالث عشر جمادى الآخرة، وسار إلى القدسِ فوافاه يوم الجمعة عشرة، وكشف أحوال البلدِ وما يحتاج إليه المسجِدُ من العمارة، ونظر في الأوقاف وكتب بحمايتِها، ورتَّبَ برسم مصالح المسجد في كل سنة خمسة آلاف درهم وأمر ببناء خان خارج البلد، ونقل إليه من القاهرة باب القصر المعروف بباب العيد، ونادى بالقدس ألا ينزل أحدٌ في زرع."},{"id":2666,"title":"نصير الدين الطوسي مبعوث هولاكو للنظر في أوقاف بغداد .","date":["العام الهجري :662","العام الميلادي :1263"],"text":"قدم نصيرُ الدين الطوسي إلى بغداد من جهة هولاكو، فنظر في الأوقافِ وأحوالِ البلد، وأخذ كتبًا كثيرةً مِن سائِرِ المدارس وحَوَّلها إلى رَصدِه الذي بناه بمراغة، ثم انحَدَر إلى واسط والبصرة."},{"id":2667,"title":"محاولة عز الدين السلجوقي قتل الأشكري صاحب القسطنطينية .","date":["العام الهجري :662","العام الميلادي :1263"],"text":"في هذه السنةِ قبض الأشكري صاحِبُ قسطنطينية على عزِّ الدين كيكاوس بن كيخسرو بن كيقباذ صاحِبِ بلاد الروم، وسَبَبُه أن الأشكري كان قد وقع بين كيكاوس وبين أخيه، فاستظهر أخوه عليه، فهرب كيكاوس وبقِيَ أخوه ركن الدين قليج أرسلان في سلطنة بلاد الرومِ، ثم سار كيكاوس إلى قسطنطينيَّة، فأحسن إليه الأشكري صاحبُ قسطنطينية. وإلى من معه من الأمراء، واستمَرُّوا كذلك مدة، فعزمت الأمراءُ والجماعة الذين كانوا مع عزِّ الدين على اغتيالِ الأشكري، والتغَلُّب على قسطنطينية، وبلغ ذلك الأشكريَّ، فقبض عليهم، واعتقَلَ عز الدين كيكاوس بن كيخسرو في بعض القلاعِ، وكحَلَ الأمراءَ والجماعةَ الذين كانوا عَزَموا على ذلك، فأعمى عيونَهم."},{"id":2668,"title":"عدوان الأرمن على الشام .","date":["العام الهجري :662","العام الميلادي :1263"],"text":"ورد الخبر أن هيتوم ملك الأرمن جمَعَ قوَّاتِه وسار إلى هرقلة، ونزل على قلعةِ صَرخد، فخرج البريدُ مِن قلعة الجبَلِ إلى حماة وحِمص بالمسير إلى حلب، فخرجوا وأغاروا على عَسكَرِ الأرمن، وقتَلوا منهم وأسَروا، فانهزم الأرمنُ واستنجدوا بالتَّتارِ، فقَدِمَ منهم من كان في بلادِ الروم وهم سبعُمائة فارس، فلما وصلوا إلى حارم رجعوا من كثرة الثلج، وقد هلك منهم كثيرٌ، ومع ذلك اهتم ملك الأرمن بالمسير إلى بلاد الشام، وأعدَّ ألف قباء –ثوب- تتري وألف سراقوج - لباس الرأس عند التتار- ألبسها الأرمن ليوهم أنهم نجدة من التتار، ولما ورد الخبَرُ بذلك خرج البريد إلى دمشق بخروج عسكَرِها إلى حمص، وخروج عسكر حماة، وألا يخرجُ عُربان الشام في هذه السنة إلى البرية، فخرَجَت العساكر، ووالت الغاراتِ مِن كل جهة، فانهزم الأرمنُ، ونزل العسكر على أنطاكية فقَتَل وأسر وغنم، وأغار العسكرُ أيضًا ببلاد الساحل على الفرنج حتى وصل إلى أبواب عكا."},{"id":2669,"title":"الأسبان يهاجمون غرناطة وابن الأحمر يهزمهم ويسترجع بعض المدن .","date":["العام الهجري :662","العام الميلادي :1263"],"text":"كان مَلِكُ قشتالة ألفونسو ملك النصارى قد طلب من محمَّدِ بنِ يوسف بن الأحمر حاكِمِ غرناطةَ الساحِلَ من مالقةَ إلى المرية فاستعان ابنُ الأحمر بالمتطَوِّعة والمجاهدين الذين وفدوا إليه من المغربِ فهزم الأسبان واسترد منهم مدينةَ شريش وقادس، وأخذ ألفونسو أسيرًا. ثم اجتمع العدوُّ المخذول في جمع كبير، ونازلوا غرناطة فانتصر عليهم المسلمون، وقتلوا منهم مقتلةً عظيمة، وجُمِع من رؤوسِهم نحو خمسة وأربعين ألف رأس، فعملوها كومًا، وأذَّنَ المسلمونَ فَوقَه، وأسروا منهم عشرة آلاف أسير. وكان ذلك في رمضان. وانهزم ألفونسو إلى إشبيلية، وهي له، وكان قد دَفَنَ أباه بها بالجامع، فأخرجه من قبرِه خوفًا من استيلاء المسلمين، وحمله إلى طليطلة. واسترجع المسلمون اثنين وثلاثين بلدًا، من جملتِها إشبيلية ومرسية."},{"id":2670,"title":"وفاة الأمير حسام الدين الجوكندار من كبار أمراء دمشق .","date":["العام الهجري :662","الشهر القمري : محرم","العام الميلادي :1263"],"text":"هو الأميرُ حسام الدين لاجين العزيزي الجوكندار- حامل الجوكان مع السلطان في لعب الكرة- وهو مِن غِلمانِ العزيز بن الظاهر بن السلطان صلاح الدين ومن كبار أمراء دمشق, وهو من أكابِرِ الأمراء وأعظَمِهم قدرًا، جوادًا ديِّنًا فارسًا شجاعًا حازمًا، له في الحروبِ آثارٌ جميلةٌ، وكان محبًّا للفقراء وأخلاقهم، كثيرَ البِرِّ بهم، يجمَعُهم على السَّمَاعات التي يُضرَبُ بها المثل، وكان له يدٌ طولى في كَسرِ التتار بوقعة حمص سنة 659، وقتل مقدمهم بيدرًا، وكان قد تولى نيابةَ حلب، ومات كهلًا في التاسع عشر من محرم."},{"id":2671,"title":"وفاة الملك الأشرف صاحب حمص .","date":["العام الهجري :662","الشهر القمري : صفر","العام الميلادي :1264"],"text":"هو الملك الأشرف مظفر الدين موسى بن الملك المنصور أبو إبراهيم بن الملك المجاهد شيركوه بن الأمير ناصر الدين محمد بن أسد الدين شيركوه بن شادي بن مروان صاحب حمص، مَلَك حمصَ بعد وفاة أبيه، وطالت مدَّتُه بها، وكان فيه مداراةٌ للتَّتارِ واستمرَّ على ذلك إلى أن توفِّيَ بحمص يوم الجمعة حادي عشر من صفر عن غيرِ ولد ولا أخٍ ولا ولي، فبعث السلطانُ الظاهر بيبرس إلى الأمير عز الدين بيليك العلائي أحد الأمراء، فتسَلَّمَها في السابع عشر من هذا الشهر وحَلَفَ الناسُ بها للملك الظاهر، وتسَلَّمَ الرحبةَ أيضًا، وبعث السلطان إليها عشرين ألف دينار عينًا، وولى مدينة حران الأمير جمال الدين الجاكي، وولى مدينة الرقة أميرا آخر."},{"id":2672,"title":"وفاة الشيخ الصالح محمد بن منصور القباري الإسكندراني .","date":["العام الهجري :662","الشهر القمري : شعبان","العام الميلادي :1264"],"text":"الشيخ الصالحُ محمد بن منصور بن يحيى الشيخ أبي القاسم القباري الإسكندراني كان مقيمًا بغيط له يقتاتُ منه ويعمَلُ فيه ويبذره، ويتورَّعُ جدًّا ويُطعِمُ الناس من ثماره. توفي في سادس شعبان بالإسكندرية وله خمس وسبعون سنة، وكان يأمرُ بالمعروف وينهى عن المنكر ويردَعُ الولاة عن الظلمِ فيَسمَعون منه ويطيعونَه لزهده، وإذا جاء الناسُ إلى زيارته إنما يكَلِّمُهم من طاقة المنزل وهم راضونَ منه بذلك، ولما توفي ترك من الأثاث ما يساوي خمسين درهمًا فبيع بمبلغ عشرين ألفًا."},{"id":2673,"title":"سلطنة الملك السعيد ناصر الدين بركة .","date":["العام الهجري :662","الشهر القمري : شوال","العام الميلادي :1264"],"text":"في يومِ الخميس ثالث عشر شوال من هذه السنة، أركَبَ السلطانُ الظاهر بيبرس ولَدَه الملك السعيد بشِعارِ السَّلطنةِ ومشى في ركابِه حاملًا له الغاشيةَ، وأخذها الأمراءُ الكبار واحدًا بعد واحدٍ، وعليهم الخِلَعُ الفاخرة، والحُلَل الزاهرة، وزينت المدينةُ زينةً تامة، واستبشر بذلك الخاصَّةُ والعامة، وتقَرَّر أن يكون أتابكه الأمير عز الدين أيدمر الحلي."},{"id":2674,"title":"الظاهر بيبرس يؤدب اليهود والنصارى بسبب افتعالهم الحرائق بمصر .","date":["العام الهجري :663","العام الميلادي :1264"],"text":"كثُرَت الحرائقُ بالقاهرة ومِصرَ في مدَّة سفر السلطان الظاهر بيبرس، وأُشيعَ أنَّ ذلك من النصارى، ونزل بالناسِ مِن الحريق في كلِّ مكان شدَّةٌ عظيمة، ووُجِدَ في بعض المواضع التي احترقت نفطٌ وكبريت، فأمر السلطانُ بجمع النصارى واليهود، وأنكر عليهم هذه الأمورَ التي تفسَخُ عهدهم وأمَرَ بإحراقهم، فجُمِعَ منهم عالمٌ عظيم في القلعة، وأُحضِرَت الأحطاب والحلفاء، وأُمِرَ بإلقائهم في النار، فلاذُوا بعفوه وسألوا المنَّ عليهم، وتقَدَّم الأمير فارس الدين أقطاي أتابك العساكر فشَفَعَ فيهم، على أن يلتزموا بالأموالِ التي احتَرَقت، وأن يحملوا إلى بيتِ المال خمسين ألف دينار، فأفرج عنهم السلطانُ الظاهر، وتولى البطرك توزيعَ المال، والتزموا ألا يعودوا إلى شيءٍ مِن المنكرات، ولا يخرجوا عمَّا هو مرتب على أهلِ الذمَّة، وأُطلِقوا."},{"id":2675,"title":"هلاك هولاكو المغولي .","date":["العام الهجري :663","الشهر القمري : ربيع الآخر","العام الميلادي :1265"],"text":"هو هولاكو خان بن تولي خان بن جنكيز خان ملك التتار بن ملك التتار، وهو والِدُ مُلوكِهم، والعامَّةُ يقولون هولاوون مثل قلاوون، وقد كان هولاكو ملكًا جبارًا فاجرًا كفَّارًا- لعنه الله- قتل من المسلمين شرقًا وغربًا ما لا يَعلَمُ عَدَدَهم إلَّا الذي خلقهم، وسيجازيه على ذلك شَرَّ الجزاء، كان لا يتقيَّدُ بدين من الأديان، وإنما كانت زوجتُه تنصَّرَت وكان هو يترامى على محبَّة المعقولات، ولا يتصوَّر منها شيئًا، قال الشيخ قطب الدين: \"كان من أعظَمِ ملوك التتار، وكان شجاعًا حازمًا مدبِّرًا، ذا همة عالية، وسطوةٍ ومهابة، ونهضةٍ تامة، وخبرة بالحروب، ومحبَّة في العلوم العقلية من غير أن يتعقَّل منها شيئًا، وكان أهلُها من أفراخ الفلاسفة لهم عنده وجاهة ومكانة، اجتمع له جماعة من فضلاء العالم، وجمع حُكماء مملكته، وأمَرَهم أن يرصدوا الكواكب. وكان يطلق الكثيرَ من الأموال والبلاد. وهو على قاعدةِ المغول في عدم التقيدِ بدين، لكن زوجته ظفر خاتون قد تنصَّرَت، وكانت تفضِّلُ النصارى على سائر الخلق، وكان سعيدًا في حروبه وحصاراته. طوى البلاد، واستولى على الممالكِ في أيسرِ مدة، وهزم الجيوش، وأباد الملوك، وقتل الخليفةَ، وأمراء العراق، وصاحبَ الشام، وصاحب ميافارقين\". كانت همته في تيسير مملكتِه وتملك البلاد شيئًا فشيئًا، قال النجم أحمد بن البواب النقاش: \"عزم هولاكو على زواجِ بنت ملك الكرج، فقالت له: حتى تُسلِمَ، فقال: عرفوني ما أقولُ, فعرضوا عليه الشهادتينِ فأقَرَّ بهما، وشَهِدَ عليه بذلك الفيلسوف الخواجة نصير الدين الطوسي، وفخر الدين المنجم. فلما بلغها ذلك أجابت. فحضر القاضي فخر الدين الخلاطي، فتوكَّل لها النصير، وللسلطان الفخر المنجم، وعقدوا العقدَ باسم تامار خاتون بنت الملك داود بن إيواني على ثلاثين ألف دينار، قال لي ابن البواب: وأنا كتبت الكتابَ في ثوب أطلس أبيض، فعَجِبتُ مِن إسلامه. قلت(الذهبي): إن صحَّ هذا فلعله قالها بفمه لعَدَمِ تقيُّدِه بدين، ولم يدخُلِ الإسلامُ إلى قلبه، فالله أعلم\". هلك بمرض الصَّرعِ واجتمعت التتار على ولده أبغا، كان هلاكُه في سابع ربيع الآخر بعلَّة الصرع، فإنه حصل له الصرعُ منذ قتل الملك الكامل صاحب ميافارقين، فكان يعتريه في اليوم المرَّة والمرتين, ولما عاد من كسرةِ ابن عمه بركة خان له أقام يجمع العساكر، وعزم على العَودِ لقتال بركة خان، فزاد به الصرعُ، ومرض نحوًا من شهرين، وهلك، فأخفَوا موته، وصبروه، وجعلوه في تابوت، ثم أظهروا موتَه. وكان موته بمدينة مراغة، ودفن بقلعة تلا, وبنيت عليه قبة, وكان ابنه أبغا غائبًا فطلبوه ثمَّ مَلَّكوه، وقيل كان موتُه في سنة 664هـ."},{"id":2676,"title":"إجلاء السلطان الظاهر بيبرس التتار من مدينة البيرة .","date":["العام الهجري :663","الشهر القمري : ربيع الآخر","العام الميلادي :1265"],"text":"نزل التتارُ  على البيرة، فجهَّز السلطانُ بيبرس مِن فَورِه الأميرَ بدر الدين الخازندار- ممسك خزانة المال- على البريد؛ ليخرج أربعة آلاف فارس من بلاد الشام، وركبَ السلطان من موضِعِه وساق إلى القلعة، وعيَّنَ الأمير عز الدين إيغان المعروف باسم الموت لتقدمةِ العساكر، فخرجوا من القاهرة جرائدَ- خَيْلٌ لا رَجَّالة فيها- في رابع شهر ربيع الأول، ثم عين الأمير جمال الدين المحمدي، والأمير جمال الدين أيدغدي الحاجي، ومعهما أربعة آلاف أخرى، فبرزوا ثانيَ يوم خروجِ الأمير عز الدين إيغان إلى ظاهر القاهرة، وساروا في عاشِرِه، وفي يوم السبت رابع ربيع الآخر: شرع السلطانُ في السفر، وخرج بنفسه في خامس شهر ربيع الآخر ومعه عساكر كثيرة، فوقع فناءٌ في الدواب هلك منها عددٌ كثير، وصارت الأموالُ مطروحة، والسلطانُ لا يقَصِّرُ في المسير، ونزل السلطانُ غزة في العشرين منه، فورد الخبَرُ بأن العدو نصب على البيرة سبعة عشر منجنيقًا، فكتم ذلك ولم يعلم به سوى الأمير شمس الدين سنقر الرومي والأمير سيف الدين قلاوون فقط، وكتب السلطان للأميرِ إيغان: \" متى لم تدركوا قلعةَ البيرة وإلَّا سُقتُ إليها بنفسي جريدة، فساق الأمير إيغان العسكر، ورحل السلطان من غزة، ونزل قريبًا من صيداء، وأتاه قسطلان يافا بتقادم، ونزل السلطانُ بيبني في السادس عشر، فورد البريدُ من دمشق بأن بطاقة الملك المنصور صاحب حماة سقطت بأنَّه وصل إلى البيرة بالعساكر، صحبة الأمير عز الدين إيغان وجماعة الأمراء يوم الاثنين، وأن التتارَ عندما شاهدوهم هربوا، ورموا مجانيقَهم وغرقوا مراكِبَهم، وكان من حين كتابتِها بالبيرة إلى حين وصولها يبني أربعة أيام، ثم توالت كتُبُ الأمراء بالبشارة، فكتب بذلك إلى القاهرة وغيرها، وكتب السلطانُ بعمارة ما خُرِّبَ من البيرة، وحمل آلات القتال والأسلحة إليها من مصر والشام، وأن يُعَبَّأ فيها كل ما يحتاجُ إليه أهلها في الحصار لمدة عشر سنين، وكتب للأمراء ولصاحب حماة بالإقامة على البيرة، حتى ينظف الخندق من الحجارة التي ردَمَها العدوُّ فيه، فكان الأمراءُ ينقلون الحجارة على أكتافهم مدة."},{"id":2677,"title":"الظاهر بيبرس يسترجع مدينة قيسارية وغيرها من الفرنج .","date":["العام الهجري :663","الشهر القمري : جمادى الأولى","العام الميلادي :1265"],"text":"رحل السلطانُ بيبرس إلى قريبِ عيونِ الأساور من وادي عارة وعرعرة، فلما كان بعد عشاءِ الآخرِ أمر العسكَرَ كُلَّه فلبسوا آلة الحرب، وركِبَ آخِرَ الليل وساق إلى قيسارية، فوافاها بكرةَ نهار الخميس تاسع جمادى الأولى على حين غفلةٍ مِن أهلها، وضرب عليها بعساكِرِه، وللوقت ألقى الناسُ أنفُسَهم في خندقها، وأخذوا سكك الحديدِ التي برسم الخيولِ مع المقاود والشبح، وتعلَّقوا فيها من كل جانبٍ حتى صعدوا، وقد نُصِبَت المجانيق ورمي بها، فحرقوا أبوابَ المدينة واقتحموها، فَفَرَّ أهلها إلى قلعتها، وكانت من أحصَنِ القلاع وأحسَنِها وتعرف بالخضراء، وكان قد حمل عليها الفرنجُ العُمُدَ الصوان، وأتقنوها بتصليبِ العُمُدِ في بنيانها، حتى لا تُعمَلَ فيها النقوبُ ولا تقَعُ إذا علقت، فاستمر الزحف والقتال عليها بالمجانيق والدبابات والزحَّافات ورمي النشَّاب، وخرجت جريدة- خَيْلٌ لا رَجَّالة فيها- من عسكر السلطان إلى بيسان مع الأمير شهاب الدين القيمري، فسَيَّرَ جماعة من التركمان والعربان إلى أبوابِ عكا، فأسروا جماعةً مِن الفرنج، هذا والقتال ملِحٌّ على قلعة قيسارية، والسلطانُ مقيمٌ بأعلى كنيسةٍ تجاه القلعة ليمنَعَ الفرنج من الصعودِ إلى علو القلعةِ، وتارة يركَبُ في بعضِ الدبَّابات ذوات العجل التي تجري حتى يصل إلى السور ليرى النقوبَ بنَفسِه، وأخذ السلطانُ في يده يومًا من الأيامِ تُرسًا وقاتل، فلم يرجِعْ إلَّا وفي ترسِه عِدَّةُ سِهامٍ، فلما كان في ليلةِ الخميس النصف من جمادى الأولى: سلَّم الفرنجُ القلعةَ بما فيها، فتسلق المسلمونَ من الأسوار، وحرقوا الأبواب ودخلوها من أعلاها وأسفَلِها، وأذِّنَ بالصبحِ عليها، وطلع السلطانُ ومعه الأمراء إليها، وقسَّمَ المدينة على الأمراء والمماليك والحلقة، وشرع في الهدمِ ونزل وأخذ بيَدِه قطاعةً وهدَمَ بنَفسِه، فلما قارب الفراغَ مِن هدم قيسارية بعث السلطانُ الأمير سنقر الرومي والأمير سيف الدين المستعرب في جماعة، فهدموا قلعةً كانت للفرنج عند الملوحة قريب دمشق، وكانت عاتية حتى دكُّوها دكًّا، وفي السادس عشر: سار السلطانُ جريدة إلى عثليث، وسير الأمير سنقرًا السلاح دار، والأمير عز الدين الحموي، والأمير سنقرًا الألفي إلى حيفا، فوصلوا إليها، ففر الفرنجُ إلى المراكب وتركوا قلعَتَها، فدخلها الأمراءُ بعد ما قتلوا عِدَّةً من الفرنج وبعد ما أسروا كثيرًا، وخربوا المدينة والقلعة وأحرقوا أبوابها في يومٍ واحد، وعادوا بالأسرى والرؤوس والغنائم سالمين، ووصل السلطانُ إلى عثليث فأمر بتشعيثِها وقطْع أشجارها، فقُطِعَت كلُّها وخربت أبنيتها في يوم واحد، وعاد إلى الدهليز بقيسارية، وكمَّل هَدْمَها حتى لم يدَعْ لها أثرًا، وقدمت منجنيقات من الصبيبة وزرد خاناه من دمشق، وورد عِدَّة من الفرنج للخدمة، فأكرَمَهم السلطان وأقطعهم الإقطاعات، وفي التاسع عشر: رحل السلطان من قيسارية، وسار من غير أن يَعرِفَ أحدٌ قَصْدَه فنزل على أرسوف مستهلَّ جمادى الآخرة، ونقل إليها من الأحطاب ما صارت حولَ المدينة كالجبال الشاهقة وعَمَل منها ستائر، وحفر سربين من خندق المدينة إلى خندق القلعةِ وسَقَفَه بالأخشاب، وعمل السلطان طريقًا من الخندقين إلى القلعة، وردمت الأحطابُ في الخندق، فتحَيَّل الفرنجُ وأحرقوها كلَّها، فأمر السلطان بالحفر من باب السربين إلى البحرِ، وعمل سروبًا تحت الأرض يكون حائطُ خندق العدو ساترًا لها، وعمل في الحائط أبوابًا يرمي التراب منها وينزل في السروب حتى تساوي أرضُها أرض الخندق، وأحضر المهندسين حتى تقَرَّر ذلك، وولي أمرَه للأمير عز الدين أيبك الفخري، فاستمر العمل، والسلطان بنفسِه ملازم العمل بيده في الحفرِ وفي جر المنجنيقات ورمي الترابِ ونَقلِ الأحجار، أسوةً لغيره من الناس، وكان يمشي بمفرده وفي يده ترسٍ، تارة في السَّرَب وتارة في الأبوابِ التي تفتح، وتارة على حافةِ البحر يرامي مراكِبَ الفرنج، وكان يجرُّ في المجانيق، ويطلع فوق الستائر يرمي من فوقها، ورمى في يوم واحد ثلاثمائة سهم بيده، وحضر في يومٍ إلى السرب وقُدَّ في رأسه خلف طاقة يرمي منها، فخرج الفرنج بالرماح وفيها خطاطيف ليجبذوه فقام وقاتلهم يدًا بيد وكان معه الأميرُ سنقر الرومي، والأمير بيسري، والأمير بدر الدين الخازندار، فكان سنقر يناوله الحجارةَ حتى قتل فارسين من الفرنج، ورجعوا على أسوأ حال، وكان يطوفُ بين العساكر في الحصار بمفردِه، ولا يجسِرُ أحد ينظر إليه ولا يشير إليه بإصبُعِه، بل كان الناسُ فيها سواءً في العمل، حتى أثرت المجانيق في هدمِ الأسوار، وفُرِغَ من عمل الأسربة التي بجانبي الخندق، وفتحت فيها أبواب متسعة، فلما تهيأ ذلك وقع الزحفُ على أرسوف في يوم الخميس ثامن رجب، ففتحها الله في ذلك اليوم عندما وقَعَت الباشورة – الباشورة حائط ظاهر الحصن يختفي وراءه الجند عند القتال- فلم يشعر الفرنج إلا بالمسلمين قد تسلقوا وطلعوا القلعة، ورفعت الأعلام الإسلامية على الباشورة، وحَفَّت بها المقاتلة وطُرِحَت النيران في أبوابها، هذا والفرنجُ تقاتل، فدفع السُّلطانُ سنجقه للأميرِ سنقر الرومي وأمَرَه أن يؤمِّنَ الفرنج من القتل، فلما رآه الفرنجُ تركوا القتالَ، وسلَّمَ السنجق للأمير علم الدين سنجر المسروري المعروف بالخياط الحاجب، ودُلِّيَت له الحبال من القلعة فربطها في وسطِه والسنجق معه، ورفع إليها فدخَلَها وأخذ جميعَ سيوف الفرنج وربَطَهم بالحبال وساقهم إلى السلطانِ والأمراء صفوف وهم ألوف، وأباح السلطانُ القلعة للناس، وكان بها من الغِلالِ والذخائر والمال شيءٌ كثير، وكان فيها جملةٌ من الخيول والبغال لم يتعرض السلطان لشيءٍ منه، إلا ما اشتراه ممَّن أخذه بالمال ووجد فيها عِدَّةً من أسرى المسلمين في القيود فأُطلِقوا، وقَيَّد الفرنجَ بقيودهم، وعيَّنَ السلطانُ جماعةً مع الأسرى من الفرنج ليسيروا بهم، وقسَّم أبراج أرسوف على الأمراء، وأمر أن يكون أسرى الفرنجِ يتولون هدم السورِ، فهُدِمَت بأيديهم، وأمرَ السلطان بكشف بلاد قيسارية وعمَل متحَصَّلِها، فعُمِلَت بذلك أوراقٌ، وطَلَبَ قاضي دمشق وعدوله ووكيل بيت المال، وتقدم بأن يملك الأمراءُ المجاهدون من البلاد التي فتحها الله عليه، وكتبت تواقيع كل منهم من غير أن يطَّلعوا على ذلك، فلما فرغت التواقيعُ فُرِّقَت على أربابها، وكتب بذلك مكتوبٌ جامع بالتمليك ورحل السلطانُ من أرسوف بعد استكمال هدمِها في يوم الثلاثاء الثالث عشر شهر رجب إلى غزة وسار منها إلى مصر ودخل السلطان من القاهرة في يوم الخميس حادي عشر شعبان والأسرى بين يديه."},{"id":2678,"title":"الأسبان يستردون مرسية .","date":["العام الهجري :664","العام الميلادي :1265"],"text":"كان المُسلِمونَ قد استردُّوا مدينة مرسية من يد الأسبان سنة 662هـ، ثم في هذا العام استطاع ألفونسو العاشر ملك قشتالة بمساعدة ليون وجيمس الأول ملك أرغونة من استعادتها من يد المسلمينَ، فلم يبقَ بيد المسلمينَ بعدها سوى مقاطعةِ غِرناطة."},{"id":2679,"title":"السلطان الظاهر بيبرس يحرر مدينة صفد .","date":["العام الهجري :664","الشهر القمري : شوال","العام الميلادي :1266"],"text":"اهتم السلطانُ الظاهر بيبرس بأمر صفد، وأحضر العساكِرَ المجردة، ورحَّل الأمير بكتاش الفخري أميرَ سلاح بالدهليز السلطاني ونزل على صفد، وتبعه الأميرُ البندقدار والأميرُ عز الدين أوغان في جماعة، وحاصروها، هذا والسلطانُ مقيم على عكا حتى وافته العساكرُ، وعمل عدةَ مجانيقَ، ثم رحل والعساكِرُ لابسة، وساق إلى قربِ باب عكا، ووقفَ على تل الفضول، ثم سار إلى عين جالوت، ونزل على صفد يوم الاثنين ثامن شهر رمضان وحاصرها، فقدم عليه رسول متملك صور ورسل الفداوية، ورسول صاحب بيروت ورسول صاحب يافا، ورسل صاحب صهيون، وصار السلطان يباشر الحصارَ بنَفسِه، وقَدِمَت المجانيق من دمشق إلى جسر يعقوب وهو منزلة من صفد ثم نصبت المجانيقُ فرمي بها في السادس عشر، وصار السلطان يلازم الوقوف عندها وهي ترمي، وأتت العساكِرُ من مصر والشام، فنزلوا على منازلهم وفي ثاني يوم عيد الفطر: وقع الزحفُ على صفد، ودفع الزراقون النفطَ، ووعد السلطان الحجَّارين أنه من أخذ أول حجر كان له مائة دينار، وكذلك الثاني والثالث إلى العشرة، وأمر حاشيته بألا يشتغلوا بخدمته، فكان بين الفريقين قتال عظيم استُشهِدَ فيه جماعة، وكان الواحد من المسلمين إذا قُتِلَ جَرَّه رفيقه ووقف موضِعَه، وتكاثرت النقوبُ ودخل النقَّابون إليها، ودخل السلطانُ معهم، وبذل السلطانُ في هذا اليوم من المال والخِلَع كثيرًا، ونصب خيمةً فيها حكماء وجرائحية وأشربة ومآكل، فصار من يُجرَحُ من العُربان والفقهاء والفقراء وغيرهم يُحضَرُ إليها، وفي ثامنه: كانت بين الفريقين أيضًا مَقاتِلُ، وفي ليلة الرابع عشر: اشتد الزحف من الليل إلى وقت القائلة، فتفرق الناس من شدة التعب، فغضب السلطانُ من ذلك وأمر خواصَّه بالسَّوقِ إلى الصاواوين وإقامة الأمراء والأجداد بالدبابيس، وقال المسلمون على هذه الصورة، وأنتم تستريحون!! فأقيموا، وقبَضَ السلطان على نيف وأربعين أميرًا، وقيَّدَهم وسجَنَهم بالزردخاناه-خزانة السلاح-، ثم شفع فيهم فأطلَقَهم وأمرهم بملازمةِ مواضِعِهم، وضُرِبَت الطبلخاناه- الطبول والأبواق- واشتد الأمر إلى أن طلب الفرنجُ الأمان، فأمَّنَهم السلطان على ألا يخرجوا بسلاحٍ ولا لَأْمةِ حَربٍ ولا شيءٍ مِن الفضيات، ولا يُتلِفوا شيئًا من ذخائر القلعة بنارٍ ولا هدم، وأن يُفتَّشوا عند خروجهم، فإن وُجِدَ مع أحد منهم شيء من ذلك انتقَضَ العهد، ولم تزل الرسُلُ تتردد بينهم إلى يوم الجمعة الثامن عشر، ثم طلعت السناجق –رماح- الإسلاميَّة، وكان لطلوعها ساعةٌ مشهودة، هذا والسلطان راكِبٌ على باب صفد حتى نزل الفرنجُ كُلُّهم، ووقفوا بين يديه فرسم بتفتيشِهم، فوجد معهم ما يناقض الأمانَ من السلاح والفضيات، ووجد معهم عِدَّةً من أسرى مسلمين أخرجوهم على أنهم نصارى، فأخذ ما وجد معهم وأُنزِلوا عن خيولهم، وجُعِلوا في خيمةٍ ومعهم من يحفظهم، وتسَلَّمَ المسلمون صفد، وولى السلطانُ قلعَتَها الأميرَ مجد الدين الطوري، وجعل الأميرَ عز الدين العلائي نائب صفد، فلما أصبح حضر إليه النَّاسُ، فشكر اجتهادَهم واعتذر إليهم مما كان منه إلى بعضِهم، وإنه ما قصَدَ إلَّا حَثَّهم على هذا الفتح العظيم، وقال: من هذا الوقتِ نتحالَلُ، وأمَرَهم فركبوا، وأُحضِرَت خيالة الفرنج وجمعٌ من صفد، فضُرِبَت أعناقهم على تل قرب صفد حتى لم يبق منهم سوى نفرينِ، أحدهما الرسول، فإنه اختار أن يقيمَ عند السلطان ويُسلِم، فأسلم وأقطَعَه السلطانُ إقطاعًا وقَرَّبَه، والآخَرُ تُرِكَ حتى يخبِرَ الفرنج ممَّا شاهده، وصَعِدَ السلطانُ إلى قلعة صفد، وفَرَّق على الأمراء العُدَد الفرنجية والجواري والمماليك، ونَقَل إليها زردخاناه من عنده، وحمل السلطانُ على كتفه من السلاح إلى داخل القلعة، فتشَبَّه به الناس ونقلوا الزردخاناه في ساعةٍ واحدة، واستدعى السلطانُ الرجال من دمشق للإقامةِ بصفد، وقرر نفقةَ رجال القلعة في الشهرِ مبلغ ثمانين ألف درهم نقرةً واستخدم على سائر بلاد صفد، وعَمِلَ بها جامعًا في القلعة وجامعًا بالربض ووقفَ على المجنون نصف وربع الحباب، وللربع الآخر على الشيخ إلياس، ووقف قريةً منها على قبر خالد بن الوليد بحمص، وفي السابع عشر: رحل السلطان من صفد إلى دمشق."},{"id":2680,"title":"الملك المنصور صاحب حماة يأخذ بلاد سيس من الأرمن .","date":["العام الهجري :664","الشهر القمري : ذي القعدة","العام الميلادي :1266"],"text":"سار الملك المنصور صاحب حماة ومن معه، إلى حصن دير بساك ودخلوا الدربند، وقد بنى التكفور هيتوم بن قسطنطين بن باساك ملك الأرمن على رؤوس الجبال أبراجًا وهو الذي تزهَّد فيما بعد، وترك المُلكَ لولده ليفون فاستعد ووقف في عسكره، فعندما التقى الفريقان أُسِرَ ليفون بن ملك سيس، وقُتِلَ أخوه وعمه، وانهزم عمه الآخر، وقتل ابنه الآخر، وتمزق الباقي من الملوك, وكانوا اثني عشر ملكًا وقُتِلَت أبطالهم وجنودهم، وركب العسكر أقفيتهم وهو يقتل ويأسر ويحرق، وأخذ العسكر قلعة حصينة للداوية، فقُتِلَت الرجال وسُبِيت النساءُ وفُرِّقَت على العسكر وحُرِقت القلعة بما فيها من الحواصل، ودخلوا سيس فأخربوها وجعلوا عاليها سافلها، وأقاموا أيامًا يحرقون ويقتلون ويأسرون، وسار الأمير أوغان إلى جهة الروم، والأمير قلاوون إلى المصيصة وأذنة وأياس وطرسوس، فقتلوا وأسروا وهَدَموا عِدَّةَ قلاع وحرقوا، هذا وصاحب حماة مقيم بسيس، ثم عادوا إليه وقد اجتمع معهم من الغنائم ما لا يعد ولا يحصى، وذلك أن أهل سيس كانوا أضرَّ شيء على المسلمين زمن التتار، لما أخذوا مدينة حلب وغيرها أسروا من نساء المسلمين وأطفالهم خلقًا كثيرًا، ثم كانوا بعد ذلك يغيرون على بلاد المسلمين في زمن هولاكو، فكبته الله وأهانه على يدي أنصار الإسلام، هو وأميره كتبغا، وكان أخذ سيس يوم الثلاثاء العشرين من ذي القعدة من هذه السنة، وطلب صاحب سيس أن يفادي ولده، فقال السلطان لا نفاديه إلا بأسير لنا عند التتار يقال له سنقر الأشقر، فذهب صاحب سيس إلى ملك التتار فتذلل له وتمسكن وخضع له، حتى أطلقه له، فلما وصل سنقر الأشقر إلى السلطان أطلق ابن صاحب سيس."},{"id":2681,"title":"إيقاع السلطان الظاهر بيبرس بأهل قارا النصارى .","date":["العام الهجري :664","الشهر القمري : ذي الحجة","العام الميلادي :1266"],"text":"عندما توجه الملك الظاهر من دمشق، لملتقى عساكره العائدة من غزوة بلاد سيس، ونزل على قارا بين دمشق وحمص، أمر بنهب أهلها وقتلِ كبارهم، فنُهِبوا وقُتِل منهم جماعة لأنهم كانوا نصارى، وكانوا يسرِقونَ المسلمين ويبيعونَهم بالخُفيةِ إلى الفرنج، وأُخِذَت صبيانهم مماليكَ، فترَبَّوا بين الترك في الديار المصرية، فصار منهم أجنادٌ وأمراء."},{"id":2682,"title":"إقامة الجمعة في الجامع الأزهر بعد أن انقطعت عنه زمنا طويلًا .","date":["العام الهجري :665","الشهر القمري : ربيع الأول","العام الميلادي :1266"],"text":"أُقيمَت الجمعةُ بالجامع الأزهر من القاهرة، وكانت قد بطلت منه منذ ولي قضاء مصر صدرُ الدين عبد الملك بن درباس، عن السلطان صلاحِ الدين يوسف بن أيوب، وقد ظَلَّ كذلك إلى أن سكن الأميرُ عز الدين أيدمر الحلي بجواره، فانتزع كثيرًا من أوقاف الجامع كانت مغصوبة بيد جماعة، وتبرع له بمالٍ جزيل، واستطلق له مِن السلطان الظاهر بيبرس مالًا، وعَمَرَ الواهيَ من أركانه وجدرانه، وبيَّضَه وبلَّطَه ورمَّم سقوفه، وفَرَشه واستجَدَّ به مقصورةً وعَملَ فيه منبرًا، فتنازع الناسُ فيه هل تصح إقامة الجمعة فيه أم لا، فأجاز ذلك جماعةٌ من الفقهاء، ومنع منه قاضي القضاة تاج الدين عبد الوهاب بن بنت الأعز وغيره، فشكى الحليُّ ذلك إلى السلطان، فكلم فيه قاضي القضاة فصَمَّم على المنع، فعَمِلَ الحلي بفتوى من أجاز ذلك وأقام فيه الجمعة، وسأل السلطانَ أن يحضُرَ فامتنع من الحضور ما لم يحضُرْ قاضي القضاة، فحضَرَ الأتابك والصاحب بهاء الدين وعِدَّة من الأمراء والفقهاء، ولم يحضُر السلطان ولا قاضي القضاة تاج الدين، وعَمِلَ الأمير بدر الدين بيليك الخازندار- ممسك خزانة المال- بالجامع مقصورةً، ورتَّبَ فيها مدرِّسًا وجماعةً مِن الفقهاء على مذهب الشافعي، ورتب محدِّثًا يُسمِعُ بالحديث النبوي والرقائق، ورتَّبَ سبعةً لقراءة القرآن العظيم، وعَمِلَ على ذلك أوقافًا تكفيه، إلَّا أن ابن كثير قال: \"في ثاني عشر ربيع الأول صلى الظاهر بالجامع الأزهر الجمعة، ولم يكن تقامُ به الجمعة من زمن العبيديين إلى هذا الحين، مع أنه أول مَسجدٍ بني بالقاهرة، بناه جوهرٌ القائدُ وأقام فيه الجمعةَ، فلما بنى الحاكِمُ جامِعَه حَوَّل الجمعةَ منه إليه، وترك الأزهرَ لا جمعةَ فيه، فصار في حكم بقية المساجِدِ وشَعِثَ حالُه وتغيَّرَت أحواله، فأمر السلطانُ الظاهر بيبرس بعمارتِه وبياضِه وإقامةِ الجمعة\""},{"id":2683,"title":"وفاة بركة خان ابن عم هولاكو  .","date":["العام الهجري :665","الشهر القمري : ربيع الآخر","العام الميلادي :1267"],"text":"هو زعيمُ القبيلة الذهبية بركة خان بن جوجي بن جنكيز خان في بلاد القفجاق، وهو ابنُ عم هولاكو، وقد أسلم بركة خان وزوجته ججك  سنة 655، وكان يحِبُّ العلماء والصالحين ومن أكبَرِ حَسَناتِه كَسرُه لهولاكو وتفريقُ جنوده، وكان يناصِحُ الملكَ الظاهِرَ ويعَظِّمُه ويُكرِمُ رسُلَه إليه، ويُطلِقُ لهم شيئًا كثيرًا، وقد اتَّفَق معه على حربِ هولاكو، في سنة إحدى وستين وقد قام في الملكِ بعده بعضُ أهل بيته وهو منكوتمر بن طغان بن بابو بن تولى بن جنكيزخان، وكان على طريقتِه ومنوالِه، ولله الحمد."},{"id":2684,"title":"هدنة بين ابن الأحمر ملك غرناطة وملك قشتالة .","date":["العام الهجري :666","العام الميلادي :1267"],"text":"تجدَّدَت الهدنةُ بين محمد بن الأحمر ملك غرناطة وبين مَلِك قشتالة ألفونسو العاشر على أن يَنزِلَ له عن عَدَدٍ من البلادِ والحُصونِ."},{"id":2685,"title":"وفاة كيقباد صاحب سلاجقة الروم .","date":["العام الهجري :666","العام الميلادي :1267"],"text":"هو السلطانُ ركن الدين كيقباد بن السلطان غياث الدين كيخسرو بن السلطان علاء الدين كيقباد بن كيخسرو بن قليج أرسلان بن مسعود بن قليج أرسلان بن سليمان بن قطلمش بن أتسز بن إسرائيل بن سلجوق بن دقماق السلجوقي صاحب الروم، كان ملكًا جليلًا شجاعًا لكنَّه كان غيرَ سديد الرأي، كان جعَلَ أمْرَه بيَدِ البرواناه- الحاجب- فاستفحل أمر البرواناه، فأراد ركن الدين هذا قتْلَه فعاجله البرواناه وعمل على قَتْلِه حتى قُتِلَ."},{"id":2686,"title":"تحرير الظاهر بيبرس مدينة يافا من الفرنج .","date":["العام الهجري :666","الشهر القمري : جمادى الآخرة","العام الميلادي :1268"],"text":"لما كان يوم العشرين من جمادى الآخر سار السلطانُ الظاهر من العوجاء إلى يافا، وحاصرها حتى ملكها من يومه، وأخذ قلعتها وأخرج من كان فيها من الفرنجِ، وهَدَمَها كُلَّها وجمع أخشابَها ورخامها وحمَلَه في البحر إلى القاهرة، وأمَرَ السلطان ببناء الجوامِعِ بتلك البلاد، وأزال منها المنكَراتِ، ورتَّبَ الخفراءَ على السواحلِ وألزَمَهم بدَركِها، ورسم أن المال المتحصَّل من هذه البلاد لا يُخلَطُ بغيره، وجعله لمأكله ومشربه، وأنزل التركمان بالبلاد الساحلية لحمايتها، وقرر عليهم خيلًا وعدة، فتجَدَّد له عسكرٌ بغير كلفة، وفيه رسَمَ بتجديد عمارةِ الخليل عليه السَّلامُ، ورسم أن يكون عمل الخوان الذي يمَدُّ ناصيةً عن مسجد الخليل."},{"id":2687,"title":"تحرير الظاهر بيبرس حصن الشقيف من الفرنج  .","date":["العام الهجري :666","الشهر القمري : رجب","العام الميلادي :1268"],"text":"جهَّزَ السلطان عسكرًا إلى الشقيف، ثم سار إليها بنفسه فنزل عليها في يوم الأربعاء تاسع عشر شهر رجب، وقدم الفقهاءُ للجهاد، ونصب السلطانُ عليها ستة وعشرين منجنيقًا، وألح عليها حتى أخذها يوم الأحد آخر رجب، وأخرج منها نساء الفرنجِ وأولادهم إلى صور، وقيَّدَ الرجال كلهم وسَلَّمَهم للعساكر، وهدم السلطان قلعةً استجدها الفرنجُ هناك، واستناب على القلعة الأخرى الأميرَ صارم الدين قايماز الكافري، ورتب بها الأجناد والرجالة، وقرر فيها قاضيًا وخطيبًا."},{"id":2688,"title":"غزو السلطان الظاهر بيبرس الفرنج بالشام .","date":["العام الهجري :666","الشهر القمري : رجب","العام الميلادي :1268"],"text":"رحل السُّلطانَ من الشقيف إلى قرب بانياس، وبعث الأثقالَ إلى دمشق وجهز الأميرَ عز الدين أوغان بجماعة لجهة، وجهز الأمير بدر الدين الأيدمري في جماعةٍ إلى جهة أخرى، فحَفِظَت العساكر الطرقات، ثم سار السلطانُ إلى  طرابلس وخيَّمَ عليها في النصف من رجب، وناوش أهلَها القتال وأخذ برجًا كان هناك، وضرب أعناقَ مَن كان من الفرنج، وأغارت العساكِرُ على من في تلك الجبال، وغَنِموا شيئًا كثيرًا وأخذوا عدة مغاير بالسيف، وأحضروا المغانمَ والأسرى إلى السلطان فضَرَبَ أعناق الأسرى، وقطع الأشجارَ وهدم الكنائس، وقسَمَ الغنائم في العسكر، ودخل السلطانُ عن طرابلس في الرابع عشر، فتلقَّاه صاحب صافيتا وأنطرسوس بالخدمة، وأحضر ثلاثمائة أسير كانوا عنده، فشكَرَه السلطان ولم يتعرَّض لبلاده، ونزل السلطان على حمص، وأمر بإبطالِ الخمر والمنكَرات، ثم دخل إلى حماة ولا يعرف أحدٌ أي جهة يقصد، فرتَّب العسكر ثلاثَ فرق: فرقة بصحبة الأمير بدر الدين الخازندار- ممسك خزانة المال- وفرقة مع الأمير عز الدين إيغان، وفرقة مع السلطان، فتوجه الخازندار إلى السويدية، وتوجه إيغان إلى درب بساك، فقتلوا وأسروا، ونزل السلطان أفامية، ووافاه الجميع على أنطاكية."},{"id":2689,"title":"الظاهر بيبرس يحرر إمارة أنطاكية من الصليبيين .","date":["العام الهجري :666","الشهر القمري : رمضان","العام الميلادي :1268"],"text":"بعد أن انتهى السلطان الظاهر بيبرس من أمر طرابلس وعاد إلى حماة واجتمعت فيه أمراؤه، فأصبح أول شهر رمضان والسلطان مغير على أنطاكية، وأطافت العساكرُ بها من كل جانب، فتكمَّلوا بخيامهم في ثالثه، وبعث السلطان إلى الفرنج يدعوهم وينذرهم بالزحف عليهم، وفاوضهم في ذلك مدة ثلاثة أيام وهم لا يجيبونَ، فزحف عليهم وقاتلهم قتالًا شديدا، وتسَوَّر المسلمون الأسوار من جهة الجبل بالقرب من القلعة، ونزلوا المدينة ففر أهلُها إلى القلعة، ووقع النهبُ والقتل والأسر في المدينة، فلم يُرفَعِ السيف عن أحد من الرجال وكان بها فوقَ المائة ألف، وأحاط الأمراءُ بأبواب المدينة حتى لا يفِرَّ منها أحد، واجتمع بالقلعة من المقاتلة ثمانيةُ آلاف سوى النساء والأولاد، فبعثوا يطلبونَ الأمان فأمِّنوا، وصَعِدَ السلطان إليهم ومعه الحبال، فكُتِّفوا وفُرِّقوا على الأمراء، والكتَّاب بين يدي السلطان ينزلون الأسماءَ، وكانت أنطاكية للبرنس بيموند بن بيموند، وله معها طرابلس، وهو مقيم بطرابلس وكتبت البشائرُ بالفتح إلى الأقطار الشامية والمصرية والفرنجية، وسلمَ السلطان القلعة إلى الأمير بدر الدين بيليك الخازندار- ممسك خزانة المال- والأمير بدر الدين بيسري الشمسي، وأمر بإحضار المغانم لتقتسم، وركب وأبعد عن الخيام وحَمَل ما غَنِمَه وما غنمته مماليكُه وخواصه، وأقام السلطان يومين وهو يباشر القِسمةَ بنفسه، وما ترك شيئًا حتى قسَّمَه ثم ركب السلطان إلى القلعة وأحرقها، وعم بالحريقِ أنطاكية، فأخذ الناسُ من حديد أبوابها ورصاص كنائسِها ما لا يوصف كثرةً، وأقيمت الأسواق خارج المدينة، فقَدِمَ التجَّار من كل جهة، وكان بالقرب من أنطاكية عدَّةُ حصون، فطلب أهلُها الأمان، فتوجه إليهم الأمير بيليك الأشرفي وتسلمها في الحادي عشر، وأسر من فيها من الرجال، ورحل السلطان من أنطاكية إلى شيزر، ثم سار السلطانُ من حمص إلى دمشق، فدخلها في السادس عشر والأسرى بين يديه."},{"id":2690,"title":"السلطان الظاهر بيبرس يحرر قلعة بغراس .","date":["العام الهجري :666","الشهر القمري : رمضان","العام الميلادي :1268"],"text":"حرر الملك الظاهر بغراس وسبب ذلك أنَّه لما فتح أنطاكية، هرب أهلُ بغراس منها وتركوا الحِصنَ خاليًا، فأرسل الظاهِرُ من استولى عليها، وشحنه بالرِّجالِ والعُدَد، وصار من الحصونِ الإسلاميَّة."},{"id":2691,"title":"دخول السلطان بيبرس إلى دمشق بعد تحرير أنطاكية .","date":["العام الهجري :666","الشهر القمري : رمضان","العام الميلادي :1268"],"text":"لما فرغ أمر السلطانِ الظاهِرِ من غزوه للشامِ وتحرير أنطاكية عاد منصورًا، فدخل دمشقَ في السابع والعشرين من رمضان في أبهة عظيمة وهيئة هائلة، وقد زُينت له البلد، ودُقت البشائر فرحًا به."},{"id":2692,"title":"السلطان الظاهر بيبرس يجدد البيعة لولده بركة من بعده .","date":["العام الهجري :667","الشهر القمري : صفر","العام الميلادي :1268"],"text":"جدَّد السلطان الظاهِرُ البيعةَ لولده من بعده الملك السعيدِ محمد بركة خان، وأحضَرَ الأمراءَ كُلَّهم والقضاة والأعيان وأركَبَه ومشى بين يديه، وكتب له ابنُ لقمان تقليدًا هائلًا بالمُلكِ مِن بعد أبيه، وأن يحكُمَ عنه أيضًا في حالِ حياته."},{"id":2693,"title":"إبطال السلطان الظاهر بيبرس الخمور وبيوت الخنا .","date":["العام الهجري :667","الشهر القمري : جمادى الآخرة","العام الميلادي :1269"],"text":"أمَرَ السلطان الملك الظاهر بإراقةِ الخمور وتبطيل المُفسِدات وبيوت الخنا بالبلاد كلها، فنُهِبَت الزواني وسُلِبنَ جميعَ ما كان معهن حتى يتزوَّجنَ، وكُتِبَ إلى جميع البلاد بذلك، وأسقَطَ المكوسَ التي كانت مرتَّبةً على ذلك، وعوَّضَ من كان محالًا على ذلك بغيرِها."},{"id":2694,"title":"الظاهر بيبرس يبسط نفوذه على الحجاز .","date":["العام الهجري :667","الشهر القمري : ذي القعدة","العام الميلادي :1269"],"text":"وصَلَ السلطانُ بيبرس إلى المدينة النبويَّةِ في خامس عشر من ذي القعدة، فلم يقابِلْه جماز ولا مالك أميرا المدينة وفَرَّا منه، ورحل منها في سابع عشر، وأحرم فدخل مكَّةَ في خامس ذي الحجة، وأعطى خواصَّه جملةً من المال ليفَرِّقوها سرًّا، وفرق كساويَ على أهل الحرمينِ وصار كواحدٍ مِن الناس، لا يحجُبُه أحَدٌ ولا يحرُسُه إلا الله، وهو منفَرِدٌ يصلي ويطوف ويسعى، وغَسَلَ البيتَ، وصار في وسط الخلائق، وكلُّ من رمى إليه إحرامَه غَسَلَه وناولَه إيَّاه، وجلس على باب البيت، وأخذ بأيدي النَّاسِ ليُطلِعَهم إلى البيت، فتعلَّق بعض العامَّة بإحرامه ليَطلَعَ فقَطَعه، وكاد يرمي السُّلطانَ إلى الأرض، وهو مستبشر بجميعِ ذلك، وعَلَّق كسوة البيت بيده وخواصِّه، وتردد إلى مَن بالحرمين من الصالحين، هذا وقاضي القضاة صدر الدين سليمان بن عبد الحق الحنفي مرافِقُه طول الطريق، يستفتيه ويتفهَّمُ منه أمر دينه، ولم يغفُل السلطان مع ذلك تدبيرَ الممالك، وكتاب الإنشاء تكتُبُ عنه في المهمات، وكتب إلى صاحِبِ اليمن كتابًا ينكر عليه أمورًا، ويقول فيه: سطرتُها من مكة المشرَّفة، وقد أخذت طريقها في سبع عشرة خطوة يعني بالخطوة المغزلة، ويقول له: الملك هو الذي يجاهِدُ في الله حَقَّ جهاده، ويبذلُ نَفسَه في الذبِّ عن حوزةِ الدين، فإن كنتَ ملكًا فأخرج التتارَ، وأحسَن السلطانُ إلى أميري مكة، وهما الأمير نجم الدين أبي نمي والأمير إدريس بن قتادة، وإلى أمير ينبُع وأمير خليص وأكابر الحجاز، وكتب منشورين لأميري مكَّة، فطلبا منه نائبًا تقوى به أنفسُهما، فرتَّبَ الأمير شمس الدين مروان نائب أمير جاندار بمكة، يرجع أمرُهما إليه ويكون الحَلُّ والعقد على يديه، وزاد أميري مكة مالًا وغِلالًا في كلِّ سنة بسبَبِ تسبيل البيتِ للنَّاسِ، وزاد أمراءَ الحجاز إلَّا جمازًا ومالكًا أميري المدينة، فإنهما انتزحا من بين يديه، وقضى السلطانُ مَناسِكَ الحج وسار من مكَّةَ في الثالث عشر، فوصل إلى المدينة في العشرينَ منه، فبات بها وسار من الغدِ، فجَدَّ في السير ومعه عدةٌ يسيرة حتى وصل إلى الكرك بُكرةَ يوم الخميس آخره، ولم يعلم أحدٌ بوصوله إلا عند قبر جعفر الطيَّار بمؤتة، فالتَقَوه هناك، ودخل السلطانُ مدينة الكرك وهو لابس عباءةً، وقد ركب راحلةً، فبات بها ورحل من الغد."},{"id":2695,"title":"رياح وأمطار شديدة في مصر يهلك بسببها الكثير .","date":["العام الهجري :667","الشهر القمري : ذي الحجة","العام الميلادي :1269"],"text":"هبَّت ريحٌ شديدة بديار مصر غرقت مائتي مركبٍ في النيل، وهلك فيها خلقٌ كثير، ووقع هنالك مطرٌ شديدٌ جدًّا، وأصاب الشامَ من ذلك صقعةٌ أهلَكَت الثِّمارَ."},{"id":2696,"title":"تحصين الإسكندرية وعمل الجسور خوفًا من مداهمة الفرنجة .","date":["العام الهجري :668","العام الميلادي :1269"],"text":"اهتم السلطان الظاهر لأمر الإسكندرية وأولاها اهتمامَه البالغ كل ذلك لأنها محطُّ نظر الفرنج، ومنها يدخلون مصرَ، فأمر بتحصينها للغايةِ، فعُمِلَت الجسور عليها التي تمنع دخول السفنِ وحُصِّنَت بالأسوار، وقُتِلَت الكلابُ التي فيها."},{"id":2697,"title":"حرب الموحدين مع بني مرين ونهاية دولة الموحدين في المغرب .","date":["العام الهجري :668","الشهر القمري : محرم","العام الميلادي :1269"],"text":"قام ملك الموحدين الواثقُ بالله المعروف بأبي دبوس بالسير لقتال بني مرين فالتقى معهم في معركة جرت في وادي غفو بين مراكش وفاس، انهزم فيها الموحدون وقُتل فيها أبو العلاء إدريس بن عبد الله بن محمد بن يوسف الواثق واستولى المرينيون على معسكرهم، وكان الواثق آخر ملوك الموحدين في المغرب، وبالتالي تنتهي دولتهم في المغرب."},{"id":2698,"title":"تحالف الصليبيين مع المغول .","date":["العام الهجري :668","الشهر القمري : ربيع الأول","العام الميلادي :1269"],"text":"بعد أن رجع السلطان الظاهر من الحج ودخل دمشق وعاد منها إلى مصر، بلغه حركة التتار، وأنهم واعدوا فرنج الساحل، فعاد إلى قلعة الجبل، فورد الخبر بغارة التتار على الساجور بالقرب من حلب، فجرد السلطانُ الأميرَ علاء الدين البندقدار في جماعة من العسكر، وأمره أن يقيمَ في أوائل البلاد الشاميَّة على أُهبة، وسار السلطانُ من قلعة الجبل في ليلة الاثنين الحادي عشر ربيع الأول ومعه نفرٌ يسير فوصَلَ إلى غزةَ، ثمَّ دخل دمشق في سابع ربيع الآخر، ولحق الناسَ في الطريق مشقةٌ عظيمة من البرد، فخيَّم على ظاهر دمشق، ووردت الأخبارُ بانهزام التتار عندما بلغهم حركةُ السلطان، ثم ورد الخبَرُ بأن جماعة من الفرنج خرجوا من الغرب، وبعَثوا إلى أبغا بن هولاكو بأنهم واصلون لمواعدتِه من جهة سيس في سفن كثيرةٍ، فبعث الله على تلك السفن ريحًا أتلفت عدَّةً منها، ولم يُسمَع بعدها لمن بقي في الأخرى خبَرٌ."},{"id":2699,"title":"إغارة السلطان الظاهر بيبرس على عكا بسبب نكثهم العهد .","date":["العام الهجري :668","الشهر القمري : ربيع الأول","العام الميلادي :1269"],"text":"خرج فرنج عكا وخيَّموا بظاهرها، وركبوا وأعجبَتْهم أنفسُهم بمن قدم إليهم من فرنج الغرب، وتوجَّهت طائفة منهم إلى عسكر جينين وعسكر صفد، فخرج السلطانُ من دمشق على أنه يتصَيَّد في مرج برغوث وبعث من أحضر إليه العُدَد ومن أخرج العساكرَ كُلَّها من الشام، فتكاملوا عنده بكرةَ يوم الثلاثاء الحادي عشر ربيع الأول بمرج برغوث، وساق بهم إلى جسرِ يعقوب فوصل آخرَ النهار، وسار بهم في الليل فأصبحَ في أول المرج، وكان السلطانُ قد سيَّرَ إلى عساكر عين جالوت وعساكر صفد بالإغارة في الثاني عشر، فإذا خرج إليهم الفرنج انهزموا منهم، فاعتمدوا ذلك، ودخل السلطان الكمين، فعندما خرج جماعة من الفرنج لقتال عسكر صفد تقدم إليهم الأمير إيغان، ثم بعده الأمير جمال الدين الحاجبي، ومعهما أمراءُ الشام، ثم ساق الأمير أيتمش السعدي، والأميرُ كندغدي أمير مجلس، ومعهما مقدَّمو الحلقة، فقاتل الأمراءُ الشاميون أحسَنَ قتال، وتَبِعَ السلطان مقَدَّمي الحلقة، فما أدركهم إلا والعدوُّ قد انكسر، وصارت الخيَّالة بخيلها مطَّرحةً في المرج، وأسر السلطان كثيرا من أكابرهم، ولم يعدم من المسلمين سوى الأمير فخر الدين ألطونبا الفائزي، فسارت البشائرُ إلى البلاد، وعاد السلطانُ إلى صفد والرؤوس بين يديه، وتوجَّه منها إلى دمشق فدخَلَها في السادس عشر، والأسرى ورؤوس القتلى بين يديه."},{"id":2700,"title":"إغارة السلطان الظاهر بيبرس على حصن الأكراد  .","date":["العام الهجري :668","الشهر القمري : جمادى الآخرة","العام الميلادي :1270"],"text":"ركب السلطان في ثالث جمادى الآخرة، بمائتي فارس من غير سلاح، وأغار على حصن الأكراد وصَعِدَ الجبل الذي عليه حصن الأكرادِ ومعه قدر أربعين فارسًا، فخرج عليه عدة من الفرنج ملبسين، فحمل عليهم وقتل منهم جماعةً، وكسر باقيَهم وتبعهم حتى وصل إلى خنادقهم، وقال يستخف بهم: خلوا الفرنجَ يخرجوا، فما نحن أكثَرُ من أربعين فارسًا، وعاد إلى مخيمه، ورعى الخيولُ مروجَها وزروعَها."},{"id":2701,"title":"أمراء الشام يقدمون على الظاهر بيبرس لتقديم فروض الطاعة .","date":["العام الهجري :668","الشهر القمري : جمادى الآخرة","العام الميلادي :1270"],"text":"أثناء حصارِ السلطان بيبرس حصن الأكرادَ حضر إلى خدمة السلطان كثيرٌ من أصحاب البلاد المجاورة، فلم يبق أحدٌ إلا وقدم على السلطان مثل: صاحب حماة، وصاحب صهيون، إلا نجم الدين حسن بن الشعراني صاحب قلاع الإسماعيليَّة، فإنه لم يحضر بل بعث يطلبُ تنقيضَ القطعة التي حملوها لبيت المال، بدلًا مما كانوا يحملونه إلى الفرنج، وكان صارم الدين مبارك بن الرضي صاحب العليقة قد تغير السلطان عليه من مدة، فدخل صاحب صهيون بينه وبين السلطان في الصلح، وأحضره إلى الخدمة، فقَلَّدَه السلطان بلاد الدعوةِ استقلالًا، وأعطاه طبلخاناه، وعزل نجمَ الدين حسن بن الشعراني وولده من نيابة الدعوة، وتوجه صارم الدين إلى مصياف كرسي بلاد الإسماعيليَّة في السابع عشر جمادى الآخرة، وصَحِبَته جماعةٌ لتقرير أمره."},{"id":2702,"title":"الحملة الصليبية الثامنة على شمال أفريقيا بقيادة لويس التاسع .","date":["العام الهجري :669","الشهر القمري : ربيع الأول","العام الميلادي :1270"],"text":"قام ملك فرنسا لويس التاسع بتجهيز حملة صليبيةٍ هي في التعداد الثامنة، وقصد بها تونسَ ليجعَلَها طريقه إلى مصر، لكنَّ قواتِ أمير تونس أبي عبد الله محمد بن أبي زكريا الحفصي تصَدَّت لها وساعد أيضًا على فشلها انتشار الأوبئة بينهم مع حرارةِ الجو وكان ممَّن توفي في تونس من الصليبيين الملك نفسُه لويس التاسع، غير الكثير من أفراد جيشه."},{"id":2703,"title":"وفاة الملك تقي الدين عباس بن الملك العادل الأيوبي .","date":["العام الهجري :669","الشهر القمري : جمادى الآخرة","العام الميلادي :1271"],"text":"هو الملك تقي الدين عباس بن الملك العادل أبي بكر بن أيوب بن شاذي، وهو آخِرُ من بقي من أولاد العادل، وقد سَمِعَ الحديثَ مِن الكندي وابن الحرستاني، وكان محترمًا عند الملوك لا سيما عند الملك الظاهِرِ لا يترفَّعُ عليه أحد في المجالِسِ والمواكب، وكان لين الأخلاق حَسَن العِشرة، لا تُمَلُّ مجالسته‏, توفِّيَ يوم الجمعة الثاني والعشرين من جمادى الآخرة بدرب الريحان، ودُفِنَ بتربة له بسفح قاسيون."},{"id":2704,"title":"السلطان الظاهر بيبرس يفتح حصن الأكراد .","date":["العام الهجري :669","الشهر القمري : شعبان","العام الميلادي :1271"],"text":"في يوم الخميس ثامن رجب دخل الظاهر دمشق وفي صحبته ولده الملك السعيد بركة وابن الحنا الوزير وجمهور الجيش ثم خرجوا متفرقين وتواعدوا أن يلتقوا بالساحل ليشنوا الغارة على جبلة واللاذقية ومرقب وعرقا وما حولها من البلاد، فلما اجتمعوا فتحوا صافينا والمجدل، ثم ساروا فنزلوا على حصنِ الأكراد يوم الثلاثاء التاسع عشر رجب، وله ثلاثةُ أسوار، فنصبوا المنجنيقاتِ ففتحها قسرًا يوم نصف شعبان، فدخل الجيش، وكان الذي يحاصره ولد السلطان الملك السعيد بركة، فأطلق السلطان أهله ومَنَّ عليهم وأجلاهم إلى طرابلس، وتسَلَّم القلعةَ بعد عشرة أيام من الفتح، فأجلى أهلَها أيضًا وجعل كنيسةَ البلد جامعًا، وأقام فيه الجمعة، وولى فيها نائبًا وقاضيًا وأمر بعمارة البلد، وبعث صاحبَ طرسوس بمفاتيح بلده يطلُبُ منه الصُّلحَ على أن يكون نصف مغل بلاده للسلطان، وأن يكون له بها نائبًا فأجابه إلى ذلك، وكذلك فعل صاحب المرقب فصالحه أيضًا على المناصفة ووضع الحربَ عشرَ سنين."},{"id":2705,"title":"تحرير السلطان الظاهر حصن عكا .","date":["العام الهجري :669","الشهر القمري : رمضان","العام الميلادي :1271"],"text":"بلغ السلطان الظاهر بيبرس وهو مخيِّم على حصن الأكراد أنَّ صاحب جزيرة قبرص قد ركِبَ بجيشه إلى عكا لينصُرَ أهلها خوفًا من السلطان، فأراد السلطان أن يغتَنِمَ هذه الفرصة فبعث جيشًا كثيفًا في اثني عشرة شيني - نوعا من المراكب- ليأخذوا جزيرة قبرص في غيبةِ صاحِبِها عنها، فسارت المراكِبُ مسرعة فلما قاربت المدينة جاءتها ريحٌ عاصف فصدم بعضها بعضًا فانكسر بعضُها, وغَرِقَ خلقٌ وأسَرَ الفرنج من الصناع والرجال قريبًا من ألف وثمانمائة، ثم سار السلطانُ فنصب المجانيق على حِصنِ عكا فسأله أهلُها الأمان على أن يخَلِّيَهم فأجابهم إلى ذلك، ودخل البلدَ يوم عيد الفطر فتسَلَّمه، وكان الحِصنُ شديد الضرر على المسلمين، وهو وادٍ بين جبلين."},{"id":2706,"title":"وفاة ابن سبعين الصوفي .","date":["العام الهجري :669","الشهر القمري : شوال","العام الميلادي :1271"],"text":"هو أبو محمد عبد الحق بن إبراهيم بن محمد بن نصر بن محمد بن نصر بن محمد بن سبعين، القرشي، المخزومي، بن قطب الدين المقدسي  الصوفي الرقوطي، نسبة إلى رقوطة بلدة قريبة من مرسية بالأندلس. المشهور بابن سبعين، ولِدَ سنة أربع عشرة وستمائة، واشتغل بعلم الأوائل والفلسفة، فتولَّدَ له من ذلك نوع من الإلحاد، وصنَّفَ فيه، وكان يعرف السيميا، وكان يلَبِّسُ بذلك على الأغبياء من الأمراء والأغنياء، ويزعُمُ أنه حال من أحوال القوم، وله المصنفات منها كتاب البدوي، وكتاب الهو، رسالة النصيحة النورية، عهد ابن سبعين، الإحاطة، الرسالة الفقيرية، الحكم والمواعظ، الرسالة القبرصية,  وقد أقام بمكة واستحوذ على عقل صاحبها أبي نمي بن أبي سعد. وشاع صيتُه وكثر أتباعه بين أهل مكة بسبب سخائه وعِلمِه، وقد ظل ابن سبعين في مكَّة حتى توفي به، وجاور في بعض الأوقاتِ بغار حراء يرتجي فيما يُنقَلُ عنه أن يأتيه فيه وحيٌ، كما أتى النبيَّ صلى الله عليه وسلم!! بناء على ما يعتقده من العقيدة الفاسدة من أن النبوة مكتسبة، وأنها فيض يفيض على العقل إذا صفا، فما حصل له إلا الخزي في الدنيا والآخرة، إن كان مات على ذلك, وقد كان إذا رأى ابن سبعين الطائفينَ حول البيت يقول عنهم كأنهم الحميرُ حول المدار، وأنهم لو طافوا به كان أفضَلَ من طوافهم بالبيتِ، وقد نُقِلَت عنه عظائم من الأقوال والأفعال. قال شيخ الإسلام ابن تيمية: \"فصار بعضُهم يرى أن باب النبوة مفتوح لا يمكن إغلاقُه فيقول كما كان ابن سبعين يقول: \"لقد زرَّب ابن آمنة حيث قال: لا نبي بعدي\" أو يرى لكونه أشد تعظيمًا للشريعة أن باب النبوة قد أغلق فيدعي أن الولاية أعظم من النبوة، وأن خاتم الأولياء أعلم بالله من خاتم الأنبياء، وأن خاتم الأنبياء بل وجميع الأنبياء إنما يستفيدون معرفة الله من مشكاة خاتم الأولياء!! ويقول إنه يوافق النبي في معرفة الشريعة العملية؛ لأنه يرى الأمر على ما هو عليه فلا بد أن يراه هكذا، وإنه أعلم من النبي بالحقائق العلمية؛ لأنه يأخذ من المعدن الذي يأخذ منه الملك الذي يوحى به إلى الرسول!! وهذا بناء على أصول هؤلاء الفلاسفة الكفار الذين هم أكفر من اليهود والنصارى\". وقال شيخ الإسلام: \"ابن سبعين أحد أئمة الاتحادية ومحققيهم وأذكيائهم، أنه قال عن كلام ابن عربي:  \"فلسفة مخموجة\" وكلامه هو أدخل في الفلسفة وأبعد عن الإسلام، ولا ريب أن هؤلاء من جنس الملاحدة الباطنية القرامطة، وهؤلاء الفلاسفة مشتركون في الضلال ومذاهب هؤلاء الفلاسفة في الإلهيات من أشد المذاهب اضطرابًا وتناقضًا وقولًا لا حقيقة له، فلما كان مذهبهم المقارنة التي هي في الحقيقة تعطيل الصنع والخلق والإبداع وإن كانوا يدَّعون أنهم يثبتون واجبًا غير العالم، فهذا دعواهم، وإلا ففي الحقيقة يلزمهم ألا يكون ثَمَّ واجِبُ الوجود غير العالم، وهذا حقيقة قول الاتحادية وهو الذي أظهره إمام هؤلاء فرعون؛ فإن الاتحادية تنتحله وتعظمه والباطنية تنتحله وتعظمه وهو على مقتضى أصول الفلاسفة الصابئة المشركين الذين هم من أعظم الناس إيمانًا بالجبت والطاغوت\" قال الذهبي: \"كان ابن سبعين صوفيًّا على قاعدة زهاد الفلاسفة وتصوفهم، وله كلام كثير في العرفان على طريق الاتحاد والزندقة, وقد ذكرنا محط هؤلاء الجنس في ترجمة \" ابن الفارض \"، و \" ابن العربي \" وغيرهما. فيا حسرة على العباد كيف لا يغضبون لله تعالى ولا يقومون في الذبِّ عن معبودهم، تبارك اسمُه وتقدست في ذاته، عن أن يمتزج بخَلقِه أو يحِلَّ فيهم, وتعالى الله عن أن يكون هو عينَ السموات والأرض وما بينهما, فإن هذا الكلام شر من مقالة من قال بقدم العالم، ومن عرف هؤلاء الباطنية عذرني، أو هو زنديق مبطن للاتحاد يذب عن الاتحادية والحلولية، ومن لم يعرفهم فالله يثيبه على حسن قصده. وينبغي للمرء أن يكون غضَبُه لربه إذا انتُهِكَت حرماته أكثَرَ من غضبه لفقير غير معصوم من الزَّلَل. فكيف بفقير يحتمل أن يكون في الباطن كافرًا، مع أنا لا نشهد على أعيان هؤلاء بإيمان ولا كفر لجواز توبتهم قبل الموت. وأمرهم مُشكِل وحسابُهم على الله, وأما مقالاتهم فلا ريب في أنها شر من الشرك، فيا أخي ويا حبيبي أعطِ القوس باريَها ودعني ومعرفتي بذلك، فإنني أخاف الله أن يعذبني على سكوتي، كما أخاف أن يعذبني على الكلام في أوليائه. وأنا لو قلت لرجل مسلم: يا كافر، لقد بؤتُ بالكفر، فكيف لو قلتُه لرجل صالح أو ولي لله تعالى؟ \"  توفي ابن سبعين في الثامن والعشرين من شوال بمكة."},{"id":2707,"title":"السلطان الظاهر بيبرس يحرر القرين .","date":["العام الهجري :669","الشهر القمري : ذي القعدة","العام الميلادي :1271"],"text":"خرج السلطان الظاهر بيبرس من دمشق وأتى إلى الساحل، ثم سار إلى القرين وهي  قلعة تقع شمال شرق عكا ونازله، وأخذ باشورته –حائط ظاهر الحصن يختفي وراءه الجند عند القتال- في ثاني ذي القعدة، فأخذ الحصن وأمر بهدم قلعته، ثم سار عنه ونزل اللجون، وتقدمت مراسيمه إلى النواب بالديار المصرية بتجهيز الشواني، ثم إن السلطان جاء إلى عكا وأشرف عليها وتأملها، ثم سار إلى الديار المصرية."},{"id":2708,"title":"السلطان الظاهر بيبرس يأمر بإراقة الخمور من سائر بلاده .","date":["العام الهجري :669","الشهر القمري : ذي الحجة","العام الميلادي :1271"],"text":"وفي اليوم السابع عشر من ذي الحجة من هذه السنة أمر بإراقة الخمور من سائر بلادِه وتهَدَّد من يعصِرُها أو يعتَصِرُها بالقتل، وأسقَطَ ضمان ذلك، وكان ذلك بالقاهرة وحدها كلَّ يوم ضمانه ألف دينار، ثم سارت البُرُد بذلك إلى الآفاق."},{"id":2709,"title":"الروم يغيرون على بعض بلاد المسلمين .","date":["العام الهجري :670","الشهر القمري : ربيع الآخر","العام الميلادي :1271"],"text":"وصلت العساكرُ المصريَّةُ إلى حضرة السلطان الظاهر بيبرس إلى دمشق فسار بهم منها في سابع هذا الشهر، فاجتاز بحماة واستصحب ملكها المنصور، ثم سار إلى حَلَب فخيم بالميدان الأخضر بها، وكان سَبَبُ ذلك أن عساكِرَ الروم جمعوا نحوًا من عشرة آلاف فارس وبعثوا طائفةً منهم فأغاروا على عينِ تاب، ووصلوا إلى نسطون ووقعوا على طائفة من التركمان بين حارم وأنطاكية فاستأصلوهم، فلما سمع الروم بوصول السلطان ومعه العساكر المنصورة ارتدوا على أعقابهم راجعينَ، وكان بلغه أن الفرنج أغاروا على بلاد قاقون ونهَبوا طائفة من التركمان، فقبض على الأمراءِ الذين هناك حيث لم يهتَمُّوا بحفظ البلاد وعادوا إلى الديارِ المصرية."},{"id":2710,"title":"محاربة السلطان الظاهر طائفة من التتار وخوضه نهر الفرات .","date":["العام الهجري :671","الشهر القمري : جمادى الآخرة","العام الميلادي :1273"],"text":"في خامس جمادى الآخرة وصل السلطان بعسكره إلى الفراتِ؛ لأنه بلغه أن طائفةً مِن التتار هنالك فخاض إليهم الفراتَ بنَفسِه وجنده، وقتل من أولئك مقتلةً كبيرةً وخلقًا كثيرًا، وكان أوَّلَ من اقتحم الفراتَ يومئذ الأميرُ سيف الدين قلاوون وبدر الدين بيسرى وتبعهما السلطانُ، وكان قد اقتحم الأمير قلاوون الألفي الصالحي الفرات، فخاض ومعه عِدَّةٌ وافرة، وصدم التتارَ صَدمةً فَرَّقهم بها ومزَّقهم، ثم فعل بالتتار ما فعل من القتلِ والأسر، ثم ساق إلى ناحيةِ البيرة وقد كانت محاصرةً بطائفة من التتار أخرى، فلما سمعوا بقدومه هربوا وتركوا أموالهم وأثقالهم، ودخل السلطانُ إلى البيرة في أبَّهة عظيمةٍ وفَرَّق في أهلها أموالًا كثيرة، ثم عاد إلى دمشقَ في ومعه الأسرى."},{"id":2711,"title":"وفاة الإمام العلامة القرطبي صاحب التفسير .","date":["العام الهجري :671","الشهر القمري : ذي القعدة","العام الميلادي :1273"],"text":"هو الإمامُ العلَّامة، المتفنن المتبحر في العلم، أبو عبد الله محمد بن أحمد بن أبي بكر بن فرخ الخزرجي الأنصاري القرطبي، من أهل قرطبة، كان عالِمًا بالتفسير والأحكام واللغة. قال الذهبي: \"له تصانيفُ مفيدة تدل على كثرة اطلاعه ووفور فضله، أشهرها تفسيره الجامع لأحكام القرآن، وقد سارت به لعظيمِ شأنه الركبانُ، وهو كامل في معناه. ومن تصانيفه كذلك: الأسنى في شرح أسماء الله الحسنى، والتذكار في أفضل الأذكار،  وكتاب \"التذكرة\"، وأشياء تدل على إمامته وذكائه وكثرة اطلاعه\". رحل إلى المشرق واستقر في شمال أسيوط، كان عالِمًا بالتفسير والأحكام واللغة. توفي في أوائل هذه السنة بمنية بني خصيب من الصعيد الأدنى عن 93 عامًا."},{"id":2712,"title":"تسليم الإسماعيلية ما كان بقي بأيديهم من الحصون .","date":["العام الهجري :671","الشهر القمري : ذي القعدة","العام الميلادي :1273"],"text":"في سادس عشر من صفر عام 670هـ قدم شمس الدين بن نجم الدين صاحب الدعوة الإسماعيلية، فقُبِضَ عليه وعلى أصحابه وسُيِّروا إلى مصر، واستمرت مضايقةُ حصونهم حتى تسَلَّم نواب السلطان حصنَ الخواني وحصن العليقة، وفي ذي القعدة من هذا العام سلمت الإسماعيليةُ ما كان بقي بأيديهم من الحصونِ، وهي الكهف، والقدموس، والمنطقة، وعُوِّضوا عن ذلك بإقطاعات، ولم يبق بالشامِ شَيءٌ لهم من القلاع، واستناب السلطانُ فيها."},{"id":2713,"title":"وفاة الملك المغيث عمر بن الملك العادل .","date":["العام الهجري :671","الشهر القمري : ذي الحجة","العام الميلادي :1273"],"text":"هو الملك المغيث فتح الدين أبو الفتح عمر بن الملك العادل أبي بكر بن الملك الكامل محمد بن الملك العادل أبي بكر بن أيوب، صاحب الكرك، كان مولده بالقاهرة في صفر سنة 606. قتل المَلِك المغيث في هذه السنة, وسَبَب قتله كما قال الذهبي: \"أنه كان في قلب الملك الظاهِرِ بيبرس منه غيظٌ عظيم، لأمورٍ كانت بينهما، قيل إنَّ المغيث أكره امرأةَ الملك الظاهر بيبرس، لَمَّا قبضَ المغيث على البحرية. وأرسَلَهم إلى الناصر يوسف صاحب دمشق، وهرب الملِكُ الظاهر بيبرس، وبقيت امرأتُه في الكرك، والله أعلم بحقيقة ذلك، وكان من حديثِ مَقتَلِه: أنَّ الملك الظاهر بيبرس ما زال يجتهد على حضور المغيث، وسار المغيثُ حتى وصل إلى بيسان، فركب الملك الظاهِرُ بعساكره والتقاه في يوم السبت السابع والعشرين من جمادى الأولى من هذه السنة، فلما شاهَدَ المغيث الملك الظاهر، ترجَّلَ فمنعه الملك الظاهِرُ وأركبه وساقَ إلى جانِبِه، وقد تغير وجهُ الملك الظاهر، فلما قارب الدهليز، أفرد المَلِكَ المغيثَ عنه وأنزَلَه في خيمةٍ وقَبَضَ عليه، وأحضر الفُقَهاءَ والقضاة وأوقَفَهم على مكاتبات من التتار  إلى الملك المغيث، أجوبةً عمَّا كتب إليهم به في إطماعِهم في ملك مصر والشام, ثم أرسَلَه مُعتَقَلًا إلى مصر، فكان آخرَ العهد به. وقيل إنه حُمِلَ إلى امرأة الملك الظاهر بيبرس بقلعة الجبل، فأمَرَت جواريَها فقتَلْنَه بالقباقيبِ\" قُتِلَ المغيث في السابع والعشرين من ذي الحجة."},{"id":2714,"title":"مقتل رجل ادعى أنه عيسى بن مريم .","date":["العام الهجري :672","العام الميلادي :1273"],"text":"فوض ملك التتار إلى علاء الدين صاحب الديوان ببغداد النظرَ في تستُرَ وأعمالِها، فسار إليها ليتصَفَّحَ أحوالها فوجد بها شابًّا من أولاد التجَّار يقال له \"لي\" قد قرأ القرآنَ وشَيئًا من الفقه والإشارات لابن سينا، ونظر في النجوم، ثمَّ ادعى أنه عيسى ابن مريم، وصَدَّقه على ذلك جماعةٌ من جهلة تلك الناحية، وقد أسقَطَ لهم من الفرائِضِ صلاةَ العصر وعِشاء الآخرة!! فاستحضره وسأله عن ذلك فرآه ذكيًّا، إنما يفعل ذلك عن قصدٍ، فأمر به فقُتِلَ بين يديه، جزاه الله خيرًا، وأمر العوامَّ فنهبوا أمتعَتَه وأمتعة العوامِّ ممَّن كان اتبعه."},{"id":2715,"title":"وفاة جلال الدين الرومي أحد أعلام الشعر الصوفي .","date":["العام الهجري :672","الشهر القمري : جمادى الآخرة","العام الميلادي :1274"],"text":"هو جلال الدين محمد بن محمد بن حسين بهاء الدين البلخي البكري, وعرف أيضًا باسم مولانا جلال الدين الرومي شاعر، عالمٌ بفقه الحنفيَّة. من فحولِ شعراء الصوفية في الإسلام. وُلد ببلخ في 6 من ربيع الأول 604هـ (30 من سبتمبر 1207م) لأسرةٍ قيل: إن نسَبَها ينتهي إلى أبي بكر الصديقِ رضي الله عنه، وتحظى بمصاهرة البيت الحاكم في خوارزم، وأمُّه كانت ابنة خوارزم شاه علاء الدين محمد, وما كاد يبلغُ الثالثة من عمره حتى انتقل مع أبيه إلى بغداد سنة 607هـ (1210م) على إثر خلاف بين أبيه والوالي محمد قطب الدين خوارزم شاه, وفي بغداد نزل أبوه في المدرسة المستنصريَّة، ولكنه لم يستقِرَّ بها طويلًا؛ إذ قام برحلة واسعة ومعه ابنه جلال الدين زار خلالها دمشق ومكة وملطية وأرزبخان ولارند، ثم استَقَرَّ آخر الأمر في قونية في عام 632هـ (1226م) حيث وجَدَ أبوه الحماية والرعاية في كنف الأمير السلجوقي علاء الدين قبقباذ، واختير للتدريس في أربع مدارس بقونية حتى توفي سنة 628هـ (1231م)، فخلفه ابنه جلال الدين في التدريس بتلك المدارس. وقد عُرف جلال  الدين بالبراعة في الفقه إلا أنه لم يستمر كثيرًا في التدريس؛ فقد كان للقائه بالصوفي المعروف شمس الدين تبريزي أعظَمُ الأثر في حياته العقليَّة والأدبية، فمنذ أن التقى به حينما وفد على قونية في إحدى جولاته، تعلق به جلال الدين، وأصبح له سلطانٌ عظيمٌ عليه ومكانةٌ خاصة لديه. وانصرف جلال الدين بعد هذا اللقاء عن التدريس، وانقطع للتصوُّفِ ونظْمِ الأشعار وإنشادها، وأنشأ طريقةً صوفية عُرفت باسم المولويَّة نسبة إلى مولانا جلال الدين.اهتم جلال الدين الرومي بالرياضة وسماع الموسيقى، وجعل للموسيقى مكانةً خاصة في محافِلِ تلك الطريقة. توفِّي جلال الدين عن عمر بلغ نحو سبعين عامًا، ودُفن في ضريحه المعروف في \"قونية\" في تلك التكية التي أنشأها لتكون بيتًا للصوفيَّة."},{"id":2716,"title":"وفاة ابن مالك النحوي صاحب الألفية .","date":["العام الهجري :672","الشهر القمري : رمضان","العام الميلادي :1274"],"text":"هو العلَّامة الأوحَدُ، أبو عبدِ اللهِ جمالُ الدين محمد بن عبد الله بن مالك الطائي الجياني الأندلسي الشافعي النحوي، نزيلُ دمشق. ولد بجيَّان في الأندلس سنة 600 وأقام بحَلَب مدة، ثم بدمشق، أخذَ العربية عن غير واحد، وجالس بحلب ابن عمرون وغيره. وتصدر بحَلَب لإقراء العربية وصَرَف همَّتَه إلى إتقان لسان العرب حتى بلغ فيه الغايةَ، وحاز قَصَب السبق، وأربى على المتقدِّمين, وهو صاحب الألفية المشهورة (ألفية بن مالك) التي شرحها وَلَدُه بدر الدين شرحًا مفيدًا، وكان كثير الاجتماع بابنِ خَلِّكان وأثنى عليه غيرُ واحد، كان إمامًا في اللغة والنحو والقراءات وعِلَلِها، صَنَّف فيها قصيدة دالية مرموزة في مقدار \"الشاطبية\"، وأما اللغة فكان إليه المنتهى في الإكثارِ مِن نَقلِ غَريبِها والاطلاعِ على وَحشِيِّها، وأما النحو والتصريف فكان فيه بحرًا لا يجارى وحَبرًا لا يُبارى، وأما أشعار العرب التي يُستشهَدُ بها على اللغة والنحو فكانت الأئمَّة الأعلام يتحيَّرون فيه ويتعجبون من أين يأتي بها، وكان نظمُ الشِّعرِ سَهلًا عليه، رَجَزُه وطويلُه وبسيطُه وغير ذلك، هذا مع ما هو عليه من الدِّينِ المتين وصِدقِ اللهجة وكثرة النوافِلِ، وحُسنِ السَّمتِ، ورقة القلبِ، وكمال العقل والوقار والتؤَدة. أقام بدمشقَ مدة يصنِّف ويشغل. وتصدر بالتربة العادلية وبالجامع المعمور، وتخرج به جماعة كثيرة. وله تصانيفُ مشهورة المفيدة، منها الكافية الشافية وشرحها وهي في ثلاثة آلاف بيت، تسهيل الفوائد في النحو وشرحه، وسبك المنظوم وفك المختوم، وله تحفة المودود في المقصور والممدود، ولامية الأفعال، وغيرها، توفي ابن مالك بدمشق ليلة الأربعاء ثاني عشر رمضان، وقد نيف على التسعين، ودفن بتربة القاضي عز الدين بن الصائغ بقاسيون."},{"id":2717,"title":"وفاة نصير الدين الطوسي وزير هولاكو .","date":["العام الهجري :672","الشهر القمري : ذي الحجة","العام الميلادي :1274"],"text":"هو الفيلسوف الرياضي الفلكي نصير الدين أبو جعفر محمد بن عبد الله الطوسي، كان يقال له المولى نصير الدين، ويقال الخواجا نصير الدين، اشتغل في شبيبتِه وحصَّل علم الأوائلِ جيدًا، وصَنَّف في ذلك في علم الكلامِ، وشرح الإشارات لابن سينا، حتى كان رأسًا في علم الأوائل، لا سيَّما معرفة الرياضة وصنعة الأرصاد، فإنه فاق بذلك على الكبار. اشتغل في بداية أمرِه على المعين سالم بن بدران المصري المعتزلي، المتشيِّع الرافضي فنزع فيه عروق كثيرة منه، حتى أفسد اعتقادَه، وزَرَ نصير الدين لأصحاب قلاع ألموت من الإسماعيلية، ثم وزر لهولاكو، وكان ذا حُرمة وافرة ومنزلةٍ عاليةٍ عند هولاكو, وكان معه في واقعة بغداد، وقيل إنه أشار على هولاكو خان بقتل الخليفةِ بعد أن كان أحدُ منجِّمي هولاكو حذَّره من مغبة ذلك، وكان يطيعُه فيما يشير به, وجعله هولاكو على أوقافِ بغداد يتصَرَّف فيها كيف يشاء, فابتنى بمدينةِ مراغة قُبَّة رصد عظيمة ورتَّبَ فيها الحكماء من المنجِّمين والفلاسفة والمتكلمين والفقهاء والمحدثين والأطباء وغيرهم من أنواع الفضلاء، وجعل لهم الجامكيَّة- الراتب- واتخذ فيها خزانةً عظيمة عالية، فسيحةَ الأرجاء وملأها بالكتب التي نُهِبَت من بغداد والشام والجزيرة، حتى تجمَّعَ فيها زيادة على أربعمائة ألف مجلد. وكان سمحًا، كريمًا، حليمًا حسن العشرةِ، غزيرَ الفضائل، جليلَ القدر، لكنَّه على مذهب الأوائِلِ في كثيرٍ مِن الأصول، نسأل الله الهدى والسَّداد. وله شعرٌ جيد قوي, وله كتابُ أخلاق ناصري بالفارسية ألَّفه لمتملك الإسماعيليَّة لما كان وزيرًا له في ألموت، وله كتاب تجريد العقائد بالعربية، وهو في الفلسفة وعلم الكلام، وله إثبات العقل الفعال وشرح كتاب المجسطي (المنطق) وغير ذلك. قال ابن القيم: \" صارع محمد الشهرستانى ابن سينا في كتاب سماه \"المصارعة\" أبطل فيه قولَه بقدم العالم وإنكار المعاد، ونفى علمَ الرب تعالى وقدرته، وخلقه العالم، فقام له نصير الإلحاد وقعد، ونقَضَه بكتاب سماه \"مصارعة المصارعة\" ووقَفْنا على الكتابين نصر فيه: أن الله تعالى لم يخلق السموات والأرض في ستة أيام. وأنه لا يعلم شيئًا، وأنه لا يفعل شيئًا بقدرته واختياره، ولا يبعث من في القبور, وبالجملة فكان هذا الملحِدُ هو وأتباعه من الملحدين الكافرين بالله، وملائكته، وكتبه، ورسوله، واليوم الآخر\". توفي في بغداد في ثاني عشر ذي الحجة، وله خمس وسبعون سنة."},{"id":2718,"title":"استيلاء المرينيين على سجلماسة .","date":["العام الهجري :673","العام الميلادي :1274"],"text":"قام المنصور بالله أبو يوسف يعقوب بن عبد الحق المريني الأمازيغي بالاستيلاءِ على سجلماسة واستخلصها من أيدي بني زيان بعد أن حاصرها عامًا كاملًا، ويُذكَرُ أنه استعمل في هدم أسوارِها قاذفات البارود."},{"id":2719,"title":"الظاهر بيبرس يغزو كليكيا والمصيصة الأرمينية .","date":["العام الهجري :673","الشهر القمري : رمضان","العام الميلادي :1275"],"text":"في سابع رمضان دخل السلطانُ بيبرس حماة، ثم صار منها بالعساكر والعربان، وجرَّد السُّلطان عيسى بن مهنا، والأمير حسام الدين العنتابي، بعسكرٍ إلى البيرة، وجهَّزَ الأمير قلاوون الألفي والأمير بيليك الخازندار – ممسك خزنة المال-  بعسكرٍ إلى بلاد سيس؛ وذلك بسبب أن الحاجِبَ معين الدين سليمان بن مهذب الدين علي الديلمي وزير قليج أرسلان الرابع ملك سلاجقة الروم دعاه إليها وحرضه على القدوم، وبسبب أيضا تحالف الأرمنيين مع التتار، فساروا وهجموا على الأرمن في المصيصة، وقتلوا من بها، وكانت المراكِبُ قد حملت معهم على البغال وهي مفصلة، ليعدُوا فيها من نهر جهان والنهر الأسود، فلم يحتَجْ إليها، ووصل السلطانُ على الأثر بعد ما قطع بعساكره النهرَ الأسود وقاسَوا مشقة، وملكوا الجبالَ وغَنِموا عنها ما لا يحصى كثرة، ما بين أبقار وجواميس وأغنام، فدخل السلطانُ إلى سيس في التاسع عشر وعيَّدَ بها، وانتهبها وهدم قصور التكفور ومناظِرَه وبساتينَه، وبعث إلى دربند الروم، فأحضر إليه من سبايا التتار عدة نساء وأولاد، وسَيَّرَ إلى طرسوس، فأُحضِرَ إليه منها ثلاثمائة رأس من الخيل والبغال، وبعث إلى البحر عسكرًا فأخذ مراكب، وقتل من كان فيها، وانبثت الغاراتُ في الجبال، فقتلوا وأسروا وغنموا، وبعث السلطانُ إلى إياس بالعساكر، وكانت قد أُخلِيَت، فنَهَبوا وحَرَقوا وقَتَلوا جماعةً، وكان قد فَرَّ مِن أهلها نحوُ الألفين ما بين فرنج وأرمن في مراكب، فغَرِقوا بأجمَعِهم في البحر، واجتمَعَ من الغنائم ما لا يحصُرُه قَلَمٌ لكثرته، ووصلَت العُربان والعسكَرُ إلى البيرة، وساروا إلى عينتاب وغنموا، فانهزم التتارُ منهم وعادوا، فرحل السلطانُ من سيس إلى المصيصة من الدربند، فلما قطَعَه جعل الغنائِمَ بمرج أنطاكيةَ حتى ملأته طولًا وعرضًا، ووقف بنفسه حتى فرقها، فلما فرغ من القسمة سار إلى دمشق، فدخلها في النصفِ من ذي الحجة."},{"id":2720,"title":"ملك غرناطة يستنجد بملك مرين .","date":["العام الهجري :674","العام الميلادي :1275"],"text":"استنجد أبو عبد الله محمد الثاني بن محمد الأول ملك غرناطة الملقَّب بالفقيه السلطان أبي يوسف المنصور يعقوب بن عبد الحق ملك بني مرين فسَيَّرَ إليه الأخير جيشًا كثيفًا عبر البحر ونزل مدينةَ طريف وأخذ في غزو البلاد التي استولى عليها الأسبانُ فخرج إليه سانشو ملك قشتالة ووقع اللقاءُ على مقربة من مدينة استجه، وانتهت المعركة الضارية بانتصار المسلمين فطلب سانشو الصلحَ فاستجاب السلطان واشترط شروطًا منها مسالمةُ المسلمين وعدم الاعتداءِ على أراضيهم."},{"id":2721,"title":"التتار والروم ومن تواطأ معهم من المسلمين يغزون البيرة .","date":["العام الهجري :674","الشهر القمري : جمادى الأولى","العام الميلادي :1275"],"text":"نزل التتار على البيرة في ثلاثين ألف مُقاتلٍ، خمسة عشر ألفًا من المغول، وخمسة عشر ألفًا من الروم، والمقَدَّم على الجميع البرواناه- الحاجب- وهو حاجب السلطان السلجوقي بأمر أبغا بن هولاكو ملك التتار، ومعهم جيش الموصل وجيش ماردين والأكراد، ونَصَبوا عليها ثلاثة وعشرين منجنيقًا، فخرج أهلُ البيرة في الليل فكبسوا عسكَرَ التتار وأحرقوا المنجنيقاتِ ونهبوا شيئًا كثيرًا، ورجعوا إلى بيوتهم سالمين، فأقام عليها الجيشُ مُدَّة إلى التاسِعَ عشر من هذا الشهر، ثم رجعوا عنها بغيظِهم لم ينالوا خيرا {وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا} [الأحزاب: 25]، ولما بلغ السلطانَ بيبرس نزولُ التتار على البيرة أنفَقَ في الجيش ستَّمائة ألف دينار، ثم ركب سريعًا وفي صحبته ولدُه الملك السعيد بركة، فلما كان في أثناء الطريق بلغه رحيلُ التتار عنها فعاد إلى دمشق، ثم ركب في رجب إلى القاهرة فدخلها في الثامن عشر."},{"id":2722,"title":"عسكر السلطان الظاهر بيبرس يقاتلون أهل النوبة .","date":["العام الهجري :674","الشهر القمري : شعبان","العام الميلادي :1276"],"text":"حضر ابنُ أخت ملك النوبة واسمه مشكد متظلمًا من داود ملك النوبة، فجَرَّد السلطانُ الظاهر بيبرس معه الأميرَ آقسنقر الفارقاني، ومعه من العسكَرِ وأجناد الولاة والعربان، والزرَّاقون والرُّماة والحراريقُ والزردخاناه-خزانة السلاح- فخرج مشكد في مستهل شعبان حتى تجاوز أسوان، وقاتل خالَه الملك داود ومن معه من السودان، فقاتلوه على النجب، وهَزَمَهم وأسر منهم كثيرًا، وبعث الأميرُ آقسنقر الأميرَ عزَّ الدين الأفرم، فأغار على قلعة الدقم، وقَتَل وسبى، ثم توجه الأمير سنقر في أثَرِه يقتل ويأسر حتى وصل إلى جزيرة ميكاليل وهي رأس جنادل النوبة، فقتل وأسر، وأقَرَّ الأميرُ آقسنقر قمر الدولة صاحب الجبل وبيده نصفُ بلاد النوبة على ما بيده، ثم واقَعَ الملك داود حتى أفنى معظَمَ رجاله قتلًا وأسرًا، وفر داود بنفسه في البحر وأُسِرَ أخوه شنكو، فساق العسكر خَلفَه ثلاثة أيام، والسيفُ يعمل فيمن هناك حتى دخلوا كلُّهم في الطاعة، وأُسِرَت أم الملك داود وأخته، وأقيم مشكد في المملكة، وأُلبِسَ التاج وأُجلِسَ في مكان داود، وقُرِّرَت عليه القطعة في كل سنة، وهي ثلاثة فيلة، وثلاث زرافات، وخمس فهود إناث، ومائة صهب جياد، ومائة من الأبقار الجياد منتخبة, وقرر أن تكون البلادُ مشاطرة، نصفُها للسلطان ونصفُها لعمارة البلاد وحفظِها، وأن تكون بلادُ العلى وبلاد الجبل للسلطان، وهي قدر ربع بلاد النوبة لقُربِها من أسوان، وأن يحمِلَ القُطن والتمر مع الحقوق الجاري بها العادةُ من القديم، وعرض عليهم الإسلامَ أو الجزية أو القَتلَ، فاختاروا الجزيةَ، وأن يقومَ كُلٌّ منهم بدينار عينًا في كلِّ سنةٍ، وعُمِلَت نسخة يمين بهذه الشروط، وحلف عليها مشكد وأكابِرُ النوبة، وعملت أيضًا نسخةٌ للرغبة بأنهم يطيعون نائِبَ السلطان ما دام طائعًا له، ويقومون بدينارٍ عن كلِّ بالغٍ، وخُرِّبَت كنيسة سرس، التي كان يزعم داود أنَّها تحدِّثُه بما يريده، وأخَذَ ما فيها من الصُّلبان الذَّهَب وغيرها، فجاءت مبلغ أربعة آلاف وستمائة وأربعين دينارًا ونصف، وبلغت الأواني الفِضَّة ثمانية آلاف وستمائة وستين دينارًا، وكان داودُ قد عَمَرَها على أكتاف المسلمين الذين أسَرَهم من عيذاب وأسوان، وقرر على أقارب داود حمل ما خلفه من رقيقٍ وقماشٍ إلى السلطان، وأُطلِقَت الأسرى الذين كانوا بالنوبة من أهل عيذاب وأسوان، ورُدُّوا إلى أوطانهم، ومن العسكرِ مِن الرقيق شيئًا كثيرًا، حتى بِيعَ كُلُّ رأس بثلاثة دراهم، وفضَل بعد القتل والبيع عشرة آلاف نفس، وأقام العسكر، بمدينة دنقلة سبعة عشر يومًا، وعادوا إلى القاهرة في خامس ذي الحجة بالأسرى والغنائم، فرسَمَ السلطان للصاحب بهاء الدين بن حنا أن يستخدم عمالًا على ما يستخرج من النوبة من الخَراجِ والجزية بدنقلة وأعمالا، فعمل لذلك ديوان."},{"id":2723,"title":"ثورة العامة على اليهود بمدينة فاس .","date":["العام الهجري :674","الشهر القمري : شوال","العام الميلادي :1276"],"text":"ثارت العامَّةُ في فاس على اليهود بسَبَبِ حدثٍ أحدثوه فقتلوا منهم أربعة عشر يهوديًّا، ولولا أنَّ السلطان يعقوب ركب بنَفسِه وردَّ العامة عنهم لقتلوهم جميعًا."},{"id":2724,"title":"وفاة أحمد البدوي الصوفي .","date":["العام الهجري :675","الشهر القمري : ربيع الأول","العام الميلادي :1276"],"text":"هو أبو العباس أحمد بن علي بن إبراهيم بن محمد بن أبي بكر المقدسىُّ الأصل، الحسيني البدوي، يلقَّب بالسطوحي، والسيد صاحب الشهرة في الديار المصرية، الذي يَستغيثُ به كُفرًا وعُدوانًا كثيرٌ مِن المتصوفة اليوم، ويعتقدون فيه من النفع والضر ممَّا لا يملكه إلا الله، يُعرف بأبي اللثَّامين لملازمته اللثامَ صيفًا وشتاء، أصله من المغرب حيث وُلِدَ بفاس، سنة 596 طاف البلاد وأقام بمكة والمدينة، ودخل مصرَ في أيام الظاهر بيبرس، سافر إلى دمشقَ والعراق، عظُمَ شأنُه جدًّا في مصر حتى عدُّوه صاحب طريقة، ولقِّبَ بالسطوحي لأنه مكث على السطوح اثني عشر عامًا، نُسِبَت له كرامات، توفي في طنطا وبني عليه مسجد وقبره يزار من قبل الجَهَلة والمتصَوِّفة إلى اليوم!!!"},{"id":2725,"title":"وقعة البلستين وفتح قيسارية .","date":["العام الهجري :675","الشهر القمري : ذي القعدة","العام الميلادي :1277"],"text":"في ثالث عشر المحرم دخل السلطان الظاهر بيبرس إلى دمشق، وسبق العساكر إلى بلاد حلب، فلما توافدت إليه أرسل بين يديه الأميرَ بدر الدين الأتابكي بألف فارس إلى البلستين بتركيا، فصادف بها جماعةً مِن عسكر الروم فرَكِبوا إليه وحَمَلوا إليه الإقاماتِ، وطلب جماعةٌ منهم أن يدخلوا بلادَ الإسلام فأذِنَ لهم، فدخل طائفةٌ منهم بيجار وابن الخطير، فرسم لهم أن يدخلوا القاهرةَ فتلقَّاهم الملك السعيد بركة بن السلطان بيبرس، ثم عاد السلطان من حَلَبَ إلى القاهرة، فدخلها في ثاني عشر ربيع الآخر، ثم ركِبَ السلطان من مِصرَ في العساكر فدخل دمشق في سابع عشر شوال، فأقام بها ثلاثةَ أيام، ثم سار حتى دخل حلب في مستهَلِّ ذي القعدة، فأقام بها يومًا ورسم لنائب حلب أن يقيم بعسكَرِ حَلَب على الفراتِ لحِفظِ المنائر، وسار السُّلطان الظاهر بيبرس فقطع الدربند في نصف يوم، ووقع سنقر الأشقر في أثناء الطريقِ بثلاثة آلاف من المغول فهزمهم يوم الخميسِ تاسع ذي القعدة وصَعِدَ العسكر على الجبالِ فأشرفوا على وطأة البلستين، فرأوا التتار قد رتَّبوا عسكرهم وكانوا أحدَ عَشَرَ ألف مقاتل، وعَزَلوا عنهم عسكَرَ الروم خوفًا من مخامرتهم، فلمَّا تراءى الجمعان حملت ميسرةُ التتار فصَدَمت رماح السلطان، ودخلت طائفةٌ منهم بينهم فشقُّوها، وساقت إلى الميمنة، فلما رأى السلطان ذلك أردف المسلمينَ بنفسه ومن معه، ثم لاحت منه التفاتةٌ فرأى الميسرة قد كادت أن تتحطَّمَ فأمر جماعةً من الأمراء بإردافها، ثم حمل العسكرُ جميعُه حملةً واحدة على التتار فترجَّلوا إلى الأرض عن آخرهم، وقاتلوا المسلمينَ قتالًا شديدًا، وصبر المسلمون صبرًا عظيمًا، فأنزل اللهُ نَصرَه على المسلمين، فأحاطت بالتتارِ العساكرُ مِن كل جانب، وقتلوا منهم خلقًا كثيرًا، وقتل من المسلمين أيضًا جماعةً، وأسر جماعةً من أمراء المغول، ومن أمراءِ الروم، وهرب حاجِبُ السلطان السلجوقي, فنجا بنفسه، ودخل قيسارية بفلسطين في بكرة الأحد ثاني عشر ذي القعدة، وأعلم أمراءُ الروم مَلِكَهم بكسرةِ التتار على البلستين، وأشار عليهم بالهزيمةِ فانهزموا منها وأخلوها، فدخلها الملكُ الظاهر وصلى بها الجمعةَ سابع ذي القعدة، وخُطِبَ له بها، ثم كرَّ راجعًا مؤيَّدًا منصورًا، وسارت البشائِرُ إلى البلدان ففرح المؤمنون يومئذ بنصر الله، ولما بلغ خبَرُ هذه الوقعة ملكَ التتار أبغا بن هولاكو جاء حتى وقف بنفسه وجيشِه، وشاهد مكان المعركة ومَن فيها من قتلى المغول، فغاظه ذلك وأعظَمَه وحنق على البرواناه؛ إذ لم يُعلِمه بجليَّة الحال، وكان يظنُّ أمر الملك الظاهر دون هذا كلِّه، واشتد غضَبُه على أهل قيسارية وأهلِ تلك الناحية، فقتَلَ منهم قريبًا من مائتي ألف، وقيل قتل منهم خمسمائة ألف من قيسارية وأرزن الروم، وكان في جملةِ مَن قُتِلَ القاضي جلال الدين حبيب، فإنَّا لله وإنا إليه راجعون."},{"id":2726,"title":"وفاة الأمير أبي عبد الله محمد بن الأمير أبي زكريا صاحب تونس. .","date":["العام الهجري :675","الشهر القمري : ذي الحجة","العام الميلادي :1277"],"text":"هو الأميرُ أبو عبد الله محمد بن يحيى بن عبد الواحد بن عمر الأمير المستنصر بن الأمير أبي زكرياء الهنتاتي البربري، الموحدي، ولي أبوه يحيى مدة ومات سنة 647 وهما بربريان من أتباع دولة الموحدين صاحبا تونس وأجل ملوكِ الغرب في زمانهما، كان جدُّه الشيخ الهنتاتي من العشرة خواص ابن تومرت، وكان محمد ملكًا مدبِّرًا شجاعًا، عاليَ الهمة، سائسًا، متحيلًا على بلوغ مقاصده، مقتحمًا للأخطار، كريمًا جوادًا، ذا غرام بالعمارات واللذات، تُزَفُّ إليه كلَّ ليلة جارية، وكان وليَّ عهد أبيه واتفق موت أبيه وهو غائبٌ عن تونس، يعني أبا عبد الله، فساق إليها على بغل في خمسة أيام ومات البغلُ وأسرع خوفًا مِن عَمَّيه، ثم لما تمكَّن قَتَلَ عمَّيه وأنفق في العرب الأموالَ واستخدمهم. أباد جماعة من الخوارج ظفر بجماعةٍ مِن أعيانهم وسجَنَهم، ثم أهلكَهم ببناء قبة عمل أساسها من ملحٍ وحبسهم بها، ثم أرسل الماء على أساسِها، فانردمت عليهم, وكانت أسلحةُ الجيش كلُّها في خزائنه، فإذا وقع أمرٌ أخرَجَها وفَرَّقَها عليهم وإذا فرغ من الحَربِ أعادها إلى الخزائن. ولم يكن لجنده إقطاع، بل يجمَعُ ارتفاع البلاد، فيأخذ لنفسِه الربعَ والثمُنَ ويُنفِقُ ما بقي فيهم في كلِّ عام أربع نفقات، توفي في أواخر هذه السنة وسَبَبُ موته أنه خرج إلى الصيد وحصل له من كثرةِ الحركة انزعاج وتغير مزاج، وزاد به الألم، فعاد إلى المدينة وهو ضعيف، فبقي على ذلك مدة أيام إلى أن توفي، وله من العمر اثنان وخمسون سنة."},{"id":2727,"title":"مقتل الشيخ خضر بن أبي بكر المهراني .","date":["العام الهجري :676","الشهر القمري : محرم","العام الميلادي :1277"],"text":"هو الشيخ خضر بن أبي بكر المهراني العدوي وهو شيخ السلطان الظاهر بيبرس، كان حظيًّا عنده مُكرَّمًا لديه، له عنده المكانة الرفيعة، كان السلطان ينزل بنَفسِه إلى زاويته التي بناها له في الحُسَينية، في كل أسبوع مرة أو مرتين، وبنى له عندها جامعًا يخطب فيه للجمعة، وكان يعطيه مالًا كثيرًا، ويطلق له ما أراد، ووقف على زاويته شيئًا كثيرًا جِدًّا، وكان معظَّمًا عند الخاص والعام بسبب حبِّ السلطان وتعظيمه له، وكان يمازِحُه إذا جلس عنده، وكان فيه دينٌ وصلاح. كان صاحب حالٍ ونفس قوية، وكان يتكهَّن كحالِ الكهان، وله مكاشفات يخبر بها الظاهِرُ؛ ولهذا كان السلطانُ يقَرِّبُه، أخبر الظاهر بسلطنَتِه قبل وقوعِها، فلهذا كان يعظِّمُه ويزوره ويُطلِعُه على غوامِضِ أسراره ويستصحِبُه في أسفاره، سأله وهو محاصِرٌ أرسوف: متى تؤخَذُ؟ فعين له اليومَ، فوافق ذلك، وكذلك صفد وقيسارية, ولما عاد إلى الكرك سنة خمس وستين استشاره في قَصدِها، فأشار عليه ألَّا يقصدها ويتوجه إلى مصر، فخالفه وتوجَّه فوقع عند بركة زيزا وانكَسَرَت فَخِذُه, وقال في بعلبك والظاهِرُ على حصن الأكراد: يأخذُه السلطان بعد أربعين يومًا، فوافق ذلك. وقد دخل الشيخ خضر مرة كنيسة القمامة بالمقدس فذَبَحَ قِسِّيسَها بيده، ووهب ما فيها لأصحابِه، وكذلك فعَلَ بالكنيسة التي بالإسكندرية وهي من أعظم كنائِسِهم، نهبها وحوَّلها مسجدًا ومدرسة أنفق عليها أموالًا كثيرةً مِن بيت المال، وسَّماها المدرسة الخضراء، وكذلك فعل بكنيسة اليهود بدمشق، دخلها ونهب ما فيها من الآلات والأمتعة، ومد فيها سماطًا، واتخذها مسجدًا مُدَّةً، ثم سعوا إليه في رَدِّها إليهم وإبقائها عليهم، ثم اتفق في هذه السنة أنه وقعت منه أشياءُ أُنكِرَت عليه وحُوقِقَ عليها عند السلطان الظاهر، فظهر له منه ما أوجب سجنه، كاللُّواط والزِّنا وغيره، وقيل مخالطته لبنات الأمراءِ حتى أصبَحْنَ لا يستَتِرْنَ منه فافتتَنَ بهن ووقع منه القبائِحُ، فأمر السلطان بإعدامِه، فقال له إن بيني وبينك أيامًا قلائل، فسجنه من عام 671هـ إلى هذا العام، فأمر بقَتلِه، وكانت وفاته في هذه السنة، ودُفِنَ بزاويته سامحه الله، وقد كان السلطانُ يحبُّه محبة عظيمة حتى إنه سمى بعض أولاده خضرًا موافقة لاسمه، وإليه تُنسَبُ القبة التي على الجبل غربي الربوة التي يقال لها قبة الشيخ خضر."},{"id":2728,"title":"وفاة السلطان الظاهر بيبرس البندقداري  وتولي ابنه السعيد بركة .","date":["العام الهجري :676","الشهر القمري : محرم","العام الميلادي :1277"],"text":"هو السلطان الأعظم الملك الظاهر ركن الدين بيبرس بن عبد الله، البندقداري  الصالحي؛ يُعد المؤسِّسَ الفعلي لدولة المماليك وأعظَمَ سلاطينها، اجتمعت فيه صفاتُ العدل والفروسية والإقدام. ولِدَ بيبرس- بيبرس كلمة تركية تعني أمير فهد- بأرض القبجاق سنة 625، تعرضت ديارهم في القبجاق لغارات فأُسِرَ جماعة منهم، وكان بيبرس فيمن أُسِرَ وحُمِلَ إلى القاهرة، فاشتراه الأميرُ علاء الدين البندقدار الصالحي فطلع بطلًا شجاعًا نجيبًا لا ينبغي أن يكونَ إلَّا عند ملك. فأخذه الملِكُ الصالح إليه وصار من جملةِ البحرية. وشَهِدَ وقعة المنصورة بدمياط وصار أميرًا في دولة المعز عز الدين أيبك. وتقلبت به الأمور وجرت له أحوال, واشتهر بالشجاعةِ والإقدام وبَعُدَ صِيتُه. ولما سارت الجيوشُ المنصورة من مصر لحرب التتار في عين جالوت كان هو طليعةَ الإسلام. وجلس على سريرِ المُلكِ بعد قتل الملكِ المظفَّر وذلك في سابع عشر ذي القعدة من سنة ثمان وخمسين بقلعة الجبل, فصار أستاذُه البندقدار بعض أمرائه وكان الظاهر غازيا، مجاهدا، مرابطا، خليقا للملك، لولا ما كان فيه من الظلم والله يرحمه ويغفر له ويسامحه، فإن له أياما بيضاء في الإسلام ومواقف مشهودة وفتوحات معدودة. وله سيرتان كبيرتان لابن عبد الظاهر ولابن شداد. كانت وفاته يوم الخميس السابِعَ عشَرَ من محرم بعد الزوال، وقد تجاوز الخمسين سنة، ومُدَّة ملكه سبعَ عشرة سنة وشهران واثنا عشر يومًا، أما عن سبب موته فقيل إنه شرب القمز، وهو نوعٌ من النبيذ فمَرِضَ بعده أيامًا ثم إنَّه أخذ دواءً فزاد مرضُه وأصيبَ بإسهالٍ حادٍّ وحاول الأطباءُ علاجه بدواء آخر فأفرط الإسهال حتى إنه رمى دمًا قيل إنه كَبِدُه، ثم لم يلبث أيامًا حتى توفي، وقيل بل إن وفاته كانت بالسُّمِّ حيث إنه وُضِعَ السم في القمز للملك القاهر بهاء الدين عبد الملك بن الملك المعظم عيسى بن العادل أبي بكر بن أيوب، الذي أبلى بلاءً عظيمًا ضد المغول وكان بيبرس قد قيل له إنه يموت في دمشق مَلِكٌ بالسمِّ في هذا العام فأراد أن يكون هذا الملك هو القاهر بهاء، وخاصة أنه خاف منه لما ظهر منه أمام المغول فوضع له السمُّ فشربه القاهر ومات من فَورِه ولكِنَّ الله أنسى بيبرس أمر الكأسِ وسقاه خادِمُه من نفس الكأس ثانيةً، فكانت بقايا السم هي سبب حتفه، فالله أعلم كيف كانت وفاته، ودفن في دمشق قريبًا من المكتبة الظاهرية، فجزاه الله خيرًا على ما قام به من فتح كثير من البلاد التي كانت استعصت على من قَبلَه، وعلى العمران الذي شيَّدَه وعلى الهيبةِ التي ردها للمُسلمينَ بعد أن كانت تحطَّمَت أمام أفعال المغول، وبالجملة أقامه الله في هذا الوقت المتأخر عونًا ونصرًا للإسلام وأهله، وشجًا في حلوق المارقين من الفرنج والتتار، والمشركين، وكان الملك الظاهر بيبرس قد عَهِدَ بالملك لابنه الملك السعيد بركة الذي أصبح ملكًا بعد أن أخفي موت الظاهر بيبرس أيامًا حتى استحلف الأمراء مرة أخرى على بيعته، ثم أعلنت وفاة الظاهر وبويع الملكُ السعيدُ بالمُلكِ بعده."},{"id":2729,"title":"ما فعله الملك السعيد بأمراء المماليك بعد أن استلم الملك .","date":["العام الهجري :676","الشهر القمري : ربيع الآخر","العام الميلادي :1277"],"text":"في سادس ربيع الآخر مات الأمير بدر الدين بيليك النائب، واتهم أن المَلِكَ السعيد سَمَّه؛ وذلك أنه اختصَّ بجماعة من المماليك الأحداث، ومن بعده اضطربت أمورُ الملك السعيد، وأقام الملك السعيد بعده في نيابةِ السلطنة الأمير شمس الدين آقنسنقر الفارقاني، وكان حازمًا، فضم إليه جماعة منهم شمس الدين أقوش، وقطليجا الرومي، وسيف الدين قلج البغدادي، وسيف الدين بيجو البغدادي، وعز الدين ميغان أمير شكار، وسيف الدين بكتمر السلاح دار, فثقَّل الأمير آقسنقر على خاصكية السلطان، فحدثوا السلطانَ في أمره، واستعانوا بالأمير سيف الدين كوندك الساقي، وكان الملك السعيد قد قَدَّمَه وعظَّمَه لأنه ربِّيَ معه في المكتب، فقبض على آقسنقر الفارقاني وهو جالسٌ في باب القلة، وسُجِنَ وأهين ونُتِفَت لحيته وضُرِب، ثم أُخرج بعد أيام يسيرة ميتًا، فاستقر بعده في النيابة الأمير شمس الدين سنقر الألفي المظفري، فكرهه الخاصكية وقالوا، هذا ما هو من الظاهريَّة وخيلوا الملك السعيد منه أنه يريد أن يثور بخشداشيته- زملاء مهنته- مماليك الملك المظفر قطز، فعزله سريعًا، وولى الأمير سيف الدين كوندك الساقي نيابة السلطة وهو شابٌّ، فعضده الأمير سيف الدين قلاوون الألفي ومال إليه، وكان من جملة المماليك السلطانية الخاصكية شخصٌ يعرف بلاجين الزيني، وقد غلب على الملك السعيد في سائر أحوالِه، وضم إليه عدة من الخاصكية، وأخذ لاجين لهم الإقطاعات والأموال الجزيلة، وتنافر كوندك النائب ولاجين، فتوغرت بينهما الصدور، وأعمل كل منهما مكرهَ في أذية الآخر، وضم النائبُ إليه جماعة من الأمراء الكبار، وصار العسكرُ حزبين، فآل الأمرُ إلى ما آل إليه من الفساد، وتغير السلطانُ على الأمراء، وقبض في السابع عشر على الأمير جودي القيمري الكردي فنفرت منه قلوبُ الأمراء لا سيما الصالحيَّة: مثل الأمير سيف الدين قلاوون، والأمير شمس الدين سنقر الأشقر، والأمير علم الدين سنجر الحلبي، والأمير بدر الدين، بيسري، وأقرانهم فإنهم كانوا يأنفون من تمَلُّك الملك الظاهر عليهم، ويرون أنهم أحقُّ منه بالملك، فصار ابنه الملك السعيد يضَعُ من أقدارهم، ويقَدِّمُ عليهم مماليك أصاغر، ويخلو بهم وكانوا صِباحَ الوجوه، ويعطهيم مع ذلك الأموال الكثيرة، ويسمَعُ من رأيهم ويُبعِدُ الأمراءَ الكبار، واستمر الحالُ على هذا إلى أن كان يوم الجمعة الخامس عشر، فقبض السلطان على الأمير شمس الدين سنقر الأشقر، والأمير بدر الدين بيسري، وسجنهما بالقلعة ثلاثة وعشرين يومًا، فزادت الوحشة بينه وبين الأمراء، ودخل خالُه الأمير بدر الدين محمد بركة خان إلى أختِه أم السلطان، وقال لها: قد أساء ابنك التدبير بقبضه على مثل هؤلاء الأمراء الأكابر، والمصلحةُ أن تردِّيه إلى الصواب، لئلا يَفسُد نظامُه وتَقصُر أيامه، فلما بلغ الملك السعيد ذلك قبض عليه واعتقله، فلم تزل به أمه تعنِّفُه وتتلطف به، حتى أطلقهم وخلع عليهم وأعادَهم إلى ما كانوا عليه، وقد تمسَّكَت عداوته من قلوبهم، وتوهَّم منه بقية الأمراء، وخَشُوا أن يعامِلَهم كما عامل الأميرَ بيليك الخازندار- ممسك خزنة المال- مع حفظه له المُلك وتسليم الخزائن والعساكر إليه، فلم يكافئْه إلا بأن قتله بالسمِّ، فاجتمع الأمراء وهموا أن يَخرُجوا عنه إلى بلاد الشام، ثم اتفقوا وصعدوا إلى قلعة الجبل، ومعهم مماليكُهم وألزامهم وأجنادُهم وأتباعهم، ومن انضَمَّ إليهم من العساكر، فامتلأ منهم الإيوانُ ورحبة القصر، وبعثوا إلى الملك السعيد: بأنَّك قد أفسدت الخواطِرَ، وتعرضتَ إلى أكابر الأمراء، فإما أن ترجِعَ عما أنت عليه، وإلا كان لنا ولك شأن، فلاطفهم في الجوابِ وتنَصَّلَ مما كان منه، وبعث إليهم التشاريفَ فلم يلبسوها، وترددت الأجوبةُ بينهم وبينه إلى أن تقرَّر الصلحُ، وحلف لهم إنَّه لا يريد بهم سوءًا، وتولى تحليفَه الأمير بدر الدين الأيدمري فَرَضُوا وانصَرَفوا."},{"id":2730,"title":"وفاة الإمام محيي الدين النووي .","date":["العام الهجري :676","الشهر القمري : رجب","العام الميلادي :1277"],"text":"هو الإمام أبو زكريا محيي الدين يحيى بن شرف بن حسن بن حسين بن جمعة النووي، الشافعي نسبة إلى نوى قرية من قرى حوران بسوريا، وُلِدَ بنوى في العشر الأوسط من المحرم سنة 631. رحل أبو زكريا إلى دمشق ودرس فيها وسَمِعَ الحديث مع زهد وورع وأمر بالمعروف ونهي عن المنكر، قال الشيخ محيي الدين: \"لما كان لي تسع عشرة سنة قدم بي والدي إلى دمشق في سنة تسع وأربعين، فسكنت المدرسة الرواحية، وبقيت نحو سنتين لم أضع جنبي إلى الأرض. وكان قوتي فيها جرايةَ المدرسة لا غير، وحفظت التنبيهَ في نحو أربعة أشهر ونصف, وبقيت أكثَرَ من شهرين أو أقل لما قرأت: يجب الغُسلُ من إيلاج الحشفة في الفرج، أعتقد أن ذلك قرقرة البطنِ، وكنت أستحمَّ بالماء البارد كلما قرقَرَ بطني. وقرأت حفظًا ربع المهذب في باقي السنة، وجعلت أشرحُ وأصحِّحُ على شيخنا كمال الدين إسحاق بن أحمد المغربي، ولازمته فأُعجِبَ بي وأحبني، وجعلني أعيد لأكثر جماعته, وكنت أقرأُ كل يوم اثني عشر درسًا على المشايخ شرحًا وتصحيحًا وكنت أعلِّقُ جميع ما يتعلق بها من شرح مُشكِل، ووضوحِ عبارة، وضَبطِ لغة، وبارك الله لي في وقتي, وخطَرَ لي الاشتغالُ بعلم الطب، فاشتريتُ كتاب القانون فيه، وعزمتُ على الاشتغال فيه، فأظلم عليَّ قلبي، وبقيت أيامًا لا أقدر على الاشتغالِ بشيءٍ، ففكَّرتُ في أمري ومن أين دخل عليَّ الداخل، فألهمني الله أنَّ سَبَبَه اشتغالي بالطب، فبِعتُ القانون في الحال، واستنار قلبي.\" وليَ أبو زكريا مشيخة دار الحديث من غيرِ أجر، وله مصنفات عديدة مفيدة أشهرها كتاب: رياض الصالحين، والأربعون النووية، وشرحه لصحيح مسلم المنهاج في شرح صحيح مسلم بن الحجاج، ومنهاج الطالبين في الفقه الشافعي الذي يعتبر عمدة في المذهب، ويعتبر النووي من المعُتمَدين في المذهب؛ فكلامه أصل في المذهبِ، وهو أحد الشيخين الذين يعتمد على ترجيحهم في المذهب والآخر هو الرافعي، وله كتاب المجموع شرح المهذب أيضًا في الفقه الشافعي لكنه لم يتِمَّه، وله كتاب التقريب والتيسير في مصطلح الحديث. قال ابن العطار: \"ذكر لي شيخنا محيي الدين رحمه الله أنه كان لا يضيِّعُ له وقتًا في ليل ولا نهار إلا في وظيفة من الاشتغال بالعلم، حتى في ذهابه في الطرق يكرِّرُ أو يطالع. وأنه بقي على هذا نحو ست سنين، ثم اشتغل بالتصنيفِ والإشغال والنصح للمسلمين وولاتهم، مع ما هو عليه من المجاهدة لنفسه، والعمل بدقائق الفقه، والحرص على الخروجِ مِن خلاف العلماء، والمراقبة لأعمال القلوب وتصفيتها من الشوائب، يحاسِبُ نفسَه على الخطرة بعد الخطرة. وكان محقِّقًا في علمه وفنونه، مدققًا في عمله وشؤونه، حافظًا لحديث رسول الله صلى الله عليه وسلم، عارفًا بأنواعه من صحيحه وسقيمه وغريب ألفاظه واستنباط فقهه، حافظًا للمذهب وقواعده وأصوله، وأقوالِ الصحابة والتابعين، واختلاف العلماء ووفاقهم؛ سالكًا في ذلك طريقة السلف. قد صرف أوقاتَه كلَّها في أنواع العلم والعمل بالعلم\". توفي في ليلة أربع وعشرين من رجب في نوى عن خمس وأربعين عامًا، ودفن هناك وقبره فيها معروف رحمه الله وجزاه خيرًا."},{"id":2731,"title":"ملك غرناطة يسترد مالقة .","date":["العام الهجري :677","العام الميلادي :1278"],"text":"استولى ملك غرناطة الفقيه محمد الثاني بن الأحمر على مالقة وضمها إلى مملكته، وكان المنصورُ يعقوب ملك بني مرين يطمع فيها فساءت بذلك العلاقةُ بينه وبين ملك غرناطة، فعَزَم على قتلِه."},{"id":2732,"title":"خلاف يدب في سائر الطوائف .","date":["العام الهجري :678","العام الميلادي :1279"],"text":"اتَّفَق في هذه السنة أمورٌ عجيبة، وذلك أنَّه وقع الخُلفُ بين الممالك كلِّها؛ اختلفت التتارُ فيما بينهم واقتتلوا فقُتِلَ منهم خلق كثير، واختلفت الفرنجُ في السواحِلِ وصال بعضهم على بعض وقتل بعضُهم بعضًا، وكذلك الفرنجُ الذين في داخل البحور وجزائرها، فاختلفوا واقتتلوا، وقَتَلت قبائلُ الأعراب بعضُها في بعض قتالًا شديدًا، وكذلك وقع الخلف بين العشير من الحوارنة وقامت الحرب بينهم على ساق، وكذلك وقع الخلفُ بين الأمراء الظاهرية بسبب أن السلطان الملك السعيد بن الظاهر لَمَّا بعث الجيش إلى سيس أقام بعده بدمشقَ وأخذ في اللَّهوِ واللعب والانبساط مع الخاصكية، وتمكَّنوا من الأمور، وبعد عنه الأمراء الكِبار، فغضبت طائفةٌ منهم ونابذوه وفارَقوه."},{"id":2733,"title":"بنو مرين يغزون غرناطة .","date":["العام الهجري :678","العام الميلادي :1279"],"text":"لما ساءت العلاقة بين بني مرين وملك غرناطة بسبب استيلاء ابن الأحمر على مالقة، وجَّه المنصور أبو يوسف ملك بني مرين في هذه السنة جيشًا بقيادة ابنه الأمير أبي يعقوب لقتال بني الأحمر واستعان بملك قشتالة فاستولى على ماربللا وهي من أملاك غرناطة، ثم زحف إلى غرناطة، ولكن ابن الأحمر ردَّه عنها، ثم إن ابن الأحمر صالح المنصور سلطان بني مرين على أن يتنازلَ له عن مالقة لتكون قاعدةَ عبور لبني مرين إلى الأندلس."},{"id":2734,"title":"خلع الملك السعيد وتولية أخيه سلامش بن الظاهر بيبرس .","date":["العام الهجري :678","الشهر القمري : ربيع الآخر","العام الميلادي :1279"],"text":"كان قد حدث من الملك السعيد أشياء أوغرت صدورَ الأمراء عليه، وأصبَحَ خاصية الملك يحظَونَ بما يريدون ويُبعِدونَ من أرادوا حتى كان في السنة الماضيةِ أن أرسل بعض الأمراء إلى سيس للقتال فخرجوا وهم مكرهون، فأما الأمراء فإنهم غَزَوا سيس وقتلوا وسَبَوا، ثم عادوا إلى دمشق ونزلوا بالمرجِ، فخرج الأميرُ كوندك إلى لقائهم على العادة، وأخبرهم مما وقع من الخاصكية في حَقِّهم وحَقِّه من تخوُّفِ الملك منهم، فحَرَّك قَولُه ما عندهم من كوامِنِ الغضب، وتحالفوا على الاتفاق والتعاون، وبعثوا من المرج إلى السلطانِ يُعلِمونَه أنهم مقيمون بالمرج، وأن الأمير كوندك شكى إليهم من لاجين الزيني وهو من أقرَبِ مقربي الملك السعيد شكاوى كثيرة، ولا بد لنا من الكشفِ عنها، وسألوا السلطانَ أن يحضر إليهم حتى يسمعوا كلامَه وكلام كوندك، فلما بلغ السلطانَ ذلك لم يعبأ بقولهم، وكتب إلى من معهم من الأمراءِ الظاهريَّة يأمُرُهم بمفارقة الصالحيَّة ودخول دمشق، فرحلوا مِن فَورِهم ونزلوا على الجورةِ مِن جهة داريا، وأظهروا الخلافَ، ورموا الملكَ السعيد بأنه قد أسرف وأفرطَ في سوء الرأي وأفسد التدبير، فخاف السلطان عند ذلك سوء العاقبة، وبعث إليهم الأميرَ سنقر الأشقر، والأمير سنقر التكريتي الأستادار- المشرف على شؤون بيوت السلطان-  ليلطفا بهم ويعملا الحيلة في إحضارِهم، فلم يوافقوا على ذلك، وعادا إلى السلطان فزاد قلقُه، وتردَّدَت الرسل بينه وبين الأمراء، فاقترحوا عليه إبعادَ الخاصكية، فلم يوافق، فرحل الأمراءُ بمن معهم من العساكِرِ إلى مصر وتَبِعَهم الملك السعيد ليلحَقَهم ويتلافى أمرَهم فلم يُدرِكْهم فعاد إلى دمشق وبات بها، ثم سار من دمشق بالعساكر يريد مصرَ فنزل بلبيس في نصف ربيع الأول وكان قد سبقه الأميرُ قلاوون بمن معه إلى القاهرة، ونزلوا تحت الجبل الأحمر، فبلغ ذلك الأمراء الذين بقلعة الجبل، وهم الأمير عز الدين أيبك أمير جانذار والأمير أفطوان الساقي، والأمير بلبان الزربقي، فامتنعوا بها وحَصَّنوها وتقدموا إلى متولي القاهرة فسَدَّ أبوابها فراسَلَهم قلاوون والأمراء في فتحِ أبواب القاهرة ليدخُلَ العسكر إلى بيوتهم ويُبصِروا أولادَهم؛ فإن عهدهم بَعُدَ بهم ونزل الأمير لاجين البركخاي وأيبك الأفرم وأقطون إلى الأمراء لمعرفة الخبر فقَبَضوا عليهم وبعثوا إلى القاهرة ففُتِحَت أبوابها ودخل كلُّ أحد إلى داره وسُجِنَ الثلاثة الأمراء في دار الأمير قلاوون بالقاهرة وزحفوا إلى القلعةِ وحاصروها وأمَّا السلطان فإنه لما نزل بلبيس وبلغه خبَرُ الأمراء خامر عليه من كان معه من عسكَرِ الشام وتركوه في بلبيس وعادوا إلى دمشق وبها الأمير عز الدين أيدمر نائب الشام، فصاروا إليه ولم يبقَ مع السلطان إلا مماليكُه ولم يبق معه من الأمراء الكبار إلا الأميرُ سنقر الأشقر فقط، فسار السلطان من بلبيس ففارقه الأشقر من المطرية وأقام بموضعه، وبلغ الأمراءَ أن السلطان جاء من خَلفِ الجبل الأحمر فركبوا ليحولوا بينه وبين القلعة وكان الضباب كثيرًا فنجا منهم واستتر عن رؤيتِهم وطلع إلى المقَدِّمة، فلما انكشف الضباب بلغ الأمراء أن السلطانَ بالقلعة فعادوا إلى حصارِها وصار السلطان يُشرِفُ من برج الرفرف المطلِّ على الإسطبل ويصيح بهم: يا أمراءُ، أرجِعُ إلى رأيكم ولا أعمَلُ إلا ما تقولونَه، فلم يجبه أحدٌ منهم وأظهروا كتبًا عنه يطلب فيها جماعةً من الفداوية لقَتلِهم وأحاطوا بالقلعة وحصروه، وكان الأميرُ سنجر الحلبي معتَقلًا بالقلعة، فأخرجه السلطانُ وصار معه، فاستمر الحصارُ مدة أسبوع، وكان الذي قام في خلع السلطان جماعةٌ كثيرة من الأمراء وأعيان المفاردة والبحرية، ولما طال الحصار بعث الخليفةُ العباسي الحاكم بأمر الله أحمد، يقول: يا أمراءُ، أيش غرضكم؟ فقالوا: يخلع المَلِكُ السعيد نفسه من الملك ونعطيه الكرك، فأذعن السعيدُ لذلك، وحلف له الأمراء، وحضر الخليفةُ والقضاة والأعيان، وأنزل بالملك السعيد، وأشهد عليه أنَّه لا يَصلُحُ للمُلك، وخلعَ السعيدُ نفسَه، وحلف أنه لا يتطَرَّقُ إلى غير الكرك، ولا يكاتِبُ أحدًا من النواب، ولا يستميلُ أحد من الجند، وسافر من وقته إلى الكرك مع الأمير بيدغان الركني، وذلك في سابع شهر ربيع الآخر، فكانت مدة ملكه من حين وفاة أبيه إلى يوم خلعه سنتين وشهرين وثمانية أيام، فوصل إلى الكرك وتسَلَّمَها في الخامس عشر من جمادى الآخرة، واحتوى على ما فيها من الأموال وكانت شيئًا كثيرًا، ولما تم خلعُ الملك السعيد وسافر إلى الكرك، عرض الأمراءُ السلطنة على الأمير سيف الدين قلاوون الألفي فامتنع، وقال: أنا ما خلعت الملك السعيد طمعًا في السلطنة، والأولى ألا يخرجَ الأمر عن ذرية الملك الظاهر، فاستُحسِنَ ذلك منه؛ لأن الفتنة سكنت فإنَّ الظاهرية كانوا معظم العسكرِ، وكانت القلاعُ بيَدِ نواب الملك السعيد، وقصَدَ قلاوون بهذا القَولِ أن يتحَكَّم حتى يغَيِّرَ النواب ويتمكن مما يريد، فمال الجميعُ إلى قوله وصوبوا رأيه، واستدعوا سلامش بن السلطان الظاهر، واتفقوا أن يكون الأمير قلاوون أتابِكَه، وأن يكون إليه أمرُ العساكر وتدبير الممالك، فحضر سلامش وله من العمر سبع سنين وأشهر، وحلف العسكرُ جميعه على إقامته سلطانًا، وإقامة الأمير قلاوون أتابك العساكر، ولقَّبوه الملك العادل بدر الدين، فاستقَرَّ الأمرُ على ذلك، وأقيم الأمير عز الدين أيبك الأفرم في نيابة السلطنة."},{"id":2735,"title":"عزل العادل سلامش وتنصيب السلطان قلاوون الألفي .","date":["العام الهجري :678","الشهر القمري : رجب","العام الميلادي :1279"],"text":"بعد أن تمَّ تنصيبُ العادل سلامش في الملك لم يكنْ له من الأمر شيءٌ، بل كل شيء من حَلٍّ وعَقدٍ بيد قلاوون الألفي فشرع الأمير قلاوون في القبض على الأمراء الظاهريَّة، فقبض على أعيانِهم وبعث بهم إلى الثغور فسُجِنوا بها، وأمسك أيضًا كثيرًا من الظاهريَّة وملأ الحبوسَ بهم، وأعطى قلاوونُ ومنع وقطع، ووصل واستخدم وعزل، فكان صورتُه أتابك وتصَرُّفُه تصرُّفَ الملوك، وانفرد قلاوون بالمملكة وأجَدَّ في تدبر أحواله وفَرَّق على المماليك واستمالهم، وقرَّبَ الصالحية وأعطاهم الإقطاعات، وسَيَّرَ عدة منهم إلى البلاد الشاميَّة واستنابهم في القلاع، وتتَبَّع ذراريَّهم وأخذ كثيرًا منهم كانوا قد تصَنَّفوا بالصنائع والحرف، فرتَّبَ طائفة منهم في البحرية، وقررَ لجماعة منهم جامكية –رواتب- وقوِيَ بهم جانبه وتمكَّنَت أسبابه، ثم جمع قلاوون الأمراء في العشرين من رجب وتحَدَّث معهم في صغر سن الملك العادِلِ، وقال لهم: قد علمتُم أن المملكة لا تقومُ إلا برجلٍ كامل، إلى أن اتفقوا على خلع سلامش فخلعوه، وبعَثوا به إلى الكرك وكانت مُدَّة مُلكِه مائة يوم، ولم يكن حَظُّه من المُلك سوى الاسم فقط، وجميعُ الأمور إلى الأتابك قلاوون، وقع الاتفاق على خلع العادل وإقامة قلاوون، فأُجلِسَ قلاوون على تخت المُلك في يوم الأحد العشرين من رجب، وحلَفَ له الأمراءُ وأرباب الدولة، وتلَقَّب بالملك المنصور، وأمر أن يُكتَبَ في صدر المناشير والتواقيع والمكاتبات لفظُ الصالحي، فكُتِبَ بذلك في كل ما يكتب عن السلطان، وجعل عن يمين البسملة تحتها بشيء لطيف جدًّا، وخرج البريد بالبشائر إلى الأعمال، وجُهِّزَت نسخة اليمين إلى دمشق وغيرها، وزُيِّنَت القاهرة ومصر وظواهِرُهما وقلعة الجبل، وأقيمت له الخطبةُ بأعمال مصر، ويُذكَرُ أن قلاوون هذا هو السابع من ملوك الترك بالديار المصريَّة، والرابع ممن مَسَّه الرِّقُّ."},{"id":2736,"title":"وفاة الملك السعيد محمد بركة خان بن الملك الظاهر صاحب الكرك .","date":["العام الهجري :678","الشهر القمري : ذي القعدة","العام الميلادي :1280"],"text":"هو السُّلطان الملك السعيد، ناصر الدين، أبو المعالي محمد بركة خان بن السلطان الملك الظاهر بيبرس وُلِدَ سنة 658 في صفر بالعش من ضواحي القاهرة، وسلطنه أبوه وهو ابن خمس سنين أو نحوها. وبويع بالملك بعد والده وهو ابن ثمان عشرة سنة. وكان شابًّا مليحًا كريمًا، فيه عَدلٌ ولين وإحسان إلى الرعيَّة، ليس في طبعه ظلمٌ ولا عسف، بل يحب الخير وفعله. وكان محببا إلى الرعية، لكنه شاب غِرٌّ لم يحمِلْ أعباء الملك، وعجز عن ضبط الأمورِ فتعصَّبَ أمراء المماليك لذلك وخلعوه من السلطنة، وعملوا محضرًا بذلك، وأطلقوا له سلطنة الكرك فسار إليها بأهله ومماليكه، فلما استقر بها قَصَده جماعةٌ من الناس، فكان يُنعِمُ عليهم ويصلهم، فكثروا عليه بحيث نَفِدَ كثير من حواصِلِه، وبلغ ذلك السلطان الملك المنصور قلاوون الألفي فتأثر منه، مات الملك السعيد بركة خان بالكرك في الحادي عشر من ذي القعدة، وكان قد ركبَ في الميدان فتقنطر عن فَرَسِه وهو يلعب بالكرة، فصدع وحُمَّ أيامًا، ومات وعمره نيف وعشرون سنة، وقيل إنه مات مسمومًا، وورد الخبر بوفاته إلى مصر في العشرين منه، فعمل له السلطان قلاوون عزاءً بالإيوان من قلعة الجبل، وجلس كئيبًا ببياضٍ، وقد حضر العلماء والقضاة والأمراء والوعاظ والأعيان، فكان يومًا مشهودًا، وأقام القراءُ شهرًا يقرؤون القرآن، وكتب إلى أعمال مصر والشام بأن يصلَّى عليه صلاة الغائب، ودُفِنَ عند جعفر الطيار، ثمَّ نقل إلى تربته بدمشق بعد سنة وخمسة أشهر، ودفن عند والده. ووجدت عليه امرأتُه بنت الملك المنصور سيف الدين وجدًا شديدًا، ولم تزل باكية حزينة إلى أن ماتت بعده بمدة. وعندما مات الملك السعيد أقام الأمير ُعلاء الدين أيدغدي الحراني نائب الكرك نجمَ الدين خضر بن الظاهر ملكًا مكان أخيه بالكرك، ولقَّبه الملك المسعود فتحَكَّم عليه مماليكه وأساؤوا التدبير، وفَرَّقوا الأموال ليستجلبوا الناسَ، وحضر إليهم طائفةٌ من البطَّالين فساروا إلى الصلت واستولوا عليها، وبعثوا إلى صرخد فلم يتمَكَّنوا منها، وأتَتْهم العربان وتقربوا إليهم بالنصيحة، وأخذوا مالًا كثيرا من المسعود ثم تسلَّلوا عنه، ولم يزل المسعود في إنفاق المالِ حتى فنيت ذخائر الكرك التي كان المَلك الظاهر قد أعدَّها لوقت الشدة، وبعث المسعودُ إلى الأمير سنقر الأشقر نائب دمشق يستدعيه، فجرد السلطان قلاوون الأمير عز الدين أيبك الأفرم إلى الكرك."},{"id":2737,"title":"غزو الفرنج لمعاونتهم التتار .","date":["العام الهجري :679","العام الميلادي :1280"],"text":"خرج الأميرُ بدر الدين بكتاش النجمي إلى حمص مجردًا، وخرج الأمير علاء الدين أيدكين البندقداري  الصالحي لحفظ الساحل من الفرنج، وكتب السلطان قلاوون إلى الأمير سيف الدين بلبان الطباخي نائب حصن الأكراد بغزو الفرنج بالمرقب؛ لمساعدتهم التتارَ عند وصولهم حلب، فجمَعَ التركمان وغيرَهم، وحمل المجانيق والآلات، ونازل المرقَبَ، فانهزم المسلمون ونهَبَهم الفرنج، وعَدِمَ من المسلمين مقدارُ مائتي فارس وراجل، فكبُرَ ذلك على السلطان، وتحرك للسَّفَرَ وخرج في أول ذي الحجة، واستخلف ابنَه الملك الصالح، وخيم بمسجدِ تبر."},{"id":2738,"title":"الأمير شمس الدين سنقر الأشقر يستولي على دمشق .","date":["العام الهجري :679","الشهر القمري : محرم","العام الميلادي :1280"],"text":"لما كان يوم الجمعة الرابع والعشرين من ذي القعدة سنة 678هـ ركب الأمير شمس الدين سنقر الأشقر من دار السعادة بعد صلاة العصر وبين يديه جماعة من الأمراء والجند مشاة، وقصد باب القلعةِ الذي يلي مدينة دمشق، فهجم منه ودخل القلعة واستدعى الأمراء فبايعوه على السلطنة، ولُقِّبَ بالملك الكامل، وأقام بالقلعة ونادت المنادية بدمشق بذلك، فلما أصبح يومَ السبت استدعى بالقضاة والعلماء والأعيان ورؤساء البلد إلى مسجد أبي الدرداء بالقلعة، وحَلَّفهم وحلف له بقية الأمراء والعسكر، وأرسل العساكر إلى غزة لحفظ الأطراف وأخذ الغلات، وفي يوم الخميس أول المحرم من هذه السنة ركب الملك الكامِلُ سنقر الأشقر بشعار السلطنة من قلعة دمشق إلى الميدان الأخضر، وبين يديه الأمراء مشاة بالخِلَع، ثم عاد، وفي يوم الجمعة ثانيه: خطب له على منبر الجامع بدمشق."},{"id":2739,"title":"قتال عسكر مصر لسنقر الأشقر بعد استيلائه على دمشق .","date":["العام الهجري :679","الشهر القمري : صفر","العام الميلادي :1280"],"text":"لما أعلن سنقر الأشقر نفسَه سلطانًا في دمشق كتب إلى الأمير عز الدين الأفرم وهو بالكرك يعتذر عن قيامِه بما كَلَّف به السلطان في الكرك، وأتبع الكتابَ بعسكر، فلما ورد كتابه جهزه الأفرم إلى السلطان قلاوون بمصر، فكتب السلطانُ عند وروده إلى الأشقر يقَبِّحُ فعله، وكتب أمراءُ مصر إليه بذلك، ويحثُّونه على الإذعان وترك الفتنة، وسار بالكتُبِ بلبان الكريمي، فوصل دمشقَ في ثامنه، وخرج سنقر الأشقر إلى لقائه وأكرمه، ولم يرجِعْ عما هو فيه، واستقر الأفرم بغزة، فوافاه عسكَرُ سنقر الأشقر بها، فاندفع من قُدَّامِهم إلى الرمل، وملك عسكر سنقر غزة واطمأنوا، فطرَقَهم الأفرم وأوقع بهم فانهزموا إلى الرملة، وأسَرَ من الأمراء عدة وغنم منهم مالًا وخيولًا وأثقالًا كثيرة، وبعث الأفرم بالبشارةِ على يد ناصر الدين محمد ولد الأمير بكتاش الفخري، فقدم في الخامس عشر بالأمراء المأسورين، فعفا السلطانُ عنهم وأحسن إليهم، وأعادهم على أخبازهم – عطاياهم-وجعلهم في عسكَرِه، ولما بلغ سنقر الأشقر كسرةُ عَسكرِه، جمع وحشد وبعث إلى الأمراء بغزة يَعِدُهم ويستميلهم، فقَدِمَ عليه شهاب الدين أحمد بن حجي أمير العربان بالبلاد القبلية، والأمير شرف الدين عيسى بن مهنا أمير العربان بالبلاد الشرقية والشمالية، وأتته النجداتُ مِن حلب وحماة ومن جبال بعلبك، واستخدم عدةً كبيرةً وبذل فيهم المال، وكَثُرت عنده بدمشق الأرجافُ أن عسكر مصر قد سار إليه، فاشتد استعدادُه، وجرَّد السلطان من القاهرة الأميرَ بدر الدين بكتاش الفخري أميرَ سلاح، ومعه الأمير بدر الدين الأيدمري والأمير حسام الدين أيتمش بن أطلس خان في أربعة آلاف فارس، فسار إلى غزة، واجتمعوا مع الأمير عز الدين الأفرم والأمير بدر الدين الأيدمري، وساروا جميعًا والمقَدَّم عليهم علم الدين سنجر الحلبي، فرحل عسكَرُ سنقر الأشقر من الرملة إلى دمشق، فخرج سنقر الأشقر في الثاني عشر صفر بعساكره وخيم بالجسورة خارج دمشق، ونزل عسكرُ مصر الكسوة والعقوة في يوم الاثنين السابع عشر بالجسورة، فوقعت الحرب في التاسع عشر، وثبت سنقر الأشقر وأبلى بلاء عظيمًا، ثم خامر من عسكَرِه طائفة كبيرة إلى عسكر مصر، وانهزم كثيرٌ منهم، ورجع عسكر حلب وحماة عنه إلى بلادِهم، وتخاذل عنه عسكرُ دمشق، وحمَلَ عليه الأمير سنجر الحلبي فانهزم منه، وهرب سنقر الأشقر وتَبِعَه بعض خواصه من الأمراء وساروا معه هم والأمير عيسى بن مهنا إلى برية الرحبة، وأقاموا بها أيامًا، وتوجهوا إلى الرحبة، وكان سنقر قبل ذلك قد بَعَثَ حرمه وأمواله إلى صهيون، ولما انهزم سنقر الأشقر تفرق عسكرُه في سائر الجهات، وغُلِّقَت أبواب دمشق، وزحف عسكر مصر إليها وأحاطوا بها، ونزلوا في الخيام ولم يتعرضوا لشيء، وأقام الأمير سنجر الحلبي بالقصر الأبلق في الميدان الأخضر خارج دمشق، فلما أصبح أمَرَ فنُوديَ بالأمان، وكان بقلعة دمشق الأميرُ سيف الدين الجكندار، وهو متوليها من جهة سنقر الأشقر، فأفرج عن الأمير ركن الدين بيبرس العجمي الجالق، والأمير حسام الدين لاجين المنصوري، والصاحب تقي الدين توبة، وحَلَّفَهم ألا يؤذوه إذا أطلقهم، ثم فتح باب القلعة، ونزل لاجين إلى باب الفرج فوقَفَ عليه، ومنع العسكَرَ من دخول المدينة، ونودِيَ بإطابة قلوب النَّاسِ وزينة البلد، فوقَفَ البشائر بالقلعة، وقدم كثيرٌ ممن كان مع سنقر الأشقر فأمنهم الأميرُ سنجر الحلبي، ثم في صفر من سنة 680هـ جردَ السلطان من دمشق الأميرَ عِزَّ الدين أيبك الأفرم والأمير علاء الدين كشتغدي الشمسي في عدة من الأجناد، فساروا إلى شيزر، فبعث سنقر الأشقر يطلب الصلحَ على أن يسلِّمَ شيزر، ويعَوَّضَ عنها الشغر وبكاس وكانتا، قد أخذت منه ومعهما فامية وكفر طلب وأنطاكية وعدة ضياع، مع ما بيده من صهيون وبلاطنس ونرزية واللاذقية، وشرط أيضًا أن يكون أميرًا بستمائة فارس، ويؤمر من عنده من الأمراء، فأُجيبَ إلى ذلك."},{"id":2740,"title":"وفاة الأمير سيف الدين أبي بكر بن أسبهسلار والي شرطة مصر .","date":["العام الهجري :679","الشهر القمري : ربيع الآخر","العام الميلادي :1280"],"text":"هو الأمير سيف الدين أبو بكر بن أسبهسلار وقد ولي شرطةَ مِصرَ عِدَّةَ سنين، وكان موصوفًا بالكرم المفرط، خيِّرًا في أموره، يشكُره الناس, وكان ممن زاد به السِّمَن– زيادة الوزن- حتى قاسى منه شِدَّة، وأشار عليه الطبيب بعدم النوم على جنبٍ، وبقي مدة لا يرمي جنبَه إلى الأرض خوفًا من أن يغرق في النومِ فيموت. مات في ربيع الآخر من هذه السنة، ودُفِنَ في القرافة."},{"id":2741,"title":"المغول يزحفون نحو إمارة حلب المملوكية .","date":["العام الهجري :679","الشهر القمري : جمادى الآخرة","العام الميلادي :1280"],"text":"ورد الخبر بمسير التتار إلى البلاد الشامية وذلك لما بلغهم من حصول الاختلاف بين المسلمين، وافترق التتار ثلاث فرق: فرقة سارت من جهة بلاد الروم ومقدمهم صمغار وتنجي وطرنجي، وفرقة من جهة الشرق ومقدمهم بيدو بن طوغاي بن هولاكو وبصحبته صاحب ماردين، وفرقة فيها معظم العسكرِ وشِرارُ المغول ومقدَّمُهم منكوتمر بن هولاكو، فخرج من دمشقَ الأميرُ ركن الدين إياجي على عسكر، وانضم مع العسكر المحاصر لشيزر، وخرج من القاهرةِ الأمير بدر الدين بكتاش النجمي على عسكر، واجتمع الجميعُ على حماة، وراسلوا الأميرَ سنقر الأشقر في إخماد الفتنة والاجتماعِ على قتال التتار، فبعث إليهم عسكرًا من صهيون أقام حول صهيون، ونزل الحاج أزدمر من شيزر وخيم تحت قلعتها، ووقعت الجفلةُ في البلاد الحلبية، فسار منها خلق كثير إلى دمشق في النصف من جمادى الآخرة، وكثُرَ الاضطراب في دمشق وأعمالها، وعزم الناسُ على تركها والمسير إلى ديار مصر، فلما كان في الحادي عشر هجمت طوائف التتار على أعمال حلب، وملكوا عينتاب وبغراس ودربساك، ودخلوا حلَبَ وقد خلت من العسكَرِ، فقتلوا ونهبوا وسَبَوا، وأحرقوا الجامِعَ والمدارس ودارَ السلطنة ودور الأمراء، وأقاموا بها يومينِ يكثرون الفساد بحيث لم يسلم منهم إلا من اختفى في المغائر والأسربة، ثم رحلوا عنها في يوم الأحد ثالث عشر عائدين إلى بلادهم بما أخذوه، وتفَرَّقوا في مشاتيهم، وتوجه السلطان قلاوون من مصر بالعساكر إلى البلاد الشاميَّة يريد لقاء التتار، بعد ما أنفق في كل أميرٍ ألف دينار، وفي كل جندي خمسَمائة درهم، واستخلف على مصر بقلعة الجبل ابنه الملك الصالح عليها، فسار السلطان إلى غزة، وقدم عليه بغزة من كان في البلاد الشامية من عساكر مصر، وقدم عليه أيضًا طائفةٌ من أمراء سنقر الأشقر فأكرَمَهم، ولم ينزل السلطانُ بغزة إلى عاشر شعبان، فرحل منها عائدًا إلى مصر، بعد أن بلغه رجوعُ التتار."},{"id":2742,"title":"وفاة أبغا بن هولاكو المغولي وقيام أخيه تكدرا بالملك وإسلامه .","date":["العام الهجري :680","العام الميلادي :1281"],"text":"هو ملك التتار، وصاحِبُ العراق والجزيرة وخراسان وغير ذلك، أبغا بن هولاكو بن تولي بن جنكيزخان, ويقال: اسمه أباقا، كان مقدامًا شجاعًا، عالي الهمة، لم يكن في إخوتِه مِثلُه، وهو على دينِ التتار لم يدخل في الإسلام، وكان ذا رأيٍ وحزم وخبرةٍ بالحرب، ولما توجَّه أخوه منكوتمر بالعساكِرِ إلى الشام لم يكن ذلك بتحريضِه، بل أشير عليه فوافق. قال الذهبي: \"كان كافِرَ النفس، سفاكًا للدماء، قتل في الروم خلقًا كثيرًا؛ لكونهم دخلوا في طاعة الملك الظاهرِ، وفرحوا بمجيئه إليهم، وقد نفذ الملك الظاهر إليه رسُلَه وهديه\" قال ابن عبد الظاهر في السيرة: \"وصِفَتُه أنه شاب أسمر أكحل، ربع القامة، جهوري الصوت، فيه بحة يسيرة، عليه قباء نفطي رومي، وسراقوج بنفسجي، تزوج زوجةَ أبيه ألجي خاتون وهي كهلة\" هلك أباقا بنواحي همذان عن نحو خمسين سنة، منها مدة ملكه سبع عشرة سنة، وقام في الملك بعده أخوه تكدار بن هولاكو، الذي اعتنق الإسلامَ بعد ذلك وتسمَّى بأحمد ولَقَّب نفسه بالسلطان فانقلبت بعد ذلك سياسةُ الدولة الإيلخانية ناحية بلاد الإسلام، وكان قد أرسل رسالة إلى السلطان قلاوون يُعلِمُه بإسلامه وما قام به من بناء المساجد والمدارس والأوقاف وتجهيز الحُجَّاج، وطلب منه كذلك العمَلَ على اجتماع الكلمة لإخماد الحروب والفِتَن والتحالُفِ ضدَّ الصليبيينَ."},{"id":2743,"title":"الهدنة بين الفرنج والسلطان قلاوون .","date":["العام الهجري :680","الشهر القمري : محرم","العام الميلادي :1281"],"text":"سار السلطان قلاوون من ظاهر القاهرة فأتته رسلُ الفرنج وهو بمنزلة الروحا في تقريرِ الهدنة، فتقَرَّرَت بين مقدم بيت الإسبتار وسائر الإسبتارية بعكا، وبين السلطان وولده الملك الصالح لمدة عشر سنين وعشرة أشهر وعشرة أيام وعشر ساعات، أولُها يوم السبت الثاني والعشرين من المحرم، وتقررت الهدنة أيضًا مع متملك طرابلس الشام بيمند بن بيمند لمدة عشر سنين، أولها السابع والعشرين شهر ربيع الأول، وعادت الرسل، وتوجه الأمير فخر الدين أياز المقري الحاجب لتحليف الفرنج ومقدم الإسبتار على ذلك، فحلفهم."},{"id":2744,"title":"ثورة العشير من الحورانية ونهبهم لغزة .","date":["العام الهجري :680","الشهر القمري : جمادى الآخرة","العام الميلادي :1281"],"text":"ثار العشير من الحورانية ونهبوا مدينة غزة، وقتلوا خلقًا كثيرًا وأفسدوا، فبعث السلطانُ قلاوون الأمير علاء الدين أيدكين الفخري على عسكرٍ مِن دمشق، وخرج من القاهرةِ الأمير شمس الدين سنقر البدوي على عسكر لتأديبِهم"},{"id":2745,"title":"هزيمة التتار على يد السلطان المنصور قلاوون في حمص .","date":["العام الهجري :680","الشهر القمري : رجب","العام الميلادي :1281"],"text":"ورد الخبر بدخول منكوتمر أخي أبغا بن هولاكو بن طلوي بن جنكيزخان إلى بلاد الروم بعساكر المغول، وأنه نزل بين قيسارية والأبلستين، فبعث السلطان قلاوون الكشافة، فلقوا طائفةً من التتار أسروا منهم شخصًا وبعثوا به إلى السلطان، فقَدِمَ إلى دمشق في العشرينَ مِن جمادى الأولى، فأتاه السلطانُ ولم ينزل به حتى أعلَمَه أن التتار في نحو ثمانين ألفًا، وإنهم يريدونَ بلاد الشام في أول رجب، فشرع السلطانُ في عرض العساكر، واستدعى الناس، فحضَرَ الأمير أحمد بن حجي من العراق في جماعة كبيرةٍ مِن آل مراتكون زهاء أربعة آلاف فارس، وقدمت نجدةٌ من الملك المسعود خضر بن الظاهر بيبرس صاحب الكرك، وقدمت عساكِرُ مصر وسائر العربان والتركمان وغيرهم، فوردت الأخبار بمسير التتار، وأنهم انقَسَموا فسارت فرقةٌ مع الملك أبغا بن هولاكو إلى الرحبة ومعه صاحب ماردين، وفرقة أخرى من جانب آخر، فخرج بجكا العلائي في طائفة من الكشافة إلى جهة الرحبة، وجفل الناسُ من حلب إلى حماة وحمص حتى خلت من أهلها، وعَظُم الإرجاف، وتتابع خروج العساكر من دمشق إلى يوم الأحد سادس عشر جمادى الآخرة، فخرج السلطانُ إلى المرج، بمن بقي من العساكر وأقام به إلى آخر الشهر، ثم رحل يريد حمص فنزل عليها في حادي عشر رجب ومعه سائر العساكر، وحضر الأمير سنقر الأشقر من صهيون ومعه بعض أمرائه فسُرَّ السلطان قلاوون بذلك وأكرمهم وأنعم عليهم، وكان ذلك في ثاني عشر فنزل سنقر الأشقر على الميسرة، وقويت الأراجيف بقرب العدو، ووصل التتارُ إلى أطراف بلاد حلب، وقدم منكوتمر إلى عين تاب، ونازل الملك أبغا قلعة الرحبة في السادس عشر جمادى الآخرة، ومعه نحو ثلاثة آلاف فارس، وتقدم منكوتمر قليلًا قليلًا حتى وصل حماة، وأفسد نواحيها وخرب جواسقَ الملك المنصور صاحب حماة وبستانه فورد الخبر إلى السلطان قلاوون بذلك وهو على حمص، وأن منكوتمر في خمسين ألفًا من المغول وثلاثين ألفًا من الكرج والروم والأرمن والفرنجة، وأنَّه قد قفز إليه مملوك الأمير ركن الدين بيبرس العجمي الجالق ودله على عورات المسلمين، ثم ورد الخبَرُ بأن منكوتمر قد عزم أن يرحل عن حماة، ويكون اللقاء في يوم الخميس رابع عشر رجب، واتفق عند رحيله أن يدخل رجلٌ منهم إلى حماة وقال للنائب: اكتُبِ الساعة إلى السلطان قلاوون على جناحِ الطائر بأن القَومَ ثمانون ألف مقاتل، في القلب منهم أربعةٌ وأربعون ألفًا من المغول وهم طالبون القلب، وميمنتهم قوية جدًّا، فيقوي ميسرة المسلمين، ويحترز على السناجق، فسقط الطائر بذلك وعلم بمقتضاه، وبات المسلمون على ظهور خيولهم، وعند إسفار الصباح من يوم الخميس رابع عشر شهر رجب: ركب السلطان ورتب العساكِرَ: وجعل في الميسرة الأميرَ سنقر الأشقر ومن معه من الأمراء، ثم اختار السلطانُ مِن مماليكه مائتي فارس، وانفرد عن العصائب ووقف على تل، فكان إذا رأى طلبًا قد اختل أردفه بثلاثمائةٍ مِن مماليكه، فأشرَفت كراديس التتار وهم مِثْلَا عساكر المسلمين، ولم يعتدُّوا منذ عشرين سنة مثل هذه العِدَّة، ولا جمعوا مثل جَمعِهم هذا، فإنَّ أبغا عرض من سيره صحبة أخيه منكوتمر فكانوا خمسة وعشرين ألف فارس منتخبة، فالتحم القتال بين الفريقين بوطأة حمص، قريبًا من مشهد خالد بن الوليد، ويوم الخميس رابع عشر رجب، من ضحوة النهار إلى آخره، وقيل من الساعة الرابعة، فصدمت ميسرة التتار ميمنة المسلمينَ صَدمةً شديدة ثبتوا لها ثباتًا عظيمًا، وحملوا على ميسرةِ التتار فانكسرت وانتَهَت إلى القلب وبه منكوتمر، وصَدَمَت ميمنة التتار  ميسرة المسلمين، فانكسرت الميسرةُ وانهزم من كان فيها، وانكسر جناحُ القلب الأيسر، وساق التتار خلفَ المسلمين حتى انتهوا إلى تحت حمص وقد غُلِّقَت أبوابها، ووقعوا في السوقةِ والعامة والرجَّالة والمجاهدين والغلمان بظاهر حمص، فقتلوا منهم خلقًا كثيرًا وأشرف الناس على التلاف، ولم يعلم المسلمون من أهل الميسرة بما جرى للمسلمين أهل الميمنة من النصر، ولا علم التتار الذين ساقوا خلف المسلمين ما نزل بميسرتِهم من الكسرة، ووصل بعض المنهزمين إلى صفد، وكثيرٌ منهم دخل دمشق، ومر بعضُهم إلى غزة، فاضطرب الناسُ بهذه البلاد وانزعجوا انزعاجًا عظيمًا، وأما التتار الذين ساقوا خلف المنهزمين من المسلمين أصحاب الميسرة، فإنهم نزلوا عن خيولهم وأيقنوا بالنَّصرِ، وأرسلوا خيولهم ترعى في مرج حمص، وأكلوا ونهبوا الأثقال والوطاقات والخزانة وهم يحسبون أن أصحابهم ستُدرِكُهم، فلما أبطأوا عليهم بعثوا من يكشف الخبر، فعادت كشافتُهم وأخبرتهم أن منكوتمر هرب، فركبوا وردُّوا راجعين، هذا ما كان من أمر ميمنة التتار وميسرة المسلمين، وأما ميمنة المسلمين فإنها ثبتت وهزمت ميسرة التتار حتى انتهت إلى القلب، إلا الملك المنصورَ قلاوون فإنه ثبت تحت السناجق –الرماح-، ولم يبقَ معه غير ثلاثمائة فارس، والكوسات تضرب، وتقدَّم سنقر الأشقر، وبيسري، وطيبرس الوزيري، وأمير سلاح، وأيتمش السعدي، ولاجين نائب دمشق، وطرنطاي نائب مصر، والدواداري، وأمثالهم من أعيان الأمراء إلى التتار، وأتاهم عيسى بن مهنا فيمن معه، فقتلوا من التتار مقتلةً عظيمة، وكان منكوتمر مقدم التتار قائمًا في جيشه، فلما أراده الله من هزيمته نزل عن فرسه ونظر من تحت أرجل الخيل، فرأى الأثقالَ والدواب فاعتقد أنَّها عساكر، ولم يكن الأمرُ كذلك، بل كان السلطان قلاوون قد تفرقت عنه عساكِرُه ما بين منهزم ومَن تقدم القتال، حتى بقي معه نحو الثلاثمائة فارس لا غير، فنهض منكوتمر من الأرض ليركَبَ فتقنطر عن فرسِه، فنزل التتار  كلُّهم لأجله وأخذوه، فعندما رآهم المسلمون قد ترجَّلوا حملوا عليهم حملةً واحدة كان الله معهم فيها، فانتصروا على التتار، وقيل إنَّ الأمير عز الدين أزدمر الحاج حمل في عسكر التتار وأظهر أنه من المنهزِمين، فقَدِمَهم وسأل أن يوصَلَ إلى منكوتمر، فلما قرب منه حمل عليه وألقاه عن فَرَسِه إلى الأرض، فلما سقط نزل التتارُ إليه من أجل أنه وقع، فحمل المسلمون عليهم عند ذلك، فلم يثبُت منكوتمر وانهزم وهو مجروح، فتبعه جيشه وقد افترقوا فرقتين: فرقة أخذت نحو سلمية والبرية، وفرقة أخذت جهة حلب والفرات، وأما ميمنة التتار التي كسرت ميسرة المسلمين، فإنها لما رجعت من تحت حمص كان السلطان قد أمر أن تلف السناجق ويبطل ضرب الكوسات، فإنَّه لم يبق معه إلَّا نحو الألف، فمرت به التتار ولم تعرض له، فلما تقدموه قليلًا ساق عليهم، فانهزموا هزيمةً قبيحة لا يلوون على شيء، وكان ذلك تمام النصر، وهو عند غروبِ الشمس من يوم الخميس، ومر هؤلاء المنهزمون من التتار نحو الجبل يريدون منكوتمر، فكان ذلك من تمام نعمة الله على المسلمين، وإلَّا لو قدر الله أنهم رجعوا على المسلمين لما وجدوا فيهم قوة، ولكِنَّ الله نصر دينه، وهزَمَ عَدُوَّه مع قوتهم وكثرتهم، وانجلَت هذه الواقعة عن قتلى كثيرة من التتار  لا يحصى عددهم، وعاد السلطانُ في بقية يومه إلى منزلتِه بعد انقضاء الحرب، وكتب البطائِقَ بالنصرة وبات ليلةَ الجمعة إلى السحر في منزلته، فثار صياحٌ لم يشك النَّاسُ في عود التتار، فبادر السلطان وركب وسائِرُ العساكر، فإذا العسكر الذي تبع التتار وقت الهزيمة قد عاد، وقتل من التتار في الهزيمة أكثَرَ ممن قتل في المصاف، واختفى كثيرٌ منهم بجانب الفرات، فأمر السلطان أن تُضرَمَ النيران بالأزوار التي على الفرات، فاحترق منهم طائفة عظيمة، وهلك كثير منهم في الطريق التي سلكوها من سلمية، وفي يوم الجمعة: خرج من العسكر طائفة في تتبع التتار، مقدمهم الأمير بدر الدين بيليك الأيدمري، ورحل السلطان من ظاهر حمص إلى البحيرة ليبعد عن الجيف، وقتل من التتار صمغار، وهو من أكبر مقدميهم وعظمائهم، وكانت له إلى الشام غارات عديدة، واستشهد من المسلمين زيادة على مائتي رجل، وأمَّا أبغا بن هولاكو ملك التتار فإنه لم يشعر وهو على الرحبة إلا وقد وقعت بطاقة من السلطانِ إلى نائب الرحبة، بما منَّ الله به من النصر وكسرةِ التتار فعندما بلغه ذلك بدق بشائر القلعة رحل إلى بغداد، ووصل الأميرُ بدر الدين الأيدمري إلى حلب، وبعث في طلب التتار إلى الفرات، ففَرُّوا من الطلب وغرق منهم خلق كثير، وعبرت طائفة منهم على قلعة البيرة، فقاتلهم أهلُها وقتلوا منهم خمسمائة، وأسروا مائة وخمسين، وتوجَّه منهم ألف وخمسمائة فارس إلى بغراس، وفيهم أكابِرُ أصحاب سيس وأقاربهم فخرج عليهم الأميرُ شجاع الدين السيناني بمن معه، فقتَلَهم وأسَرَهم عن آخرهم بحيث لم يُفلِتْ منهم إلا دون العشرين، وتوجَّه منهم على سلمية نحو أربعة آلاف، فأخذ عليهم نواب الرحبة الطرقات والمعابر، فساروا في البرية فماتوا عطشًا وجوعًا، ولم يسلم منهم إلا نحو ستمائة فارس، فخرج إليهم أهل الرحبة فقتلوا أكثرهم، وأحضروا عِدَّةً منهم إلى الرحبة ضُرِبت أعناقهم بها، وأدرك بقية التتار  الملك أبغا، وفيهم أخوه منكوتمر وهو مجروح، فغضب عليه وقال: \" لم لا مت أنت والجيش ولا انهزمت\" وغضب أيضًا على المقدمين، فلما دخل أبغا بغداد سار منها إلى جهة همذان وتوجه منكوتمر إلى بلاد الجزيرة فنزل بجزيرة ابن عمر، وكانت الجزيرة لأمه قد أعطاها إياها أبوه هولاكو لما أخذها."},{"id":2746,"title":"ثورة ابن أبي عمارة في تونس .","date":["العام الهجري :681","العام الميلادي :1282"],"text":"ثار على إبراهيم بن زكريا بن يحيى الثاني أمير الحفصيين في تونس رجل يدعى أحمد بن مرزوق يعرف بابن أبي عمارة الذي قوي أمره، حتى تنازل إبراهيم لابنه أبي فارس أمير مدينة بجاية من قبل أبيه فلقب نفسه بالمعتمد وسار إلى قتال ابن أبي عمارة غير أنه هزم وقُتِلَ، فما كان من أبيه إلا أن هرب باتجاه تلمسان فأدركه بعض أتباع ابن أبي عمارة فحُمِلَ إلى بجاية وقُتِلَ فيها عام 683هـ."},{"id":2747,"title":"بعض أخبار بني مرين والأندلس .","date":["العام الهجري :681","العام الميلادي :1282"],"text":"قام سانشو بن ملك قشتالة بالخروج على أبيه لينتزع منه الملك، فاستنجد الملك ألفونسو بأبي يوسف يعقوب بن عبد الحق سلطان بني مرين بالمغرب فأنجده بمال يستعين به على حشد الجنود، كما اجتاز السلطان بنفسِه البحر إلى الأندلس فأغار على أراضي قشتالة وحاصر قرطبة وغزا طليطلة، أمَّا أمير غرناطة أبو عبد الله محمد بن نصر بن الأحمر فأراد أن يصانع سانشو فزحف على المنكب التي كانت تحتلها قوات بني مرين؛ مما اضطر السلطان المريني أن يتخلى عن مؤازرة ألفونسو وعاد ليستردَّ المنكب وكادت أن تقع بينه وبين ابن نصر ملك غرناطة فتنة تفاداها ابن نصر بالتفاهم معه والتخلي له عن المنكب، وعاد السلطانُ المريني إلى المغرب وقد مكنت عودته وانسحابه من إنجاد ألفونسو أن تغلب سانشو على أبيه وهَزَمَه فأصبح طريدًا إلى أن توفي بعد سنتين."},{"id":2748,"title":"وفاة قاضي القضاة شمس الدين بن خلكان .","date":["العام الهجري :681","الشهر القمري : رجب","العام الميلادي :1282"],"text":"قاضي القضاة شمس الدين أبو العباس أحمد بن محمد بن إبراهيم بن أبي بكر بن خَلِّكان البرمكي الأربلي الشافعي، ولد بإربل سنة 608, وكان فاضلًا بارعًا متفننًا كريمًا جوادًا ممدوحًا فيه ستر وحِلمٌ وعفو، وعارفًا بالمذهب حسن الفتاوى جيد القريحة بصيرًا بالعربية علَّامة في الأدب والشعر وأيام الناس، كثيرَ الاطلاع حلو المذاكرة وافِرَ الحرمة، فيه رياسة كبيرة، قدم الشام في شبيبته, ودخل مصرَ وسكنها مدَّةً وتأهل بها وناب بها في القضاءِ عن القاضي بدر الدين السنجاري، ثم قدم الشام على القضاء في ذي الحجة سنة تسع وخمسين منفردًا بالأمر ثم أقيم معه في القضاء ثلاثة قضاة, ثم عزل عن القضاء سنة تسع وستين بالقاضي عز الدين بن الصائغ، ثم عزل ابن الصائغ بعد سبع سنين به، وقد كان المنصب بينه وبين ابن الصائغ دولًا يُعزل هذا تارة ويولى هذا، ويُعزَلُ هذا ويولى هذا، وابن خلكان هو أوَّلُ من جدد في أيامه قضاءَ القضاة من سائر المذاهب، فاشتغلوا بالأحكامِ بعد ما كانوا نوابًا له، وقد درَّس ابن خلكان في عدة مدارس لم تجتمع لغيره، ولم يبقَ معه في آخر وقت سوى الأمينية، وبيَدِ ابنه كمال الدين موسى النجيبية، توفي ابن خلكان بالمدرسة النجيبية في إيوانها يوم السبت آخر النهار، في السادس والعشرين من رجب، ودفن من الغد بسفح قاسيون عن ثلاث وسبعين سنة، له مصنفات أشهرها وفيات الأعيان وقد اشتهر كثيرًا وأنباء أبناء الزمان فيه أكثر من ثمانمائة ترجمة, وله مجاميع أدبية."},{"id":2749,"title":"أخذ قلعة قطيبا من التتار وقلعة كختا من النصارى .","date":["العام الهجري :682","العام الميلادي :1283"],"text":"في خامس المحرم خرجت تجريدة -الجريدة خَيْلٌ لا رَجَّالة فيها - من قلعة كركر إلى حصار قلعة قطيبا إحدى قلاع آمد، فأخذوها من أيدي التتار، وأقيم فيها الرجالُ وعملت بها الأسلحة والغلال، فصارت من حصون الإسلام المنيعة، وأخذت أيضًا قلعة كختا من النصارى بسؤال أهلها، فتسَلَّمَها أمراء السلطان قلاوون، بمدينة حلب، وشحنت بالأسلحة وغيرها، وصارت مسلطة على الأرمن."},{"id":2750,"title":"قتال مع الأرمن عند باب إسكندرونة .","date":["العام الهجري :682","العام الميلادي :1283"],"text":"غارت عساكر المسلمين على بلاد الأرمن، ووصلوا إلى مدينة أياس وقتلوا ونهبوا وحرقوا، واقتتلوا مع الأرمن عند باب إسكندرونة وهزموهم إلى تل حمدون، وعادوا سالمين ظافرين بالغنائم."},{"id":2751,"title":"قتال المسلمين مع فرنج قبرص ببيروت .","date":["العام الهجري :682","العام الميلادي :1283"],"text":"حين قصد الفرنج قبرص بلاد الساحل، قاتلهم المسلمون فردوهم عن دخول الساحل، وأسروا منهم زيادة على ثمانين رجلًا، وأخذت منهم غنائم كثيرة."},{"id":2752,"title":"وصول رسل صاحب بلاد سيلان من الهند إلى السلطان قلاوون .","date":["العام الهجري :682","الشهر القمري : محرم","العام الميلادي :1283"],"text":"وصولُ رسل صاحب بلاد سيلان من أرض الهند واسمه أبو أنكيه بكتابه، وهو صحيفة ذهب عرض ثلاثة أصابع في طول نصف ذراع بداخلها شيء أخضر يشبه الخوص، إلى السلطان قلاوون بمصر مكتوب فيه بقلم لم يوجد في القاهرة من يحسن قراءته، فسئل الرسل عنه فقالوا \" إنه يتضمن السلام والمحبة وإنه ترك صحبة صاحب اليمن وتعلق بمحبة السلطان، ويريد أن يتوجه إليه رسول، وذكر أن عنده أشياء عدها من الجواهر والفيلة والتحف ونحوها، وأنه عبأ تقدمة إلى أبواب السلطان، وأن في مملكة سيلان سبعًا وعشرين قلعة، وبها معادن الجواهر والياقوت، وأن خزائنه ملآنة من الجواهر."},{"id":2753,"title":"هدنة بين السلطان قلاوون وبين الفرنج .","date":["العام الهجري :682","الشهر القمري : ربيع الأول","العام الميلادي :1283"],"text":"جرت الهدنة بين السلطان قلاوون وبين الفرنج بعكا مدة عشر سنين."},{"id":2754,"title":"خروج أرغون بن أبغا المغولي على عمه أحمد سلطان .","date":["العام الهجري :682","الشهر القمري : جمادى الأولى","العام الميلادي :1283"],"text":"خرج أرغون بن أبغا على عمه تكدار المسمى أحمد سلطان بخراسان، فسار إليه وهزمه ثم أسره، فقامت الخواتين مع أرغون، وسألن الملك تكدار أحمد في الإفراج عنه وتوليته خراسان، فلم يرضَ بذلك، وكانت المغول قد تغيرت على تكدار، لكونه دخل في دين الإسلام وإلزامه لهم بالإسلام، فثاروا وأخرجوا أرغون من الاعتقال، وطرقوا ألناق نائب تكدار ليقتُلوه ففَرَّ منهم فأدركوه وقتلوا تكدار أيضًا في العام التالي، وأقاموا أرغون بن أبغا ملكًا، فولى أرغون وزارته سعد الدولة اليهودي، وولى ولديه خربندا وقازان خراسان، وعمل أتابكهما الأمير نوروز."},{"id":2755,"title":"وفاة شهاب الدين عبد الحليم بن تيمية والد شيخ الإسلام .","date":["العام الهجري :682","الشهر القمري : ذي الحجة","العام الميلادي :1284"],"text":"هو شهاب الدين عبد الحليم بن الشيخ الإمام العلامة مجد الدين عبد السلام أبي البركات بن عبد الله بن أبي القاسم بن تيمية الحراني، والد تقي الدين شيخ الإسلام ابن تيمية، مفتي الفرق، الفارق بين الفرق، كان له فضيلة حسنة، ولديه فضائل كثيرة، وكان له كرسي بجامع دمشق يتكلم عليه عن ظاهر قلبهِ، وولي مشيخةَ دار الحديث السكَّرية بالقصاعين، وبها كان سكَنُه، كان إمامًا في المذهب الحنبلي وَلِيَ القضاء على كُرهٍ، ثم اعتزله كان زاهدًا وَرِعًا مشهورَ الصَّلاحِ، توفي في دمشق عن 55 عامًا ودفن بمقابر الصوفيَّة رحمه الله."},{"id":2756,"title":"انقسام دولة بني حفص في تونس .","date":["العام الهجري :683","العام الميلادي :1284"],"text":"بعد خروج ابن أبي عمارة على دولة الحفصيين بتونس خلع أميرَها إبراهيم بن زكريا الحفصي وبويع أبو حفص عمر الأول بن يحيى بن عبد الواحد الحفصي، أما أبو زكريا يحيى بن أبي إسحاق فقد استقَلَّ بمدينة بجاية وقسطينة وبونة، وأقام دولة لهم بالمغرب الأوسط واتخذَ مِن بجاية عاصمةً له."},{"id":2757,"title":"وفاة ابن مودود الموصلي الفقيه الحنفي .","date":["العام الهجري :683","الشهر القمري : محرم","العام الميلادي :1284"],"text":"هو الإمام العالم المصَنِّف الفقيه الحنفي أبو الفضل عبد الله بن محمود بن مودود الموصلي، ولد بالموصل سنة 599هـ (1203م) له أصحاب وحلقة أشغال، ومن مصنفاته: \"المختار في الفتوى\" و\"الاختيار لتعليل المختار\" و\"الوقاية\" و\"شرح الجامع الكبير للشيباني\"، تولى قضاء الكوفة فترة، ثم استقَرَّ في بغداد يفتي ويدرس في مسجد الإمامِ أبي حنيفة. قال ابن الفوطي: \"كان عالمًا بالفقه والخلاف والأصول، سمع الكثيرَ في صباه وألحق الأحفاد بالأجداد، وكان صبورًا على السماع، ولي قضاء الكوفة، ثم فوض إليه تدريس مشهد الإمام أبي حنيفة، فكان على ذلك إلى أن توفي في العشرين من محرم\" مات ببغداد ودفن بمشهد أبي حنيفة، وكان يومًا مشهودًا."},{"id":2758,"title":"تحرك الفرنج لأخذ الشام .","date":["العام الهجري :683","الشهر القمري : ربيع الآخر","العام الميلادي :1284"],"text":"ورد الخبر بحركة الفرنج لأخذ الشام، فتجَهَّز السلطان قلاوون الألفي للسَّفَر وركب بعساكِرِه في يوم الأحد ثامن جمادى الأولى، وتوجه من قلعة الجبل إلى دمشق، وفي يوم السبت ثاني عشر جمادى الآخرة دخل السلطان إلى دمشق، فقدم القصاد من بلاد التتار بقتل أحمد تكدار بن هولاكو ملك التتار المسلم وولاية ابن أخيه أرغون بن أبغا."},{"id":2759,"title":"قتال الشريف أبو نمي بسبب أخذه الضرائب من حجاج اليمن .","date":["العام الهجري :683","الشهر القمري : رمضان","العام الميلادي :1284"],"text":"طردَ الشَّريفُ أبو نمي جند اليَمَن واستبدَّ بها، وكان من خبَرِه أن مكة كانت بينه وبين قتادة، وكان يؤخَذُ من حاج اليمنِ على كل جمل مبلغ ثلاثين درهمًا، ومن حاج مصر على الجمل مبلغ خمسين درهمًا مع كثرة النهب والعسف في جباية ما ذكر، فما زال الظاهر بيبرس حتى صار يؤخَذُ من حاج مصر مبلغ ثلاثين درهمًا على كل جمل، فجرَّد المظفر صاحب اليمن إلى مكة عسكرًا عليه أسد الدين جغريل، فمَلَكَها بعد حرب، فجمع قتادة وأبو نمي العرب لحربه، فوقع الاتفاق بينهما أن تكون مكةُ بينهم نصفين ثم اختلفا بعد مُدَّة، وانفرد أبو نمي وقَوِيَ وأخرج عسكر اليمن، واشتد على الحجاجِ في الجباية، فرسم السلطانُ بسفر ثلاثمائة فارس صحبة الأمير علاء الدين سنجر الباشقردي، وأنفق في كل فارسٍ ثلاثمائة درهم، وكتب بخروجِ مائتي فارس من الشام فتوجهوا صحبة الحاج، فكانت بينهم وبين أبي نمي وقعة، وأخربوا الدرب، وكان الحاجُّ كثيرًا؛ لأنها كانت وقفة الجمعة، ووقعت الحربُ بمكة بسبب أن أبا نمي بلغه توجه العسكر، فلم يخرج إلى لقاء الحاج وبَعَث قواده فقط، فلم يرضَ الباشقردي إلا بحضوره واستعَدَّ للحرب، وقد وقف أبو نمي بمن معه ليمنع العسكر من دخول مكة، ورموهم بالحِجارةِ فرماهم العسكر بالنشَّاب، وأحرق البابَ ودخلوا مكة، فقام البرهانُ خضر السنجاري حتى أخمد الفتنةَ، وحُمِلَت خِلعةُ أبي نمي إليه، وقضى الناس حَجَّهم."},{"id":2760,"title":"وفاة الملك المنصور ناصر الدين محمد الأيوبي صاحب حماة .","date":["العام الهجري :683","الشهر القمري : شوال","العام الميلادي :1285"],"text":"هو الملك المنصور ناصر الدين محمد بن الملك المظفر تقي الدين عمر بن شاهنشاه بن نجم الدين أيوب بن شاذي، صاحب حماة. ولد سنة 630، وتملك حماة سنة ثنتين وأربعين، وله عشر سنين، فمكث في الملك أزيد من أربعين سنة، وكان له بر وصدقات، وقد أعتَقَ في مرض موته خلقًا من الأرقاء. توفي يوم عاشر شوال بحماة وقام في الملك بعده ولده الملك المظفر بتقليد الملك المنصور له بذلك."},{"id":2761,"title":"أرغون المغولي يعتنق البوذية ويخطط لحرب المسلمين واستعانة بالبابا .","date":["العام الهجري :684","العام الميلادي :1285"],"text":"اعتنق أرغون البوذية- هو الذي خرج على عمه تكودار أحمد وقتله- وأرسل إلى البابا أربع سفارات يطلب منه إرسال حملة صليبية إلى مصر على أنه سيقوم هو بغزو الشام؛ حتى يُحكِموا قبضَتَهم على المسلمين، ولكن البابا لم يجِبه بشيء."},{"id":2762,"title":"وفاة أبي البقاء الرندي .","date":["العام الهجري :684","العام الميلادي :1285"],"text":"هو العلامة أثير الدين أبو البقاء صالح بن يزيد بن صالح بن علي بن موسى بن أبي القاسم بن شريف النفزي الرندي من قبيلة نفزة البربرية أبو الطيب، شاعر أندلسي من أهل رندة من جزيرة الأندلس، ولِدَ برندة سنة 601, وهو من القضاة، وله علمٌ بالحساب والفرائض، وهو أحد الأدباء المجيدين من أهل الأندلس. أقام بمالقة شهرًا، وأكثر الترددَ إلى غرناطة يسترفد ملوكَها، قال عنه أبو عبد الله محمد المراكشي في الذيل والتكملة: \"كان خاتمة أدباء الأندلس، بارع التصرف في منظوم الكلام ومنثوره، فقيهًا حافظًا فرَضيًّا متفنِّنًا في معارف جليلة، نبيل المنازع، متواضعًا مقتصدًا في أحواله، وله مقامات بديعة في أغراض شتى، وكلامه نظمًا ونثرًا مدون، وله تأليف في العَروض، وتأليف في صنعة الشعر سماه \"الكافي في علم القوافي\"، وأودعه جملة وافرة من نظمه\" وهو الذي نظم القصيدة المشهورة في رثاء الأندلس والتي أولها:لكل شيءٍ إذا ما تمَّ نقصانُ فلا يُغَرَّ بطِيبِ العيش إنسانُ رثى فيها الأندلس بعد انهيار دولة الموحدين في أعقاب هزيمتهم في معركة العقاب سنة 609 وانحسار المسلمين في غرناطة بعد أن استولى الفرنج على معظم مدن الأندلس الكبرى، كقرطبة وإشبيلية وبلنسية وغيرها، وعمل الفرنج على محو آثار الإسلام في هذه المدن, وكذلك عندما تنازل حاكم غرناطة الأمير محمد بن يوسف بن نصر لملك قشتالة الفونسو عن بعض المدن والحصون الإسلامية مصانعةً له, فأثارت هذه الأوضاع حميةَ أبي البقاء وغيَّرَتْه، فنظم هذه القصيدة المشهورة، والتي انتشرت في بلاد المسلمين وخاصة بلاد المغرب أرض العدوة، يرثي فيها حال المسلمين بالأندلس، ويستنجد بحكامها لإنقاذ إخوانهم في الأندلس."},{"id":2763,"title":"فتح المسلمين حصن المرقب وتحرير أسارى المسلمين .","date":["العام الهجري :684","الشهر القمري : صفر","العام الميلادي :1285"],"text":"سافر السلطان المنصور قلاوون الألفي بالعساكر المصرية والشامية فنزل المرقب، وهي قلعة حصينة تشرف على البحر بالشام، كانت بيد الإسبتارية، ففتحه الله عليهم في يوم الجمعة ثامن عشر صفر، وجاءت البشارة بذلك إلى دمشق فدُقَّت البشائر وزُينت البلد وفرح المسلمون بذلك؛ لأن هذا الحصن كان مضرة على المسلمين، ولم يتَّفِق فتحه لأحد من ملوك الإسلام لا للملك صلاح الدين، ولا للملك الظاهر بيبرس، وفتح حوله بلنياس ومرقب وهي بلدة صغيرة إلى جانب البحر عند حصن منيع جدًّا لا يصل إليه سهم ولا حجر منجنيق، فأرسل إلى صاحب طرابلس فهدمه تقربًا إلى السلطان الملك المنصور قلاوون، واستنقذ السلطان خلقًا كثيرًا من أسارى المسلمين، الذين كانوا عند الفرنجِ."},{"id":2764,"title":"وفاة الأمير علاء الدين أيدكين البندقدار الصالحيّ. .","date":["العام الهجري :684","الشهر القمري : ربيع الآخر","العام الميلادي :1285"],"text":"هو الأمير الكبير أيدكين علاء الدين البندقدار الصالحي أستاذ الملك الظاهر بيبرس وإليه ينسب. كان من كبار الأمراء الصالحية وكان عاقلًا ساكنًا. كان مملوكًا للأمير جمال الدين موسى بن يغمور ثم انتقل إلى الصالح نجم الدين فجعله بندقداره,  ثم غضب الملك الصالح نجم الدين أيوب على أيدكين وصادره، وأخذ منه مماليكَه وكان منهم بيبرس البندقداري، وأضافه إليه لشهامتِه ونهضته، فتقدَّمَ بيبرس عنده على خشداشيته – زملائه مهنته – فلما تسلطن بيبرس صار علاء الدين أيدكين أحدَ قادة الظاهر بيبرس وتوفي علاء الدين بالقاهرة في ربيع الآخر من هذه السنة، ودُفِنَ بالشارع الأعظم قبالة حمام الفارقاني بظاهر القاهرة. وصُلي عليه بدمشق صلاة الغائب وكان قد ناهز السبعينَ."},{"id":2765,"title":"وفاة الشاعر حازم القرطاجني  .","date":["العام الهجري :684","الشهر القمري : رمضان","العام الميلادي :1285"],"text":"هو الشاعر والناقد أبو الحسن حازم بن محمد بن حازم الأنصاري القرطاجني. ولد سنة 608هـ )1211م) في قرطاجنة وإليها نسب، ونشأ في أسرة ذات علم ودين، فأبوه كان فقيهًا عالِمًا، تولى والده قضاء قرطاجنة أكثر من أربعين عامًا، وقد عني بولده حازم فوجهه إلى طلب العلم مبكرًا. وبعد أن سقطت قرطاجنة ومرسية في أيدي القشتاليين للمرة الأولى سنة 640هـ (1243م) غادر عدد كبير من العلماء والأدباء الأندلس، ووجهوا شطرهم إما إلى بلاد المشرق الإسلامي أو إلى بلاد المغرب، وكان حازم القرطاجني ممن استقر به المقام في مراكش، والتحق بحاشية حاكم الموحدين أبي محمد عبد الواحد الملقب بالرشيد، وكان بلاطه عامرًا بالأدباء والشعراء، ثم ما لبث أن ترك مراكش إلى تونس، واتصل بسلطانها أبي زكريا الحفصي، فعرف له فَضلَه وعِلمَه، فقَرَّبه منه، وعيَّنه كاتبًا في ديوانه. ولما توفِّي أبو زكريا الحفصيُّ خلفه ابنه أبو عبد الله محمد المستنصر، وكان على شاكلة أبيه في احترامِ العلماء والأدباء وتقديرهم؛ ولهذا وجد حازم القرطاجني في ظِلِّ حُكمِه كل عناية وتقدير، وكان المستنصِرُ يثق به وبذوقه الأدبي، فكان يدفع إليه ببعض المؤلفات ليرى فيها رأيه ويقرر مستواها العلمي. وظل حازم القرطاجني في تونس ولم يغادرها، محاطًا بكل عناية من حكام الدولة الحفصية، موزعًا وقته بين العمل في الديوان وعقد حلقات العلم لتلاميذه، حتى تُوفِّي في ليلة السبت 24 من رمضان من هذه السنة."},{"id":2766,"title":"وفاة السلطان المنصور يعقوب المريني .","date":["العام الهجري :685","العام الميلادي :1286"],"text":"هو السلطان المنصور أبو يوسف يعقوب بن عبد الحق بن محبو بن حمامة المريني مؤسس دولة بني مرين ببلاد المغرب بين فكيك وملوية. ولد بالمغرب سنة 609 وقد تولى قيادة بني مرين سنة 653 بعد وفاة أخيه أبي بكر بن عبد الحق, وتلقب يعقوب بالمنصور. وكان شجاعًا صوامًا قوامًا مجاهدًا مقرِّبًا لأهل الصلاح والخير والعلم. خرج على أبي دبوس آخر حكام الموحدين وقتله، واستولى على مملكة المغرب، فقضى على دولة آل عبد المؤمن الموحدين, ومَلَك سبتة سنة 672 واستقرَّت قدمُه في الملك، وكانت له جهود كبيرة في نصرة المسلمين في الأندلس، فاستعاد إشبيلية، وملَكَ بعده ولده يوسف أبو يعقوب, والمنصور هذا يختلف عن المنصور أبي يوسف يعقوب بن عبد المؤمن الموحدي المتوفى سنة 595"},{"id":2767,"title":"وقعة بين بلبان الطباخي نائب حصن الأكراد وبين أهل المرقب .","date":["العام الهجري :685","العام الميلادي :1286"],"text":"كانت وقعةٌ بين الأمير بلبان الطباخي أحد مماليك المَلِك المنصور، ونائِبِه بحصنِ الأكراد وبينَ أهلِ حصنِ المرقب، بسَبَبِ أخذِهم قافلةَ تجارةٍ قُتِلَ فيها عِدَّةٌ من مماليك بلبان، وجُرِحَ هو في كَتِفِه، فاستأذنَ بلبان السُّلطان في الإغارةِ على بلَدِ المرقب، لِما اعتمده أهلُه من الفساد عند وصول التتر إلى حلب، فأذِنَ له السلطان في ذلك، فجمع بلبان الطباخي عساكرَ الحصون، وسار إلى المرقَب، ولم يزَلْ عليه حتى أخذَه بعد حروبٍ شديدةٍ في يوم الجمعة تاسع عشَرَ ربيع الأول، واستقَرَّ الطباخي نائبًا به."},{"id":2768,"title":"وفاة القاضي البيضاوي .","date":["العام الهجري :685","العام الميلادي :1286"],"text":"هو القاضي الإمامُ العلَّامة ناصرُ الدين عبدُ الله بنُ عمر الشيرازي البيضاوي، قاضيها وعالمُها وعالمُ أذربيجان وتلك النواحي، ولِدَ في البيضا من فارس، تولى قضاء شيراز ثم رحل إلى تبريز، اشتهر بعلمِه فقد كان بارعًا في الأصول والفقه والكلام والنحو، ومن مصنفاته: منهاج الوصول إلى علم الأصول، وهو مشهور، وقد شرحه غيرُ واحد، وشرْح التنبيه في أربع مجلدات، والغاية القصوى في دراية الفتوى، وشرح المنتخب، والكافية في المنطق، وطوالع الأنوار وشرح المحصول أيضًا، والتفسير المشهور بتفسير البيضاوي، واسمُه أنوار التنزيل وأسرار التأويل، وله غير ذلك من التصانيف، مات بتبريز سنة 685، وقد أوصى إلى القطب الشيرازي أن يُدفَنَ بجانبه بتبريز."},{"id":2769,"title":"أخذ السلطان قلاوون الكرك من الملك المسعود بن الظاهر بيبرس .","date":["العام الهجري :685","الشهر القمري : صفر","العام الميلادي :1286"],"text":"سار الأميرُ حُسام الدين طرنطاي نائبُ السلطنة بعسكَرٍ كثيفٍ إلى الكرك، فتلَقَّاه عسكَرُ دِمشقَ صحبة الأمير بدر الدين الصوابي، فتوجَّهَ معه إليها، وضايقَها وقطَعَ الميرةَ عنها حتى بعث المَلِكُ المسعود بن الظاهر بيبرس أخاه خضر يطلبُ الأمان، فبعث إليه السلطانُ قلاوون الأميرَ ركن الدين بيبرس الدوادار من قلعة الجبل بالأمانِ، فنزل الملك المسعود وأخوه بدر الدين سلامش إلى الأميرِ طرنطاي في خامس صفر، واستقَرَّ الأمير عزُّ الدين أيبك الموصلي نائبُ الشوبك في نيابة الكرك، ووردت البشارة بأخذِ الكركِ إلى قلعةِ الجَبَل في ثامن صفر، وقَدِمَ الأمير طرنطاي بأولاد الظاهرِ إلى القاهرة، فخرج السلطانُ إلى لقائه في ثاني عشر ربيع الأول، وأكرم السلطانُ الملكَ المسعود وسلامش، وأمَّرَ كُلًّا منهما إمرةَ مائة فارس، وصارا يركبان في الموكب والميادين، ورتبا يركبان مع الملك الصالح علي، وفي سابع رجب توجَّه السلطان إلى الكرك، فوصلها وعرَضَ حواصِلَها ورجالها وشحَنَ بها ألفي غرارة قمح، وقرَّرَ بها بحريَّةً ورتَّبَ أمورَها، ونظَّف البركة، وجعل في نيابة الكرك الأميرَ ركن الدين بيبرس الدوادار، ونقل عز الدين أيبك إلى نيابة غزَّة، ثم نقله إلى نيابةِ صَفد."},{"id":2770,"title":"مطر عظيم بالمدينة يخرب المسجد النبوي وجراد يهلك الزرع .","date":["العام الهجري :686","الشهر القمري : محرم","العام الميلادي :1287"],"text":"أُمطِرَت المدينةُ النبويَّةُ في ليلة الرابع من المحرم مطرًا عظيمًا فوكَفَت سقوفُ المسجِدِ النبوي والحُجرة الشريفة، وخَربت عدَّةُ دُورٍ وتَلِفَ نخلٌ كثيرٌ من السيولِ، ثم عقب ذلك جرادٌ عظيمٌ صار له دويٌّ كالرعد، فأتلف التَّمرَ وجريد النخلِ وغيرَه من المزارع، وكانت الأعينُ قد أتلَفَها السيلُ، وخَرَّبَ عين الأزرق حتى عادت مِلحًا أُجاجًا، فكتب بذلك إلى السُّلطانِ قلاوون، وأنَّ الحُجرةَ الشَّريفةَ عادتُها أن تُشمسَ في زَمَن الخُلَفاء إذا وَلِيَ الخليفةُ، فلا تزالُ حتى يقومَ خليفةٌ آخرُ فيُشمِسوها، وأنَّ المنبرَ والرَّوضةَ يُبعَث بكسوتِها في كلِّ سَنةٍ، وإنَّهما يحتاجانِ إلى كسوةٍ."},{"id":2771,"title":"استرجاع حصن صهيون في اللاذقية .","date":["العام الهجري :686","الشهر القمري : جمادى الآخرة","العام الميلادي :1287"],"text":"توجَّه الأميرُ حُسام الدين طرنطاي نائبُ السُّلطة على عسكرٍ كثيرٍ لقتالِ الأمير شمسِ الدين سنقر الأشقر بصهيون، وسَبَبُ ذلك أنَّ السُّلطانَ لَمَّا نازَل المرقب وهي بالقربِ من صهيون، لم يحضُرْ إليه سنقر الأشقر، وبعث إليه ابنَه ناصرَ الدين صمغار، فأسَرَّها السلطانُ في نفسِه، ولم يمكِّنْ صمغار من العودِ إلى أبيه وحَمَله معه إلى مصر، واستمَرَّ الحالُ على ذلك حتى هذه السنة، فسار طرنطاي ونازل صهيونَ حتى بعث الأشقر يطلُبُ الأمانَ فأمَّنَه، ونزل سنقر إليه ليسَلِّمَ الحصن، فخرج طرنطاي إلى لقائِه ماشيًا، فنزل سنقر عندما رآه وتعانقا، وسار سنقر إلى مخيم طرنطاي، وقد خلع طرنطاي قباءَه وفَرَشه على الأرض ليمشيَ عليه سنقر، فرفع سنقر القباءَ عن الأرض وقَبَّله ثمَّ لَبِسَه، فأعظم طرنطاي ذلك من فِعلِ سنقر، وشَقَّ عليه وخَجِلَ، وأخذ يعامل سنقر من الخدمة بأتمِّ ما يكون، وتسَلَّمَ طرنطاي حصن صهيون، ورتَّبَ فيه نائبًا وواليًا وأقام به رجالًا، بعد ما أنفق في تلك المدَّة أربعَمائة ألف درهم في العسكر الذي معه، فعتب عليه السلطانُ، ثم سار طرنطاي إلى مصر ومعه سنقر الأشقر حتى قَرُب من القاهرة، فنزل السلطان من قلعة الجبل، وهو وابنُه الملك الصالح علي، وابنُه الملك الأشرف خليل، وأولاد الملك الظاهر، في جميعِ العساكر إلى لقاءِ سنقر الأشقر، وعاد به إلى القلعةِ، وبعث إليه الخِلَع والثيابَ وحوائِصَ الذَّهَب والتُّحَف والخيولَ، وأنعم عليه بإمرةِ مائة فارس وقَدَّمَه على ألف، فلازم سنقر الخِدمةَ مع الأمراءِ إلى سابع عِشْرِي شهر رجب، وخرج السلطان من قلعة الجبل سائرًا إلى الشام، فأقام بتل العجول ظاهِرَ غَزَّة."},{"id":2772,"title":"غزو بلاد النوبة .","date":["العام الهجري :686","الشهر القمري : ذي الحجة","العام الميلادي :1288"],"text":"في سادس ذي الحجة توجَّه الأميرُ عَلَم الدين سنجر المسروري المعروف بالخياط متولي القاهرة، والأميرُ عز الدين الكوراني، إلى غزوِ بلاد النوبة، وجرَّدَ السلطانُ قلاوون معهما طائفةً مِن أجناد الولايات بالوجهِ القبلي والقراغلامية، وكتب إلى الأمير عز الدين أيدمر السيفي السلاح دار متولِّي قوص أن يسيرَ معهما بعُدَّته ومن عنده من المماليك السلطانية المركزين بالأعمال القوصيَّة، وأجناد مركز قوص، وعُربان الإقليم: وهم أولاد أبي بكر وأولاد عمر، وأولاد شيبان وأولاد الكنز وبني هلال، وغيرهم، فسار الخياط في البَرِّ الغربي بنصف العسكرِ، وسار أيدمر بالنصفِ الثاني من البر الشرقي، وهو الجانبُ الذي فيه مدينُة دنقلة، فلما وصل العسكرُ أطرافَ بلاد النوبة أخلى ملك النوبةِ سمامون البلادَ، وكان صاحِبَ مكرٍ ودهاء، وعنده بأس، وأرسل سمامون إلى نائبه بجزائر ميكائيل وعمل الدو واسمه جريس، ويُعرف صاحب هذه الولاية عند النوبة بصاحب الجبل، يأمره بإخلاء البلادِ التي تحت يده أمامَ الجيش الزاحف، فكانوا يرحلونَ والعسكَرُ وراءهم منزلةً بمنزلة، حتى وصلوا إلى مَلِك النوبة بدنقلة، فخرجَ سمامون وقاتلَ الأمير عز الدين أيدمر قتالًا شديدًا، فانهزم ملكُ النوبة وقُتِلَ كثيرٌ ممن معه، واستشهد عدَّةٌ من المسلمين، فتبع العسكَرُ مَلِكَ النوبةِ مَسيرةَ خَمسةَ عَشَر يومًا من رواءِ دنقلة إلى أن أدركوا جريس وأسروه، وأسَرُوا أيضًا ابنَ خالة الملك، وكان من عظمائِهم، فرتَّبَ الأميرُ عِزُّ الدين في مملكة النوبةِ ابنَ أختِ الملك، وجعل جريس نائبًا عنه، وجرَّد معهما عسكرًا، وقرَّرَ عليهما قطعةً يَحمِلانها في كلِّ سَنةٍ، ورجع بغنائم كثيرة ما بين رقيق وخيول وجمال وأبقار وأكسية."},{"id":2773,"title":"نقض الفرنج بطرابلس الهدنة .","date":["العام الهجري :687","العام الميلادي :1288"],"text":"نقض الفرنجُ بطرابلس الهدنةَ، عندما أخذوا جماعةً مِن التجارِ وغَيرهم، وصار بأيديهم عدَّةُ أسرى، وكانوا لَمَّا مَلَك السلطانُ قَلعةَ المرقب قد بعثوا إليه هديةً، وصالحوه على ألَّا يتركوا عندهم أسيرًا، ولا يتعَرَّضوا لتاجرٍ ولا يقطعوا الطريقَ على مسافرٍ، فتجهَّزَ السلطان قلاوون لأخذ طرابلسَ."},{"id":2774,"title":"وفاة الإمام النحوي بدر الدين محمد بن مالك .","date":["العام الهجري :687","الشهر القمري : محرم","العام الميلادي :1288"],"text":"هو الإمامُ البليغُ النَّحوي بدرُ الدين أبو عبدِ اللهِ محمَّدُ بنُ محمد بن الإمام العلامة الأوحد جمال الدين عبد الله بن مالك، الإمامُ البليغ النحوي بدر الدين ابن الإمام العلامة جمال الدين الطائي الجياني ثم الدمشقي شارح الألفية التي لأبيه، وهو من أحسَنِ الشروحِ وأكثَرِها فوائد، كان إمامًا ذكيًّا فَهِمًا حادَّ الخاطر، إمامًا في النحو والمعاني والبيان والبديع والعروض والمنطق، جَيِّدَ المشارَكةِ في الفقهِ والأصولِ، أخذ عن والده وسكن بعلبَكَّ فقرأ عليه بها جماعةٌ منهم بدر الدين بن زيد، فلما مات والده طلب إلى دمشق ووَلِيَ وظيفةَ والِدِه وسكنها وتصدى للأشغالِ والتصنيفِ, وكان لطيفًا ظريفًا فاضلًا، كانت وفاته يومَ الأحدِ الَّثاِمَن من المحرم، ودفن من الغد بباب الصغير بدمشقَ."},{"id":2775,"title":"غزو دنقلة من بلاد النوبة .","date":["العام الهجري :687","الشهر القمري : جمادى الأولى","العام الميلادي :1288"],"text":"كتب السلطان قلاوون إلى الأكابر ببلاد السند والهند والصين واليمن والنوبة صورةَ أمان لمن اختار الحضورَ إلى ديار مصر وبلادِ الشام، من إنشاءِ فَتحِ الدين بن عبد الظاهر، وسيَّرَه مع التجار، وفي أول جمادى الأولى ورَدَت كتب الأمير علم الدين سنجر المسروري الخياط من دنقلة (من بلاد النوبة)، بفتحها والاستيلاءِ عليها وأسرِ مُلوكها، وأخْذِ تيجانهم ونسائِهم، وكان الكِتابُ على يد ركن الدين منكورس الفاقاني، فخلع عليه وكتب معه الجوابَ بإقامة الأمير عزِّ الدين أيدمر والي قوص بدنقلة، ومعه مَن رسمَ لهم من المماليك والجُند والرجال، وأن يحضُرَ الأمير علم الدين ببقيَّة العسكر، وجهَّزَ من قلعة الجبل سعد ابن أخت داود؛ ليكونَ مع الأمير أيدمر لخبرته بالبلادِ وأهلها، فسار وقد أعطي سيفًا مُحلًّى، فأقام بقوص، وأما النوبةُ فإن عامون مَلِكَها رجع بعد خروج العسكر إلى دنقلة، وحارب من بها وهزَمَهم، وفَرَّ منه الملك وجريس والعسكر المجرد، وساروا إلى القاهرة، فغضب السلطانُ وأمر بتجهيز العسكر لغزو النوبةِ."},{"id":2776,"title":"وفاة ولي العهد الملك الصالح علاء الدين بن الملك المنصور قلاوون  .","date":["العام الهجري :687","الشهر القمري : شعبان","العام الميلادي :1288"],"text":"هو المَلِكُ الصالح علاءُ الدين ابن الملك المنصور قلاوون وَليُّ العهدِ توفِّيَ في يوم الأحد خامس عشر من رجب خرج السلطان مبرزًا بظاهر القاهرة يريد الشامَ، فركب معه ابنه الملك الصالح ثمَّ عاد الصالح إلى قلعة الجبل آخِرَ النهار، فتحَرَّك عليه فؤاده في الليلِ وكَثُرَ إسهاله الدموي وأفرط، فعاد السلطانُ لعيادته في يوم الأربعاء الثامن عشر ولم يُفِدْ فيه العلاج، فعاد السلطانُ إلى الدهليز من يومِه، فأتاه الخبر بشدة مرض الملك الصالح، فعاد إلى القلعة، وصَعِدَت الخزائن في يوم الثلاثاء أوَّلَ شعبان، وطلعت السناجق والطلب في يوم الأربعاء ثانيه، فمات الصالحُ بكرة يوم الجمعة رابعَه من دوسنطاريا كبديَّة، وتحدثت طائفةٌ بأن أخاه الملك الأشرف خليلًا سَمَّه، فحضر الناسُ للصلاة عليه، وصلى عليه بالقلعةِ قاضي القضاة تقي الدين بن بنت الأعز إمامًا، والسلطانُ خَلفَه في بقيَّة الأمراء والملك الأشرف خليل، ثم حُمِلَت جنازته، وصلى عليه ثانيًا قاضي القضاة معز الدين نعمان بن الحسن بن يوسف الخطبي الحنفي خارج القلعة، ودُفِنَ بتربة أمه قريبًا من المشهد النفيسي، وفي حادي عشر شعبان.."},{"id":2777,"title":"ولاية العهد الأشرف صلاح الدين خليل بن قلاوون بعد وفاة أخيه .","date":["العام الهجري :687","الشهر القمري : شعبان","العام الميلادي :1288"],"text":"فوَّضَ السلطانُ قلاوون ولايةَ العهدِ لابنه المَلِك الأشرف صلاحِ الدين خليل بعد وفاة أخيه ولي العهد المَلِك الصالح علاء الدين، فركِبَ بشعار السَّلطنة من قلعةِ الجبل إلى باب النصر، وعبَرَ إلى القاهرة وخرج من بابِ زويلة، وصَعِدَ إلى القلعة وسائِرُ الأمراء وغيرُهم في خدمته، ودُقَّت البشائر، وحَلَف القضاةُ له وجميع العسكر، وخلع على سائرِ أهل الدولة، وخُطِبَ له بولاية العهد، واستقَرَّ على قاعدة أخيه الصالحِ علي، وكُتِبَ بذلك إلى سائر البلاد، وكُتِبَ له تقليدٌ."},{"id":2778,"title":"وفاة الطبيب ابن النفيس .","date":["العام الهجري :687","الشهر القمري : ذي القعدة","العام الميلادي :1288"],"text":"هو العلَّامةُ علاء الدين علي بن أبي الحزم القرشي الدمشقي شيخُ الأطباء في عصرِه المعروف بابن النفيس، الحكيمُ في فَنِّه، لم يكُنْ في عصره من يضاهيه في الطبِّ والعلاج والعِلم، اشتغل على المهذَّب حتى برع، وانتهت إليه رياسةُ فَنِّه في زمانه، وهو صاحِبُ التصانيفِ المفيدة، منها: الشامِلُ في الطب، والمهَذَّب في الكحل، والموجز، وشرح القانون لابن سينا، وكانت تصانيفُه يُملِيها من ذهنه ولا يحتاجُ فيها إلى مراجعةٍ لِتَبحُّرِه في فن الطب, وانتهت إليه رياسةُ الطبِّ بالديارِ المصرية. درَّسَ الطبَّ في البيمارستان النوري في مصر، وإليه يُنسَبُ اكتشاف الدورة الدموية الصغرى، وقال: إن الدم ينقى في الرِّئتَين، ومات في ذي القعدة بعد أن أوقف داره وأملاكَه وجميع ما يتعلَّقُ به على البيمارستان المنصوري بالقاهرة."},{"id":2779,"title":"فتح السلطان قلاوون قلاعًا كثيرة بناحية حلب .","date":["العام الهجري :688","العام الميلادي :1289"],"text":"فُتِحَت قلاعٌ كثيرة بناحية حلب كركر وتلك النواحي، وكُسِرَت طائفة من التتر هناك، وقُتِلَ مَلِكُهم خربندا نائبُ التتار على ملطية."},{"id":2780,"title":"السلطان قلاوون يحرر إمارة طرابلس من الصليبيين .","date":["العام الهجري :688","الشهر القمري : ربيع الآخر","العام الميلادي :1289"],"text":"خرج السلطانُ قلاوون من دمشق إلى طرابلس فنازلها، وقد قَدِمَ لنجدة أهلِها أربعة شوان- سفن حربية كبيرة- من جهةِ متمَلِّك قبرص، فوالى السلطانُ الرميَ بالمجانيق عليها والزَّحفِ والنُّقوب في الأسوار، حتى افتَتَحها عَنوةً في الساعة السابعة من يوم الثلاثاء رابع ربيع الآخر، بعدما أقام عليها أربعة وثلاثين يومًا، ونصب عليها تسعةَ عشر منجنيقًا، وعَمِلَ فيها ألف وخمسمائة نفسٍ من الحجَّارين الزرَّاقين- رُماة الرماح- وفرَّ أهلُها إلى جزيرة تجاه طرابلس، فخاض الناس فرسانًا ورجالًا وأسَرُوهم وقتلوهم وغَنِموا ما معهم، وظَفِرَ الغلمان والأوشاقية- مسؤولو ركوب السلطان للأحصنة للمتعة والرياضة- بكثيرٍ منهم كانوا قد ركبوا البحرَ فألقاهم الريحُ بالساحل، وكَثُرت الأسرى حتى صار إلى زردخاناه السلطان ألف ومائتا أسير، واستشهد من المسلمين الأميرُ عِزُّ الدين معن، والأميرُ ركن الدين منكورس الفارقاني، وخمسة وخمسون من رجال الحلقة، وأمر السلطان بمدينة طرابلس فهُدِمت، وكان عرض سورها يمرُّ عليه ثلاثةُ فرسان بالخيل، ولأهلها سعاداتٌ جليلة منها أربعة آلاف نول قزازاة، وأقر السلطان بلدةَ حبيل مع صاحِبِها على مالٍ أخذه منه، وأخذ بيروت وجبلة وما حولها من الحصون، وعاد السلطانُ إلى دمشق في نصف جمادى الأولى، ثم عمر المسلمون مدينة بجوار النهر فصارت مدينة جليلة، وهي التي تعرف اليوم بطرابلس، وقد كان لها في أيدي الفرنج من سنة 503 إلى هذا التاريخ، وقد كانت قبل ذلك في أيدي المسلمين من زمان معاوية، فقد فتحها سفيانُ بن نجيب لمعاوية، فأسكنها معاويةُ اليهود، ثم كان عبدُ الملك بن مروان جدَّدَ عِمارَتَها وحَصَّنَها وأسكنها المسلمين، وصارت آمنةً عامرة مطمئنة، وبها ثمارُ الشام ومصر، فإنَّ بها الجوز والموز والثلج والقصب، والمياه جارية فيها تصعدُ إلى أماكِنَ عالية، وقد كانت قبل ذلك ثلاثَ مدن متقاربةً، ثم صارت بلدًا واحدًا، ثم حُوِّلت من موضعها ثمَّ أمر السلطان الملك المنصور قلاوون أن تهَدَّمَ البلد بما فيها من العمائِرِ والدور والأسوار الحصينة التي كانت عليها، وأن يبنى على ميل منها بلدةٌ غيرُها أمكَنُ منها وأحسَنُ، ففعل ذلك، فهي هذه البلدة التي يقال لها طرابلس."},{"id":2781,"title":"وفاة الملك المنصور شهاب الدين محمود .","date":["العام الهجري :688","الشهر القمري : شعبان","العام الميلادي :1289"],"text":"هو الملك المنصور شهاب الدين محمود بن الملك الصالح إسماعيل بن الملك العادل. وقد توفِّيَ يوم الأربعاء ثامن عشر شعبان، وصلي عليه بالجامع الأموي، ودفِنَ مِن يومِه."},{"id":2782,"title":"فتح مدينة دنقلة من بلاد النوبة .","date":["العام الهجري :688","الشهر القمري : شوال","العام الميلادي :1289"],"text":"جرَّد السلطان قلاوون الأميرَ عِزُّ الدين أيبك الأفرم أمير جاندرا إلى بلاد النوبة، ومعه من الأمراء قبجاق المنصوري وبكتمر الجوكندار، وأيدمر والي قوص، وكثير من الأمراء، وسائرُ أجناد المراكز بالوجه القبلي، ونواب الولاة، ومن عُربان الوجهين القبلي والبحري عدة أربعين ألف راجل، ومعهم متمَلِّك النوبة وجريس، فساروا في ثامن شوال، وصَحِبَتهم خمسمائة مركب ما بين حراريق ومراكب كبار وصغار تحمِلُ الزاد والسلاح والأثقال، فلما وصلوا ثغر أسوان مات متمَلِّك النوبة ونائبه، فدُفِن بأسوان، فطالع الأميرُ عز الدين الأفرم السلطانَ بموته، فجَهَّزَ إليه من أولاد أخت الملك داود رجلًا كان بالقاهرة ليملِّكَه، فأدرك العسكرَ على خيل البريد بأسوان وسار معه، وقد انقسموا نصفين: أحدهما الأميرُ عز الدين الأفرم وقبجاق في نصف العسكرِ مِن الترك والعَرَب في البر الغربي، وسار الأمير أيدمر والي قوص والأمير بكتمر بالبقية على البر الشرقي، وتقَدَّمَهم جريس نائب ملك النوبة ومعه أولاد الكنز؛ ليؤمِّنَ أهل البلاد ويجهِّز الإقامات، فكان العسكرُ إذا قَدِمَ إلى بلد خرج إليه المشايخ والأعيان، وقَبَّلوا الأرض وأخذوا الأمان وعادوا، وذلك من بلد الدو إلى جزائر ميكائيل، وهي ولاية جريس، وأما ما عدا ذلك من البلاد التي لم يكن لجريس عليها ولاية، من جزائر ميكائيل إلى دنقلة، فإنَّ أهلَها جلوا عنها طاعة لمتمَلِّك النوبة، فنهبها العسكرُ وقَتَلوا من وجدوه بها، ورَعَوا الزروع وخرَّبوا السواقي إلى أن وصلوا مدينةَ دنقلة، فوجدوا المَلِكَ قد أخلاها حتى لم يبقى بها سوى شيخ وعجوز، فأخبر أنَّ المَلِكَ نزل بجزيرةٍ في بحر النيلِ بُعدُها عن دنقلة خمسة عشر يومًا، فتتبعه والي قوص، ولم يقدِرْ مركب على سلوك النيل هناك لتوعُّرِ النيل بالأحجارِ. وفي جمادى الأولى من عام 689 هـ وصل أيدمر والي قوص ممَّن معه إلى اتجاه الجزيرة التي بها سمامون ملك النوبة، فرأوا بها عدة من مراكب النوبة، فبعثوا إليه في الدخولِ في الطاعةِ وأمَّنوه فلم يقبَلْ، فأقام العسكرُ تجاهه ثلاثة أيام، فخاف سمامون من مجيءِ الحراريق والمراكبِ إليه، فانهزم إلى جهةِ الأبواب، وهي خارجةٌ عن مملكتِه، ففارقه السواكرة وهم الأمراء وفارقه الأسقُفُ والقُسوس، ومعهم الصليبُ الفِضَّة الذي كان يُحمَلُ على رأسِ الملك، وتاجُ الملك، وسألوا الأمان فأمَّنَهم أيدمر وخلَعَ على أكابِرِهم، وعادوا إلى مدينةِ دنقلة وهم جمعٌ كبير، وعند وصولهم عبر الأمير عزُّ الدين الأفرم وقبجاق إلى البر الشرقي، وأقام العسكرُ مكانه، واجتمع الأمراءُ بدنقلة، ولبس العسكرُ آلةَ الحرب وطلبوا من الجانبينِ، وزُيِّنَت الحراريق في البحر، ولعب الزرَّاقون بالنِّفاط، ومدَّ الأمراء السماط في كنيسةِ أسوس أكبَرِ كنائس دنقلة وأكلوا، ثم ملَّكوا الرجلَ الذي بعثه السلطانُ قلاوون وألبسوه التاجَ، وحلفوا وسائِرَ الأكابرِ، وعينوا طائفةً من العسكر تقيمُ عندهم وعليها بيبرس العزي مملوكُ الأمير عزِّ الدين، وعاد العسكرُ إلى أسوان بعدما غاب عنها ستة أشهر، وساروا إلى القاهرةِ في آخر جمادى الأولى بغنائِمَ كثيرة، وأما سمامون فإنَّه عاد إلى دنقلة مختفيًا، وصار بطريقِ باب كلِّ واحد من السواكرة ويستدعيه، فإذا خرج ورآه قَبَّلَ له الأرضَ وحلف له، فما طلع الفجرُ حتى ركِبَ معه سائرُ عَسكرِه، وزحف سمامون بعسكره على دار الملك، وأخرج بيبرس العزي ومَن معه إلى قوص، وقَبَض على الذي تمَلَّك مَوضِعَه وعرَّاه من ثيابه، وألبسه جلدَ ثورٍ كما ذُبِحَ ولَفَّها عليه، ثمَّ أقامه مع خشبةٍ وتركه حتى مات، وقُتِلَ جريس أيضًا، وكتب سمامون إلى السلطانِ يسأله العفو، وأنَّه يقوم بالمقرَّر وزيادة، وبعث رقيقًا وغيره تقدمةً فقَبِلَ منه، وأقرَّه السلطانُ بعد ذلك بالنوبةِ."},{"id":2783,"title":"نهاية حكم الغوريين في الهند .","date":["العام الهجري :689","العام الميلادي :1290"],"text":"كانت أسرةُ بلبن الغورية تحكُمُ تلك المناطق في الهندِ دلهي وغيرَها، وكان آخِرُ ملوكهم هو معزُّ الدين كيقباد الذي مرِضَ مرضًا شديدًا عجز الأطباءُ عن إيجاد علاجِه، فيبس أحَدُ شِقَّيه، فخرج عليه نائبُه جلال الدين فيروز الخلجي وأعلن خلعَ الطاعةِ في ظاهر المدينةِ وانضَمَّ له الأمراءُ ودخل الخلجي دلهي وقتل كيقباد بعد أن بَقِيَ في حكمه ثلاث سنوات وبضعة أشهر، وبموتِه تنتهي حكومةُ أسرة بلبان وتبدأ دولة الخلجيين، وأوَّلُ ملوكها هو جلال الدين فيروز."},{"id":2784,"title":"أهل عكا ينقضون العهد .","date":["العام الهجري :689","العام الميلادي :1290"],"text":"ثار أهلُ عكَّا بتجَّار المسلمين وقتلوهم، فغَضِبَ السلطان قلاوون وكتب إلى البلاد الشاميَّة بعَمَلِ مجانيق وتجهيزِ زردخاناة- خزنة الأسلحة- لحصارِ عكا، وذلك أنَّ الظاهِرَ بيبرس كان قد هادَنَهم، فصاروا يحمِلونَ إليه هديَّتَهم في كلِّ سَنةٍ واستمَرُّوا في حَملِها إلى الملك المنصور قلاوون، إلَّا أنهم كثُرَ طَمَعُهم وفسادُهم وقَطعُهم الطريقَ على التجار، فأخرج لهم السلطانُ قلاوون الأميرَ شمس الدين سنقر المساح على عسكر، ونزلوا اللجونَ على العادة في كلِّ سنة، فإذا بفرسانٍ مِن الفرنج بعكا قد خرَجَت فحاربوهم، واستمَرَّت الحربُ بينهم وبين أهل عكا مُدَّة أيام، وكُتِبَ إلى السلطان بذلك، فأخذ في الاستعدادِ لحَربِهم، فشرع الأميرُ شمس الدين سنقر الأعسر في عمل ذلك، وقرَّرَ على ضياع المرج وغوطة دمشق مالًا على كلِّ رجلٍ ما بين ألفي درهمٍ إلى خمسمائة درهم، وجبى أيضًا من ضِياعِ بعلبك والبقاع، وسار إلى وادٍ بين جبال عكا وبعلبك لقطع أخشابِ المجانيق، فسقط عليه ثلجٌ عظيمٌ كاد أن يُهلِكَه، فركب وساق وتَرَك أثقالَه وخيامه لينجوَ بنفسه، فطَمَّها الثلجُ تحته إلى زَمَنِ الصيف، فتَلِفَ أكثَرُها."},{"id":2785,"title":"غزو بلاد الصعيد .","date":["العام الهجري :689","الشهر القمري : محرم","العام الميلادي :1290"],"text":"سار الأميرُ طرنطاي النائبُ إلى بلاد الصعيد ومعه عسكرٌ كبيرٌ، فوصل إلى طوخ تجاهَ قوص، وقَتَل جماعةً من العربان، وحرق كثيرًا منهم بالنار، وأخذ خيولًا كثيرة وسلاحًا ورهائنَ مِن أكابرهم، وعاد بمائة ألف رأسٍ مِن الغنم، وألفٍ ومائتي فرس، وألف جمل، وسلاحٍ لا يقع عليه حصرٌ."},{"id":2786,"title":"غزو بلاد النوبة .","date":["العام الهجري :689","الشهر القمري : جمادى الأولى","العام الميلادي :1290"],"text":"وصل والي قوص ممَّن معه إلى اتجاه الجزيرة التي بها عامون ملك النوبة، فرأوا بها عدة من مراكب النوبة، فبعثوا إليه في الدخولِ في الطاعةِ وأمَّنوه فلم يقبَلْ، فأقام العسكرُ تجاهه ثلاثة أيام، فخاف عامون من مجيءِ الحراريق والمراكبِ إليه، فانهزم إلى جهةِ الأبواب، وهي خارجةٌ عن مملكتِه وبينها وبين الجزيرة التي كان فيها ثلاثةُ أيام، ففارقه السواكرة وهم الأمراء وفارقه الأسقُفُ والقُسوس، ومعهم الصليبُ الفِضَّة الذي كان يُحمَلُ على رأسِ الملك، وتاجُ الملك، وسألوا الأمان فأمَّنَهم والي قوص وخلَعَ على أكابِرِهم، وعادوا إلى مدينةِ دنقلة وهم جمعٌ كبير، وعند وصولهم عبر الأمير عزُّ الدين الأفرم وقبجاق إلى البر الشرقي، وأقام العسكرُ مكانه، واجتمع الأمراءُ بدنقلة، ولبس العسكرُ آلةَ الحرب وطلبوا من الجانبينِ، وزُيِّنَت الحراريق في البحر، ولعب الزرَّاقون بالنِّفاط، ومدَّ الأمراء السماط في كنيسةِ أسوس أكبَرِ كنائس دنقلة وأكلوا، ثم ملَّكوا الرجلَ الذي بعثه السلطانُ قلاوون وألبسوه التاجَ، وحلفوا وسائِرَ الأكابرِ، وعينوا طائفةً من العسكر تقيمُ عندهم وعليها بيبرس العزي مملوكُ الأمير عزِّ الدين والي قوص، وعاد العسكرُ إلى أسوان بعدما غاب عنها ستة أشهر، وساروا إلى القاهرةِ في آخر جمادى الأولى بغنائِمَ كثيرة، وأما عامون فإنَّه عاد بعد رجوع العسكرِ إلى دنقلة مختفيًا، وصار بطريقِ باب كلِّ واحد من السواكرة ويستدعيه، فإذا خرج ورآه قَبَّلَ له الأرضَ وحلف له، فما طلع الفجرُ حتى ركِبَ معه سائرُ عَسكرِه، وزحف عامون بعسكره على دار الملك، وأخرج بيبرس العزي ومَن معه إلى قوص، وقَبَض على الذي تمَلَّك مَوضِعَه وعرَّاه من ثيابه، وألبسه جلدَ ثورٍ كما ذُبِحَ بعدما قَدَّه سيورًا ولَفَّها عليه، ثمَّ أقامه مع خشبةٍ وتركه حتى مات، وقُتِلَ جريس أيضًا، وكتب عامون إلى السلطانِ يسأله العفو، وأنَّه يقوم بالبقط المقرَّر وزيادة، وبعث رقيقًا وغيره تقدمةً فقَبِلَ منه، وأقرَّه السلطانُ بعد ذلك بالنوبةِ."},{"id":2787,"title":"قيام الدولة الخلجية في الهند على أنقاض الدولة الغورية .","date":["العام الهجري :689","الشهر القمري : جمادى الآخرة","العام الميلادي :1290"],"text":"الخلجيُّونَ أصلُهم من الترك الأفغانيين، وكانوا أسرةً مُحارِبةً، ظهر أمرُها من أيام الغزنويِّينَ، ويرى بعضُ المؤرخين أنَّهم ينتَسِبونَ إلى \"قليج خان\" أحدِ أصهار \"جنكيز خان\" والذي نزل بجبال الغورِ بعد هزيمة \"خوارزم شاه\"، وحرَّف اسمه بعد ذلك إلى خلج، وعُرِفَ ورثته بالخلجيون، واندمجوا في الحياةِ في \"أفغانستان\"، واعتنقوا الإسلامَ في عهد سلاطين الدولةِ الغزنوية، وضم الجيشُ الغزنوي فرقًا منهم أسهمت في فتح الهند. وظهر أمرُهم منذ أيامِ الدولة الغورية، وازداد نفوذُهم في عهد المماليك، وتولَّوا حكمَ إقليم البنغال، ونهضوا بالوظائفِ الكبرى في الدولةِ، وبعد وفاة غياث الدين بلبن تولى حفيدُه كيقباد الحُكمَ، وكان شابًّا لاهيًا منصرفًا عن إدارة الدولة، وهو ما أطمعَ الخلجيينَ في الإطاحة بنظام الحُكمِ في دلهي، فجمعوا أمرَهم تحت قيادة زعيمِهم فيروز، ودخلوا دلهي، وأسقطوا حكمَ بيت غياث الدين بلبن، وأعلن فيروزُ نَفسَه سُلطانًا، ولقَّب نفسَه بجلال الدين، وذلك في الثاني من جمادى الآخرة 689هـ (13 من يونيو1290م) واستطاع السلطانُ جلال الدين أن يجذِبَ القلوبَ التي كانت نافرةً منه بعد اجتياحِ قُوَّاتِه مدينةَ دلهي وقَتلِها كيقباد، وقد كان شيخًا كبيرًا في السبعينَ مِن عُمُرِه، يميلُ إلى الحِلمِ والسماحة؛ فنجح في أن يتألَّف القلوبَ مِن حوله، وبلغ من سماحتِه أنَّه عفا عن بعض الثائرين عليه، وفكَّ أغلالَهم، وأجلَسَهم بمجلِسِه، وقال لهم: كنتم زملائي، وقد جعلني اللهُ ملكًا، فأنا أشكر الله على نعمته، ولا أنسى الماضي، وأنتم بوفائِكم لأميرِكم من آلِ بلبن قد قمتُم بواجِبِكم، ولا يمكِنُ أن أحاسِبَكم على هذا الوفاءِ. وقد نجح السلطانُ جلال الدين في ردِّ غارات المغول حين عاودوا هجومَهم على الهند، وأسَرَ منهم ألوفًا، وأنزلهم بضواحي دلهي, ثم خرج في سنة 694هـ لفتح الدكن، وتمكَّنَ من التغلُّبِ على إمارة ديوكر الهندية، ودخل الدكن، فكان أوَّلَ من دخلها من سلاطينِ المسلمين، وكان من إفراطِ السلطان في حُسنِ الظن بمن حوله أن استطاع ابنُ أخيه علاء الدين محمد أن يستدرِجَه إلى مقامِه في \"كره\"، بدعوى مشاهدةِ بعضِ الغنائِمِ الثمينةِ التي أتى بها من الدكن، ودَبَّرَ له مَن قتَلَه قبل أن يلتقيا في 4 من رمضان 694هـ (18 يوليو 1295م)."},{"id":2788,"title":"وفاة السلطان قلاوون وتولي ابنه خليل بعده .","date":["العام الهجري :689","الشهر القمري : ذي القعدة","العام الميلادي :1290"],"text":"هو السلطانُ المَلِكُ المنصورُ سَيفُ الدنيا والدين، أبو المعالي وأبو الفتوح قلاوون بن عبد الله التركي الصالحيُّ النجميُّ الألفي، اشتراه المَلِكُ الصالحُ نجم الدين أيوب بألفي دينار، ولهذا يقالُ له الألفي, وكان من أكابِرِ الأمراء عنده وبعدَه، كان ملكًا عظيمًا حَسَنَ الصورة مَهيبًا، عليه أبَّهةُ السلطنة ومهابة المُلك، تامَّ القامة حَسَنَ اللِّحيةِ عاليَ الهِمَّة شجاعًا وقورًا, وكان لا يحِبُّ سَفكَ الدماء، إلَّا أنه كان يحِبُّ جمع الأموال، ولَمَّا تزوَّج الملكُ السعيد بن الظاهر بابنة قلاوون غازية خاتون، عظُمَ شأنُه جِدًّا عند الظاهر، وما زال يترفَّعُ في الدولة حتى صار أتابكَ سلامش بن الظاهر، ثم عزله واستقَلَّ بالملك في سنة أربع وثمانين. فأمسَكَ قلاوون بجماعةٍ مِن أمراء ظاهرية، واستعمل مماليكَه على نيابة البلاد. كسر التتارَ سنة ثمانين، ونازل حصنَ المرقب, وفتح طرابلسَ سنة ثمان وثمانين، وعزم على فتح عكَّا وبرز إليها فعاجَلَته المنيَّةُ, ودفن بتربته بمدرسته العظيمةِ التي أنشأها بين القصرين، والتي ليس بديارِ مِصرَ ولا بالشَّامِ مِثلُها. وفيها دارُ حديث والمارستان المنصوري. وعليها أوقافٌ دارَّة كثيرة عظيمة، مات عن قريبٍ من ستين سنة، وكانت مدَّة ملكه اثنتي عشرة سنة، وقد أبقى اللهُ تعالى الملكَ في بنيه ومماليكِه وبني بنيه إلى أواخِرِ القرن الثامن الهجري, وبعد وفاته جلس ابنُه وولي العَهدَ الملِكُ الأشرف صلاح الدين خليل على تخت الملك بقلعةِ الجبل يوم الأحد سابع ذي القعدة سنة تسع وثمانين وستمائة."},{"id":2789,"title":"مناوشات بين أمير مكة وحجاج مصر .","date":["العام الهجري :689","الشهر القمري : ذي الحجة","العام الميلادي :1291"],"text":"حَجَّ بالنَّاسِ في هذه السنة من الشامِ الأمير بدر الدين بكتوت الدوباسي، وحَجَّ قاضي القضاة شهاب الدين بن الخوي، وشمسُ الدين بن السلعوس ومقَدَّم الركب الأمير عتبة، فتوهَّم منه أبو نُمي، وكان بينهما عداوةٌ، فأغلق أبوابَ مكَّةَ ومنع الناسَ مِن دخولِها، فأحرق البابَ وقتَلَ جماعةً ونهَبَ بعض الأماكِنِ، وجرت خطوبٌ فظيعة، ثم أرسلوا القاضيَ ابن الخوي ليصلح بين الفريقين، ولَمَّا استقر عند أبي نمي رحل الركوبُ وبقي هو في الحَرَمِ وَحدَه وأرسل معه أبو نمي من ألحقَه بهم سالِمًا معظَّمًا."},{"id":2790,"title":"أحوال البلاد الإسلامية مع بداية هذه السنة .","date":["العام الهجري :690","العام الميلادي :1291"],"text":"استهلَّت هذه السنةُ والخليفةُ بمصرَ الحاكمُ بأمر الله أبو العباس العباسي، وسلطانُ البلادِ المَلِكُ الأشرف صلاحُ الدين خليل بن المنصور قلاوون، ونائبُه بمصر وأعمالها بدر الدين بيدرا، ووزيرُه ابن السلعوس الصاحِبُ شمس الدين، ونائبه بالشام حسامُ الدين لاجين السلحداري المنصوري، وصاحِبُ اليمن الملِكُ المظفَّر شمس الدين يوسف بن المنصور نور الدين عمر بن علي بن رسول، وصاحِبُ مكة نجم الدين أبو نمي محمد بن إدريس بن علي بن قتادة الحسيني، وصاحبُ المدينة عز الدين جماز بن شيحة الحسيني، وصاحب الرومِ غياثُ الدين كيخسرو، وهو ابنُ ركن الدين قلج أرسلان السلجوقي، وصاحِبُ حماة تقي الدين محمود بن الملك المنصور ناصر الدين محمد بن الملك المظفر تقي الدين محمد، وسلطانُ بلاد العراق وخراسان وتلك النواحي أرغون بن أبغا بن هولاكو بن تولو بن جنيكزخان. وجلال الدين فيروز الخلجي في الهند."},{"id":2791,"title":"وفاة الملك العادل بدر الدين سلامش بن الظاهر بيبرس .","date":["العام الهجري :690","العام الميلادي :1291"],"text":"هو المَلِكُ العادِلُ بدرُ الدين سلامش بن الظاهرِ بيبرس بن عبد الله، كان قد بويع بالمُلك بعد أخيه الملِك السَّعيد، وجَعَلَ الملكُ المنصورُ قلاوونَ أتابِكَه وخطَبَ له، وضربَ السكةَ باسمه ثلاثة أشهر، ثم استقَلَّ قلاوون بالمُلكِ لصِغَرِ سِنِّ سلامش وقتَها، فلما عُزِلَ من الحكم بقي خاملًا. كان سلامش من أحسن الناسِ شَكلًا وأبهاهم منظرًا، فقد كان شابًّا مليحًا، تام الشكل، رشيق القدِّ، طويلَ الشعر، ذا حياءٍ وعقل، وقد افتتن به خلقٌ كثير، وكان رئيسًا مهيبًا وقورًا، أرسله السلطانُ قلاوون إلى أخيه الملك السعيد في الكركِ ثم أعادهم إلى القاهرةِ، ولما تملك الملكُ الأشرفُ جَهَّزه وأخاه الملك خضر وأهله إلى مدينة إسطنبول بلاد الأشكري، فمات هناك وهو قريب من عشرين سنة، وبقي أخوه نجم الدين خضر وأهلوهم بتلك الناحية، ويُذكَرُ أن الظاهر بيبرس كان قد اعتقل قلاوون لَمَّا استلم السلطنةَ وأرسله مع أمِّه إلى بلاد الأشكري، فجرى لولده سلامش وأمِّه ما فعَلَه هو بغيره!"},{"id":2792,"title":"وفاة أرغون بن أبغا بن هولاكو ملك التتار .","date":["العام الهجري :690","الشهر القمري : ربيع الأول","العام الميلادي :1291"],"text":"هو أرغونُ بن أبغا ملكُ التتار, وحاكِمُ بلاد العراق وخراسان وما حولها. كان شهمًا شجاعًا سفَّاكًا للدماء، كافرًا، على دينِ قَومِه المغول؛ لذلك قتَلَ عَمَّه المسلمَ السلطان أحمد (تكدار) بن هولاكو، فعَظُمَ في أعين المغول, فلمَّا كان في هذه السنة مات من شرابٍ شَرِبَه فيه سُمٌّ، فاتهمت المغولُ اليهودَ به, وكان وزيرُه سعد الدولة بن الصفي يهوديًّا, فقتلوا من اليهودِ خلقًا كثيرًا، ونهبوا منهم أموالًا عظيمةً جدًّا في جميع مدائن العراق، ثم اختلفوا فيمن يقيمونَه بعده، فمالت طائفةٌ إلى كيختو فأجلسوه على سريرِ المملكة، فبقي مُدَّة، قيل سنةً، وقيل أقل من ذلك، ثم قتلوه وملَّكوا بعده بيدرا، وجاء الخبَرُ بوفاة أرغون إلى الملك الأشرف وهو محاصرٌ عكَّا ففرح بذلك كثيرًا، وكانت مُدَّةُ مُلك أرغون ثماني سنين، وقد وصفه بعض مؤرخي العراق بالعَدلِ والسياسة الجيِّدة."},{"id":2793,"title":"تحرير إمارة عكا من الوجود الصليبي وهي آخر معاقلهم .","date":["العام الهجري :690","الشهر القمري : جمادى الآخرة","العام الميلادي :1291"],"text":"شرع السلطانُ الأشرفُ صلاحُ الدين خليلُ بن قلاوون في الاهتمامِ بفَتحِ عَكَّا، وبعثَ الأميرَ عِزَّ الدين أيبك الأفرم أمير جاندار إلى الشامِ لتجهيزِ أعوادِ المجانيق، فقَدِمَ دِمشقَ وجُهِّزَت أعوادُ المجانيق، وبرزت في أول ربيع الأول وتكامَلَت في الثاني عشر، وسار بها الأميرُ عَلَم الدين سنجر الدواداري أحدُ أمراء الشام، ثم فُرِّقَت على الأمراء مقَدَّمي الألوف، فتوجَّهَ كل أمير ومضافيه بما أمر بنقله منها، وخرج من القاهرةِ الأمير سيف الدين طغريل الأيغاني إلى استنفار الناسِ مِن الحصون بممالكِ الشام، فوصل المظفَّر صاحب حماة إلى دمشق في الثالث عشر بعسكره وبمجانيقِ وزردخاناه- خزانة الأسلحة- ووصل الأميرُ سيف الدين بلبان الطباخي نائبُ الفتوحات بعساكِرِ الحصون وطرابلس، وبالمجانيق والزردخاناه في الرابع عشر، وتوجَّه الأميرُ حسام الدين لاجين نائبُ الشام بالجيشِ مِن دمشق في العشرينَ مِن ربيع الأول، وسار جميعُ النواب بالعساكر إلى عكا، وكان السلطانُ الأشرف خليل توجَّه بالعساكِرِ يوم الثلاثاء ثالث ربيع الأول يريد أخْذَ عَكَّا، وسيَّرَ حريمه إلى دمشق فوصلوا إليها في سابع ربيع الآخر، وسار السلطان فنزل عكَّا في يوم الخميس ثالث ربيع الآخر، ووصلت المجانيقُ يوم ثاني وصولِه وعدَّتُها اثنان وتسعون منجنيقًا، فتكاملَ نَصبُها في أربعة أيام، وأُقيمَت الستائرُ ووقع الحصارُ، وقد أتت جمائِعُ الفرنجِ إلى عكا أرسالًا من البحر، صار بها عالمٌ كبير، فاستمَرَّ الحصارُ إلى سادس عشر جمادى الأولى، وكثُرَت النقوب بأسوارِ عَكَّا، فلما كان يومُ الجمعة السابع عشر عزم السُّلطانُ على الزحف، فرَتَّب كوساته- قطعتان من نحاس تشبهانِ الترسَ الصغيرَ يُدَقُّ بأحدها على الآخر بإيقاع مخصوص- على ثلاثمائة جمل، وأمر أن تُضرَبَ كُلُّها دفعة واحدة، وركب السلطانُ وضُرِبَت، فهال ذلك أهلَ عكا، وزحف بعساكِرِه ومن اجتمع معه قَبلَ شروق الشمس، فلم ترتفع الشمسُ حتى علت السناجِقُ- الرايات- الإسلاميَّة على أسوار عكا، وهرب الفرنجُ في البحر وهلك منهم خلقٌ كثير في الازدحام، والمسلمون يقتُلونَ ويأسِرونَ وينهَبونَ فقَتَلوا ما لا يحصى عَدُّه كثرةً، وأخذوا من النساءِ والصبيان ما يتجاوَزُ الوصفَ، وكان عند فتحها أن أقبل من الفرنجِ نحوُ عشرة آلاف في هيئةٍ مُستأمنين، ففَرَّقهم السلطان على الأمراء فقتلوهم عن آخِرِهم، وكانت مدَّةُ حصار عكا أربعة وأربعين يومًا، واستُشهِدَ من المسلمين الأميرُ علاء الدين كشتغدي الشمسي ودُفِنَ بجلجولية، وعزُّ الدين أيبك العزي نقيب العساكر، وسيفُ الدين أقمش الغتمي، وبدرُ الدين بيليك المسعودي، وشرفُ الدين قيران السكزي، وأربعةٌ من مقَدَّمي الحلقةِ، وجماعةٌ من العسكر، وفي يومِ السبت الثامن عشر وقع الهدمُ في مدينة عكا، فهُدِّمَت الأسوار والكنائسُ وغيرها وحُرِقَت، وحُمِلَ كثير من الأسرى بها إلى الحصونِ الإسلاميَّة."},{"id":2794,"title":"استرداد مدن الساحل من الصليبيين .","date":["العام الهجري :690","الشهر القمري : رجب","العام الميلادي :1291"],"text":"بعد أن منَّ الله على المسلمينَ بفتح عكا، فُتِحَت صور وحيفا وعثليث وبعض صيدا بغيرِ قِتالٍ، وفَرَّ أهلُها خوفًا على أنفُسِهم، فتسَلَّمَها الأميرُ علم الدين سنجر الشجاعي، فقَدِمَت البشائرُ بتسليم مدينة صور في التاسع عشر، وبتسليم صيدا في العشرينَ منه، وأنَّ طائفةً مِن الفرنج عصَوا في برجٍ منها، فأمر السلطانُ بهدم صور وصيدا وعثليث وحيفا، فتوجَّه الأمير شمس الدين نبا الجمقدار بن الجمقدار لهدم صور، واتفق أمرٌ عجيب، وهو أن الفرنج لَمَّا قدموا إلى صور كان بها عزُّ الدين نبا واليًا عليها من قِبَل المصريين، فباع صور للفرنجِ بمالٍ، وصار إلى دمشقَ!"},{"id":2795,"title":"وفاة الملك المظفر صاحب ماردين وقيام ابنه بعده بالملك .","date":["العام الهجري :691","العام الميلادي :1291"],"text":"هو المَلِكُ المظَفَّر قرا أرسلان بن السعيد غازي بن المنصور أرتق بن إيلغازي بن ألبي بن تمرتاش بن إيلغازي بن أرتق، صاحِبُ ماردين بعدما ملكَ ثلاثًا وثلاثين سنة، وقام بعده ولدُه شمس الدين داود ولقِّبَ بالملك السَّعيدِ."},{"id":2796,"title":"فتح الملك الأشرف قلعة الروم .","date":["العام الهجري :691","الشهر القمري : رجب","العام الميلادي :1292"],"text":"خرج الملِكُ الأشرَفُ مِن دمشق من يوم الاثنين سادس عشر جمادى الأولى، فدخل حَلَب في الثامن عشر، وخرج منها في رابعَ جمادى الآخرة يريدُ قلعةَ الروم فنزل عليها يومَ الثلاثاء ثامِنَه، ونصب عشرينَ منجنيقًا ورمى عليها، وعُمِلَت النقوبُ وعَمِلَ الأمير سنجر الشجاعي نائب دمشق سلسلةً وشَبَكَها في شراريفِ القلعة وأوثق طرفَها بالأرض، فصعد الأجنادُ فيها وقاتلوا قتالًا شديدًا، ففتح اللهُ القلعةَ يوم السبت حادي عشر رجب عَنوةً، وقَتَلَ من بها من المقاتلة، وسَبى الحريمَ والصبيان، وأخذ منها بترك الأرمن وكان بها فأُسِر، وكانت مدة حصارِها ثلاثة وثلاثين يومًا، وقد سماها السلطانُ قلعةَ المسلمين فعرفت بذلك، وحَمَل إليها زردخاناه- خزانة الأسلحة- وألفين ومائتي أسير، واستُشهِدَ عليها الأمير شرف الدين بن الخطير، فلما وردت البشائِرُ إلى دمشق بفتحِ قلعة الروم زُيِّنَت البلد ودُقَّت البشائر، ورتَّبَ السلطان الأميرَ سنجر الشجاعي نائبَ الشام لعمارة قلعة المسلمين، فعَمَر ما هدَّمَته المجانيق والنقوب، وخَرَّب رَبضَها، وعاد السلطانُ راجعًا يوم السبت الثامن عشر، فأقام بحلب إلىَ نصف شعبان، وعزل قرا سنقر عن نيابة حلَب، وولَّى عِوَضَه الأميرَ سيف الدين بلبان الطباخي المنصوري، ورتَّبَ بها الأميرَ عِزَّ الدين أيبك الموصلي شاد الدواوين، ورحل السلطان إلى دمشق، فدخلها في الثانية من يوم الثلاثاء العاشر من شعبان، وبين يديه بترك الأرمن صاحبُ قلعة الروم وعِدَّة من الأسرى."},{"id":2797,"title":"كيختو ملك التتار يهدد باجتياح بلاد الشام .","date":["العام الهجري :692","العام الميلادي :1292"],"text":"قَدِم رسُلُ كيختو ملك التتار بكتابِه يتضَمَّنُ أنه يريدُ الإقامة بحلب؛ فإنَّها مما فتحه أبوه هولاكو، وإن لم يُسمَحْ له بذلك أخَذَ بلادَ الشامِ، فأجابه السلطانُ بأنَّه قد وافق القان ما كان في نفسي، فإني كنتُ على عزمٍ مِن أخذ بغداد، وقَتْلِ رجاله، فإني أرجو أن أردَّها دارَ إسلامٍ كما كانت، وسينظُرُ أيُّنا يَسبِقُ إلى بلادِ صاحِبِه، وكتب إلى بلاد الشامِ بتجهيز الإقاماتِ وعرْضِ العساكِرِ."},{"id":2798,"title":"الملك الأشرف يقتل عددا من أمرائه .","date":["العام الهجري :692","الشهر القمري : محرم","العام الميلادي :1293"],"text":"في ليلةِ أوَّلِ المحَرَّم أخرَجَ مَن في الجُبِّ مِن الأمراء، وقد كان اعتقَلَهم قبل ذلك لأمورٍ رآها منهم، ومنهم من اعتُقِلَ قبل هذا وأُطلِقَ ثمَّ اعتُقِلَ ثانيًا، وهم سنقر الأشقر وجرمك والهاروني وبكتوت وبيبرس وطقصوا ولاجين، وأمر بخَنقِهم أمامَ السلطان، فخُنِقوا بأجمعِهم حتى ماتوا، وتولى خنقَ لاجين الأميرُ قرا سنقر، فلمَّا وضع الوتَرَ في عنقِه انقطع، فقال: \"يا خوند، مالي ذنب إلا حميي طقصوا وقد هلك، وأنا أطَلِّقُ ابنته، وكان قرا سنقر له به عناية، فتلطَّف به ولم يعجَلْ عليه، لما أراد الله من أن لاجين يقتُلُ الأشرفَ ويَملِكُ مَوضِعَه، وانتظر أن تقَعَ به شفاعة، فشفَعَ الأمير بدر الدين بيدرا في لاجين، وساعَدَه مَن حضر من الأمراء، فعفا عنه ظنًّا أنه لا يعيشُ!"},{"id":2799,"title":"عقد صلح بين الملك الأشرف وبلاد سيس .","date":["العام الهجري :692","الشهر القمري : جمادى الآخرة","العام الميلادي :1293"],"text":"ركِبَ الملِكُ الأشرف خليلُ بن قلاوون على الهجنِ في أوَّلِ جمادى الأولى ومعه جماعةٌ مِن أمرائه وخواصِّه، وسار إلى الكرك من غيرِ الدَّربِ الذي يُسلَكُ منه إلى الشام، فرَتَّب أحوالَها، وتوجَّهَ إلى دمشقَ، فقَدِمَها في تاسِعِ جمادى الآخرةِ بعد وصولِ الأميرِ بيدرا والوزيرِ بثلاثة أيام، فأمَرَ بالتجهيزِ إلى بهسنا وأخَذَها من الأرمِن أهل سيس، فقَدِمَ رسل سيس يطلبونَ العفوَ، فاتفق الحالُ معهم على تسليم بهسنا ومرعش وتل حمدون، فسار الأميرُ طوغان والي البر بدمشقَ معهم ليتسلَّما، وقدم البريدُ إلى دمشق بتسليمِها في أول رجب، فدُقَّت البشائِرُ، واستَقَرَّ الأميرُ بدر الدين بكتاش في نيابةِ بهسنا، وعُيِّن لها قاضٍ وخطيب، واستُخدِمَ لها رجالٌ وحَفَظة، وقَدِمَ الأمير طوغان ومعه رسُلُ سيس بالحمل والتقادم إلى دمشق في الثاني عشر بعد توجُّه السلطان، فتَبِعوه."},{"id":2800,"title":"وفاة الكاتب المؤرخ ابن عبد الظاهر .","date":["العام الهجري :692","الشهر القمري : رجب","العام الميلادي :1293"],"text":"هو الكاتبُ المؤرِّخُ الصاحبُ محيى الدين عبد الله بن رشيد الدين عبد الظاهر بن نشوان بن عبد الظاهر السّعدىُّ الموقَّعُ كاتب الإنشاء بالديار المصريَّة، وكان من أبرع المؤرِّخين الذين ظهروا في مطالِعِ دولة المماليك البحريَّة، وكان إلى جانب كونِه مؤرِّخًا، كاتبًا صاحِبَ قَلمٍ بليغٍ أهَّلَه لأن يحتلَّ مكانةً مرموقة في الصفِّ الأوَّل من كتَّاب العربيَّة. ولد بالقاهرة في 9 محرم 620هـ (12 من فبراير 1223م) بدأ حياته بحفظ القرآنِ مِثلَ أقرانه من طلبةِ العلم، وتردَّدَ على حلقات الفُقَهاءِ والمحدثين, وامتَدَّت ثقافته لتشمل الأدبَ والتاريخ والأخبار، وهو ما مكَّنَه من الالتحاق بديوانِ الإنشاء على عهدِ الأيوبيِّينَ، الذي كان يضُمُّ فحولَ الكتَّاب البارعين، ولم يبدأ نجم ابن عبد الظاهر في التألُّق والظهورِ إلَّا في عهد السلطان الظاهر بيبرس، حين عَهِدَ إليه بعَمَلِ شَجرةِ نَسَب للخليفة الحاكِمِ بأمر الله أحمد العباسي، الذي اختاره بيبرس خليفةً للمسلمين في محاولةٍ منه لإحياء الخلافة العباسيَّة في القاهرةِ بعد أن سقَطَت في بغداد سنة 656هـ ( 1257م)، ثم توثَّقَت صلتُه بالظاهر بيبرس حتى صار موضِعَ ثِقتِه، فعندما أرسلَ إليه الملك المغولي بركة خان يطلُبُ عَقدَ حِلفٍ مع بيبرس كتَبَ ابن عبد الظاهر صيغةَ الكِتاب، وقرأه على السلطانِ بحضور الأمراء، كما كتب تفويضَ الظاهر بيبرس بولايةِ العهدِ إلى ولَدِه الملك السعيدِ بركة خان. واحتفَظَ ابن عبد الظاهر بمكانتِه أيضًا في عهد السلطان قلاوون الذي حكم مصرَ بعد الظاهِرِ بيبرس وولَدَيه، وكتب له تفويضَ السَّلطَنة بولايةِ العَهدِ إلى ابنه علاء الدين علي، ثم لابنه الملك الأشرف خليل قلاوون. وقد أشاد ببلاغتِه معاصِروه وشهدوا له بالتقدُّم في صناعةِ الكِتابة والأدب؛ فقد وصفه القلقشندي بأنَّه وأبناءه بيتُ الفصاحة ورؤوسُ البلاغة، وقال عنه ابن تغري بردي: بأنَّه من ساداتِ الكُتَّاب ورؤسائِهم وفُضَلائِهم, وهو صاحِبُ النَّظمِ الرَّائقِ والنَّثر الفائق, ولَمَّا وضع ابن عبد الظاهر مؤلَّفاته التاريخيَّةَ ضَمَّنَها عددًا كبيرًا من الوثائق التي كتبها، وصاغ أحداثَ عَصرِه ووقائعه وصوَّرَ أبطالَه ومعاركَه، وترك ابن عبد الظاهر عددًا من المؤلَّفات التاريخيَّة والأدبيَّة وصل إلينا كثيرٌ منها مثل: الروض الزاهر في سيرة الملك الظاهر، وهذه السيرة كتبها المؤلِّفُ في حياة السلطانِ، وتشريف الأيام والعصور بسيرة السلطان الملك المنصور، وهي سيرةٌ للمنصور قلاوون، والروضة البهيَّة الزاهرة في خطط المُعِزِّية القاهرة. وقد امتدَّت الحياة بابن عبد الظاهر حتى تجاوز السبعينَ مِن عمره قضى معظمَها قريبًا من الأحداث التي شَهِدَتها مصرُ والشام فسَجَّلَها في كتبه. تُوفي في القاهرة في 4 من شهر رجب من هذه السنة, ودفن بالقرافة بتُربتِه التي أنشأها."},{"id":2801,"title":"أمطار شديدة في الشام .","date":["العام الهجري :692","الشهر القمري : رجب","العام الميلادي :1293"],"text":"وقع ببعلبكَّ أمطار وسيولٌ خارجةٌ عن الحد، ففسد من كرومِها ومزارعِها ومساكِنِها ما تزيد قيمتُه على مائةِ ألفِ دينار."},{"id":2802,"title":"واقعة النصراني الذي شتم الرسول صلى الله عليه وسلم واستجارته بعساف بن حجي .","date":["العام الهجري :693","العام الميلادي :1293"],"text":"كان هذا النَّصرانيُّ من أهل السويداء قد شَهِدَ عليه جماعةٌ أنَّه سَبَّ النبيَّ صلى الله عليه وسلم، وقد استجار هذا النصرانيُّ بعساف بن أحمد بن حجي أمير آل مري، فاجتمع شيخُ الإسلام تقي الدين ابنِ تيميَّة، والشيخ زين الدين الفارقي شيخُ دار الحديث، فدخلا على الأميرِ عزِّ الدين أيبك الحموي نائبِ السَّلطنة فكَلَّماه في أمرِه فأجابهما إلى ذلك، وأرسل ليُحضِرَه فخرجَا من عنده ومعهما خلقٌ كثيرٌ من الناس، فرأى الناسُ عسَّافًا حين قَدِمَ ومعه الرجلُ فسَبُّوه وشَتَموه، فقال عساف: هو خيرٌ منكم- يعني النصرانيَّ- فرجمَهما الناسُ بالحجارة، وأصابت عسَّافًا ووقعت خبطةٌ قويَّةٌ، فأرسل النائِبُ فطلب الشيخينِ ابنَ تيميَّةَ والفارقيَّ فضرَبَهما بينَ يديه، ورسَمَ عليهما في العذراويَّة، وقَدِمَ النصرانيُّ فأسلَمَ وعُقِدَ مجلسٌ بسَبَبِه، وأثبت بينه وبين الشهودِ عداوةً، فحُقِنَ دمُه، ثم استدعى بالشيخينِ فأرضاهما وأطلقَهما، ولحقَ النصرانيُّ بعد ذلك ببلادِ الحجاز، ثم في السنة التالية اتفق قتلُ عَسَّاف قريبًا من مدينة رسولِ اللهِ صلَّى الله عليه وسلَّم، قتَلَه ابنُ أخيه هنالك، وصَنَّف الشيخُ تقي الدين ابن تيميَّةَ بسَبَبِ هذه الواقعةِ كتابَه المشهورَ (الصارمُ المسلول على شاتِمِ الرَّسول)."},{"id":2803,"title":"اغتيال السلطان الأشرف خليل بن قلاوون .","date":["العام الهجري :693","الشهر القمري : محرم","العام الميلادي :1293"],"text":"هو السُّلطانُ المَلِكُ الأشرف صلاحُ الدين خليل بن السلطان الملك المنصور قلاوون الصالحي، جلس على تخت المُلك في ذي القعدة سنة 689، بعد موت والده، واستفتح المُلكَ بالجهاد، وسار فنازل عكَّا وافتتحها، ونظَّفَ الشامَ كُلَّه من الفرنج، ثم سار في السنة الثانية فنازل قلعةَ الروم وحاصَرَها خمسة وعشرين يومًا وافتتحها، ثم في السنة الثالثة جاءته مفاتيحُ قلعة بهسنا من غير قتالٍ إلى دمشق، ولو طالت مدَّتُه مَلَكَ العِراقَ وغيرها، فإنه كان شجاعًا مِقدامًا مَهيبًا عالي الهمَّة، يملأُ العينَ ويَرجُف القلب. وكان ضخمًا سمينًا كبيرَ الوجه مستديرَ اللحية، على صورتِه رونقُ الحُسنِ وهَيبةُ السلطنة، وكان إلى جودِه وبذلِه الأموالَ في أغراضِه المنتهى، تخافه الملوكُ في أقطارها؛ أباد جماعةً من كبار الدولة، وكان منهَمِكًا على اللذَّات، لا يعبأُ بالتحرُّزِ على نفسِه لشجاعتِه. توجه من القاهرة ثالث المحرم سنة 693 هو والوزير شمس الدين بن السلعوس وأمراءُ دولته، وفارقه وزيرُه من الطرانة إلى الإسكندرية، وعَسَف وظَلَم وصادَرَ النَّاس، ونزل السلطانُ الأشرف بأرض الحمامات للصيد، وأقام إلى يومِ السبت ثالث عشر المحرم، فلما كان العصرُ وهو بتروجة حضر نائب السلطنةِ بيدرا وجماعةٌ من الأمراء، وكان الأشرف أمره بُكرةً أن يتقَدَّم بالدهليز ليتصَيَّدَ هو ويعود عشيَّة، فاحتاطوا به وليس معه إلَّا شهاب الدين بن الأشل أميرُ شكارة، فابتدره نائبُه على مصر بدر الدين بيدرا فضربَه بالسيف فقطَعَ يَدَه، فصاح حسامُ الدين لاجين عليه، وقال: من يريد السلطنةَ تكونُ هذه ضربَتَه؟! وضربه على كَتِفِه فحله، فسقط السلطان إلى الأرض، ولم يكن معه سيفٌ، بل كان وسَطُه مشدودًا بالبند، ثم جاء سيف الدين بهادر رأس نوبة، فأدخل السيفَ من أسفله وشَقَّه إلى حلقه، وتركوه طريحًا في البريَّة، والتفُّوا على بيدرا وحَلَفوا له، وساق تحت العصايب يطلب القاهرةَ، وتسَمَّى بالملك الأوحد، وبات تلك الليلةَ، وأصبح يسيرُ، فلما ارتفع النهار إذا بطَلَبٍ كبير قد أقبل يقدُمُه زين الدين كتبغا وحسام الدين أستاذدار يطلبون بيدرا بدمِ أستاذِهم، وذلك بالطرانة."},{"id":2804,"title":"بدر الدين بيدرا يتولى السلطنة بمصر بعد قتله السلطان الأشرف .","date":["العام الهجري :693","الشهر القمري : محرم","العام الميلادي :1293"],"text":"لَمَّا قَتَل بدر الدين بيدرا السلطانَ الأشرفَ بن قلاوون عاد بمن معه من الأمراء، ونزل بالدهليزِ وجلس في دست السلطة، وقام الأمراءُ فقَبَّلوا الأرضَ بين يديه وحلفوا له، وتلقَّب بالملك الأوحد وقيل المعظَّم، وقيل المَلِك القاهر، ثمَّ قبض بيدرا على الأميرِ بيسري والأميرِ بكتمر السلاح دار أمير جاندار، وقصد قتْلَهما ثم تركهما تحت الاحتياطِ لشفاعةِ الأمراء فيهما، وركب إلى الطرانة فبات بها وقد سار الأمراءُ والمماليكُ السلطانية ومعهم الأميرُ برغلي، وهم الذين كانوا بالدهليز والوطاق، ورَكِبوا في آثار بيدرا ومَن معه يريدون القبضَ عليه، فبلغ الأميرَ كتبغا ومن معه مقتلُ السلطانِ وسَلطنة بيدرا، فلَحِقَ بمن معه الأميرُ برغلي ومن معه من الأمراء والمماليك، وجدُّوا بأجمَعِهم في طلب بيدرا ومَن معه، وساقوا في تلك الليلة إلى الطرانة وقد لحِقَ بيدرا بسيف الدين أبي بكر بن الجمقدار نائبِ أمير جاندار، والأمير صارم الدين الفخري، والأمير ركن الدين بيبرس أمير جاندار، ومعهم الزردخاناه- خزينة الأسلحة- عند المساءِ من يوم السبت الذي قُتِلَ فيه السلطان الأشرف، فعندما أدركهم تقَدَّم إليه بيبرس أمير جاندار وقال له: يا خوند، هذا الذي فعلته كان بمشورة الأمراء؟ فقال: نعم، أنا قتلتُه بمشورتهم وحضورِهم، وهاهم كلهم حاضرون، ثم شرع يعَدِّدُ مساوئَ الأشرف ومخازيَه واستهتارَه بالأمراء ومماليكِ أبيه، وإهماله لأمور المسلمين، ووزارته ابن السلعوس، ونفور الأمراء منه لمَسكِه عز الدين الأفرم، وقتل سنقر الأشقر وطقصوا وغيره، وتأميره مماليكَه، وقِلَّة دينه وشُربه الخمرَ في شهر رمضان، وفِسْقه بالمردان، ثمَّ سأل بيدرا عن الأمير كتبغا فلم يَرَه، فقيل له: هل كان عند كتبغا من هذه القضية عِلمٌ؟ قال: نعم، هو أول من أشار بها، فلما كان يوم الأحد ثاني يومٍ من قَتْلِ الأشرفِ وافى الأميرُ كتبغا في طلبٍ كبيرٍ من المماليك السلطانية عِدَّتُه نحو الألفي فارس، وجماعة من الحلقة والعسكر ومعهم الأمير حسام الدين لاجين الأستادار الطرانة وبها بيدرا يريدون قتالَه، وميز كتبغا أصحابَه بعلائِمَ حتى يُعرَفوا من جماعة بيدرا، وهم أنَّهم جعلوا مناديلَ مِن رقابِهم إلى تحت آباطِهم فأطلق بيدرا حينئذ الأميرينِ بيسري وبكتمر السلاح دار، ليكونا عونًا له فكانا عونًا عليه، ورتَّبَ كتبغا جماعةً ترمي بالنشاب، وتقَدَّمَ بمن معه وحملوا على بيدرا حملةً منكرة، وقصد الأميرُ كتبغا بيدرا، وقال: يا بيدرا أين السلطان؟ ورماه بسَهمٍ وتبعه البقيَّةُ بسهامهم، فولى بيدرا بمَن معه وكتبغا في طلبِه حتى أدركه، وقُتِلَ بيدرا بعدما قُطِعَت يدُه ثمَّ كَتِفُه كما فَعَل بالأشرف، وحُمِلَت رأسُه على رمحٍ وبُعِثَ بها إلى قلعة الجبل، فطِيفَ بها القاهرة ومصر، ووُجِدَ في جيب بيدرا ورقةٌ فيها: ما يقول السادةُ الفقهاءُ في رجلٍ يَشرَبُ الخمرَ في شَهرِ رَمَضانَ، ويَفسُق بالمردان ولا يصلِّي، فهل على قاتِلِه ذَنبٌ أو لا؟ فكُتِبَ جوابُها: يُقتَلُ ولا إثمَ على قاتِلِه، وعندما انهزم بيدرا هرب لاجين وقرا سنقر، ودخلا القاهرةَ فاختفيا، وكان الذي وصل إلى قلعة الجبل بخبر مقتل السلطان الأشرف سيف الدين سنكو الدوادار، ولَمَّا بلغ الأميرَ علم الدين سنجر الشجاعي قتلُ السلطانِ، ضَمَّ الحراريقَ والمعادي وسائِرَ المراكِبِ إلى برِّ مِصرَ والقاهرة، وأمَرَ ألا يعدى بأحدٍ من الأمراء والمماليك إلا بإذنه، موصل الأمير زين الدين كتبغا ومَن معه من الأمراء والمماليك، بعد قتل بيدرا وهزيمة أصحابه، فلم يجدوا مركبًا يعدونَ به النيل، فأشار على من معه من الأمراء وهم حسام الدين لاجين الأستادار، وركن الدين بيبرس الجاشنكير، وسيف الدين برلغي وسيف الدين طغجي، وعز الدين طقطاي، وسيف الدين قطبة، وغيرهم أن ينزلوا في برِّ الجيزة بالخيام حتى يراسلوا الأميرَ سنجر الشجاعي، فوافقوه وضربوا الخيامَ وأقاموا بها، وبعثوا إلى الشجاعي فلم يمكِّنْهم من التعدية، وما زالت الرسل بينهم وبينه حتى وقع الاتفاقُ على إقامة المَلِك الناصِرِ محمَّد بن قلاوون، فبعَث عند ذلك الحراريقَ والمراكِبَ إليهم بالجيزة، وعدوا بأجمعهم وصاروا إلى قلعة الجبل في رابع عشر المحرم."},{"id":2805,"title":"مقتل الأمراء الذين شاركوا في قتل الملك الأشرف بن قلاوون .","date":["العام الهجري :693","الشهر القمري : محرم","العام الميلادي :1293"],"text":"وقع الطَّلَبُ على الأمراء الذين كانوا مع بدر الدين بيدرا في قَتلِ السلطان الأشرف، فأوَّلُ من وُجِدَ منهم الأميرُ سيف الدين بهادر رأسُ نوبة، والأميرُ جمال الدين أقش الموصلي الحاجب، فضُرِبَت أعناقُهما وأُحرِقَت أبدانُهما في المجاير ثامِنَ يوم سلطنة الناصر، ثمَّ أخذ بعدهما سبعة أمراء: وهم حسام الدين طرنطاي الساقي، ونوغاي السلاح دار، وسيف الدين الناق الساقي السلاح دار، وسيف الدين أروس الحسامي السلاح دار، وعلاء الدين ألطبغا الجمدار، وأقسنقر الحسامي، وناصر الدين محمد بن خوجا، ثم قُبِضَ على قوش قرا السلاح دار، وذلك في العشرين من المحرم فسُجِنوا بخزانة البنود من القاهرة، وتولى بيبرس الجاشنكير عقوبتَهم ليُقِرُّوا على من كان معهم، ثم أُخرِجوا يوم الاثنين الثامن عشر، وقُطِعَت أيديهم بالساطور على قرم خشب بباب القلعة، وسُمروا على الجمال وأيديهم معلَّقة، وشقُّوا بهم- ورأس بيدرا على رمح قدامهم- القاهرةَ ومصرَ، واجتمع لرؤيتِهم من العالَم ما لا يمكِنُ حصرُه، بحيث كادت القاهرة ومصر أن تُنهَبا، ومَرُّوا بهم على أبوابِ دُورِهم، فلما جازوا على دار علاء الدين الطنبغا خرجت جواريه حاسراتٍ يَلطِمنَ، ومعهن أولادُه وغِلمانُه قد شَقُّوا الثياب وعَظُم صياحُهم، وكانت زوجتُه بأعلى الدار، فألقت نفسَها لتقع عليه فأمسَكْنْها جواريها، وهي تقولُ: ليتني فداك، وقَطَّعَت شعرَها ورمَتْه عليه فتهالك النَّاسُ من كثرةِ البكاءِ رحمة لهم، واستمَرُّوا على ذلك أيامًا: فمنهم من مات على ظهور الجمال، ومنهم من فُكَّت مساميرُه وحُمِلَ إلى أهلِه ثمَّ أُخِذَ مَرَّةً ثانية وأعيد تسميرُه فمات، هذا وجواري المَلِك الأشرف وسيال حواشيه قد لَبِسنَ الحِدادَ وتذرَّعنَ السخام، وطفن في الشوارع بالنواحات يُقِمن المأتم، فلم يُرَ بمصر أشنع من تلك الأيام، ثم أُخِذَ بعد ذلك الأمير سيف الدين قجقار الساقي فشُنِقَ بسوق الخيل، ولم يوقف لقراسنقر ولا للاجين على خبرٍ البتةَ، ثم في أواخر رمضان ظهر الأميرُ حسام الدين لاجين، فاعتذر له عند السلطانِ فقَبِلَه وخَلَع عليه وأكرَمَه، وأنه لم يكن قتَلَه باختيارِه."},{"id":2806,"title":"تولية الملك الناصر محمد بن قلاوون ملك مصر .","date":["العام الهجري :693","الشهر القمري : محرم","العام الميلادي :1293"],"text":"لَمَّا قُتِلَ المَلِكُ الأشرَفُ صلاحُ الدين خليلُ بن قلاوون بالقُربِ مِن تروجة، وعدى الأميرُ زين الدين كتبغا والأمراء، اجتمَعَ بهم الأميرُ علم الدين سنجر الشجاعي ومن كان بالقاهرةِ والقلعة من الأمراء الصالحيَّة والمنصورية، وقرَّروا سلطنةَ الناصر محمد بن قلاوون وأحضروه وعُمُرُه تسعُ سنين سوى أشهر في يومِ السبت سادس عشر المحرم وأجلَسوه على سريرِ السلطنة، ورتَّبوا الأمير زين الدين كتبغا نائب السلطنة عِوَضًا عن بيدرا، والأميرَ علم الدين سنجر الشجاعي وزيرًا ومدبرًا عِوَضًا عن ابن السلعوس، والأميرَ حُسام الدين لاجين الرومي الأستادار أطابكَ العساكر، والأميرَ رُكنَ الدين بيبرس الجاشنكير أستادارا، والأميرَ ركن الدين بيبرس الدوادار دوادارًا، وأعطِيَ إمرةَ مائة فارس وتقدمة ألف، وجعل إليه أمر ديوان الإنشاء في المكاتَباتِ والأجوبة والبريد، وأنفق في العسكرِ وحَلَفوا فصار كتبغا هو القائِمَ بجميع أمورِ الدولة، وليس للمَلِكِ الناصِرِ مِن السلطنة إلا اسمُ المَلِك من غيرِ زيادةٍ على ذلك، وسكن كتبغا بدارِ النيابة من القلعةِ، وجعل الخوانَ يُمَدُّ بين يديه."},{"id":2807,"title":"وفاة الملك الحافظ غياث الدين محمد بن الملك السعيد الأيوبي .","date":["العام الهجري :693","الشهر القمري : شعبان","العام الميلادي :1294"],"text":"هو المَلِكُ الحافِظُ غِياثُ الدين محمَّد بن الملك السعيد معين الدين بن الملك الأمجد بهرام شاه بن المعز عز الدين فروخ شاه بن شاهنشاه بن أيوب، وُلِدَ بدمشق أو ببعلبك سنة 616 وقد سَمِعَ الحديثَ وسَمِعَ البخاريَّ من الزبيدي وحدَّث به وأجاز مروياته للشيخِ شمس الدين، وكان أميرًا جليلًا متميزًا، نسَخَ الكثيرَ بخطه المنسوب وخَلَّف عدة أولاد، وكان يحبُّ العُلَماء والفقراء. وتوفِّيَ يوم الجمعة سادس شعبان‏, ودفن عند جدِّه لأمه ابن المقدم، ظاهر باب الفراديس."},{"id":2808,"title":"وباء عام ومجاعة هائلة في مصر .","date":["العام الهجري :694","العام الميلادي :1294"],"text":"وقع بديار مصرَ كُلِّها وباءٌ عظيم في القاهرة ومصر، وتزايد حتى كان يموتُ فيهما كل يومٍ ألوف، ويبقي الميِّتُ مطروحًا في الأزقة والشوارع ملقًى في الممرات والقوارع اليوم واليومينِ لا يوجد من يدفِنُه، لاشتغال الأصحَّاء بأمواتِهم، والسُّقَماء بأمراضهم، وقصُرَ مَدُّ النيل فتزايد الغلاءُ واشتَدَّ البلاء، وأجدَبَت بلاد بُرقة أيضًا، وعمَّ الغلاء والقحط ممالِكَ المشرق والمغرب والحجاز، وتزايد موتُ النَّاسِ حتى بلغت عدة من أطلق من الديوان في شهرِ ذي الحجة سبعة عشر ألفًا وخمسمائة، سوى الغُرَباء والفُقَراء وهم أضعاف ذلك، وأكلَ النَّاسُ مِن شدة الجوع جثَثَ الموتى والكلاب والقطاط والحمير، وأكل بعضُهم لحم بعضٍ! وأناف عدَدُ مَن عُرِفَ بموته في كلِّ يوم ألف نفس، سوى من لم يثبُت اسمُه في الديوان، فلما اشتَدَّ الأمرُ فَرَّق السلطانُ الفقراءَ على أربابِ الأموالِ بحَسَبِ حالِهم."},{"id":2809,"title":"دخول أكثر التتار الإسلام بسبب إسلام ملكهم قازان بن أرغون .","date":["العام الهجري :694","العام الميلادي :1294"],"text":"ورد الخبَرُ بأن كيختو بن أبغا بن هولاكو، الذي تسلطنَ بعد أخيه أرغون في سنة تسعين، قُتِل في سنة ثلاث وتسعين، وملَك بعده ابنُ عمه بيدو، وهو ابن طرغاي بن هولاكو، فخرج عليه قازان بن أرغون بن أبغا نائبُ خراسان، وكسَرَه وأخذ المُلكَ منه، ويقال: إن قازان أسلم على يدِ الشيخ صدر الدين بن حمُّويه الجويني، وقيل: على يد نائبه الأمير توزون، ودخلَت التتار أو أكثرُهم في الإسلام، ونثر قازان الذهبَ والفضَّةَ واللؤلؤ على رؤوس النَّاسِ يوم إسلامه، وتسَمَّى بمحمود، وشهِدَ الجمعةَ والخُطبة، وخَرَّب كنائسَ كثيرةً، وضرب على النصارى الجزيةَ ورَدَّ مظالمَ كثيرةً ببغداد وغَيرِها من البلادِ."},{"id":2810,"title":"وفاة ملك اليمن المنصور وما جرى بعده من قتال .","date":["العام الهجري :694","العام الميلادي :1294"],"text":"هو المَلِكُ المظَفَّر شمس الدين أبي المظفَّر يوسف بن الملك المنصور نور الدين عمر بن علي بن رسول التركماني صاحِبُ اليمن المظفَّر صاحب اليمن. قُتِلَ أبوه وعمره ستٌّ وأربعون سنة، فقام هو بالأمر من بعده. توفِّيَ المظفَّر في شهر رمضان وكانت مُدَّةُ حُكمِه نحوَ خمسٍ وأربعين سنةً، وكانت سيرتُه جيدة، وملك بعده ابنُه الملك الأشرف ممهد الدين عمر، فنازعه أخوه المَلِك المؤيد هزبر الدين داود وجمع لقتاله، وحاصر عدن ثلاثةَ عشَرَ يومًا وملَكَها وأخذ الأموالَ بغير حق، وسار يريد تعز، فبعث إليه الأشرف جيشًا قاتله وأسَرَه وحمله إليه، فاعتَقَله."},{"id":2811,"title":"فتنة المماليك الأشرفية بمصر .","date":["العام الهجري :694","الشهر القمري : محرم","العام الميلادي :1294"],"text":"في ليلةِ الأربعاءِ حادي عشر المحرم اجتمع المماليكُ الأشرفيَّة وخرجوا إلى الاسطبلات التي تحت القلعةِ، وركبوا الخيولَ ونَهَبوا ما قَدَروا عليه، وداروا على خوشداشيتهم- زملاء المهنة- فأركبوهم ومَضَوا إلى باب سعادة من أبوابِ القاهرة فأحرَقوه، ودخلوا إلى دارِ الوزارة ليُخرِجوا مَن فيها من المماليك، فلم يوافِقوهم على ذلك فتَرَكوهم، وقَصَدوا سوق السلاح بالقاهرة، وفتَحوا الحوانيتَ وأخذوا السِّلاحَ، ومضوا إلى خزانةِ البنود وأخرَجوا من فيها من المماليك، وساروا إلى إسطبل السُّلطانِ ووقَفوا تحت القلعة، فركِبَ الأمراءُ الذين بالقلعةِ وقاتَلوهم، فلم يثبُتِ المماليكُ الأشرفيَّةُ وانهزموا وتفَرَّقوا، فقُبِضَ عليهم في القاهرة وضواحيها ولم يُفلِتْ منهم أحدٌ، فضُربت رقابُ بَعضِهم بباب القلعة، وقُطِعَت أيدي وأرجُلِ جماعةٍ منهم، وغُرِّقَ بَعضُهم، وفيهم من أُكحِلَ، وفيهم من قُطِعَت ألسِنَتُهم، ومنهم من صُلِبَ على باب زويلة، ومنهم من بَقِيَ، وفُرِّقَ بعضُهم على الأمراءِ وكانوا زيادةً على ثلاثِمائة مملوكٍ."},{"id":2812,"title":"خلع الملك الناصر محمد بن المنصور وسلطنة الملك العادل زين الدين كتبغا .","date":["العام الهجري :694","الشهر القمري : محرم","العام الميلادي :1294"],"text":"في يومِ الأربعاءِ حادي عشر المحرم خُلِعَ المَلِكُ النَّاصِرُ بن قلاوون، وكانت أيَّامُه سَنةً واحدةً تَنقُصُ ثلاثةَ أيام، لم يكن له فيها أمرٌ ولا نهيٌ، بل كل ذلك بيَدِ السلطان الملك العادل زين الدين كتبغا المنصوري الذي كان في مُدَّة سلطنة الملك الناصِرِ هو القائِمَ بجميع أمور الدولة، وليس للناصرِ معه تصرفٌ البتة، ثمَّ إنه أخذ في أسباب السُّلطةِ بعد قتل الشجاعيِّ المنافِسِ الأوَّل لكتبغا، ولَمَّا دخل المحرم انقطع في دارِ النيابة وأظهَرَ أنَّه ضعيفُ البَدَنِ، وباطِنُ أمْرِه أنه يريد أن يقَرِّرَ أمورَه في السَّلطنةِ، فخرج إليه الناصِرُ وعاده، فلما كانت فتنةُ المماليك، جلس في صباحِ تلك الليلة بدارِ النيابة وجمَعَ الأمراء وقال لهم: قد انخرق ناموسُ المملكة، والحُرمةُ لا تتِمُّ بسَلطنةِ الناصِرِ لِصِغَرِ سِنِّه، فاتَّفَقوا على خَلعِه وإقامة كتبغا مكانه، وحلفُوا له على ذلك، وقَدِمَ إليه فرس النوبة بالرَّقَبة الملوكية، ورَكِبَ من دار النيابة قبل أذان العصرِ من يوم الأربعاء حادي عشر المحرم، ودخل من باب القلعةِ إلى دار السلطانيَّة، والأمراء مشاةٌ بين يديه حتى جلس على التخت بأبَّهة الملك، وتلقَّب بالملك العادل، ويُذكَرُ أن أصله من التتار من سَبْيِ وَقعةِ حمص الأولى التي كانت في سنة 659 أيَّام الملك الظاهرِ بيبرس بعد وقعة عين جالوت، وكان من الغويرانية، وهم طائفةٌ من التَّتر, فأخذه الملكُ المنصورُ قلاوون وأدَّبَه ثم أعتَقَه، وجعَلَه من جملة مماليكِه، ورقَّاه حتى صار من أكابِرِ أمرائه. وهو من خيارِ الأمراء وأجوَدِهم سيرةً ومَعدلةً، وقصدًا في نصرةِ الإسلامِ."},{"id":2813,"title":"وفاة السلطان جلال الدين سلطان الدولة الخلجية بالهند .","date":["العام الهجري :694","الشهر القمري : رمضان","العام الميلادي :1295"],"text":"هو السُّلطانُ جلالُ الدينِ فيروز شاه، مؤسِّسُ الدولة الخلجية بالهند, وكان نائبًا للمماليك, وقد وسَّعت هذه الدولةُ حُكمَ المسلمين في الهند فشَمِلت الدكنَ والبنغال وجيتور والكجرات، وقد تولى حكم الدولة علاء الدين الخلجي بعد وفاة جلال الدين. وقد زحف علاء الدين بجيشه إلى دلهي، حين جمعت زوجة جلال الدين أنصارَ زوجها، ونادت بابنِها ركن الدين إبراهيم سلطانًا خلفًا لأبيه، لكنَّ علاء الدين هاجمَ دلهي، وأجبر ركن الدين على الفرارِ إلى الملتان، ونصَّب نفسَه على عرش الهند في دلهي سنة 695 هـ (1295م)."},{"id":2814,"title":"توسع حكم المسلمين في الدولة الخلجية الهند .","date":["العام الهجري :694","الشهر القمري : شوال","العام الميلادي :1295"],"text":"لما استقرَّت الأمور لعلاء الدين في الدولة الخلجية بالهند بدأ يتَّجِهُ لشؤون الدولة الحربيَّة، ويعنى بالنواحي الاجتماعيَّة، وكان سلطانًا قويًّا طموحًا، نجح في دفع الخطر المغوليِّ عن بلاده، وقاد جنده في فتوحات متَّصلة، حتى أظلَّت راية الإسلام شبهَ القارة الهندية كلَّها لأول مرة في التاريخ. ولكي يدفَعَ هجمات المغول أقام سلسلةً من الحصون على حدوده الغربية، وزوَّدها بالجند والسلاح، ولكنَّ ذلك لم يحُلْ دون هجمات المغول على الهند، فتوالت حملاتُهم على الرغم مما كان يتكبَّدونه من خسائر على أيدي علاء الدين وقادته، مثلما حدث في سنة 698هـ ( 1298م) حين سار سلطانُ المغول قتلق خواجه على رأس قوات كثيفة، فتصَدَّى لها علاءُ الدين وقائداه ظفرخان وألج خان، وأنزلوا بالمغول هزيمةً قاصمة، لكنَّها لم تمنَعْهم من موالاةِ الهجوم مراتٍ أخرى حتى تمكَّن القائدُ غازي ملك تغلق من القضاء على خطر المغول تمامًا. وفي الوقت الذي كان فيه علاء الدين مشغولًا بالقضاء على هجمات المغول كان يعِدُّ الجيوشَ لاستكمال فتح الهند، فأرسل في سنة 699هـ (1299م) قائديه ألنخان ونصرت خان لفتح حصن رنتنبهور أعظَمِ حصونِ إقليم الراجبوتانا، فنجحا في مهمتهما بعد حروب دامية، ودخل الإقليمُ في طاعة علاء الدين الخلجي، ثم فتح إمارة موار، وكانت أمنَعَ إمارات الراجبوتانا بقلعتها الحصينة القائمةِ على قِمَّةِ جَبَلٍ منحوتةٍ في الصخر، ثم استولى على ملوة وأوجين ودهري نجري، ولم يكد يأتي عام 706 هـ (1306م) حتى كان علاء الدين الخلجي قد فتح الهنستان كلَّها من البنغال إلى البنجاب. وواصل علاء الدين فتوحاتِه، فأرسل قائدَه الحبشيَّ كافور، فاخترق أقاليمَ ملوة والكجرات، ثم أردف ذلك بجيش آخر يقوده أدلوغ خان، واستولى الجيشان على ديوكر، وتوالت انتصارات علاء الدين حتى تمكن من فتح الجنوب الهندي كلِّه."},{"id":2815,"title":"المجاعة والقحط ينتشران في مصر والشام والحجاز .","date":["العام الهجري :695","العام الميلادي :1295"],"text":"استمَرَّ الحالُ على الغلاء في الأسعار بشكلٍ فاحشٍ جِدًّا وهلك معظَمُ الدوابِّ لعَدَمِ العَلَفِ، حتى لم توجَدْ دابة للكِراءِ، وهلكت الكلاب والقِطَطُ من الجوع، وانكشف حالُ كثيرٍ مِن الناس، وشَحَّت الأنفسُ حتى صار أكابِرُ الأمراء يمنعونَ مَن يدخُلُ عليهم من الأعيانِ عند مَدِّ أسمِطَتِهم، وكثُرَ تعزير محتَسِب القاهرة ومِصر لبيَّاعي لحوم الكلاب والمَيتات، ثمَّ تفاقم الأمر فأكل الناسُ الميتةَ مِن الكلابِ والمواشي وبني آدم، وأكل النِّساءُ أولادَهنَّ الموتى، ثم إن الأسعارَ انحَلَّت في شهرِ رَجَب ثم في شوال تزايد السِّعرُ وساءت ظنونُ الناس، وكثُرَ الشحُّ وضاقت الأرزاق ووَقَفَت الأحوال، واشتَدَّ البكاء وعَظُمَ ضجيجُ النَّاسِ في الأسواق من شِدَّةِ الغلاء، وتزايد الوباءُ بحيث كان يخرجُ مِن كل باب من أبواب القاهرةِ في كل يوم ما يزيدُ على سبعمائة ميت، ويُغَسَّل في الميضأة من الغرباءِ الطُّرَحاء في كلِّ يَومٍ نحوُ المائة والخمسين ميتًا، ولا يكاد يوجد باب أحدٍ من المستورين بالقاهرة ومصر إلَّا ويصبِحُ على بابه عِدَّةُ أمواتٍ قد طُرِحوا حتى يكَفِّنَهم، فيَشتَغِلَ نهارَه، ثم تزايد الأمر فصارت الأمواتُ تُدفَنُ بغير غسل ولا كفَنٍ، فإنه يدفَنُ الواحد في ثوبٍ ثم ساعة ما يوضع في حُفرتِه يؤخَذُ ثَوبُه حتى يُلبَسَ لميت آخرَ، فيكَفَّنُ في الثوب الواحد عدةُ أمواتٍ!! وعجز الناس عن مواراة الأموات في القبور لكثرتِهم وقِلَّة من يحفرُ لهم، فعملت حفائِرُ كِبارٌ ألقِيَت فيها الأمواتُ من الرجال والنساء والصبيان حتى تمتلئ الحفرةُ، ثم تطَمُّ بالترابِ، وانتُدِبَ أناسٌ لحَملِ الأموات ورَمْيهم في الحفر، فكانوا يأخذونَ عن كلِّ مَيتٍ نِصفَ درهم، فيحمِلُه الواحد منهم ويلقيه إمَّا في حفرة أو في النيلِ إن كان قريبًا منه، وصارت الولاةُ بالقاهرة ومصر تحمل الأموات في شباك على الجمال، ويعلِّقونَ الميِّتَ بيديه ورجليه من الجانبين، ويُرمى في الحفر بالكيمانِ مِن غير غُسلٍ ولا كفنٍ! ورُمِيَ كثيرٌ من الأموات في الآبار حتى تُملأَ ثمَّ تُردَم، ومات كثير من الناس بأطرافِ البلاد فبَقِيَ على الطرقات حتى أكلَته الكلابُ، وأكل كثيرًا منها بنو آدم أيضًا، وحُصِرَ في شَهرٍ واحد من هذه السنة عِدَّةُ مَن مات ممَّن قُدِرَ على معرفته، فبَلَغَت العدَّةُ مائة ألفٍ وسبعةً وعشرين ألف إنسان، وعَظُم الموتانُ في أعمال مصر كلِّها حتى خلت القرى، وتأخَّر المطرُ ببلاد الشام حتى دخل فصلُ الشتاء ليلة الخميسِ سادس صفر وهو سادس عشر ديسمبر ولم يقَعِ المطر، فتزايدت الأسعارُ في سائر بلاد الشام، وجَفَّت المياه، فكانت الدابةُ تُسقى بدرهمٍ شَربةً واحدةً، ويشرَبُ الرجُلُ برُبعِ دِرهمٍ شَربةً واحدة، ولم يبق عُشبٌ ولا مرعى، واشتد الغلاءُ بالحِجازِ!!"},{"id":2816,"title":"وفاة الأمير عمر الحفصي صاحب تونس وتولي أبي عصيدة بعده .","date":["العام الهجري :695","العام الميلادي :1295"],"text":"هو الأميرُ أبو حفص عمر بن يحيى بن عبد الواحد بن أبي حفص ملك تونس. لمَّا استقر لأبي حفص المُلك بتونس بعد قتله أحمد بن مرزوق بن أبي عمار الذي ادَّعى أنه الفضل بن أمير المؤمنين الواثقِ بالله يحي بن محمد بن أبي زكريا. تلقَّب أبو حفص بالمستنصِر بالله أمير المؤمنين، وهو المستنصِرُ الثاني، ولما استقَرَّ في المملكة سار ابنُ أخيه يحيى بن إبراهيم بن أبي زكريا الذي سَلِمَ من المعركة إلى بجاية، وملَكَها وتلقَّب بالمنتخب لإحياءِ دين الله، أمير المؤمنين، واستمَرَّ المستنصر الثاني أبو حَفص عمرُ بن أبي زكريا في مملكتِه حتى توفي، وفي أوائِلِ المحرم سنة 695، ولما اشتَدَّ مَرَضُه بايع لابنٍ له صغيرٍ، فاجتمَعَت الفُقَهاءُ، وقالوا له: أنت صائرٌ إلى الله، وتوليةُ مثل هذا لا يحِلُّ، فأبطل بيعَتَه، وأخرج ولَدَ الواثِقِ المخلوعَ، الذي كان صغيرًا وسَلِمَ من الذبح، الملَقَّب بأبي عصيدة، وهو أبو عبد الله محمد بن يحيى بن محمد بن يحيى بن عبد الواحد، وبويع صبيحةَ مَوتِ أبي حفص عمر الملقَّب بالمستنصر, وكانت وفاة أبي حفص ليلة الجمعة رابع عِشْري ذي الحجة، وكانت مدَّةُ حُكمِه إحدى عشرة سنة وثمانية أشهر."},{"id":2817,"title":"وفاة الملك السعيد صاحب ماردين وتولي أخيه بعده .","date":["العام الهجري :695","العام الميلادي :1295"],"text":"هو المَلِكُ السعيدُ شمس الدين إيلغازي بن الملك المظفر فخر الدين قرا أرسلان بن الملك السعيد صاحِبُ ماردين الأرتقي، ودُفِنَ بتربة جده أرتق، وتولى بعده سلطنةَ ماردين أخوه الملك المنصور نجم الدين غازي، وكانت مُدَّةُ مَملكةِ الملك السعيد هذا على ماردين دونَ الثلاث سنين."},{"id":2818,"title":"قدوم كثير من أسر المغول إلى مصر والشام .","date":["العام الهجري :695","الشهر القمري : ربيع الآخر","العام الميلادي :1296"],"text":"قدم البريدُ بوصول طائفةِ الأويراتية من التتار ومُقَدَّمُهم طرغاي زوجُ بنت هولاكو، وإنَّهم نحو الثمانية عشر ألف بيت، وقد فَرُّوا من غازان ملك التتار وعبَروا الفراتَ يريدون الشام، فكتب إلى نائب الشام أن يبعَثَ إليهم الأمير علم الدين سنجر الدواداري إلى الرَّحبةِ لِيلقاهم، فخرجَ من دمشق، ثم توجَّه بعده الأميرُ سنقر الأعسر شاد الدواوين بدمشق، ووصلت أعيانُ الأويراتيَّة صُحبة سنقر الأعسر في الثالث عشر من صفر، وكانت عِدَّتُهم مائة وثلاثة عشَرَ رجُلًا، ومقَدَّمُهم طرغاي، ومن أكابِرِهم الوص وككباي، فتلقاهم النائبُ والأمراء واحتفل لقدومِهم احتفالًا زائدًا، ثم سار بهم الأميرُ قراسنقر إلى القاهرةِ يوم الاثنين سابعَ ربيع الآخر، فلما وصلوا بالغَ السلطان في إكرامِهم والإحسانِ إليهم، وأمر عدَّةً منهم، وبقُوا على كفرهم، ودخل شهرُ رمضان فلم يَصُمْ منهم أحد، وصاروا يأكلونَ الخيلَ مِن غيرِ ذَبحِها، بل يربط الفَرَسُ ويُضرَبُ على وجهِه حتى يموتَ فيُؤكَلَ، فأنِفَ الأمراء من جلوسِهم معهم بباب القلَّة في الخدمة، وعَظُم على الناس إكرامُهم، وتزايد بعضُهم في السلطان، وانطلقت الألسنةُ بذَمِّه حتى أوجب ذلك خلعَ السلطان العادل كتبغا فيما بعدُ، وأما بقيَّةُ الأويراتية فإنه كتب إلى سنجر الدواداري أن ينزِلَهم ببلاد الساحل، فمَرَّ بهم على مرج دمشق، وأخرجت الأسواقُ إليهم فنُصِبَت بالمرج وبمنزلة الصنمين وفي الكسوة، ولم يمكِنْ أحدًا من الأويرايتة أن يدخُلَ مدينة دمشق، وأُنزلوا من أراضي عثليث ممتَدِّين في بلاد الساحل، وأقام الأميرُ سنجر عندهم إلى أن حضر السلطانُ كتبغا إلى الشام، وقد هلك منهم عالم كبير، وأخذ الأمراء أولادهم الشباب للخدمة، وكثرت الرغبةُ فيهم لجمالِهم، وتزوَّج الناسُ ببناتهم، وتنافسَ الأمراءُ والأجناد وغيرهم في صبيانِهم وبناتهم، ثم انغمس من بَقِيَ منهم في العساكِرِ، فتفَرَّقوا في الممالك، ودخلوا في الإسلامِ واختلطوا بأهل البلاد، ويُذكَرُ أن أصل السلطان كتبغا هو من التتار كان مملوكًا مغوليًّا ثم علا شأنُه حتى تمَلَّك مِصرَ؛ فلذلك قَدِمَت الأسَرُ المغوليَّةُ إليه."},{"id":2819,"title":"وفاة زين الدين أبي البركات بن المنجى شيخ الحنابلة .","date":["العام الهجري :695","الشهر القمري : شعبان","العام الميلادي :1296"],"text":"هو الإمامُ العلَّامة، مفتي المسلمين، أبو البركات زين الدين المنجي بن عثمان بن أسعد بن المنجي بن بركات بن المؤمل، التنوخي، المعرِّي الأصل، الدمشقي، شيخُ الحنابلة. ولد سنة 631. سمع الحديث وتفقَّهَ فبرع في فنون من العلمِ كثيرةٍ مِن الأصول والفروع والعربيَّة والتفسير وغير ذلك، وانتهت إليه رياسة المذهب، وصنَّف في الأصول وشرَحَ المُقنِعَ، وله تعاليقُ في التفسير, فدرَّس وأفتى وصنَّف, وتفقَّه عليه: ابن الفخر، وابن أبي الفتح، وابن تيمية، وجماعة من الأئمة. وكان قد جمع له بين حُسنِ السَّمت والديانة والعِلمِ والوجاهة وصِحَّة الذهن والمناظرة, وطولِ النفس في البحث، وله مُلكٌ وثَروةٌ وحُرمةٌ وافرةٌ, وكان له في الجامِعِ حلقة للإشغالِ والفتوى نحو ثلاثين سنة متبَرِّعًا لا يتناوَلُ على ذلك أجرًا. وكانت له أوراد، منها صومُ الاثنين والخميس، والذِّكرُ من حين يصلِّي الصبحَ إلى أن يصلي الضُّحى. وله مع الصلوات تطوع كثير. ويصلي الضحى ويطيلُها جِدًّا. وكان له في آخِرِ الليل تهجدٌ كثيرٌ وتيقُّظٌ وذِكرٌ. وكان له إيثارٌ كبير؛ يفطِّرُ الفقراء عنده في بعضِ الليالي، وفي شهر رمضانَ كُلِّه. وكان مع ذلك حسَنَ الأخلاقِ، لطيفًا مع المشتغلين، مليحَ المجالسة. قال الذهبي: \" أجاز لي مرويَّاتِه سنة سبع وسبعين، وقصدته لأسمعَ منه فقال لي: تعالَ وقتًا آخر. فاشتغلت ولم يقَدَّر لي السماعُ منه. وكان مليحَ الشكل، حسَنَ البِزَّة، كثيرَ التطهُّر والنظافة. وكان غالِبَ أوقاته في الجامع وفي بيت المأذنةِ\". توفي يوم الخميس رابع شعبان، وتوفيت معه زوجتُه أم محمد ست أبيها بنت صدر الدين الخجندي، وصُلِّيَ عليهما بعد الجمعة بجامع دمشقَ وحُمِلا جميعًا إلى سفح قاسيون شمال الجامع المظفري تحت الروضة، فدفنا في تربةٍ واحدة رحمهما الله تعالى، وهو والد رئيسِ القضاة علاء الدين، وكان شيخ المسماريَّة ثم وليها بعده ولداه شرف الدين وعلاء الدين، وكان شيخَ الحنبليَّة فدَرَّس بها بعده الشيخ تقي الدين ابنُ تيمية."},{"id":2820,"title":"خلع الملك كتبغا وتولي حسام لاجين ملك مصر .","date":["العام الهجري :696","الشهر القمري : محرم","العام الميلادي :1296"],"text":"رحل السلطانُ كتبغا من دمشقَ بعساكِرِه يريدُ القاهرةَ، وقد توغَّرَت صدور الأمراء وتواعَدوا على الفتك به، فسار إلى أن نزل بالعوجاء قريبًا من الرملة، وحضر الأمراءُ عنده بالدهليز، فأمر بإحضارِ الأمير بيسري فطلب طلبًا حثيثًا، فلما حضَرَ لم يقُم له السلطانُ على عادته، وأغلظَ له في الكلام ونسَبَه إلى أنه كاتب التتار، فكانت بينهما مفاوضة، ثم نهض السلطانُ، وانفضَّ الأمراء وقد حَرَّك منهم ما كان عندهم كامنًا، فاجتمعوا عند الأمير حسام لاجين النائبِ وفيهم بيسري، وسألوه عما كان من السلطانِ في حقٍّ، فقال: إنَّ مماليك السلطان كتبوا عنك كتبًا إلى التتار، وأحضروها إليه وقالوا إنَّك كتبتَها، ونيَّتُه القبضُ عليك إذا وصل إلى مصرَ، وأن يقبِضَ عليَّ أيضًا وعلى أكابر الأمراء، ويقَدِّمَ مماليكه، فأجمعوا عند ذلك على مبادرةِ السلطان، فركبوا يوم الثلاثاء سابع عشري المحرَّم وقت الظهر, وهم لاجين بيسري وقرا سنقر وقبجاق والحاج بهادر الحاجب في آخرين، واستصحبوا معهم حملَ نقارات وساقوا ملبسين إلى باب الدهليز، وحركت النقَّارات حربيًّا، فركب عدَّةٌ من العادلية واقتتلوا، فتقَدَّم تكلان العادلي فضربه الأميرُ لاجين في وجهه ضربةً أخذت منه جانبًا كبيرًا، وجرح تكلان فرسَ لاجين وقُتِلَ الأمير بدر الدين بكتوت الأزرق العادلي في خيمتِه، وقتل الأمير سيف الدين بتخاص العادلي، وقد فَرَّ إلى الدهليز فأدركوه بباب الدهليز فقتلوه، وجرحوا عدّةً من المماليك العادلية، فلم يثبت السلطانُ العادل كتبغا، وخرج من ظهر الدهليز، وركب فرسَ النوبة ببغلطاق صدر، وعبر على قنطرة العوجاء يريد دمشقَ مِن غير أن يفطِنَ به أحد، ولم يدركه سوى خمسةٍ من مماليكه، وهجم لاجينُ على الدهليز فلم يجِدِ العادل وبلغه أنَّه فَرَّ، فساق خلفه فلم يدرِكْه ورجعَ إلى الدهليز، فلما عاينَه الأمراء ترجَّلوا له ومَشَوا في ركابه حتى نزل، فكانت مدة كتبغا منذ جلس على التخت بقلعة الجبل في يوم الأربعاء حادي عشر محرم سنة 694، وإلى أن فارق الدهليز بمنزلة العوجاء في يوم الثلاثاء السابع عشر محرم من هذه السنة، سنتين وسبعة عشر يومًا، ثم أصبح السلطان الملك المنصور حسام الدين لاجين المنصوري المعروفُ بالصغيرُ هو سلطانَ مِصرَ، وملَكَها، وكان أولًا من جملة مماليك الملك المنصور علي بن الملك المعز أيبك، فلما خُلِعَ اشتراه الأمير سيف الدين قلاوون وهو أميرٌ بسبعمائة وخمسين درهمًا، من غير مالكٍ شَرعيٍّ، فلما تبيَّنَ له أنه من مماليك المنصور اشتراه مرةً ثانية وحضروا بأجمَعِهم بين يدي لاجين واتَّفَقوا على سلطنته، وشرطوا عليه أن يكون معهم كأحَدِهم، ولا ينفَرِدَ برأيٍ دونهم، ولا يبسُطَ أيدي مماليكه ولا يقَدِمَهم، وحلَّفوه على ذلك، فلما حلف قال له الأمير قبجاق المنصوري: نخشى أنَّك إذا جلستَ في منصب السلطنة تنسى هذا الذي تقَرَّرَ بيننا وبينك، وتقَدِّمُ مماليكك وتخَوِّلُ مملوكَك منكوتمر علينا، فيُصيبنا منه ما أصابنا من مماليك كتبغا، وكان منكوتمر مملوك لاجين، وكان يودُّه ويؤثِرُه، وله عنده مكانةٌ متمَكِّنةٌ من قَلبِه، فحلف لاجين مرةً ثانيةً أنه لا يفعَلُ ذلك، ولا يخرجُ عما التَزَمه وشرطوه عليه، فحَلَف له الأمراءُ وأرباب الدولة، وتلَقَّبَ بالملك المنصور، وركِبَ بشعار السلطنة في يوم الثلاثاء السابع عشر محرم."},{"id":2821,"title":"السلطان المخلوع كتبغا يستبد بدمشق ثم تؤخذ منه .","date":["العام الهجري :696","الشهر القمري : صفر","العام الميلادي :1296"],"text":"بعد أن هرب السلطانُ العادِلُ كتبغا من حسام الدين لاجين وأمرائِه الذين حاولوا قتْلَه، كان قد قَدِمَ قبله إلى دمشق أميرُ شكاره وهو مجروح، ليُعلِمَ الأمير أغرلو نائب دمشق بما وقع، فوصَلَ في يوم الأربعاء آخر المحرم، فكثُرَ بدمشق القالُ والقيل، وألبس أغرلو العسكرَ السلاح ووقفوا خارجَ باب النصر، فوصل كتبغا في أربعةِ أنفس قبل الغروبِ وصَعِدَ القلعة، وحضر إليه الأمراءُ والقُضاة وجُدِّدَت له الأيمان، ثم أوقَعَ الحوطة على أموالِ لاجين، وقَدِمَ في أول صفر الأمير زين الدين غلبك العادلي بطائفةٍ مِن المماليك العادليَّة، وجلس شهابُ الدين الحنفي وزير الملك العادل كتبغا في الوزارة بالقلعةِ، ورتَّبَ الأمور وأحوال السلطنةِ، فاشتهرت بدمشقِ سلطنةُ الملك المنصور حسام الدين لاجين في اليومِ الثالث عشر من محرَّم، وأنَّ البشائِرَ دُقَّت بصفد ونابلس والكرك، فصار كتبغا مقيمًا بقلعة دمشق لا ينزِلُ منها، وبعث الأميرُ سيف الدين طقصبا الناصري في جماعةٍ لكشف الخبر، فعادوا وأخبروا بصِحَّةِ سلطنة لاجين، فأمر كتبغا جماعةً من دمشق، وأبطل عدَّةَ مكوس في يومِ الجمعة السادس عشر صفر، وكتب بذلك توقيعًا قُرِئَ بالجامع، فبعث المَلِكُ المنصور لاجين من مصرَ الأمير سنقر الأعسر وكان في خدمتِه، فوصل إلى ظاهِرِ دمشق في الرابع عشر صفر، وأقام ثلاثةَ أيام، فرَّقَ عِدَّةَ كُتُبٍ على الأمراء وغيرهم وأخذ الأجوبةَ عنها، وحلف الأمراءُ، وسار إلى قارا وكان بها عِدَّةُ أمراء مجرَّدين فحَلَّفَهم وحلَّف عدَّةً من الناس، وكتب بذلك كلِّه إلى مصر، وسار إلى لد، فأقام بها في جماعةٍ كبيرة لحفظ البلاد، ولم يعلَمْ كتبغا بشيءٍ من ذلك، وكان قد وصل الأميرُ سيف الدين كجكن وعِدَّةٌ من الأمراء كانوا مجرَّدينَ بالرَّحبة، فلم يدخلوا دمشق، ونزلوا بميدان الحصا قريبًا من مسجد القدم، فأعلنوا باسم السلطان الملك المنصور حسام الدين لاجين، وراسلوا الأمراءَ بدمشق فخرجوا إليهم طائفةً بعد طائفة، وانحَلَّ أمر كتبغا، فتدارك نفسَه وقال للأمراء: السلطانُ الملك المنصورُ لاجين خوشداشي- زميل مهنتي- وأنا في خِدمتِه وطاعتِه، وأنا أكونُ في بعض القاعات بالقلعةِ إلى أن يكاتِبَ السُّلطانَ ويَرِدَ جوابُه بما يقتضيه في أمري فأدخله الأميرُ جاغان الحسامي مكانًا من القلعة، واجتمع الأمراءُ بباب الميدان، وحَلَفوا للملك المنصور وكتبوا إليه بذلك، وحفظ جاغان القلعةَ ورَتَّبَ بها من يحفَظُ كتبغا، وغُلِّقَت أبواب دمشق كلُّها إلا باب النصر، ورَكِبَ العسكر بالسلاح ظاهِرَ دمشق، وأحاط جماعةٌ بالقلعةِ خَوفًا من خروج كتبغا وتحيُّزه في جهةٍ أخرى، وكثُرَ كلام الناس واختلفت أقوالُهم، وعظم اجتماعُهم بظاهر دمشق حتى إنَّه سقط في الخندقِ جماعةٌ لشدة الزحام فيما بين باب النصرِ وباب القلعة، فمات نحوُ العشرة، واستمر الحالُ على هذا ذلك اليوم، ثم دُقَّت البشائر بعد العصر على القلعةِ، وأعلن بالدعاء للملك المنصور لاجين، ودُعِيَ له على المآذِنِ في ليلة الأحد، وضُرِبَت البشائر على أبواب الأمراء، وفُتِحَت الأبواب في يوم الأحد، وحضر الأمراءُ والقضاة بدار السعادة وحلف الأمراء بحضور الأمير أغرلو نائب الشام، وحلف هو وأظهر السرور، وركب أغرلو والأمير جاغان البريد إلى مصر، وبلغ ذلك الأمير سنقر الأعسر بلد، فنهض إلى دمشق ودخلها يوم الخميس التاسِعَ عشر، وقد تلقاه الناس وأشعلوا له الشموع، وأتاه الأعيان، ونودي من له مَظلمةٌ فعليه بباب الأمير شمس الدين سنقر الأعسر، وفي يوم الجمعةِ أوَّل شهر ربيع الأول خُطِبَ بدمشق للملك المنصور، فلما كان يومُ الجمعة ثامنه: وصل الأميرُ حسام الدين الأستادار بعسكر مصر ليحلِّفَ الأمراء، فحَلَفوا بدار السعادة في يوم السبت تاسِعَه، وقرئ عليهم كتابُ الملك المنصور باستقراره في المُلك وجُلوسِه على تخت الملك بقلعة الجبل، واجتماعِ الكلمة عليه وركوبه بالتشاريفِ الخليفيَّة والتقليد بين يديه من أمير المؤمنينَ الحاكِم بأمر الله أبي العباس أحمد."},{"id":2822,"title":"وفاة محمد بن سعيد الصنهاجي البوصيري صاحب قصيدة البردة .","date":["العام الهجري :697","العام الميلادي :1297"],"text":"شرفُ الدين أبو عبد الله محمَّدُ بن سعيد بن حماد الصنهاجي البوصيري المصري، وبوصيرُ هي بين الفيوم وبني سويف بمصرَ، وُلِدَ البوصيري ببني سويف في مصرَ سنة 608 من أسرةٍ ترجع أصولُها إلى قبيلةِ صِنهاجةَ التي كانت تسكُنُ شَمالَ أفريقية, فهو شاعِرٌ صنهاجي له شعرٌ غايةٌ في الحسن واللطافة عذب الألفاظ منسجم التركيب. تنقَّل بين القدس والمدينة ومكَّة، ثم عاد إلى مصر وعَمِلَ كاتبًا في الدولةِ ثم أصبح يعلِّمُ الصبيانَ القرآن، وكان صوفيًّا على الطريقة الشاذليَّة، اشتهر بقصيدته المشهورة بالبُردة، واسمها (الكواكِبُ الدُّرِّيَّة في مدح خير البَريَّة)، ويقال إنَّ سَبَبَ نَظمِها أنَّه مَرِضَ مَرَضًا شديدًا فرأى النبيَّ صلى الله عليه وسلم في منامه فشكا له مرضَه فألقى عليه النبيُّ صلى الله عليه وسلم البُردةَ، فقام من نومِه وقد شُفِيَ، فعَمِلَ القصيدة، ولكنَّ هذه القصيدة فيها كثيرٌ مِن الأبيات المخالِفةِ للعقيدةِ الصحيحةِ وغُلوٌّ في الثناءِ النَّبَويِّ حتى وصف النبيَّ صلى الله عليه وسلم ببعضِ أوصاف الربوبيَّة! وقد صحَّ عن النبي صلى الله عليه وسلم ما رواه الإمامُ البخاريُّ في صحيحِه: عن ابنِ عَبَّاسٍ سَمِعَ عُمَرَ رضي الله عنه يقولُ على المنبر: سمعتُ النبيَّ صَلَّى الله عليه وسلم يقولُ: ((لا تُطرُوني، كما أطرَتِ النصارى ابنَ مريمَ؛ فإنَّما أنا عبدُه، فقولوا عبدُ اللهِ ورَسولُه))."},{"id":2823,"title":"وفاة الغازي أرطغرل بك والد الغازي عثمان مؤسس الدولة العثمانية .","date":["العام الهجري :697","العام الميلادي :1297"],"text":"هو الغازي أرطغرل بك بن سليمان شاه القايوي التركماني كان مع والده سليمانَ شاه عندما انتقلَ من موطنهم الأصلي باتجاه الغربِ على أثر الاجتياحِ التتري إلى أن غَرِقَ والده سليمان في الفراتِ فرجع أخويه سنقور تكين وكون طوغدي إلى الشرق, ومكث أرطغرل في ذلك الموضِعِ يجاهِدُ الكُفَّار، ثم أرسل ابنَه صارو بالي إلى علاء الدين السلجوقي يستأذِنُه في الدخول إلى بلادِه، ويطلب منه موضعًا ينزِلُ فيه فأذِنَ له وعَيَّنَ له جبالَ طومالج وأرمنك وما بينهما، فأقبل أرطغرل مع أربعمائة خركاه- خيمة- من قومِه فتوطَّنوا في قرة جه طاغ، وكان أرطغرل شجاعًا فشَمَّرَ ساعد الجِدِّ في خدمة السلطانِ علاء الدين كيقباد بن كيخسرو بن قلج أرسلان بن طغرل السلجوقي، ولَمَّا قصد علاءُ الدين غزوَ الكُفَّارِ أقبل أرطغرل إليه نجدةً له، فازداد عند السلطان مكانةً وقربًا, فأقطعه جزءًا كبيرًا من الأرضِ مقابِلَ الروم مكافأةً له مِن جهةٍ، ومن جهة أخرى يكون ردءًا له من الروم، فاستقَرَّت هذه الأسَرُ التركمانيَّةُ في تلك الناحية قريبًا من بحر مرمرة التابع للبحر الأسود قريبًا من مدينة بورصة، فلما نازل السلطانُ علاء الدين سنة 685 قلعةَ كوتاهيه وقد كانت للكُفَّار، فلما قرب مِن أخذِ القلعة بلغه أنَّ التَّتارَ يَطرُقُ بعضَ بلاده، فنهض إلى طرَفِ العدو وفوَّضَ أمرَ القلعة إلى أرطغرل بك وتركه بها مع بعضِ العسكَرِ. ولم يزل حتى فتحها عَنوةً وغَنِمَ شيئًا كثيرًا، ولم يزَلْ بعد ذلك يجاهد، وفُتِحَت على يديه بلادٌ كثيرة من بلاد الكُفَّارِ حتى توفِّيَ في شهور هذه السنة، فلمَّا سمع علاء الدين بوفاتِه تأسَّفَ عليه, وكتب لعثمانَ بنِ أرطغرل بالسَّلطنةِ، وأرسل إليه خِلعةً وسَيفًا ونقارةً، وخَصَّه بالغزوِ على الكُفَّار."},{"id":2824,"title":"خروج عساكر السلطان لاجين لاسترداد سيس من التتار .","date":["العام الهجري :697","الشهر القمري : محرم","العام الميلادي :1297"],"text":"استشار السلطان حسام الدين لاجين الأمراءَ في أخذ سيس، وكان ذلك الوقتُ وقتَ اختلاف المغول، ثم عرض الجيشَ وجَرَّد في مصر تجريدةً فيها مجموعةٌ من الأمراء وكَتَب كتابًا لنائِبِ الشام سيف الدين قبجق بأن يتجَرَّد ويجَرِّدَ معه مجموعةً من الأمراء، وكتب إلى نائب طرابلس أيضًا أن يتجَرَّد بعساكرها، وإلى نائبِ حماة كذلك، وإلى نائبِ صفد فارس الدين اليكي الظاهري كذلك. فاجتمع هؤلاء مع الأميرِ سَيفِ الدين بلبان الطباخي نائبِ حلب، وتوجهوا إلى سيس، وكان وصولُهم إليها في شهر رجب، فشَنُّوا الإغارةَ على أهلِها، وأوقعوا بخيلِها ورجالِها، ودوَّخوا أرجاءَ حَزْنِها وسَهلِها، وفَتَحوا تَلَّ حمدون والمصيصة وحموص وقلعة نجم وسروندكار وحَجَر شعلان والنقير وقلعة الهارونية."},{"id":2825,"title":"السلطان لاجين يقر بأنه مؤقت في الملك حتى يكبر الملك الناصر .","date":["العام الهجري :697","الشهر القمري : صفر","العام الميلادي :1297"],"text":"استدعى السلطانُ حسام الدين لاجين قاضيَ القضاة زينَ الدين علي بن مخلوف المالكي، وصِيَّ المَلِك الناصرِ محمد بن قلاوون، وقال له: الملِكُ الناصر ابنُ أستاذي، وأنا قائِمٌ في السلطنة كالنائِبِ عنه إلى أن يُحسِنَ القيامَ بأمرها، والرأيُ أن يتوجَّهَ إلى الكرك وأمَرَه بتجهيزِه، ثم قال السلطانُ للملك الناصر محمد بن قلاوون: لو عَلِمتُ أنَّهم يخلونَك سلطانًا واللهِ ترَكْتُ المُلكَ لك، لكِنَّهم لا يخلونه لك وأنا مملوكُك ومملوكُ والدِك، أحفَظُ لك المُلكَ، وأنت الآن تروح إلى الكرك إلى أن تترعرعَ وترتجِلَ وتتحَرَّج وتجرِّبَ الأمور وتعود إلى مُلكِك، بشرط أنك تعطيني دمشقَ وأكونَ بها مثل صاحِبِ حماة فيها، فقال له الناصر: فاحلِفْ لي أن تبقيَ على نفسي وأنا أروحُ، فحَلَفَ كلٌّ منهما على ما أراده الآخَرُ، فخرج الناصِرُ في أواخر صفر، ومعه الأميرُ سيف الدين سلار أمير مجلس، والأمير سيف الدين بهادر الحموي، والأمير أرغون الدوادار، وطيدمر جوباش رأس نوبة الجمدارية، فوصل إلى الكرك في رابع ربيع الأول، فقام لخدمته الأميرُ جمال الدين أقوش الأشرف نائب الكرك."},{"id":2826,"title":"وفاة أحمد بن عثمان بن قايماز والد الإمام الذهبي .","date":["العام الهجري :697","الشهر القمري : جمادى الأولى","العام الميلادي :1298"],"text":"هو شِهابُ الدين أحمد بن عثمان بن قايماز بن الشيخ عبد الله التركماني الفارقي الأصل ثم الدمشقي الذهبي. قال الذهبي: \"والدي أحسَنَ اللهُ جزاءه ولد سنة 641 تقريبًا، وبرع في دقِّ الذَّهَب، وحصل منه ما أعتق منه خمسَ رقاب، وسَمِعَ الصحيح في سنة 666 من المقداد القيسي، وحجَّ في أواخر عمره، كان يقومُ مِن الليل\". توفِّي في آخر جمادى الأولى ليلة الجمعة، وصلى عليه الخلقُ يؤُمُّهم قاضي القضاة ابنُ جماعة."},{"id":2827,"title":"غزو سيس لتحريرها من الأرمن .","date":["العام الهجري :697","الشهر القمري : رجب","العام الميلادي :1298"],"text":"قَدِمَ البريدُ مِن حَلَب بوقوع الخلاف بين الملك طقطاي بن منكوتمر ملك التتار وطائفة الأمير نغيه حتى قُتل منهم كثيرٌ من المغول، وانكسر طقطاي، وأنَّ غازان قَتَل وزيره نيروز وعِدَّةً ممن يلوذ به، فاتَّفق الرأي على أخذ سيس ما دام الخلافُ قائمًا بين المغول، وأن يخرُجَ الأمير بدر الدين بكتاش أميرُ سلاح ومعه ثلاثةُ أمراء وعشرةُ آلاف فارس، وكتب لنائب الشامِ بتجريد الأمير بيبرس الجالق وغيرِه من أمراءِ دِمشقَ وصفد وطرابلس، وعُرض الجيش في جمادى الأولى، فلما تجهَّزوا سار الأميرُ بدرُ الدين بكتاش الفخري إلى غزاةِ سيس، ومعه مِن الأمراءِ حسامُ الدين لاجين الرومي الأستادار وشمس الدين أقسنقر كرتاي ومضافيهم، فدخلوا دمشق في خامس جمادى الآخرة، وخرج معهم منها الأميرُ بيبرس الجالق العجمي والأميرُ سيف الدين كجكن والأمير بهاء الدين قرا أرسلان ومضافيهم في ثامنه، وساروا بعسكرِ صفد وحمص وبلاد الساحِلِ وطرابلس، والملك المظَفَّر تقي الدين محمود صاحب حماة، فلما بلغ مسيرُهم متمَلِّكَ سيس بعث إلى السلطانِ يسأله العفوَ، فلم يجِبْه، ووصلت هذه العساكِرُ إلى حلب، وجهَّز السلطانُ الأميرَ علم الدين سنجر الدواداري بمضافيه من القاهرة ليلحَقَ بهم، فأدرك العساكِرَ بحلب، وخرجوا منها بعسكرِ حلب إلى العمق، وهم عشرةُ آلاف فارس، فتوجَّه الأميرُ بدر الدين بكتاش في طائفةٍ مِن عقبة بغراس إلى إسكندرونة، ونازلوا تل حمدون، وتوجَّه الملك المظَفَّر صاحب حماة والأمير علم الدين سنجر الدوادراي والأمير شمس الدين أقسنقر كرتاي في بقيَّةِ الجيشِ إلى نهر جهان، ودخَلوا جميعًا دربند سيس في يوم الخميسِ رابع رجب، وهناك اختلفوا، فأشار الأميرُ بكتاش بالحصار ومنازلةِ القلاع، وأشار سنجر الدواداري بالغارةِ فقط، وأراد أن يكونَ مُقَدَّم العسكر، ومنَعَ الأمير بكتاش من الحصارِ ومنازلةِ القِلاعِ فلم ينازِعْه، فوافقه بكتاش وقطَعوا نهرَ جهان للغارة، ونزل صاحِبُ حماة على مدينة سيس، وسار الأميرُ بكتاش إلى أذنة، واجتمَعَت العساكِرُ جميعُها عليها بعد أن قتَلوا من ظَفِروا به من الأرمن، وساقوا الأبقار والجواميس، ثم عادوا من أذنة إلى المصيصة بعد الغارة، وأقاموا عليها ثلاثة أيام حتى نصبوا جسرًا مرَّت عليه العساكِرُ إلى بغراس، ونزلوا بمرجِ أنطاكية ثلاثة أيام، ثم رحلوا إلى جسرِ الحديدِ يريدونَ العودةَ إلى مصر، فعادت العساكرُ من الروج إلى حلب وأقاموا بها ثمانية أيام، وتوجَّهوا إلى سيس من عقبة بغراس، وسار كجكن وقرا أرسلان إلى أياس وعادا شبه منهزمَينِ؛ فإنَّ الأرمن أكمنوا لهم في البساتين، فأنكر عليهما الأمير بكتاش، فاعتذروا بضيقِ المسلك والتفاف الأشجارِ وعدم التمكُّن من العدُوِّ."},{"id":2828,"title":"فتح تل حمدون ومرعش .","date":["العام الهجري :697","الشهر القمري : رمضان","العام الميلادي :1298"],"text":"بعد غزو سيس رحل الأمير بكتاش بجميع العساكِرِ إلى تل حمدون، فوجدوه خاليًا وقد نزح من كان فيه من الأرمن إلى قلعةِ نجيمة فتسَلَّمَها في سابع رمضان وأقام بها من يحفَظُها، وسيَّرَ الأمير بلبان الطباخي نائِبُ حلَب عسكرًا، فملكوا قلعةَ مرعش في رمضانَ أيضًا."},{"id":2829,"title":"تحرير قلعة نجيمة  .","date":["العام الهجري :697","الشهر القمري : ذي القعدة","العام الميلادي :1298"],"text":"جاء الخبرُ إلى الأمير بكتاش وهو على تل حمدون بأن واديًا تحت قلعة نجيمة وحميص قد امتلأ بالأرمن، وأنَّ أهل قلعة نجيمة تحميهم، فبعث طائفةً مِن العسكر إليهم فلم ينالوا غرَضًا، فسَيَّرَ طائفةً ثانيةً فعادت بغير طائل، فسار الأمراءُ في عِدَّة وافرة وقاتلوا أهلَ نجيمة حتى ردُّوهم إلى القلعة، وزحفوا على الوادي وقتَلوا وأسَروا مَن فيه، ونازلوا قلعةَ نجيمة ليلةً واحدة، وسار العسكَرُ إلى الوطأة، وبقي الأميرُ بكتاش والمَلِك المظفَّر في مقابلة مَن بالقلعة خشيةَ أن يخرُجَ أهل نجيمة فينالوا من أطرافِ العسكر، حتى صار العسكَرُ بالوطأة، ثم اجتمعوا بها، فقَدِمَ البريد من السلطان بمنازلةِ قلعة نجيمة حتى تُفتَح، فعادوا إلى حصارها، واختلف الأميرُ بكتاش والأمير سنجر الدواداري على قتالها، فقال الدواداري: متى نازلها الجيشُ بأسْرِه لا يُعلَمُ من قاتل ممَّن عجَز وتخاذلَ، والرأي أن يقاتِلَ كُلَّ يومٍ أميرٌ بألفه، وأخذ يُدِلُّ بشجاعتِه، ويصَغِّرُ شأن القلعة، وقال: أنا آخُذُها في حجري فسَلَّموا له واتَّفَقوا على تقديمه لقتالها قبل كلِّ أحد، فتقدم الدواداري إليها بألفِه حتى لاحف السور، فأصابه حجَرُ المنجنيقِ فقطع مشطَ رِجلِه، وسقط عن فَرَسِه إلى الأرض، وكاد الأرمن يأخذونَه، إلَّا أن الجماعة بادرت وحمَلَته على جنوبة إلى وطاقه، ولَزِمَ الفراش، فعاد إلى حلب، وسار منها إلى القاهرة، وقُتِلَ في هذه النوبة الأميرُ علم الدين سنجر طقصبا الناصري، وزحف في هذا اليومِ الأمير كرتاي ونَقَب سور القلعة وخَلَّصَ منه ثلاثة أحجار، واستُشهد معه ثلاثة عشر رجلًا، ثم زحف الأميرُ بكتاش وصاحِبُ حماة ببقية الجيش طائفة بعد طائفة، وكلٌّ منهم يُردِفُ الآخر حتى وصلوا إلى السورِ، وأخذوا في النَّقب وأقاموا الستائر، وتابعوا الحصار واحدًا وأربعين يومًا، وكان قد اجتمع بها من الفلَّاحين ونساءِ القرى وأولادِهم خلقٌ كثيرٌ، فلمَّا قلَّ الماءُ عندهم أخرجوا مرَّةً مائتي رجلٍ وثلاثَمائة امرأة ومائةً وخمسين صبيًّا، فقتَلَ العسكر الرجال واقتسموا النساءَ والصبيان، ثم أخرجوا مرَّةً أخرى مائة وخمسين رجلًا ومائتي امرأة وخمسة وسبعين صبيًّا، ففعلوا بهم مثلَ ما فعلوا بمن تقَدَّم، ثم أخرجوا مرةً ثالثة طائفة أخرى، فأتوا على جميعِهم بالقتلِ والسَّبي، حتى لم يتأخَّرْ بالقلعةِ إلَّا المقاتِلة، وقَلَّت المياه عندهم حتى اقتتلوا بالسيوفِ على الماء، فسألوا الأمانَ فأُمِّنوا، وأُخِذَت القلعة في ذي القعدة، وسار مَن فيها إلى حيث أراد، وأخذ أيضًا أحد عشر حصنًا من الأرمن، ومنها النقير، وحجر شغلان، وسرقندكار، وزنجفرة، وحميص، وسَلَّمَ ذلك كُلَّه الأميرُ بكتاش إلى الأميرِ سيف الدين أسندمر كرجي من أمراء دمشقَ، وعيَّنه نائبًا بها، فلم يزَلْ أسندمر بها حتى قَدِمَ التتارُ، فباع ما فيها من الحواصِلِ ونزح عنها، فأخذَها الأرمن، ولما تم هذا الفتحُ عادت العساكرُ إلى حلب وكان الشتاء شديدًا، فأقاموا بها، وبعث السلطانُ إليهم الأميرَ سيف الدين بكتمر السلاح دار، والأميرَ عز الدين طقطاي، والأميرَ مبارز الدين أوليا بن قرمان، والأميرَ علاء الدين أيدغدي شقير الحسامي، في ثلاثة آلاف فارسٍ مِن عساكر مصر، فدخلوا دمشقَ يوم الثلاثاء سابع عشر ذي القعدة، وساروا منها إلى حلب، وأقاموا بها مع العسكَرِ، وبعث متمَلِّكُ سيس إلى السلطانِ يسأل العفوَ."},{"id":2830,"title":"بعض أمراء المماليك يلجؤون إلى المغول .","date":["العام الهجري :698","العام الميلادي :1298"],"text":"لَمَّا رجعت طائفةٌ مِن الجيش من بلاد سيس بسَبَبِ المرض الذي أصاب بعضَهم، فجاء كتابُ السلطان بالعَتبِ الأكيدِ والوعيد الشديد لهم، وأن الجيش يخرج جميعًا صحبةَ نائِبِ السلطنة قبجق إلى هناك، ونصَبَ مَشانِقَ لِمن تأخر بعُذرٍ أو غيره، فخرج نائبُ السلطنة الأميرُ سيف الدين قبجق وصحبته الجيوش، وخرج أهل البلد للفرجة على الأطلابِ على ما جرت به العادة، فبرز نائبُ السَّلطنة في أبَّهة عظيمة، فدعت له العامة وكانوا يحبُّونَه، واستمَرَّ عسكر الجيش سائرين قاصدين بلاد سيس، فلمَّا وصلوا إلى حمص بلغ الأميرَ سيفَ الدين قبجق وجماعةً من الأمراء أنَّ السلطانَ قد تغَلَّت خاطرُه بسببِ سَعيِ منكوتمر فيهم؛ فإن السلطان لاجين لَمَّا تولى السلطنة خلَفَ بوَعدِه للأمراء أنَّه لن يلي مملوكُه منكوتمر شيئًا، ولكنه أمَّرَه بل جعَلَه نائبَه الأوَّلَ، بل انقاد لرأيِه في الأمراءِ؛ حيث إنَّ منكوتمر أمَّلَ أن يكونَ وليَّ عهد السلطان لاجينَ خاصَّةً أن السلطان كان قد مَرِضَ ولم يكن له ولَدٌ ذكَرٌ وليًّا لعهده، فعَمِلَ على إبعاد مُنافِسيه من الأمراء الذين بمصرَ، وتمكَّنَ من السعي بهم والقَبض ِعليهم، وبدا أنَّ السلطانَ يميلُ إلى الاحتجاب وتفويضِ أمورِ السلطنة إلى منكوتمر، وبَقِيَ عليه إزاحةُ أمراء الشامِ وإقامةِ غَيرِهم من مماليك السلطانِ في مصر والشام ليتمكَّنَ مِن مراده، وعَلِموا أن السُّلطانَ لا يخالفه لمحبَّتِه له، فاتفق جماعةٌ منهم على الدخول إلى بلاد التتر والنجاةِ بأنفُسِهم، فساقوا من حمص فيمن أطاعهم، وهم قبجق وبزلي وبكتمر السلحدار (رتبة عسكرية) والأيلي، واستمرُّوا ذاهبين، فرجع كثيرٌ من الجيش إلى دمشق، وتخبَّطَت الأمور وتأسَّفَت العوامُّ على قبجق لحسن سيرته، وذلك في ربيع الآخِر من هذه السَّنة."},{"id":2831,"title":"تأسيس الدولة العثمانية على يد الغازي عثمان بن أرطغرل بك .","date":["العام الهجري :698","العام الميلادي :1298"],"text":"كان الأميرُ علاء الدين السلجوقي قد أقطع أرطغرل جزءًا كبيرًا من الأرضِ مقابِلَ الرومِ مكافأةً له مِن جهةٍ، ومن جهةٍ أخرى يكون ردءًا له من الروم، فاستقَرَّت هذه الأسَرُ التركمانية في تلك الناحية قريبًا من بحرِ مرمرة التابع للبحر الأسودِ قريبًا من مدينة بورصة، إلى أن توفي أرطغرل سنة 697 فخَلَفَه ابنُه عثمانُ أكبَرُ أولاده، الذي حَظِيَ أيضًا بقَبولِ الأمير علاء الدين السلجوقي، ويُعَدُّ عُثمانُ هذا هو أوَّلَ مؤسِّسٍ للدَّولةِ العثمانية؛ حيث بدأ يتوسَّعُ بإمارته فتمَكَّنَ سنة 698 من ضَمِّ قلعة حصار أو القلعة السوداء ممَّا زاد من إعجابِ الأمير علاء الدين به، فمنحه لقَبَ بيك، وأقَرَّه على الأراضي التي ضَمَّها إليه، كما أقرَّه على ضَربِ عُملةٍ باسمِه بالإضافة إلى ذِكرِ اسمِه في الخُطَبِ يوم الجمعة، ثم زاد من أمرِ عثمانَ أنَّ المغول لما أغاروا على علاء الدين سنة 699 ففَرَّ منهم وتوفِّيَ في العامِ نَفسِه وخُلِعَ ابنُه غياث الدين الذي قتلَتْه المغولُ أيضًا، فلم يَعُدْ أمام عثمان أيُّ سلطةٍ أعلى منه، فبدأ بالتوسُّعِ، فاتخذَ مِن مدينة يني شهر- أي: المدينة الجديدة- قاعدةً له، ولقَّبَ نفسَه باديشاه آل عُثمان، واتخذ رايةً (وهي نفسُ عَلَمِ تركيا اليومَ)."},{"id":2832,"title":"اغتيال المنصور لاجين سلطان المماليك وتنصيب محمد بن قلاوون .","date":["العام الهجري :698","الشهر القمري : ربيع الآخر","العام الميلادي :1299"],"text":"قُتِلَ السلطانُ المَلِكُ المنصورُ حسام الدين لاجين ونائبُه سيف الدين منكوتمر، ليلةَ الجمعة حادي عشر ربيع الآخر، على يدِ الأمير سيف الدين كرجي الأشرفي ومَن وافقه من الأمراء، وذلك بحضورِ القاضي حسامِ الدين الحنفي وهو جالسٌ في خدمته يتحَدَّثان، وقيل كانا يلعبانِ بالشطرنج، فلم يشعُرا إلَّا وقد دخلوا عليهم فبادروا إلى السلطانِ بسُرعةٍ جَهرةً ليلةَ الجمعة فقَتَلوه وقُتِلَ نائبُه منكوتمر صبرًا صبيحة يوم الجمعةِ وألقِيَ على مزبلة، واتفق الأمراءُ على إعادة ابنِ أستاذهم المَلِك النَّاصر محمدِ بنِ قلاوون، فأرسلوا وراءَه، وكان بالكرك ونادَوا له بالقاهرة، وخُطِبَ له على المنابر قبل قدومِه، وجاءت الكتُبُ إلى نائِبِ الشامِ قبجق فوجدوه قد فَرَّ خَوفًا من غائلة لاجين، فسارت إليه البريديَّةُ فلم يدركوه إلا وقد لحِقَ بالمغول عند رأسِ العين، من أعمال ماردين، وتفارط الحالُ ولا قُوَّة إلَّا بالله، وكان سَبَبُ قتل لاجين ونائبه منكوتمر هو ما بدر منهما تجاهَ الأمراءِ؛ فإن لاجين كان قد حَلَف لهم يوم أن نَصَبوه سلطانًا بعد قتْلِه كتبغا أنَّه لن يولي منكوتمر شيئًا بل سيقَدِّمُهم فَهُم الأمراءُ, ولكِنَّ هذا ما لم يكُنْ، فقَدَّمَ مَملوكَه وجعَلَه نائبَه وأصبح يعتَقِلُ الأمراء ويقتُلُ بَعضَهم، حتى إنه في أسبوعٍ واحد قتل خمسةً مِن الأمراء، والذي لم يُقتَل أو يُعتَقَل أُبعِدَ في الولاياتِ السخيفةِ التي لا تليقُ بهم في الأماكِنِ البعيدة، وكُلُّ ذلك بتدبيرِ النائب منكوتمر؛ طمعًا منه أن يليَ السلطنة؛ لأنَّ لاجين لا ذريَّةَ له من الذكور، فأفعالُه تلك أوغَرَت عليه صدورَ الأمراء ممَّا حدا بهم إلى قتلِهما جميعًا، ثم كان دخولُ الملك الناصر إلى مصرَ يوم السبتِ رابِعَ جمادى الأولى، وكان يومًا مشهودًا، ودُقَّت البشائِرُ ودخل القضاةُ وأكابِرُ الدولة إلى القلعة، وبويع بحضرةِ عَلَم الدين أرجواش، وخُطِبَ له على المنابر بدِمشقَ وغيرها بحضرةِ أكابر العلماء والقُضاة والأُمراءِ."},{"id":2833,"title":"وفاة الشيخ رسلان الصوفي .","date":["العام الهجري :699","العام الميلادي :1299"],"text":"هو الشيخُ الزَّاهِدُ العابدُ، رسلان بن يعقوب بن عبد الله بن عبد الرحمن الجعبري، ثم الدمشقي، صوفي مشهورٌ تعتقد فيه العامَّةٌ كراماتٍ كما هو شأنُهم في المتصَوِّفة، فنَسَبوا له الطيرانَ في الهواء وأنه ما جلس تحت شجرةٍ يابسةٍ إلَّا اخضَرَّت، بل نسب جهلةُ العوامِّ إليه أنه هو السَّبَبُ في انحسار التتار عن دمشق وأنه هو حامي البَرِّ والشام، بل إن بعُضهم إلى اليوم يذكُرُ ذلك عنه!! توفي في دمشق ودُفِنَ فيها وقَبرُه فيها معروفٌ، وله عنده مسجدٌ يُعرَفُ به."},{"id":2834,"title":"المغول يهزمون المماليك في موقعة سلمية بالشام .","date":["العام الهجري :699","الشهر القمري : ربيع الأول","العام الميلادي :1299"],"text":"دارت مَعركةٌ بين \"محمود غازان\" سلطانِ الدولةِ الإيلخانية المغوليَّة, والذي أعلن هو وكثيرٌ من التتار دخولَهم في الإسلام سنة 694, و\"النَّاصر قلاوون\" سلطانُ دولة المماليك، وكانت معركةً هائلةً أسفرت عن انتصار غازان وجنودِه؛ بسَبَبِ تفَوُّقِهم في العِدَّة والعتاد، وتعَرَّض السلطانُ الناصر محمد قلاوون لمؤامرةٍ لخَلعِه, فقد تحرَّك غازان متَّجِهًا إلى بلاد الشام فقَطَع الفرات، وكانت الأخبارُ قد وصلت إلى السلطنةِ وتجهَّزَ العسكرُ مِن مصر ووصل إلى دمشقَ وتجهز عسكر دمشق، ووصلت الأخبارُ أن غازان قد وصل قريبًا من حلب في جيشٍ عظيم، حتى هرب كثيرٌ من أهل حلب وحماة إلى دمشق، ووصل العسكرُ المصري إلى دمشق، ثم خرج السلطانُ بالجيش من دمشق يوم الأحدِ سابع عشر ربيع الأول، ولم يتخَلَّف أحد من الجيوش، وخرج معهم خلقٌ كثير من المتطَوِّعة، فلما وصل السلطانُ إلى وادي الخزندار عند وادي سلمية قريبًا من حمص، التقى مع التَّتَر هناك يوم الأربعاء السابع والعشرين من ربيع الأول وتصادما، وقد كَلَّت خيولُ السلطان وعساكِرُه مِن السَّوْق؛ والتحم القتالُ بين الفريقين، وحمَلَت ميسرةُ المسلمين عليهم فكسَرتَهم أقبحَ كَسرةٍ، وقَتَلوا منهم جماعة كثيرة نحو خمسةِ آلاف أو أكثر، ولم يُقتَل من المسلمين إلا اليسير، ثم حملت القلبُ أيضًا حملةً هائلة وصَدَمت العدوَّ أعظمَ صَدمةٍ، وثبت كلٌّ من الفريقين ثباتًا عظيمًا، ثم حصل تخاذلٌ في عسكَرِ الإسلام بعضُهم في بعضٍ؛ بلاءً مِن الله تعالى، - فانهزمت ميمنةُ السلطان بعد أن كان لاح لهم النصرُ، فلا قوةَ إلا بالله، ولما انهزمت الميمنةُ انهزم أيضًا من كان وراء السناجق- الرايات- السلطانية من غير قتالٍ، وألقى الله تعالى الهزيمةَ عليهم فانهزم جميعُ عساكر الإسلام بعد النصر، وساق السلطان في طائفة يسيرةٍ من أمرائه ومدبري مملكتِه إلى نحو بعلبك وترَكوا جميع الأثقال مُلقاةً، فبقيت العُدَد والسِّلاح والغنائم والأثقالُ ملأت تلك الأراضي حتى بقيت الرماحُ في الطرقِ كأنَّها القَصَبُ لا ينظر إليها أحدٌ، ورمى الجندُ خُوذَهم عن رؤوسِهم وجواشنَهم وسلاحَهم تخفيفًا عن الخيلِ لتنجيَهم بأنفسهم، وقصد الجميعُ دمشق، وكان أكثَرُ من وصل إلى دمشق من المنهزمين من طريق بعلبك، ولما بلغ أهلَ دمشق وغيرها كسرةُ السلطانِ عَظُمَ الضجيج والبكاء، وخرجت المخَدَّراتُ حاسراتٍ لا يعرفن أين يذهبن والأطفالُ بأيديهن، وصار كل واحد في شغلٍ عن صاحِبِه إلى أن ورد عليهم الخبَرُ أن ملك التتار قازان مسلِمٌ، وأن غالِبَ جَيشِه على ملَّة الإسلام، وأنهم لم يتْبَعوا المنهزمين، وبعد انفصال الوقعة لم يقتلوا أحدًا ممن وجَدوه، وإنما يأخذونَ سلاحَه ومركوبَه ويُطلِقونه، فسكن بذلك روعُ أهل دمشق قليلًا، ثم صار من وصل إلى دمشق أخذَ أهلَه وحواصِلَه بحيث الإمكان وتوجَّه إلى جهة مصر، وبقي من بقيَ بدمشق في خمدةٍ وحَيرةٍ لا يدرون ما عاقبةُ أمرهم؛ فطائفةٌ تغَلَّب عليهم الخوفُ، وطائفةٌ يترجَّونَ حَقنَ الدماء، وطائفةٌ يترجَّون أكثَرَ من ذلك من عَدلٍ وحُسنِ سيرة."},{"id":2835,"title":"دخول قازان وجيشه المغول إلى دمشق .","date":["العام الهجري :699","الشهر القمري : ربيع الآخر","العام الميلادي :1300"],"text":"بعد أن انهزم جيشُ المماليك من التتار في موقعةِ السلمية في ربيع الأول، وبعد ما حصل لأهل دمشق من الخوفِ الشديد، زاد الأمر أنَّه في ليلة الأحد ثاني ربيع الآخر كسر المحبوسون بحَبسِ أبي الصغير الحبسَ وخرجوا منه على حميةٍ، وتفرقوا في البلدِ، وكانوا قريبًا من مائتي رجل فنَهَبوا ما قدروا عليه وجاؤوا إلى باب الجابية فكسروا أقفالَ الباب البراني وخرَجوا منه إلى بر البلد، فتفَرَّقوا حيث شاؤوا لا يقدِرُ أحد على رَدِّهم، وعاثت الحرافشة- كالشُّطَّار والعيَّارين في بغداد- في ظاهرِ البلد، فكسروا أبواب البساتين وقلعوا من الأبوابِ والشبابيك شيئًا كثيرًا، وباعوا ذلك بأرخَصِ الأثمان، هذا وسلطانُ التتار قد قصد دمشقَ بعد الوقعة، فاجتمع أعيانُ البلد والشيخ تقي الدين ابنُ تيميَّةَ في مشهدِ عليٍّ، واتفقوا على المسير إلى قازان لتلَقِّيه، وأخْذِ الأمانِ منه لأهل دمشق، فتوجَّهوا يوم الاثنين ثالث ربيع الآخر فاجتَمَعوا به عند النبك، وكلَّمَه الشيخُ تقي الدين كلامًا قويًّا شديدًا فيه مصلحةٌ عظيمةٌ عاد نفعُها على المسلمين. ذكر ابن كثير: \"أنَّ شَيخَ الإسلامِ تقيَّ الدينِ ابن تيميَّةَ قال لترجمانِ قازان: قل للقان: أنت تزعُمُ أنَّك مسلِمٌ ومعك مؤذِّنونَ وقاضٍ وإمامٌ وشَيخٌ على ما بلَغَنا، فغزَوْتَنا وبلَغْتَ بلادَنا على ماذا؟! وأبوك وجَدُّك هولاكو كانا كافرينِ وما غزَوَا بلادَ الإسلام، بل عاهَدوا قومَنا، وأنت عاهَدْتَ فغَدَرْتَ وقُلْتَ فما وفَيْتَ! قال: وجَرَت له مع قازان وقطلوشاه وبولاي أمور ونُوَب، قام ابن تيمية فيها كُلِّها لله، وقال الحَقَّ ولم يخشَ إلا الله عزَّ وجَلَّ. قال: وقَرَّب إلى الجماعةِ طَعامًا فأكلوا منه إلَّا ابنَ تيميَّةَ، فقيل له: ألا تأكُلُ؟ فقال: كيف آكُلُ مِن طعامِكم وكلُّه مما نهَبْتُم من أغنامِ النَّاسِ وطَبَختُموه بما قطَعْتُم من أشجارِ النَّاسِ؟! قال: ثمَّ إن قازان طلَبَ منه الدعاءَ، فقال في دعائه: \"اللهم إن كان هذا عبدُك محمود إنَّما يقاتِلُ لتكونَ كَلِمَتُك هي العُليا وليكونَ الدِّينُ كُلُّه لك، فانصُرْه وأيِّدْه ومَلِّكْه البِلادَ والعبادَ، وإن كان إنما قام رياءً وسُمعةً وطَلبًا للدنيا ولتكونَ كَلِمتُه هي العليا ولِيُذِلَّ الإسلامَ وأهلَه، فاخذُلْه وزلزِلْه ودَمِّرْه واقطَع دابِرَه\" قال: وقازان يؤمِّنُ على دعائه، ويَرفَعُ يديه. قال: فجعَلْنا نجمَعُ ثيابَنا خوفًا من أن تتلوَّثَ بدَمِه إذا أمَرَ بقَتلِه!! قال: فلمَّا خرجنا من عنده قال له قاضي القضاة نجم الدين بن صصرى وغيره: كدتَ أن تُهلِكَنا وتُهلِكَ نَفسَك، واللهِ لا نَصحَبُك من هنا، فقال: وأنا واللهِ لا أصحَبُكم. قال: فانطلَقْنا عُصبةً وتأخَّرَ هو في خاصَّةِ نَفسِه ومعه جماعةٌ من أصحابه، فتسامَعَ به الأمراءُ من أصحاب قازان فأتوه يتبَرَّكونَ بدعائه، وهو سائِرٌ إلى دمشق، وينظُرونَ إليه، قال: والله ما وصل إلى دمشقَ إلَّا في نحو ثلثمائةِ فارسٍ في رِكابِه، وكنت أنا من جملةِ مَن كان معه، وأمَّا أولئك الذين أبوا أن يصحبوه فخرج عليهم جماعةٌ من التتر فشَلحوهم عن آخِرِهم!!\"، ودخل المسلمونَ ليلتئذٍ مِن جهة قازان فنزلوا بالبدرانيَّة وغُلِّقَت أبوابُ البلد سوى باب توما، وخَطَب الخطيبُ بالجامع يوم الجمعةِ، ولم يَذكُرْ سُلطانًا في خُطبتِه، وبعد الصلاةِ قَدِمَ الأمير إسماعيل ومعه جماعةٌ مِن الرسُلِ فنزلوا ببستان الظاهر عند الطرن، وحضر الفرمان بالأمان وطِيفَ به في البلد، وقرئ يومَ السبتِ ثامِنَ الشهر بمقصورة الخطابة، ونُثِرَ شَيءٌ من الذهب والفضة، وفي ثاني يوم من المناداة بالأمان طُلِبَت الخيولُ والسلاح والأموال المخبَّأة عند الناس من جهةِ الدولة، وجلس ديوان الاستخلاصِ إذ ذاك بالمدرسة القيمريَّة، وفي يوم الاثنين عاشِرَ الشهر قَدِمَ سيف الدين قبجق المنصوري الذي كان هرب إلى التتارِ، فنزل في الميدان واقترب جيشُ التتر وكَثُرَ العَيثُ في ظاهر البلد، وقُتِلَ جماعةٌ وغَلَت الأسعارُ بالبلد جِدًّا، وأرسل قبجق إلى نائب القلعة ليسَلِّمَها إلى التتر فامتنع أرجواش من ذلك أشدَّ الامتناع، فجمع له قبجق أعيانَ البلد فكَلَّموه أيضًا فلم يجبهم إلى ذلك، وصَمَّمَ على ترك تسليمِها إليهم وبه عَينٌ تَطرفُ؛ فإنَّ الشَّيخَ تقيَّ الدين ابن تيمية أرسل إلى نائب القلعةِ يقول له ذلك، لو لم يبقَ فيها إلَّا حَجَرٌ واحِدٌ فلا تسَلِّمْهم ذلك إن استطعْتَ، وكان في ذلك مصلحةٌ عظيمة لأهل الشامِ؛ فإن الله حَفِظَ لهم هذا الحِصنَ والمَعقِلَ الذي جعله الله حِرزًا لأهل الشام التي لا تزال دارَ إيمانٍ وسُنَّةٍ، حتى ينزِلَ بها عيسى بنُ مريم، وفي يوم دخول قبجق إلى دمشقَ دخل السلطانُ ونائبُه سلار إلى مصرَ، كما جاءت البطاقة بذلك إلى القلعة، ودُقَّت البشائرُ بها، فقَوِيَ جأش الناس بعضَ قُوَّةٍ، وفي يوم الجمعة رابع عشر ربيع الآخر خُطِبَ لقازان على منبر دمشقَ بحضور المغول بالمقصورةِ ودُعِيَ له على السُّدَّة بعد الصلاة، وقرئ عليها مرسومٌ بنيابة قبجق على الشام، وذهب إليه الأعيان فهنَّؤوه بذلك، فأظهر الكرامةَ وأنه في تعَبٍ عظيمٍ مع التتر، وفي يوم السبت النصف من ربيع الآخر شرعت التتارُ وصاحب سيس في نهب الصالحيَّة ومسجدِ الأسديَّة ومسجد خاتون ودار الحديث الأشرفيَّة بها، واحترق جامعُ التوبة بالعقيبية، وكان هذا من جهةِ الكرج والأرمن من النصارى الذين هم مع التَّتارِ قَبَّحَهم الله، وسَبَوا من أهلِها خلقًا كثيرًا وجمًّا غفيرًا، وجاء أكثَرُ الناس إلى رباط الحنابلة، فاحتاطت به التتار فحماه منهم شيخُ الشيوخ، وأعطى في الساكِنِ مال له صورة ثم اقتحموا عليه فسَبَوا منه خلقًا كثيرًا من بنات المشايخ وأولادِهم، ولما نُكِب دير الحنابلة في ثاني جمادى الأولى قتلوا خلقًا من الرجال وأسَروا من النساء كثيرًا، ونال قاضيَ القضاةِ تقيَّ الدين ابنَ تيميَّةَ أذًى كثيرٌ، ويقال إنَّهم قتلوا من أهل الصالحية قريبًا من أربعمائة، وأسَروا نحوًا من أربعة آلاف أسير، ونُهِبَت كتب كثيرة من الرباط الناصري والضيائية، وخزانة ابن البزوري، وكانت تباعُ وهي مكتوبٌ عليها الوقفيَّة، وفعلوا بالمزَّة مثل ما فعلوا بالصالحية، وكذلك بداريا وبغيرها، وتحصَّن الناسُ منهم في الجامِعِ بداريا ففتحوه قسرًا وقتلوا منهم خلقًا وسَبَوا نساءَهم وأولادهم، وخرج الشيخُ ابنُ تيمية في جماعةٍ مِن أصحابه يوم الخميس العشرين من ربيع الآخر إلى مَلِك التتر قازان، وعاد بعد يومينِ ولم يتَّفِق اجتماعُه به، حجَبَه عنه الوزير سعد الدين والرشيد مشير الدولة المسلماني ابن يهودي، والتزما له بقضاءِ الشغلِ، وذكرَا له أن التَّتر لم يحصل لكثيرٍ منهم شيءٌ إلى الآن، ولا بُدَّ لهم من شيءٍ، واشتهر بالبلد أن التتر يريدون دخولَ دمشقَ، فانزعج الناسُ لذلك وخافوا خوفًا شديدًا، وأرادوا الخروجَ منها والهرب على وجوههم، وأين الفرارُ ولات حينَ مَناصٍ!! وقد أُخِذَ من البلد فوق العشرةِ آلاف فرس، ثمَّ فُرِضَت أموال كثيرة على البلدِ مُوزَّعةً على أهل الأسواقِ، كلُّ سوقٍ بحَسَبِه من المال، وشرع التتر في عمل مجانيقَ بالجامِعِ لِيَرموا بها القلعةَ مِن صحن الجامِعِ، وغُلِّقَت أبوابُه ونزل التتار في مشاهِدِه يحرسونَ أخشاب المجانيق، وينهَبونَ ما حوله من الأسواقِ، وأهلُ البلدِ قد أذاقَهم اللهُ لباسَ الجوعِ والخَوفِ بما كانوا يصنعونَ، فإنَّا لله وإنا إليه راجعون، والمصادراتُ والتراسيمُ والعقوباتُ عمالة في أكابِرِ أهلِ البلدِ ليلًا ونهارًا، حتى أُخِذَ منهم شيء كثير من الأموال والأوقاف، كالجامِعِ وغيره، ثم جاء مرسومٌ بصيانة الجامِعِ وتوفيرِ أوقافه وصَرْف ما كان يؤخذُ من خزائن السلاحِ إلى الحجاز، وقرئ ذلك المرسومُ بعد صلاة الجمعة بالجامع في تاسع عشر جمادى الأولى، وفي ذلك اليوم توجَّه السلطان قازان وترك نوَّابَه بالشام في ستين ألف مقاتلٍ نحو بلاد العراق، وجاء كتابُه: إنا قد تركنا نوَّابَنا بالشامِ في ستين ألف مقاتلٍ، وفي عَزْمنا العودُ إليها في زمن الخريف، والدخولُ إلى الديار المصرية وفَتْحُها، وقد أعجَزَتْهم القلعةُ أن يصلوا إلى حجَرٍ منها، وخرج سيف الدين قبجق لتوديع قطلوشاه نائب قازان وسار وراءه وضُرِبَت البشائر بالقلعة فرحًا لرحيلهم، ولم تُفتَح القلعة، وأرسل أرجواش ثاني يومٍ من خروج قبجق إلى الجامعِ، فكسروا أخشاب المنجنيقات المنصوبةِ به، وعادوا إلى القلعةِ سريعًا سالمين، واستصحبوا معهم جماعةً ممَّن كانوا يلوذون بالتتر قهرًا إلى القلعة، منهم الشريفُ القمي، وهو شمس الدين محمد بن محمد بن أحمد بن أبي القاسم المرتضي العلوي، وجاءت الرسلُ من قبجق إلى دمشق، فنادوا بها: طَيِّبوا أنفُسَكم وافتَحوا دكاكينَكم وتهيَّؤوا غدا لتلقِّي سلطان الشام سيف الدين قبجق، فخرج الناسُ إلى أماكنهم فأشرفوا عليها فرأوا ما بها من الفسادِ والدَّمارِ، وانفَكَّ رؤساء البلد من التراسيمِ بعد ما ذاقوا شيئًا كثيرًا!!"},{"id":2836,"title":"رحيل المغول من دمشق وتركهم قبجق نائبا لهم فيها .","date":["العام الهجري :699","الشهر القمري : جمادى الأولى","العام الميلادي :1300"],"text":"رحل المغولُ مِن دمشق على أنَّهم سيعودون زمن الخريف ليدخلوا مصر أيضًا، وعاد سيف الدين قبجق إلى دمشقَ يوم الخميس بعد الظهر خامس عشرين جمادى الأولى ومعه الألبكي وجماعة، وبين يديه السيوفُ مُسَلَّلة وعلى رأسه عصابةٌ، فنزل بالقصر ونودي بالبَلَدِ: نائبُكم قبجق قد جاء فافتَحوا دكاكينَكم واعملوا معاشَكم، ولا يغرر أحدٌ بنفسه هذا الزَّمان والأسعارُ في غاية الغلاءِ والقِلَّة، ولما كان في أواخر الشهر نادى قبجق بالبلد أن يخرُجَ الناس إلى قُراهم، وأمر جماعة وانضاف إليه خلقٌ من الأجناد، وكَثُرت الأراجيف على بابه، وعَظُم شأنه ودُقَّت البشائر بالقلعة، وركب قبجق بالعصائبِ في البلد والشاويشية بين يديه، وجهز نحوًا من ألف فارس نحو خربة اللصوصِ، ومشى مشيَ الملوك في الولاياتِ وتأمير الأمراءِ والمراسيم العالية النافذة، ثم إنَّه ضمن الخماراتِ ومواضِعَ الزنا من الحاناتِ وغيرها، وجُعِلَت دارُ ابن جرادة خارج من باب توما خمارةً وحانة أيضًا، وصار له على ذلك في كلِّ يومٍ ألفُ درهم، وهي التي دمَّرَتْه ومحقت آثارَه، وأخذ أموالًا أخرى من أوقاف المدارس وغيرها، ورجع بولاي من جهة الأغوار وقد عاث في الأرض فسادًا، ونهب البلادَ وخَرَّب ومعه طائفةٌ من التتر كثيرة، وقد خربوا قرًى كثيرة، وقتلوا من أهلها وسَبَوا خلقًا من أطفالها، وجبى لبولاي من دمشق أيضًا جباية أخرى، وخرج طائفةٌ من القلعة فقَتَلوا طائفة من التتر ونهبوهم، وقُتِلَ جماعة من المسلمين في غبون ذلك، وأخذوا طائفةً ممن كان يلوذ بالتتر، ورَسَمَ قبجق لخطيبِ البلَدِ وجماعة من الأعيان أن يدخُلوا القلعة فيتكَلَّموا مع نائِبِها في المصالحةِ، فدخلوا عليه يومَ الاثنين ثاني عشر جمادى الآخرة، فكلَّموه وبالغوا معه فلم يجِب إلى ذلك، وقد أجاد وأحسن وأرجل في ذلك بيَّضَ اللهُ وَجهَه، وفي ثامن رجب طلب قبجق القضاةَ والأعيان فحَلَّفَهم على المناصحة للدولة المحمودية- يعني قازان- فحلفوا له، وفي هذا اليوم خرج الشيخ تقيُّ الدين ابن تيمية إلى مخيَّم بولاي فاجتمع به في فكاكِ مَن كان معه من أسارى المُسلمين، فاستنقذ كثيرًا منهم من أيديهم، وأقام عنده ثلاثةَ أيامٍ ثم عاد، ثم راح إليه جماعةٌ من أعيان دمشق ثم عادوا من عنده فشُلحوا عند باب شرقي وأخَذَ ثيابَهم وعمائِمَهم ورجعوا في شرِّ حالة، ثم بعَثَ في طلبهم فاختفى أكثَرُهم وتغيَّبوا عنه."},{"id":2837,"title":"خروج التتار من دمشق وعودتها لحكم الناصر بمصر .","date":["العام الهجري :699","الشهر القمري : رجب","العام الميلادي :1300"],"text":"في ثالث رجب نودي بجامِعِ دمشق بعد الصلاةِ مِن جهة نائب القلعةِ بأنَّ العساكِرَ المِصريَّة قادِمةٌ إلى الشام، وفي عشيَّة يوم السبت رحل بولاي وأصحابُه من التتر وانشمروا عن دمشق، وقد أراح الله منهم وساروا من على عقبة دمر، فعاثوا في تلك النواحي فسادًا، ولم يأت سابع الشهر وفي حواشي البلد منهم أحدٌ، وقد أزاح الله عز وجل شَرَّهم عن العباد والبلاد، ونادى قبجق في الناسِ: قد أَمِنَت الطرقاتُ ولم يبقَ بالشَّامِ مِن التتر أحد، وصلى قبجق يومَ الجمعة عاشر رجب بالمقصورة، ومعه جماعةٌ عليهم لَأْمةُ الحرب من السيوفِ والقِسِيِّ والتراكيش فيها النشَّاب، وأَمِنَت البلاد، وخرج الناسُ للفرجة في غيضِ السفرجل على عادتهم، فعاثت عليهم طائفةٌ مِن التتر، فلمَّا رأوهم رجعوا إلى البلدِ هاربين مُسرِعينَ، ونهب بعضُ النَّاسِ بَعضًا، ومنهم من ألقى نفسَه في النَّهرِ، وإنما كانت هذه الطائفة مجتازين ليس لهم قرار، وتقلَّقَ قبجق من البلَدِ ثمَّ إنَّه خرج منها في جماعةٍ مِن رؤسائها وأعيانِها، منهم عز الدين بن القلانسي ليتلَقَّوا الجيش المصري، وذلك أن جيش مصر خرج إلى الشام في تاسع رجب وجاءت البريديَّة بذلك، وبقي البلدُ ليس به أحد، ونادى أرجواش في البلد: احفَظوا الأسوارَ وأخرِجوا ما كان عندكم من الأسلحةِ، ولا تهملوا الأسوارَ والأبواب، ولا يبيتَنَّ أحدٌ إلا على السور، ومن بات في داره شُنِقَ، فاجتمع الناس على الأسوار لحفظ البلاد، وكان الشيخُ تقي الدين ابن تيمية يدورُ كُلَّ ليلة على الأسوارِ يُحَرِّضُ النَّاسَ على الصبر والقتال، ويتلو عليهم آياتِ الجهادِ والرِّباطِ، وفي يوم الجمعة سابع عشر رجب أعيدت الخطبةُ بدمشق لصاحب مِصرَ، ففرح الناسُ بذلك، وكان يُخطَبُ لقازان بدمشق وغيرها من بلاد الشام مائةَ يومٍ سواء، وفي بكرةِ يوم الجمعة المذكور دار الشيخُ تقي الدين ابن تيمية رحمه الله وأصحابُه على الخَمَّارات والحانات، فكَسَّروا آنيةَ الخُمورِ وشَقَّقوا الظروفَ وأراقوا الخمورَ، وعَزَّروا جماعةً مِن أهل الحانات المتَّخَذة لهذه الفواحِشِ، ففرح الناسُ بذلك، ونودي يوم السبتِ ثامِنَ عشر رجب بأن تُزَيَّن البلد لقدوم العساكِرِ المصرية، وفُتِحَ باب الفرج مضافًا إلى باب النصر يوم الأحد تاسع عشر رجب، ففرح النَّاسُ بذلك وانفرجوا."},{"id":2838,"title":"وفاة الإمام المفتي الزاهد جمال الدين الباجربقي  .","date":["العام الهجري :699","الشهر القمري : شوال","العام الميلادي :1300"],"text":"هو الإمامُ المفتي الزاهِدُ جمال الدين أبو محمد عبد الرحيم بن عبد المنعم بن عمر بن عثمان الباجربقي الموصلي الشافعي شيخٌ فقيهٌ محَقِّقٌ نقَّال طويل مهيب ساكِنٌ، كثيرُ الصلاة يلازم الجامِعَ، له حلقة تحت النسر إلى جانب البرادة، منقبض عن الناس، اشتغل بالموصل وأفاد وخطَبَ بجامِعِ دمشق نيابةً، ودرس بالغزالية نيابةً، وولي تدريس الفتحية، وحدَّث بجامع الأصول لابن الأثير عن واحد عن المصنَّف، وله نظم ونثر ووعظٌ، وقد نظم كتابَ التعجيز وعَمِلَه برموز, وقد وَلِيَ قَضاءَ غَزَّة سنة تسع وسبعين. وهو والدُ الزاهد محمد الباجربقي المنحرفِ صاحِبِ الملحمة الباجربقيَّة الذي حكم المالكيُّ بقَتلِه لزندقتِه وضَلالِه، توفي الشيخُ جمال الدين في خامس شوال وصُلِّيَ عليه عقيبَ الجمعة"},{"id":2839,"title":"مسير الجيش الشامي برفقة شيخ الإسلام ابن تيمية إلى جبال الجرد .","date":["العام الهجري :699","الشهر القمري : شوال","العام الميلادي :1300"],"text":"في يومِ الجمعة العشرين من شوَّالٍ ركِبَ نائب السلطنة جمال الدين آقوش الأفرم في جيش دمشقَ إلى جبال الجرد وكسروان (وهي من مناطق الساحل اللبناني كان يسكنُها الدروز والروافض) وخرج الشيخُ تقي الدين ابن تيميَّة ومعه خلقٌ كثير من المتطَوِّعة والحوارنة لقتال أهل تلك الناحية؛ بسبب فساد نيَّتِهم وعقائدِهم وكُفرِهم وضَلالِهم، وما كانوا عامَلوا به العساكِرَ لَمَّا كسرهم التَّتَرُ، وهربوا حين اجتازوا ببلادهم، ووثَبوا عليهم ونهَبوهم وأخذوا أسلحتَهم وخيولهم، وقتلوا كثيرًا منهم، فلما وصلوا إلى بلادِهم جاء رؤساؤُهم إلى الشيخ تقي الدين ابن تيمية فاستتابَهم وبيَّنَ للكثيرِ منهم الصوابَ وحصل بذلك خيرٌ كثيرٌ، وانتصارٌ كبير على أولئك المُفسِدين، والتزموا بردِّ ما كانوا أخَذوه من أموال الجيش، وقَرَّر عليهم أموالًا كثيرة يحملونَها إلى بيت المال، وأُقطِعَت أراضيهم وضياعُهم، ولم يكونوا قبل ذلك يدخُلونَ في طاعة الجُندِ ولا يلتَزِمونَ أحكام المِلَّة، ولا يدينونَ دينَ الحَقِّ، ولا يحَرِّمونَ ما حرم اللهُ ورسوله، وعاد نائبُ السلطنة يوم الأحد ثالث عشر ذي القعدة وتلقاه الناسُ بالشموع إلى طريق بعلبك وسطَ النَّهار."},{"id":2840,"title":"اقتتال العربان فيما بينهم بمصر .","date":["العام الهجري :700","العام الميلادي :1300"],"text":"اختلف عربانُ البحيرة واقتَتَل طائفتا جابر وبرديس حتى فني بينهما بشرٌ كثير، واستظهرت برديس، فخرج الأميرُ بيبرس الدوادار في عشرين أميرًا من الطبلخاناه إلى تروجة، فانهزم العربُ منهم، فتَبِعوهم إلى الليونةِ وأخذوا جمالَهم وأغنامَهم، واستدعوا أكابِرَهم ووفَقَّوا بينهم وعادوا، فخرج الوزيرُ شمس الدين سنقر الأعسر في عدة مائة من المماليك السلطانية إلى الوجهِ القبلي لحَسمِ العربانِ، وقد كان كَثُرَ عَيثُهم وفسادُهم، ومَنَع كثيرٌ منهم الخراج لِما كان من الاشتغالِ بحركات قازان التتري، فأوقع الوزيرُ شمس الدين بكثير من بلاد الصعيد الكَبَساتِ، وقتل جماعاتٍ مِن المفسدين، وأخذ سائِرَ الخيول التي ببلاد الصعيد، فلم يَدَعْ بها فرسًا لفلاحٍ ولا بدويٍّ ولا قاضٍ ولا فقيهٍ ولا كاتب، وتتَّبَع السلاحَ الذي مع الفلاحين والعربان فأخذه عن آخِرِه، وأخذ الجِمالَ، وعاد من قوص إلى القاهرة، ومعه ألف وستون فرسًا، وثمانمائة وسبعون جملًا، وألف وستمائة رمح، وألف ومائتا سيف، وسبعمائة درقة، وستة آلاف رأسٍ من الغنم، فسكن ما كان بالبلادِ مِن الشَّرِّ، وذَلَّ الفلاحون، وأعطوا الخراجَ."},{"id":2841,"title":"تثبيت شيخ الإسلام بن تيمية للأمراء والناس في مواجهة التتار .","date":["العام الهجري :700","الشهر القمري : صفر","العام الميلادي :1300"],"text":"في مستهَلِّ صَفَر وردت أخبارٌ بقَصدِ التتر بلادَ الشام، وأنهم عازمونَ على دخول مصر، فانزعج الناسُ لذلك وازدادوا ضعفًا على ضعفهم، وشرعَ الناسُ في الهرب إلى بلادِ مِصرَ والكرك والشوبك والحصون المنيعة، وجلس الشيخُ تقي الدين ابن تيمية في ثاني صفر بمجلِسِه في الجامع وحَرَّضَ الناسَ على القتال، وساق لهم الآياتِ والأحاديثَ الواردة في ذلك، ونهى عن الإسراعِ في الفرار، ورغَّبَ في إنفاق الأموال في الذَّبِّ عن المسلمين وبلادِهم وأموالِهم، وأنَّ ما يُنفَقُ في أجرةِ الهَرَبِ إذا أُنفِقَ في سبيل الله كان خيرًا، وأوجب جهاد التتر حتمًا في هذه الكَرَّة، وتابع المجالِسَ في ذلك، ونودِيَ في البلادِ لا يسافِرْ أحدٌ إلا بمرسومٍ وورقةٍ، فتوقَّفَ النَّاسُ عن السير وسكَنَ جأشُهم، وتحَدَّث الناس بخروج السلطانِ مِن القاهرة بالعساكرِ، وفي أول ربيع الآخر قَوِيَ الإرجاف بأمر التتر، وجاء الخبَرُ بأنهم قد وصلوا إلى البيرة ونودِيَ في البلد أن تخرج العامَّةُ من العسكر، وجاء مرسومُ النائب من المرج بذلك، فاستعرضوا في أثناء الشَّهرِ فعرض نحو خمسةِ آلاف من العامة بالعُدَّة والأسلحة على قدر طاقتِهم، وأشاع المرجفونَ بأن التتر قد وصلوا إلى حَلَب وأن نائب حلب تقهقَرَ إلى حماة، ونودي في البلد بتطييبِ قُلوبِ الناس وإقبالِهم على معايِشِهم، وأن السلطانَ والعساكر واصلةٌ، وأُبطلَ ديوان المستخرج, وكانوا قد استخرجوا أكثَرَ مِمَّا أمروا به، وبقيت بواقٍ على الناس الذين قد اختَفَوا، فعُفي عما بَقِي، ولم يَرُدَّ ما سَلف، لا جرم أن عواقِبَ هذه الأفعال خَسَرٌ ونُكرٌ، وأن أصحابها لا يُفلِحون، ثم جاءت الأخبار بأن سلطان مصر رجع عائدًا إلى مصر بعد أن خرج منها قاصدًا الشام، فكثر الخوفُ واشتد الحال، وكثرت الأمطار جدًّا، وخرج كثير من الناس خفافًا وثِقالًا يتحمَّلونَ بأهليهم وأولادهم، واستهَلَّ جمادى الأولى والناسُ على خطَّة صعبة من الخوف، وتأخَّرَ السلطان واقترَبَ العدُوُّ، وخرج الشيخ تقي الدين ابن تيمية في مستهَلِّ هذا الشهرِ وكان يوم السبت إلى نائبِ الشامِ في المرج فثَبَّتَهم وقَوَّى جأشَهم وطَيَّبَ قلوبهم ووعَدَهم النصرَ والظَّفَرَ على الأعداء، وتلا قولَه تعالى: {ذَلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِ ثُمَّ بُغِيَ عَلَيْهِ لَيَنْصُرَنَّهُ اللَّهُ إِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ} [الحج: 60] وبات عند العسكَرِ ليلةَ الأحد ثم عاد إلى دمشق وقد سأله النائِبُ والأمراء أن يركَبَ على البريدِ إلى مِصرَ يستَحِثُّ السلطانَ على المجيءَ، فساق وراء السلطانِ، وكان السلطانُ قد وصل إلى الساحِلِ فلم يدرِكْه إلَّا وقد دخل القاهرةَ وتفارط الحال، ولكنَّه استحَثَّهم على تجهيز العساكر إلى الشامِ إن كان لهم به حاجةٌ، وقال لهم فيما قال: إن كنتم أعرضتُم عن الشامِ وحمايتِه أقَمْنا له سلطانًا يحوطُه ويحميه ويستغِلُّه في زَمَنِ الأمن، ولم يَزَلْ بهم حتى جُرِّدَت العساكِرُ إلى الشام، ثم قال لهم: لو قُدِّرَ أنكم لستُم حكامَ الشَّامِ ولا ملوكَه واستنصركم أهلُه، وجب عليكم النصرُ، فكيف وأنتم حكَّامُه وسلاطينُه وهم رعاياكم وأنتم مسؤولونَ عنهم؟! وقَوَّى جأشَهم وضَمِنَ لهم النصر هذه الكَرَّةَ، فخرجوا إلى الشام، فلما تواصَلَت العساكِرُ إلى الشام فرح الناسُ فَرَحًا شديدًا بعد أن كانوا قد يَئِسوا من أنفُسِهم وأهليهم وأموالهم، ثمَّ قَوِيت الأراجيف بوصول التتر، وتحقُّقِ عَودِ السلطان إلى مصر، ونادى ابنُ النحاس متولي البلد في الناسِ: من قَدَرَ على السَّفَرِ فلا يقعُدْ بدمشق، فتصايح النِّساءُ والوِلدان، ورهق الناسَ ذِلَّةٌ عظيمةٌ وخَمدةٌ، وزُلزِلوا زلزالًا شَديدًا، وغُلِّقَت الأسواقُ وتيَقَّنوا أنْ لا ناصِرَ لهم إلا اللهُ عزَّ وجَلَّ، ودخل كثير من الناس إلى البراري والقِفار والمغر بأهاليهم من الكبارِ والصغار، ونودي في الناسِ من كانت نيتُه الجهادَ فليلتَحِقْ بالجيش؛ فقد اقترب وصول التتر، ولم يبق بدمشقَ مِن أكابرها إلا القليل، وجاءت الأخبارُ بوصول التتر إلى سرقين، وخرج الشيخ زين الدين الفارقي والشيخ إبراهيم الرقي وابن قوام وشرف الدين ابن تيمية وابن خبارة إلى نائب السلطنة الأفرم، فقَوَّوا عَزمَه على ملاقاةِ العدو، واجتمعوا بمهنا أمير العرب فحَرَّضوه على قتال العدو، فأجابهم بالسَّمعِ والطاعة، وقَوِيَت نياتهم على ذلك، وخرج طلبُ سلار من دمشق إلى ناحية المرج، واستعدوا للحَربِ والقتال بنيَّات صادقة، ورجع الشيخُ تقي الدين ابن تيمية من الديارِ المِصريَّة في السابع والعشرين من جمادى الأولى على البريد، وأقام بقلعة مصرَ ثمانيةَ أيَّامٍ يَحُثُّهم على الجهاد والخروج إلى العدو، وقد اجتمع بالسلطانِ والوزير وأعيان الدولة فأجابوه إلى الخروجِ، وقد غلت الأسعار بدمشقَ جِدًّا، ثم جاءت الأخبار بأن مَلِكَ التتار قد خاض الفراتَ راجِعًا عامَه ذلك لِضَعفِ جَيشِه وقِلَّةِ عَدَدِهم، فطابت النفوسُ لذلك وسكن النَّاسُ، وعادوا إلى منازِلِهم منشرحين آمنينَ مُستبشرينَ، ولَمَّا جاءت الأخبار بعدم وصول التتار إلى الشامِ في جمادى الآخرة تراجعت أنفُسُ الناس إليهم وعاد نائِبُ السلطنة إلى دمشق، وكان مخيمًا في المرج من مدة أربعة أشهر متتابعة، وهو من أعظَمِ الرباط، وتراجَعَ النَّاسُ إلى أوطانهم."},{"id":2842,"title":"وقعة أهل الذمة بمصر والشام في إلزامهم بالشروط العمرية .","date":["العام الهجري :700","الشهر القمري : رجب","العام الميلادي :1301"],"text":"في هذا الشَّهرِ كانت وقعةُ أهلِ الذِّمَّة، وهي أنهم كانوا قد تزايد تَرَفُهم بالقاهرة ومصر، وتفَنَّنوا في ركوب الخَيلِ المُسَوَّمة والبَغلات الرائعة بالحُليِّ الفاخرة، ولَبِسوا الثيابَ السريَّة، ووُلوا الأعمالَ الجليلة، فاتفق قدومُ وزير ملك المغرب يريدُ الحَجَّ، واجتمع بالسلطانِ والأمراء، وبينما هو تحت القلعة إذا برجلٍ راكب فرسًا وحَولَه عِدَّةٌ من الناس مشاةٌ في ركابِه، يتضَرَّعونَ له ويسألونه ويقَبِّلون رجليه، وهو مُعرِضٌ عنهم لا يعبأُ بهم، بل ينهَرُهم ويصيح في غِلمانِه بطَردِهم، فقيل للمغربي: إنَّ هذا الرَّاكِبَ نصرانيٌّ، فشَقَّ عليه، واجتمع بالأميرين بيبرس وسلار وحدَّثهما بما رآه، وأنكر ذلك وبكى بكاءً كثيرًا، وشَنَّعَ في أمر النصارى وقال: كيف ترجون النَّصرَ والنصارى تركَبُ عندكم الخيول وتلبَسُ العمائِمَ البِيضَ، وتُذِلُّ المسلمين وتُشبِهُهم في خدمتِكم؟! وأطال القولَ في الإنكار وما يلزَمُ وُلاةَ الأمور من إهانةِ أهل الذِّمَّة وتغيير زيِّهم، فأثَّرَ كلامُه في نفوس الأمراء، فرَسَم أن يُعقَدَ مَجلِسٌ بحضور الحُكَّام، واستُدعِيَت القضاة والفُقَهاء، وطُلِبَ بطرك النصارى، وبرز مرسومُ السلطان بحَملِ أهل الذمة على ما يقتضيه الشَّرعُ المحَمَّدي، فاجتمع القضاةُ بالمدرسةِ الصالحية بين القصرين، ونُدِبَ لذلك من بينهم قاضي القضاة شمس الدين أحمد السروجي الحنفي، وطُلِبَ بطرك النصارى، وجماعةٌ من أساقفتهم وأكابر قِسِّيسِيهم وأعيان مِلَّتِهم، وديَّان اليهود وأكابِر مِلَّتِهم، وسُئِلوا عما أقَرُّوا عليه في خلافة أمير المؤمنين عمرَ بنِ الخطاب رضي الله عنه مِن عَقدِ الذِّمَّة، فلم يأتوا عن ذلك بجواب، وطال الكلامُ معهم إلى أن استقَرَّ الحالُ على أنَّ النصارى تتميَّزُ بلباس العمائِمِ الزُّرقِ، واليهودَ بلُبسِ العمائم الصُّفر، ومُنِعوا من ركوبِ الخَيلِ والبِغالِ، ومِن كُلِّ ما منعهم منه الشارِعُ صَلَّى الله عليه وسلم، وأُلزِموا بما شَرَطَه عليهم أميرُ المؤمنين عمر بن الخطاب رضي الله عنه، فالتزموا ذلك وأُشهِدَ عليه البطرك أنَّه حَرَّم على جميع النصرانية مخالفةَ ذلك والعُدول عنه، وقال رئيس اليهود ودانهم: أوقعت الكَلِمةَ على سائِرِ اليهود في مخالفةِ ذلك والخروج عنه وانفَضَّ المجلس، وطُولِعَ السلطان والأمراء مما وقع، فكتب إلى أعمالِ مِصرَ والشام به، ولَمَّا كان يوم خميس العهدِ وهو العشرون من شهر رجب جُمِعَ النصارى واليهود بالقاهرة ومصر وظواهِرِها، ورُسِمَ ألَّا يُستخدَمَ أحَدٌ منهم بديوانِ السُّلطانِ ولا بدواوينِ الأمراءِ، وألَّا يَركَبوا خيلًا وبغالًا، وأن يلتَزِموا سائِرَ ما شُرِطَ عليهم، ونودِيَ بذلك في القاهرةِ ومصر، وهدد من خالفه بسفك دمه، فانحصر النصارى من ذلك، وسَعَوا بالأموال في إبطالِ ما تقَرَّر، فقام الأمير بيبرس الجاشنكير في إمضاءِ ما ذُكِرَ قيامًا محمودًا، وصَمَّم تصميمًا زائدًا، فاضطر الحالُ بالنصارى إلى الإذعان، وأسلَمَ أمين الملك عبد الله بن العنام مستوفي الصحبةِ وخَلقٌ كثيرٌ، حرصًا منهم على بقاءِ رياستِهم، وأنفةً مِن لُبسِ العمائِمِ الزُّرقِ وركوب الحَميرِ، وخرج البريدُ بحَملِ النصارى واليهود فيما بين دنقلة من النوبة والفرات على ما تقَدَّمَ ذِكرُه، وامتَدَّت أيدي العامَّة إلى كنائس اليهود والنصارى، فهَدَموها بفتوى الشَّيخِ الفَقيهِ نجم الدين أحمد بن محمد بن الرفعة، فطَلَب الأمراءُ القُضاةَ والفقهاءَ للنَّظَرِ في أمر الكنائس، فصَرَّحَ ابن الرفعة بوجوب هَدمِها، وامتنع من ذلك قاضي القضاةِ تقي الدين محمد بن دقيق العيد، واحتَجَّ بأنَّه إذا قامت البيِّنةُ بأنها أُحدِثَت في الإسلامِ تُهدَمُ، وإلَّا فلا يُتعَرَّض لها، ووافَقَه البقيَّةُ على هذا وانفَضُّوا، وكان أهلُ الإسكندريةِ لما ورد عليهم مرسومُ السلطان في أمر الذمَّة ثاروا بالنَّصارى وهَدَّموا لهم كنيستين، وهَدَّموا دُورَ اليهود والنصارى التي تعلو على دُورِ جيرانِهم المُسلِمينَ، وحَطُّوا مساطِبَ حوانيتِهم حتى صارت أسفَلَ مِن حوانيت المسلمين، وهُدِمَ بالفيومِ أيضًا كَنيستانِ، وقَدِمَ البريد في أمر الذمَّة إلى دمشق يوم الاثنين سابع شعبان، فاجتمع القضاةُ والأعيان عند الأمير أقش الأفرم، وقرئ عليهم مرسومُ السلطان بذلك، فنودي في الخامس عشر أن يَلبَسَ النصارى العمائِمَ الزُّرقَ، واليهودُ العمائمَ الصُّفرَ، والسَّامرةُ العمائِمَ الحُمر، وهُدِّدوا على المخالفة، فالتزم النصارى واليهود بسائِرِ مملكة مصر والشام ما أُمِروا به، وصَبَغوا عمائِمَهم إلَّا أهل الكركِ؛ فإن الأمير جمال الدين أقش الأفرم الأشرفي النائبُ بها رأى إبقاءَهم على حالتِهم، واعتذَرَ بأنَّ أكثَرَ أهل الكرك نصارى، فلم يغَيِّرْ أهلُ الكرك والشوبك من النصارى العمائِمَ البيض، وبَقِيَت الكنائسُ بأرض مصر مدة سنةٍ مُغَلَّقة حتى قَدِمَت رسل الأشكري ملك الفرنج تشفَعُ في فتحِها، ففُتِحَت كنيسةُ المُعَلَّقة بمدينة مصر، وكنيسة ميكائيل الملكيَّة، ثم قدمت رسل ملوك أخر، ففُتِحَت كنيسةُ حارة وزويلة، وكنيسة نقولا."}]
